(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("demosthenes-orations-2-e", [{"sp": "HDR", "t": "Κατὰ Μειδίου, Ἀνδροτίωνος, Ἀριστοκράτους, Τιμοκράτους, Ἀριστογείτονος"}, {"sp": "HDR", "t": "Κατὰ Μειδίου περὶ τοῦ Κονδύλου", "st": "21"}, {"sp": "N", "t": "τὴν μὲν ἀσέλγειαν, ὦ ἄνδρες δικασταί, καὶ τὴν ὕβριν, ᾗ πρὸς ἅπαντας ἀεὶ χρῆται Μειδίας, οὐδέν’ οὔθ’ ὑμῶν οὔτε τῶν ἄλλων πολιτῶν ἀγνοεῖν οἴομαι. ἐγὼ δ’, ὅπερ ἂν καὶ ὑμῶν ἕκαστος ὑβρισθεὶς προείλετο πρᾶξαι, τοῦτο καὶ αὐτὸς ἐποίησα, καὶ προὐβαλόμην ἀδικεῖν τοῦτον περὶ τὴν ἑορτήν, οὐ μόνον πληγὰς ὑπ’ αὐτοῦ λαβὼν τοῖς Διονυσίοις, ἀλλὰ καὶ ἄλλα πολλὰ καὶ βίαια παθὼν παρὰ πᾶσαν τὴν χορηγίαν.", "st": "21.1"}, {"sp": "N", "t": "ἐπειδὴ δὲ καλῶς καὶ τὰ δίκαια ποιῶν ὁ δῆμος ἅπας οὕτως ὠργίσθη καὶ παρωξύνθη καὶ σφόδρ’ ἐσπούδασεν ἐφ’ οἷς ἠδικημένῳ μοι συνῄδει, ὥστε πάντα ποιοῦντος τούτου καί τινων ἄλλων ὑπὲρ αὐτοῦ, οὐκ ἐπείσθη οὐδ’ ἀπέβλεψεν εἰς τὰς οὐσίας τὰς τούτων οὐδὲ τὰς ὑποσχέσεις, ἀλλὰ μιᾷ γνώμῃ κατεχειροτόνησεν αὐτοῦ, πολλοί μοι προσιόντες, ὦ ἄνδρες δικασταί, καὶ τῶν ἐν τῷ δικαστηρίῳ νῦν ὄντων ὑμῶν καὶ τῶν ἄλλων πολιτῶν ἠξίουν καὶ παρεκελεύοντ’ ἐπεξελθεῖν καὶ παραδοῦναι τοῦτον εἰς ὑμᾶς, ὡς μὲν ἐμοὶ δοκεῖ, δι’ ἀμφότερ’, ὦ ἄνδρες Ἀθηναῖοι, νὴ τοὺς θεούς, καὶ δεινὰ πεπονθέναι νομίζοντες ἐμὲ καὶ δίκην ἅμα βουλόμενοι λαβεῖν ὧν ἐπὶ τῶν ἄλλων ἐτεθέαντο θρασὺν ὄντα καὶ βδελυρὸν καὶ οὐδὲ καθεκτὸν ἔτι.", "st": "21.2"}, {"sp": "N", "t": "οὕτω δὲ τούτων ἐχόντων, ὅσα μὲν παρ’ ἐμοῦ προσῆκε φυλαχθῆναι, πάντα δικαίως ὑμῖν τετήρηται, καὶ κατηγορήσων, ἐπειδή τις εἰσάγει, πάρειμι, ὡς ὁρᾶτε, πολλὰ μέν, ὦ ἄνδρες Ἀθηναῖοι, χρήματα, ἐξόν μοι λαβεῖν ὥστε μὴ κατηγορεῖν, οὐ λαβών, πολλὰς δὲ δεήσεις καὶ χάριτας καὶ νὴ Δί’ ἀπειλὰς ὑπομείνας.", "st": "21.3"}, {"sp": "N", "t": "ἃ δ’ ἐν ὑμῖν μετὰ ταῦτ’ ἔσθ’ ὑπόλοιπα, ὅσῳ πλείοσιν οὗτος ἠνώχληκε καὶ παρήγγελκεν (ἑώρων γὰρ αὐτὸν ἄρτι πρὸ τῶν δικαστηρίων οἷ’ ἐποίει), τοσούτῳ μᾶλλον ἐλπίζω τὸ δίκαιον ἕξειν. οὐ γὰρ ἂν καταγνοίην ὑμῶν οὐδενὸς οὔθ’ ὡς περὶ ὧν πρὸς ἔμ’ ἐσπουδάσατ’ αὐτοί, τούτων ἀμελήσετε, οὔθ’ ὡς, ἵνα Μειδίας ἀδεῶς τὸ λοιπὸν ὑβρίζῃ, ψηφιεῖταί τις ὑμῶν ὀμωμοκὼς ἄλλο τι πλὴν ὅ τι ἂν δίκαιον ἡγῆται.", "st": "21.4"}, {"sp": "N", "t": "εἰ μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, παρανόμων ἢ παραπρεσβείας ἤ τινος ἄλλης αἰτίας ἔμελλον αὐτοῦ κατηγορεῖν τοιαύτης, οὐδὲν ἂν ὑμῶν ἠξίουν δεῖσθαι, νομίζων τῷ μὲν κατηγόρῳ περὶ τῶν τοιούτων προσήκειν ἐλέγχειν μόνον, τῷ δὲ φεύγοντι καὶ παραιτεῖσθαι. ἐπειδὴ δὲ τούς τε κριτὰς διαφθείραντος τούτου καὶ διὰ τοῦτο τῆς φυλῆς ἀδίκως ἀφαιρεθείσης τὸν τρίποδα,", "st": "21.5"}, {"sp": "N", "t": "καὶ αὐτὸς πληγὰς εἰληφὼς καὶ ὑβρισμένος οἷ’ οὐκ οἶδ’ εἴ τις ἄλλος πώποτε χορηγὸς ὑβρίσθη, ἣν ὑπὲρ τούτων ἀγανακτήσας καὶ συνοργισθεὶς καταχειροτονίαν ὁ δῆμος ἐποιήσατο, ταύτην εἰσέρχομαι, οὐκ ὀκνήσω καὶ δεῖσθαι. εἰ γὰρ οἷόν τε τοῦτ’ εἰπεῖν, ἐγὼ νῦν φεύγω, εἴπερ ὑβρισθέντα μηδεμιᾶς δίκης τυχεῖν ἐστί τις συμφορά.", "st": "21.6"}, {"sp": "N", "t": "δέομαι οὖν ὑμῶν ἁπάντων, ὦ ἄνδρες δικασταί, καὶ ἱκετεύω, πρῶτον μὲν εὐνοϊκῶς ἀκοῦσαί μου λέγοντος, ἔπειτ’, ἐὰν ἐπιδείξω Μειδίαν τουτονὶ μὴ μόνον εἰς ἐμὲ ἀλλὰ καὶ εἰς ὑμᾶς καὶ εἰς τοὺς νόμους καὶ εἰς τοὺς ἄλλους ἅπαντας ὑβρικότα, βοηθῆσαι καὶ ἐμοὶ καὶ ὑμῖν αὐτοῖς. καὶ γὰρ οὕτω πως ἔχει, ὦ ἄνδρες Ἀθηναῖοι· ὕβρισμαι μὲν ἐγὼ καὶ προπεπηλάκισται τὸ σῶμα τοὐμὸν τότε, ἀγωνιεῖται δὲ καὶ κριθήσεται τὸ πρᾶγμα νυνί, πότερον ἐξεῖναι δεῖ τὰ τοιαῦτα ποιεῖν καὶ εἰς τὸν τυχόνθ’ ὑμῶν ἀδεῶς ὑβρίζειν ἢ μή.", "st": "21.7"}, {"sp": "N", "t": "εἴ τις οὖν ὑμῶν ἄρα καὶ τὸν ἔμπροσθεν χρόνον τῶν ἰδίων τινὸς εἵνεκα γίγνεσθαι τὸν ἀγῶνα τόνδ’ ὑπελάμβανεν, ἐνθυμηθεὶς νῦν ὅτι δημοσίᾳ συμφέρει μηδενὶ μηδὲν ἐξεῖναι τοιοῦτο ποιεῖν, ὡς ὑπὲρ κοινοῦ τοῦ πράγματος ὄντος καὶ προσέχων ἀκουσάτω, καὶ τὰ φαινόμεν’ αὑτῷ δικαιότερ’ εἶναι, ταῦτα ψηφισάσθω. ἀναγνώσεται δὲ πρῶτον μὲν ὑμῖν τὸν νόμον καθ’ ὃν εἰσὶν αἱ προβολαί· μετὰ δὲ ταῦτα καὶ περὶ τῶν ἄλλων πειράσομαι διδάσκειν. λέγε τὸν νόμον.", "st": "21.8"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "21.8"}, {"sp": "N", "t": "[Τοὺς πρυτάνεις ποιεῖν ἐκκλησίαν ἐν Διονύσου τῇ ὑστεραίᾳ τῶν Πανδίων. ἐν δὲ ταύτῃ χρηματίζειν πρῶτον μὲν περὶ ἱερῶν, ἔπειτα τὰς προβολὰς παραδιδότωσαν τὰς γεγενημένας ἕνεκα τῆς πομπῆς ἢ τῶν ἀγώνων τῶν ἐν τοῖς Διονυσίοις, ὅσαι ἂν μὴ ἐκτετισμέναι ὦσιν.]", "st": "21.8"}, {"sp": "N", "t": "ὁ μὲν νόμος οὗτός ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, καθ’ ὃν αἱ προβολαὶ γίγνονται, λέγων, ὥσπερ ἠκούσατε, ποιεῖν τὴν ἐκκλησίαν ἐν Διονύσου μετὰ τὰ Πάνδια, ἐν δὲ ταύτῃ ἐπειδὰν χρηματίσωσιν οἱ πρόεδροι περὶ ὧν διῴκηκεν ὁ ἄρχων, χρηματίζειν καὶ περὶ ὧν ἄν τις ἠδικηκὼς ᾖ περὶ τὴν ἑορτὴν ἢ παρανενομηκώς, καλῶς, ὦ ἄνδρες Ἀθηναῖοι, καὶ συμφερόντως ἔχων ὁ νόμος, ὡς τὸ πρᾶγμ’ αὐτὸ μαρτυρεῖ. ὅπου γὰρ ἐπόντος τοῦ φόβου τούτου φαίνονταί τινες οὐδὲν ἧττον ὑβρισταί, τί χρὴ τοὺς τοιούτους προσδοκᾶν ἂν ποιεῖν, εἰ μηδεὶς ἐπῆν ἀγὼν μηδὲ κίνδυνος;", "st": "21.9"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν καὶ τὸν ἑξῆς ἀναγνῶναι νόμον τούτῳ· καὶ γὰρ ἐκ τούτου φανερὰ πᾶσιν ὑμῖν ἥ τε τῶν ἄλλων ὑμῶν εὐλάβεια γενήσεται καὶ τὸ τούτου θράσος. λέγε τὸν νόμον.", "st": "21.10"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "21.10"}, {"sp": "N", "t": "[Εὐήγορος εἶπεν· ὅταν ἡ πομπὴ ᾖ τῷ Διονύσῳ ἐν Πειραιεῖ καὶ οἱ κωμῳδοὶ καὶ οἱ τραγῳδοί, καὶ ⟨ἡ⟩ ἐπὶ Ληναίῳ πομπὴ καὶ οἱ τραγῳδοὶ καὶ οἱ κωμῳδοί, καὶ τοῖς ἐν ἄστει Διονυσίοις ἡ πομπὴ καὶ οἱ παῖδες καὶ ὁ κῶμος καὶ οἱ κωμῳδοὶ καὶ οἱ τραγῳδοί, καὶ Θαργηλίων τῇ πομπῇ καὶ τῷ ἀγῶνι, μὴ ἐξεῖναι μήτε ἐνεχυράσαι μήτε λαμβάνειν ἕτερον ἑτέρου, μηδὲ τῶν ὑπερημέρων, ἐν ταύταις ταῖς ἡμέραις. ἐὰν δέ τις τούτων τι παραβαίνῃ, ὑπόδικος ἔστω τῷ παθόντι, καὶ προβολαὶ αὐτοῦ ἔστωσαν ἐν τῇ ἐκκλησίᾳ τῇ ἐν Διονύσου ὡς ἀδικοῦντος, καθὰ περὶ τῶν ἄλλων τῶν ἀδικούντων γέγραπται.]", "st": "21.10"}, {"sp": "N", "t": "ἐνθυμεῖσθ’, ὦ ἄνδρες δικασταί, ὅτι ἐν τῷ προτέρῳ νόμῳ κατὰ τῶν περὶ τὴν ἑορτὴν ἀδικούντων οὔσης τῆς προβολῆς, ἐν τούτῳ καὶ κατὰ τῶν τοὺς ὑπερημέρους εἰσπραττόντων ἢ καὶ ἄλλ’ ὁτιοῦν τινὸς λαμβανόντων ἢ βιαζομένων ἐποιήσατε τὰς προβολάς. οὐ γὰρ ὅπως τὸ σῶμ’ ὑβρίζεσθαί τινος ἐν ταύταις ταῖς ἡμέραις, ἢ τὴν παρασκευὴν ἣν ἂν ἐκ τῶν ἰδίων πορίσαιτό τις εἰς λῃτουργίαν, ᾤεσθε χρῆναι, ἀλλὰ καὶ τὰ δίκῃ καὶ ψήφῳ τῶν ἑλόντων γιγνόμενα τῶν ἑαλωκότων καὶ κεκτημένων ἐξ ἀρχῆς τὴν γοῦν ἑορτὴν ἀπεδώκατ’ εἶναι.", "st": "21.11"}, {"sp": "N", "t": "ὑμεῖς μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, πάντες εἰς τοσοῦτον ἀφῖχθε φιλανθρωπίας καὶ εὐσεβείας ὥστε καὶ τῶν πρότερον γεγενημένων ἀδικημάτων τὸ λαμβάνειν δίκην ἐπέσχετε ταύτας τὰς ἡμέρας· Μειδίας δ’ ἐν αὐταῖς ταύταις ταῖς ἡμέραις ἄξια τοῦ δοῦναι τὴν ἐσχάτην δίκην ποιῶν δειχθήσεται. βούλομαι δ’ ἕκαστον ἀπ’ ἀρχῆς ὧν πέπονθ’ ἐπιδείξας καὶ περὶ τῶν πληγῶν εἰπεῖν ἃς τὸ τελευταῖον προσενέτεινέ μοι· ἓν γὰρ οὐδέν ἐστιν ἐφ’ ᾧ τῶν πεπραγμένων οὐ δίκαιος ὢν ἀπολωλέναι φανήσεται.", "st": "21.12"}, {"sp": "N", "t": "ἐπειδὴ γὰρ οὐ καθεστηκότος χορηγοῦ τῇ Πανδιονίδι φυλῇ, τρίτον ἔτος τουτί, παρούσης δὲ τῆς ἐκκλησίας ἐν ᾗ τὸν ἄρχοντ’ ἐπικληροῦν ὁ νόμος τοῖς χοροῖς τοὺς αὐλητὰς κελεύει, λόγων καὶ λοιδορίας γιγνομένης, καὶ κατηγοροῦντος τοῦ μὲν ἄρχοντος τῶν ἐπιμελητῶν τῆς φυλῆς, τῶν δ’ ἐπιμελητῶν τοῦ ἄρχοντος, παρελθὼν ὑπεσχόμην ἐγὼ χορηγήσειν ἐθελοντής, καὶ κληρουμένων πρῶτος αἱρεῖσθαι τὸν αὐλητὴν ἔλαχον,", "st": "21.13"}, {"sp": "N", "t": "ὑμεῖς μέν, ὦ ἄνδρες Ἀθηναῖοι, πάντες ἀμφότερ’ ὡς οἷόν τε μάλιστ’ ἀπεδέξασθε, τήν τ’ ἐπαγγελίαν τὴν ἐμὴν καὶ τὸ συμβὰν ἀπὸ τῆς τύχης, καὶ θόρυβον καὶ κρότον τοιοῦτον ὡς ἂν ἐπαινοῦντές τε καὶ συνησθέντες ἐποιήσατε, Μειδίας δ’ οὑτοσὶ μόνος τῶν πάντων, ὡς ἔοικεν, ἠχθέσθη, καὶ παρηκολούθησε παρ’ ὅλην τὴν λῃτουργίαν ἐπηρεάζων μοι συνεχῶς καὶ μικρὰ καὶ μείζω.", "st": "21.14"}, {"sp": "N", "t": "ὅσα μὲν οὖν τοὺς χορευτὰς ἐναντιούμενος ἡμῖν ἀφεθῆναι τῆς στρατείας ἠνώχλησεν, ἢ προβαλλόμενος καὶ κελεύων ἑαυτὸν εἰς Διονύσια χειροτονεῖν ἐπιμελητήν, ἢ τἄλλα πάνθ’ ὅσα τοιαῦτα, ἐάσω· οὐ γὰρ ἀγνοῶ τοῦθ’ ὅτι τῷ μὲν ἐπηρεαζομένῳ τότ’ ἐμοὶ καὶ ὑβριζομένῳ τὴν αὐτὴν ὀργὴν ἕκαστον τούτων ἥνπερ ἄλλ’ ὁτιοῦν τῶν δεινοτάτων παρίστη, ὑμῖν δὲ τοῖς ἄλλοις, ἔξω τοῦ πράγματος οὖσιν, οὐκ ἂν ἴσως ἄξια ταῦτα καθ’ αὕτ’ ἀγῶνος φανείη· ἀλλ’ ἃ πάντες ὁμοίως ἀγανακτήσετε, ταῦτ’ ἐρῶ.", "st": "21.15"}, {"sp": "N", "t": "ἔστι δ’ ὑπερβολὴ τῶν μετὰ ταῦτα, ἃ μέλλω λέγειν, καὶ οὐδ’ ἂν ἐπεχείρησ’ ἔγωγε κατηγορεῖν αὐτοῦ νῦν, εἰ μὴ καὶ τότ’ ἐν τῷ δήμῳ παραχρῆμ’ ἐξήλεγξα. τὴν γὰρ ἐσθῆτα τὴν ἱεράν (ἱερὰν γὰρ ἔγωγε νομίζω πᾶσαν ὅσην ἄν τις εἵνεκα τῆς ἑορτῆς παρασκευάσηται, τέως ἂν χρησθῇ) καὶ τοὺς στεφάνους τοὺς χρυσοῦς, οὓς ἐποιησάμην ἐγὼ κόσμον τῷ χορῷ, ἐπεβούλευσεν, ὦ ἄνδρες Ἀθηναῖοι, διαφθεῖραί μοι νύκτωρ ἐλθὼν ἐπὶ τὴν οἰκίαν τὴν τοῦ χρυσοχόου. καὶ διέφθειρεν, οὐ μέντοι πᾶσάν γε· οὐ γὰρ ἐδυνήθη. καίτοι τοῦτό γ’ οὐδεὶς πώποτ’ οὐδένα φησὶν ἀκηκοέναι τολμήσαντ’ οὐδὲ ποιήσαντ’ ἐν τῇ πόλει.", "st": "21.16"}, {"sp": "N", "t": "οὐκ ἀπέχρησε δ’ αὐτῷ τοῦτο, ἀλλὰ καὶ τὸν διδάσκαλον, ὦ ἄνδρες Ἀθηναῖοι, διέφθειρέ μου τοῦ χοροῦ· καὶ εἰ μὴ Τηλεφάνης ὁ αὐλητὴς ἀνδρῶν βέλτιστος περὶ ἐμὲ τότ’ ἐγένετο, καὶ τὸ πρᾶγμ’ αἰσθόμενος τὸν ἄνθρωπον ἀπελάσας αὐτὸς συγκροτεῖν καὶ διδάσκειν ᾤετο δεῖν τὸν χορόν, οὐδ’ ἂν ἠγωνισάμεθ’, ὦ ἄνδρες Ἀθηναῖοι, ἀλλ’ ἀδίδακτος ἂν εἰσῆλθεν ὁ χορὸς καὶ πράγματ’ αἴσχιστ’ ἂν ἐπάθομεν. καὶ οὐδ’ ἐνταῦθ’ ἔστη τῆς ὕβρεως, ἀλλὰ τοσοῦτον αὐτῷ περιῆν ὥστε τὸν ἐστεφανωμένον ἄρχοντα διέφθειρεν, τοὺς χορηγοὺς συνῆγεν ἐπ’ ἐμέ, βοῶν, ἀπειλῶν, ὀμνύουσι παρεστηκὼς τοῖς κριταῖς, τὰ παρασκήνια φράττων, προσηλῶν, ἰδιώτης ὢν τὰ δημόσια, κακὰ καὶ πράγματ’ ἀμύθητά μοι παρέχων διετέλεσεν.", "st": "21.17"}, {"sp": "N", "t": "καὶ τούτων, ὅσα γ’ ἐν τῷ δήμῳ γέγον’ ἢ πρὸς τοῖς κριταῖς ἐν τῷ θεάτρῳ, ὑμεῖς ἐστέ μοι μάρτυρες πάντες, ἄνδρες δικασταί. καίτοι τῶν λόγων τούτους χρὴ δικαιοτάτους ἡγεῖσθαι, οὓς ἂν οἱ καθήμενοι τῷ λέγοντι μαρτυρῶσιν ἀληθεῖς εἶναι. προδιαφθείρας τοίνυν τοὺς κριτὰς τῷ ἀγῶνι τῶν ἀνδρῶν, δύο ταῦθ’ ὡσπερεὶ κεφάλαι’ ἐφ’ ἅπασι τοῖς ἑαυτῷ νενεανιευμένοις ἐπέθηκεν, ἐμοῦ μὲν ὕβρισεν τὸ σῶμα, τῇ φυλῇ δὲ κρατούσῃ τὸν ἀγῶν’ αἰτιώτατος τοῦ μὴ νικῆσαι κατέστη.", "st": "21.18"}, {"sp": "N", "t": "τὰ μὲν οὖν εἰς ἐμὲ καὶ τοὺς φυλέτας ἠσελγημένα καὶ περὶ τὴν ἑορτὴν ἀδικήματα τούτῳ πεπραγμένα, ἐφ’ οἷς αὐτὸν προὐβαλόμην, ταῦτ’ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, καὶ πόλλ’ ἕτερα, ὧν ὅσ’ ἂν οἷός τ’ ὦ διέξειμι πρὸς ὑμᾶς αὐτίκα δὴ μάλα. ἔχω δὲ λέγειν καὶ πονηρίας ἑτέρας παμπληθεῖς αὐτοῦ καὶ ὕβρεις εἰς πολλοὺς ὑμῶν καὶ τολμήματα τοῦ μιαροῦ τούτου πολλὰ καὶ δεινά,", "st": "21.19"}, {"sp": "N", "t": "ἐφ’ οἷς τῶν πεπονθότων οἱ μέν, ὦ ἄνδρες δικασταί, καταδείσαντες τοῦτον καὶ τὸ τούτου θράσος καὶ τοὺς περὶ αὐτὸν ἑταίρους καὶ πλοῦτον καὶ τἄλλ’ ὅσα δὴ πρόσεστι τούτῳ, ἡσυχίαν ἔσχον, οἱ δ’ ἐπιχειρήσαντες δίκην λαμβάνειν οὐκ ἐδυνήθησαν, εἰσὶ δ’ οἳ διελύσαντο, ἴσως λυσιτελεῖν ἡγούμενοι. τὴν μὲν οὖν ὑπὲρ αὑτῶν δίκην ἔχουσιν οἵ γε πεισθέντες· τῆς δ’ ὑπὲρ τῶν νόμων, οὓς παραβὰς οὗτος κἀκείνους ἠδίκει καὶ νῦν ἐμὲ καὶ πάντας τοὺς ἄλλους, ὑμεῖς ἐστὲ κληρονόμοι.", "st": "21.20"}, {"sp": "N", "t": "πάντων οὖν ἁθρόων ἓν τίμημα ποιήσασθε, ὅ τι ἂν δίκαιον ἡγῆσθε. ἐξελέγξω δὲ πρῶτον μὲν ὅσ’ αὐτὸς ὑβρίσθην, ἔπειθ’ ὅσ’ ὑμεῖς· μετὰ ταῦτα δὲ καὶ τὸν ἄλλον, ὦ ἄνδρες Ἀθηναῖοι, βίον αὐτοῦ πάντ’ ἐξετάσω, καὶ δείξω πολλῶν θανάτων, οὐχ ἑνὸς ὄντ’ ἄξιον. λέγε μοι τὴν τοῦ χρυσοχόου πρώτην λαβὼν μαρτυρίαν.", "st": "21.21"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ", "st": "21.21"}, {"sp": "N", "t": "[Παμμένης Παμμένους Ἑρχιεὺς ἔχω χρυσοχοεῖον ἐν τῇ ἀγορᾷ, ἐν ᾧ καταγίγνομαι καὶ ἐργάζομαι τὴν χρυσοχοϊκὴν τέχνην. ἐκδόντος δέ μοι Δημοσθένους, ᾧ μαρτυρῶ, στέφανον χρυσοῦν ὥστε κατασκευάσαι καὶ ἱμάτιον διάχρυσον ποιῆσαι, ὅπως πομπεύσαι ἐν αὐτοῖς τὴν τοῦ Διονύσου πομπήν, καὶ ἐμοῦ συντελέσαντος αὐτὰ καὶ ἔχοντος παρ’ ἐμαυτῷ ἕτοιμα, εἰσπηδήσας πρός με νύκτωρ Μειδίας ὁ κρινόμενος ὑπὸ Δημοσθένους, ἔχων μεθ’ ἑαυτοῦ καὶ ἄλλους, ἐπεχείρησε διαφθείρειν τὸν στέφανον καὶ τὸ ἱμάτιον, καὶ τινὰ μὲν αὐτῶν ἐλυμήνατο, οὐ μέντοι πάντα γε ἠδυνήθη διὰ τὸ ἐπιφανέντα με κωλῦσαι.]", "st": "21.22"}, {"sp": "N", "t": "πολλὰ μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ περὶ ὧν τοὺς ἄλλους ἠδίκηκεν ἔχω λέγειν, ὥσπερ εἶπον ἐν ἀρχῇ τοῦ λόγου, καὶ συνείλοχ’ ὕβρεις αὐτοῦ καὶ ἀτιμίας τοσαύτας ὅσας ἀκούσεσθ’ αὐτίκα δὴ μάλα. ἦν δ’ ἡ συλλογὴ ῥᾳδία· αὐτοὶ γὰρ οἱ πεπονθότες προσῇσάν μοι.", "st": "21.23"}, {"sp": "N", "t": "βούλομαι δὲ πρὸ τούτων εἰπεῖν οἷς ἐπιχειρήσειν αὐτὸν ἀκήκο’ ἐξαπατᾶν ὑμᾶς· τοὺς γὰρ ὑπὲρ τούτων λόγους ἐμοὶ μὲν ἀναγκαιοτάτους προειπεῖν ἡγοῦμαι, ὑμῖν δὲ χρησιμωτάτους ἀκοῦσαι. διὰ τί; ὅτι τοῦ δικαίαν καὶ εὔορκον θέσθαι τὴν ψῆφον ὁ κωλύσας ἐξαπατηθῆναι λόγος ὑμᾶς οὗτος αἴτιος ἔσται. πολὺ δὴ μάλιστα πάντων τούτῳ τῷ λόγῳ προσέχειν ὑμᾶς δεῖ, καὶ μνημονεῦσαι τοῦτον, καὶ πρὸς ἕκαστον ἀπαντᾶν, ὅταν οὗτος λέγῃ.", "st": "21.24"}, {"sp": "N", "t": "ἔστι δὲ πρῶτον μὲν ἐκεῖν’ οὐκ ἄδηλος ἐρῶν, ἐξ ὧν ἰδίᾳ πρός τινας αὐτὸς διεξιὼν ἀπηγγέλλετό μοι, ὡς εἴπερ ἀληθῶς ἐπεπόνθειν ταῦθ’ ἃ λέγω, δίκας ἰδίας μοι προσῆκεν αὐτῷ λαχεῖν, τῶν μὲν ἱματίων καὶ τῶν χρυσῶν στεφάνων τῆς διαφθορᾶς καὶ τῆς περὶ τὸν χορὸν πάσης ἐπηρείας, βλάβης, ὧς δ’ εἰς τὸ σῶμ’ ὑβρίσθαι φημί, ὕβρεως, οὐ μὰ Δί’ οὐχὶ δημοσίᾳ κρίνειν αὐτὸν καὶ τίμημ’ ἐπάγειν ὅ τι χρὴ παθεῖν ἢ ἀποτεῖσαι.", "st": "21.25"}, {"sp": "N", "t": "ἐγὼ δ’ ἓν μὲν ἐκεῖν’ εὖ οἶδα, καὶ ὑμᾶς δ’ εἰδέναι χρή, ὅτι εἰ μὴ προὐβαλόμην αὐτόν, ἀλλ’ ἐδικαζόμην, οὑναντίος ἧκεν ἂν εὐθύς μοι λόγος, ὡς εἴπερ ἦν τι τούτων ἀληθές, προβάλλεσθαί μ’ ἔδει καὶ παρ’ αὐτὰ τἀδικήματα τὴν τιμωρίαν ποιεῖσθαι· ὅ τε γὰρ χορὸς ἦν τῆς πόλεως, ἥ τ’ ἐσθὴς τῆς ἑορτῆς εἵνεκα πᾶσα παρεσκευάζετο, ἐγώ θ’ ὁ πεπονθὼς ταῦτα χορηγὸς ἦν· τίς ἂν οὖν ἑτέραν εἵλετο τιμωρίαν ἢ τὴν ἐκ τοῦ νόμου κατὰ τῶν περὶ τὴν ἑορτὴν ἀδικούντων οὖσαν;", "st": "21.26"}, {"sp": "N", "t": "ταῦτ’ εὖ οἶδ’ ὅτι πάντ’ ἂν ἔλεγεν οὗτος τότε. φεύγοντος μὲν γάρ, οἶμαι, καὶ ἠδικηκότος ἐστὶ τὸ τὸν παρόντα τρόπον τοῦ δοῦναι δίκην διακρουόμενον τὸν οὐκ ὄνθ’ ὡς ἔδει γενέσθαι λέγειν, δικαστῶν δέ γε σωφρόνων τούτοις τε μὴ προσέχειν καὶ ὃν ἂν λάβωσιν ἀσελγαίνοντα κολάζειν.", "st": "21.27"}, {"sp": "N", "t": "μὴ δὴ τοῦτο λέγειν αὐτὸν ἐᾶτε, ὅτι καὶ δίκας ἰδίας δίδωσ’ ὁ νόμος μοι καὶ γραφὴν ὕβρεως· δίδωσι γάρ· ἀλλ’ ὡς οὐ πεποίηκεν ἃ κατηγόρηκα, ἢ πεποιηκὼς οὐ περὶ τὴν ἑορτὴν ἀδικεῖ, τοῦτο δεικνύτω· τοῦτο γὰρ αὐτὸν ἐγὼ προὐβαλόμην, καὶ περὶ τούτου τὴν ψῆφον οἴσετε νῦν ὑμεῖς. εἰ δ’ ἐγὼ τὴν ἐπὶ τῶν ἰδίων δικῶν πλεονεξίαν ἀφεὶς τῇ πόλει παραχωρῶ τῆς τιμωρίας, καὶ τοῦτον εἱλόμην τὸν ἀγῶν’ ἀφ’ οὗ μηδὲν ἔστι λῆμμα λαβεῖν ἐμοί, χάριν, οὐ βλάβην δήπου τοῦτ’ ἂν εἰκότως ἐνέγκοι μοι παρ’ ὑμῶν.", "st": "21.28"}, {"sp": "N", "t": "οἶδα τοίνυν ὅτι καὶ τούτῳ πολλῷ χρήσεται τῷ λόγῳ “μή με Δημοσθένει παραδῶτε, μηδὲ διὰ Δημοσθένην μ’ ἀνέλητε. ὅτι τούτῳ πολεμῶ, διὰ τοῦτό μ’ ἀναιρήσετε;” τὰ τοιαῦτα πολλάκις οἶδ’ ὅτι φθέγξεται, βουλόμενος φθόνον τιν’ ἐμοὶ διὰ τούτων τῶν λόγων συνάγειν.", "st": "21.29"}, {"sp": "N", "t": "ἔχει δ’ οὐχ οὕτω ταῦτα, οὐδ’ ἐγγύς. οὐδένα γὰρ τῶν ἀδικούντων ὑμεῖς οὐδενὶ τῶν κατηγόρων ἐκδίδοτε· οὐδὲ γὰρ ἐπειδὰν ἀδικηθῇ τις, ὡς ἂν ἕκαστος ὑμᾶς ὁ παθὼν πείσῃ, ποιεῖσθε τὴν τιμωρίαν, ἀλλὰ τοὐναντίον νόμους ἔθεσθε πρὸ τῶν ἀδικημάτων, ἐπ’ ἀδήλοις μὲν τοῖς ἀδικήσουσιν, ἀδήλοις δὲ τοῖς ἀδικησομένοις. οὗτοι δὲ τί ποιοῦσιν οἱ νόμοι; πᾶσιν ὑπισχνοῦνται τοῖς ἐν τῇ πόλει, δίκην, ἂν ἀδικηθῇ τις, ἔσεσθαι δι’ αὐτῶν λαβεῖν. ὅταν τοίνυν τῶν παραβαινόντων τινὰ τοὺς νόμους κολάζητε, οὐ τοῖς κατηγόροις τοῦτον ἐκδίδοτε, ἀλλὰ τοὺς νόμους ὑμῖν αὐτοῖς βεβαιοῦτε.", "st": "21.30"}, {"sp": "N", "t": "ἀλλὰ μὴν πρός γε τὸ τοιοῦτον, ὅτι “Δημοσθένης” φησὶν “ὕβρισται,” δίκαιος καὶ κοινὸς καὶ ὑπὲρ ἁπάντων ἔσθ’ ὁ λόγος. οὐ γὰρ εἰς Δημοσθένην ὄντα μ’ ἠσέλγαινε μόνον ταύτην τὴν ἡμέραν, ἀλλὰ καὶ εἰς χορηγὸν ὑμέτερον· τοῦτο δ’ ὅσον δύναται γνοίητ’ ἂν ἐκ τωνδί.", "st": "21.31"}, {"sp": "N", "t": "ἴστε δήπου τοῦθ’ ὅτι τῶν θεσμοθετῶν τούτων οὐδενὶ θεσμοθέτης ἔστ’ ὄνομα, ἀλλ’ ὁτιδήποθ’ ἑκάστῳ. ἂν μὲν τοίνυν ἰδιώτην ὄντα τιν’ αὐτῶν ὑβρίσῃ τις ἢ κακῶς εἴπῃ, γραφὴν ὕβρεως καὶ δίκην κακηγορίας ἰδίαν φεύξεται, ἐὰν δὲ θεσμοθέτην, ἄτιμος ἔσται καθάπαξ. διὰ τί; ὅτι τοὺς νόμους ἤδη ὁ τοῦτο ποιῶν προσυβρίζει καὶ τὸν ὑμέτερον κοινὸν στέφανον καὶ τὸ τῆς πόλεως ὄνομα· ὁ γὰρ θεσμοθέτης οὐδενὸς ἀνθρώπων ἔστ’ ὄνομα, ἀλλὰ τῆς πόλεως.", "st": "21.32"}, {"sp": "N", "t": "καὶ πάλιν γε τὸν ἄρχοντα, ταὐτὸ τοῦτο, ἐὰν μὲν ἐστεφανωμένον πατάξῃ τις ἢ κακῶς εἴπῃ, ἄτιμος, ἐὰν δ’ ἰδιώτην, ἰδίᾳ ὑπόδικος. καὶ οὐ μόνον περὶ τούτων οὕτω ταῦτ’ ἔχει, ἀλλὰ καὶ περὶ πάντων οἷς ἂν ἡ πόλις τιν’ ἄδειαν ἢ στεφανηφορίαν ἤ τινα τιμὴν δῷ. οὕτω τοίνυν καὶ ἐμέ, εἰ μὲν ἐν ἄλλαις τισὶν ἡμέραις ἠδίκησέ τι τούτων Μειδίας ἰδιώτην ὄντα, ἰδίᾳ καὶ δίκην προσῆκεν αὐτῷ διδόναι·", "st": "21.33"}, {"sp": "N", "t": "εἰ δὲ χορηγὸν ὄνθ’ ὑμέτερον ἱερομηνίας οὔσης πάνθ’ ὅσ’ ἠδίκηκεν ὑβρίσας φαίνεται, δημοσίας ὀργῆς καὶ τιμωρίας δίκαιός ἐστι τυγχάνειν· ἅμα γὰρ τῷ Δημοσθένει καὶ ὁ χορηγὸς ὑβρίζετο, τοῦτο δ’ ἐστὶ τῆς πόλεως, καὶ τὸ ταύταις ταῖς ἡμέραις, αἷς οὐκ ἐῶσιν οἱ νόμοι. χρὴ δ’, ὅταν μὲν τιθῆσθε τοὺς νόμους, ὁποῖοί τινές εἰσι σκοπεῖν, ἐπειδὰν δὲ θῆσθε, φυλάττειν καὶ χρῆσθαι· καὶ γὰρ εὔορκα ταῦθ’ ὑμῖν ἐστι καὶ ἄλλως δίκαια.", "st": "21.34"}, {"sp": "N", "t": "ἦν ὁ τῆς βλάβης ὑμῖν νόμος πάλαι, ἦν ὁ τῆς αἰκείας, ἦν ὁ τῆς ὕβρεως. εἰ τοίνυν ἀπέχρη τοὺς τοῖς Διονυσίοις τι ποιοῦντας τούτων κατὰ τούτους τοὺς νόμους δίκην διδόναι, οὐδὲν ἂν προσέδει τοῦδε τοῦ νόμου. ἀλλ’ οὐκ ἀπέχρη. σημεῖον δέ· ἔθεσθ’ ἱερὸν νόμον αὐτῷ τῷ θεῷ περὶ τῆς ἱερομηνίας. εἴ τις οὖν κἀκείνοις τοῖς προϋπάρχουσι νόμοις καὶ τούτῳ τῷ μετ’ ἐκείνους τεθέντι καὶ πᾶσι τοῖς λοιποῖς ἔστ’ ἔνοχος, ὁ τοιοῦτος πότερα μὴ δῷ διὰ τοῦτο δίκην ἢ ⟨κἂν⟩ μείζω δοίη δικαίως; ἐγὼ μὲν οἴομαι μέζω.", "st": "21.35"}, {"sp": "N", "t": "ἀπήγγελλε τοίνυν τίς μοι περιιόντ’ αὐτὸν συλλέγειν καὶ πυνθάνεσθαι τίσι πώποτε συμβέβηκεν ὑβρισθῆναι, καὶ λέγειν τούτους καὶ διηγεῖσθαι πρὸς ὑμᾶς μέλλειν, οἷον, ὦ ἄνδρες Ἀθηναῖοι, τὸν πρόεδρον ὅν ποτέ φασιν ἐν ὑμῖν ὑπὸ Πολυζήλου πληγῆναι, καὶ τὸν θεσμοθέτην ὃς ἔναγχος ἐπλήγη τὴν αὐλητρίδ’ ἀφαιρούμενος, καὶ τοιούτους τινάς, ὡς, ἐὰν πολλοὺς ἑτέρους δεινὰ καὶ πολλὰ πεπονθότας ἐπιδείξῃ, ἧττον ὑμᾶς ἐφ’ οἷς ἐγὼ πέπονθ’ ὀργιουμένους. ἐμοὶ δ’ αὖ τοὐναντίον, ὦ ἄνδρες Ἀθηναῖοι,", "st": "21.36"}, {"sp": "N", "t": "δοκεῖτε ποιεῖν ἂν εἰκότως, εἴπερ ὑπὲρ τοῦ κοινῇ βελτίστου δεῖ μέλειν ὑμῖν. τίς γὰρ οὐκ οἶδεν ὑμῶν τοῦ μὲν πολλὰ τοιαῦτα γίγνεσθαι τὸ μὴ κολάζεσθαι τοὺς ἐξαμαρτάνοντας αἴτιον ὄν, τοῦ δὲ μηδέν’ ὑβρίζειν τὸ λοιπὸν τὸ δίκην τὸν ἀεὶ ληφθένθ’ ἣν προσήκει διδόναι μόνον αἴτιον ἂν γενόμενον; εἰ μὲν τοίνυν ἀποτρέψαι συμφέρει τοὺς ἄλλους, τοῦτον καὶ δι’ ἐκεῖνα κολαστέον, καὶ μᾶλλόν γ’ ὅσῳπερ ἂν ᾖ πλείω καὶ μείζω· εἰ δὲ παροξῦναι καὶ τοῦτον καὶ πάντας, ἐατέον.", "st": "21.37"}, {"sp": "N", "t": "ἔτι τοίνυν οὐδ’ ὁμοίαν οὖσαν τούτῳ κἀκείνοις συγγνώμην εὑρήσομεν. πρῶτον μὲν γὰρ ὁ τὸν θεσμοθέτην πατάξας τρεῖς εἶχεν προφάσεις, μέθην, ἔρωτα, ἄγνοιαν διὰ τὸ σκότους καὶ νυκτὸς τὸ πρᾶγμα γενέσθαι. ἔπειθ’ ὁ Πολύζηλος ὀργῇ καὶ τρόπου προπετείᾳ φθάσας τὸν λογισμὸν ἁμαρτὼν ἔπαισεν· οὐ γὰρ ἐχθρός γ’ ὑπῆρχεν ὤν, οὐδ’ ἐφ’ ὕβρει τοῦτ’ ἐποίησεν. ἀλλ’ οὐ Μειδίᾳ τούτων οὐδὲν ἔστ’ εἰπεῖν· καὶ γὰρ ἐχθρὸς ἦν, καὶ μεθ’ ἡμέραν εἰδὼς ὕβριζεν, καὶ οὐκ ἐπὶ τούτου μόνον, ἀλλ’ ἐπὶ πάντων φαίνεται προῃρημένος μ’ ὑβρίζειν.", "st": "21.38"}, {"sp": "N", "t": "καὶ μὴν οὐδὲ τῶν πεπραγμένων ἐμοὶ καὶ τούτοις οὐδὲν ὅμοιον ὁρῶ. πρῶτον μὲν γὰρ ὁ θεσμοθέτης οὐχ ὑπὲρ ὑμῶν οὐδὲ τῶν νόμων φροντίσας οὐδ’ ἀγανακτήσας φανήσεται, ἀλλ’ ἰδίᾳ πεισθεὶς ὁπόσῳ δήποτ’ ἀργυρίῳ καθυφεὶς τὸν ἀγῶνα· ἔπειθ’ ὁ πληγεὶς ἐκεῖνος ὑπὸ τοῦ Πολυζήλου, ταὐτὸ τοῦτο, ἰδίᾳ διαλυσάμενος, ἐρρῶσθαι πολλὰ τοῖς νόμοις εἰπὼν καὶ ὑμῖν, οὐδ’ εἰσήγαγε τὸν Πολύζηλον.", "st": "21.39"}, {"sp": "N", "t": "εἰ μὲν τοίνυν ἐκείνων κατηγορεῖν βούλεταί τις ἐν τῷ παρόντι, δεῖ λέγειν ταῦτα· εἰ δ’ ὑπὲρ ὧν ἐγὼ τούτου κατηγόρηκ’ ἀπολογεῖσθαι, πάντα μᾶλλον ἢ ταῦτα λεκτέα. πᾶν γὰρ τοὐναντίον ἐκείνοις αὐτὸς μὲν οὔτε λαβὼν οὐδὲν οὔτ’ ἐπιχειρήσας λαβεῖν φανήσομαι, τὴν δ’ ὑπὲρ τῶν νόμων καὶ τὴν ὑπὲρ τοῦ θεοῦ καὶ τὴν ὑπὲρ ὑμῶν τιμωρίαν δικαίως φυλάξας καὶ νῦν ἀποδεδωκὼς ὑμῖν. μὴ τοίνυν ἐᾶτε ταῦτ’ αὐτὸν λέγειν, μηδ’, ἂν βιάζηται, πείθεσθ’ ὡς δίκαιόν τι λέγοντι.", "st": "21.40"}, {"sp": "N", "t": "ἂν γὰρ ταῦθ’ οὕτως ἐγνωσμέν’ ὑπάρχῃ παρ’ ὑμῖν, οὐκ ἐνέσται αὐτῷ λόγος οὐδὲ εἷς. ποία γὰρ πρόφασις, τίς ἀνθρωπίνη καὶ μετρία σκῆψις φανεῖται τῶν πεπραγμένων αὐτῷ; ὀργὴ νὴ Δία· καὶ γὰρ τοῦτο τυχὸν λέξει. ἀλλ’ ἃ μὲν ἄν τις ἄφνω τὸν λογισμὸν φθάσας ἐξαχθῇ πρᾶξαι, κἂν ὑβριστικῶς ποιήσῃ, δι’ ὀργήν γ’ ἔνι φῆσαι πεποιηκέναι· ἃ δ’ ἂν ἐκ πολλοῦ συνεχῶς ἐπὶ πολλὰς ἡμέρας παρὰ τοὺς νόμους πράττων τις φωρᾶται, οὐ μόνον δήπου τοῦ μὴ μετ’ ὀργῆς ἀπέχει, ἀλλὰ καὶ βεβουλευμένως ὁ τοιοῦτος ὑβρίζων ἐστὶν ἤδη φανερός.", "st": "21.41"}, {"sp": "N", "t": "ἀλλὰ μὴν ὁπηνίκα καὶ πεποιηκὼς ἃ κατηγορῶ καὶ ὕβρει πεποιηκὼς φαίνεται, τοὺς νόμους ἤδη δεῖ σκοπεῖν, ὦ ἄνδρες δικασταί· κατὰ γὰρ τούτους δικάσειν ὀμωμόκατε. καὶ θεωρεῖθ’ ὅσῳ μείζονος ὀργῆς καὶ ζημίας ἀξιοῦσι τοὺς ἑκουσίως καὶ δι’ ὕβριν πλημμελοῦντας τῶν ἄλλως πως ἐξαμαρτανόντων.", "st": "21.42"}, {"sp": "N", "t": "πρῶτον μὲν τοίνυν οἱ περὶ τῆς βλάβης οὗτοι νόμοι πάντες, ἵν’ ἐκ τούτων ἄρξωμαι, ἂν μὲν ἑκὼν βλάψῃ, διπλοῦν, ἂν δ’ ἄκων, ἁπλοῦν τὸ βλάβος κελεύουσιν ἐκτίνειν. εἰκότως· ὁ μὲν γὰρ παθὼν πανταχοῦ βοηθείας δίκαιος τυγχάνειν, τῷ δράσαντι δ’ οὐκ ἴσην τὴν ὀργήν, ἄν θ’ ἑκὼν ἄν τ’ ἄκων, ἔταξ’ ὁ νόμος. ἔπειθ’ οἱ φονικοὶ τοὺς μὲν ἐκ προνοίας ἀποκτιννύντας θανάτῳ καὶ ἀειφυγίᾳ καὶ δημεύσει τῶν ὑπαρχόντων ζημιοῦσι, τοὺς δ’ ἀκουσίως αἰδέσεως καὶ φιλανθρωπίας πολλῆς ἠξίωσαν.", "st": "21.43"}, {"sp": "N", "t": "οὐ μόνον δ’ ἐπὶ τούτων τοῖς ἐκ προαιρέσεως ὑβρισταῖς χαλεποὺς ὄντας ἰδεῖν ἔστι τοὺς νόμους, ἀλλὰ καὶ ἐφ’ ἁπάντων. τί γὰρ δή ποτ’, ἄν τις ὀφλὼν δίκην μὴ ἐκτίνῃ, οὐκέτ’ ἐποίησ’ ὁ νόμος τὴν ἐξούλην ἰδίαν, ἀλλὰ προστιμᾶν ἐπέταξε τῷ δημοσίῳ; καὶ πάλιν τί δή ποτ’, ἂν μὲν ἑκὼν παρ’ ἑκόντος τις λάβῃ τάλαντον ἓν ἢ δύ’ ἢ δέκα καὶ ταῦτ’ ἀποστερήσῃ, οὐδὲν αὐτῷ πρὸς τὴν πόλιν ἐστίν, ἂν δὲ μικροῦ πάνυ τιμήματος ἄξιόν τις λάβῃ, βίᾳ δὲ τοῦτ’ ἀφέληται, τὸ ἴσον τῷ δημοσίῳ προστιμᾶν οἱ νόμοι κελεύουσιν ὅσον περ δὴ τῷ ἰδιώτῃ;", "st": "21.44"}, {"sp": "N", "t": "ὅτι πάνθ’ ὅσα τις βιαζόμενος πράττει κοίν’ ἀδικήματα καὶ κατὰ τῶν ἔξω τοῦ πράγματος ὄντων ἡγεῖθ’ ὁ νομοθέτης· τὴν μὲν γὰρ ἰσχὺν ὀλίγων, τοὺς δὲ νόμους ἁπάντων εἶναι, καὶ τὸν μὲν πεισθέντ’ ἰδίας, τὸν δὲ βιασθέντα δημοσίας δεῖσθαι βοηθείας. διόπερ καὶ τῆς ὕβρεως αὐτῆς τὰς μὲν γραφὰς ἔδωκεν ἅπαντι τῷ βουλομένῳ, τὸ δὲ τίμημ’ ἐποίησεν ὅλον δημόσιον· τὴν γὰρ πόλιν ἡγεῖτ’ ἀδικεῖν, οὐ τὸν παθόντα μόνον, τὸν ὑβρίζειν ἐπιχειροῦντα, καὶ δίκην ἱκανὴν τὴν τιμωρίαν εἶναι τῷ παθόντι, χρήματα δ’ οὐ προσήκειν τῶν τοιούτων ἐφ’ ἑαυτῷ λαμβάνειν.", "st": "21.45"}, {"sp": "N", "t": "καὶ τοσαύτῃ γ’ ἐχρήσαθ’ ὑπερβολῇ, ὥστε κἂν εἰς δοῦλον ὑβρίζῃ τις, ὁμοίως ἔδωκεν ὑπὲρ τούτου γραφήν. οὐ γὰρ ὅστις ὁ πάσχων ᾤετο δεῖν σκοπεῖν, ἀλλὰ τὸ πρᾶγμ’ ὁποῖόν τι τὸ γιγνόμενον· ἐπειδὴ δ’ εὗρεν οὐκ ἐπιτήδειον, μήτε πρὸς δοῦλον μήθ’ ὅλως ἐξεῖναι πράττειν ἐπέτρεψεν. οὐ γὰρ ἔστιν, οὐκ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, τῶν πάντων οὐδὲν ὕβρεως ἀφορητότερον, οὐδ’ ἐφ’ ὅτῳ μᾶλλον ὑμῖν ὀργίζεσθαι προσήκει. ἀνάγνωθι δ’ αὐτόν μοι λαβὼν τὸν τῆς ὕβρεως νόμον· οὐδὲν γὰρ οἷον ἀκούειν αὐτοῦ τοῦ νόμου.", "st": "21.46"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "21.46"}, {"sp": "N", "t": "ἐάν τις ὑβρίζῃ εἴς τινα, ἢ παῖδα ἢ γυναῖκα ἢ ἄνδρα, τῶν ἐλευθέρων ἢ τῶν δούλων, ἢ παράνομόν τι ποιήσῃ εἰς τούτων τινά, γραφέσθω πρὸς τοὺς θεσμοθέτας ὁ βουλόμενος Ἀθηναίων οἷς ἔξεστιν, οἱ δὲ θεσμοθέται εἰσαγόντων εἰς τὴν ἡλιαίαν τριάκοντα ἡμερῶν ἀφ’ ἧς ἂν γραφῇ, ἐὰν μή τι δημόσιον κωλύῃ, εἰ δὲ μή, ὅταν ᾖ πρῶτον οἷόν τε. ὅτου δ’ ἂν καταγνῷ ἡ ἡλιαία, τιμάτω περὶ αὐτοῦ παραχρῆμα, ὅτου ἂν δοκῇ ἄξιος εἶναι παθεῖν ἢ ἀποτεῖσαι. ὅσοι δ’ ἂν γράφωνται γραφὰς ἰδίας κατὰ τὸν νόμον, ἐάν τις μὴ ἐπεξέλθῃ ἢ ἐπεξιὼν μὴ μεταλάβῃ τὸ πέμπτον μέρος τῶν ψήφων, ἀποτεισάτω χιλίας δραχμὰς τῷ δημοσίῳ. ἐὰν δὲ ἀργυρίου τιμηθῇ τῆς ὕβρεως, δεδέσθω, ἐὰν ἐλεύθερον ὑβρίσῃ, μέχρι ἂν ἐκτείσῃ.", "st": "21.47"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦ νόμου τῆς φιλανθρωπίας, ὃς οὐδὲ τοὺς δούλους ὑβρίζεσθαι ἀξιοῖ. τί οὖν πρὸς θεῶν; εἴ τις εἰς τοὺς βαρβάρους ἐνεγκὼν τὸν νόμον τοῦτον, παρ’ ὧν τὰ ἀνδράποδ’ εἰς τοὺς Ἕλληνας κομίζεται, ἐπαινῶν ὑμᾶς καὶ διεξιὼν περὶ τῆς πόλεως εἴποι πρὸς αὐτοὺς ὅτι", "st": "21.48"}, {"sp": "N", "t": "“εἰσὶν Ἕλληνές τινες ἄνθρωποι οὕτως ἥμεροι καὶ φιλάνθρωποι τοὺς τρόπους ὥστε πόλλ’ ὑφ’ ὑμῶν ἠδικημένοι, καὶ φύσει τῆς πρὸς ὑμᾶς ἔχθρας αὐτοῖς ὑπαρχούσης πατρικῆς, ὅμως οὐδ’ ὅσων ἂν τιμὴν καταθέντες δούλους κτήσωνται, οὐδὲ τούτους ὑβρίζειν ἀξιοῦσιν, ἀλλὰ νόμον δημοσίᾳ τὸν ταῦτα κωλύσοντα τέθεινται τουτονὶ καὶ πολλοὺς ἤδη παραβάντας τὸν νόμον τοῦτον ἐζημιώκασιν θανάτῳ,”", "st": "21.49"}, {"sp": "N", "t": "εἰ ταῦτ’ ἀκούσειαν καὶ συνεῖεν οἱ βάρβαροι, οὐκ ἂν οἴεσθε δημοσίᾳ πάντας ὑμᾶς προξένους αὑτῶν ποιήσασθαι; τὸν τοίνυν οὐ παρὰ τοῖς Ἕλλησιν μόνον εὐδοκιμοῦντα νόμον, ἀλλὰ καὶ παρὰ τοῖς βαρβάροις εὖ δόξαντ’ ἂν ἔχειν, σκοπεῖσθ’ ὁ παραβὰς ἥντινα δοὺς δίκην ἀξίαν ἔσται δεδωκώς.", "st": "21.50"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, μὴ χορηγὸς ὢν ταῦτ’ ἐπεπόνθειν ὑπὸ Μειδίου, ὕβριν ἄν τις μόνον κατέγνω τῶν πεπραγμένων αὐτῷ· νῦν δέ μοι δοκεῖ, κἂν ἀσέβειαν εἰ καταγιγνώσκοι, τὰ προσήκοντα ποιεῖν. ἴστε γὰρ δήπου τοῦθ’ ὅτι τοὺς χοροὺς ὑμεῖς ἅπαντας τούτους καὶ τοὺς ὕμνους τῷ θεῷ ποιεῖτε, οὐ μόνον κατὰ τοὺς νόμους τοὺς περὶ τῶν Διονυσίων, ἀλλὰ καὶ κατὰ τὰς μαντείας, ἐν αἷς ἁπάσαις ἀνῃρημένον εὑρήσετε τῇ πόλει, ὁμοίως ἐκ Δελφῶν καὶ ἐκ Δωδώνης, χοροὺς ἱστάναι κατὰ τὰ πάτρια καὶ κνισᾶν ἀγυιὰς καὶ στεφανηφορεῖν.", "st": "21.51"}, {"sp": "N", "t": "ἀνάγνωθι δέ μοι λαβὼν αὐτὰς τὰς μαντείας.", "st": "21.52"}, {"sp": "N", "t": "ΜΑΝΤΕΙΑ", "st": "21.52"}, {"sp": "N", "t": "αὐδῶ Ἐρεχθείδῃσιν, ὅσοι Πανδίονος ἄστυ<br>ναίετε καὶ πατρίοισι νόμοις ἰθύνεθ’ ἑορτάς,<br>μεμνῆσθαι Βάκχοιο, καὶ εὐρυχόρους κατ’ ἀγυιὰς<br>ἱστάναι ὡραίων Βρομίῳ χάριν ἄμμιγα πάντας,<br>καὶ κνισᾶν βωμοῖσι κάρη στεφάνοις πυκάσαντας.", "st": "21.52"}, {"sp": "N", "t": "περὶ ὑγιείας θύειν καὶ εὔχεσθαι Διὶ ὑπάτῳ, Ἡρακλεῖ, Ἀπόλλωνι προστατηρίῳ· περὶ τύχας ἀγαθᾶς Ἀπόλλωνι ἀγυιεῖ, Λατοῖ, Ἀρτέμιδι, καὶ κατ’ ἀγυιὰς κρατῆρας ἱστάμεν καὶ χοροὺς καὶ στεφαναφορεῖν καττὰ πάτρια θεοῖς Ὀλυμπίοις πάντεσσι καὶ πάσαις, ἰδίας δεξιὰς καὶ ἀριστερὰς ἀνίσχοντας, καὶ μνασιδωρεῖν.", "st": "21.52"}, {"sp": "N", "t": "ΕΚ ΔΩΔΩΝΗΣ ΜΑΝΤΕΙΑΙ", "st": "21.52"}, {"sp": "N", "t": "τῷ δήμῳ τῷ Ἀθηναίων ὁ τοῦ Διὸς σημαίνει. ὅτι τὰς ὥρας παρηνέγκατε τῆς θυσίας καὶ τῆς θεωρίας, αἱρετοὺς πέμπειν κελεύει θεωροὺς ἕνεκα τούτου διὰ ταχέων, ⟨καὶ⟩ τῷ Διὶ τῷ Ναΐῳ τρεῖς βοῦς καὶ πρὸς ἑκάστῳ βοῒ δύο οἶς, τῇ Διώνῃ βοῦν καλλιερεῖν, καὶ τράπεζαν χαλκῆν [καὶ] πρὸς τὸ ἀνάθημα ὃ ἀνέθηκεν ὁ δῆμος ὁ Ἀθηναίων.", "st": "21.53"}, {"sp": "N", "t": "ὁ τοῦ Διὸς σημαίνει ἐν Δωδώνῃ, Διονύσῳ δημοτελῆ ἱερὰ τελεῖν καὶ κρατῆρα κεράσαι καὶ χοροὺς ἱστάναι, Ἀπόλλωνι ἀποτροπαίῳ βοῦν θῦσαι, καὶ στεφανηφορεῖν ἐλευθέρους καὶ δούλους, καὶ ἐλινύειν μίαν ἡμέραν. Διὶ κτησίῳ βοῦν λευκόν.", "st": "21.53"}, {"sp": "N", "t": "εἰσίν, ὦ ἄνδρες Ἀθηναῖοι, καὶ αὗται καὶ ἄλλαι πολλαὶ μαντεῖαι τῇ πόλει κἀγαθαί. τί οὖν ἐκ τούτων ὑμᾶς ἐνθυμεῖσθαι δεῖ; ὅτι τὰς μὲν ἄλλας θυσίας τοῖς ἐφ’ ἑκάστης μαντείας προφαινομένοις θεοῖς προστάττουσι θύειν, ἱστάναι δὲ χοροὺς καὶ στεφανηφορεῖν κατὰ τὰ πάτρια πρὸς ἁπάσαις ταῖς ἀφικνουμέναις μαντείαις προσαναιροῦσιν ὑμῖν.", "st": "21.54"}, {"sp": "N", "t": "οἱ τοίνυν χοροὶ πάντες οἱ γιγνόμενοι καὶ οἱ χορηγοὶ δῆλον ὅτι τὰς μὲν ἡμέρας ἐκείνας ἃς συνερχόμεθ’ ἐπὶ τὸν ἀγῶνα, κατὰ τὰς μαντείας ταύτας ὑπὲρ ὑμῶν ἐστεφανώμεθα, ὁμοίως ὅ τε μέλλων νικᾶν καὶ ὁ πάντων ὕστατος γενήσεσθαι, τῇ δὲ τῶν ἐπινικίων ὑπὲρ αὑτοῦ τότ’ ἤδη στεφανοῦται ὁ νικῶν. τὸν οὖν εἴς τινα τούτων τῶν χορευτῶν ἢ τῶν χορηγῶν ὑβρίζοντ’ ἐπ’ ἔχθρᾳ, καὶ ταῦτ’ ἐν αὐτῷ τῷ ἀγῶνι καὶ ἐν τῷ τοῦ θεοῦ ἱερῷ, τοῦτον ἄλλο τι πλὴν ἀσεβεῖν φήσομεν;", "st": "21.55"}, {"sp": "N", "t": "καὶ μὴν ἴστε γε τοῦθ’ ὅτι βουλόμενοι μηδέν’ ἀγωνίζεσθαι ξένον οὐκ ἐδώκαθ’ ἁπλῶς τῶν χορηγῶν οὐδενὶ προσκαλέσαντι τοὺς χορευτὰς σκοπεῖν, ἀλλ’ ἐὰν μὲν καλέσῃ, πεντήκοντα δραχμάς, ἐὰν δὲ καθέζεσθαι καθέζεσθαι κελεύσῃ, χιλίας ἀποτίνειν ἐτάξατε. τίνος εἵνεκα; ὅπως μὴ τὸν ἐστεφανωμένον καὶ λῃτουργοῦντα τῷ θεῷ ταύτην τὴν ἡμέραν καλῇ μηδ’ ἐπηρεάζῃ μηδ’ ὑβρίζῃ μηδεὶς ἐξεπίτηδες.", "st": "21.56"}, {"sp": "N", "t": "εἶτα τὸν μὲν χορευτὴν οὐδ’ ὁ προσκαλέσας κατὰ τὸν νόμον ἀζήμιος ἔσται, τὸν δὲ χορηγὸν οὐδ’ ὁ συγκόψας παρὰ πάντας τοὺς νόμους οὕτω φανερῶς δώσει δίκην; ἀλλὰ μὴν οὐδέν ἐστ’ ὄφελος καλῶς καὶ φιλανθρώπως τοὺς νόμους ὑπὲρ τῶν πολλῶν κεῖσθαι, εἰ τοῖς ἀπειθοῦσι καὶ βιαζομένοις αὐτοὺς ἡ παρ’ ὑμῶν ὀργὴ τῶν ἀεὶ κυρίων μὴ γενήσεται.", "st": "21.57"}, {"sp": "N", "t": "φέρε δὴ πρὸς θεῶν κἀκεῖνο σκέψασθε. παραιτήσομαι δ’ ὑμᾶς μηδὲν ἀχθεσθῆναί μοι, ἐὰν ἐπὶ συμφορᾶς τινῶν γεγονότων ὀνομαστὶ μνησθῶ· οὐ γὰρ ὀνειδίσαι μὰ τοὺς θεοὺς οὐδενὶ δυσχερὲς οὐδὲν βουλόμενος τοῦτο ποιήσω, ἀλλὰ δεῖξαι τὸ βιάζεσθαι καὶ ὑβρίζειν καὶ τὰ τοιαῦτα ποιεῖν ὡς ἅπαντες ὑμεῖς οἱ ἄλλοι φεύγετε. Σαννίων ἐστὶ δήπου τις ὁ τοὺς τραγικοὺς χοροὺς διδάσκων· οὗτος ἀστρατείας ἑάλω καὶ κέχρηται συμφορᾷ.", "st": "21.58"}, {"sp": "N", "t": "τοῦτον μετὰ τὴν ἀτυχίαν ταύτην ἐμισθώσατό τις φιλονικῶν χορηγὸς τραγῳδῶν, οἶμαι, Θεοζοτίδης. τὸ μὲν οὖν πρῶτον ἠγανάκτουν οἱ ἀντιχορηγοὶ καὶ κωλύσειν ἔφασαν, ὡς δ’ ἐπληρώθη τὸ θέατρον καὶ τὸν ὄχλον συνειλεγμένον εἶδον ἐπὶ τὸν ἀγῶνα, ὤκνησαν, εἴασαν, οὐδεὶς ἥψατο, ἀλλὰ τοσοῦτον τῆς εὐσεβείας ἐν ἑκάστῳ τις ἂν ὑμῶν ἴδοι τὸ συγκεχωρηκὸς ὥστε πάντα τὸν μετὰ ταῦτα χρόνον διδάσκει τοὺς χοροὺς καὶ οὐδὲ τῶν ἰδίων ἐχθρῶν οὐδεὶς κωλύει· τοσοῦτ’ ἀπέχει τῶν χορηγῶν.", "st": "21.59"}, {"sp": "N", "t": "ἄλλος ἐστὶν Ἀριστείδης Οἰνῇδος φυλῆς, ἠτυχηκώς τι καὶ οὗτος τοιοῦτον, ὃς νῦν μὲν καὶ γέρων ἐστὶν ἤδη καὶ ἴσως ἥττων χορευτής, ἦν δέ ποθ’ ἡγεμὼν τῆς φυλῆς [κορυφαῖος]. ἴστε δὲ δήπου τοῦθ’ ὅτι τὸν ἡγεμόν’ ἂν ἀφέλῃ τις, οἴχεται ὁ λοιπὸς χορός. ἀλλ’ ὅμως πολλῶν χορηγῶν φιλονικησάντων, οὐδεὶς πώποτε τοῦτ’ εἶδε τὸ πλεονέκτημα, οὐδ’ ἐτόλμησε τοῦτον ἐξαγαγεῖν οὐδὲ κωλῦσαι· διὰ γὰρ τὸ δεῖν αὐτὸν ἐπιλαβόμενον τῇ χειρὶ τοῦτο ποιῆσαι καὶ μὴ προσκαλέσασθαι πρὸς τὸν ἄρχοντ’ ἐξεῖναι, ὥσπερ ἂν εἰ ξένον τις ἐξαγαγεῖν ἐβούλετο, ἅπας τις ὤκνει τῆς ἀσελγείας ταύτης αὐτόχειρ ὀφθῆναι γιγνόμενος.", "st": "21.60"}, {"sp": "N", "t": "οὔκουν δεινόν, ὦ ἄνδρες δικασταί, καὶ σχέτλιον τῶν μὲν νικᾶν ἂν παρὰ τοῦτ’ οἰομένων χορηγῶν, τῶν ἀνηλωκότων πολλάκις πάντα τὰ ὄντ’ εἰς τὰς λῃτουργίας, μηδένα τολμῆσαι πώποτε μηδ’ ὧν οἱ νόμοι διδόασιν ἅψασθαι, ἀλλ’ οὕτως εὐλαβῶς, οὕτως εὐσεβῶς, οὕτω μετρίως διακεῖσθαι ὥστ’ ἀναλίσκοντας, ἀγωνιῶντας ὅμως ἀπέχεσθαι καὶ προορᾶσθαι τὰς ὑμετέρας βουλήσεις καὶ τὴν περὶ τὴν ἑορτὴν σπουδήν, Μειδίαν δ’ ἰδιώτην ὄντα, μηδὲν ἀνηλωκότα, ὅτι τῳ προσέκρουσεν καὶ ἐχθρὸς ὑπῆρχεν, τοῦτον ἀναλίσκοντα, χορηγοῦντα, ἐπίτιμον ὄντα προπηλακίζειν καὶ τύπτειν, καὶ μήτε τῆς ἑορτῆς μήτε τῶν νόμων μήτε τί ὑμεῖς ἐρεῖτε μήτε τοῦ θεοῦ φροντίζειν;", "st": "21.61"}, {"sp": "N", "t": "πολλῶν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, γεγενημένων ἐχθρῶν ἀλλήλοις, οὐ μόνον ἐξ ἰδίων ἀλλὰ καὶ ἐκ κοινῶν πραγμάτων, οὐδεὶς πώποτ’ εἰς τοσοῦτ’ ἀναιδείας ἀφίκεθ’ ὥστε τοιοῦτόν τι τολμῆσαι ποιεῖν. καίτοι φασὶν Ἰφικράτην ποτ’ ἐκεῖνον Διοκλεῖ τῷ Πιθεῖ τὰ μάλιστ’ ἐλθεῖν εἰς ἔχθραν, καὶ ἔτι πρὸς τούτῳ συμβῆναι Τεισίαν τὸν Ἰφικράτους ἀδελφὸν ἀντιχορηγῆσαι τῷ Διοκλεῖ. ἀλλ’ ὅμως πολλοὺς μὲν ἔχων φίλους Ἰφικράτης, πολλὰ δὲ χρήματα κεκτημένος, φρονῶν δ’ ἐφ’ αὑτῷ τηλικοῦτον ἡλίκον εἰκὸς ἄνδρα καὶ δόξης καὶ τιμῶν τετυχηκόθ’ ὧν ἐκεῖνος ἠξίωτο παρ’ ὑμῶν,", "st": "21.62"}, {"sp": "N", "t": "οὐκ ἐβάδιζ’ ἐπὶ τὰς τῶν χρυσοχόων οἰκίας νύκτωρ, οὐδὲ κατερρήγνυεν τὰ παρασκευαζόμεν’ ἱμάτι’ εἰς τὴν ἑορτήν, οὐδὲ διέφθειρε διδάσκαλον, οὐδὲ χορὸν μανθάνειν ἐκώλυεν, οὐδὲ τῶν ἄλλων οὐδὲν ὧν οὗτος διεπράττετ’ ἐποίει, ἀλλὰ τοῖς νόμοις καὶ τῇ τῶν ἄλλων βουλήσει συγχωρῶν ἠνείχετο καὶ νικῶντα καὶ στεφανούμενον τὸν ἐχθρὸν ὁρῶν, εἰκότως· ἐν ᾗ γὰρ αὐτὸς εὐδαίμων ᾔδει γεγονὼς πολιτείᾳ, ταύτῃ συγχωρεῖν τὰ τοιαῦτ’ ἠξίου.", "st": "21.63"}, {"sp": "N", "t": "πάλιν Φιλόστρατον πάντες ἴσμεν τὸν Κολωνῆθεν Χαβρίου κατηγοροῦντα, ὅτ’ ἐκρίνετο τὴν περὶ Ὠρωποῦ κρίσιν θανάτου, καὶ πάντων τῶν κατηγόρων πικρότατον γενόμενον, καὶ μετὰ ταῦτα χορηγοῦντα παισὶν Διονύσια καὶ νικῶντα, καὶ Χαβρίαν οὔτε τύπτοντα οὔτ’ ἀφαρπάζοντα τὸν στέφανον οὔθ’ ὅλως προσιόνθ’ ὅποι μὴ προσῆκεν αὐτῷ.", "st": "21.64"}, {"sp": "N", "t": "πολλοὺς δ’ ἂν ἔχων εἰπεῖν ἔτι καὶ διὰ πολλὰς προφάσεις ἐχθροὺς γεγενημένους ἀλλήλοις, οὐδένα πώποτ’ οὔτ’ ἀκήκοα οὔθ’ ἑόρακα ὅστις εἰς τοσοῦτον ἐλήλυθεν ὕβρεως ὥστε τοιοῦτόν τι ποιεῖν. οὐδέ γ’ ἐκεῖν’ οὐδεὶς ὑμῶν οἶδ’ ὅτι μνημονεύει πρότερον, τῶν ἐπὶ τοῖς ἰδίοις ἢ καὶ τοῖς κοινοῖς ἐχθρῶν ἀλλήλοις οὐδέν’ οὔτε καλουμένων τῶν κριτῶν παρεστηκότα, οὔθ’ ὅταν ὀμνύωσιν ἐξορκοῦντα, οὔθ’ ὅλως ἐπ’ οὐδενὶ τῶν τοιούτων ἐχθρὸν ἐξεταζόμενον.", "st": "21.65"}, {"sp": "N", "t": "ταῦτα γὰρ πάντα καὶ τὰ τοιαῦτ’, ὦ ἄνδρες Ἀθηναῖοι, φιλονικίᾳ μὲν ὑπαχθέντα χορηγὸν ὄντα ποιεῖν ἔχει τινὰ συγγνώμην· ἔχθρᾳ δ’ ἐλαύνοντά τινα, ἐκ προαιρέσεως, ἐφ’ ἅπασι, καὶ τὴν ἰδίαν δύναμιν κρείττω τῶν νόμων οὖσαν ἐνδεικνύμενον, Ἡράκλεις, βαρὺ κοὐχὶ δίκαιόν ἐστιν οὐδὲ συμφέρον ὑμῖν. εἰ γὰρ ἑκάστῳ τῶν χορηγούντων τοῦτο πρόδηλον γένοιτο, ὅτι ἂν ὁ δεῖν’ ἐχθρὸς ᾖ μοι, Μειδίας ἤ τις ἄλλος θρασὺς οὕτω καὶ πλούσιος, πρῶτον μὲν ἀφαιρεθήσομαι τὴν νίκην, κἂν ἄμεινον ἀγωνίσωμαί τινος, ἔπειτ’ ἐφ’ ἅπασιν ἐλαττωθήσομαι καὶ προπηλακιζόμενος διατελῶ, τίς οὕτως ἀλόγιστος ἢ τίς οὕτως ἄθλιός ἐστιν, ὅστις ἑκὼν ἂν μίαν δραχμὴν ἐθελήσειεν ἀναλῶσαι; οὐδεὶς δήπου.", "st": "21.66"}, {"sp": "N", "t": "ἀλλ’, οἶμαι, τὸ πάντας ποιοῦν καὶ φιλοτιμεῖσθαι καὶ ἀναλίσκειν ἐθέλειν ἐκεῖν’ ἐστίν, ὅτι τῶν ἴσων καὶ τῶν δικαίων ἕκαστος ἡγεῖται ἑαυτῷ μετεῖναι ἐν δημοκρατίᾳ. ἐγὼ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τούτων οὐκ ἔτυχον διὰ τοῦτον, ἀλλὰ χωρὶς ὧν ὑβρίσθην, καὶ τῆς νίκης προσαπεστερήθην. καίτοι πᾶσιν ὑμῖν ἐγὼ τοῦτο δείξω σαφῶς, ὅτι μηδὲν ἀσελγὲς ἐξῆν ποιοῦντι Μειδίᾳ μηδ’ ὑβρίζοντι μηδὲ τύπτοντι καὶ λυπεῖν ἐμὲ καὶ κατὰ τοὺς νόμους αὐτῷ φιλοτιμεῖσθαι πρὸς ὑμᾶς, καὶ μηδὲ διᾶραι περὶ αὐτοῦ τὸ στόμ’ ἔχειν ἐμέ.", "st": "21.67"}, {"sp": "N", "t": "ἐχρῆν γὰρ αὐτόν, ὦ ἄνδρες Ἀθηναῖοι, ὅτ’ ἐγὼ τῆς Πανδιονίδος χορηγὸς ὑπέστην ἐν τῷ δήμῳ, τότε τῆς Ἐρεχθῇδος ἀναστάντα, τῆς ἑαυτοῦ φυλῆς, ἀνθυποστῆναι, καὶ καταστήσανθ’ ἑαυτὸν ἐξ ἴσου καὶ τὰ ὄντ’ ἀναλίσκονθ’ ὥσπερ ἐγώ, οὕτω μ’ ἀφαιρεῖσθαι τὴν νίκην, ὑβρίζειν δὲ τοιαῦτα καὶ τύπτειν μηδὲ τότε.", "st": "21.68"}, {"sp": "N", "t": "νῦν δὲ τοῦτο μὲν οὐκ ἐποίησεν, ἐν ᾧ τὸν δῆμον ἐτίμησεν ἄν, οὐδ’ ἐνεανιεύσατο τοιοῦτον οὐδέν· ἐμοὶ δ’, ὃς εἴτε τις, ὦ ἄνδρες Ἀθηναῖοι, βούλεται νομίσαι μανίαν (μανία γὰρ ἴσως ἐστὶν ὑπὲρ δύναμίν τι ποιεῖν), εἴτε καὶ φιλοτιμίᾳ χορηγὸς ὑπέστην, οὕτω φανερῶς καὶ μιαρῶς ἐπηρεάζων παρηκολούθησεν ὥστε μηδὲ τῶν ἱερῶν ἱματίων μηδὲ τοῦ χοροῦ μηδὲ τοῦ σώματος τὼ χεῖρε τελευτῶν ἀποσχέσθαι μου.", "st": "21.69"}, {"sp": "N", "t": "εἰ τοίνυν τις ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, ἄλλως πως ἔχει τὴν ὀργὴν ἐπὶ Μειδίαν ἢ ὡς δέον αὐτὸν τεθνάναι, οὐκ ὀρθῶς ἔχει. οὐ γάρ ἐστι δίκαιον οὐδὲ προσῆκον τὴν τοῦ παθόντος εὐλάβειαν τῷ μηδὲν ὑποστειλαμένῳ πρὸς ὕβριν μερίδ’ εἰς σωτηρίαν ὑπάρχειν, ἀλλὰ τὸν μὲν ὡς ἁπάντων τῶν ἀνηκέστων αἴτιον κολάζειν προσήκει, τῷ δ’ ἐπὶ τοῦ βοηθεῖν ἀποδιδόναι τὴν χάριν.", "st": "21.70"}, {"sp": "N", "t": "οὐδὲ γὰρ αὖ τοῦτ’ ἔστιν εἰπεῖν, ὡς οὐ γεγενημένου πώποτ’ οὐδενὸς ἐκ τῶν τοιούτων δεινοῦ τῷ λόγῳ τὸ πρᾶγμ’ ἐγὼ νῦν αἴρω καὶ φοβερὸν ποιῶ. πολλοῦ γε καὶ δεῖ. ἀλλ’ ἴσασιν ἅπαντες, εἰ δὲ μή, πολλοί γε, Εὔθυνον τὸν παλαίσαντά ποτ’ ἐκεῖνον, τὸν νεανίσκον, [καὶ] Σώφιλον τὸν παγκρατιαστήν (ἰσχυρός τις ἦν, μέλας, εὖ οἶδ’ ὅτι γιγνώσκουσίν τινες ὑμῶν ὃν λέγω,) τοῦτον ἐν Σάμῳ ἐν συνουσίᾳ τινὶ καὶ διατριβῇ οὕτως ἰδίᾳ, ὅτι [ὁ τύπτων] αὐτὸν ὑβρίζειν ᾤετο, ἀμυνάμενον οὕτως ὥστε καὶ ἀποκτεῖναι. ἴσασιν Εὐαίωνα πολλοὶ τὸν Λεωδάμαντος ἀδελφόν, ἀποκτείναντα Βοιωτὸν ἐν δείπνῳ καὶ συνόδῳ κοινῇ διὰ πληγὴν μίαν.", "st": "21.71"}, {"sp": "N", "t": "οὐ γὰρ ἡ πληγὴ παρέστησε τὴν ὀργήν, ἀλλ’ ἡ ἀτιμία· οὐδὲ τὸ τύπτεσθαι τοῖς ἐλευθέροις ἐστὶ δεινόν, καίπερ ὂν δεινόν, ἀλλὰ τὸ ἐφ’ ὕβρει. πολλὰ γὰρ ἂν ποιήσειεν ὁ τύπτων, ὦ ἄνδρες Ἀθηναῖοι, ὧν ὁ παθὼν ἔνι’ οὐδ’ ἂν ἀπαγγεῖλαι δύναιθ’ ἑτέρῳ, τῷ σχήματι, τῷ βλέμματι, τῇ φωνῇ, ὅταν ὡς ὑβρίζων, ὅταν ὡς ἐχθρὸς ὑπάρχων, ὅταν κονδύλοις, ὅταν ἐπὶ κόρρης. ταῦτα κινεῖ, ταῦτ’ ἐξίστησιν ἀνθρώπους αὑτῶν, ἀήθεις ὄντας τοῦ προπηλακίζεσθαι. οὐδεὶς ἄν, ὦ ἄνδρες Ἀθηναῖοι, ταῦτ’ ἀπαγγέλλων δύναιτο τὸ δεινὸν παραστῆσαι τοῖς ἀκούουσιν οὕτως ὡς ἐπὶ τῆς ἀληθείας καὶ τοῦ πράγματος τῷ πάσχοντι καὶ τοῖς ὁρῶσιν ἐναργὴς ἡ ὕβρις φαίνεται.", "st": "21.72"}, {"sp": "N", "t": "σκέψασθε δὴ πρὸς Διὸς καὶ θεῶν, ὦ ἄνδρες Ἀθηναῖοι, καὶ λογίσασθε παρ’ ὑμῖν αὐτοῖς, ὅσῳ πλείον’ ὀργὴν ἐμοὶ προσῆκε παραστῆναι πάσχοντι τοιαῦθ’ ὑπὸ Μειδίου ἢ τότ’ ἐκείνῳ τῷ Εὐαίωνι τῷ τὸν Βοιωτὸν ἀποκτείναντι. ὁ μέν γ’ ὑπὸ γνωρίμου, καὶ τούτου μεθύοντος, ἐναντίον ἓξ ἢ ἕπτ’ ἀνθρώπων ἐπλήγη, καὶ τούτων γνωρίμων, οἳ τὸν μὲν κακιεῖν οἷς ἔπραξε, τὸν δ’ ἐπαινέσεσθαι μετὰ ταῦτ’ ἀνασχόμενον καὶ κατασχόνθ’ ἑαυτὸν ἔμελλον, καὶ ταῦτ’ εἰς οἰκίαν ἐλθὼν ἐπὶ δεῖπνον, οἷ μηδὲ βαδίζειν ἐξῆν αὐτῷ·", "st": "21.73"}, {"sp": "N", "t": "ἐγὼ δ’ ὑπ’ ἐχθροῦ, νήφοντος, ἕωθεν, ὕβρει καὶ οὐκ οἴνῳ τοῦτο ποιοῦντος, ἐναντίον πολλῶν καὶ ξένων καὶ πολιτῶν ὑβριζόμην, καὶ ταῦτ’ ἐν ἱερῷ καὶ οἷ πολλή μοι ἦν ἀνάγκη βαδίζειν χορηγοῦντι. καὶ ἐμαυτὸν μέν γ’, ὦ ἄνδρες Ἀθηναῖοι, σωφρόνως, μᾶλλον δ’ εὐτυχῶς οἶμαι βεβουλεῦσθαι, ἀνασχόμενον τότε καὶ οὐδὲν ἀνήκεστον ἐξαχθέντα πρᾶξαι· τῷ δ’ Εὐαίωνι καὶ πᾶσιν, εἴ τις αὑτῷ βεβοήθηκεν ἀτιμαζόμενος, πολλὴν συγγνώμην ἔχω.", "st": "21.74"}, {"sp": "N", "t": "δοκοῦσι δέ μοι καὶ τῶν δικασάντων τότε πολλοί· ἀκούω γὰρ αὐτὸν ἔγωγε μιᾷ μόνον ἁλῶναι ψήφῳ, καὶ ταῦτ’ οὔτε κλαύσαντ’ οὔτε δεηθέντα τῶν δικαστῶν οὐδενός, οὔτε φιλάνθρωπον οὔτε μικρὸν οὔτε μέγ’ οὐδ’ ὁτιοῦν πρὸς τοὺς δικαστὰς ποιήσαντα. θῶμεν τοίνυν οὑτωσί, τοὺς μὲν καταγνόντας αὐτοῦ μὴ ὅτι ἠμύνατο, διὰ τοῦτο καταψηφίσασθαι, ἀλλ’ ὅτι τοῦτον τὸν τρόπον ὥστε καὶ ἀποκτεῖναι, τοὺς δ’ ἀπογνόντας καὶ ταύτην τὴν ὑπερβολὴν τῆς τιμωρίας τῷ γε τὸ σῶμ’ ὑβρισμένῳ δεδωκέναι.", "st": "21.75"}, {"sp": "N", "t": "τί οὖν; ἐμοὶ τῷ τοσαύτῃ κεχρημένῳ προνοίᾳ τοῦ μηδὲν ἀνήκεστον γενέσθαι, ὥστε μηδ’ ἀμύνασθαι, παρὰ τοῦ τὴν τιμωρίαν ὧν πέπονθ’ ἀποδοθῆναι προσήκει; ἐγὼ μὲν οἶμαι παρ’ ὑμῶν καὶ τῶν νόμων, καὶ παράδειγμά γε πᾶσι γενέσθαι τοῖς ἄλλοις, ὅτι τοὺς ὑβρίζοντας ἅπαντας καὶ τοὺς ἀσελγεῖς οὐκ αὐτὸν ἀμύνεσθαι μετὰ τῆς ὀργῆς, ἀλλ’ ἐφ’ ὑμᾶς ἄγειν δεῖ, ὡς βεβαιούντων ὑμῶν καὶ φυλαττόντων τὰς ἐν τοῖς νόμοις τοῖς παθοῦσι βοηθείας.", "st": "21.76"}, {"sp": "N", "t": "οἶμαι τοίνυν τινὰς ὑμῶν, ὦ ἄνδρες δικασταί, ποθεῖν ἀκοῦσαι τὴν ἔχθραν, ἥτις ἦν ἡμῖν πρὸς ἀλλήλους· νομίζειν γὰρ οὐδέν’ ἂν ἀνθρώπων οὕτως ἀσελγῶς καὶ βιαίως οὐδενὶ τῶν πολιτῶν χρήσασθαι, μὴ μεγάλου τινὸς ὄντος ὃ αὐτῷ προωφείλετο. βούλομαι δὴ καὶ περὶ ταύτης ὑμῖν ἐξ ἀρχῆς εἰπεῖν καὶ διηγήσασθαι, ἵν’ εἰδῆθ’ ὅτι καὶ τούτων ὀφείλων δίκην φανήσεται. ἔσται δὲ βραχὺς περὶ αὐτῶν ὁ λόγος, κἂν ἄνωθεν ἄρχεσθαι δοκῶ.", "st": "21.77"}, {"sp": "N", "t": "ἡνίκα τὰς δίκας ἔλαχον τῶν πατρῴων τοῖς ἐπιτρόποις, μειρακύλλιον ὢν κομιδῇ καὶ τοῦτον οὐδ’ εἰ γέγον’ εἰδὼς οὐδὲ γιγνώσκων ὡς μηδὲ νῦν ὤφελον, τότε μοι μελλουσῶν εἰσιέναι τῶν δικῶν εἰς ἡμέραν ὡσπερεὶ τετάρτην ἢ πέμπτην εἰσεπήδησαν ἁδελφὸς ὁ τούτου καὶ οὗτος εἰς τὴν οἰκίαν ἀντιδιδόντες τριηραρχίαν. τοὔνομα μὲν δὴ παρέσχεν ἐκεῖνος, καὶ ἦν ὁ ἀντιδιδοὺς Θρασύλοχος· τὰ δ’ ἔργα πάντ’ ἦν καὶ τὰ πραττόμενα ὑπὸ τούτου.", "st": "21.78"}, {"sp": "N", "t": "καὶ πρῶτον μὲν κατέσχισαν τὰς θύρας τῶν οἰκημάτων, ὡς αὐτῶν ἤδη γιγνομένας κατὰ τὴν ἀντίδοσιν· εἶτα τῆς ἀδελφῆς, ἔτ’ ἔνδον [οὔσης] τότε καὶ παιδὸς οὔσης κόρης, ἐναντίον ἐφθέγγοντ’ αἰσχρὰ καὶ τοιαῦθ’ οἷ’ ἂν ἄνθρωποι τοιοῦτοι φθέγξαιντο (οὐ γὰρ ἔγωγε προαχθείην ἂν εἰπεῖν πρὸς ὑμᾶς τῶν τότε ῥηθέντων οὐδέν), καὶ τὴν μητέρα κἀμὲ καὶ πάντας ἡμᾶς ῥητὰ καὶ ἄρρητα κάκ’ ἐξεῖπον· ὃ δ’ οὖν δεινότατον καὶ οὐ λόγος, ἀλλ’ ἔργον ἤδη· τὰς δίκας ὡς αὐτῶν οὔσας ἀφίεσαν τοῖς ἐπιτρόποις.", "st": "21.79"}, {"sp": "N", "t": "καὶ ταῦτ’ ἐστὶ μὲν παλαιά, ὅμως δέ τινας μνημονεύειν ὑμῶν οἴομαι· ὅλη γὰρ ἡ πόλις τὴν ἀντίδοσιν καὶ τὴν ἐπιβουλὴν τότε ταύτην καὶ τὴν ἀσέλγειαν ᾔσθετο. κἀγὼ τότε παντάπασιν ἔρημος ὢν καὶ νέος κομιδῇ, ἵνα μὴ τῶν παρὰ τοῖς ἐπιτρόποις ἀποστερηθείην, οὐχ ὅσ’ ἐδυνήθην ἀνακομίσασθαι προσδοκῶν εἰσπράξειν, ἀλλ’ ὅσων ἐμαυτῷ συνῄδειν ἀπεστερημένῳ, δίδωμ’ εἴκοσι μνᾶς τούτοις, ὅσου τὴν τριηραρχίαν ἦσαν μεμισθωκότες. τὰ μὲν δὴ τόθ’ ὑβρίσματα τούτων εἰς ἐμὲ ταῦτ’ ἐστίν.", "st": "21.80"}, {"sp": "N", "t": "δίκην δὲ τούτῳ λαχὼν ὕστερον τῆς κακηγορίας εἷλον ἐρήμην· οὐ γὰρ ἀπήντα. λαβὼν δ’ ὑπερήμερον καὶ ἔχων, οὐδενὸς ἡψάμην πώποτε τῶν τούτου, ἀλλὰ λαχὼν ἐξούλης πάλιν οὐδέπω καὶ τήμερον εἰσελθεῖν δεδύνημαι· τοσαύτας τέχνας καὶ σκήψεις οὗτος εὑρίσκων ἐκκρούει. κἀγὼ μὲν οὕτως εὐλαβῶς τῇ δίκῃ, τοῖς νόμοις ἅπαντα πράττειν ἀξιῶ· ὁ δ’, ὡς ὑμεῖς ἀκούετε, ἀσελγῶς οὐ μόνον εἰς ἐμὲ καὶ τοὺς ἐμοὺς ᾤετο δεῖν ὑβρίζειν, ἀλλὰ καὶ εἰς τοὺς φυλέτας δι’ ἐμέ.", "st": "21.81"}, {"sp": "N", "t": "ὡς οὖν ταῦτ’ ἀληθῆ λέγω, κάλει μοι τούτων τοὺς μάρτυρας, ἵν’ εἰδῆθ’ ὅτι, πρὶν κατὰ τοὺς νόμους δίκην ὧν πρότερον ἠδικήθην λαβεῖν, πάλιν τοιαῦθ’ οἷ’ ἀκηκόαθ’ ὕβρισμαι.", "st": "21.82"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ", "st": "21.82"}, {"sp": "N", "t": "[Καλλισθένης Σφήττιος, Διόγνητος Θορίκιος, Μνησίθεος Ἀλωπεκῆθεν, οἴδαμεν Δημοσθένην, ᾧ μαρτυροῦμεν, κρίσιν λελογχότα Μειδίᾳ ἐξούλης, τῷ καὶ νῦν ὑπ’ αὐτοῦ κρινομένῳ δημοσίᾳ, καὶ ἤδη τῇ κρίσει ἐκείνῃ διαγεγονότα ἔτη ὀκτώ, καὶ τοῦ χρόνου γεγενημένον παντὸς αἴτιον Μειδίαν ἀεὶ προφασιζόμενον καὶ ἀναβαλλόμενον.]", "st": "21.82"}, {"sp": "N", "t": "ὃ τοίνυν πεποίηκεν, ὦ ἄνδρες Ἀθηναῖοι, περὶ τῆς δίκης, ἀκούσατε, καὶ θεωρεῖτ’ ἐφ’ ἑκάστου τὴν ὕβριν καὶ τὴν ὑπερηφανίαν αὐτοῦ. τῆς γὰρ δίκης, ταύτης λέγω ἧς εἷλον αὐτόν, γίγνεταί μοι διαιτητὴς Στράτων Φαληρεύς, ἄνθρωπος πένης μέν τις καὶ ἀπράγμων, ἄλλως δ’ οὐ πονηρός, ἀλλὰ καὶ πάνυ χρηστός· ὅπερ τὸν ταλαίπωρον οὐκ ὀρθῶς οὐδὲ δικαίως, ἀλλὰ καὶ πάνυ αἰσχρῶς ἀπολώλεκεν.", "st": "21.83"}, {"sp": "N", "t": "οὗτος διαιτῶν ἡμῖν ὁ Στράτων, ἐπειδή ποθ’ ἧκεν ἡ κυρία, πάντα δ’ ἤδη διεξεληλύθει ταῦτα τἀκ τῶν νόμων, ὑπωμοσίαι καὶ παραγραφαί, καὶ οὐδὲν ἔτ’ ἦν ὑπόλοιπον, τὸ μὲν πρῶτον ἐπισχεῖν ἐδεῖτό μου τὴν δίαιταν, ἔπειτ’ εἰς τὴν ὑστεραίαν ἀναβαλέσθαι· τὸ τελευταῖον δ’, ὡς οὔτ’ ἐγὼ συνεχώρουν οὔθ’ οὗτος ἀπήντα, τῆς δ’ ὥρας ἐγίγνετ’ ὀψέ, κατεδιῄτησεν.", "st": "21.84"}, {"sp": "N", "t": "ἤδη δ’ ἑσπέρας οὔσης καὶ σκότους ἔρχεται Μειδίας οὑτοσὶ πρὸς τὸ τῶν ἀρχόντων οἴκημα, καὶ καταλαμβάνει τοὺς ἄρχοντας ἐξιόντας καὶ τὸν Στράτων’ ἀπιόντ’ ἤδη, τὴν ἔρημον δεδωκότα, ὡς ἐγὼ τῶν παραγενομένων τινὸς ἐπυνθανόμην. τὸ μὲν οὖν πρῶτον οἷός τ’ ἦν πείθειν αὐτόν, ἣν κατεδεδιῃτήκει, ταύτην ἀποδεδιῃτημένην ἀποφαίνειν, καὶ τοὺς ἄρχοντας μεταγράφειν, καὶ πεντήκοντα δραχμὰς αὐτοῖς ἐδίδου·", "st": "21.85"}, {"sp": "N", "t": "ὡς δ’ ἐδυσχέραινον οὗτοι τὸ πρᾶγμα καὶ οὐδετέρους ἔπειθεν, ἀπειλήσας καὶ διαλοιδορηθεὶς ἀπελθὼν τί ποιεῖ; καὶ θεάσασθε τὴν κακοήθειαν. τὴν μὲν δίαιταν ἀντιλαχὼν οὐκ ὤμοσεν, ἀλλ’ εἴασε καθ’ αὑτοῦ κυρίαν γενέσθαι, καὶ ἀνώμοτος ἀπηνέχθη· βουλόμενος δὲ τὸ μέλλον λαθεῖν, φυλάξας τὴν τελευταίαν ἡμέραν τῶν διαιτητῶν, τὴν τοῦ θαργηλιῶνος ἢ τοῦ σκιροφοριῶνος γιγνομένην, εἰς ἣν ὁ μὲν ἦλθε τῶν διαιτητῶν,", "st": "21.86"}, {"sp": "N", "t": "ὁ δ’ οὐκ ἦλθε, πείσας τὸν πρυτανεύοντα δοῦναι τὴν ψῆφον παρὰ πάντας τοὺς νόμους, κλητῆρ’ οὐδ’ ὁντινοῦν ἐπιγραψάμενος, κατηγορῶν ἔρημον, οὐδενὸς παρόντος, ἐκβάλλει καὶ ἀτιμοῖ τὸν διαιτητήν· καὶ νῦν εἷς Ἀθηναίων, ὅτι Μειδίας ἔρημον ὦφλε δίκην, ἁπάντων ἀπεστέρηται τῶν ἐν τῇ πόλει καὶ καθάπαξ ἄτιμος γέγονεν· καὶ οὔτε λαχεῖν ἀδικηθέντα οὔτε διαιτητὴν γενέσθαι Μειδίᾳ οὔθ’ ὅλως τὴν αὐτὴν ὁδὸν βαδίζειν, ὡς ἔοικεν, ἔστ’ ἀσφαλές.", "st": "21.87"}, {"sp": "N", "t": "δεῖ δὴ τοῦτο τὸ πρᾶγμ’ ὑμᾶς οὑτωσὶ σκέψασθαι, καὶ λογίσασθαι τί ποτ’ ἔσθ’ ὃ παθὼν Μειδίας οὕτως ὠμὸν τηλικαύτην ἐπεβούλευσε λαβεῖν τῶν πεπραγμένων παρ’ ἀνδρὸς πολίτου δίκην, κἂν μὲν ᾖ τι δεινὸν ὡς ἀληθῶς καὶ ὑπερφυές, συγγνώμην ἔχειν, ἐὰν δὲ μηδέν, θεάσασθε τὴν ἀσέλγειαν καὶ τὴν ὠμότητα, ᾗ καθ’ ἁπάντων χρῆται τῶν ἐντυγχανόντων. τί οὖν ἔσθ’ ὃ πέπονθεν; μεγάλην νὴ Δί’ ὦφλε δίκην καὶ τοσαύτην ὥστ’ ἀποστερεῖσθαι τῶν ὄντων. ἀλλὰ χιλίων ἡ δίκη μόνον ἦν δραχμῶν.", "st": "21.88"}, {"sp": "N", "t": "πάνυ γε, ἀλλὰ δάκνει καὶ τοῦτο, φαίη τις ἄν, ὅταν ἐκτίνειν ἀδίκως δέῃ, συνέβη δ’ ὑπερημέρῳ γενομένῳ λαθεῖν αὐτῷ διὰ τὸ ἀδικηθῆναι. ἀλλ’ αὐθημερὸν μὲν ᾔσθετο, ὃ καὶ μέγιστόν ἐστι τεκμήριον τοῦ μηδὲν ἠδικηκέναι τὸν ἄνθρωπον, δραχμὴν δ’ οὐδέπω μίαν ἐκτέτεικεν.", "st": "21.89"}, {"sp": "N", "t": "ἀλλὰ μή πω τοῦτο. ἀλλὰ τὴν μὴ οὖσαν ἀντιλαχεῖν ἐξῆν αὐτῷ δήπου, καὶ πρὸς ἐμὲ τὸ πρᾶγμα καταστήσασθαι, πρὸς ὅνπερ ἐξ ἀρχῆς ἦν ἡ δίκη. ἀλλ’ οὐκ ἐβούλετο· ἀλλ’ ἵνα μὴ Μειδίας ἀτίμητον ἀγωνίσηται δέκα μνῶν δίκην, πρὸς ἣν οὐκ ἀπήντα δέον, καὶ εἰ μὲν ἠδίκηκε, δίκην δῷ, εἰ δὲ μή, ἀποφύγῃ, ἄτιμον Ἀθηναίων ἕν’ εἶναι δεῖ καὶ μήτε συγγνώμης μήτε λόγου μήτε ἐπιεικείας μηδεμιᾶς τυχεῖν, ἃ καὶ τοῖς ὄντως ἀδικοῦσιν ἅπανθ’ ὑπάρχει.", "st": "21.90"}, {"sp": "N", "t": "ἀλλ’ ἐπειδή γ’ ἠτίμωσεν ὃν ἐβουλήθη, καὶ τοῦτ’ ἐχαρίσασθ’ αὐτῷ, καὶ τὴν ἀναιδῆ γνώμην, ᾗ ταῦτα προαιρεῖται ποιεῖν, ἐνέπλησεν αὑτοῦ, ἐκεῖν’ ἐποίησε, τὴν καταδίκην ἐκτέτεικε, δι’ ἣν τὸν ἄνθρωπον ἀπώλεσεν; οὐδὲ χαλκοῦν οὐδέπω καὶ τήμερον, ἀλλὰ δίκην ἐξούλης ὑπομένει φεύγειν. οὐκοῦν ὁ μὲν ἠτίμωται καὶ παραπόλωλεν, ὁ δ’ οὐδ’ ὁτιοῦν πέπονθεν, ἀλλ’ ἄνω κάτω τοὺς νόμους, τοὺς διαιτητάς, πάνθ’ ὅσ’ ἂν βούληται στρέφει.", "st": "21.91"}, {"sp": "N", "t": "καὶ τὴν μὲν κατὰ τοῦ διαιτητοῦ γνῶσιν, ἣν ἀπρόσκλητον κατεσκεύασεν, αὐτὸς κυρίαν αὑτῷ πεποίηται· ἣν δ’ αὐτὸς ὦφλεν ἐμοὶ προσκληθείς, εἰδώς, οὐκ ἀπαντῶν, ἄκυρον ποιεῖ. καίτοι εἰ παρὰ τῶν ἔρημον καταδιαιτησάντων αὐτοῦ τηλικαύτην δίκην οὗτος ἀξιοῖ λαμβάνειν, τίν’ ὑμῖν προσήκει παρὰ τούτου λαβεῖν, τοῦ φανερῶς τοὺς ὑμετέρους νόμους ἐφ’ ὕβρει παραβαίνοντος; εἰ γὰρ ἀτιμία καὶ νόμων καὶ δικῶν καὶ πάντων στέρησις ἐκείνου τἀδικήματος προσήκουσ’ ἐστὶν δίκη, τῆς γ’ ὕβρεως μικρὰ θάνατος φαίνεται.", "st": "21.92"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἀληθῆ λέγω, κάλει μοι τούτων τοὺς μάρτυρας, καὶ τὸν τῶν διαιτητῶν ἀνάγνωθι νόμον.", "st": "21.93"}, {"sp": "N", "t": "Μάρτυρες", "st": "21.93"}, {"sp": "N", "t": "[Νικόστρατος Μυρρινούσιος, Φανίας Ἀφιδναῖος οἴδαμεν Δημοσθένην, ᾧ μαρτυροῦμεν, καὶ Μειδίαν τὸν κρινόμενον ὑπὸ Δημοσθένους, ὅτ’ αὐτῷ Δημοσθένης ἔλαχε τὴν τοῦ κακηγορίου δίκην, ἑλομένους διαιτητὴν Στράτωνα, καὶ ἐπεὶ ἧκεν ἡ κυρία τοῦ νόμου, οὐκ ἀπαντήσαντα Μειδίαν ἐπὶ τὴν δίαιταν, ἀλλὰ καταλιπόντα. γενομένης δὲ ἐρήμου κατὰ Μειδίου, ἐπιστάμεθα Μειδίαν πείθοντα τόν τε Στράτωνα τὸν διαιτητὴν καὶ ἡμᾶς, ὄντας ἐκείνοις τοῖς χρόνοις ἄρχοντας, ὅπως τὴν δίαιταν αὐτῷ ἀποδιαιτήσομεν, καὶ διδόντα δραχμὰς πεντήκοντα. καὶ ἐπειδὴ οὐχ ὑπεμείναμεν, προσαπειλήσαντα ἡμῖν καὶ οὕτως ἀπαλλαγέντα. καὶ διὰ ταύτην τὴν αἰτίαν ἐπιστάμεθα Στράτωνα ὑπὸ Μειδίου καταβραβευθέντα καὶ παρὰ πάντα τὰ δίκαια ἀτιμωθέντα.]", "st": "21.93"}, {"sp": "N", "t": "λέγε δὴ καὶ τὸν τῶν διαιτητῶν νόμον.", "st": "21.94"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "21.94"}, {"sp": "N", "t": "[Ἐὰν δέ τινες περὶ συμβολαίων ἰδίων πρὸς ἀλλήλους ἀμφισβητῶσι καὶ βούλωνται διαιτητὴν ἑλέσθαι ὁντινοῦν, ἐξέστω αὐτοῖς αἱρεῖσθαι ὃν ἂν βούλωνται [διαιτητὴν ἑλέσθαι]. ἐπειδὰν δ’ ἕλωνται κατὰ κοινόν, μενέτωσαν ἐν τοῖς ὑπὸ τούτου διαγνωσθεῖσι, καὶ μηκέτι μεταφερέτωσαν ἀπὸ τούτου ἐφ’ ἕτερον δικαστήριον ταὐτὰ ἐγκλήματα, ἀλλ’ ἔστω τὰ κριθέντα ὑπὸ τοῦ διαιτητοῦ κύρια.]", "st": "21.94"}, {"sp": "N", "t": "κάλει δὴ καὶ τὸν Στράτων’ αὐτὸν τὸν τὰ τοιαῦτα πεπονθότα· ἑστάναι γὰρ ἐξέσται δήπουθεν αὐτῷ.", "st": "21.95"}, {"sp": "N", "t": "οὗτος, ὦ ἄνδρες Ἀθηναῖοι, πένης μὲν ἴσως ἐστίν, οὐ πονηρὸς δέ γε. οὗτος μέντοι πολίτης ὤν, ἐστρατευμένος ἁπάσας τὰς ἐν ἡλικίᾳ στρατείας καὶ δεινὸν οὐδὲν εἰργασμένος, ἕστηκε νυνὶ σιωπῇ, οὐ μόνον τῶν ἄλλων ἀγαθῶν τῶν κοινῶν ἀπεστερημένος, ἀλλὰ καὶ τοῦ φθέγξασθαι ἢ ὀδύρασθαι· καὶ οὐδ’ εἰ δίκαι’ ἢ ἄδικα πέπονθεν, οὐδὲ ταῦτ’ ἔξεστιν αὐτῷ πρὸς ὑμᾶς εἰπεῖν.", "st": "21.95"}, {"sp": "N", "t": "καὶ ταῦτα πέπονθ’ ὑπὸ Μειδίου καὶ τοῦ Μειδίου πλούτου καὶ τῆς ὑπερηφανίας παρὰ τὴν πενίαν καὶ ἐρημίαν καὶ τὸ τῶν πολλῶν εἷς εἶναι. καὶ εἰ μὲν παραβὰς τοὺς νόμους ἔλαβεν τὰς πεντήκοντα δραχμὰς παρ’ αὐτοῦ, καὶ τὴν δίκην ἣν κατεδιῄτησεν ἀποδεδιῃτημένην ἀπέφηνεν, ἐπίτιμος ἂν ἦν καὶ οὐδὲν ἔχων κακὸν τῶν ἴσων μετεῖχε τοῖς ἄλλοις ἡμῖν· ἐπειδὴ δὲ παρεῖδε πρὸς τὰ δίκαια Μειδίαν, καὶ τοὺς νόμους μᾶλλον ἔδεισε τῶν ἀπειλῶν τῶν τούτου, τηνικαῦτα τηλικαύτῃ καὶ τοιαύτῃ συμφορᾷ περιπέπτωκεν ὑπὸ τούτου.", "st": "21.96"}, {"sp": "N", "t": "εἶθ’ ὑμεῖς τὸν οὕτως ὠμόν, τὸν οὕτως ἀγνώμονα, τὸν τηλικαύτας δίκας λαμβάνονθ’ ὧν αὐτὸς ἠδικῆσθαι φησὶ μόνον (οὐ γὰρ ἠδίκητό γε), τοῦτον ὑβρίζοντα λαβόντες εἴς τινα τῶν πολιτῶν [ἀφήσετε], καὶ μήθ’ ἑορτῆς μήθ’ ἱερῶν μήτε νόμου μήτ’ ἄλλου μηδενὸς πρόνοιαν ποιούμενον, οὐ καταψηφιεῖσθε;", "st": "21.97"}, {"sp": "N", "t": "οὐ παράδειγμα ποιήσετε; καὶ τί φήσετ’, ὦ ἄνδρες δικασταί; καὶ τίν’, ὢ πρὸς τῶν θεῶν, ἕξετ’ εἰπεῖν πρόφασιν δικαίαν ἢ καλήν; ὅτι νὴ Δί’ ἀσελγής ἐστι καὶ βδελυρός· ταῦτα γάρ ἐστι τἀληθῆ· ἀλλὰ μισεῖν ὀφείλετ’, ἄνδρες Ἀθηναῖοι, δήπου τοὺς τοιούτους μᾶλλον ἢ σῴζειν. ἀλλ’ ὅτι πλούσιός ἐστιν· ἀλλὰ τοῦτό γε τῆς ὕβρεως αὐτοῦ σχεδὸν αἴτιον εὑρήσετ’ ὄν, ὥστ’ ἀφελεῖν τὴν ἀφορμήν, δι’ ἣν ὑβρίζει, προσήκει μᾶλλον ἢ σῶσαι διὰ ταύτην· τὸ γὰρ χρημάτων πολλῶν θρασὺν καὶ βδελυρὸν καὶ τοιοῦτον ἄνθρωπον ἐᾶν εἶναι κύριον, ἀφορμήν ἐστιν ἐφ’ ὑμᾶς αὐτοὺς δεδωκέναι.", "st": "21.98"}, {"sp": "N", "t": "τί οὖν ὑπόλοιπον; ἐλεῆσαι νὴ Δία· παιδία γὰρ παραστήσεται καὶ κλαήσει καὶ τούτοις αὑτὸν ἐξαιτήσεται· τοῦτο γὰρ λοιπόν. ἀλλ’ ἴστε δήπου τοῦθ’ ὅτι τοὺς ἀδίκως τι πάσχοντας, ὃ μὴ δυνήσονται φέρειν, ἐλεεῖν προσήκει, οὐ τοὺς ὧν πεποιήκασι δεινῶν δίκην διδόντας. καὶ τίς ἂν ταῦτ’ ἐλεήσειε δικαίως, ὁρῶν τὰ τοῦδ’ οὐκ ἐλεηθένθ’ ὑπὸ τούτου, ἃ τῇ τοῦ πατρὸς συμφορᾷ χωρὶς τῶν ἄλλων κακῶν οὐδ’ ἐπικουρίαν ἐνοῦσαν ὁρᾷ. οὐ γάρ ἐστιν ὄφλημ’ ὅ τι χρὴ καταθέντ’ ἐπίτιμον γενέσθαι τουτονί, ἀλλ’ ἁπλῶς οὕτως ἠτίμωται τῇ ῥύμῃ τῆς ὀργῆς καὶ τῆς ὕβρεως τῆς Μειδίου.", "st": "21.99"}, {"sp": "N", "t": "τίς οὖν ὑβρίζων παύσεται καὶ δι’ ἃ ταῦτα ποιεῖ χρήματ’ ἀφαιρεθήσεται, εἰ τοῦτον ὥσπερ δεινὰ πάσχοντ’ ἐλεήσετε; εἰ δέ τις πένης μηδὲν ἠδικηκὼς ταῖς ἐσχάταις συμφοραῖς ἀδίκως ὑπὸ τούτου περιπέπτωκε, τούτῳ δ’ οὐδὲ συνοργισθήσεσθε; μηδαμῶς· οὐδεὶς γάρ ἐστι δίκαιος τυγχάνειν ἐλέου τῶν μηδέν’ ἐλεούντων, οὐδὲ συγγνώμης τῶν ἀσυγγνωμόνων.", "st": "21.100"}, {"sp": "N", "t": "ἐγὼ γὰρ οἶμαι πάντας ἀνθρώπους φέρειν ἀξιοῦν παρ’ ἑαυτῶν εἰς τὸν βίον αὑτοῖς ἔρανον παρὰ πάνθ’ ὅσα πράττουσιν· οἷον ἐγώ τις οὑτοσὶ μέτριος πρὸς ἅπαντάς εἰμ’, ἐλεήμων, εὖ ποιῶν πολλούς· ἅπασι προσήκει τῷ τοιούτῳ ταὔτ’ εἰσφέρειν, ἐάν του καιρὸς ἢ χρεία παραστῇ. ἕτερος οὑτοσί τις βίαιος, οὐδέν’ οὔτ’ ἐλεῶν οὔθ’ ὅλως ἄνθρωπον ἡγούμενος· τούτῳ τὰς ὁμοίας φορὰς παρ’ ἑκάστου δίκαιον ὑπάρχειν. σὺ δή, πληρωτὴς τοιούτου γεγονὼς ἐράνου σεαυτῷ, τοῦτον δίκαιος εἶ συλλέξασθαι.", "st": "21.101"}, {"sp": "N", "t": "ἡγοῦμαι μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ εἰ μηδὲν ἔτ’ ἄλλ’ εἶχον κατηγορεῖν Μειδίου, μηδὲ δεινότερ’ ἦν ἃ μέλλω λέγειν ὧν εἴρηκα, δικαίως ἂν ὑμᾶς ἐκ τῶν εἰρημένων καὶ καταψηφίσασθαι καὶ τιμᾶν αὐτῷ τῶν ἐσχάτων. οὐ μὴν ἐνταῦθ’ ἕστηκε τὸ πρᾶγμα, οὐδ’ ἀπορήσειν μοι δοκῶ τῶν μετὰ ταῦτα· τοσαύτην ἀφθονίαν οὗτος πεποίηκε κατηγοριῶν.", "st": "21.102"}, {"sp": "N", "t": "ὅτι μὲν δὴ λιποταξίου γραφὴν κατεσκεύασεν κατ’ ἐμοῦ καὶ τὸν τοῦτο ποιήσοντ’ ἐμισθώσατο, τὸν μιαρὸν καὶ λίαν εὐχερῆ, τὸν κονιορτὸν Εὐκτήμονα, ἐάσω. καὶ γὰρ οὔτ’ ἀνεκρίνατο ταύτην ὁ συκοφάντης ἐκεῖνος, οὔθ’ οὗτος οὐδενὸς εἵνεκ’ αὐτὸν ἐμισθώσατο πλὴν ἵν’ ἐκκέοιτο πρὸ τῶν ἐπωνύμων καὶ πάντες ὁρῷεν “Εὐκτήμων Λουσιεὺς ἐγράψατο Δημοσθένην Παιανιέα λιποταξίου·” καί μοι δοκεῖ κἂν προσγράψαι τοῦθ’ ἡδέως, εἴ πως ἐνῆν, ὅτι Μειδίου μισθωσαμένου γέγραπται. ἀλλ’ ἐῶ τοῦτο· ἐφ’ ᾗ γὰρ ἐκεῖνος ἠτίμωκεν αὑτὸν οὐκ ἐπεξελθών, οὐδεμιᾶς ἔγωγ’ ἔτι προσδέομαι δίκης, ἀλλ’ ἱκανὴν ἔχω.", "st": "21.103"}, {"sp": "N", "t": "ἀλλ’ ὃ καὶ δεινόν, ὦ ἄνδρες Ἀθηναῖοι, καὶ σχέτλιον καὶ κοινὸν ἔμοιγ’ ἀσέβημα, οὐκ ἀδίκημα μόνον, τούτῳ πεπρᾶχθαι δοκεῖ, τοῦτ’ ἐρῶ. τῷ γὰρ ἀθλίῳ καὶ ταλαιπώρῳ κακῆς καὶ χαλεπῆς συμβάσης αἰτίας Ἀριστάρχῳ τῷ Μόσχου, τὸ μὲν πρῶτον, ὦ ἄνδρες Ἀθηναῖοι, κατὰ τὴν ἀγορὰν περιιὼν ἀσεβεῖς καὶ δεινοὺς λόγους ἐτόλμα περὶ ἐμοῦ λέγειν, ὡς ἐγὼ τὸ πρᾶγμ’ εἰμὶ τοῦτο δεδρακώς· ὡς δ’ οὐδὲν ἤνυε τούτοις, προσελθὼν τοῖς ἐπ’ ἐκεῖνον ἄγουσι τὴν αἰτίαν τοῦ φόνου, τοῖς τοῦ τετελευτηκότος οἰκείοις, χρήμαθ’ ὑπισχνεῖτο δώσειν εἰ τοῦ πράγματος αἰτιῷντ’ ἐμέ, καὶ οὔτε θεοὺς οὔθ’ ὁσίαν οὔτ’ ἄλλ’ οὐδὲν ἐποιήσατ’ ἐμποδὼν τοιούτῳ λόγῳ, οὐδ’ ὤκνησεν.", "st": "21.104"}, {"sp": "N", "t": "ἀλλ’ οὐδὲ πρὸς οὓς ἔλεγεν αὐτοὺς ᾐσχύνθη, εἰ τοιοῦτο κακὸν καὶ τηλικοῦτον ἀδίκως ἐπάγει τῳ, ἀλλ’ ἕν’ ὅρον θέμενος παντὶ τρόπῳ μ’ ἀνελεῖν, οὐδὲν ἐλλείπειν ᾤετο δεῖν, ὡς δέον, εἴ τις ὑβρισθεὶς ὑπὸ τούτου δίκης ἀξιοῖ τυχεῖν καὶ μὴ σιωπᾷ, τοῦτον ἐξόριστον ἀνῃρῆσθαι καὶ μηδαμῇ παρεθῆναι, ἀλλὰ καὶ λιποταξίου γραφὴν ἑαλωκέναι καὶ ἐφ’ αἵματι φεύγειν καὶ μόνον οὐ προσηλῶσθαι. καίτοι ταῦθ’ ὅταν ἐξελεγχθῇ ποιῶν πρὸς οἷς ὕβριζέν με χορηγοῦντα, τίνος συγγνώμης ἢ τίνος ἐλέου δικαίως τεύξεται παρ’ ὑμῶν;", "st": "21.105"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ αὐτόν, ὦ ἄνδρες Ἀθηναῖοι, νομίζω αὐτόχειρά μου γεγενῆσθαι τούτοις τοῖς ἔργοις, καὶ τότε μὲν τοῖς Διονυσίοις τὴν παρασκευὴν καὶ τὸ σῶμα καὶ τἀναλώμαθ’ ὑβρίζειν, νῦν δὲ τούτοις οἷς ἐποίει καὶ διεπράττετ’ ἐκεῖνά τε καὶ τὰ λοιπὰ πάντα, τὴν πόλιν, τὸ γένος, τὴν ἐπιτιμίαν, τὰς ἐλπίδας· εἰ γὰρ ἓν ὧν ἐπεβούλευσε κατώρθωσεν, ἁπάντων ἂν ἀπεστερήμην ἐγὼ καὶ μηδὲ ταφῆναι προσυπῆρχεν οἴκοι μοι. διὰ τί, ἄνδρες δικασταί; εἰ γάρ, ἐάν τις παρὰ πάντας τοὺς νόμους ὑβρισθεὶς ὑπὸ Μειδίου βοηθεῖν αὑτῷ πειρᾶται, ταῦτα καὶ τοιαῦθ’ ἕτερ’ αὐτῷ παθεῖν ὑπάρξει, προσκυνεῖν τοὺς ὑβρίζοντας ὥσπερ ἐν τοῖς βαρβάροις, οὐκ ἀμύνεσθαι κράτιστον ἔσται.", "st": "21.106"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἀληθῆ λέγω καὶ προσεξείργασται ταῦτα τῷ βδελυρῷ τούτῳ καὶ ἀναιδεῖ, κάλει μοι καὶ τούτων τοὺς μάρτυρας.", "st": "21.107"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ", "st": "21.107"}, {"sp": "N", "t": "[Διονύσιος Ἀφιδναῖος, Ἀντίφιλος Παιανιεὺς διαφθαρέντος Νικοδήμου τοῦ οἰκείου ἡμῶν βιαίῳ θανάτῳ ὑπὸ Ἀριστάρχου τοῦ Μόσχου ἐπεξῇμεν τοῦ φόνου τὸν Ἀρίσταρχον. αἰσθόμενος δὲ ταῦτα Μειδίας ὁ νῦν κρινόμενος ὑπὸ Δημοσθένους, ᾧ μαρτυροῦμεν, ἔπειθεν ἡμᾶς διδοὺς κέρματα τὸν μὲν Ἀρίσταρχον ἀθῷον ἀφεῖναι, Δημοσθένει δὲ τὴν γραφὴν τοῦ φόνου παραγράψασθαι.]", "st": "21.107"}, {"sp": "N", "t": "λαβὲ δή μοι τὸν περὶ τῶν δώρων νόμον.", "st": "21.107"}, {"sp": "N", "t": "ἐν ὅσῳ δὲ τὸν νόμον, ὦ ἄνδρες Ἀθηναῖοι, λαμβάνει, βούλομαι μικρὰ πρὸς ὑμᾶς εἰπεῖν, δεηθεὶς ὑμῶν ἁπάντων πρὸς Διὸς καὶ θεῶν, ὦ ἄνδρες δικασταί· περὶ πάντων ὧν ἂν ἀκούητε, τοῦθ’ ὑποθέντες ἀκούετε τῇ γνώμῃ, τί ἄν, εἴ τις ἔπασχε ταῦθ’ ὑμῶν, ἐποίει, καὶ τίν’ ἂν εἶχεν ὀργὴν ὑπὲρ αὑτοῦ πρὸς τὸν ποιοῦντα. ἐγὼ γὰρ ἐνηνοχὼς χαλεπῶς ἐφ’ οἷς περὶ τὴν λῃτουργίαν ὑβρίσθην, ἔτι πολλῷ χαλεπώτερον, ὦ ἄνδρες Ἀθηναῖοι, τούτοις τοῖς μετὰ ταῦτ’ ἐνήνοχα καὶ μᾶλλον ἠγανάκτηκα.", "st": "21.108"}, {"sp": "N", "t": "τί γὰρ ὡς ἀληθῶς πέρας ἂν φήσειέ τις εἶναι κακίας καὶ τίν’ ὑπερβολὴν ἀναιδείας καὶ ὠμότητος καὶ ὕβρεως, ἄνθρωπος εἰ ποιήσας δεινὰ νὴ Δία καὶ πόλλ’ ἀδίκως τινά, ἀντὶ τοῦ ταῦτ’ ἀναλαμβάνειν καὶ μεταγιγνώσκειν, πολλῷ δεινότερ’ ὕστερον ἄλλα προσεξεργάζοιτο, καὶ χρῷτο τῷ πλουτεῖν μὴ ἐπὶ ταῦτ’ ἐν οἷς μηδένα βλάπτων αὐτὸς ἄμεινόν τι τῶν ἰδίων θήσεται, ἀλλ’ ἐπὶ τἀναντία, ἐν οἷς ἀδίκως ἐκβάλλων τινὰ καὶ προπηλακίσας αὑτὸν εὐδαιμονιεῖ τῆς περιουσίας;", "st": "21.109"}, {"sp": "N", "t": "ταῦτα τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, πάντα τούτῳ πέπρακται κατ’ ἐμοῦ. καὶ γὰρ αἰτίαν ἐπήγαγέ μοι φόνου ψευδῆ καὶ οὐδὲν ἐμοὶ προσήκουσαν, ὡς τὸ πρᾶγμ’ αὔτ’ ἐδήλωσεν, καὶ γραφὴν λιποταξίου μ’ ἐγράψατο τρεῖς αὐτὸς τάξεις λελοιπώς, καὶ τῶν ἐν Εὐβοίᾳ πραγμάτων (τουτὶ γὰρ αὖ μικροῦ παρῆλθέ μ’ εἰπεῖν), ἃ Πλούταρχος ὁ τούτου ξένος καὶ φίλος διεπράξατο, ὡς ἐγὼ αἴτιός εἰμι, κατεσκεύαζε πρὸ τοῦ τὸ πρᾶγμα γενέσθαι πᾶσιν φανερὸν διὰ Πλουτάρχου γεγονός.", "st": "21.110"}, {"sp": "N", "t": "καὶ τελευτῶν βουλεύειν μου λαχόντος δοκιμαζομένου κατηγόρει, καὶ τὸ πρᾶγμ’ εἰς ὑπέρδεινόν μοι περιέστη· ἀντὶ γὰρ τοῦ δίκην ὑπὲρ ὧν ἐπεπόνθειν λαβεῖν, δοῦναι πραγμάτων ὧν οὐδὲν ἐμοὶ προσῆκεν ἐκινδύνευον. καὶ ταῦτα πάσχων ἐγὼ καὶ τοῦτον τὸν τρόπον ὃν διεξέρχομαι νυνὶ πρὸς ὑμᾶς ἐλαυνόμενος, οὐκ ὢν οὔτε τῶν ἐρημοτάτων οὔτε τῶν ἀπόρων κομιδῇ, οὐκ ἔχω, ὦ ἄνδρες Ἀθηναῖοι, τί χρὴ ποιῆσαι.", "st": "21.111"}, {"sp": "N", "t": "εἰ γὰρ εἰπεῖν τι καὶ περὶ τούτων ἤδη δεῖ, οὐ μέτεστι τῶν ἴσων οὐδὲ τῶν ὁμοίων, ὦ ἄνδρες Ἀθηναῖοι, πρὸς τοὺς πλουσίους τοῖς λοιποῖς ἡμῖν, οὐ μέτεστιν, οὔ· ἀλλὰ καὶ χρόνοι τούτοις τοῦ τὴν δίκην ὑποσχεῖν, οὓς ἂν αὐτοὶ βούλωνται, δίδονται, καὶ τἀδικήμαθ’ ἕωλα τὰ τούτων ὡς ὑμᾶς καὶ ψύχρ’ ἀφικνεῖται, τῶν δ’ ἄλλων ἡμῶν ἕκαστος, ἄν τι συμβῇ, πρόσφατος κρίνεται. καὶ μάρτυρές εἰσιν ἕτοιμοι τούτοις καὶ συνήγοροι πάντες καθ’ ἡμῶν εὐτρεπεῖς· ἐμοὶ δ’ οὐδὲ τἀληθῆ μαρτυρεῖν ἐθέλοντας ὁρᾶτ’ ἐνίους.", "st": "21.112"}, {"sp": "N", "t": "ταῦτα μὲν οὖν ἀπείποι τις ἄν, οἶμαι, θρηνῶν. τὸν δὲ νόμον μοι λέγ’ ἐφεξῆς, ὥσπερ ἠρξάμην. λέγε.", "st": "21.113"}, {"sp": "N", "t": "ΝΟΜΟΣ", "st": "21.113"}, {"sp": "N", "t": "ἐάν τις Ἀθηναίων λαμβάνῃ παρά τινος, ἢ αὐτὸς διδῷ ἑτέρῳ, ἢ διαφθείρῃ τινὰς ἐπαγγελλόμενος, ἐπὶ βλάβῃ τοῦ δήμου ἢ ἰδίᾳ τινὸς τῶν πολιτῶν, τρόπῳ ἢ μηχανῇ ᾑτινιοῦν, ἄτιμος ἔστω καὶ παῖδες καὶ τὰ ἐκείνου.", "st": "21.113"}, {"sp": "N", "t": "οὕτω τοίνυν οὗτός ἐστ’ ἀσεβὴς καὶ μιαρὸς καὶ πᾶν ἂν ὑποστὰς εἰπεῖν καὶ πρᾶξαι, εἰ δ’ ἀληθὲς ἢ ψεῦδος ἢ πρὸς ἐχθρὸν ἢ φίλον ἢ τὰ τοιαῦτα, ἀλλ’ οὐδ’ ὁτιοῦν διορίζων, ὥστ’ ἐπαιτιασάμενός με φόνου καὶ τοιοῦτο πρᾶγμ’ ἐπαγαγών, εἴασε μέν μ’ εἰσιτητήρι’ ὑπὲρ τῆς βουλῆς ἱεροποιῆσαι καὶ θῦσαι καὶ κατάρξασθαι τῶν ἱερῶν ὑπὲρ ὑμῶν καὶ ὅλης τῆς πόλεως,", "st": "21.114"}, {"sp": "N", "t": "εἴασε δ’ ἀρχεθεωροῦντ’ ἀγαγεῖν τῷ Διὶ τῷ Νεμείῳ τὴν κοινὴν ὑπὲρ τῆς πόλεως θεωρίαν, περιεῖδε δὲ ταῖς σεμναῖς θεαῖς ἱεροποιὸν αἱρεθέντ’ ἐξ Ἀθηναίων ἁπάντων τρίτον αὐτὸν καὶ καταρξάμενον τῶν ἱερῶν. ἆρ’ ἄν, εἴ γ’ εἶχε στιγμὴν ἢ σκιὰν τούτων ὧν κατεσκεύαζεν κατ’ ἐμοῦ, ταῦτ’ ἂν εἴασεν; ἐγὼ μὲν οὐκ οἶμαι. οὐκοῦν ἐξελέγχεται τούτοις ἐναργῶς ὕβρει ζητῶν μ’ ἐκβάλλειν ἐκ τῆς πατρίδος.", "st": "21.115"}, {"sp": "N", "t": "ἐπειδὴ τοίνυν τοῦτο τὸ πρᾶγμ’ οὐδὲ καθ’ ἕν, πανταχῇ στρέφων, οἷός τ’ ἦν ἀγαγεῖν ἐπ’ ἐμέ, φανερῶς ἤδη δι’ ἐμὲ τὸν Ἀρίσταρχον ἐσυκοφάντει. καὶ τὰ μὲν ἄλλα σιωπῶ· τῆς δὲ βουλῆς περὶ τούτων καθημένης καὶ σκοπουμένης, παρελθὼν οὗτος “ἀγνοεῖτ’” ἔφη “ὦ βουλή, τὸ πρᾶγμα; καὶ τὸν αὐτόχειρ’ ἔχοντες” λέγων τὸν Ἀρίσταρχον “μέλλετε καὶ ζητεῖτε καὶ τετύφωσθε; οὐκ ἀποκτενεῖτε; οὐκ ἐπὶ τὴν οἰκίαν βαδιεῖσθε;”", "st": "21.116"}, {"sp": "N", "t": "“οὐχὶ συλλήψεσθε;” καὶ ταῦτ’ ἔλεγ’ ἡ μιαρὰ καὶ ἀναιδὴς αὕτη κεφαλή, ἐξεληλυθὼς τῇ προτεραίᾳ παρ’ Ἀριστάρχου, καὶ χρώμενος ὥσπερ ἂν ἄλλος τις τὰ πρὸ τούτου, καί, ὅτ’ ηὐτύχει, πλεῖστα παρεσχηκότος ἐκείνου πράγματά μοι περὶ τῶν πρὸς τοῦτον ἀπαλλαγῶν. εἰ μὲν οὖν εἰργάσθαι τι τούτων ἐφ’ οἷς ἀπόλωλεν ἡγούμενος τὸν Ἀρίσταρχον καὶ πεπιστευκὼς τοῖς τῶν αἰτιασαμένων λόγοις ταῦτ’ ἔλεγεν,", "st": "21.117"}, {"sp": "N", "t": "χρῆν μὲν οὐδ’ οὕτω (μετρία γὰρ δίκη παρὰ τῶν φίλων ἐστίν, ἄν τι δοκῶσι πεποιηκέναι δεινόν, μηκέτι τῆς λοιπῆς φιλίας κοινωνεῖν, τὸ δὲ τιμωρεῖσθαι καὶ ἐπεξιέναι τοῖς πεπονθόσι καὶ τοῖς ἐχθροῖς παραλείπεται)· ὅμως δ’ ἔστω τούτῳ γε συγγνώμη. εἰ δὲ λαλῶν μὲν καὶ ὁμωρόφιος γιγνόμενος ὡς οὐδὲν εἰργασμένῳ φανήσεται, λέγων δὲ καὶ καταιτιώμενος ταῦθ’ εἵνεκα τοῦ συκοφαντεῖν ἐμέ, πῶς οὐ δεκάκις, μᾶλλον δὲ μυριάκις δίκαιός ἐστ’ ἀπολωλέναι;", "st": "21.118"}, {"sp": "N", "t": "ἀλλὰ μὴν ὡς ἀληθῆ λέγω καὶ τῇ μὲν προτεραίᾳ ὅτε ταῦτ’ ἔλεγεν, εἰσεληλύθει καὶ διείλεκτ’ ἐκείνῳ, τῇ δ’ ὑστεραίᾳ πάλιν (τοῦτο γάρ, τοῦτ’ οὐκ ἔχον ἐστὶν ὑπερβολὴν ἀκαθαρσίας, ἄνδρες Ἀθηναῖοι) εἰσελθὼν οἴκαδ’ ὡς ἐκεῖνον καὶ ἐφεξῆς οὑτωσὶ καθεζόμενος, τὴν δεξιὰν ἐμβαλών, παρόντων πολλῶν, μετὰ τοὺς ἐν τῇ βουλῇ τούτους λόγους, ἐν οἷς αὐτόχειρα καὶ τὰ δεινότατ’ εἰρήκει τὸν Ἀρίσταρχον, ὤμνυε μὲν κατ’ ἐξωλείας μηδὲν εἰρηκέναι κατ’ αὐτοῦ φλαῦρον, καὶ οὐδὲν ἐφρόντιζ’ ἐπιορκῶν, καὶ ταῦτα παρόντων τῶν συνειδότων, ἠξίου δὲ καὶ πρὸς ἔμ’ αὑτῷ δι’ ἐκείνου γίγνεσθαι τὰς διαλύσεις, τούτων τοὺς παρόντας ὑμῖν καλῶ μάρτυρας.", "st": "21.119"}, {"sp": "N", "t": "καίτοι πῶς οὐ δεινόν, ὦ ἄνδρες Ἀθηναῖοι, μᾶλλον δ’ ἀσεβές, λέγειν ὡς φονεύς, καὶ πάλιν ὡς οὐκ εἴρηκε ταῦτ’ ἀπομνύναι, καὶ φόνον μὲν ὀνειδίζειν, τούτῳ δ’ ὁμωρόφιον γίγνεσθαι; κἂν μὲν ἀφῶ τοῦτον ἐγὼ καὶ προδῶ τὴν ὑμετέραν καταχειροτονίαν, οὐδέν, ὡς ἔοικ’, ἀδικῶ· ἂν δ’ ἐπεξίω, λέλοιπα τὴν τάξιν, φόνον κοινωνῶ, δεῖ μ’ ἀνηρπάσθαι. ἐγὼ δ’ αὐτὸ τοὐναντίον οἶμαι, εἰ τοῦτον ἀφῆκα, λελοιπέναι μέν, ὦ ἄνδρες Ἀθηναῖοι, τὴν τοῦ δικαίου τάξιν, φόνου δ’ ἂν εἰκότως ἐμαυτῷ λαχεῖν· οὐ γὰρ ἦν μοι δήπου βιωτὸν τοῦτο ποιήσαντι.", "st": "21.120"}, {"sp": "N", "t": "ὅτι τοίνυν καὶ ταῦτ’ ἀληθῆ λέγω, κάλει μοι καὶ τούτων τοὺς μάρτυρας.", "st": "21.121"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ", "st": "21.121"}, {"sp": "N", "t": "[Λυσίμαχος Ἀλωπεκῆθεν, Δημέας Σουνιεύς, Χάρης Θορίκιος, Φιλήμων Σφήττιος, Μόσχος Παιανιεύς, καθ’ οὓς καιροὺς ἡ εἰσαγγελία ἐδόθη εἰς τὴν βουλὴν ὑπὲρ Ἀριστάρχου τοῦ Μόσχου, ὅτι εἴη Νικόδημον ἀπεκτονώς, οἴδαμεν Μειδίαν τὸν κρινόμενον ὑπὸ Δημοσθένους, ᾧ μαρτυροῦμεν, ἐλθόντα πρὸς τὴν βουλὴν καὶ λέγοντα μηδένα ἕτερον εἶναι τὸν Νικοδήμου φονέα, ἀλλ’ Ἀρίσταρχον, καὶ τοῦτον αὐτοῦ γεγονέναι αὐτόχειρα, καὶ συμβουλεύοντα τῇ βουλῇ βαδίζειν ἐπὶ τὴν οἰκίαν τὴν Ἀριστάρχου καὶ συλλαμβάνειν αὐτόν. ταῦτα δ’ ἔλεγε πρὸς τὴν βουλὴν τῇ προτεραίᾳ μετ’ Ἀριστάρχου καὶ μεθ’ ἡμῶν συνδεδειπνηκώς. οἴδαμεν δὲ καὶ Μειδίαν, ὡς ἀπῆλθεν ἀπὸ τῆς βουλῆς τούτους τοὺς λόγους εἰρηκώς, εἰσεληλυθότα πάλιν ὡς Ἀρίσταρχον καὶ τὴν δεξιὰν [ὡς] ἐμβεβληκότα καὶ ὀμνύοντα κατ’ ἐξωλείας μηδὲν κατ’ αὐτοῦ πρὸς τὴν βουλὴν εἰρηκέναι φαῦλον, καὶ ἀξιοῦντα Ἀρίσταρχον ὅπως ἂν διαλλάξῃ αὐτῷ Δημοσθένην.]", "st": "21.121"}, {"sp": "N", "t": "τίς οὖν ὑπερβολή, τίς ὁμοία τῇ τούτου γέγον’ ἢ γένοιτ’ ἂν πονηρία; ὃς ἄνδρ’ ἀτυχοῦντα, οὐδὲν αὐτὸν ἠδικηκότα (ἐῶ γὰρ εἰ φίλον), ἅμα συκοφαντεῖν ᾤετο δεῖν καὶ πρὸς ἔμ’ αὑτὸν διαλύειν ἠξίου, καὶ ταῦτ’ ἔπραττε καὶ χρήματ’ ἀνήλισκεν ἐπὶ τῷ μετ’ ἐκείνου κἀμὲ προσεκβαλεῖν ἀδίκως.", "st": "21.122"}, {"sp": "N", "t": "τοῦτο μέντοι τὸ τοιοῦτον ἔθος καὶ τὸ κατασκεύασμ’, ὦ ἄνδρες Ἀθηναῖοι, τὸ τοῖς ὑπὲρ αὑτῶν ἐπεξιοῦσι δικαίως ἔτι πλείω περιιστάναι κακά, οὐκ ἐμοὶ μὲν ἄξιόν ἐστ’ ἀγανακτεῖν καὶ βαρέως φέρειν, ὑμῖν δὲ τοῖς ἄλλοις παριδεῖν, πολλοῦ γε καὶ δεῖ, ἀλλὰ πᾶσιν ὁμοίως ὀργιστέον, ἐκλογιζομένοις καὶ θεωροῦσιν ὅτι τοῦ μέν, ὦ ἄνδρες Ἀθηναῖοι, ῥᾳδίως κακῶς παθεῖν ἐγγύταθ’ ὑμῶν εἰσιν οἱ πενέστατοι καὶ ἀσθενέστατοι, τοῦ δ’ ὑβρίσαι καὶ τοῦ ποιήσαντας μὴ δοῦναι δίκην, ἀλλὰ τοὺς ἀντιπαρέξοντας πράγματα μισθώσασθαι, οἱ βδελυροὶ καὶ χρήματ’ ἔχοντές [εἰσιν ἐγγυτάτω].", "st": "21.123"}, {"sp": "N", "t": "οὐ δὴ δεῖ παρορᾶν τὰ τοιαῦτα, οὐδὲ τὸν ἐξείργοντα δέει καὶ φόβῳ τὸ δίκην ὧν ἂν ἡμῶν ἀδικηθῇ τις λαμβάνειν παρ’ αὐτοῦ ἄλλο τι χρὴ νομίζειν ποιεῖν ἢ τὰς τῆς ἰσηγορίας καὶ τὰς τῆς ἐλευθερίας ἡμῶν μετουσίας ἀφαιρεῖσθαι. ἐγὼ μὲν γὰρ ἴσως διεωσάμην, καὶ ἄλλος τις ἄν, ψευδῆ λόγον καὶ συκοφαντίαν, καὶ οὐκ ἀνήρπασμαι· οἱ δὲ πολλοὶ τί ποιήσετε, ἂν μὴ δημοσίᾳ πᾶσιν φοβερὸν καταστήσητε τὸ εἰς ταῦτ’ ἀποχρῆσθαι τῷ πλουτεῖν;", "st": "21.124"}, {"sp": "N", "t": "δόντα λόγον καὶ ὑποσχόντα κρίσιν περὶ ὧν ἄν τις ἐγκαλῇ, τότ’ ἀμύνεσθαι τοὺς [ἀδίκως] ἐφ’ αὑτὸν ἐλθόντας χρή, καὶ τότ’, ἂν ἀδικοῦντας ὁρᾷ τις, οὐ προαναρπάζειν, οὐδ’ ἐπάγοντ’ αἰτίας ψευδεῖς ἄκριτον ζητεῖν ἀποφεύγειν, οὐδ’ ἐπὶ τῷ διδόναι δίκην ἀσχάλλειν, ἀλλὰ μὴ ποιεῖν ἐξ ἀρχῆς ἀσελγὲς μηδέν.", "st": "21.125"}, {"sp": "N", "t": "ὅσα μὲν τοίνυν εἴς τε τὴν λῃτουργίαν καὶ τὸ σῶμ’ ὑβρίσθην, καὶ πάντ’ ἐπιβουλευόμενος τρόπον καὶ πάσχων κακῶς ἐκπέφευγα, ἀκηκόατ’, ὦ ἄνδρες Ἀθηναῖοι. καὶ παραλείπω δὲ πολλά· οὐ γὰρ ἴσως ῥᾴδιον πάντ’ εἰπεῖν. ἔχει δ’ οὕτως. οὐκ ἔστ’ ἐφ’ ὅτῳ τῶν πεπραγμένων ἐγὼ μόνος ἠδίκημαι, ἀλλ’ ἐπὶ μὲν τοῖς εἰς τὸν χορὸν γεγενημένοις ἀδικήμασιν ἡ φυλή, δέκατον μέρος ὑμῶν, συνηδίκηται, ἐπὶ δ’ οἷς ἔμ’ ὕβρισε καὶ ἐπεβούλευσεν οἱ νόμοι, δι’ οὓς εἷς ἕκαστος ὑμῶν σῶς ἐστιν· ἐφ’ ἅπασι δὲ τούτοις ὁ θεός, ᾧ χορηγὸς ἐγὼ καθειστήκειν, καὶ τὸ τῆς ὁσίας, ὁτιδήποτ’ ἐστί, τὸ σεμνὸν καὶ τὸ δαιμόνιον [συνηδίκηται].", "st": "21.126"}, {"sp": "N", "t": "δεῖ δὴ τούς γε βουλομένους ὀρθῶς τὴν κατ’ ἀξίαν τῶν πεπραγμένων παρὰ τούτου δίκην λαμβάνειν, οὐχ ὡς ὑπὲρ ἐμοῦ μόνον ὄντος τοῦ λόγου τὴν ὀργὴν ἔχειν, ἀλλ’ ὡς ἐν ταὐτῷ τῶν νόμων, τοῦ θεοῦ, τῆς πόλεως, ὁμοῦ πάντων ἠδικημένων, οὕτω ποιεῖσθαι τὴν τιμωρίαν, καὶ τοὺς βοηθοῦντας καὶ τοὺς συνεξεταζομένους μετὰ τούτου μὴ συνηγόρους μόνον, ἀλλὰ καὶ δοκιμαστὰς τῶν τούτῳ πεπραγμένων ὑπολαμβάνετ’ εἶναι.", "st": "21.127"}, {"sp": "N", "t": "εἰ μὲν τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, σώφρονα καὶ μέτριον πρὸς τἄλλα παρεσχηκὼς αὑτὸν Μειδίας καὶ μηδένα τῶν ἄλλων πολιτῶν ἠδικηκὼς εἰς ἔμ’ ἀσελγὴς μόνον οὕτω καὶ βίαιος ἐγεγόνει, πρῶτον μὲν ἔγωγ’ ἀτύχημ’ ἂν ἐμαυτοῦ τοῦθ’ ἡγούμην, ἔπειτ’ ἐφοβούμην ἂν μὴ τὸν ἄλλον ἑαυτοῦ βίον οὗτος μέτριον δεικνύων καὶ φιλάνθρωπον διακρούσηται τούτῳ τὸ δίκην ὧν ἔμ’ ὕβρικεν δοῦναι.", "st": "21.128"}, {"sp": "N", "t": "νυνὶ δὲ τοσαῦτ’ ἐστὶ τἄλλ’ ἃ πολλοὺς ὑμῶν ἠδίκησεν καὶ τοιαῦτα, ὥστε τούτου μὲν τοῦ δέους ἀπήλλαγμαι, φοβοῦμαι δὲ πάλιν τοὐναντίον μή, ἐπειδὰν πολλὰ καὶ δείν’ ἑτέρους ἀκούηθ’ ὑπ’ αὐτοῦ πεπονθότας, τοιοῦτός τις ὑμῖν λογισμὸς ἐμπέσῃ “τί οὖν; σὺ δεινότερ’ ἢ τῶν ἄλλων εἷς ἕκαστος πεπονθὼς ἀγανακτεῖς;” πάντα μὲν δὴ τὰ τούτῳ πεπραγμένα οὔτ’ ἂν ἐγὼ δυναίμην πρὸς ὑμᾶς εἰπεῖν, οὔτ’ ἂν ὑμεῖς ὑπομείναιτ’ ἀκούειν, οὐδ’, εἰ τὸ παρ’ ἀμφοτέρων ἡμῶν ὕδωρ ὑπάρξειε πρὸς τὸ λοιπόν, πᾶν τό τ’ ἐμὸν καὶ τὸ τούτου προστεθέν, οὐκ ἂν ἐξαρκέσειεν· ἃ δ’ ἐστὶ μέγιστα καὶ φανερώτατα, ταῦτ’ ἐρῶ.", "st": "21.129"}, {"sp": "N", "t": "μᾶλλον δ’ ἐκεῖνο ποιήσω· ἀναγνώσομαι μὲν ὑμῖν, ὡς ἐμαυτῷ γέγραμμαι, πάντα τὰ ὑπομνήματα, λέξω δ’ ὅ τι ἂν πρῶτον ἀκούειν βουλομένοις ὑμῖν ᾖ, τοῦτο πρῶτον, εἶθ’ ἕτερον, καὶ τἄλλα τὸν αὐτὸν τρόπον, ἕως ἂν ἀκούειν βούλησθε. ἔστι δὲ ταῦτα παντοδαπά, καὶ ὕβρεις πολλαὶ καὶ περὶ τοὺς οἰκείους κακουργήματα καὶ περὶ τοὺς θεοὺς ἀσεβήματα, καὶ τόπος οὐδείς ἐστιν ἐν ᾧ τοῦτον οὐ θανάτου πεποιηκότ’ ἄξια πόλλ’ εὑρήσετε.", "st": "21.130"}, {"sp": "N", "t": "ΥΠΟΜΝΗΜΑΤΑ ΤΩ͂Ν ΜΕΙΔΙΟΥ ΑΔΙΚΗΜΑΤΩΝ", "st": "21.130"}, {"sp": "N", "t": "ὅσα μὲν τοίνυν, ὦ ἄνδρες δικασταί, τὸν ἀεὶ προστυχόντ’ αὐτῷ πεποίηκεν, ταῦτ’ ἐστίν. καὶ παραλέλοιφ’ ἕτερα· οὐ γὰρ ἂν δύναιτ’ οὐδεὶς εἰσάπαξ εἰπεῖν ἃ πολὺν χρόνον οὗτος ὑβρίζων συνεχῶς ἅπαντα τὸν βίον εἴργασται. ἄξιον δ’ ἰδεῖν ἐφ’ ὅσον φρονήματος ἤδη προελήλυθε τῷ τούτων δίκην μηδενὸς δεδωκέναι. οὐ γὰρ ἡγεῖθ’, ὡς ἐμοὶ δοκεῖ, λαμπρὸν οὐδὲ νεανικὸν οὐδ’ ἄξιον ἑαυτοῦ ὅ τι ἄν τις πρὸς ἕν’ εἷς διαπράττηται, ἀλλ’ εἰ μὴ φυλὴν ὅλην καὶ βουλὴν καὶ ἔθνος προπηλακιεῖ καὶ πολλοὺς ἁθρόους ὑμῶν ἅμ’ ἐλᾷ, ἀβίωτον ᾤετ’ ἔσεσθαι τὸν βίον αὑτῷ.", "st": "21.131"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλα σιωπῶ, μυρί’ εἰπεῖν ἔχων, περὶ δὲ τῶν συστρατευσαμένων ἱππέων εἰς Ἄργουραν ἴστε δήπου πάντες οἷ’ ἐδημηγόρησε παρ’ ὑμῖν, ὅθ’ ἧκεν ἐκ Χαλκίδος, κατηγορῶν καὶ φάσκων ὄνειδος ἐξελθεῖν τὴν στρατιὰν ταύτην τῇ πόλει· καὶ τὴν λοιδορίαν ἣν ἐλοιδορήθη Κρατίνῳ περὶ τούτων, τῷ νῦν, ὡς ἐγὼ πυνθάνομαι, μέλλοντι βοηθεῖν αὐτῷ, μέμνησθε. τὸν δὴ τοσούτοις ἁθρόοις τῶν πολιτῶν ἔχθραν ἐπ’ οὐδενὶ τηλικαύτην ἀράμενον πόσῃ πονηρίᾳ καὶ θρασύτητι ταῦτα χρὴ νομίζειν πράττειν;", "st": "21.132"}, {"sp": "N", "t": "καίτοι πότερ’ εἰσὶν ὄνειδος, ὦ Μειδία, τῇ πόλει οἱ διαβάντες ἐν τάξει καὶ τὴν σκευὴν ἔχοντες ἣν προσῆκε τοὺς ἐπὶ τοὺς πολεμίους ἐξιόντας καὶ συμβαλουμένους τοῖς συμμάχοις, ἢ σὺ ὁ μηδὲ λαχεῖν εὐχόμενος τῶν ἐξιόντων ὅτ’ ἐκληροῦ, τὸν θώρακα δ’ οὐδεπώποτ’ ἐνδύς, ἐπ’ ἀστράβης δ’ ὀχούμενος ἀργυρᾶς τῆς ἐξ Εὐβοίας, χλανίδας δὲ καὶ κυμβία καὶ κάδους ἔχων, ὧν ἐπελαμβάνονθ’ οἱ πεντηκοστολόγοι; ταῦτα γὰρ εἰς τοὺς ὁπλίτας ἡμᾶς ἀπηγγέλλετο· οὐ γὰρ εἰς ταὐτὸν ἡμεῖς τούτοις διέβημεν.", "st": "21.133"}, {"sp": "N", "t": "εἶτα, εἴ σ’ ἐπὶ τούτοις ἔσκωψεν Ἀρχετίων ἤ τις ἄλλος, πάντας ἤλαυνες; εἰ μὲν γὰρ ἐποίεις ταῦτ’, ὦ Μειδία, ἃ σέ φασιν οἱ συνιππεῖς καὶ κατηγόρεις ὡς λέγοιεν περὶ σοῦ, δικαίως κακῶς ἤκουες· καὶ γὰρ ἐκείνους καὶ τουτουσὶ καὶ ὅλην τὴν πόλιν ἠδίκεις καὶ κατῄσχυνες. εἰ δὲ μὴ ποιοῦντός σου κατεσκεύαζόν τινες καταψευδόμενοί σου, οἱ δὲ λοιποὶ τῶν στρατιωτῶν οὐκ ἐκείνοις ἐπετίμων, ἀλλὰ σοὶ ἐπέχαιρον, δῆλον ὅτι ἐκ τῶν ἄλλων ὧν ἔζης ἄξιος αὐτοῖς ἐδόκεις εἶναι τοῦ τοιαῦτ’ ἀκούειν· σαυτὸν οὖν μετριώτερον ἐχρῆν παρέχειν, οὐκ ἐκείνους διαβάλλειν.", "st": "21.134"}, {"sp": "N", "t": "σὺ δ’ ἀπειλεῖς πᾶσιν, ἐλαύνεις πάντας· τοὺς ἄλλους ἀξιοῖς ὅ τι σὺ βούλει σκοπεῖν, οὐκ αὐτὸς σκοπεῖς ὅ τι μὴ λυπήσεις τοὺς ἄλλους ποιῶν. καὶ τὸ δὴ σχετλιώτατον καὶ μέγιστον ἔμοιγε δοκοῦν ὕβρεως εἶναι σημεῖον· τοσούτων ἀνθρώπων, ὦ μιαρὰ κεφαλή, σὺ παρελθὼν ἁθρόων κατηγόρεις, ὃ τίς οὐκ ἂν ἔφριξε ποιῆσαι τῶν ἄλλων;", "st": "21.135"}, {"sp": "N", "t": "τοῖς μὲν τοίνυν ἄλλοις ἅπασιν ἀνθρώποις ὁρῶ τοῖς κρινομένοις, ὦ ἄνδρες δικασταί, ἓν μὲν ἢ δύ’ ὄντα τἀδικήμαθ’ ἃ κατηγορεῖται, λόγους δ’ ἀφθόνους τοιούτους ὑπάρχοντας “τίς ὑμῶν ἐμοί τι σύνοιδε τοιοῦτον; τίς ὑμῶν ἐμὲ ταῦθ’ ἑόρακε ποιοῦντα; οὐκ ἔστιν, ἀλλ’ οὗτοι δι’ ἔχθραν καταψεύδονταί μου, καταψευδομαρτυροῦμαι,” τὰ τοιαῦτα· τούτῳ δ’ αὖ τἀναντία τούτων.", "st": "21.136"}, {"sp": "N", "t": "πάντας γὰρ ὑμᾶς εἰδέναι νομίζω τὸν τρόπον καὶ τὴν ἀσέλγειαν καὶ τὴν ὑπερηφανίαν τοῦ βίου, καὶ πάλαι θαυμάζειν ἐνίους οἴομαι ὧν αὐτοὶ μὲν ἴσασιν, οὐκ ἀκηκόασι δὲ νῦν ἐμοῦ. πολλοὺς δὲ τῶν πεπονθότων οὐδὲ πάνθ’ ὅσ’ ἠδίκηνται μαρτυρεῖν ἐθέλοντας ὁρῶ, τὴν βίαν καὶ τὴν φιλοπραγμοσύνην ὁρῶντας τὴν τούτου καὶ τὴν ἀφορμήν, ἥπερ ἰσχυρὸν ποιεῖ καὶ φοβερὸν τὸν κατάπτυστον τουτονί.", "st": "21.137"}, {"sp": "N", "t": "τὸ γὰρ ἐπ’ ἐξουσίας καὶ πλούτου πονηρὸν εἶναι καὶ ὑβριστὴν τεῖχός ἐστι πρὸς τὸ μηδὲν ἂν αὐτὸν ἐξ ἐπιδρομῆς παθεῖν, ἐπεὶ περιαιρεθεὶς οὗτος τὰ ὄντα ἴσως μὲν οὐκ ἂν ὑβρίζοι, εἰ δ’ ἄρα, ἐλάττονος ἄξιος ἔσται τοῦ μικροτάτου παρ’ ὑμῖν· μάτην γὰρ λοιδορήσεται καὶ βοήσεται, δίκην δ’, ἂν ἀσελγαίνῃ τι, τοῖς ἄλλοις ἡμῖν ἐξ ἴσου δώσει.", "st": "21.138"}, {"sp": "N", "t": "νῦν δ’, οἶμαι, τούτου προβέβληται Πολύευκτος, Τιμοκράτης, Εὐκτήμων ὁ κονιορτός· τοιοῦτοί τινές εἰσι μισθοφόροι περὶ αὐτόν, καὶ πρὸς ἔθ’ ἕτεροι τούτοις, μαρτύρων συνεστῶσ’ ἑταιρεία, φανερῶς μὲν οὐκ ἐνοχλούντων ὑμῖν, σιγῇ δὲ τὰ ψευδῆ ῥᾷστ’ ἐπινευόντων. οὓς μὰ τοὺς θεοὺς οὐδὲν ὠφελεῖσθαι νομίζω παρὰ τούτου· ἀλλὰ δεινοί τινές εἰσιν, ὦ ἄνδρες Ἀθηναῖοι, φθείρεσθαι πρὸς τοὺς πλουσίους καὶ παρεῖναι καὶ μαρτυρεῖν.", "st": "21.139"}, {"sp": "N", "t": "πάντα δὲ ταῦτ’, οἶμαι, φοβέρ’ ἐστὶ τῶν ἄλλων ὑμῶν ἑκάστῳ καθ’ ἑαυτὸν ὅπως δύναται ζῶντι. οὗπερ εἵνεκα συλλέγεσθ’ ὑμεῖς, ἵν’, ὧν καθ’ ἕν’ ἐστὶν ἕκαστος ὑμῶν ἐλάττων ἢ φίλοις ἢ τοῖς οὖσιν ἢ τῶν ἄλλων τινί, τούτων συλλεγέντες ἑκάστου κρείττους τε γίγνησθε καὶ παύητε τὴν ὕβριν.", "st": "21.140"}, {"sp": "N", "t": "τάχα τοίνυν καὶ τοιοῦτός τις ἥξει πρὸς ὑμᾶς λόγος, “τί δὴ τὰ καὶ τὰ πεπονθὼς ὁ δεῖν’ οὐκ ἐλάμβανεν δίκην παρ’ ἐμοῦ;” ἢ “τί δὴ” πάλιν ἄλλον ἴσως τινὰ τῶν ἠδικημένων ὀνομάζων. ἐγὼ δὲ δι’ ἃς μὲν προφάσεις ἕκαστος ἀφίσταται τοῦ βοηθεῖν αὑτῷ, πάντας ὑμᾶς εἰδέναι νομίζω· καὶ γὰρ ἀσχολία καὶ ἀπραγμοσύνη καὶ τὸ μὴ δύνασθαι λέγειν καὶ ἀπορία καὶ μυρί’ ἐστὶν αἴτια·", "st": "21.141"}, {"sp": "N", "t": "προσήκειν μέντοι τούτῳ μὴ ταῦτα λέγειν ἡγοῦμαι νυνί, ἀλλ’ ὡς οὐ πεποίηκέ τι τούτων ὧν αὐτοῦ κατηγόρηκα διδάσκειν, ἐὰν δὲ μὴ δύνηται, διὰ ταῦτ’ ἀπολωλέναι πολὺ μᾶλλον, εἰ γὰρ τηλικοῦτός τίς ἐστιν ὥστε τοιαῦτα ποιῶν δύνασθαι καθ’ ἕν’ ἕκαστον ἡμῶν ἀποστερεῖν τοῦ δίκης παρ’ αὐτοῦ τυχεῖν, κοινῇ νῦν, ἐπειδήπερ εἴληπται, πᾶσιν ὑπὲρ ἁπάντων ἐστὶ τιμωρητέος ὡς κοινὸς ἐχθρὸς τῇ πολιτείᾳ.", "st": "21.142"}, {"sp": "N", "t": "λέγεται τοίνυν ποτ’ ἐν τῇ πόλει κατὰ τὴν παλαιὰν ἐκείνην εὐδαιμονίαν Ἀλκιβιάδης γενέσθαι, ᾧ σκέψασθε τίνων ὑπαρχόντων καὶ ποίων τινῶν πρὸς τὸν δῆμον πῶς ἐχρήσανθ’ ὑμῶν οἱ πρόγονοι, ἐπειδὴ βδελυρὸς καὶ ὑβριστὴς ᾤετο δεῖν εἶναι. καὶ οὐκ ἀπεικάσαι δήπου Μειδίαν Ἀλκιβιάδῃ βουλόμενος τούτου μέμνημαι τοῦ λόγου (οὐχ οὕτως εἴμ’ ἄφρων οὐδ’ ἀπόπληκτος ἐγώ), ἀλλ’ ἵν’ εἰδῆθ’ ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, καὶ γνῶθ’ ὅτι οὐδὲν οὔτ’ ἔστιν οὔτ’ ἔσται, οὐ γένος, οὐ πλοῦτος, οὐ δύναμις, ὅ τι τοῖς πολλοῖς ὑμῖν, ἂν ὕβρις προσῇ, προσήκει φέρειν.", "st": "21.143"}, {"sp": "N", "t": "ἐκεῖνος γάρ, ὦ ἄνδρες Ἀθηναῖοι, λέγεται πρὸς πατρὸς μὲν Ἀλκμεωνιδῶν εἶναι (τούτους δέ φασιν ὑπὸ τῶν τυράννων ὑπὲρ τοῦ δήμου στασιάζοντας ἐκπεσεῖν, καὶ δανεισαμένους χρήματ’ ἐκ Δελφῶν ἐλευθερῶσαι τὴν πόλιν καὶ τοὺς Πεισιστράτου παῖδας ἐκβαλεῖν), πρὸς δὲ μητρὸς Ἱππονίκου καὶ ταύτης τῆς οἰκίας ἧς ὑπάρχουσι πολλαὶ καὶ μεγάλαι πρὸς τὸν δῆμον εὐεργεσίαι.", "st": "21.144"}, {"sp": "N", "t": "οὐ μόνον δὲ ταῦθ’ ὑπῆρχεν αὐτῷ, ἀλλὰ καὶ αὐτὸς ὑπὲρ τοῦ δήμου θέμενος τὰ ὅπλα δὶς μὲν ἐν Σάμῳ, τρίτον δ’ ἐν αὐτῇ τῇ πόλει, τῷ σώματι τὴν εὔνοιαν, οὐ χρήμασιν οὐδὲ λόγοις ἐνεδείξατο τῇ πατρίδι. ἔτι δ’ ἵππων Ὀλυμπίασιν ἀγῶνες ὑπῆρχον αὐτῷ καὶ νῖκαι καὶ στέφανοι, καὶ στρατηγὸς ἄριστος, καὶ λέγειν ἐδόκει πάντων, ὥς φασιν, εἶναι δεινότατος.", "st": "21.145"}, {"sp": "N", "t": "ἀλλ’ ὅμως οἱ κατ’ ἐκεῖνον ὑμέτεροι πρόγονοι οὐδενὸς τούτων αὐτῷ συνεχώρησαν ὑβρίζειν αὑτούς, ἀλλὰ ποιήσαντες φυγάδ’ ἐξέβαλον· καὶ Λακεδαιμονίων ὄντων ἰσχυρῶν τότε, καὶ Δεκέλειαν ἑαυτοῖς ἐπιτειχισθῆναι καὶ τὰς ναῦς ἁλῶναι καὶ πάνθ’ ὑπέμειναν, ὁτιοῦν ἄκοντες παθεῖν κάλλιον εἶναι νομίζοντες ἢ ἑκόντες ὑβρίζεσθαι συγχωρῆσαι.", "st": "21.146"}, {"sp": "N", "t": "καίτοι τί τοσοῦτον ἐκεῖνος ὕβρισεν, ἡλίκον οὗτος νῦν ἐξελήλεγκται; Ταυρέαν ἐπάταξε χορηγοῦντ’ ἐπὶ κόρρης. ἔστω ταῦτα, ἀλλὰ χορηγῶν γε χορηγοῦντα τοῦτ’ ἐποίησεν, οὔπω τόνδε τὸν νόμον παραβαίνων· οὐ γὰρ ἔκειτό πω. εἷρξεν Ἀγάθαρχον τὸν γραφέα· καὶ γὰρ ταῦτα λέγουσιν. λαβὼν γέ τι πλημμελοῦνθ’ ὥς φασιν· ὅπερ οὐδ’ ὀνειδίζειν ἄξιον. τοὺς Ἑρμᾶς περιέκοπτεν. ἅπαντα μέν, οἶμαι, τἀσεβήματα τῆς αὐτῆς ὀργῆς δίκαιον ἀξιοῦν· τὸ δ’ ὅλως ἀφανίζειν ἱερὰ ἔσθ’ ὅ τι τοῦ κόπτειν [τοὺς Ἑρμᾶς] διαφέρει· οὐκοῦν οὗτος ἐξελήλεγκται τοῦτο ποιῶν.", "st": "21.147"}, {"sp": "N", "t": "ἀντιθῶμεν δὴ τίς ὢν καὶ τίσι ταῦτ’ ἐνδεικνύμενος. μὴ τοίνυν ὑμῖν, πρὸς τῷ μὴ καλόν, μηδὲ θεμιτὸν νομίζετ’, ἄνδρες δικασταί, μηδ’ ὅσιον εἶναι τοιούτων ἀνδρῶν οὖσιν ἀπογόνοις, πονηρὸν καὶ βίαιον καὶ ὑβριστὴν λαβοῦσιν ἄνθρωπον καὶ μηδένα μηδαμόθεν, συγγνώμης ἢ φιλανθρωπίας ἢ χάριτός τινος ἀξιῶσαι. τίνος γὰρ εἵνεκα; τῶν στρατηγιῶν· ἀλλ’ οὐδὲ καθ’ αὑτὸν στρατιώτης οὗτος οὐδενός ἐστ’ ἄξιος, μή τί γε τῶν ἄλλων ἡγεμών. ἀλλὰ τῶν λόγων· ἐν οἷς κοινῇ μὲν οὐδὲν πώποτ’ εἶπ’ ἀγαθόν, κακῶς δ’ ἰδίᾳ πάντας ἀνθρώπους λέγει.", "st": "21.148"}, {"sp": "N", "t": "γένους εἵνεκα νὴ Δία· καὶ τίς οὐκ οἶδεν ὑμῶν τὰς ἀπορρήτους, ὥσπερ ἐν τραγῳδίᾳ, τὰς τούτου γονάς; ᾧ δύ’ ἐναντιώτατα συμβέβηκεν εἶναι· ἡ μὲν γὰρ ὡς ἀληθῶς μήτηρ, ἡ τεκοῦσ’ αὐτόν, πλεῖστον ἁπάντων ἀνθρώπων εἶχε νοῦν, ἡ δὲ δοκοῦσα καὶ ὑποβαλομένη πασῶν ἦν ἀνοητοτάτη γυναικῶν. σημεῖον δέ· ἡ μὲν γὰρ ἀπέδοτ’ εὐθὺς γενόμενον, ἡ δ’ ἐξὸν αὐτῇ βελτίω πρίασθαι τῆς αὐτῆς τιμῆς τοῦτον ἠγόρασεν.", "st": "21.149"}, {"sp": "N", "t": "καὶ γάρ τοι διὰ τοῦτο τῶν οὐ προσηκόντων ἀγαθῶν κύριος γεγονώς, καὶ πατρίδος τετυχηκὼς ἣ νόμοις τῶν ἁπασῶν πόλεων μάλιστ’ οἰκεῖσθαι δοκεῖ, οὐδέν’ οἶμαι τρόπον φέρειν οὐδὲ χρῆσθαι τούτοις δύναται, ἀλλὰ τὸ τῆς φύσεως ὡς ἀληθῶς βάρβαρον καὶ θεοῖς ἐχθρὸν ἕλκει καὶ βιάζεται, καὶ φανερὸν ποιεῖ τοῖς παροῦσιν ὥσπερ ἀλλοτρίοις, ὅπερ ἔστιν, αὐτὸν χρώμενον.", "st": "21.150"}, {"sp": "N", "t": "τοσούτων τοίνυν καὶ τοιούτων ὄντων ἃ τῷ βδελυρῷ τούτῳ καὶ ἀναιδεῖ βεβίωται, ἔνιοί μοι προσιόντες, ὦ ἄνδρες δικασταί, τῶν χρωμένων αὐτῷ, παραινοῦντες ἀπαλλαγῆναι καὶ καθυφεῖναι τὸν ἀγῶνα τουτονί, ἐπειδή με μὴ πείθοιεν, ὡς μὲν οὐ πολλὰ καὶ δεινὰ πεποίηκεν οὗτος καὶ δίκην ἡντινοῦν ἂν δοίη δικαίως τῶν πεπραγμένων, οὐκ ἐτόλμων λέγειν, ἐπὶ ταῦτα δ’ ἀπήντων ὡς “ἑάλωκεν ἤδη καὶ κατεψήφισται· τίνος τιμήσειν αὐτῷ προσδοκᾷς τὸ δικαστήριον; οὐχ ὁρᾷς ὅτι πλουτεῖ καὶ τριηραρχίας ἐρεῖ καὶ λῃτουργίας; σκόπει δὴ μὴ τούτοις αὑτὸν ἐξαιτήσηται, καὶ ἐλάττω πολὺ τῇ πόλει καταθεὶς ἢ ὅσα σοι δίδωσι καταγελάσῃ.”", "st": "21.151"}, {"sp": "N", "t": "ἐγὼ δὲ πρῶτον μὲν οὐδὲν ἀγεννὲς ὑμῶν καταγιγνώσκω, οὐδ’ ὑπολαμβάνω τιμήσειν οὐδὲν ἐλάττονος τούτῳ ἢ ὅσον καταθεὶς οὗτος παύσεται τῆς ὕβρεως· τοῦτο δ’ ἐστὶ μάλιστα μὲν θάνατος, εἰ δὲ μή, πάντα τὰ ὄντ’ ἀφελέσθαι. ἔπειθ’ ὑπὲρ τῶν τούτου λῃτουργιῶν καὶ τῶν τριηραρχιῶν καὶ τῶν τοιούτων λόγων ὡδὶ γιγνώσκω.", "st": "21.152"}, {"sp": "N", "t": "εἰ μέν ἐστιν, ὦ ἄνδρες Ἀθηναῖοι, τὸ λῃτουργεῖν τοῦτο, τὸ ἐν ὑμῖν λέγειν ἐν ἁπάσαις ταῖς ἐκκλησίαις καὶ πανταχοῦ “ἡμεῖς οἱ λῃτουργοῦντες, ἡμεῖς οἱ προεισφέροντες ὑμῖν, ἡμεῖς οἱ πλούσιοί ἐσμεν,” εἰ τὸ τὰ τοιαῦτα λέγειν, τοῦτ’ ἔστιν λῃτουργεῖν, ὁμολογῶ Μειδίαν ἁπάντων τῶν ἐν τῇ πόλει λαμπρότατον γεγενῆσθαι· ἀποκναίει γὰρ ἀηδίᾳ δήπου καὶ ἀναισθησίᾳ καθ’ ἑκάστην τὴν ἐκκλησίαν ταῦτα λέγων.", "st": "21.153"}, {"sp": "N", "t": "εἰ μέντοι τί ποτ’ ἐστὶν ἃ λῃτουργεῖ τῇ ἀληθείᾳ δεῖ σκοπεῖν, ἐγὼ πρὸς ὑμᾶς ἐρῶ· καὶ θεάσασθ’ ὡς δικαίως αὐτὸν ἐξετάσω, πρὸς ἐμαυτὸν κρίνων. οὗτος, ὦ ἄνδρες Ἀθηναῖοι, γεγονὼς ἔτη περὶ πεντήκοντ’ ἴσως ἢ μικρὸν ἔλαττον οὐδὲν ἐμοῦ πλείους λῃτουργίας ὑμῖν λελῃτούργηκεν, ὃς δύο καὶ τριάκοντ’ ἔτη γέγονα. κἀγὼ μὲν κατ’ ἐκείνους τοὺς χρόνους ἐτριηράρχουν, εὐθὺς ἐκ παίδων ἐξελθών, ὅτε σύνδυ’ ἦμεν οἱ τριήραρχοι καὶ τἀναλώματα πάντ’ ἐκ τῶν ἰδίων [οἴκων] καὶ τὰς ναῦς ἐπληρούμεθ’ αὐτοί·", "st": "21.154"}, {"sp": "N", "t": "οὗτος δέ, ὅτε μὲν κατὰ ταύτην τὴν ἡλικίαν ἦν ἣν ἐγὼ νῦν, οὐδέπω λῃτουργεῖν ἤρχετο, τηνικαῦτα δὲ τοῦ πράγματος ἧπται, ὅτε πρῶτον μὲν διακοσίους καὶ χιλίους πεποιήκατε συντελεῖς ὑμεῖς, παρ’ ὧν εἰσπραττόμενοι τάλαντον ταλάντου μισθοῦσι τὰς τριηραρχίας οὗτοι, εἶτα πληρώμαθ’ ἡ πόλις παρέχει καὶ σκεύη δίδωσιν, ὥστ’ αὐτῶν ἐνίοις τῇ ἀληθείᾳ τὸ μηδὲν ἀναλῶσαι καὶ δοκεῖν λελῃτουργηκέναι καὶ τῶν ἄλλων λῃτουργιῶν ἀτελεῖς γεγενῆσθαι περίεστιν.", "st": "21.155"}, {"sp": "N", "t": "ἀλλὰ μὴν τί ἄλλο; τραγῳδοῖς κεχορήγηκέ ποθ’ οὗτος, ἐγὼ δ’ αὐληταῖς ἀνδράσιν. καὶ ὅτι τοῦτο τἀνάλωμ’ ἐκείνης τῆς δαπάνης πλέον ἐστὶ πολλῷ, οὐδεὶς ἀγνοεῖ δήπου. κἀγὼ μὲν ἐθελοντὴς νῦν, οὗτος δὲ καταστὰς ἐξ ἀντιδόσεως τότε, οὗ χάριν οὐδεμίαν δήπου δικαίως ἄν τις ἔχοι. τί ἔτι; εἱστίακα τὴν φυλὴν ἐγὼ καὶ Παναθηναίοις κεχορήγηκα, οὗτος δ’ οὐδέτερα.", "st": "21.156"}, {"sp": "N", "t": "ἡγεμὼν συμμορίας ὑμῖν ἐγενόμην ἐγὼ ἔτη δέκα, ἴσον Φορμίωνι καὶ Λυσιθείδῃ καὶ Καλλαίσχρῳ καὶ τοῖς πλουσιωτάτοις, εἰσφέρων οὐκ ἀφ’ ὑπαρχούσης οὐσίας (ὑπὸ γὰρ τῶν ἐπιτρόπων ἀπεστερήμην), ἀλλ’ ἀπὸ τῆς δόξης ὧν ὁ πατήρ μοι κατέλιπεν καὶ ὧν δίκαιον ἦν με δοκιμασθέντα κομίσασθαι. ἐγὼ μὲν οὖν οὕτως ὑμῖν προσενήνεγμαι, Μειδίας δὲ πῶς; οὐδέπω καὶ τήμερον συμμορίας ἡγεμὼν γέγονεν, οὐδὲν τῶν πατρῴων ἀποστερηθεὶς ὑπ’ οὐδενός, ἀλλὰ παρὰ τοῦ πατρὸς πολλὴν οὐσίαν παραλαβών.", "st": "21.157"}, {"sp": "N", "t": "τίς οὖν ἡ λαμπρότης, ἢ τίνες αἱ λῃτουργίαι καὶ τὰ σέμν’ ἀναλώματα τούτου; ἐγὼ μὲν γὰρ οὐχ ὁρῶ, πλὴν εἰ ταῦτά τις θεωρεῖ· οἰκίαν ᾠκοδόμηκεν Ἐλευσῖνι τοσαύτην ὥστε πᾶσιν ἐπισκοτεῖν τοῖς ἐν τῷ τόπῳ, καὶ εἰς μυστήρια τὴν γυναῖκ’ ἄγει, κἂν ἄλλοσέ ποι βούληται, ἐπὶ τοῦ λευκοῦ ζεύγους τοῦ ἐκ Σικυῶνος, καὶ τρεῖς ἀκολούθους ἢ τέτταρας αὐτὸς ἔχων διὰ τῆς ἀγορᾶς σοβεῖ, κυμβία καὶ ῥυτὰ καὶ φιάλας ὀνομάζων οὕτως ὥστε τοὺς παριόντας ἀκούειν.", "st": "21.158"}, {"sp": "N", "t": "ἐγὼ δ’ ὅσα μὲν τῆς ἰδίας τρυφῆς εἵνεκα Μειδίας καὶ περιουσίας κτᾶται, οὐκ οἶδ’ ὅ τι τοὺς πολλοὺς ὑμῶν ὠφελεῖ· ἃ δ’ ἐπαιρόμενος τούτοις ὑβρίζει, ἐπὶ πολλοὺς καὶ τοὺς τυχόντας ἡμῶν ἀφικνούμεν’ ὁρῶ. οὐ δεῖ δὴ τὰ τοιαῦθ’ ἑκάστοτε τιμᾶν οὐδὲ θαυμάζειν ὑμᾶς, οὐδὲ τὴν φιλοτιμίαν ἐκ τούτων κρίνειν, εἴ τις οἰκοδομεῖ λαμπρῶς ἢ θεραπαίνας κέκτηται πολλὰς ἢ σκεύη [καλά], ἀλλ’ ὃς ἂν ἐν τούτοις λαμπρὸς καὶ φιλότιμος ᾖ, ὧν ἅπασι μέτεστι τοῖς πολλοῖς ὑμῶν· ὧν οὐδὲν εὑρήσετε τούτῳ προσόν.", "st": "21.159"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία τριήρη ἐπέδωκεν· ταύτην γὰρ οἶδ’ ὅτι θρυλήσει, καὶ φήσει “ἐγὼ ὑμῖν τριήρη ἐπέδωκα.” οὑτωσὶ δὴ ποιήσατε. εἰ μέν, ὦ ἄνδρες Ἀθηναῖοι, φιλοτιμίας εἵνεκα ταύτην ἐπέδωκεν, ἣν προσήκει τῶν τοιούτων ἔχειν χάριν, ταύτην ἔχετ’ αὐτῷ καὶ ἀπόδοτε, ὑβρίζειν δὲ μὴ δῶτε· οὐδενὸς γὰρ πράγματος οὐδ’ ἔργου τοῦτο συγχωρητέον. εἰ δὲ δὴ καὶ δειλίας καὶ ἀνανδρίας εἵνεκα δειχθήσεται τοῦτο πεποιηκώς, μὴ παρακρουσθῆτε. πῶς οὖν εἴσεσθε; ἐγὼ καὶ τοῦτο διδάξω· ἄνωθεν δέ, βραχὺς γάρ ἐσθ’ ὁ λόγος, λέξω.", "st": "21.160"}, {"sp": "N", "t": "ἐγένοντ’ εἰς Εὔβοιαν ἐπιδόσεις παρ’ ὑμῖν πρῶται· τούτων οὐκ ἦν Μειδίας, ἀλλ’ ἐγώ, καὶ συντριήραρχος ἦν μοι Φιλῖνος ὁ Νικοστράτου. ἕτεραι δεύτεραι μετὰ ταῦτ’ εἰς Ὄλυνθον· οὐδὲ τούτων ἦν Μειδίας. καίτοι τόν γε δὴ φιλότιμον πανταχοῦ προσῆκεν ἐξετάζεσθαι. τρίται νῦν αὗται γεγόνασιν ἐπιδόσεις· ἐνταῦθ’ ἐπέδωκεν. πῶς; ἐν τῇ βουλῇ γιγνομένων ἐπιδόσεων παρὼν οὐκ ἐπεδίδου τότε·", "st": "21.161"}, {"sp": "N", "t": "ἐπειδὴ δὲ πολιορκεῖσθαι τοὺς ἐν Ταμύναις στρατιώτας ἐξηγγέλλετο, καὶ πάντας ἐξιέναι τοὺς ὑπολοίπους ἱππέας, ὧν εἷς οὗτος ἦν, προεβούλευσεν ἡ βουλή, τηνικαῦτα φοβηθεὶς τὴν στρατείαν ταύτην εἰς τὴν ἐπιοῦσαν ἐκκλησίαν, πρὶν καὶ προέδρους καθέζεσθαι, παρελθὼν ἐπέδωκεν. τῷ δῆλον, ὥστε μηδ’ ἀντειπεῖν αὐτὸν ἔχειν, ὅτι τὴν στρατείαν φεύγων, οὐ φιλοτιμίᾳ, τοῦτ’ ἐποίησεν; τοῖς μετὰ ταῦτα πραχθεῖσιν ὑπ’ αὐτοῦ.", "st": "21.162"}, {"sp": "N", "t": "τὸ μὲν γὰρ πρῶτον, ὡς οὐκ ἐδόκει, προϊούσης τῆς ἐκκλησίας καὶ λόγων γιγνομένων, τῆς τῶν ἱππέων βοηθείας ἤδη δεῖν, ἀλλ’ ἀνεπεπτώκει τὰ τῆς ἐξόδου, οὐκ ἀνέβαιν’ ἐπὶ τὴν ναῦν ἣν ἐπέδωκεν, ἀλλὰ τὸν μέτοικον ἐξέπεμψε τὸν Αἰγύπτιον, Πάμφιλον, αὐτὸς δὲ μένων ἐνθάδε τοῖς Διονυσίοις διεπράττετο ταῦτ’ ἐφ’ οἷς νυνὶ κρίνεται·", "st": "21.163"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὁ στρατηγὸς Φωκίων μετεπέμπετο τοὺς ἐξ Ἀργούρας ἱππέας ἐπὶ τὴν διαδοχὴν καὶ κατείληπτο σοφιζόμενος, τόθ’ ὁ δειλὸς καὶ κατάρατος οὑτοσὶ λιπὼν τὴν τάξιν ταύτην ἐπὶ τὴν ναῦν ᾤχετο, καὶ ὧν ἱππαρχεῖν ἠξίωσε παρ’ ὑμῖν ἱππέων, τούτοις οὐ συνεξῆλθεν. εἰ δ’ ἐν τῇ θαλάττῃ κίνδυνός τις ἦν, εἰς τὴν γῆν δῆλον ὅτι ᾤχετ’ ἄν.", "st": "21.164"}, {"sp": "N", "t": "οὐ μὴν Νικήρατός γ’ οὕτως ὁ τοῦ Νικίου, ὁ ἀγαπητός, ὁ ἄπαις, ὁ παντάπασιν ἀσθενὴς τῷ σώματι· οὐδ’ Εὐκτήμων ὁ τοῦ Αἰσίωνος, οὐχ οὕτως· οὐδ’ Εὐθύδημος ὁ τοῦ Στρατοκλέους· ἀλλ’ αὐτῶν ἕκαστος ἑκὼν ἐπιδοὺς τριήρη οὐκ ἀπέδρα ταύτῃ τὴν στρατείαν, ἀλλὰ τὴν μὲν [ἐπίδοσιν] ἐν χάριτος μέρει καὶ δωρειᾶς παρεῖχον πλέουσαν τῇ πόλει, οὗ δ’ ὁ νόμος προσέταττεν, ἐνταῦθα τοῖς σώμασιν αὐτοὶ λῃτουργεῖν ἠξίουν.", "st": "21.165"}, {"sp": "N", "t": "ἀλλ’ οὐχ ὁ ἵππαρχος Μειδίας, ἀλλὰ τὴν ἐκ τῶν νόμων τάξιν λιπών, οὗ δίκην ὀφείλει τῇ πόλει δοῦναι, τοῦτ’ ἐν εὐεργεσίας ἀριθμήσει μέρει. καίτοι τὴν τοιαύτην τριηραρχίαν, ὢ πρὸς θεῶν, πότερον τελωνίαν καὶ πεντηκοστὴν καὶ λιποτάξιον καὶ στρατείας ἀπόδρασιν καὶ πάντα τὰ τοιαῦθ’ ἁρμόττει καλεῖν, ἢ φιλοτιμίαν; οὐδένα γὰρ τρόπον ἄλλον ἐν τοῖς ἱππεῦσιν αὑτὸν ἀτελῆ ποιῆσαι στρατείας δυνάμενος ταύτην εὕρηκε Μειδίας καινὴν ἱππικήν τινα πεντηκοστήν.", "st": "21.166"}, {"sp": "N", "t": "καὶ γὰρ αὖ τοῦτο. τῶν ἄλλων ἁπάντων τῶν ἐπιδόντων τριηράρχων παραπεμπόντων ὑμᾶς ὅτε δεῦρ’ ἀπεπλεῖτ’ ἐκ Στύρων, μόνος οὗτος οὐ παρέπεμπεν, ἀλλ’ ἀμελήσας ὑμῶν χάρακας καὶ βοσκήματα καὶ θυρώμαθ’ ὡς αὑτὸν καὶ ξύλ’ εἰς τὰ ἔργα τὰ ἀργύρει’ ἐκόμιζεν, καὶ χρηματισμός, οὐ λῃτουργία γέγονεν ἡ τριηραρχία τῷ καταπτύστῳ τούτῳ. ἀλλὰ μὴν ὡς ἀληθῆ λέγω σύνιστε μὲν τὰ πολλὰ τούτων, ὅμως δὲ καὶ μάρτυρας ὑμῖν καλῶ.", "st": "21.167"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ", "st": "21.167"}, {"sp": "N", "t": "[Κλέων Σουνιεύς, Ἀριστοκλῆς Παιανιεύς, Πάμφιλος, Νικήρατος Ἀχερδούσιος, Εὐκτήμων Σφήττιος, καθ’ ὃν καιρὸν ἐκ Στύρων ἀπεπλέομεν δεῦρο τῷ στόλῳ παντί, ἐτύχομεν τριηραρχοῦντες καὶ αὐτοὶ καὶ Μειδίας ὁ νῦν κρινόμενος ὑπὸ Δημοσθένους, ᾧ μαρτυροῦμεν. παντὸς δὲ τοῦ στόλου πλεόντων ἐν τάξει, καὶ τῶν τριηράρχων ἐχόντων παράγγελμα μὴ χωρίζεσθαι ἕως ἂν δεῦρο καταπλεύσωμεν, Μειδίας ὑπολειφθεὶς τοῦ στόλου, καὶ γεμίσας τὴν ναῦν ξύλων καὶ χαράκων καὶ βοσκημάτων καὶ ἄλλων τινῶν, κατέπλευσεν εἰς Πειραιᾶ μόνος μεθ’ ἡμέρας δύο, καὶ οὐ συγκατέστησε τὸν στόλον μετὰ τῶν ἄλλων τριηράρχων.]", "st": "21.168"}, {"sp": "N", "t": "εἰ τοίνυν ὡς ἀληθῶς, ἄνδρες Ἀθηναῖοι, οἷάπερ φήσει καὶ καταλαζονεύσεται πρὸς ὑμᾶς αὐτίκα δὴ μάλα, τοιαῦτ’ ἦν αὐτῷ τὰ λελῃτουργημένα καὶ πεπραγμένα, καὶ μὴ τοιαῦθ’ οἷ’ ἐγὼ δεικνύω, οὐδ’ οὕτω δήπου τό γε δοῦναι δίκην ὧν ὕβρικεν ἐκφυγεῖν ταῖς λῃτουργίαις δίκαιος ἂν ἦν. ἐγὼ γὰρ οἶδ’ ὅτι πολλοὶ πολλὰ κἀγάθ’ ὑμᾶς εἰσιν εἰργασμένοι, οὐ κατὰ τὰς Μειδίου λῃτουργίας, οἱ μὲν ναυμαχίας νενικηκότες, οἱ δὲ πόλεις εἰληφότες, οἱ δὲ πολλὰ καὶ καλὰ ὑπὲρ τῆς πόλεως στήσαντες τρόπαια·", "st": "21.169"}, {"sp": "N", "t": "ἀλλ’ ὅμως οὐδενὶ πώποτε τούτων δεδώκατε τὴν δωρειὰν ταύτην οὐδ’ ἂν δοίητε, ἐξεῖναι τοὺς ἰδίους ἐχθροὺς ὑβρίζειν αὐτῶν ἑκάστῳ, ὁπότ’ ἂν βούληται καὶ ὃν ἂν δύνηται τρόπον. οὐδὲ γὰρ Ἁρμοδίῳ καὶ Ἀριστογείτονι· τούτοις γὰρ δὴ μέγισται δέδονται δωρειαὶ παρ’ ὑμῶν καὶ ὑπὲρ μεγίστων. οὐδ’ ἂν ἠνέσχεσθε, εἰ προσέγραψέ τις ἐν τῇ στήλῃ “ἐξεῖναι δὲ καὶ ὑβρίζειν αὐτοῖς ὃν ἂν βούλωνται·” ὑπὲρ γὰρ αὐτοῦ τούτου τὰς ἄλλας ἔλαβον δωρειάς, ὅτι τοὺς ὑβρίζοντας ἔπαυσαν.", "st": "21.170"}, {"sp": "N", "t": "ὅτι τοίνυν καὶ κεκόμισται χάριν, ὦ ἄνδρες Ἀθηναῖοι, παρ’ ὑμῶν, οὐ μόνον ὧν αὐτὸς λελῃτούργηκε λῃτουργιῶν ἀξίαν (μικρὰ γὰρ αὕτη γέ τις ἦν), ἀλλὰ καὶ τῶν μεγίστων, καὶ τοῦτο βούλομαι δεῖξαι, ἵνα μηδ’ ὀφείλειν οἴησθέ τι τῷ καταπτύστῳ τούτῳ. ὑμεῖς γάρ, ὦ ἄνδρες Ἀθηναῖοι, ἐχειροτονήσατε τοῦτον τῆς Παράλου ταμίαν, ὄντα τοιοῦτον οἷός ἐστι, καὶ πάλιν ἵππαρχον, ὀχεῖσθαι διὰ τῆς ἀγορᾶς ταῖς πομπαῖς οὐ δυνάμενον, καὶ μυστηρίων ἐπιμελητὴν καὶ ἱεροποιόν ποτε καὶ βοώνην, καὶ τὰ τοιαῦτα δή.", "st": "21.171"}, {"sp": "N", "t": "εἶτα πρὸς τῶν θεῶν τὸ τὴν τῆς φύσεως κακίαν καὶ ἀνανδρίαν καὶ πονηρίαν ταῖς παρ’ ὑμῶν ἀρχαῖς καὶ τιμαῖς καὶ χειροτονίαις ἐπανορθοῦσθαι μικρὰν ὑπολαμβάνετ’ εἶναι δωρειὰν καὶ χάριν; καὶ μὴν εἴ τις αὐτοῦ ταῦτ’ ἀφέλοιτο “ἱππάρχηκα, τῆς Παράλου ταμίας γέγονα,” τίνος ἔστ’ ἄξιος οὗτος;", "st": "21.172"}, {"sp": "N", "t": "ἀλλὰ μὴν κἀκεῖνό γ’ ἐπίστασθε, ὅτι τῆς μὲν Παράλου ταμιεύσας Κυζικηνῶν ἥρπασε πλεῖν ἢ πέντε τάλαντα, ὑπὲρ ὧν ἵνα μὴ δῷ δίκην, πάντα τρόπον περιωθῶν καὶ ἐλαύνων τοὺς ἀνθρώπους καὶ τὰ σύμβολα συγχέων τὴν μὲν πόλιν ἐχθρὰν τῇ πόλει πεποίηκεν, τὰ χρήματα δ’ αὐτὸς ἔχει· ἵππαρχος δὲ χειροτονηθεὶς λελύμανται τὸ ἱππικὸν ὑμῶν, τοιούτους θεὶς νόμους οὓς πάλιν αὐτὸς ἔξαρνος ἦν μὴ τεθεικέναι.", "st": "21.173"}, {"sp": "N", "t": "καὶ τῆς μὲν Παράλου ταμιεύων τότε, ὅτε τὴν ἐπὶ Θηβαίους ἔξοδον εἰς Εὔβοιαν ἐποιεῖσθ’ ὑμεῖς, δώδεκα τῆς πόλεως τάλαντ’ ἀναλίσκειν ταχθείς, ἀξιούντων ὑμῶν πλεῖν καὶ παραπέμπειν τοὺς στρατιώτας οὐκ ἐβοήθησεν, ἀλλ’ ἤδη τῶν σπονδῶν γεγονυιῶν, ἃς Διοκλῆς ἐσπείσατο Θηβαίοις, ἧκεν. καὶ τόθ’ ἡττᾶτο πλέων τῶν ἰδιωτικῶν τριήρων μιᾶς· οὕτως εὖ τὴν ἱερὰν τριήρη παρεσκευάκει. ἱππαρχῶν τοίνυν, τί οἴεσθε τἄλλα; ἀλλ’ ἵππον, ἵππον οὐκ ἐτόλμησεν ὁ λαμπρὸς καὶ πλούσιος οὗτος πρίασθαι, ἀλλ’ ἐπ’ ἀλλοτρίου τὰς πομπὰς ἡγεῖτο, τοῦ Φιλομήλου τοῦ Παιανιέως ἵππου· καὶ ταῦτα πάντες ἴσασιν οἱ ἱππεῖς. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, κάλει μοι καὶ τούτων τοὺς μάρτυρας.", "st": "21.174"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ", "st": "21.174"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὅσων ἤδη καταχειροτονήσαντος τοῦ δήμου περὶ τὴν ἑορτὴν ἀδικεῖν ὑμεῖς κατεγνώκατε, εἰπεῖν, καὶ δεῖξαι τί πεποιηκότες αὐτῶν ἔνιοι τίνος ὀργῆς τετυχήκασι παρ’ ὑμῶν, ἵνα ταῦτα πρὸς τὰ τούτῳ πεπραγμέν’ ἀντιθῆτε. πρῶτον μὲν τοίνυν, ἵνα πρώτης τῆς τελευταίας γεγονυίας μνησθῶ καταγνώσεως, περὶ τὰ μυστήρι’ ἀδικεῖν Εὐάνδρου κατεχειροτόνησεν ὁ δῆμος τοῦ Θεσπιῶς, προβαλλομένου αὐτὸν Μενίππου, Καρός τινος ἀνθρώπου. ἔστι δ’ ὁ αὐτὸς νόμος τῷδε τῷ περὶ τῶν Διονυσίων ὁ περὶ τῶν μυστηρίων, κἀκεῖνος ὕστερος τοῦδ’ ἐτέθη.", "st": "21.175"}, {"sp": "N", "t": "τί οὖν ποιήσαντος, ὦ ἄνδρες Ἀθηναῖοι, κατεχειροτονήσατε τοῦ Εὐάνδρου; τοῦτ’ ἀκούσατε. ὅτι δίκην ἐμπορικὴν καταδικασάμενος τοῦ Μενίππου, οὐκ ἔχων πρότερον λαβεῖν αὐτόν, ὡς ἔφη, τοῖς μυστηρίοις ἐπιδημοῦντος ἐπελάβετο. κατεχειροτονήσατε μὲν διὰ ταῦτα, καὶ οὐδ’ ὁτιοῦν ἄλλο προσῆν, εἰσελθόντα δ’ εἰς τὸ δικαστήριον ἐβούλεσθε μὲν θανάτῳ κολάσαι, τοῦ δὲ προβαλλομένου πεισθέντος τὴν δίκην τε πᾶσαν ἀφεῖναι ἠναγκάσατ’ αὐτόν, ἣν ᾑρήκει πρότερον (ἦν δὲ δυοῖν αὕτη ταλάντοιν), καὶ προσετιμήσατε τὰς βλάβας, ἃς ἐπὶ τῇ χειροτονίᾳ μένων ἐλογίζεθ’ αὑτῷ γεγενῆσθαι πρὸς ὑμᾶς ἅνθρωπος.", "st": "21.176"}, {"sp": "N", "t": "εἷς μὲν οὗτος ἐξ ἰδίου πράγματος, οὐδεμιᾶς ὕβρεως προσούσης, ὑπὲρ αὐτοῦ τοῦ παραβῆναι τὸν νόμον τοσαύτην ἔδωκε δίκην. εἰκότως· τοῦτο γάρ ἐσθ’ ὃ φυλάττειν ὑμᾶς δεῖ, τοὺς νόμους, τὸν ὅρκον· ταῦτ’ ἔχεθ’ ὑμεῖς οἱ δικάζοντες ἀεὶ παρὰ τῶν ἄλλων ὡσπερεὶ παρακαταθήκην, ἣν ἅπασιν, ὅσοι μετὰ τοῦ δικαίου πρὸς ὑμᾶς ἔρχονται, σῶν ὑπάρχειν δεῖ.", "st": "21.177"}, {"sp": "N", "t": "ἕτερος ἀδικεῖν ποτ’ ἔδοξεν ὑμῖν περὶ τὰ Διονύσια, καὶ κατεχειροτονήσατ’ αὐτοῦ παρεδρεύοντος ἄρχοντι τῷ υἱεῖ, ὅτι θέαν τινὸς καταλαμβάνοντος ἥψατο, ἐξείργων ἐκ τοῦ θεάτρου· ἦν δ’ οὗτος ὁ τοῦ βελτίστου πατὴρ Χαρικλείδου, τοῦ ἄρξαντος.", "st": "21.178"}, {"sp": "N", "t": "καὶ μέγα γ’ ὑμῖν τοῦτ’ ἐδόκει δίκαιον ἔχειν ὁ προβαλλόμενος λέγειν, “εἰ κατελάμβανον, ἄνθρωπε, θέαν, εἰ μὴ τοῖς κηρύγμασιν, ὡς σύ με φῄς, ἐπειθόμην, τίνος ἐκ τῶν νόμων εἶ κύριος, καὶ ὁ ἄρχων αὐτός; τοῖς ὑπηρέταις ἐξείργειν εἰπεῖν, οὐκ αὐτὸς τύπτειν. οὐδ’ οὕτω πείθομαι· ἐπιβολὴν ἐπιβαλεῖν, πάντα μᾶλλον πλὴν αὐτὸς ἅψασθαι τῇ χειρί· πολλὰ γὰρ πρὸ τοῦ μὴ τὸ σῶμ’ ἕκαστον ὑβρίζεσθαι πεποιήκασιν οἱ νόμοι.” ταῦτ’ ἔλεγεν μὲν ἐκεῖνος, ἐχειροτονήσατε δ’ ὑμεῖς· οὐ μὴν εἰσῆλθεν εἰς τὸ δικαστήριον οὗτος, ἀλλ’ ἐτελεύτησεν πρότερον.", "st": "21.179"}, {"sp": "N", "t": "ἑτέρου τοίνυν ὅ τε δῆμος ἅπας κατεχειροτόνησ’ ἀδικεῖν περὶ τὴν ἑορτήν, καὶ ὑμεῖς εἰσελθόντ’ ἀπεκτείνατε τοῦτον, Κτησικλέα, ὅτι σκῦτος ἔχων ἐπόμπευε, καὶ τούτῳ μεθύων ἐπάταξέ τιν’ ἐχθρὸν ὑπάρχονθ’ ἑαυτῷ· ἐδόκει γὰρ ὕβρει καὶ οὐκ οἴνῳ τύπτειν, ἀλλὰ τὴν ἐπὶ τῆς πομπῆς καὶ τοῦ μεθύειν πρόφασιν λαβὼν ἀδικεῖν, ὡς δούλοις χρώμενος τοῖς ἐλευθέροις.", "st": "21.180"}, {"sp": "N", "t": "ἁπάντων τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τούτων, ὧν ὁ μὲν ὧν εἷλεν ἀποστάς, ὁ δὲ καὶ θανάτῳ ζημιωθεὶς φαίνεται, πολλῷ δεινότερ’ εὖ οἶδ’ ὅτι πάντες ἂν εἶναι φήσειαν τὰ Μειδίᾳ πεπραγμένα· οὔτε γὰρ πομπεύων οὔτε δίκην ᾑρηκὼς οὔτε παρεδρεύων οὔτ’ ἄλλην σκῆψιν ἔχων οὐδεμίαν πλὴν ὕβριν, τοιαῦτα πεποίηκεν οἷ’ οὐδεὶς ἐκείνων. καὶ τούτους μὲν ἐάσω.", "st": "21.181"}, {"sp": "N", "t": "ἀλλὰ Πύρρον, ὦ ἄνδρες Ἀθηναῖοι, τὸν Ἐτεοβουτάδην, ἐνδειχθέντα δικάζειν ὀφείλοντα τῷ δημοσίῳ, θανάτῳ ζημιῶσαί τινες ὑμῶς ᾤοντο χρῆναι, καὶ τέθνηκεν ἁλοὺς παρ’ ὑμῖν· καίτοι τοῦτο τὸ λῆμμα δι’ ἔνδειαν, οὐ δι’ ὕβριν λαμβάνειν ἐπεχείρησεν ἐκεῖνος. καὶ πολλοὺς ἂν ἑτέρους ἔχοιμι λέγειν, ὧν οἱ μὲν τεθνᾶσιν, οἱ δ’ ἠτιμωμένοι διὰ πολλῷ τούτων εἰσὶν ἐλάττω πράγματα. ὑμεῖς [δ’], ὦ ἄνδρες Ἀθηναῖοι, Σμίκρῳ δέκα ταλάντων ἐτιμήσατε καὶ Σκίτωνι τοσούτων ἑτέρων, δόξαντι παράνομα γράφειν, καὶ οὔτε παιδί’ οὔτε φίλους οὔτε συγγενεῖς οὔθ’ ὁντινοῦν ἠλεήσατε τῶν παρόντων ἐκείνοις.", "st": "21.182"}, {"sp": "N", "t": "μὴ τοίνυν, ἐὰν μὲν εἴπῃ τις παράνομα, οὕτως ὀργιζόμενοι φαίνεσθε, ἐὰν δὲ ποιῇ, μὴ λέγῃ, πράως διάκεισθε. οὐδὲν γὰρ ῥῆμ’ οὐδ’ ὄνομ’ οὕτως ἐστὶ τοῖς πολλοῖς ὑμῶν χαλεπόν, ὡς ὅσ’ ὑβρίζων τις τὸν ἐντυχόνθ’ ὑμῶν διαπράττεται. μὴ τοίνυν αὐτοὶ καθ’ ὑμῶν αὐτῶν δεῖγμα τοιοῦτον ἐξενέγκητ’, ἄνδρες Ἀθηναῖοι, ὡς ἄρ’ ὑμεῖς, ἂν μὲν τῶν μετρίων τινὰ καὶ δημοτικῶν λάβηθ’ ὁτιοῦν ἀδικοῦντα, οὔτ’ ἐλεήσετ’ οὔτ’ ἀφήσετε, ἀλλ’ ἀποκτενεῖτ’ ἢ ἀτιμώσετε, ἂν δὲ πλούσιος ὤν τις ὑβρίζῃ, συγγνώμην ἕξετε. μὴ δῆτα· οὐ γὰρ δίκαιον· ἀλλ’ ἐπὶ πάντων ὁμοίως ὀργιζόμενοι φαίνεσθε.", "st": "21.183"}, {"sp": "N", "t": "ἃ τοίνυν οὐδενὸς τῶν εἰρημένων ἧττον ἀναγκαῖον εἶναι νομίζω πρὸς ὑμᾶς εἰπεῖν, ταῦτ’ εἰπὼν ἔτι καὶ βραχέα περὶ τούτων διαλεχθεὶς καταβήσομαι. ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, μεγάλη τοῖς ἀδικοῦσιν ἅπασι μερὶς καὶ πλεονεξία ἡ τῶν ὑμετέρων τρόπων πραότης. ὅτι δὴ ταύτης οὐδ’ ὁτιοῦν ὑμῖν μεταδοῦναι τούτῳ προσήκει, ταῦτ’ ἀκούσατέ μου. ἐγὼ νομίζω πάντας ἀνθρώπους ἐράνους φέρειν παρὰ πάντα τὸν βίον αὑτοῖς, οὐχὶ τούσδε μόνους οὓς συλλέγουσί τινες καὶ ὧν πληρωταὶ γίγνονται, ἀλλὰ καὶ ἄλλους.", "st": "21.184"}, {"sp": "N", "t": "οἷον ἔστι μέτριος καὶ φιλάνθρωπός τις ἡμῶν καὶ πολλοὺς ἐλεῶν· τούτῳ ταὐτὸ δίκαιον ὑπάρχειν παρὰ πάντων, ἄν ποτ’ εἰς χρείαν καὶ ἀγῶν’ ἀφίκηται. ἄλλος οὑτοσί τις ἀναιδὴς καὶ πολλοὺς ὑβρίζων, καὶ τοὺς μὲν πτωχούς, τοὺς δὲ καθάρματα, τοὺς δ’ οὐδ’ ἀνθρώπους ὑπολαμβάνων· τούτῳ τὰς αὐτὰς δίκαιον ὑπάρχειν φοράς, ἅσπερ αὐτὸς εἰσενήνοχε τοῖς ἄλλοις. ἂν τοίνυν ὑμῖν ἐπίῃ σκοπεῖν, τούτου πληρωτὴν εὑρήσετε Μειδίαν ὄντα τοῦ ἐράνου, καὶ οὐκ ἐκείνου.", "st": "21.185"}, {"sp": "N", "t": "οἶδα τοίνυν ὅτι τὰ παιδί’ ἔχων ὀδυρεῖται, καὶ πολλοὺς λόγους καὶ ταπεινοὺς ἐρεῖ, δακρύων καὶ ὡς ἐλεινότατον ποιῶν ἑαυτόν. ἔστι δ’, ὅσῳ περ ἂν αὑτὸν νῦν ταπεινότερον ποιῇ, τοσούτῳ μᾶλλον ἄξιον μισεῖν αὐτόν, ὦ ἄνδρες Ἀθηναῖοι. διὰ τί; ὅτι εἰ μὲν μηδαμῶς δυνηθεὶς ταπεινὸς γενέσθαι οὕτως ἀσελγὴς καὶ βίαιος ἦν ἐπὶ τοῦ παρεληλυθότος βίου, τῇ φύσει καὶ τῇ τύχῃ, δι’ ἣν τοιοῦτος ἐγένετο, ἄξιον ἦν ἄν τι τῆς ὀργῆς ἀνεῖναι· εἰ δ’ ἐπιστάμενος μέτριον παρέχειν αὑτὸν ὅταν βούληται τὸν ἐναντίον ἢ τοῦτον τὸν τρόπον εἵλετο ζῆν, εὔδηλον δήπου τοῦθ’ ὅτι καὶ νῦν ἂν διακρούσηται, πάλιν αὐτὸς ἐκεῖνος ὃν ὑμεῖς ἴστε γενήσεται.", "st": "21.186"}, {"sp": "N", "t": "οὐ δεῖ δὴ προσέχειν, οὐδὲ τὸν παρόντα καιρόν, ὃν οὗτος ἐξεπίτηδες πλάττεται, κυριώτερον οὐδὲ πιστότερον τοῦ παντός, ὃν αὐτοὶ σύνιστε, χρόνου ποιήσασθαι. ἐμοὶ παιδί’ οὐκ ἔστιν, οὐδ’ ἂν ἔχοιμι ταῦτα παραστησάμενος κλάειν καὶ δακρύειν ἐφ’ οἷς ὑβρίσθην. διὰ τοῦτ’ ἄρα τοῦ πεποιηκότος ὁ πεπονθὼς ἔλαττον ἕξω παρ’ ὑμῖν;", "st": "21.187"}, {"sp": "N", "t": "μὴ δῆτα· ἀλλ’ ὅταν οὗτος ἔχων τὰ παιδία τούτοις ἀξιοῖ δοῦναι τὴν ψῆφον ὑμᾶς, τόθ’ ὑμεῖς τοὺς νόμους ἔχοντά με πλησίον ἡγεῖσθε παρεστάναι [καὶ τὸν ὅρκον ὃν ὀμωμόκατε], τούτοις ἀξιοῦντα καὶ ἀντιβολοῦνθ’ ἕκαστον ὑμῶν ψηφίσασθαι. οἷς ὑμεῖς κατὰ πολλὰ δικαιότερον πρόσθοισθ’ ἂν ἢ τούτῳ· καὶ γὰρ ὀμωμόκατ’, ὦ ἄνδρες Ἀθηναῖοι, τοῖς νόμοις πείσεσθαι, καὶ τῶν ἴσων μέτεστιν ὑμῖν διὰ τοὺς νόμους, καὶ πάνθ’ ὅσ’ ἔστ’ ἀγάθ’ ὑμῖν διὰ τοὺς νόμους ἐστίν, οὐ διὰ Μειδίαν οὐδὲ διὰ τοὺς Μειδίου παῖδας.", "st": "21.188"}, {"sp": "N", "t": "καὶ “ῥήτωρ ἐστὶν οὗτος” ἴσως ἐμὲ φήσει λέγων. ἐγὼ δ’, εἰ μὲν ὁ συμβουλεύων ὅ τι ἂν συμφέρειν ὑμῖν ἡγῆται, καὶ τοῦτ’ ἄχρι τοῦ μηδὲν ὑμῖν ἐνοχλεῖν μηδὲ βιάζεσθαι, ῥήτωρ ἐστίν, οὔτε φύγοιμ’ ἂν οὔτ’ ἀπαρνοῦμαι τοῦτο τοὔνομα· εἰ μέντοι ῥήτωρ ἐστὶν οἵους ἐνίους τῶν λεγόντων ἐγὼ καὶ ὑμεῖς δ’ ὁρᾶτε, ἀναιδεῖς καὶ ἀφ’ ὑμῶν πεπλουτηκότας, οὐκ ἂν εἴην οὗτος ἐγώ· εἴληφα μὲν γὰρ οὐδ’ ὁτιοῦν παρ’ ὑμῶν, τὰ δ’ ὄντ’ εἰς ὑμᾶς πλὴν πάνυ μικρῶν ἅπαντ’ ἀνήλωκα. καίτοι καὶ εἰ τούτων ἦν πονηρότατος, κατὰ τοὺς νόμους ἔδει παρ’ ἐμοῦ δίκην λαμβάνειν, οὐκ ἐφ’ οἷς ἐλῃτούργουν ὑβρίζειν.", "st": "21.189"}, {"sp": "N", "t": "ἔτι τοίνυν οὐδὲ εἷς ἐστιν ὅστις ἐμοὶ τῶν λεγόντων συναγωνίζεται. καὶ οὐδενὶ μέμφομαι· οὐδὲ γὰρ αὐτὸς οὐδενὸς εἵνεκα τούτων οὐδὲν ἐν ὑμῖν πώποτ’ εἶπον, ἀλλ’ ἁπλῶς κατ’ ἐμαυτὸν ἔγνων καὶ λέγειν καὶ πράττειν ὅ τι ἂν συμφέρειν ὑμῖν ἡγῶμαι. ἀλλὰ τούτῳ πάντας αὐτίκα δὴ μάλα συνεξεταζομένους τοὺς ῥήτορας ὄψεσθ’ ἐφεξῆς. καίτοι πῶς ἐστι δίκαιον, τοὔνομα μὲν τοῦθ’ ὡς ὄνειδος προφέρειν ἐμοί, διὰ τούτων δ’ αὐτὸν τῶν ἀνδρῶν ἀξιοῦν σωθῆναι;", "st": "21.190"}, {"sp": "N", "t": "τάχα τοίνυν ἴσως καὶ τὰ τοιαῦτ’ ἐρεῖ, ὡς ἐσκεμμένα καὶ παρεσκευασμένα πάντα λέγω νῦν. ἐγὼ δ’ ἐσκέφθαι μέν, ὦ ἄνδρες Ἀθηναῖοι, φημὶ καὶ οὐκ ἂν ἀρνηθείην, καὶ μεμελετηκέναι γ’ ὡς ἐνῆν μάλιστ’ ἐμοί· καὶ γὰρ ἂν ἄθλιος ἦν, εἰ τοιαῦτα παθὼν καὶ πάσχων ἠμέλουν ὧν περὶ τούτων ἐρεῖν ἔμελλον πρὸς ὑμᾶς·", "st": "21.191"}, {"sp": "N", "t": "γεγραφέναι μέντοι μοι τὸν λόγον Μειδίαν· ὁ γὰρ τὰ ἔργα παρεσχηκὼς περὶ ὧν εἰσιν οἱ λόγοι δικαιότατ’ ἂν ταύτην ἔχοι τὴν αἰτίαν, οὐχ ὁ ἐσκεμμένος οὐδ’ ὁ μεριμνήσας τὰ δίκαια λέγειν νῦν. ἐγὼ μὲν οὖν τοῦτο ποιῶν, ὦ ἄνδρες Ἀθηναῖοι, καὶ αὐτὸς ὁμολογῶ· Μειδίαν μέντοι μηδὲν ἐσκέφθαι πώποτ’ ἐν παντὶ τῷ βίῳ δίκαιον εἰκός ἐστιν· εἰ γὰρ καὶ κατὰ μικρὸν ἐπῄει τὰ τοιαῦτ’ αὐτῷ σκοπεῖν, οὐκ ἂν τοσοῦτον διημάρτανε τοῦ πράγματος.", "st": "21.192"}, {"sp": "N", "t": "οἶμαι τοίνυν αὐτὸν οὐδὲ τοῦ δήμου κατηγορεῖν ὀκνήσειν οὐδὲ τῆς ἐκκλησίας, ἀλλ’ ἅπερ τότ’ ἐτόλμα λέγειν ὅτ’ ἦν ἡ προβολή, ταῦτα καὶ νῦν ἐρεῖν, ὡς ὅσοι δέον ἐξιέναι κατέμενον καὶ ὅσοι τὰ φρούρι’ ἦσαν ἔρημα λελοιπότες, ἐξεκλησίασαν, καὶ χορευταὶ καὶ ξένοι καὶ τοιοῦτοί τινες ἦσαν οἳ κατεχειροτόνησαν αὐτοῦ.", "st": "21.193"}, {"sp": "N", "t": "εἰς γὰρ τοῦτο θράσους καὶ ἀναιδείας τότ’ ἀφίκετ’, ὦ ἄνδρες δικασταί, ὡς ἴσασιν ὅσοι παρῆσαν ὑμῶν, ὥστε κακῶς λέγων καὶ ἀπειλῶν καὶ βλέπων εἰς τὸν ἀεὶ θορυβοῦντα τόπον τῆς ἐκκλησίας καταπλήξειν ᾤετο τὸν δῆμον ἅπαντα. ᾗ καὶ γελοῖ’ εἶναι τὰ νῦν, οἶμαι, δάκρυ’ εἰκότως ἂν αὐτοῦ δοκοίη.", "st": "21.194"}, {"sp": "N", "t": "τί λέγεις, ὦ μιαρὰ κεφαλή; σὺ τὰ σαυτοῦ παιδί’ ἀξιώσεις ἐλεεῖν ἢ σὲ τούσδε, ἢ σπουδάζειν εἰς τὰ σά, τοὺς ὑπὸ σοῦ δημοσίᾳ προπεπηλακισμένους; σὺ μόνος τῶν ὄντων ἀνθρώπων ἐπὶ μὲν τοῦ βίου τοσαύτης ὑπερηφανίας πλήρης ὢν [πάντων ἀνθρώπων] ἔσει φανερώτατος, ὥστε καὶ πρὸς οὓς μηδέν ἐστί σοι πρᾶγμα, λυπεῖσθαι τὴν σὴν θρασύτητα καὶ φωνὴν καὶ [τὸ] σχῆμα καὶ τοὺς σοὺς ἀκολούθους καὶ πλοῦτον καὶ ὕβριν θεωροῦντας, ἐν δὲ τῷ κρίνεσθαι παραχρῆμ’ ἐλεηθήσει;", "st": "21.195"}, {"sp": "N", "t": "μεγάλην μέντἂν ἀρχήν, μᾶλλον δὲ τέχνην, εἴης εὑρηκώς, εἰ δύο τἀναντιώταθ’ ἑαυτοῖς ἐν οὕτω βραχεῖ χρόνῳ περὶ σαυτὸν δύναιο ποιεῖσθαι, φθόνον ἐξ ὧν ζῇς, καὶ ἐφ’ οἷς ἐξαπατᾷς ἔλεον. οὐκ ἔστιν οὐδαμόθεν σοι προσήκων ἔλεος οὐδὲ καθ’ ἕν, ἀλλὰ τοὐναντίον μῖσος καὶ φθόνος καὶ ὀργή· τούτων γὰρ ἄξια ποιεῖς. ἀλλ’ ἐπ’ ἐκεῖν’ ἐπάνειμι, ὅτι τοῦ δήμου κατηγορήσει καὶ τῆς ἐκκλησίας.", "st": "21.196"}, {"sp": "N", "t": "ὅταν οὖν τοῦτο ποιῇ, ἐνθυμεῖσθε παρ’ ὑμῖν αὐτοῖς, ἄνδρες δικασταί, ὅτι οὗτος τῶν μεθ’ ἑαυτοῦ στρατευσαμένων ἱππέων, ὅτ’ εἰς Ὄλυνθον διέβησαν, ἐλθὼν πρὸς ὑμᾶς εἰς τὴν ἐκκλησίαν κατηγόρει. πάλιν νῦν μείνας πρὸς τοὺς ἐξεληλυθότας τοῦ δήμου κατηγορήσει. πότερον οὖν ὑμεῖς, ἐάν τε μένητε ἐάν τ’ ἐξίητε, ὁμολογήσετ’ εἶναι τοιοῦτοι οἵους Μειδίας ὑμᾶς ἀποφαίνει, ἢ τοὐναντίον τοῦτον ἀεὶ καὶ πανταχοῦ θεοῖς ἐχθρὸν καὶ βδελυρόν; ἐγὼ μὲν οἶμαι τοῦτον τοιοῦτον· ὃν γὰρ οὐχ ἱππεῖς, οὐ συνάρχοντες, οὐ φίλοι δύνανται φέρειν, τί τοῦτον εἴπῃ τις;", "st": "21.197"}, {"sp": "N", "t": "ἐμοὶ μὲν νὴ τὸν Δία καὶ τὸν Ἀπόλλω καὶ τὴν Ἀθηνᾶν (εἰρήσεται γάρ, εἴτ’ ἄμεινον εἴτε μή,) ὅθ’ οὗτος ὡς ἀπήλλαγμαι περιιὼν ἐλογοποίει, ἔνδηλοί τινες ἦσαν ἀχθόμενοι τῶν πάνυ τούτῳ λαλούντων ἡδέως. καὶ νὴ Δί’ αὐτοῖς πολλὴ συγγνώμη· οὐ γάρ ἐστι φορητὸς ἅνθρωπος, ἀλλὰ καὶ πλουτεῖ μόνος καὶ λέγειν δύναται μόνος, καὶ πάντες εἰσὶ τούτῳ καθάρματα καὶ πτωχοὶ καὶ οὐδ’ ἄνθρωποι.", "st": "21.198"}, {"sp": "N", "t": "τὸν οὖν ἐπὶ ταύτης τῆς ὑπερηφανίας ὄντα, νῦν ἐὰν ἀποφύγῃ, τί ποιήσειν οἴεσθε; ἐξ ὅτου δὲ τοῦτ’ ἂν εἰδείητ’ ἐγὼ φράσω· εἰ τοῖς μετὰ τὴν χειροτονίαν τεκμηρίοις θεωρήσαιτε. τίς γάρ ἐστιν ὅστις καταχειροτονηθὲν αὐτοῦ, καὶ ταῦτ’ ἀσεβεῖν περὶ τὴν ἑορτήν, εἰ καὶ μηδεὶς ἄλλος ἐπῆν ἀγὼν ἔτι μηδὲ κίνδυνος, οὐκ ἂν ἐπ’ αὐτῷ τούτῳ κατέδυ καὶ μέτριον παρέσχεν ἑαυτὸν τόν γε δὴ μέχρι τῆς κρίσεως χρόνον, εἰ καὶ μὴ πάντα; οὐδεὶς ὅστις οὐκ ἄν.", "st": "21.199"}, {"sp": "N", "t": "ἀλλ’ οὐ Μειδίας, ἀλλ’ ἀπὸ τῆς ἡμέρας ταύτης λέγει, λοιδορεῖται, βοᾷ. χειροτονεῖταί τις· Μειδίας Ἀναγυράσιος προβέβληται. Πλουτάρχου προξενεῖ, τἀπόρρητ’ οἶδεν, ἡ πόλις αὐτὸν οὐ χωρεῖ. καὶ ταῦτα πάντα ποιεῖ δῆλον ὅτι οὐδὲν ἄλλ’ ἐνδεικνύμενος ἢ ὅτι “ἐγὼ οὐδὲν πέπονθ’ ὑπὸ τῆς καταχειροτονίας, οὐδὲ δέδοικ’ οὐδὲ φοβοῦμαι τὸν μέλλοντ’ ἀγῶνα.”", "st": "21.200"}, {"sp": "N", "t": "ὃς οὖν, ὦ ἄνδρες Ἀθηναῖοι, τὸ μὲν ὑμᾶς δεδιέναι δοκεῖν αἰσχρὸν ἡγεῖται, τὸ δὲ μηδὲν φροντίζειν ὑμῶν νεανικόν, τοῦτον οὐκ ἀπολωλέναι δεκάκις προσήκει; οὐδὲ γὰρ ἕξειν ὑμᾶς ὅ τι χρήσεσθ’ αὐτῷ νομίζει. πλούσιος, θρασύς, μέγα φρονῶν, μέγα φθεγγόμενος, βίαιος, ἀναιδής, —ποῦ ληφθήσεται, νῦν ἐὰν διακρούσηται;", "st": "21.201"}, {"sp": "N", "t": "ἀλλ’ ἔγωγε, εἰ μηδενὸς εἵνεκα τῶν ἄλλων, τῶν γε δημηγοριῶν ὧν ἑκάστοτε δημηγορεῖ, καὶ ἐν οἷς καιροῖς, τὴν μεγίστην ἂν αὐτὸν δικαίως οἶμαι δίκην δοῦναι. ἴστε γὰρ δήπου τοῦθ’ ὅτι, ἂν μέν τι τῶν δεόντων ἀπαγγελθῇ τῇ πόλει καὶ τοιοῦτον οἷον εὐφρᾶναι πάντας, οὐδαμοῦ πώποτε Μειδίας τῶν συνηδομένων οὐδὲ τῶν συγχαιρόντων ἐξητάσθη τῷ δήμῳ,", "st": "21.202"}, {"sp": "N", "t": "ἂν δέ τι φλαῦρον, ὃ μηδεὶς ἂν βούλοιτο τῶν ἄλλων, πρῶτος ἀνέστηκεν εὐθέως καὶ δημηγορεῖ, ἐπεμβαίνων τῷ καιρῷ καὶ τῆς σιωπῆς ἀπολαύων ἣν ἐπὶ τῷ περὶ τῶν συμβεβηκότων ἄχθεσθαι ποιεῖσθ’ ὑμεῖς· “τοιοῦτοι γάρ ἐστ’, ὦ ἄνδρες Ἀθηναῖοι· οὐ γὰρ ἐξέρχεσθε, οὐδ’ οἴεσθε δεῖν χρήματ’ εἰσφέρειν. εἶτα θαυμάζετ’ εἰ κακῶς τὰ πράγμαθ’ ὑμῖν ἔχει; ἔμ’ οἴεσθ’ ὑμῖν εἰσοίσειν, ὑμεῖς δὲ νεμεῖσθαι; ἔμ’ οἴεσθε τριηραρχήσειν, ὑμεῖς δ’ οὐκ ἐμβήσεσθαι;”", "st": "21.203"}, {"sp": "N", "t": "τοιαῦθ’ ὑβρίζων καὶ τὴν ἀπὸ τῆς ψυχῆς πικρίαν καὶ κακόνοιαν, ἣν κατὰ τῶν πολλῶν ὑμῶν ἔχων ἀφανῆ παρ’ ἑαυτῷ περιέρχεται, φανερὰν ἐπὶ τοῦ καιροῦ καθιστάς. δεῖ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὑμᾶς οὕτω νῦν, ὅταν ἐξαπατῶν καὶ φενακίζων ὀδύρηται καὶ κλάῃ καὶ δέηται, ταῦθ’ ὑποβάλλειν αὐτῷ· “τοιοῦτος γὰρ εἶ, Μειδία· ὑβριστὴς γὰρ εἶ, οὐκ ἐθέλεις ἔχειν παρὰ σεαυτῷ τὼ χεῖρε. εἶτα θαυμάζεις εἰ κακὸς κακῶς ἀπολεῖ; ἀλλὰ νομίζεις ἡμᾶς μὲν ἀνέξεσθαί σου, αὐτὸς δὲ τυπτήσειν; καὶ ἡμᾶς μὲν ἀποψηφιεῖσθαί σου, σὺ δ’ οὐ παύσεσθαι;”", "st": "21.204"}, {"sp": "N", "t": "καὶ βοηθοῦσιν οἱ λέγοντες ὑπὲρ αὐτοῦ, οὐχ οὕτω τούτῳ χαρίσασθαι μὰ τοὺς θεοὺς βουλόμενοι, ὡς ἐπηρεάζειν ἐμοὶ διὰ τὴν ἰδίαν ἔχθραν, ἣν οὗτος αὑτῷ πρὸς ἐμέ, ἄν τ’ ἐγὼ φῶ ἄν τε μὴ φῶ, φησὶν εἶναι καὶ βιάζεται, οὐκ ὀρθῶς· ἀλλὰ κινδυνεύει τὸ λίαν εὐτυχεῖν ἐνίοτ’ ἐπαχθεῖς ποιεῖν· ὅπου γὰρ ἐγὼ μὲν οὐδὲ πεπονθὼς κακῶς ἐχθρὸν εἶναί μοι τοῦτον ὁμολογῶ, οὗτος δ’ οὐδ’ ἀφιέντ’ ἀφίησιν, ἀλλὰ καὶ ἐπὶ τοῖς ἀλλοτρίοις ἀγῶσιν ἀπαντᾷ καὶ νῦν ἀναβήσεται μηδὲ τῆς κοινῆς τῶν νόμων ἐπικουρίας ἀξιῶν ἐμοὶ μετεῖναι, πῶς οὐχ οὗτος ἐπαχθής ἐστιν ἤδη καὶ μείζων ἢ καθ’ ὅσον ἡμῶν ἑκάστῳ συμφέρει;", "st": "21.205"}, {"sp": "N", "t": "ἔτι τοίνυν παρῆν, ὦ ἄνδρες Ἀθηναῖοι, καὶ καθῆτ’ Εὔβουλος ἐν τῷ θεάτρῳ, ὅθ’ ὁ δῆμος κατεχειροτόνησε Μειδίου, καὶ καλούμενος ὀνομαστὶ καὶ ἀντιβολοῦντος τούτου καὶ λιπαροῦντος, ὡς ὑμεῖς ἴστε, οὐκ ἀνέστη. καὶ μὴν εἰ μὲν μηδὲν ἠδικηκότος ἡγεῖτο τὴν προβολὴν γεγενῆσθαι, τότ’ ἔδει τόν γε φίλον δήπου συνειπεῖν καὶ βοηθῆσαι· εἰ δὲ καταγνοὺς ἀδικεῖν τότε, διὰ ταῦτ’ οὐχ ὑπήκουσεν, νῦν δ’, ὅτι προσκέκρουκεν ἐμοί, διὰ ταῦτα τοῦτον ἐξαιτήσεται, ὑμῖν οὐχὶ καλῶς ἔχει χαρίσασθαι·", "st": "21.206"}, {"sp": "N", "t": "μὴ γὰρ ἔστω μηδεὶς ἐν δημοκρατίᾳ τηλικοῦτος, ὥστε συνειπὼν τὸν μὲν ὑβρίσθαι, τὸν δὲ μὴ δοῦναι δίκην ποιῆσαι. ἀλλ’ εἰ κακῶς ἐμὲ βούλει ποιεῖν, Εὔβουλε, ὡς ἔγωγε μὰ τοὺς θεοὺς οὐκ οἶδ’ ἀνθ’ ὅτου, δύνασαι μὲν καὶ πολιτεύει, κατὰ τοὺς νόμους δ’ ἥντινα βούλει παρ’ ἐμοῦ δίκην λάμβανε, ὧν δ’ ἐγὼ παρὰ τοὺς νόμους ὑβρίσθην, μή μ’ ἀφαιροῦ τὴν τιμωρίαν. εἰ δ’ ἀπορεῖς ἐκείνως με κακῶς ποιῆσαι, εἴη ἂν καὶ τοῦτο σημεῖον τῆς ἐμῆς ἐπιεικείας, εἰ τοὺς ἄλλους ῥᾳδίως κρίνων ἐμὲ μηδὲν ἔχεις ἐφ’ ὅτῳ τοῦτο ποιήσεις.", "st": "21.207"}, {"sp": "N", "t": "πέπυσμαι τοίνυν καὶ Φιλιππίδην καὶ Μνησαρχίδην καὶ Διότιμον τὸν Εὐωνυμέα καὶ τοιούτους τινὰς πλουσίους καὶ τριηράρχους ἐξαιτήσεσθαι καὶ λιπαρήσειν παρ’ ὑμῶν αὐτόν, αὑτοῖς ἀξιοῦντας δοθῆναι τὴν χάριν ταύτην. περὶ ὧν οὐδὲν ἂν εἴποιμι πρὸς ὑμᾶς φλαῦρον ἐγώ (καὶ γὰρ ἂν μαινοίμην)· ἀλλ’ ἃ θεωρεῖν ὑμᾶς, ὅταν οὗτοι δέωνται, δεῖ καὶ λογίζεσθαι, ταῦτ’ ἐρῶ.", "st": "21.208"}, {"sp": "N", "t": "ἐνθυμεῖσθ’, ὦ ἄνδρες δικασταί, εἰ γένοιντο (ὃ μὴ γένοιτ’ οὐδ’ ἔσται) οὗτοι κύριοι τῆς πολιτείας μετὰ Μειδίου καὶ τῶν ὁμοίων τούτῳ, καί τις ὑμῶν τῶν πολλῶν καὶ δημοτικῶν ἁμαρτὼν εἴς τινα τούτων, μὴ τοιαῦθ’ οἷα Μειδίας εἰς ἐμέ, ἀλλ’ ὁτιοῦν ἄλλο, εἰς δικαστήριον εἰσίοι πεπληρωμένον ἐκ τούτων, τίνος συγγνώμης ἢ τίνος λόγου τυχεῖν ἂν οἴεσθε; ταχύ γ’ ἂν χαρίσαιντο, οὐ γάρ; ἢ δεηθέντι τῳ τῶν πολλῶν πρόσσχοιεν, ἀλλ’ οὐκ ἂν εὐθέως εἴποιεν “τὸν δὲ βάσκανον, τὸν δ’ ὄλεθρον, τοῦτον δ’ ὑβρίζειν, ἀναπνεῖν δέ; ὃν εἴ τις ἐᾷ ζῆν, ἀγαπᾶν δεῖ;”", "st": "21.209"}, {"sp": "N", "t": "μὴ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τούτοις τοῖς οὕτω χρησαμένοις ἂν ὑμῖν ἄλλως πως ἔχεθ’ ὑμεῖς, μηδὲ τὸν πλοῦτον μηδὲ τὴν δόξαν τὴν τούτων θαυμάζετε, ἀλλ’ ὑμᾶς αὐτούς. πολλὰ τούτοις ἀγάθ’ ἐστίν, ἃ τούτους οὐδεὶς κωλύει κεκτῆσθαι· μὴ τοίνυν μηδ’ οὗτοι τὴν ἄδειαν, ἣν ἡμῖν κοινὴν οὐσίαν οἱ νόμοι παρέχουσι, κωλυόντων κεκτῆσθαι.", "st": "21.210"}, {"sp": "N", "t": "οὐδὲν δεινὸν οὐδ’ ἐλεινὸν Μειδίας πείσεται, ἂν ἴσα κτήσηται τοῖς πολλοῖς ὑμῶν, οὓς νῦν ὑβρίζει καὶ πτωχοὺς ἀποκαλεῖ, ἃ δὲ νῦν περιόντ’ αὐτὸν ὑβρίζειν ἐπαίρει, περιαιρεθῇ. οὐδ’ οὗτοι δήπου ταῦθ’ ὑμῶν εἰσι δίκαιοι δεῖσθαι, “μὴ κατὰ τοὺς νόμους δικάσητ’, ἄνδρες δικασταί· μὴ βοηθήσητε τῷ πεπονθότι δεινά· μὴ εὐορκεῖτε· ἡμῖν δότε τὴν χάριν ταύτην.” ταῦτα γάρ, ἄν τι δέωνται περὶ τούτου, δεήσονται, κἂν μὴ ταῦτα λέγωσι τὰ ῥήματα.", "st": "21.211"}, {"sp": "N", "t": "ἀλλ’ εἴπερ εἰσὶ φίλοι καὶ δεινὸν εἰ μὴ πλουτήσει Μειδίας ἡγοῦνται, εἰσὶ μὲν εἰς τὰ μάλιστ’ αὐτοὶ πλούσιοι, καὶ καλῶς ποιοῦσι, χρήματα δ’ αὐτῷ παρ’ ἑαυτῶν δόντων, ἵν’ ὑμεῖς μὲν ἐφ’ οἷς εἰσήλθετ’ ὀμωμοκότες δικαίως ψηφίσησθε, οὗτοι δὲ παρ’ αὑτῶν τὰς χάριτας, μὴ μετὰ τῆς ὑμετέρας αἰσχύνης, ποιῶνται. εἰ δ’ οὗτοι χρήματ’ ἔχοντες μὴ πρόοιντ’ ἄν, πῶς ὑμῖν καλὸν τὸν ὅρκον προέσθαι;", "st": "21.212"}, {"sp": "N", "t": "πλούσιοι πολλοὶ συνεστηκότες, ὦ ἄνδρες Ἀθηναῖοι, τὸ δοκεῖν τινὲς εἶναι δι’ εὐπορίαν προσειληφότες, ὑμῶν παρίασι δεησόμενοι. τούτων μηδενί μ’, ὦ ἄνδρες Ἀθηναῖοι, προῆσθε, ἀλλ’ ὥσπερ ἕκαστος τούτων ὑπὲρ τῶν ἰδίᾳ συμφερόντων καὶ ὑπὲρ τούτου σπουδάσεται, οὕτως ὑμεῖς ὑπὲρ ὑμῶν αὐτῶν καὶ τῶν νόμων καὶ ἐμοῦ τοῦ ἐφ’ ὑμᾶς καταπεφευγότος σπουδάσατε, καὶ τηρήσατε τὴν γνώμην ταύτην ἐφ’ ἧς νῦν ἐστέ.", "st": "21.213"}, {"sp": "N", "t": "καὶ γὰρ εἰ μέν, ὦ ἄνδρες Ἀθηναῖοι, τόθ’ ὅτ’ ἦν ἡ προβολή, τὰ πεπραγμέν’ ὁ δῆμος ἀκούσας ἀπεχειροτόνησε Μειδίου, οὐκ ἂν ὁμοίως ἦν δεινόν· καὶ γὰρ μὴ γεγενῆσθαι, καὶ μὴ περὶ τὴν ἑορτὴν ἀδικήματα ταῦτ’ εἶναι, καὶ πόλλ’ ἂν εἶχέ τις αὑτὸν παραμυθήσασθαι.", "st": "21.214"}, {"sp": "N", "t": "νῦν δὲ τοῦτο καὶ πάντων ἄν μοι δεινότατον συμβαίη, εἰ παρ’ αὐτὰ τἀδικήμαθ’ οὕτως ὀργίλως καὶ πικρῶς καὶ χαλεπῶς ἅπαντες ἔχοντες [ἐφαίνεσθε], ὥστε Νεοπτολέμου καὶ Μνησαρχίδου καὶ Φιλιππίδου καί τινος τῶν σφόδρα τούτων πλουσίων δεομένων καὶ ἐμοῦ καὶ ὑμῶν, ἐβοᾶτε μὴ ἀφεῖναι, καὶ προσελθόντος μοι Βλεπαίου τοῦ τραπεζίτου, τηλικοῦτ’ ἀνεκράγετε, ὡς, τοῦτ’ ἐκεῖνο, χρήματά μου ληψομένου,", "st": "21.215"}, {"sp": "N", "t": "ὥστε μ’, ὦ ἄνδρες Ἀθηναῖοι, φοβηθέντα τὸν ὑμέτερον θόρυβον θοἰμάτιον προέσθαι καὶ μικροῦ γυμνὸν ἐν τῷ χιτωνίσκῳ γενέσθαι, φεύγοντ’ ἐκεῖνον ἕλκοντά με, καὶ μετὰ ταῦτ’ ἀπαντῶντες “ὅπως ἐπέξει τῷ μιαρῷ καὶ μὴ διαλύσει· θεάσονταί σε τί ποιήσεις Ἀθηναῖοι” τοιαῦτα λέγοντες· ἐπειδὴ κεχειροτόνηται μὲν ὕβρις τὸ πρᾶγμ’ εἶναι, ἐν ἱερῷ δ’ οἱ ταῦτα κρίνοντες καθεζόμενοι διέγνωσαν, διέμεινα δ’ ἐγὼ καὶ οὐ προὔδωκ’ οὔθ’ ὑμᾶς οὔτ’ ἐμαυτόν, τηνικαῦτ’ ἀποψηφιεῖσθ’ ὑμεῖς.", "st": "21.216"}, {"sp": "N", "t": "μηδαμῶς· πάντα γὰρ τὰ αἴσχιστ’ ἔνεστιν ἐν τῷ πράγματι. εἰμὶ δ’ οὐ τούτων ὑμῖν ἄξιος (πῶς γάρ, ὦ ἄνδρες Ἀθηναῖοι;) κρίνων ἄνθρωπον καὶ δοκοῦντα καὶ ὄντα βίαιον καὶ ὑβριστήν, ἡμαρτηκότ’ ἀσελγῶς ἐν πανηγύρει, μάρτυρας τῆς ὕβρεως τῆς ἑαυτοῦ πεποιημένον οὐ μόνον ὑμᾶς, ἀλλὰ καὶ τοὺς ἐπιδημήσαντας ἅπαντας τῶν Ἑλλήνων. ἤκουσεν ὁ δῆμος τὰ πεπραγμένα τούτῳ. τί οὖν; ὑμῖν καταχειροτονήσας παρέδωκεν.", "st": "21.217"}, {"sp": "N", "t": "οὐ τοίνυν οἷόν τ’ ἀφανῆ τὴν γνῶσιν ὑμῶν γενέσθαι, οὐδὲ λαθεῖν, οὐδ’ ἀνεξέταστον εἶναι τί ποθ’ ὡς ὑμᾶς τοῦ πράγματος ἐλθόντος ἔγνωτε· ἀλλ’ ἐὰν μὲν κολάσητε, δόξετε σώφρονες εἶναι καὶ καλοὶ κἀγαθοὶ καὶ μισοπόνηροι, ἂν δ’ ἀφῆτε, ἄλλου τινὸς ἡττῆσθαι. οὐ γὰρ ἐκ πολιτικῆς αἰτίας, οὐδ’ ὥσπερ Ἀριστοφῶν ἀποδοὺς τοὺς στεφάνους ἔλυσε τὴν προβολήν, ἀλλ’ ἐξ ὕβρεως, ἐκ τοῦ μηδὲν ἂν ὧν πεποίηκ’ ἀναλῦσαι δύνασθαι κρίνεται. πότερ’ οὖν τούτου γενομένου κρεῖττον αὖθις ἢ νυνὶ κολάσαι; ἐγὼ μὲν οἶμαι νῦν· κοινὴ γὰρ ἡ κρίσις, καὶ τἀδικήματα πάντ’ ἐφ’ οἷς νῦν κρίνεται κοινά.", "st": "21.218"}, {"sp": "N", "t": "ἔτι δ’ οὐκ ἔμ’ ἔτυπτεν, ἄνδρες Ἀθηναῖοι, μόνον οὗτος οὐδ’ ὕβριζε τῇ διανοίᾳ τότε ποιῶν οἷ’ ἐποίει, ἀλλὰ πάντας ὅσους περ ἂν οἴηταί τις ἧττον ἐμοῦ δύνασθαι δίκην ὑπὲρ αὑτῶν λαβεῖν. εἰ δὲ μὴ πάντες ἐπαίεσθε μηδὲ πάντες ἐπηρεάζεσθε χορηγοῦντες, ἴστε δήπου τοῦθ’ ὅτι οὐδ’ ἐχορηγεῖθ’ ἅμα πάντες, οὐδὲ δύναιτ’ ἄν ποθ’ ὑμᾶς οὐδεὶς ἅπαντας μιᾷ χειρὶ προπηλακίσαι.", "st": "21.219"}, {"sp": "N", "t": "ἀλλ’ ὅταν εἷς ὁ παθὼν μὴ λάβῃ δίκην, τόθ’ ἕκαστον αὐτὸν χρὴ προσδοκᾶν τὸν πρῶτον μετὰ ταῦτ’ ἀδικησόμενον γενήσεσθαι, καὶ μὴ παρορᾶν τὰ τοιαῦτα, μηδ’ ἐφ’ ἑαυτὸν ἐλθεῖν περιμένειν, ἀλλ’ ὡς ἐκ πλείστου φυλάττεσθαι. μισεῖ Μειδίας ἴσως ἐμέ, ὑμῶν δέ γ’ ἕκαστον ἄλλος τις. ἆρ’ οὖν συγχωρήσαιτ’ ἂν τοῦτον, ὅστις ἐστὶν ἕκαστος ὁ μισῶν, κύριον γενέσθαι τοῦ ταῦθ’ ἅπερ οὗτος ἐμὲ ὑμῶν ἕκαστον ποιῆσαι; ἐγὼ μὲν οὐκ οἶμαι. μὴ τοίνυν μηδ’ ἔμ’, ὦ ἄνδρες Ἀθηναῖοι, προῆσθε τούτῳ.", "st": "21.220"}, {"sp": "N", "t": "ὁρᾶτε δέ· αὐτίκα δὴ μάλα, ἐπειδὰν ἀναστῇ τὸ δικαστήριον, εἷς ἕκαστος ὑμῶν, ὁ μὲν θᾶττον ἴσως, ὁ δὲ σχολαίτερον, οἴκαδ’ ἄπεισιν οὐδὲν φροντίζων οὐδὲ μεταστρεφόμενος οὐδὲ φοβούμενος, οὔτ’ εἰ φίλος οὔτ’ εἰ μὴ φίλος αὑτῷ συντεύξεταί τις, οὐδέ γ’ εἰ μέγας ἢ μικρός, [ἢ] ἰσχυρὸς ἢ ἀσθενής, οὐδὲ τῶν τοιούτων οὐδέν. τί δήποτε; ὅτι τῇ ψυχῇ τοῦτ’ οἶδε καὶ θαρρεῖ καὶ πεπίστευκε τῇ πολιτείᾳ, μηδέν’ ἕλξειν μηδ’ ὑβριεῖν μηδὲ τυπτήσειν.", "st": "21.221"}, {"sp": "N", "t": "εἶτ’ ἐφ’ ἧς ἀδείας αὐτοὶ πορεύεσθε, ταύτην οὐ βεβαιώσαντες ἐμοὶ βαδιεῖσθε; καὶ τίνι χρή με λογισμῷ περιεῖναι ταῦτα παθόντα, εἰ περιόψεσθέ με νῦν ὑμεῖς; θάρρει νὴ Δία, φήσειέ τις ἄν· οὐ γὰρ ἔτ’ οὐδὲν ὑβρισθήσει. ἐὰν δέ, τότ’ ὀργιεῖσθε, νῦν ἀφέντες; μηδαμῶς, ὦ ἄνδρες δικασταί, μὴ προδῶτε μήτ’ ἐμὲ μήθ’ ὑμᾶς αὐτοὺς μήτε τοὺς νόμους.", "st": "21.222"}, {"sp": "N", "t": "καὶ γὰρ αὐτὸ τοῦτ’ εἰ ’θέλοιτε σκοπεῖν καὶ ζητεῖν, τῷ ποτ’ εἰσὶν ὑμῶν οἱ ἀεὶ δικάζοντες ἰσχυροὶ καὶ κύριοι τῶν ἐν τῇ πόλει πάντων, ἐάν τε διακοσίους ἐάν τε χιλίους ἐάν θ’ ὁποσουσοῦν ἡ πόλις καθίσῃ, οὔτε τῷ μεθ’ ὅπλων εἶναι συντεταγμένοι μόνοι τῶν ἄλλων πολιτῶν, εὕροιτ’ ἄν, οὔτε τῷ τὰ σώματ’ ἄριστ’ ἔχειν καὶ μάλιστ’ ἰσχύειν [τοὺς δικάζοντας], οὔτε τῷ τὴν ἡλικίαν εἶναι νεώτατοι, οὔτε τῶν τοιούτων οὐδενί, ἀλλὰ τῷ τοὺς νόμους ἰσχύειν.", "st": "21.223"}, {"sp": "N", "t": "ἡ δὲ τῶν νόμων ἰσχὺς τίς ἐστιν; ἆρ’ ἐάν τις ὑμῶν ἀδικούμενος ἀνακράγῃ, προσδραμοῦνται καὶ παρέσονται βοηθοῦντες; οὔ· γράμματα γὰρ γεγραμμέν’ ἐστί, καὶ οὐχὶ δύναιντ’ ἂν τοῦτο ποιῆσαι. τίς οὖν ἡ δύναμις αὐτῶν ἐστιν; ὑμεῖς ἐὰν βεβαιῶτ’ αὐτοὺς καὶ παρέχητε κυρίους ἀεὶ τῷ δεομένῳ. οὐκοῦν οἱ νόμοι θ’ ὑμῖν εἰσιν ἰσχυροὶ καὶ ὑμεῖς τοῖς νόμοις.", "st": "21.224"}, {"sp": "N", "t": "δεῖ τοίνυν τούτοις βοηθεῖν ὁμοίως ὥσπερ ἂν αὑτῷ τις ἀδικουμένῳ, καὶ τὰ τῶν νόμων ἀδικήματα κοινὰ νομίζειν, ἐφ’ ὅτου περ ἂν λαμβάνηται, καὶ μήτε λῃτουργίας μήτ’ ἔλεον μήτ’ ἄνδρα μηδένα μήτε τέχνην μηδεμίαν εὑρῆσθαι, δι’ ὅτου παραβάς τις τοὺς νόμους οὐ δώσει δίκην.", "st": "21.225"}, {"sp": "N", "t": "ὑμῶν οἱ θεώμενοι τοῖς Διονυσίοις εἰσιόντ’ εἰς τὸ θέατρον τοῦτον ἐσυρίττετε καὶ ἐκλώζετε, καὶ πάνθ’ ἃ μίσους ἐστὶ σημεῖ’ ἐποιεῖτε, οὐδὲν ἀκηκοότες πω περὶ αὐτοῦ παρ’ ἐμοῦ. εἶτα πρὶν μὲν ἐλεγχθῆναι τὸ πρᾶγμα, ὠργίζεσθε, προὐκαλεῖσθ’ ἐπὶ τιμωρίαν τὸν παθόντα, ἐκροτεῖθ’ ὅτε προὐβαλόμην αὐτὸν ἐν τῷ δήμῳ·", "st": "21.226"}, {"sp": "N", "t": "ἐπειδὴ δ’ ἐξελήλεγκται, καὶ προκατέγνωκεν ὁ δῆμος τούτου εἰς ἱερὸν καθεζόμενος, καὶ τἄλλα προσεξήτασται τὰ πεπραγμένα τῷ μιαρῷ τούτῳ, καὶ δικάσοντες εἰλήχατε, καὶ πάντ’ ἐστὶν ἐν ὑμῖν μιᾷ ψήφῳ διαπράξασθαι, νῦν ὀκνήσετ’ ἐμοὶ βοηθῆσαι, τῷ δήμῳ χαρίσασθαι, τοὺς ἄλλους σωφρονίσαι, μετὰ πολλῆς ἀσφαλείας αὐτοὶ τὸ λοιπὸν διάγειν, παράδειγμα ποιήσαντες τοῦτον τοῖς ἄλλοις;", "st": "21.227"}, {"sp": "N", "t": "πάντων οὖν εἵνεκα τῶν εἰρημένων, καὶ μάλιστα τοῦ θεοῦ χάριν περὶ οὗ τὴν ἑορτὴν ἀσεβῶν οὗτος ἑάλωκεν, τὴν ὁσίαν καὶ δικαίαν θέμενοι ψῆφον τιμωρήσασθε τοῦτον.", "st": "21.227"}, {"sp": "HDR", "t": "Κατὰ Ἀνδροτίωνος παρανόμων", "st": "22"}, {"sp": "N", "t": "ὅπερ Εὐκτήμων, ὦ ἄνδρες δικασταί, παθὼν ὑπ’ Ἀνδροτίωνος κακῶς, ἅμα τῇ τε πόλει βοηθεῖν οἴεται δεῖν καὶ δίκην ὑπὲρ αὑτοῦ λαβεῖν, τοῦτο κἀγὼ πειράσομαι ποιεῖν, ἐὰν ἄρ’ οἷός τ’ ὦ. συμβέβηκε δέ, πολλὰ καὶ δεινὰ καὶ παρὰ πάντας τοὺς νόμους Εὐκτήμονος ὑβρισμένου, ἐλάττω ταῦτ’ εἶναι τῶν ἐμοὶ γεγενημένων δι’ Ἀνδροτίωνος πραγμάτων. οὗτος μέν γ’ εἰς χρήματα καὶ τὸ παρ’ ὑμῶν ἀδίκως ἐκπεσεῖν ἐπεβουλεύθη· ἐμὲ δ’ οὐδ’ ἂν ἐδέξατο τῶν ὄντων ἀνθρώπων οὐδὲ εἷς, εἰ τὰ κατασκευασθένθ’ ὑπὸ τούτου παρ’ ὑμῖν ἐπιστεύθη.", "st": "22.1"}, {"sp": "N", "t": "αἰτιασάμενος γάρ με, ἃ καὶ λέγειν ἂν ὀκνήσειέ τις, εἰ μὴ τύχοι προσόμοιος ὢν τούτῳ, τὸν πατέρ’ ὡς ἀπέκτον’ ἐγὼ τὸν ἐμαυτοῦ, καὶ κατασκευάσας ἀσεβείας γραφὴν οὐκ ἐπ’ ἐμέ, ἀλλ’ ἐπὶ τὸν θεῖόν μου, γράψας ἀσεβεῖν ἐμοὶ συνιόντ’ εἰς ταὐτὸν ὡς πεποιηκότι ταῦτα, εἰς ἀγῶνα κατέστησεν· ὃν εἰ συνέβη τόθ’ ἁλῶναι, τίς ἂν ἀθλιώτερ’ ἐμοῦ πεπονθὼς ἦν ὑπὸ τούτου; τίς γὰρ ἂν ἢ φίλος ἢ ξένος εἰς ταὐτό ποτ’ ἐλθεῖν ἠθέλησεν ἐμοί; τίς δ’ ἂν εἴασε πόλις που παρ’ ἑαυτῇ γενέσθαι τὸν τὸ τοιοῦτ’ ἀσέβημα δοκοῦντ’ εἰργάσθαι; οὐκ ἔστιν οὐδὲ μία.", "st": "22.2"}, {"sp": "N", "t": "ἐγὼ τοίνυν ταῦτα μὲν οὐ παρὰ μικρὸν ἀγωνιζόμενος παρ’ ὑμῖν ἀπελυσάμην, ἀλλ’ ὥστε τὸ πέμπτον μέρος μὴ λαβεῖν τούτους τῶν ψήφων· τουτονὶ δὲ μεθ’ ὑμῶν πειράσομαι καὶ νῦν καὶ τὸν ἄλλον ἅπαντ’ ἀμύνεσθαι χρόνον. καὶ περὶ μὲν τῶν ἰδίων ἔχων ἔτι πολλὰ λέγειν ἐάσω· περὶ δ’ ὧν οἴσετε τὴν ψῆφον νυνὶ καὶ περὶ ὧν οὗτος δημοσίᾳ πεπολιτευμένος οὐκ ὀλίγ’ ὑμᾶς ἔβλαψεν, ἅ μοι παραλείπειν Εὐκτήμων ἐδόκει, βέλτιον δ’ ὑμᾶς ἀκοῦσαι, ταῦτα διεξελθεῖν ἐν βραχέσιν πειράσομαι.", "st": "22.3"}, {"sp": "N", "t": "ἐγὼ γὰρ εἰ μὲν ἑώρων τιν’ ἁπλῆν τούτῳ περὶ ὧν φεύγει πρὸς ὑμᾶς οὖσαν ἀπολογίαν, οὐκ ἂν ἐποιούμην περὶ αὐτῆς μνείαν οὐδεμίαν. νῦν δ’ οἶδα σαφῶς ὅτι οὗτος ἁπλοῦν μὲν οὐδὲ δίκαιον οὐδὲν ἂν εἰπεῖν ἔχοι, ἐξαπατᾶν δ’ ὑμᾶς πειράσεται πλάττων καὶ παράγων πρὸς ἕκαστα τούτων κακούργους λόγους. ἔστι γάρ, ὦ ἄνδρες Ἀθηναῖοι, τεχνίτης τοῦ λέγειν καὶ πάντα τὸν βίον ἐσχόλακεν [ἐν] τούτῳ. ὑπὲρ οὖν τοῦ μὴ παρακρουσθέντας ὑμᾶς ἐναντία μὲν τοῖς ὀμωμοσμένοις πεισθῆναι ψηφίσασθαι, ἀφεῖναι δὲ τοῦτον ὃν ὑμῖν πολλῶν ἕνεκ’ ἄξιον κολάσαι, προσέχετε τὸν νοῦν οἷς ἐρῶ, ἵν’ ἀκούσαντες ἐμοῦ πρὸς ἕκαστον τῶν ὑπὸ τούτου ῥηθησομένων ἔχηθ’ ὑπολαμβάνειν ἃ δεῖ.", "st": "22.4"}, {"sp": "N", "t": "ἔστι γὰρ εἷς μὲν ὃν οἴεται τεχνικῶς ἔχειν αὐτῷ λόγος περὶ τοῦ ἀπροβουλεύτου. νόμος ἐστί, φησίν, ἐὰν ἀξίως ἡ βουλὴ δοκῇ βουλεῦσαι δωρειᾶς, διδόναι τὸν δῆμον τὴν δωρειὰν αὐτῇ. ταῦτ’ ἐπήρετο, φησίν, ὁ ἐπιστάτης, διεχειροτόνησεν ὁ δῆμος, ἔδοξεν. οὐδὲν δεῖ, φησί, προβουλεύματος ἐνταῦθα· κατὰ γὰρ νόμον ἦν τὰ γιγνόμενα. ἐγὼ δ’ αὐτὸ τοὐναντίον οἴομαι, νομίζω δὲ καὶ ὑμῖν συνδόξειν, περὶ τούτων ⟨δεῖν⟩ τὰ προβουλεύματ’ ἐκφέρειν μόνων περὶ ὧν κελεύουσιν οἱ νόμοι, ἐπεὶ περὶ ὧν γε μὴ κεῖνται νόμοι οὐδὲ γράφειν τὴν ἀρχὴν προσήκει οὐδὲ ἓν δήπου.", "st": "22.5"}, {"sp": "N", "t": "φησὶ τοίνυν τοῦτον ἁπάσας τὸν τρόπον εἰληφέναι τὰς βουλάς, ὅσαι πώποτ’ ἔχουσι παρ’ ὑμῶν δωρειάν, καὶ οὐδὲ μιᾷ γεγενῆσθαι προβούλευμα πώποτε. ἐγὼ δ’ οἴομαι μὲν οὐχὶ λέγειν αὐτὸν ἀληθῆ, μᾶλλον δ’ οἶδα σαφῶς· οὐ μὴν ἀλλ’ εἰ τοῦτο τοιοῦτ’ ἐστὶν τὰ μάλιστα, ὁ νόμος δὲ λέγει τἀναντία, οὐχ ὅτι πολλάκις ἡμάρτηται δήπου πρότερον, διὰ τοῦτ’ ἐπεξαμαρτητέον ἐστὶ καὶ νῦν, ἀλλὰ τοὐναντίον ἀρκτέον, ὡς ὁ νόμος κελεύει, τὰ τοιαῦτα ποιεῖν ἀναγκάζειν ἀπὸ σοῦ πρώτου.", "st": "22.6"}, {"sp": "N", "t": "σὺ δὴ μὴ λέγ’ ὡς γέγονεν τοῦτο πολλάκις, ἀλλ’ ὡς οὕτω προσήκει γίγνεσθαι. οὐ γὰρ εἴ τι πώποτε μὴ κατὰ τοὺς νόμους ἐπράχθη, σὺ δὲ τοῦτ’ ἐμιμήσω, διὰ τοῦτ’ ἀποφεύγοις ἂν δικαίως, ἀλλὰ πολλῷ μᾶλλον ἁλίσκοιο· ὥσπερ γὰρ εἴ τις ἐκείνων προήλω, σὺ τάδ’ οὐκ ἂν ἔγραψας, οὕτως, ἂν σὺ νῦν δίκην δῷς, ἄλλος οὐ γράψει.", "st": "22.7"}, {"sp": "N", "t": "περὶ τοίνυν τοῦ νόμου τοῦ διαρρήδην οὐκ ἐῶντος ἐξεῖναι μὴ ποιησαμένῃ τῇ βουλῇ τὰς τριήρεις αἰτῆσαι τὴν δωρειάν, ἄξιόν ἐστιν ἀκοῦσαι τὴν ἀπολογίαν ἣν ποιήσεται, καὶ θεωρῆσαι τὴν ἀναίδειαν τοῦ τρόπου δι’ ὧν ἐγχειρεῖ λέγειν. ὁ νόμος, φησίν, οὐκ ἐᾷ τὴν βουλὴν αἰτῆσαι τὴν δωρειάν, ἐὰν μὴ ποιήσηται τὰς τριήρεις· ὁμολογῶ. δοῦναι δέ γ’ οὐδαμοῦ, φησί, κωλύει τὸν δῆμον. ἐγὼ δ’, εἰ μὲν ἔδωκ’ αἰτούσῃ, παρὰ τὸν νόμον εἴρηκα· εἰ δὲ μὴ πεποίημαι μνείαν περὶ τῶν νεῶν ἐν ὅλῳ τῷ ψηφίσματι, ἀλλ’ ἕτερ’ ἄττα λέγω δι’ ἃ τὴν βουλὴν στεφανῶ, πῶς παρὰ τὸν νόμον εἴρηκα;", "st": "22.8"}, {"sp": "N", "t": "ἔστι δὴ πρὸς ταῦτ’ οὐ χαλεπὸν τὰ δίκαι’ ὑμῖν ἀντειπεῖν, ὅτι πρῶτον μὲν οἱ προεδρεύοντες τῆς βουλῆς καὶ ὁ ταῦτ’ ἐπιψηφίζων ἐπιστάτης ἠρώτων καὶ διαχειροτονίαν ἐδίδοσαν, ὅτῳ δοκεῖ δωρειᾶς ἀξίως ἡ βουλὴ βεβουλευκέναι καὶ ὅτῳ μή· καίτοι τούς γε μὴ αἰτοῦντας μηδὲ λαβεῖν ἀξιοῦντας τὴν ἀρχὴν οὐδ’ ἐπερωτᾶν προσῆκεν.", "st": "22.9"}, {"sp": "N", "t": "πρὸς τοίνυν τούτοις ἔστιν ἃ Μειδίου κατηγοροῦντος τῆς βουλῆς καὶ ἄλλων τινῶν, ἀναπηδῶντες οἱ βουλευταὶ ἐδέοντο μὴ σφᾶς ἀφελέσθαι τὴν δωρειάν. καὶ ταῦτ’ οὐ παρ’ ἐμοῦ δεῖ πυθέσθαι τοὺς δικάζοντας ὑμᾶς, ἀλλ’ αὐτοὶ παρόντες ἴστ’ ἐν τῷ δήμῳ γενόμενα. ὥσθ’ ὅταν μὲν μὴ φῇ τὴν βουλὴν αἰτεῖν, ταῦθ’ ὑπολαμβάνετε· ὅτι δ’ οὐδὲ τὸν δῆμον ἐᾷ διδόναι μὴ ποιησαμένοις τὰς ναῦς ὁ νόμος, καὶ τοῦτ’ ἐπιδείξω.", "st": "22.10"}, {"sp": "N", "t": "διὰ ταῦτα γάρ, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον ἔχει τὸν τρόπον ὁ νόμος, μὴ ἐξεῖναι τῇ βουλῇ μὴ ποιησαμένῃ τὰς τριήρεις αἰτῆσαι τὴν δωρειάν, ἵνα μηδὲ πεισθῆναι μηδ’ ἐξαπατηθῆναι γένοιτ’ ἐπὶ τῷ δήμῳ. οὐ γὰρ ᾤετο δεῖν ὁ τιθεὶς τὸν νόμον ἐπὶ τῇ τῶν λεγόντων δυνάμει τὸ πρᾶγμα καταστῆσαι, ἀλλ’ ὃ δίκαιον ἦν εὑρεῖν ἅμα καὶ συμφέρον τῷ δήμῳ, νόμῳ τετάχθαι. τὰς τριήρεις οὐ πεποίησαι; μὴ τοίνυν αἴτει τὴν δωρειάν. ὅπου δ’ αἰτεῖν οὐκ ἐᾷ, πῶς οὐ σφόδρα δοῦναί γε κωλύει;", "st": "22.11"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, κἀκεῖνο ἐξετάσαι, τί δήποτε, ἂν τἄλλα πάνθ’ ἡ βουλὴ καλῶς βουλεύσῃ καὶ μηδεὶς ἔχῃ μηδὲν ἐγκαλέσαι, τὰς δὲ τριήρεις μὴ ποιήσηται, τὴν δωρειὰν οὐκ ἔξεστιν αἰτῆσαι. εὑρήσετε γὰρ τοῦτο τὸ ἰσχυρὸν ὑπὲρ τοῦ δήμου κείμενον. οἶμαι γὰρ ἂν μηδέν’ ἀντειπεῖν ὡς οὐχ, ὅσα πώποτε τῇ πόλει γέγον’ ἢ νῦν ἔστ’ ἀγάθ’ ἢ θάτερα, ἵνα μηδὲν εἴπω φλαῦρον, ἐκ τῆς τῶν τριήρων τὰ μὲν κτήσεως, τὰ δ’ ἀπουσίας γέγονεν.", "st": "22.12"}, {"sp": "N", "t": "οἷον πολλὰ μὲν ἄν τις ἔχοι λέγειν καὶ παλαιὰ καὶ καινά· ἃ δ’ οὖν πᾶσι μάλιστ’ ἀκοῦσαι γνώριμα, τοῦτο μέν, εἰ βούλεσθε, οἱ τὰ προπύλαια καὶ τὸν παρθενῶν’ οἰκοδομήσαντες ἐκεῖνοι καὶ τἄλλ’ ἀπὸ τῶν βαρβάρων ἱερὰ κοσμήσαντες, ἐφ’ οἷς φιλοτιμούμεθα πάντες εἰκότως, ἴστε δήπου τοῦτ’ ἀκοῇ, ὅτι τὴν πόλιν ἐκλιπόντες καὶ κατακλεισθέντες εἰς Σαλαμῖνα, ἐκ τοῦ τριήρεις ἔχειν πάντα μὲν τὰ σφέτερ’ αὐτῶν καὶ τὴν πόλιν τῇ ναυμαχίᾳ νικήσαντες ἔσωσαν, πολλῶν δὲ καὶ μεγάλων ἀγαθῶν τοῖς ἄλλοις Ἕλλησι κατέστησαν αἴτιοι, ὧν οὐδ’ ὁ χρόνος τὴν μνήμην ἀφελέσθαι δύναται.", "st": "22.13"}, {"sp": "N", "t": "εἶεν· ἀλλ’ ἐκεῖνα μὲν ἀρχαῖα καὶ παλαιά. ἀλλ’ ἃ πάντες ἑοράκατε, ἴσθ’ ὅτι πρώην Εὐβοεῦσιν ἡμερῶν τριῶν ἐβοηθήσατε καὶ Θηβαίους ὑποσπόνδους ἀπεπέμψατε. ἆρ’ οὖν ταῦτ’ ἐπράξατ’ ἂν οὕτως ὀξέως, εἰ μὴ ναῦς εἴχετε καινὰς ἐν αἷς ἐβοηθήσατε; ἀλλ’ οὐκ ἂν ἐδύνασθε. ἄλλα πόλλ’ ἔχοι τις ἂν εἰπεῖν ἃ τῇ πόλει γέγον’ ἐκ τοῦ ταύτας κατεσκευάσθαι καλῶς ἀγαθά.", "st": "22.14"}, {"sp": "N", "t": "εἶεν· ἐκ δὲ τοῦ κακῶς πόσα δεινά; τὰ μὲν πόλλ’ ἐάσω· ἀλλ’ ἐπὶ τοῦ Δεκελεικοῦ πολέμου (τῶν γὰρ ἀρχαίων ἕν, ὃ πάντες ἐμοῦ μᾶλλον ἐπίστασθε, ὑπομνήσω) πολλῶν καὶ δεινῶν ἀτυχημάτων συμβάντων τῇ πόλει οὐ πρότερον τῷ πολέμῳ παρέστησαν πρὶν τὸ ναυτικὸν αὐτῶν ἀπώλετο. καὶ τί δεῖ τὰ παλαιὰ λέγειν; τὸν τελευταῖον γὰρ ἴστε [τὸν] πρὸς Λακεδαιμονίους πόλεμον, ὅτε μὲν ναῦς οὐκ ἐδοκεῖτ’ ἀποστεῖλαι δυνήσεσθαι, πῶς διέκειθ’ ἡ πόλις· ἴστ’ ὀρόβους ὄντας ὠνίους. ἐπειδὴ δ’ ἀπεστείλατε, εἰρήνης ἐτύχεθ’ ὁποίας τινὸς ἐβούλεσθε.", "st": "22.15"}, {"sp": "N", "t": "ὥστε δικαίως, ὦ ἄνδρες Ἀθηναῖοι, τηλικαύτην ἐχουσῶν ῥοπὴν ἐφ’ ἑκάτερα τῶν τριήρων, τοῦτον ὅρον τεθήκατε τῇ βουλῇ, πότερ’ αὐτὴν δεῖ λαβεῖν τὴν δωρειὰν ἢ οὔ. εἰ γὰρ πάντα τἄλλα διοικήσειε καλῶς, δι’ ὧν δὲ τό τ’ ἐξ ἀρχῆς ταῦτ’ ἐκτησάμεθα καὶ νῦν σῴζομεν, ταύτας μὴ ποιήσαιτο, τὰς τριήρεις λέγω, οὐδὲν ἐκείνων ὄφελος· τὴν γὰρ τῶν ὅλων σωτηρίαν πρῶτον ὑπάρχειν δεῖ παρεσκευασμένην τῷ δήμῳ. οὗτος τοίνυν εἰς τοῦτ’ ἐλήλυθε τοῦ νομίζειν αὑτῷ καὶ λέγειν καὶ γράφειν ἐξεῖναι πᾶν ὅ τι ἂν βούληται, ὥστε βεβουλευκυίας μὲν τἄλλ’ ὃν τρόπον ὑμεῖς ἀκούετε τῆς βουλῆς, οὐ πεποιημένης δὲ τὰς τριήρεις, γέγραφεν δοῦναι τὴν δωρειάν.", "st": "22.16"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς μὲν οὐ παρὰ τὸν νόμον ἐστίν, οὔτ’ ἂν οὗτος ἔχοι λέγειν οὔθ’ ὑμεῖς πεισθείητε· ἀκούω δ’ αὐτὸν τοιοῦτον ἐρεῖν τιν’ ἐν ὑμῖν λόγον, ὡς οὐχ ἡ βουλὴ γέγον’ αἰτία τοῦ μὴ πεποιῆσθαι τὰς ναῦς, ἀλλ’ ὁ τῶν τριηροποιικῶν ταμίας ἀποδρὰς ᾤχετ’ ἔχων πένθ’ ἡμιτάλαντα, καὶ τὸ πρᾶγμ’ ἀτύχημα συμβέβηκεν. ἐγὼ δὲ πρῶτον μὲν αὐτὸ τοῦτο θαυμάζω, εἰ στεφανοῦν ἐπὶ τοῖς ἠτυχημένοις ἠξίου τὴν βουλήν· τῶν κατορθουμένων γὰρ ἔγωγ’ ἡγούμην ἔργων τὰς τοιαύτας ὡρίσθαι τιμάς· ἔπειτα δὲ κἀκεῖν’ ἔτι βούλομαι φράσαι πρὸς ὑμᾶς.", "st": "22.17"}, {"sp": "N", "t": "οὔ φημι δίκαιον εἶναι περὶ ἀμφοῖν λέγειν, καὶ ὡς οὐ παρὰ τὸν νόμον ἡ δωρειὰ δέδοται, καὶ ὡς οὐ διὰ τὴν βουλὴν οὐκ εἰσὶν αἱ τριήρεις. εἰ μὲν γὰρ διδόναι καὶ μὴ ποιησαμένῃ προσήκει, τί τοῦτο δεῖ λέγειν, δι’ ὅντινα δήποτ’ οὐ πεποίηνται; εἰ δ’ οὐκ ἔξεστι, τί μᾶλλον, ἂν διὰ τὸν δεῖν’ ἢ τὸν δεῖν’ ἐπιδείξῃ μὴ πεποιημένας, ἐκείνῃ προσῆκε λαβεῖν;", "st": "22.18"}, {"sp": "N", "t": "χωρὶς δὲ τούτων ἔμοιγε δοκοῦσιν αἵρεσιν ὑμῖν οἱ τοιοῦτοι λόγοι διδόναι, πότερ’ οἴεσθε δεῖν προφάσεις καὶ λόγους ἀκούειν τῶν ἀδικούντων ὑμᾶς ἢ ναῦς κεκτῆσθαι. εἰ μὲν γὰρ τούτου ταῦτ’ ἀποδέξεσθε, ἔσται δῆλον ἁπάσαις ταῖς βουλαῖς ὅτι δεῖ πρόφασιν πιθανὴν ἐξευρεῖν πρὸς ὑμᾶς, οὐχὶ τριήρεις ποιήσασθαι· ἐκ δὲ τούτου τὰ μὲν χρήματ’ ἀναλωθήσεται, ναῦς δ’ οὐχ ἕξεθ’ ὑμεῖς.", "st": "22.19"}, {"sp": "N", "t": "ἐὰν δ’, ὡς ὁ νόμος λέγει καὶ δεῖ τοὺς ὀμωμοκότας, πικρῶς καὶ ἁπλῶς τὰς μὲν προφάσεις ἀνέλητε, φανῆτε δ’ ἀφῃρημένοι τὴν δωρειὰν ὅτι τὰς ναῦς οὐ πεποίηνται, πάντες, ὦ ἄνδρες Ἀθηναῖοι, πεποιημένας ὑμῖν παραδώσουσι τὰς τριήρεις, πάντα τἄλλα παρ’ ὑμῖν ἑορακότες ἀσθενέστερα τοῦ νόμου γεγενημένα. ὅτι τοίνυν οὐδ’ αἴτιος ἄλλος οὐδεὶς ἀνθρώπων ἐστὶ τοῦ μὴ πεποιῆσθαι τὰς ναῦς, τοῦτο σαφῶς ὑμῖν ἐπιδείξω· ἀνελοῦσα γὰρ ἡ βουλὴ τὸν νόμον, τοῦτον ἐχειροτόνησεν αὐτή.", "st": "22.20"}, {"sp": "N", "t": "ἔτι τοίνυν ἐπιχειρεῖ λέγειν περὶ τοῦ τῆς ἑταιρήσεως νόμου, ὡς ὑβρίζομεν ἡμεῖς καὶ βλασφημίας οὐχὶ προσηκούσας κατ’ αὐτοῦ ποιούμεθα. καὶ φησὶ δεῖν ἡμᾶς, εἴπερ ἐπιστεύομεν εἶναι ταῦτ’ ἀληθῆ, πρὸς τοὺς θεσμοθέτας ἀπαντᾶν, ἵν’ ἐκεῖ περὶ χιλιῶν ἐκινδυνεύομεν, εἰ καταψευδόμενοι ταῦτ’ ἐφαινόμεθα· νῦν δὲ φενακίζειν αἰτίας καὶ λοιδορίας κενὰς ποιουμένους, καὶ ἐνοχλεῖν οὐ δικασταῖς τούτων οὖσιν ὑμῖν.", "st": "22.21"}, {"sp": "N", "t": "ἐγὼ δ’ οἴομαι δεῖν ὑμᾶς πρῶτον μὲν ἐκεῖνο λογίζεσθαι παρ’ ὑμῖν αὐτοῖς, ὅτι πάμπολυ λοιδορία τε καὶ αἰτία κεχωρισμένον ἐστὶν ἐλέγχου. αἰτία μὲν γάρ ἐστιν, ὅταν τις ψιλῷ χρησάμενος λόγῳ μὴ παράσχηται πίστιν ὧν λέγει, ἔλεγχος δέ, ὅταν ὧν ἂν εἴπῃ τις καὶ τἀληθὲς ὁμοῦ δείξῃ. ἔστι τοίνυν ἀνάγκη τοὺς ἐλέγχοντας ἢ τεκμήρια δεικνύναι δι’ ὧν ἐμφανιοῦσι τὸ πιστὸν ὑμῖν, ἢ τὰ εἰκότα φράζειν, ἢ μάρτυρας παρέχεσθαι· οὐ γὰρ οἷόν τ’ ἐνίων αὐτόπτας ἐστὶ καταστῆσαι, ἀλλ’ ἐὰν ἐπιδεικνύῃ τίς τι τούτων, ἱκανὸν νομίζετ’ ἔλεγχον ἔχειν ὑμεῖς εἰκότως τῆς ἀληθείας ἑκάστοτε.", "st": "22.22"}, {"sp": "N", "t": "ἡμεῖς τοίνυν οὐκ ἐκ λόγων εἰκότων οὐδὲ τεκμηρίων, ἀλλὰ παρ’ οὗ μάλιστα δίκην ἔστι λαβεῖν τούτῳ, ταῦτ’ ἐπιδείκνυμεν—ἄνδρα παρεσχηκότα γραμματεῖον, ἐν ᾧ τὰ τούτῳ βεβιωμέν’ ἔνεστιν, ὃς αὑτὸν ὑπεύθυνον ποιήσας μαρτυρεῖ ταῦτα. ὥσθ’ ὅταν μὲν λοιδορίαν ταῦτα καὶ αἰτίαν εἶναι φῇ, ὑπολαμβάνεθ’ ὡς ταῦτα μέν ἐστιν ἔλεγχος, ἃ δ’ οὗτος ποιεῖ, ταῦτα λοιδορία καὶ αἰτία· ὅταν δ’ ὅτι πρὸς τοὺς θεσμοθέτας προσῆκεν ἐπαγγέλλειν ἡμῖν, ἐκεῖνο ὑπολαμβάνετε, ὅτι καὶ τοῦτο ποιήσομεν … καὶ νῦν προσηκόντως περὶ τοῦ νόμου λέγομεν.", "st": "22.23"}, {"sp": "N", "t": "εἰ μὲν γὰρ ἄλλον τιν’ ἀγῶν’ ἀγωνιζομένου σου ταῦτα κατηγοροῦμεν, δικαίως ἂν ἠγανάκτεις· εἰ δ’ ὁ μὲν νῦν ἐνεστηκὼς ἀγών ἐστιν παρανόμων, οἱ νόμοι δ’ οὐκ ἐῶσι λέγειν οὐδὲ τὰ ἔννομα τοὺς οὕτω βεβιωκότας, ἡμεῖς δ’ ἐπιδείκνυμεν οὐ μόνον εἰρηκότ’ αὐτὸν παράνομα, ἀλλὰ καὶ βεβιωκότα παρανόμως, πῶς οὐχὶ προσήκει λέγειν περὶ τούτου τοῦ νόμου δι’ οὗ ταῦτ’ ἐλέγχεται;", "st": "22.24"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖνό γε δεῖ μαθεῖν ὑμᾶς, ὅτι τοὺς νόμους ὁ τιθεὶς τούτους Σόλων καὶ τῶν ἄλλων τοὺς πολλούς, οὐδὲν ὅμοιος ὢν τούτῳ νομοθέτης, οὐχ ἑνὶ ἔδωκε τρόπῳ περὶ τῶν ἀδικημάτων ἑκάστων λαμβάνειν δίκην τοῖς βουλομένοις παρὰ τῶν ἀδικούντων, ἀλλὰ πολλαχῶς. ᾔδει γάρ, οἶμαι, τοῦθ’ ὅτι τοὺς ἐν τῇ πόλει γενέσθαι πάντας ὁμοίως ἢ δεινοὺς ἢ θρασεῖς ἢ μετρίους οὐκ ἂν εἴη. εἰ μὲν οὖν, ὡς τοῖς μετρίοις δίκην ἐξαρκέσει λαβεῖν, οὕτω τοὺς νόμους θήσει, μετ’ ἀδείας ἔσεσθαι πολλοὺς πονηροὺς ἡγεῖτο· εἰ δ’ ὡς τοῖς θρασέσιν καὶ δυνατοῖς λέγειν, τοὺς ἰδιώτας οὐ δυνήσεσθαι τὸν αὐτὸν τούτοις τρόπον λαμβάνειν δίκην.", "st": "22.25"}, {"sp": "N", "t": "δεῖν δ’ ᾤετο μηδέν’ ἀποστερεῖσθαι τοῦ δίκης τυχεῖν, ὡς ἕκαστος δύναται. πῶς οὖν ἔσται τοῦτο; ἐὰν πολλὰς ὁδοὺς δῷ διὰ τῶν νόμων ἐπὶ τοὺς ἠδικηκότας οἷον τῆς κλοπῆς. ἔρρωσαι καὶ σαυτῷ πιστεύεις· ἄπαγε· ἐν χιλίαις δ’ ὁ κίνδυνος. ἀσθενέστερος εἶ· τοῖς ἄρχουσιν ἐφηγοῦ· τοῦτο ποιήσουσιν ἐκεῖνοι. φοβεῖ καὶ τοῦτο· γράφου.", "st": "22.26"}, {"sp": "N", "t": "καταμέμφει σεαυτὸν καὶ πένης ὢν οὐκ ἂν ἔχοις χιλίας ἐκτεῖσαι· δικάζου κλοπῆς πρὸς διαιτητὴν καὶ οὐ κινδυνεύσεις. [οὐδέτερον βούλει τούτων· γράφου. κατοκνεῖς καὶ τοῦτο· ἐφηγοῦ.] τούτων οὐδέν ἐστι ταὐτό. τῆς ἀσεβείας κατὰ ταὔτ’ ἔστ’ ἀπάγειν, γράφεσθαι, δικάζεσθαι πρὸς Εὐμολπίδας, φαίνειν πρὸς τὸν βασιλέα. περὶ τῶν ἄλλων ἁπάντων τὸν αὐτὸν τρόπον σχεδόν.", "st": "22.27"}, {"sp": "N", "t": "εἰ δή τις ὡς μὲν οὐχὶ κακοῦργός ἐστι μὴ λέγοι, ἢ ὡς οὐκ ἀσεβής, ἢ ὅ τι δήποτ’ εἴη δι’ ὃ κρίνοιτο, διὰ ταῦτα δ’ ἐκφεύγειν ἀξιοίη, εἰ μὲν ἀπηγμένος εἴη, διότι πρὸς διαιτητὴν ἐξῆν αὐτῷ λαχεῖν ἢ γράφεσθαι χρῆν, εἰ δὲ πρὸς διαιτητῇ φεύγοι, ὅτι χρῆν σ’ ἀπάγειν, ἵν’ ἐκινδύνευες περὶ χιλιῶν, γέλως ἂν εἴη δήπουθεν. οὐ γὰρ τόν γε μηδὲν πεποιηκότα δεῖ περὶ τοῦ τρόπον ὅντινα χρὴ διδόναι δίκην ἀντιλέγειν, ἀλλ’ ὡς οὐ πεποίηκ’ ἐπιδεικνύναι.", "st": "22.28"}, {"sp": "N", "t": "τὸν αὐτὸν δὴ τρόπον, Ἀνδροτίων, καὶ σὺ μὴ διὰ ταῦτ’ οἴου σοι προσήκειν μὴ δοῦναι δίκην εἰ γράφεις ἡταιρηκώς, ὅτι καὶ πρὸς τοὺς θεσμοθέτας ἔσθ’ ἡμῖν ἐπαγγελία· ἀλλ’ ἢ δεῖξον οὐ πεποιηκότα ταῦτα σεαυτόν, ἢ δίκην ὕπεχ’ ὧν γέγραφας τοιοῦτος ὤν· οὐ γὰρ ἔξεστί σοι. εἰ δέ σε μὴ πάντας ὅσους διδόασιν οἱ νόμοι τρόπους τιμωρούμεθα, χάριν ἡμῖν ὧν παραλείπομεν, ἐκείνων ἔχε, μὴ διὰ ταῦτ’ ἀξίου μηδένα δοῦναι τρόπον δίκην.", "st": "22.29"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, καὶ τὸν θέντα τὸν νόμον ἐξετάσαι Σόλωνα, καὶ θεάσασθαι ὅσην πρόνοιαν ἐποιεῖτο ἐν ἅπασιν οἷς ἐτίθει νόμοις τῆς πολιτείας, καὶ ὅσῳ περὶ τούτου μᾶλλον ἐσπούδαζεν ἢ περὶ τοῦ πράγματος οὗ τιθείη τὸν νόμον. πολλαχόθεν μὲν οὖν ἄν τις ἴδοι τοῦτο, οὐχ ἥκιστα δ’ ἐκ τούτου τοῦ νόμου, μήτε λέγειν μήτε γράφειν ἐξεῖναι τοῖς ἡταιρηκόσιν. ἑώρα γὰρ ἐκεῖνο, ὅτι τοῖς πολλοῖς ὑμῶν ἐξὸν λέγειν οὐ λέγετε, ὥστε τοῦτ’ οὐδὲν ἡγεῖτο βαρύ, καὶ πόλλ’ ἂν εἶχεν, εἴ γε κολάζειν ἐβούλετο τούτους, χαλεπώτερα θεῖναι.", "st": "22.30"}, {"sp": "N", "t": "ἀλλ’ οὐ τοῦτ’ ἐσπούδασεν, ἀλλὰ ταῦτ’ ἀπεῖπεν ὑπὲρ ὑμῶν καὶ τῆς πολιτείας. ᾔδει γάρ, ᾔδει τοῖς αἰσχρῶς βεβιωκόσιν ἁπασῶν οὖσαν ἐναντιωτάτην πολιτείαν ἐν ᾗ πᾶσιν ἔξεστι λέγειν τἀκείνων ὀνείδη. ἔστι δ’ αὕτη τίς; δημοκρατία. οὔκουν ἐνόμιζεν ἀσφαλές, εἴ ποτε συμβήσεται γενέσθαι συχνοὺς ἀνθρώπους κατὰ τοὺς αὐτοὺς χρόνους εἰπεῖν μὲν δεινοὺς καὶ θρασεῖς, τοιούτων δ’ ὀνειδῶν καὶ κακῶν μεστούς·", "st": "22.31"}, {"sp": "N", "t": "πολλὰ γὰρ ἂν τὸν δῆμον ὑπ’ αὐτῶν ὑπαχθέντ’ ἐξαμαρτεῖν, κἀκείνους ἤτοι καταλῦσαί γ’ ἂν πειρᾶσθαι τὸ παράπαν τὸν δῆμον (ἐν γὰρ ταῖς ὀλιγαρχίαις, οὐδ’ ἂν ὦσιν ἔτ’ Ἀνδροτίωνός τινες αἴσχιον βεβιωκότες, οὐκ ἔστι λέγειν κακῶς τοὺς ἄρχοντας), ἢ προάγειν ἂν ὡς πονηροτάτους εἶναι, ἵν’ ὡς ὁμοιότατοι σφίσιν ὦσι. τὴν οὖν ἀρχὴν τοῖς τοιούτοις ἀπεῖπε μὴ μετέχειν τοῦ συμβουλεύειν, ἵνα μὴ φενακισθεὶς ὁ δῆμος ἐξαμάρτοι μηδέν. ὧν ὀλιγωρήσας ὁ καλὸς κἀγαθὸς οὗτος οὐ μόνον ᾤετο δεῖν λέγειν καὶ γράφειν οὐκ ἐξόν, ἀλλὰ καὶ παρὰ τοὺς νόμους ταῦτα ποιεῖν.", "st": "22.32"}, {"sp": "N", "t": "περὶ μὲν τοίνυν τοῦ νόμου καθ’ ὅν, ὠφληκότος αὐτοῦ τοῦ πατρὸς τῷ δημοσίῳ χρήματα καὶ οὐκ ἐκτετεικότος, οὐκ ἔξεστι λέγειν οὐδὲ γράφειν τούτῳ, ταὐτὰ δίκαια λέγειν ἂν ἔχοιτ’ εἰκότως, ἐὰν φῇ δεῖν ἡμᾶς ἐνδεικνύναι. τότε γὰρ τοῦτο ποιήσομεν, οὐ μὰ Δί’ οὐχὶ νῦν, ἡνίκα δεῖ σ’ ἑτέρων ὧν ἀδικεῖς δοῦναι λόγον, ἀλλ’ ὅταν ᾖ προσῆκον ἐκ τοῦ νόμου, καὶ νῦν δὲ δείκνυμεν οὐκ ἐῶντα γράφειν σε, οὐδ’ ἃ τοῖς ἄλλοις ἔξεστι, τὸν νόμον.", "st": "22.33"}, {"sp": "N", "t": "ὡς οὖν οὐκ ὦφλ’ ὁ πατήρ σου, τοῦτ’ ἐπίδειξον, ἢ ὡς οὐκ ἀποδρὰς ἐξῆλθεν ἐκ τοῦ δεσμωτηρίου, ἀλλὰ τὰ χρήματ’ ἐκτείσας. εἰ δὲ μὴ ταῦθ’ ἕξεις δεικνύναι, οὐκ ἐξὸν γέγραφας· κληρονόμον γάρ σε καθίστησ’ ὁ νόμος τῆς ἀτιμίας τῆς τοῦ πατρός, ὄντι δ’ ἀτίμῳ σοι λέγειν οὐ προσῆκεν οὐδὲ γράφειν. καὶ περὶ μὲν τῶν νόμων οὓς παρεγραψάμεθα, οἶμαι δεῖν ὑμᾶς, ἄν τι φενακίζειν ἐγχειρῇ καὶ παράγειν οὗτος, ταῦθ’ ὑπολαμβάνειν ἃ διεξελήλυθ’ ἐγώ.", "st": "22.34"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ περὶ τῶν ἄλλων αὐτῷ λόγοι πρὸς τὸ φενακίζειν ὑμᾶς εὖ μεμηχανημένοι, περὶ ὧν βέλτιον ὑμᾶς προακοῦσαι. ἔστιν γὰρ εἷς αὐτῷ τοιοῦτος, μὴ πεντακοσίους ὑμῶν αὐτῶν ἀφελέσθαι τὴν δωρειὰν μηδ’ ὀνείδει περιβαλεῖν· ἐκείνων ἁγών, οὐκ ἐμός. ἐγὼ δ’ εἰ μὲν ἐμέλλετ’ ἀφαιρήσεσθαι τούτους μόνον, ἄλλο δὲ μηδὲν ὠφελήσειν τὴν πόλιν, οὐδὲν ἂν ὑμᾶς σφόδρα σπουδάζειν ἠξίουν· εἰ δὲ τῷ τοῦτο ποιῆσαι πλείους ἢ μυρίους τοὺς ἄλλους πολίτας βελτίους εἶναι προτρέψετε, πόσῳ κάλλιον τοσούτους παρασκευάσαι χρηστοὺς ἢ πεντακοσίοις ἀδίκως χαρίσασθαι;", "st": "22.35"}, {"sp": "N", "t": "ὡς δ’ οὐδ’ ἔστιν ἁπάσης τὸ πρᾶγμα τῆς βουλῆς, ἀλλὰ τινῶν, οἵπερ εἰσὶν αἴτιοι τῶν κακῶν, καὶ Ἀνδροτίωνος, ἔχω λέγειν. τῷ γάρ ἐστιν ὄνειδος, εἰ σιωπῶντος αὐτοῦ καὶ μηδὲν γράφοντος, ἴσως δ’ οὐδὲ τὰ πόλλ’ εἰς τὸ βουλευτήριον εἰσιόντος, μὴ λάβοι ἡ βουλὴ τὸν στέφανον; οὐδενὶ δήπουθεν, ἀλλὰ τοῦ γράφοντος καὶ πολιτευομένου καὶ πείθοντος ἃ βούλοιτο τὴν βουλήν· διὰ γὰρ τούτους ἀνάξια τοῦ στεφανωθῆναι βεβούλευκεν.", "st": "22.36"}, {"sp": "N", "t": "οὐ μὴν ἀλλ’ εἰ καὶ τὰ μάλιστα πάσης ἔσθ’ ἁγὼν τῆς βουλῆς, ὅσῳ συμφέρει μᾶλλον ὑμῖν καταγνοῦσιν ἢ μὴ θεάσασθε. εἰ μὲν ἀπογνώσεσθε, ἐπὶ τοῖς λέγουσι τὸ βουλευτήριον ἔσται, ἐὰν δὲ καταγνῶτε, ἐπὶ τοῖς ἰδιώταις· ἑορακότες γὰρ οἱ πολλοὶ διὰ τὴν τῶν λεγόντων πονηρίαν τήνδ’ ἀφῃρημένην τὴν βουλὴν τὸν στέφανον, οὐχὶ προήσονται τούτοις τὰς πράξεις, ἀλλὰ τὰ βέλτιστ’ ἐροῦσιν αὐτοί. εἰ δὲ γενήσεται τοῦτο καὶ τῶν ἠθάδων καὶ συνεστηκότων ῥητόρων ἀπαλλαγήσεσθε, ὄψεσθ’, ὦ ἄνδρες Ἀθηναῖοι, πάνθ’ ἃ προσήκει γιγνόμενα. ὥστ’ εἰ μηδενὸς ἄλλου ἕνεκα, διὰ ταῦτα καταψηφιστέον.", "st": "22.37"}, {"sp": "N", "t": "ὃ τοίνυν ἕτερον δεῖ μὴ λαθεῖν ὑμᾶς, ἀκούσατε. ἴσως ἀναβήσεται καὶ συνερεῖ τῇ βουλῇ Φίλιππος καὶ Ἀντιγένης καὶ ὁ ἀντιγραφεὺς καί τινες ἄλλοι, οἵπερ ἐκεῖ δι’ ἑαυτῶν εἶχον μετὰ τούτου τὸ βουλευτήριον καὶ τούτων τῶν κακῶν εἰσιν αἴτιοι. δεῖ δὴ πάντας ὑμᾶς γιγνώσκειν ὅτι τούτοις ἐστὶ μὲν ἡ πρόφασις τῆς συνηγορίας τῇ βουλῇ βοηθεῖν, τῇ δ’ ἀληθείᾳ περὶ αὑτῶν ἀγωνιοῦνται καὶ τῶν εὐθυνῶν ἃς αὐτοὺς προσήκει δοῦναι τῶν πεπραγμένων.", "st": "22.38"}, {"sp": "N", "t": "ἔχει γὰρ οὕτως. ἂν μὲν ἀπογνῶτε τὴν γραφὴν ταύτην, ἅπαντές εἰσιν ἀπηλλαγμένοι καὶ δίκην οὐδεὶς οὐδεμίαν μὴ δῷ· τίς γὰρ ἔτ’ ἂν καταψηφίσαιτ’ ἐκείνων, τὴν βουλὴν ὑμῶν ἐστεφανωκότων ἧς οὗτοι προέστασαν; ἐὰν δὲ καταγνῶτε, πρῶτον μὲν τὰ εὔορκ’ ἔσεσθ’ ἐψηφισμένοι, εἶτ’ ἐπὶ ταῖς εὐθύναις ἕκαστον τούτων λαμβάνοντες, ὃς μὲν ἂν ὑμῖν ἀδικεῖν δοκῇ, κολάσετε, ὃς δ’ ἂν μή, τότ’ ἀφήσετε. μὴ οὖν ὡς ὑπὲρ τῆς βουλῆς λεγόντων καὶ τῶν πολλῶν ἀκούετε, ἀλλ’ ὡς ὑπὲρ αὑτῶν παρακρουομένοις ὀργίζεσθε.", "st": "22.39"}, {"sp": "N", "t": "ἔτι τοίνυν Ἀρχίαν οἶμαι τὸν Χολαργέα (καὶ γὰρ οὗτος ἐβούλευεν πέρυσιν) ὡς ἐπιεικῆ δεήσεσθαι καὶ συνερεῖν αὐτοῖς. ἐγὼ δ’ οἴομαι δεῖν ὡδί πως ἀκούειν Ἀρχίου, ἐρωτᾶν αὐτὸν ταῦθ’ ἃ κατηγόρηται τῆς βουλῆς, πότερ’ αὐτῷ δοκεῖ καλῶς ἔχειν ἢ κακῶς· κἂν μὲν φῇ καλῶς, μηκέτι τὸν νοῦν ὡς ἐπιεικεῖ προσέχειν, ἂν δὲ κακῶς, τί δὴ ταῦτ’ εἴα φάσκων ἐπιεικὴς εἶναι, πάλιν αὐτὸν ἐρωτᾶτε.", "st": "22.40"}, {"sp": "N", "t": "κἂν μὲν ἀντιλέγειν φῇ, μηδένα δ’ αὐτῷ πείθεσθαι, ἄτοπον δήπου νῦν λέγειν ὑπὲρ τῆς τὰ βέλτιστ’ οὐχὶ πειθομένης αὐτῷ βουλῆς· ἂν δὲ σιωπᾶν, πῶς οὐκ ἀδικεῖ, εἰ, παρὸν ἐξαμαρτάνειν μέλλοντας ἀποτρέπειν, τοῦτο μὲν οὐκ ἐποίει, νῦν δὲ λέγειν τολμᾷ ὡς δεῖ τοὺς τοσαῦτα κάκ’ εἰργασμένους στεφανῶσαι;", "st": "22.41"}, {"sp": "N", "t": "οἴομαι τοίνυν αὐτὸν οὐδ’ ἐκείνων ἀφέξεσθαι τῶν λόγων, ὅτι ταῦτα πάντ’ αὐτῷ διὰ τὰς εἰσπράξεις γέγονεν, ἃς ὑπὲρ ὑμῶν ὀλίγους εἰσπρᾶξαι φήσει πολλὰ χρήματ’ ἀναιδῶς οὐ τιθέντας. καὶ κατηγορήσει τούτων, πρᾶγμα ῥᾴδιον, οἶμαι, [τῶν μὴ τιθέντων τὰς εἰσφοράς,] καὶ φήσει πᾶσαν ἄδειαν ἔσεσθαι τοῦ μὴ τιθέναι τὰς εἰσφοράς, εἰ καταψηφιεῖσθ’ αὐτοῦ.", "st": "22.42"}, {"sp": "N", "t": "ὑμεῖς δ’, ὦ ἄνδρες Ἀθηναῖοι, πρῶτον μὲν ἐκεῖνο ἐνθυμεῖσθε, ὅτι οὐ περὶ τούτων δικάσειν ὀμωμόκατε, ἀλλ’ εἰ κατὰ τοὺς νόμους τὸ ψήφισμ’ εἶπεν, εἶθ’ ὅτι πάνδεινόν ἐστι, κατηγορίαν ποιούμενον ὡς ἀδικοῦσί τινες τὴν πόλιν, αὐτὸν ἀξιοῦν ὧν ἀδικεῖ μειζόνων ὄντων μὴ δοῦναι δίκην· πολὺ γὰρ δήπου μεῖζόν ἐστ’ ἀδίκημα γράφειν παρὰ τοὺς νόμους ἢ τὴν εἰσφορὰν μὴ τιθέναι.", "st": "22.43"}, {"sp": "N", "t": "ὅτι τοίνυν οὐδ’ εἰ φανερῶς ἔμελλεν ἁλόντος τούτου μηδεὶς εἰσοίσειν μηδ’ ἐθελήσειν εἰσπράττειν, οὐδ’ οὕτως ἀποψηφιστέον, ἐκ τῶνδε γνώσεσθε. ὑμῖν παρὰ τὰς εἰσφορὰς τὰς ἀπὸ Ναυσινίκου, παρ’ ἴσως τάλαντα τριακόσι’ ἢ μικρῷ πλείω, ἔλλειμμα τέτταρα καὶ δέκ’ ἐστὶ τάλαντα, ὧν ἑπτὰ οὗτος εἰσέπραξεν, ἐγὼ δὲ τίθημ’ ἅπαντα. ἐπὶ μὲν δὴ τοὺς ἑκόντας τιθέντας οὐ δεῖσθ’ Ἀνδροτίωνος, ἐπὶ δὲ τοὺς ἐλλείποντας.", "st": "22.44"}, {"sp": "N", "t": "ἔστι τοίνυν ὑμῖν νυνὶ σκεπτέον, εἰ τοσούτου τιμᾶσθε τὴν πολιτείαν καὶ τοὺς κειμένους νόμους καὶ τὸ εὐορκεῖν· εἰ γὰρ ἀποψηφιεῖσθε τούτου φανερῶς οὕτως παρὰ τοὺς νόμους εἰρηκότος, δόξετε πᾶσιν τὰ χρήματα ταῦτ’ ἀντὶ τῶν νόμων καὶ τῆς εὐορκίας ᾑρῆσθαι. ἃ οὐδ’ ἂν εἰ παρ’ ἑαυτοῦ δοίη τις ὑμῖν, λαβεῖν ἄξιον, μή τί γ’ ἐφ’ ᾧ ἑτέρους εἰσπράττειν.", "st": "22.45"}, {"sp": "N", "t": "ὥσθ’ ὅταν ταῦτα λέγῃ, μέμνησθε τῶν ὅρκων καὶ τὴν γραφὴν ἐνθυμεῖσθε, ὅτι νῦν οὐ περὶ πράξεως εἰσφορῶν ἐστιν, ἀλλ’ εἰ δεῖ κυρίους εἶναι τοὺς νόμους. καὶ περὶ τούτων μέν, ὃν τρόπον ὑμᾶς ἀπάγων ἀπὸ τοῦ νόμου παρακρούεσθαι ζητήσει, καὶ ἃ πρὸς ταῦθ’ ὑμᾶς μνημονεύοντας μὴ ’πιτρέπειν προσήκει, πολλὰ λέγειν ἔχων ἔτι, καὶ ταῦθ’ ἱκάν’ εἶναι νομίζων, ἐάσω.", "st": "22.46"}, {"sp": "N", "t": "βούλομαι δὲ καὶ τὰ πολιτεύματα ἐξετάσαι τοῦ καλοῦ κἀγαθοῦ τούτου, δι’ ὧν οὐκ ἔσθ’ ὅ τι τῶν δεινοτάτων ἐλλιπὼν φανήσεται· καὶ γὰρ ἀναιδῆ καὶ θρασὺν καὶ κλέπτην καὶ ὑπερήφανον καὶ πάντα μᾶλλον ἢ ἐν δημοκρατίᾳ πολιτεύεσθαι ἐπιτήδειον ὄντ’ αὐτὸν δείξω. καὶ πρῶτον μέν, ἐφ’ ᾧ μέγιστον φρονεῖ, τὴν τῶν χρημάτων εἴσπραξιν ἐξετάσωμεν αὐτοῦ, μὴ τῇ τούτου προσέχοντες ἀλαζονείᾳ τὸν νοῦν, ἀλλὰ τὸ πρᾶγμα οἷον γέγονεν τῇ ἀληθείᾳ σκοποῦντες.", "st": "22.47"}, {"sp": "N", "t": "οὗτος Εὐκτήμονα φήσας τὰς ὑμετέρας ἔχειν εἰσφορὰς καὶ τοῦτ’ ἐξελέγξειν ἢ παρ’ αὑτοῦ καταθήσειν, καταλύσας ψηφίσματι κληρωτὴν ἀρχὴν ἐπὶ τῇ προφάσει ταύτῃ, ἐπὶ τὴν εἴσπραξιν παρέδυ. δημηγορίαν δ’ ἐπὶ τούτοις ποιούμενος, ὡς ἔστι τριῶν αἵρεσις, ἢ τὰ πομπεῖα κατακόπτειν ἢ πάλιν εἰσφέρειν ἢ τοὺς ὀφείλοντας εἰσπράττειν,", "st": "22.48"}, {"sp": "N", "t": "αἱρουμένων εἰκότως ὑμῶν τοὺς ὀφείλοντας εἰσπράττειν, ταῖς ὑποσχέσεσιν κατέχων καὶ διὰ τὸν καιρὸν ὃς ἦν τότ’ ἔχων ἐξουσίαν, τοῖς μὲν κειμένοις νόμοις περὶ τούτων οὐκ ᾤετο δεῖν χρῆσθαι, οὐδ’, εἰ μὴ τούτους ἐνόμιζ’ ἱκανούς, ἑτέρους τιθέναι, ψηφίσματα δ’ εἶπεν ἐν ὑμῖν δεινὰ καὶ παράνομα, δι’ ὧν ἠργολάβει καὶ πολλὰ τῶν ὑμετέρων κέκλοφεν, τοὺς ἕνδεκα γράψας ἀκολουθεῖν μεθ’ ἑαυτοῦ.", "st": "22.49"}, {"sp": "N", "t": "εἶτ’ ἔχων τούτους ἦγ’ ἐπὶ τὰς ὑμετέρας οἰκίας. καὶ τὸν μὲν Εὐκτήμονα, ὃν εἰσπράξειν ἢ καταθήσειν αὐτὸς ἔφη τὰς εἰσφοράς, οὐδὲν εἶχεν ἐλέγχειν περὶ τούτων, ὑμᾶς δ’ εἰσέπραττεν, ὥσπερ οὐ διὰ τὴν Εὐκτήμονος ἔχθραν ἐπὶ ταῦτ’ ἐλθών, ἀλλὰ διὰ τὴν ὑμετέραν.", "st": "22.50"}, {"sp": "N", "t": "καὶ μηδεὶς ὑπολαμβανέτω με λέγειν ὡς οὐ χρῆν εἰσπράττειν τοὺς ὀφείλοντας. χρῆν γάρ. ἀλλὰ πῶς; ὡς ὁ νόμος κελεύει· τῶν ἄλλων ἕνεκα· τοῦτο γάρ ἐστι δημοτικόν. οὐ γὰρ τοσοῦτον, ὦ ἄνδρες Ἀθηναῖοι, τοσούτων χρημάτων τοῦτον τὸν τρόπον εἰσπραχθέντων ὠφέλησθε, ὅσον ἐζημίωσθε τοιούτων ἐθῶν εἰς τὴν πολιτείαν εἰσαγομένων. εἰ γὰρ θέλετ’ ἐξετάσαι τίνος εἵνεκα μᾶλλον ἄν τις ἕλοιτ’ ἐν δημοκρατίᾳ ζῆν ἢ ἐν ὀλιγαρχίᾳ, τοῦτ’ ἂν εὕροιτε προχειρότατον, ὅτι πάντα πραότερ’ ἐστὶν ἐν δημοκρατίᾳ.", "st": "22.51"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν τῆς ὅπου βούλεσθ’ ὀλιγαρχίας οὗτος ἀσελγέστερος γέγονεν, παραλείψω. ἀλλὰ παρ’ ἡμῖν πότε πώποτε δεινότατ’ ἐν τῇ πόλει γέγονεν; ἐπὶ τῶν τριάκοντα, πάντες ἂν εἴποιτε. τότε τοίνυν, ὡς ἔστιν ἀκούειν, οὐδεὶς ἔστιν ὅστις ἀπεστερεῖτο τοῦ σωθῆναι, ὅστις ἑαυτὸν οἴκοι κρύψειεν, ἀλλὰ τοῦτο κατηγοροῦμεν τῶν τριάκοντα, ὅτι τοὺς ἐκ τῆς ἀγορᾶς ἀδίκως ἀπῆγον. οὗτος τοίνυν τοσαύτην ὑπερβολὴν ἐποιήσατ’ ἐκείνων τῆς αὑτοῦ βδελυρίας ὥστ’ ἐν δημοκρατίᾳ πολιτευόμενος τὴν ἰδίαν οἰκίαν ἑκάστῳ δεσμωτήριον καθίστη, τοὺς ἕνδεκ’ ἄγων ἐπὶ τὰς οἰκίας.", "st": "22.52"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες Ἀθηναῖοι, τί οἴεσθ’ ὁπότ’ ἄνθρωπος πένης ἢ καὶ πλούσιος, πολλὰ δ’ ἀνηλωκὼς καί τιν’ ἴσως τρόπον εἰκότως οὐκ εὐπορῶν ἀργυρίου, ἢ τέγος ὡς τοὺς γείτονας ὑπερβαίνοι, ἢ ὑποδύοιθ’ ὑπὸ κλίνην ὑπὲρ τοῦ μὴ τὸ σῶμ’ ἁλοὺς εἰς τὸ δεσμωτήριον ἕλκεσθαι, ἢ ἄλλ’ ἀσχημονοίη ἃ δούλων, οὐκ ἐλευθέρων ἐστὶν ἔργα, καὶ ταῦθ’ ὑπὸ τῆς αὑτοῦ γυναικὸς ὁρῷτο ποιῶν, ἣν ὡς ἐλεύθερος ἠγγυήσατο καὶ τῆς πόλεως πολίτης, ὁ δὲ τούτων αἴτιος Ἀνδροτίων εἴη, ὃν οὐδ’ ὑπὲρ αὑτοῦ δίκην λαμβάνειν ἐᾷ τὰ πεπραγμένα καὶ βεβιωμένα, μή τί γ’ ὑπὲρ τῆς πόλεως;", "st": "22.53"}, {"sp": "N", "t": "καίτοι εἴ τις ἔροιτ’ αὐτόν, τὰς εἰσφορὰς πότερον τὰ κτήματ’ ἢ τὰ σώματ’ ὀφείλει, τὰ κτήματα φήσειεν ἄν, εἴπερ ἀληθῆ λέγειν βούλοιτο· ἀπὸ γὰρ τούτων εἰσφέρομεν. τίνος οὖν εἵνεκ’ ἀφεὶς τὸ τὰ χωρία δημεύειν καὶ τὰς οἰκίας καὶ ταῦτ’ ἀπογράφειν, ἔδεις καὶ ὕβριζες πολίτας ἀνθρώπους καὶ τοὺς ταλαιπώρους μετοίκους, οἷς ὑβριστικώτερον ἢ τοῖς οἰκέταις τοῖς σαυτοῦ κέχρησαι;", "st": "22.54"}, {"sp": "N", "t": "καὶ μὴν εἰ θέλετε σκέψασθαι τί δοῦλον ἢ ἐλεύθερον εἶναι διαφέρει, τοῦτο μέγιστον ἂν εὕροιτε, ὅτι τοῖς μὲν δούλοις τὸ σῶμα τῶν ἀδικημάτων ἁπάντων ὑπεύθυνόν ἐστιν, τοῖς δ’ ἐλευθέροις, κἂν τὰ μέγιστ’ ἀτυχῶσιν, τοῦτό γ’ ἔνεστι σῶσαι· εἰς χρήματα γὰρ τὴν δίκην περὶ τῶν πλείστων παρὰ τούτων προσήκει λαμβάνειν. ὁ δὲ τοὐναντίον εἰς τὰ σώματα, ὥσπερ ἀνδραπόδοις, ἐποιήσατο τὰς τιμωρίας.", "st": "22.55"}, {"sp": "N", "t": "οὕτω δ’ αἰσχρῶς καὶ πλεονεκτικῶς ἔσχε πρὸς ὑμᾶς ὥστε τὸν μὲν ἑαυτοῦ πατέρα ᾤετο δεῖν, δημοσίᾳ δεθέντ’ ἐπὶ χρήμασιν ἐν τῷ δεσμωτηρίῳ, μήτ’ ἀποδόντα ταῦτα μήτε κριθέντ’ ἀποδρᾶναι, τῶν δ’ ἄλλων πολιτῶν τὸν μὴ δυνάμενον τὰ ἑαυτοῦ θεῖναι οἴκοθεν εἰς τὸ δεσμωτήριον ἕλκεσθαι. εἶτ’ ἐπὶ τούτοις, ὡς ὁτιοῦν ἐξὸν ἑαυτῷ ποιεῖν, Σινώπην προσηνεχύραζεν καὶ Φανοστράτην, ἀνθρώπους πόρνας, οὐ μέντοι ὀφειλούσας εἰσφοράς.", "st": "22.56"}, {"sp": "N", "t": "καίτοι εἴ τισιν ἄρα δοκοῦσ’ ἐπιτήδειαι ’κεῖναι παθεῖν, ἀλλὰ τὸ πρᾶγμά γ’ οὐκ ἐπιτήδειον γίγνεσθαι, τηλικοῦτό τινας φρονεῖν διὰ καιρὸν ὥστε βαδίζειν ἐπ’ οἰκίας καὶ σκεύη φέρειν μηδὲν ὀφειλόντων ἀνθρώπων. πολλὰ γὰρ ἄν τις ἴδοι πολλοὺς ἐπιτηδείους ὄντας πάσχειν καὶ πεπονθέναι. ἀλλ’ οὐ ταῦτα λέγουσιν οἱ νόμοι, οὐδὲ τὰ τῆς πολιτείας ἔθη, ἃ φυλακτέον ὑμῖν· ἀλλ’ ἔνεστ’ ἔλεος, συγγνώμη, πάνθ’ ἃ προσήκει τοῖς ἐλευθέροις.", "st": "22.57"}, {"sp": "N", "t": "ὧν οὗτος ἁπάντων εἰκότως οὐ μετέχει τῇ φύσει οὐδὲ τῇ παιδείᾳ· πολλὰ γὰρ ὕβρισται καὶ προπεπηλάκισται συνὼν οὐκ ἀγαπῶσιν αὐτὸν ἀνθρώποις, ἀλλὰ δοῦναι μισθὸν δυναμένοις· ὧν προσῆκέ σοι τὴν ὀργὴν οὐκ εἰς τῶν πολιτῶν τὸν τυχόντ’ ἀφιέναι οὐδ’ εἰς τὰς ὁμοτέχνους πόρνας, ἀλλ’ εἰς τὸν τοῦτον τὸν τρόπον σε θρέψαντα.", "st": "22.58"}, {"sp": "N", "t": "ταῦτα τοίνυν ὡς μὲν οὐ δεινὰ καὶ παρὰ πάντας τοὺς νόμους, οὐχ ἕξει λέγειν οὗτος· οὕτω δ’ ἐστὶν ἀναιδὴς ὥστ’ ἐν τῷ δήμῳ, προάγωνας ἀεὶ κατασκευάζων αὑτῷ τῆσδε τῆς γραφῆς, ἐτόλμα λέγειν ὡς ὑπὲρ ὑμῶν καὶ δι’ ὑμᾶς ἐχθροὺς ἐφ’ ἑαυτὸν εἵλκυκε καὶ νῦν ἐν τοῖς ἐσχάτοις ἐστὶ κινδύνοις. ἐγὼ δ’ ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, βούλομαι δεῖξαι τοῦτον οὔτε πεπονθότ’ οὐδ’ ὁτιοῦν κακὸν οὔτε μέλλοντα πάσχειν οὐδὲν δι’ ὧν ὑπὲρ ὑμῶν ἔπραξε, διὰ μέντοι τὴν αὑτοῦ βδελυρίαν καὶ θεοισεχθρίαν πεπονθότα μὲν μέχρι τῆσδε τῆς ἡμέρας οὐδέν, πεισόμενον δ’, ἂν τὰ δίκαια ποιῆθ’ ὑμεῖς.", "st": "22.59"}, {"sp": "N", "t": "σκέψασθε γὰρ ὡδί. τί ποθ’ ὑμῖν οὗτος ὑπέσχετο καὶ τί ποιεῖν αὐτὸν ἐχειροτονήσαθ’ ὑμεῖς; χρήματ’ εἰσπράττειν. ἄλλο δὲ πρὸς τούτῳ τί ποιεῖν; οὐδὲ ἕν. φέρε δὴ καθ’ ἕκαστον ὑπομνήσω τὴν εἴσπραξιν ὑμᾶς. οὗτος εἰσέπραξε Λεπτίνην τὸν ἐκ Κοίλης τέτταρας καὶ τριάκοντα δραχμάς, καὶ Θεόξενον τὸν Ἀλωπεκῆθεν δραχμὰς ἑβδομήκοντα καὶ μικρόν τι πρός, καὶ τὸν Εὐφήρου Καλλικράτην καὶ τὸν Τελέστου νεανίσκον· οὐκ ἔχω γὰρ τοὔνομ’ εἰπεῖν· σχεδὸν δὲ πάντας οὓς εἰσέπραξεν, ἵνα μὴ καθ’ ἕκαστον λέγω, οὐκ οἶδ’ εἴ τιν’ ὑπὲρ μνᾶν ὀφείλοντα.", "st": "22.60"}, {"sp": "N", "t": "πότερ’ οὖν οἴεσθε τούτων ἕκαστον μισεῖν καὶ πολεμεῖν αὐτῷ διὰ τὴν εἰσφορὰν ταύτην, ἢ τὸν μὲν αὐτῶν, ὅτι πάντων ἀκουόντων ὑμῶν ἐν τῷ δήμῳ δοῦλον ἔφη καὶ ἐκ δούλων εἶναι καὶ προσήκειν αὐτῷ τὸ ἕκτον μέρος εἰσφέρειν μετὰ τῶν μετοίκων, τῷ δὲ παῖδας ἐκ πόρνης εἶναι, τοῦ δὲ τὸν πατέρ’ ἡταιρηκέναι, τοῦ δὲ τὴν μητέρα πεπορνεῦσθαι, τὸν δ’ ἀπογράφειν ὅσ’ ὑφείλετ’ ἐξ ἀρχῆς, τὸν δὲ τὸ δεῖνα, τὸν δ’ ὁμοῦ ῥητὰ καὶ ἄρρητα κακά, ἑξῆς ἅπαντας;", "st": "22.61"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οἶδ’ ὅτι πάντες, εἰς οὓς ἐπαρῴνησεν οὗτος, τὴν μὲν εἰσφορὰν ἕκαστος ἀναγκαῖον ἀνάλωμ’ ὑπελάμβανεν εἶναι, τοιαῦτα δ’ ἀτιμασθεὶς καὶ προπηλακισθεὶς χαλεπῶς ἐνήνοχεν. κἀκεῖνο οἶδα, ὅτι χρήματ’ εἰσπράττειν τοῦτον ἐχειροτονήσαθ’ ὑμεῖς, οὐχὶ τὰς ἰδίας συμφορὰς ὀνειδίζειν καὶ προφέρειν ἑκάστῳ. εἴτε γὰρ ἦσαν ἀληθεῖς, οὐ σοὶ ῥητέαι (πολλὰ γὰρ ἡμῶν ἕκαστος οὐχ ὡς βούλεται πράττει)· εἴτε μὴ προσηκούσας κατεσκεύαζες, πῶς οὐχ ὁτιοῦν ἂν πάθοις δικαίως;", "st": "22.62"}, {"sp": "N", "t": "ἔτι τοίνυν ἐκ τοῦδ’ ἀκριβέστερον γνώσεσθ’ ὅτι μισεῖ τοῦτον ἕκαστος οὐ διὰ τὴν εἴσπραξιν, ἀλλ’ ὑπὲρ ὧν ὑβρίσθη καὶ ἐπαρῳνήθη. Σάτυρος γὰρ ὁ τῶν νεωρίων ἐπιμελητὴς οὐχ ἑπτὰ τάλαντ’ εἰσέπραξεν ὑμῖν, ἀλλὰ τέτταρα καὶ τριάκοντα τοὺς αὐτοὺς τούτους ἀνθρώπους, ἐξ ὧν παρέθηκε τὰ σκεύη ταῖς ἐκπλευσάσαις ναυσίν· καὶ οὔτ’ ἐκεῖνος διὰ ταῦτ’ οὐδέν’ ἐχθρὸν αὑτῷ φησὶν εἶναι, οὔτε τῶν εἰσπραχθέντων οὐδεὶς ἐκείνῳ πολεμεῖ. ὁ μὲν γὰρ τὸ προστεταγμένον, οἶμαι, διεπράττετο, σὺ δὲ τῇ σαυτοῦ προπετείᾳ καὶ θρασύτητι λαβὼν ἐξουσίαν πόλλ’ ἀνηλωκότας εἰς τὴν πόλιν ἀνθρώπους καὶ σοῦ βελτίους καὶ ἐκ βελτιόνων ψευδέσι καὶ χαλεποῖς ὀνείδεσιν ᾤου δεῖν περιβάλλειν.", "st": "22.63"}, {"sp": "N", "t": "εἶτα ταῦθ’ οὗτοι πεισθῶσ’ ὑπὲρ αὑτῶν σε ποιεῖν, καὶ τὰ τῆς σῆς ἀναισθησίας καὶ πονηρίας ἔργ’ ἐφ’ αὑτοὺς ἀναδέξωνται; ἀλλὰ μισεῖν δικαιότερον διὰ ταῦτά σ’ ὀφείλουσιν ἢ σῴζειν. τὸν γὰρ ὑπὲρ πόλεως πράττοντά τι δεῖ τὸ τῆς πόλεως ἦθος μιμεῖσθαι, καὶ σῴζειν ὑμῖν τοὺς τοιούτους, ὦ ἄνδρες Ἀθηναῖοι, προσήκει, καὶ μισεῖν τοὺς οἵουσπερ οὗτος. ὡς ἐκεῖν’ εἰδόσιν μὲν ἴσως, ὅμως δ’ ἐρῶ· ὁποίους τινὰς ἂν φαίνησθ’ ἀγαπῶντες καὶ σῴζοντες, τούτοις ὅμοιοι δόξετ’ εἶναι.", "st": "22.64"}, {"sp": "N", "t": "ὅτι τοίνυν ὅλως οὐδὲ τὴν εἴσπραξιν αὐτὴν ὑπὲρ ὑμῶν πεποίηται, καὶ τοῦτ’ αὐτίκα δὴ μάλ’ ὑμῖν δῆλον ποιήσω. εἰ γάρ τις ἔροιτ’ αὐτὸν πότερ’ αὐτῷ δοκοῦσ’ ἀδικεῖν μᾶλλον τὴν πόλιν οἱ γεωργοῦντες καὶ φειδόμενοι, διὰ παιδοτροφίας δὲ καὶ οἰκεῖ’ ἀναλώματα καὶ λῃτουργίας ἑτέρας ἐλλελοιπότες εἰσφοράν, ἢ οἱ τὰ τῶν ἐθελησάντων εἰσενεγκεῖν χρήματα καὶ τὰ παρὰ τῶν συμμάχων κλέπτοντες καὶ ἀπολλύντες, οὐκ ἂν εἰς τοῦτο τόλμης δήπου, καίπερ ὢν ἀναιδής, ἔλθοι, ὥστε φῆσαι τοὺς τὰ ἑαυτῶν μὴ εἰσφέροντας μᾶλλον ἀδικεῖν ἢ τοὺς τὰ κοίν’ ὑφαιρουμένους.", "st": "22.65"}, {"sp": "N", "t": "τίνος οὖν ἕνεκ’, ὦ βδελυρέ, ἐτῶν ὄντων πλειόνων ἢ τριάκοντ’ ἀφ’ οὗ σὺ πολιτεύει, καὶ ἐν τούτῳ τῷ χρόνῳ πολλῶν μὲν στρατηγῶν ἠδικηκότων τὴν πόλιν, πολλῶν δὲ ῥητόρων, οἳ παρὰ τουτοισὶ κέκρινται, ὧν οἱ μὲν τεθνᾶσιν ἐφ’ οἷς ἠδίκουν, οἱ δ’ ὑποχωρήσαντες φεύγουσιν, οὐδενὸς πώποτ’ ἐξητάσθης κατήγορος οὐδ’ ἀγανακτῶν ὤφθης ὑπὲρ ὧν ἡ πόλις πάσχει, οὕτως ὢν θρασὺς καὶ λέγειν δεινός, ἀλλ’ ἐνταῦθ’ ἐφάνης κηδεμὼν ὤν, οὗ [σε] πολλοὺς ἔδει κακῶς ποιῆσαι;", "st": "22.66"}, {"sp": "N", "t": "βούλεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τὸ τούτων αἴτιον ἐγὼ ὑμῖν εἴπω; ὅτι τῶν μὲν", "st": "22.67"}, {"sp": "N", "t": "[μετέχουσιν ὧν ἀδικοῦσιν ὑμᾶς τινες, ἀπὸ δὲ τῶν εἰσπραττομένων ὑφαιροῦνται· δι’ ἀπληστίαν δὲ τρόπων διχόθεν καρποῦνται τὴν πόλιν. οὔτε γὰρ ῥᾷον πολλοῖς καὶ τὰ μίκρ’ ἀδικοῦσιν ἀπεχθάνεσθαι ἢ ὀλίγοις καὶ μεγάλα, οὔτε δημοτικώτερον δήπου τὰ τῶν πολλῶν ἀδικήμαθ’ ὁρᾶν ἢ τὰ τῶν ὀλίγων. ἀλλὰ τοῦτ’ αἴτιον οὑγὼ λέγω. τῶν μὲν]", "st": "22.67"}, {"sp": "N", "t": "οἶδεν ἑαυτὸν ὄντα, τῶν ἀδικούντων, ὑμᾶς δ’ οὐδενὸς ἀξίους ἡγήσατο· διὸ τοῦτον ἐχρήσατο τὸν τρόπον ὑμῖν.", "st": "22.67"}, {"sp": "N", "t": "εἰ γὰρ ἀνδραπόδων πόλις, ἀλλὰ μὴ τῶν ἄρχειν ἑτέρων ἀξιούντων ὡμολογεῖτ’ εἶναι, οὐκ ἄν, ὦ ἄνδρες Ἀθηναῖοι, τὰς ὕβρεις ἠνέσχεσθε τὰς τούτου, ἃς κατὰ τὴν ἀγορὰν ὕβριζεν ὁμοῦ μετοίκους, Ἀθηναίους· δῶν, ἀπάγων, βοῶν ἐν ταῖς ἐκκλησίαις ἐπὶ τοῦ βήματος· δούλους καὶ ἐκ δούλων καλῶν αὑτοῦ βελτίους καὶ ἐκ βελτιόνων· ἐρωτῶν εἰ μάτην τὸ δεσμωτήριον ᾠκοδομήθη. καταφαίην ἂν ἔγωγε, εἴ γ’ ὁ πατὴρ ὁ σὸς ᾤχετ’ αὐτόθεν αὐταῖς πέδαις ἐξορχησάμενος Διονυσίων τῇ πομπῇ. ἄλλα δ’ ὅσ’ ὕβρικεν οὐδ’ ἂν ἔχοι τις εἰπεῖν· τοσαῦτα τὸ πλῆθός ἐστιν. ὧν ἁθρόων ἄξιον λαβόντας δίκην τήμερον παράδειγμα ποιῆσαι τοῖς ἄλλοις, ἵν’ ὦσιν μετριώτεροι.", "st": "22.68"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦτα μὲν τοιοῦτός ἐστιν ἐν οἷς πεπολίτευται, ἄλλα δ’ ἔσθ’ ἃ καλῶς διῴκηκεν. ἀλλὰ καὶ τἄλλ’ οὕτω προσελήλυθε πάντα πρὸς ὑμᾶς ὥσθ’ ἥκιστ’ ἐν οἷς ἀκηκόατ’ ἄξιός ἐστι μισεῖσθαι. τί γὰρ βούλεσθ’ εἴπω; τὰ πομπεῖ’ ὡς ἐπεσκεύασεν, καὶ τὴν τῶν στεφάνων καθαίρεσιν, ἢ τὴν τῶν φιαλῶν ποίησιν τὴν καλήν; ἀλλ’ ἐπὶ τούτοις γε, εἰ μηδὲν ἄλλ’ ἀδικῶν ἔτυχεν τὴν πόλιν, τρίς, οὐχ ἅπαξ τεθνάναι δίκαιος ὢν φανεῖται· καὶ γὰρ ἱεροσυλίᾳ καὶ ἀσεβείᾳ καὶ κλοπῇ καὶ πᾶσι τοῖς δεινοτάτοις ἔστ’ ἔνοχος.", "st": "22.69"}, {"sp": "N", "t": "τὰ μὲν οὖν πόλλ’ ὧν λέγων ὑμᾶς ἐφενάκιζεν παραλείψω· φήσας δ’ ἀπορρεῖν τὰ φύλλα τῶν στεφάνων καὶ σαπροὺς εἶναι διὰ τὸν χρόνον, ὥσπερ ἴων ἢ ῥόδων ὄντας, ἀλλ’ οὐ χρυσίου, συγχωνεύειν ἔπεισεν. κᾆτ’ ἐπὶ μὲν ταῖς εἰσφοραῖς τὸν δημόσιον παρεῖναι προέγραψεν ὡς δὴ δίκαιος ὤν, ὧν ἕκαστος ἀντιγραφεὺς ἔμελλεν ἔσεσθαι τῶν εἰσενεγκόντων· ἐπὶ τοῖς στεφάνοις δ’ οὓς κατέκοπτεν οὐχὶ προσήγαγεν ταὐτὸ δίκαιον τοῦτο, ἀλλ’ αὑτὸς ῥήτωρ, χρυσοχόος, ταμίας, ἀντιγραφεὺς γέγονεν.", "st": "22.70"}, {"sp": "N", "t": "καὶ μὴν εἰ μὲν ἅπαντ’ ἠξίους, ὅσα πράττεις τῇ πόλει, σαυτῷ πιστεύειν, οὐκ ἂν ὁμοίως κλέπτης ὢν ἐφωρῶ· νῦν δ’ ἐπὶ ταῖς εἰσφοραῖς ὃ δίκαιόν ἐσθ’ ὁρίσας, μὴ σοὶ πιστεύειν, ἀλλὰ τοῖς ἑαυτῆς δούλοις τὴν πόλιν, ὁπότ’ ἄλλο τι πράττων καὶ χρήματα κινῶν ἱερά, ὧν ἔνι’ οὐδ’ ἐπὶ τῆς ἡμετέρας γενεᾶς ἀνετέθη, μὴ προσγραψάμενος τὴν αὐτὴν φυλακὴν ἥνπερ περὶ τῶν εἰσφορῶν φαίνει, οὐκ εὔδηλον δι’ ὃ τοῦτ’ ἐποίησας; ἐγὼ μὲν οἶμαι.", "st": "22.71"}, {"sp": "N", "t": "καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, καὶ κατὰ παντὸς τοῦ χρόνου σκέψασθ’ ὡς καλὰ καὶ ζηλώτ’ ἐπιγράμματα τῆς πόλεως ἀνελὼν ὡς ἀσεβῆ καὶ δείν’ ἀντεπιγέγραφεν. οἶμαι γὰρ ὑμᾶς ἅπαντας ὁρᾶν ὑπὸ τῶν στεφάνων ταῖς χοινικίσιν κάτωθεν γεγραμμένα “οἱ σύμμαχοι τὸν δῆμον ἀνδραγαθίας εἵνεκα καὶ δικαιοσύνης,” ἢ “οἱ σύμμαχοι ἀριστεῖον τῇ Ἀθηναίᾳ,” ἢ κατὰ πόλεις “οἱ δεῖνες τὸν δῆμον, σωθέντες ὑπὸ τοῦ δήμου,” οἷον “Εὐβοεῖς ἐλευθερωθέντες ἐστεφάνωσαν τὸν δῆμον,” πάλιν “Κόνων ἀπὸ τῆς ναυμαχίας τῆς πρὸς Λακεδαιμονίους·” τοιαῦτα γὰρ ἦν τὰ τῶν στεφάνων ἐπιγράμματα.", "st": "22.72"}, {"sp": "N", "t": "ταῦτα μὲν τοίνυν, ἃ ζῆλον πολὺν εἶχε καὶ φιλοτιμίαν ὑμῖν, ἠφάνισται καθαιρεθέντων τῶν στεφάνων· ἐπὶ ταῖς φιάλαις δ’ ἃς ἀντ’ ἐκείνων ἐποιήσαθ’ ὑμῖν ὁ πόρνος οὗτος, “Ἀνδροτίωνος ἐπιμελουμένου” [ἐποιήθησαν] ἐπιγέγραπται· καὶ οὗ τὸ σῶμ’ ἡταιρηκότος οὐκ ἐῶσιν οἱ νόμοι εἰς τὰ ἱέρ’ εἰσιέναι, τούτου τοὔνομ’ ἐν τοῖς ἱεροῖς ἐπὶ τῶν φιαλῶν γεγραμμένον ἐστίν. ὅμοιόν γε, οὐ γάρ; τοῦτο τοῖς προτέροις ἐπιγράμμασιν, ἢ φιλοτιμίαν ἴσην ἔχον ὑμῖν.", "st": "22.73"}, {"sp": "N", "t": "[τρία τοίνυν ἐκ τούτου τὰ δεινότατ’ ἄν τις ἴδοι πεπραγμέν’ αὐτοῖς. τὴν μὲν γὰρ θεὸν τοὺς στεφάνους σεσυλήκασιν· τῆς πόλεως δὲ τὸν ζῆλον ἠφανίκασι τὸν ἐκ τῶν ἔργων, ὧν ὑπόμνημ’ ἦσαν ὄντες οἱ στέφανοι· τοὺς δ’ ἀναθέντας δόξαν οὐ μικρὰν ἀφῄρηνται, τὸ δοκεῖν ὧν ἂν εὖ πάθωσ’ ἐθέλειν μεμνῆσθαι. καὶ τοιαῦτα καὶ τοσαῦτα τὸ πλῆθος κάκ’ εἰργασμένοι εἰς τοῦθ’ ἅμ’ ἀναισθησίας καὶ τόλμης προεληλύθασιν, [ὥστε μέμνηνται τούτων ὡς καλῶς αὐτοῖς διῳκημένων,] ὥσθ’ ὁ μὲν οἴεται δι’ ἐκεῖνον ὑφ’ ὑμῶν σωθήσεσθαι, ὁ δὲ παρακάθηται καὶ οὐ καταδύεται τοῖς πεπραγμένοις.]", "st": "22.74"}, {"sp": "N", "t": "οὕτω δ’ οὐ μόνον εἰς χρήματ’ ἀναιδής, ἀλλὰ καὶ σκαιός ἐστιν, ὥστ’ οὐκ οἶδεν ἐκεῖνο, ὅτι στέφανοι μέν εἰσ’ ἀρετῆς σημεῖον, φιάλαι δὲ καὶ τὰ τοιαῦτα πλούτου, καὶ στέφανος μὲν ἅπας, κἂν μικρὸς ᾖ, τὴν ἴσην φιλοτιμίαν ἔχει τῷ μεγάλῳ, ἐκπώματα δ’ ἢ θυμιατήρια, ἂν μὲν ὑπερβάλλῃ τῷ πλήθει, πλούτου τινὰ δόξαν προσετρίψατο τοῖς κεκτημένοις, ἐὰν δ’ ἐπὶ μικροῖς τις σεμνύνηται, τοσοῦτ’ ἀπέχει τοῦ τιμῆς τινος διὰ ταῦτα τυχεῖν ὥστ’ ἀπειρόκαλος πρὸς ἔδοξεν εἶναι. οὗτος τοίνυν ἀνελὼν τὰ τῆς δόξης κτήματα τὰ τοῦ πλούτου πεποίηται μικρὰ καὶ οὐχ ὑμῶν ἄξια.", "st": "22.75"}, {"sp": "N", "t": "καὶ οὐδ’ ἐκεῖν’ εἶδεν, ὅτι πρὸς μὲν χρημάτων κτῆσιν οὐδεπώποθ’ ὁ δῆμος ἐσπούδασεν, πρὸς δὲ δόξης ὡς οὐδὲ πρὸς ἓν τῶν ἄλλων. τεκμήριον δέ· χρήματα μὲν γὰρ πλεῖστα τῶν Ἑλλήνων ποτὲ σχὼν ἅπανθ’ ὑπὲρ φιλοτιμίας ἀνήλωσεν, εἰσφέρων δ’ ἐκ τῶν ἰδίων οὐδένα πώποτε κίνδυνον ὑπὲρ δόξης ἐξέστη. ἀφ’ ὧν κτήματ’ ἀθάνατ’ αὐτῷ περίεστιν, τὰ μὲν τῶν ἔργων ἡ μνήμη, τὰ δὲ τῶν ἀναθημάτων τῶν ἐπ’ ἐκείνοις σταθέντων τὸ κάλλος, προπύλαια ταῦτα, ὁ παρθενών, στοαί, νεώσοικοι, οὐκ ἀμφορίσκοι δύο οὐδὲ χρυσίδες τέτταρες ἢ τρεῖς, ἄγουσ’ ἑκάστη μνᾶν, ἅς, ὅταν σοι δοκῇ, σὺ πάλιν γράψεις καταχωνεύειν.", "st": "22.76"}, {"sp": "N", "t": "οὐ γὰρ ἑαυτοὺς δεκατεύοντες, οὐδ’ ἃν καταράσαινθ’ οἱ ἐχθροὶ ποιοῦντες, διπλᾶς πράττοντες τὰς εἰσφοράς, ταῦτ’ ἀνέθεσαν, οὐδ’ οἵοισπερ σὺ χρώμενοι συμβούλοις ἐπολιτεύοντο, ἀλλὰ τοὺς ἐχθροὺς κρατοῦντες, καὶ ἃ πᾶς τις ἂν εὖ φρονῶν εὔξαιτο, τὴν πόλιν εἰς ὁμόνοιαν ἄγοντες, ἀθάνατον κλέος αὑτῶν λελοίπασι, τοὺς ἐπιτηδεύοντας οἷα σοὶ βεβίωται τῆς ἀγορᾶς εἴργοντες.", "st": "22.77"}, {"sp": "N", "t": "ὑμεῖς δ’ εἰς τοῦτ’, ὦ ἄνδρες Ἀθηναῖοι, προῆχθ’ εὐηθείας καὶ ῥᾳθυμίας ὥστ’ οὐδὲ τοιαῦτ’ ἔχοντες παραδείγματα ταῦτα μιμεῖσθε, ἀλλ’ Ἀνδροτίων ὑμῖν πομπείων ἐπισκευαστής, Ἀνδροτίων, ὦ γῆ καὶ θεοί. καὶ τοῦτ’ ἀσέβημ’ ἔλαττον τίνος ἡγεῖσθε; ἐγὼ μὲν γὰρ οἴομαι δεῖν τὸν εἰς ἱέρ’ εἰσιόντα καὶ χερνίβων καὶ κανῶν ἁψόμενον, καὶ τῆς πρὸς τοὺς θεοὺς ἐπιμελείας προστάτην ἐσόμενον οὐχὶ προειρημένον ἡμερῶν ἀριθμὸν ἁγνεύειν, ἀλλὰ τὸν βίον ἡγνευκέναι τοιούτων ἐπιτηδευμάτων οἷα τούτῳ βεβίωται.", "st": "22.78"}, {"sp": "HDR", "t": "Κατὰ Ἀριστοκράτους", "st": "23"}, {"sp": "N", "t": "μηδεὶς ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, νομίσῃ μήτ’ ἰδίας ἔχθρας ἐμὲ μηδεμιᾶς ἕνεχ’ ἥκειν Ἀριστοκράτους κατηγορήσοντα τουτουί, μήτε μικρὸν ὁρῶντά τι καὶ φαῦλον ἁμάρτημ’ ἑτοίμως οὕτως ἐπὶ τούτῳ προάγειν ἐμαυτὸν εἰς ἀπέχθειαν, ἀλλ’ εἴπερ ἄρ’ ὀρθῶς ἐγὼ λογίζομαι καὶ σκοπῶ, ὑπὲρ τοῦ Χερρόνησον ἔχειν ὑμᾶς ἀσφαλῶς καὶ μὴ παρακρουσθέντας ἀποστερηθῆναι πάλιν αὐτῆς, περὶ τούτου μοί ἐστιν ἅπασ’ ἡ σπουδή.", "st": "23.1"}, {"sp": "N", "t": "δεῖ δὴ πάντας ὑμᾶς, εἰ βούλεσθ’ ὀρθῶς περὶ τούτων μαθεῖν καὶ κατὰ τοὺς νόμους δικαίως κρῖναι τὴν γραφήν, μὴ μόνον τοῖς γεγραμμένοις ἐν τῷ ψηφίσματι ῥήμασιν προσέχειν, ἀλλὰ καὶ τὰ συμβησόμεν’ ἐξ αὐτῶν σκοπεῖν. εἰ μὲν γὰρ ἦν ἀκούσασιν εὐθὺς εἰδέναι τὰ κεκακουργημένα, τὴν ἀρχὴν ἴσως ἂν οὐκ ἐξηπάτησθε·", "st": "23.2"}, {"sp": "N", "t": "ἐπειδὴ δὲ τοῦθ’ ἕν ἐστι τῶν ἀδικημάτων, τὸ τοῦτον τὸν τρόπον καὶ λέγειν καὶ γράφειν ἐνίους ὃν ἂν ἥκισθ’ ὑμεῖς ὑπίδοισθέ τι καὶ φυλάξαισθε, προσήκει μὴ πάνυ θαυμάζειν, εἰ καὶ τοῦτο τὸ ψήφισμ’ ἡμεῖς οὕτω γεγραμμένον ἐπιδείξομεν ὥστε δοκεῖν μὲν Χαριδήμῳ φυλακήν τινα τοῦ σώματος διδόναι, τὴν ὡς ἀληθῶς δὲ δικαίαν καὶ βέβαιον [φυλακὴν Χερρονήσου] τῆς πόλεως ἀποστερεῖν.", "st": "23.3"}, {"sp": "N", "t": "εἰκότως δ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, καὶ προσέχοιτέ μοι τὸν νοῦν καὶ μετ’ εὐνοίας ἀκούσαιθ’ ἃ λέγω. ἐπειδὴ γάρ, οὐχὶ τῶν ἐνοχλούντων ὑμᾶς οὐδὲ τῶν πολιτευομένων καὶ πιστευομένων παρ’ ὑμῖν ὤν, πρᾶγμα τηλικοῦτόν φημι δείξειν πεπραγμένον, ἐάν, ὅσον ἐστὶν ἐν ὑμῖν, συναγωνίσησθέ μοι καὶ προθύμως ἀκούσητε, τοῦτό τε σώσετε καὶ ποιήσετε μὴ κατοκνεῖν, ἐάν τίς τι καὶ ἡμῶν οἴηται δύνασθαι ποιῆσαι τὴν πόλιν ἀγαθόν. οἰήσεται δέ, ἂν μὴ χαλεπὸν εἶναι νομίζῃ τὸ παρ’ ὑμῖν λόγου τυχεῖν.", "st": "23.4"}, {"sp": "N", "t": "νῦν δὲ πολλοῖς τοῦτο φοβουμένοις, λέγειν μὲν ἴσως οὐ δεινοῖς, βελτίοσι δ’ ἀνθρώποις τῶν δεινῶν, οὐδὲ σκοπεῖν ἐπέρχεται τῶν κοινῶν οὐδέν. ἐγὼ γοῦν (ὀμνύω τοὺς θεοὺς ἅπαντας) ἀπώκνησ’ ἄν, εὖ ἴστε, καὶ αὐτὸς τὴν γραφὴν ταύτην ἀπενεγκεῖν, εἰ μὴ πάνυ τῶν αἰσχρῶν ἐνόμιζον εἶναι νῦν μὲν ἡσυχίαν ἄγειν καὶ σιωπῆσαι, πρᾶγμ’ ἀλυσιτελὲς τῇ πόλει κατασκευάζοντας ὁρῶν τινας ἀνθρώπους, πρότερον δέ, ὅτ’ ἔπλευσα τριηραρχῶν εἰς Ἑλλήσποντον, εἰπεῖν καὶ κατηγορῆσαί τινων, οὓς ἀδικεῖν ὑμᾶς ἡγούμην.", "st": "23.5"}, {"sp": "N", "t": "οὐκ ἀγνοῶ μὲν οὖν ὅτι τὸν Χαρίδημον εὐεργέτην εἶναί τινες τῆς πόλεως οἴονται· ἐγὼ δέ, ἄν περ ἃ βούλομαί τε καὶ οἶδα πεπραγμέν’ ἐκείνῳ δυνηθῶ πρὸς ὑμᾶς εἰπεῖν, οἶμαι δείξειν οὐ μόνον οὐκ εὐεργέτην, ἀλλὰ καὶ κακονούστατον ἀνθρώπων ἁπάντων καὶ πολὺ τἀναντί’ ἢ προσῆκεν ὑπειλημμένον.", "st": "23.6"}, {"sp": "N", "t": "εἰ μὲν οὖν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο μέγιστον Ἀριστοκράτης ἠδίκει, τὸ τοιούτου, οἷον ἐγώ φημι δείξειν τὸν Χαρίδημον ὄντα, τοσαύτην πεποιῆσθαι πρόνοιαν ἐν τῷ ψηφίσματι ὥστ’ ἰδίαν παρὰ τοὺς νόμους, ἄν τι πάθῃ, τιμωρίαν αὐτῷ δεδωκέναι, ταῦτ’ ἂν ἤδη λέγειν πρὸς ὑμᾶς ἐπεχείρουν, ἵν’ εἰδῆτε πολλοῦ δεῖν ἄξιον ὄντα τυχεῖν τοῦ ψηφίσματος αὐτὸν τουτουί. νυνὶ δ’ ἕτερον τούτου μεῖζον διὰ τοῦ ψηφίσματος ἔστ’ ἀδίκημα, ὃ δεῖ πρότερον καὶ μαθεῖν ὑμᾶς καὶ φυλάξασθαι.", "st": "23.7"}, {"sp": "N", "t": "ἀνάγκη δὲ ἐστὶ πρῶτον ἁπάντων εἰπεῖν καὶ δεῖξαι τί ποτ’ ἐστὶ τὸ Χερρόνησον ὑμᾶς ἀσφαλῶς ἔχειν πεποιηκός· διὰ γὰρ τοῦ μαθεῖν τοῦτο καὶ τἀδίκημα σαφῶς ὄψεσθε. ἔστι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο, τὸ τελευτήσαντος Κότυος Βηρισάδην καὶ Ἀμάδοκον καὶ Κερσοβλέπτην τρεῖς ἀνθ’ ἑνὸς γενέσθαι Θρᾴκης βασιλέας· συμβέβηκε γὰρ ἐκ τούτου αὑτοῖς μὲν ἀντιπάλους εἶναι τούτους, ὑμᾶς δ’ ὑπέρχεσθαι καὶ θεραπεύειν.", "st": "23.8"}, {"sp": "N", "t": "τοῦτο τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, βουλόμενοί τινες παῦσαι, καὶ καταλῦσαι μὲν τοὺς ἑτέρους βασιλέας, παραδοῦναι δ’ ἑνὶ τῷ Κερσοβλέπτῃ τὴν ἀρχὴν ἅπασαν, διαπράττονταί σφισι τοῦτο γενέσθαι τὸ προβούλευμα, τῷ μὲν ἀκοῦσαι κεχωρισμένον τοῦ τι τοιοῦτον δοκεῖν διαπράξασθαι, τῷ δ’ ἔργῳ πάντων μάλιστα τοῦτο περαίνοντες, ὡς ἐγὼ διδάξω.", "st": "23.9"}, {"sp": "N", "t": "ἐπειδὴ γὰρ ἑνὸς τελευτήσαντος τῶν βασιλέων Βηρισάδου, παραβὰς τοὺς ὅρκους καὶ τὰς συνθήκας ἃς μεθ’ ὑμῶν ἐποιήσατο, Κερσοβλέπτης ἐξέφερεν πόλεμον πρός τε τοὺς Βηρισάδου παῖδας καὶ πρὸς Ἀμάδοκον, εὔδηλον ἦν ὅτι τοῖς μὲν Βηρισάδου παισὶν Ἀθηνόδωρος βοηθήσοι, τῷ δ’ Ἀμαδόκῳ Σίμων καὶ Βιάνωρ· ὁ μὲν γὰρ Βηρισάδου κηδεστής, οἱ δ’ Ἀμαδόκου γεγόνασιν.", "st": "23.10"}, {"sp": "N", "t": "ἐσκόπουν οὖν τίν’ ἂν τρόπον ἡσυχίαν μὲν ἔχειν ἀναγκασθεῖεν οὗτοι, ἐρήμων δ’ ὄντων ἐκείνων ὁ Κερσοβλέπτῃ πράττων τὴν ἀρχὴν Χαρίδημος ἀσφαλῶς πάντα καταστρέψαιτο. εἰ πρῶτον μέν, ἄν τις αὐτὸν ἀποκτείνῃ, ψήφισμ’ ὑμέτερον γένοιτο, ἀγώγιμον εἶναι· δεύτερον δέ, εἰ χειροτονηθείη στρατηγὸς ὑφ’ ὑμῶν Χαρίδημος.", "st": "23.11"}, {"sp": "N", "t": "οὔτε γὰρ ὑμετέρῳ στρατηγῷ προχείρως ἐναντία θήσεσθαι τὰ ὅπλ’ ἔμελλ’ ὁ Σίμων οὐδ’ ὁ Βιάνωρ, πολῖται γεγενημένοι καὶ ἄλλως ἐσπουδακότες πρὸς ὑμᾶς· ὁ δὲ δὴ γένει πολίτης Ἀθηνόδωρος οὐδὲ βουλεύσεσθαι· οὔτε τὴν διὰ τοῦ ψηφίσματος αἰτίαν ὑποδύσεσθαι, ἣ πρόδηλος ἦν ἐπ’ ἐκείνους ἥξουσα, εἴ τι πάθοι Χαρίδημος. ἐκ δὲ τούτου τοῦ τρόπου τῶν μὲν ἐρήμων ὄντων βοηθῶν, αὑτοῖς δ’ ἀδείας δοθείσης, ῥᾳδίως ἐκβαλεῖν ἐκείνους καὶ κατασχήσειν τὴν ἀρχήν.", "st": "23.12"}, {"sp": "N", "t": "καὶ ὅτι ταῦθ’ οὕτως ᾤοντο καὶ τοῦτ’ ἦν τὸ κατασκεύασμ’ αὐτοῖς, τὰ πραχθέντ’ αὐτὰ κατηγορεῖ. ἅμα γὰρ τῷ πολέμῳ τ’ ἐνεχείρουν αὐτοὶ καὶ πρὸς ὑμᾶς ἧκεν Ἀριστόμαχος πρεσβευτὴς παρ’ αὐτῶν ὁ Ἀλωπεκῆθεν οὑτοσί, ὃς ἄλλα τ’ ἐδημηγόρει παρ’ ὑμῖν ἐπαινῶν καὶ διεξιὼν τὸν Κερσοβλέπτην καὶ τὸν Χαρίδημον, ὡς φιλανθρώπως ἔχουσι πρὸς ὑμᾶς,", "st": "23.13"}, {"sp": "N", "t": "καὶ μόνον ἀνθρώπων ἂν ἔφη Χαρίδημον Ἀμφίπολιν κομίσασθαι τῇ πόλει δύνασθαι, καὶ παρῄνει στρατηγὸν χειροτονῆσαι. ἡτοίμαστο δ’ αὐτοῖς τοῦτο τὸ προβούλευμα καὶ προδιῴκητο, ἵν’ εἰ πεισθείητ’ ἐκ τῶν ὑποσχέσεων καὶ τῶν ἐλπίδων ἃς ὑπέτειν’ ὁ Ἀριστόμαχος, εὐθὺς ἐπικυρώσειεν ὁ δῆμος καὶ μηδὲν ἐμποδὼν εἴη.", "st": "23.14"}, {"sp": "N", "t": "καίτοι πῶς ἂν τεχνικώτερον ἢ κακουργότερον συμπαρεσκεύασαν ἄνθρωποι, ὅπως οἱ μὲν ἐκπεσοῦνται τῶν βασιλέων, εἷς δ’ ὃν αὐτοὶ βούλονται πᾶσαν ὑφ’ αὑτῷ ποιήσεται τὴν ἀρχήν, ἢ τοὺς μὲν τοῖν δυοῖν βοηθήσαντας ἂν εἰς φόβον καὶ συκοφαντίας εὐλάβειαν καθιστάντες, [ἣν εἰκὸς προσδοκᾶν ἐκείνους ἐφ’ ἑαυτοὺς ἐλθεῖν ἂν διὰ τοῦ ψηφίσματος τουτουί,] τῷ δ’ ἑνὶ πράττοντι τὴν ἀρχὴν καὶ πάντα τἀναντία τοῖς ὑμῖν συμφέρουσι κατασκευάζοντι τοσαύτην ἐξουσίαν διδόντες τοῦ ταῦτ’ ἀδεῶς πράττειν;", "st": "23.15"}, {"sp": "N", "t": "οὐ τοίνυν μόνον ἐκ τούτων δῆλόν ἐσθ’ ὅτι τούτων ἕνεκ’ ἐρρήθη τὸ προβούλευμ’ ὧν λέγω, ἀλλὰ καὶ ἐκ τοῦ ψηφίσματος αὐτοῦ μαρτυρία τίς ἐστ’ εὐμεγέθης. “ἂν γὰρ ἀποκτείνῃ τις Χαρίδημον” γράψας καὶ παραβὰς τὸ τί πράττοντ’ εἰπεῖν, πότερ’ ἡμῖν συμφέροντ’ ἢ οὔ, γέγραφ’ εὐθὺς “ἀγώγιμον ἐκ τῶν συμμάχων εἶναι.”", "st": "23.16"}, {"sp": "N", "t": "οὐκοῦν τῶν μὲν ἐχθρῶν ὁμοίως ἡμῖν τε κἀκείνῳ οὐδέποτ’ εἰς τοὺς ἡμετέρους ἥξει συμμάχους οὐδείς, οὔτ’ ἀποκτείνας ἐκεῖνον οὔτε μή, ὥστ’ οὐ κατὰ τούτων γέγραφεν ταύτην τὴν τιμωρίαν. τῶν δ’ ἡμετέρων μὲν φίλων, ἐκείνου δέ, ὅταν ἐγχειρῇ τι πράττειν ἐναντίον ὑμῖν, ἐχθρῶν, τούτων δή τίς ἐστιν ὁ τοῦτο τὸ ψήφισμα φοβηθεὶς ἂν καὶ φυλαξάμενος μὴ δι’ ἀνάγκην ἡμῖν εἰς ἔχθραν ἐλθεῖν. ἔστι τοίνυν οὗτος Ἀθηνόδωρος, Σίμων, Βιάνωρ, οἱ Θρᾴκης βασιλεῖς, ἄλλος ὅστις ἂν εἰς εὐεργεσίας μέρος καταθέσθαι βούλοιτο τὸ πράττειν ὑπεναντί’ ἐκεῖνον ἐγχειροῦνθ’ ὑμῖν ἐπισχεῖν.", "st": "23.17"}, {"sp": "N", "t": "ὧν μὲν τοίνυν ἕνεκ’ ἐρρήθη τὸ προβούλευμα, ἵνα κυρώσειεν ὁ δῆμος ἐξαπατηθείς, καὶ δι’ ἃ τὴν γραφὴν ἐποιησάμεθ’ ἡμεῖς ταυτηνί, βουλόμενοι κωλῦσαι, ταῦτ’ ἐστίν, ὦ ἄνδρες Ἀθηναῖοι. δίκαιον δ’ ἐστὶν ἴσως ἔμ’ ὑπεσχημένον τρί’ ἐπιδείξειν, ἓν μὲν ὡς παρὰ τοὺς νόμους τὸ ψήφισμ’ εἴρηται, δεύτερον δ’ ὡς ἀσύμφορόν ἐστι τῇ πόλει, τρίτον δ’ ὡς ἀνάξιος τυχεῖν [τούτων] ᾧ γέγραπται, πάντων αἵρεσιν ὑμῖν δοῦναι τοῖς ἀκουσομένοις, τί πρῶτον ἢ τί δεύτερον ἢ τί τελευταῖον βουλομένοις ἀκούειν ὑμῖν ἐστιν.", "st": "23.18"}, {"sp": "N", "t": "ὅ τι δὴ βούλεσθε, ὁρᾶτε, ἵνα τοῦτο λέγω πρῶτον ὑμῖν. περὶ τοῦ παρανόμου βούλεσθε πρῶτον; τοῦτο τοίνυν ἐροῦμεν. ἃ δὴ δέομαι καὶ ἀξιῶ παρὰ πάντων ὑμῶν τυχεῖν, δίκαια, ὥς γ’ ἐμαυτὸν πείθω· μηδεὶς ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, τῷ διεψεῦσθαι τοῦ Χαριδήμου καὶ νομίζειν εὐεργέτην εἶναι φιλονικῶν δυσχερέστερον τοὺς περὶ τῶν νόμων λόγους ἀκούσῃ μου, μηδ’ ἀποστερήσῃ διὰ τοῦτο μήθ’ ἑαυτὸν τοῦ θέσθαι τὴν ψῆφον εὔορκον μήτ’ ἐμὲ τοῦ διδάξαι περὶ πάντων ὑμᾶς ὡς βούλομαι. ἀλλὰ ποιησάσθω τὴν ἀκρόασιν ὡδί· καὶ σκοπεῖσθ’ ὡς δίκαι’ ἐρῶ·", "st": "23.19"}, {"sp": "N", "t": "ὅταν μὲν λέγω περὶ τῶν νόμων, ἀφελὼν ὅτῳ τὸ ψήφισμ’ εἴρηται καὶ ποίῳ τινί, σκοπείσθω πότερον παρὰ τοὺς νόμους ἢ κατ’ αὐτοὺς εἴρηται, καὶ μηδὲν ἄλλο· ὅταν δ’ ἐλέγχω τὰ πεπραγμένα καὶ διεξίω τὸν τρόπον ὃν πεφενάκισθ’ ὑπ’ αὐτοῦ, τὰς πράξεις σκοπείσθω, πότερον γεγονυίας ἢ ψευδεῖς ἐρῶ·", "st": "23.20"}, {"sp": "N", "t": "ὅταν δ’ ἐξετάζω περὶ τοῦ συμφέρειν ἢ μὴ τῇ πόλει ταῦτα ψηφίσασθαι, πάντα τἄλλ’ ἀφεὶς τοὺς λογισμοὺς ὁράτω τοὺς περὶ τούτων, πότερ’ ὀρθῶς ἔχοντας ποιοῦμαι ἢ οὔ. ἐὰν γὰρ τοῦτον ἔχοντες τὸν τρόπον ἀκροάσησθέ μου, αὐτοί τ’ ἄρισθ’ ἃ προσήκει συνήσετε, χωρὶς ἕκαστα σκοποῦντες καὶ οὐχ ἅμα πάνθ’ ἁθρό’ ἐξετάζοντες, κἀγὼ ῥᾷσθ’ ἃ βούλομαι δυνήσομαι διδάξαι. ἔσονται δὲ βραχεῖς περὶ πάντων οἱ λόγοι·", "st": "23.21"}, {"sp": "N", "t": "λαβὲ δὴ τοὺς νόμους αὐτοὺς καὶ λέγε, ἵν’ ἐξ αὐτῶν ἐπιδεικνύω τούτων τὸ παράνομον.", "st": "23.22"}, {"sp": "N", "t": "ΝΟΜΟΣ ΕΚ ΤΩΝ ΦΟΝΙΚΩΝ ΝΟΜΩΝ ΤΩΝ ΕΞ ΑΡΕΙΟΥ ΠΑΓΟΥ.", "st": "23.22"}, {"sp": "N", "t": "δικάζειν δὲ τὴν βουλὴν τὴν ἐν Ἀρείῳ πάγῳ φόνου καὶ τραύματος ἐκ προνοίας καὶ πυρκαϊᾶς καὶ φαρμάκων, ἐάν τις ἀποκτείνῃ δούς.", "st": "23.22"}, {"sp": "N", "t": "ἐπίσχες. ἠκούσατε μὲν τοῦ τε νόμου καὶ τοῦ ψηφίσματος, ὦ ἄνδρες Ἀθηναῖοι· ὡς δ’ ἄν μοι δοκεῖτε τοὺς περὶ τοῦ παρανόμου λόγους αὐτοὺς ῥᾷστα μαθεῖν, τοῦθ’ ὑμῖν φράσω· εἰ σκέψαισθ’ ἐν τίνι τάξει ποτ’ ἔσθ’ ὑπὲρ οὗ τὸ ψήφισμ’ εἴρηται, πότερα ξένος ἢ μέτοικος ἢ πολίτης ἐστίν. εἰ μὲν δὴ μέτοικον φήσομεν, οὐκ ἐροῦμεν ἀληθῆ, εἰ δ’ αὖ ξένον, οὐχὶ δίκαια ποιήσομεν· τὴν γὰρ τοῦ δήμου δωρειάν, ἐν ᾗ πολίτης γέγονεν, κυρίαν αὐτῷ δίκαιόν ἐστιν εἶναι. ὡς ὑπὲρ πολίτου τοίνυν, ὡς ἔοικε, ποιητέον τοὺς λόγους.", "st": "23.23"}, {"sp": "N", "t": "θεάσασθε δὴ πρὸς Διὸς ὡς ἁπλῶς καὶ δικαίως χρήσομαι τῷ λόγῳ, ὃς εἰς μὲν ταύτην τίθεμαι τὴν τάξιν αὐτὸν ἐν ᾗ πλείστης ἂν τυγχάνοι τιμῆς, ἃ δ’ οὐδ’ ἡμῖν τοῖς γένει πολίταις ἐστίν, οὐδ’ ἐκείνῳ δεῖν οἶμαι γενέσθαι παρὰ τοὺς νόμους. τίν’ οὖν ἐστι ταῦτα; ἃ νυνὶ γέγραφ’ οὑτοσί. γέγραπται γὰρ ἐν μὲν τῷ νόμῳ “τὴν βουλὴν δικάζειν φόνου καὶ τραύματος ἐν προνοίας καὶ πυρκαϊᾶς καὶ φαρμάκων, ἐάν τις ἀποκτείνῃ δούς.”", "st": "23.24"}, {"sp": "N", "t": "καὶ προσειπὼν ὁ θεὶς τὸν νόμον “ἐὰν ἀποκτείνῃ,” κρίσιν πεποίηκεν ὅμως, οὐ πρότερον τί χρὴ πάσχειν τὸν δεδρακότ’ εἴρηκεν, καλῶς, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’ ὑπὲρ εὐσεβείας ὅλης τῆς πόλεως προϊδών. πῶς; οὐκ ἔνεστιν ἅπαντας ἡμᾶς εἰδέναι τίς ποτ’ ἐστὶν ὁ ἀνδροφόνος. τὸ μὲν δὴ τὰ τοιαῦτ’ ἄνευ κρίσεως πιστεύειν, ἄν τις ἐπαιτιάσηται, δεινὸν ἡγεῖτο, δεῖν δ’ ὑπελάμβανεν, ἐπειδήπερ ἡμεῖς τιμωρήσομεν τῷ πεπονθότι, πεισθῆναι καὶ μαθεῖν ἡμᾶς διδασκομένους ὡς δέδρακεν· τηνικαῦτα γὰρ εὐσεβὲς ἤδη κολάζειν εἰδόσιν εἶναι, πρότερον δ’ οὔ.", "st": "23.25"}, {"sp": "N", "t": "καὶ ἔτι πρὸς τούτῳ διελογίζετο, ὅτι πάντα τὰ τοιαῦτ’ ὀνόματα, οἷον ἐάν τις ἀποκτείνῃ, ἐάν τις ἱεροσυλήσῃ, ἐάν τις προδῷ, καὶ τὰ τοιαῦτα πάντα πρὸ μὲν τοῦ κρίσιν γενέσθαι αἰτιῶν ὀνόματ’ ἐστίν, ἐπειδὰν δὲ κριθείς τις ἐξελεγχθῇ, τηνικαῦτ’ ἀδικήματα γίγνεται. οὐ δὴ δεῖν ᾤετο τῷ τῆς αἰτίας ὀνόματι τιμωρίαν προσγράφειν, ἀλλὰ κρίσιν. καὶ διὰ ταῦτα, ἄν τις ἀποκτείνῃ τινά, τὴν βουλὴν δικάζειν ἔγραψεν, καὶ οὐχ ἅπερ, ἂν ἁλῷ, παθεῖν εἶπεν.", "st": "23.26"}, {"sp": "N", "t": "ὁ μὲν δὴ τὸν νόμον τιθεὶς οὕτως, ὁ δὲ τὸ ψήφισμα γράφων πῶς; “ἐάν τις ἀποκτείνῃ” φησὶν “Χαρίδημον.” τὴν μὲν δὴ προσηγορίαν τοῦ πάθους τὴν αὐτὴν ἐποιήσατο, “ἄν τις ἀποκτείνῃ” γράψας, ἥνπερ ὁ τὸν νόμον τιθείς· μετὰ ταῦτα δ’ οὐκέτι ταὐτά, ἀλλ’ ἀνελὼν τὸ δίκην ὑπέχειν ἀγώγιμον εὐθὺς ἐποίησεν, καὶ παραβὰς τὸ διωρισμένον ἐκ τοῦ νόμου δικαστήριον, ἄκριτον τοῖς ἐπαιτιασαμένοις παρέδωκεν ὅ τι ἂν βούλωνται χρῆσθαι τὸν οὐδ’ εἰ πεποίηκέ πω φανερόν.", "st": "23.27"}, {"sp": "N", "t": "καὶ λαβοῦσιν ἐκείνοις ἐξέσται στρεβλοῦν, αἰκίσασθαι, χρήματα πράξασθαι. καίτοι πάντα ταῦτ’ ἀπείρηκεν ἄντικρυς καὶ σαφῶς ὁ κάτωθεν νόμος μηδὲ τοὺς ἑαλωκότας καὶ δεδογμένους ἀνδροφόνους ἐξεῖναι ποιεῖν. λέγε δ’ αὐτοῖς αὐτὸν τὸν νόμον τὸν μετὰ ταῦτα.", "st": "23.28"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.28"}, {"sp": "N", "t": "τοὺς δ’ ἀνδροφόνους ἐξεῖναι ἀποκτείνειν ἐν τῇ ἡμεδαπῇ καὶ ἀπάγειν, ὡς ἐν τῷ ⟨α⟩ ἄξονι ἀγορεύει, λυμαίνεσθαι δὲ μή, μηδὲ ἀποινᾶν, ἢ διπλοῦν ὀφείλειν ὅσον ἂν καταβλάψῃ. εἰσφέρειν δ’ ἐ⟨ς⟩ τοὺς ἄρχοντας, ὧν ἕκαστοι δικασταί εἰσι, τῷ βουλομένῳ. τὴν δ’ ἡλιαίαν διαγιγνώσκειν.", "st": "23.28"}, {"sp": "N", "t": "ἠκούσατε μὲν τοῦ νόμου, σκέψασθε δ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ θεωρήσατε ὡς καλῶς καὶ σφόδρ’ εὐσεβῶς ἔθηκε ὁ τιθεὶς τὸν νόμον. “τοὺς ἀνδροφόνους” φησίν. πρῶτον μὲν δὴ τοῦτον ἀνδροφόνον λέγει, τὸν ἑαλωκότ’ ἤδη τῇ ψήφῳ. οὐ γάρ ἐστ’ οὐδεὶς ὑπὸ ταύτῃ τῇ προσηγορίᾳ, πρὶν ἂν ἐξελεγχθεὶς ἁλῷ.", "st": "23.29"}, {"sp": "N", "t": "ποῦ τοῦτο δηλοῖ; ἔν τε τῷ προτέρῳ νόμῳ καὶ τούτῳ. ἐν μὲν γὰρ ἐκείνῳ γράψας “ἐάν τις ἀποκτείνῃ,” τὴν βουλὴν δικάζειν εἶπεν, ἐν δὲ τούτῳ τὸν ἀνδροφόνον προσειπών, ἃ χρὴ πάσχειν εἴρηκεν· οὗ μὲν γὰρ ἦν αἰτία τὸ πρᾶγμα, τὴν κρίσιν εἴρηκεν, οὗ δ’ ὁ ἁλοὺς ἔνοχος τῷ προσρήματι τούτῳ καθέστηκεν, τὴν τιμωρίαν ἔγραψεν. περὶ μὲν δὴ τῶν ἑαλωκότων ἂν λέγοι. λέγει δὲ τί;", "st": "23.30"}, {"sp": "N", "t": "“ἐξεῖναι ἀποκτείνειν καὶ ἀπάγειν.” ἆρ’ ὡς αὑτόν; ἢ ὡς ἂν βούληταί τις; πολλοῦ γε καὶ δεῖ. ἀλλὰ πῶς; “ὡς ἐν τῷ ⟨α⟩ ἄξονι εἴρηται” φησίν. τοῦτο δ’ ἐστὶν τί; ὃ πάντες ἐπίστασθ’ ὑμεῖς. οἱ θεσμοθέται τοὺς ἐπὶ φόνῳ φεύγοντας κύριοι θανάτῳ ζημιῶσαί [εἰσι], καὶ τὸν ἐκ τῆς ἐκκλησίας πέρυσιν πάντες ἑωρᾶθ’ ὑπ’ ἐκείνων ἀπαχθέντα.", "st": "23.31"}, {"sp": "N", "t": "ὡς τούτους οὖν ἀπάγειν λέγει. διαφέρει δὲ τί τοῦτο τοῦ ὡς αὑτὸν ἄγειν; ὅτι ὁ μὲν ἀπάγων, ὦ ἄνδρες Ἀθηναῖοι, ὡς τοὺς θεσμοθέτας, τοὺς νόμους κυρίους ποιεῖ τοῦ δεδρακότος, ὁ δ’ ὡς αὑτὸν ἄγων ἑαυτόν. ἔστι δ’ ἐκείνως μέν, ὡς ὁ νόμος τάττει, δοῦναι δίκην, οὕτω δέ, ὡς ὁ λαβὼν βούλεται. πλεῖστον δὲ δήπου διαφέρει τὸν νόμον κύριον τῆς τιμωρίας ἢ τὸν ἐχθρὸν γίγνεσθαι.", "st": "23.32"}, {"sp": "N", "t": "“λυμαίνεσθαι δὲ” φησὶ “μή, μηδὲ ἀποινᾶν.” ταῦτα δ’ ἐστὶν τί; τὸ μὲν δὴ μὴ λυμαίνεσθαι γνώριμον οἶδ’ ὅτι πᾶσιν μὴ μαστιγοῦν, μὴ δεῖν, μὴ τὰ τοιαῦτα ποιεῖν λέγει, τὸ δὲ μηδ’ ἀποινᾶν μὴ χρήματα πράττεσθαι· τὰ γὰρ χρήματ’ ἄποιν’ ὠνόμαζον οἱ παλαιοί.", "st": "23.33"}, {"sp": "N", "t": "ὁ μὲν δὴ νόμος οὕτως τὸν ἀνδροφόνον καὶ τὸν ἑαλωκότ’ ἤδη διώρισεν ὡς κολαστέον καὶ οὗ, τὴν τοῦ πεπονθότος εἰπὼν πατρίδα, καὶ περὶ τοῦ μηδέν’ ἄλλον τρόπον ἢ τοῦτον μηδ’ ἄλλοθι πλὴν ἐνταῦθ’ ἄντικρυς εἴρηκεν. ὁ δὲ τὸ ψήφισμα γράφων, πολλοῦ γε δεῖ, διώρισεν, ὅς γε πάντα τούτοις τἀναντί’ εἴρηκεν· γράψας γὰρ “ἐάν τις ἀποκτείνῃ Χαρίδημον,” “ἀγώγιμος ἔστω” φησὶν “πανταχόθεν.”", "st": "23.34"}, {"sp": "N", "t": "τί λέγεις; τῶν νόμων οὐδὲ τοὺς ἑαλωκότας διδόντων ἀπάγειν πλὴν ἐν τῇ ἡμεδαπῇ, σὺ γράφεις ἄνευ κρίσεώς τιν’ ἀγώγιμον ἐκ τῆς συμμαχίδος πάσης; καὶ οὐδ’ ἐν τῇ ἡμεδαπῇ ἄγειν κελευόντων τῶν νόμων, σὺ δίδως ἄγειν πανταχόθεν; καὶ μὴν ἔν γε τῷ ποιεῖν ἀγώγιμον πάνθ’ ὅσ’ ἀπείρηκεν ὁ νόμος δέδωκας, χρήματα πράξασθαι, ζῶντα λυμαίνεσθαι, κακοῦν ἔχοντα, αὐτὸν ἀποκτιννύναι.", "st": "23.35"}, {"sp": "N", "t": "πῶς οὖν ἄν τις μᾶλλον ἐλεγχθείη παράνομ’ εἰρηκὼς ἢ πῶς δεινότερ’ ἂν γράφων ἢ τοῦτον τὸν τρόπον; ὃς δυοῖν ὑποκειμένων ὀνομάτων, κατὰ μὲν τῶν ἐν αἰτίᾳ, “ἐάν τις ἀποκτείνῃ,” κατὰ δὲ τῶν ἑαλωκότων, “ἐάν τις ἀνδροφόνος ᾖ,” ἐν μὲν τῇ προσηγορίᾳ τὸ τοῦ τὴν αἰτίαν ἔχοντος ἔλαβες ὄνομα, τὴν δὲ τιμωρίαν, ἣν οὐδὲ κατὰ τῶν ἐξεληλεγμένων διδόασιν οἱ νόμοι, ταύτην κατὰ τῶν ἀκρίτων ἔγραψας, καὶ τὸ μέσον τούτων ἐξεῖλες. μέσον γάρ ἐστιν αἰτίας καὶ ἐλέγχου κρίσις, ἣν οὐδαμοῦ γέγραφ’ οὗτος ἐν τῷ ψηφίσματι.", "st": "23.36"}, {"sp": "N", "t": "λέγε τοὺς ἐφεξῆς νόμους.", "st": "23.37"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.37"}, {"sp": "N", "t": "ἐὰν δέ τις τὸν ἀνδροφόνον κτείνῃ ἢ αἴτιος ᾖ φόνου, ἀπεχόμενον ἀγορᾶς ἐφορίας καὶ ἄθλων καὶ ἱερῶν Ἀμφικτυονικῶν, ὥσπερ τὸν Ἀθηναῖον κτείναντα, ἐν τοῖς αὐτοῖς ἐνέχεσθαι, διαγιγνώσκειν δὲ τοὺς ἐφέτας.", "st": "23.37"}, {"sp": "N", "t": "τουτονὶ δεῖ μαθεῖν ὑμᾶς, ὦ ἄνδρες Ἀθηναῖοι, τὸν νόμον τί ποτ’ ἐβούλεθ’ ὁ θείς· ὄψεσθε γὰρ ὡς ἅπαντ’ εὐλαβῶς διώρισε καὶ νομίμως.", "st": "23.37"}, {"sp": "N", "t": "“ἐάν τις ἀποκτείνῃ τὸν ἀνδροφόνον” φησὶν “ἢ αἴτιος ᾖ φόνου, ἀπεχόμενον ἀγορᾶς ἐφορίας καὶ ἄθλων καὶ ἱερῶν Ἀμφικτυονικῶν, ὥσπερ τὸν Ἀθηναῖον κτείναντα, ἐν τοῖς αὐτοῖς ἐνέχεσθαι, διαγιγνώσκειν δὲ τοὺς ἐφέτας.” τί δὴ ταῦτ’ ἐστίν; ἐκεῖνος ᾤετο τὸν πεφευγότ’ ἐπ’ αἰτίᾳ φόνου καὶ ἑαλωκότα, ἐάνπερ ἅπαξ ἐκφύγῃ καὶ σωθῇ, εἴργειν μὲν τῆς τοῦ παθόντος πατρίδος δίκαιον εἶναι, κτείνειν δ’ οὐχ ὅσιον πανταχοῦ. τί σκοπῶν; ὅτι καὶ τοὺς δεῦρο πεφευγότας, ἂν ἡμεῖς τοὺς ἑτέρωσ’ ἀποκτιννύωμεν, ἀποκτενοῦσ’ ἕτεροι.", "st": "23.38"}, {"sp": "N", "t": "εἰ δὲ τοῦτ’ ἔσται, ἡ μόνη λοιπὴ τοῖς ἀτυχοῦσιν ἅπασι σωτηρία διαφθαρήσεται. ἔστι δ’ αὕτη τίς; ἐκ τῆς τῶν πεπονθότων μεταστάντα εἰς τὴν τῶν μηδὲν ἠδικημένων ἀδεῶς μετοικεῖν. ἵνα δὴ μὴ τοῦτ’ ᾖ μηδ’ ἀπέραντοι τῶν ἀτυχημάτων αἱ τιμωρίαι γίγνωνται, ἔγραψεν “ἐάν τις τὸν ἀνδροφόνον κτείνῃ ἀπεχόμενον” φησὶν “ἀγορᾶς ἐφορίας.” τί τοῦτο λέγων; τῶν ὁρίων τῆς χώρας· ἐνταῦθα γάρ, ὥς γ’ ἐμοὶ δοκεῖ, τἀρχαῖα συνῇσαν οἱ πρόσχωροι παρά θ’ ἡμῶν καὶ τῶν ἀστυγειτόνων, ὅθεν ὠνόμακεν “ἀγορὰν ἐφορίαν.”", "st": "23.39"}, {"sp": "N", "t": "καὶ πάλιν “ἱερῶν Ἀμφικτυονικῶν.” τί δήποτε καὶ τούτων ἀπέκλεισε τὸν ἀνδροφόνον; ὅσων τῷ παθόντι ζῶντι μετῆν, τούτων εἴργει τὸν δεδρακότα, πρῶτον μὲν τῆς πατρίδος καὶ τῶν ἐν ταύτῃ πάντων καὶ ὁσίων καὶ ἱερῶν, τὴν ἐφορίαν ἀγορὰν ὅρον προσγράψας ἧς εἴργεσθαί φησιν, εἶτα τῶν ἱερῶν τῶν ἐν Ἀμφικτύοσιν· καὶ γὰρ τούτων, εἴπερ ἦν Ἕλλην ὁ παθών, μετῆν αὐτῷ. “καὶ ἄθλων.” διὰ τί; ὅτι κοινοὶ πᾶσίν εἰσιν οἱ κατὰ τὴν Ἑλλάδ’ ἀγῶνες, κατὰ δὲ τὴν πάντων μετουσίαν μετῆν καὶ τούτων τῷ πεπονθότι· καὶ τούτων οὖν ἀπεχέσθω.", "st": "23.40"}, {"sp": "N", "t": "τούτων μὲν δὴ τὸν εἰργασμένον εἴργει. ἂν δ’ ἔξω τούτων κτείνῃ τις αὐτὸν ἄλλοθι, τὴν αὐτὴν ὑπὲρ αὐτοῦ δίκην δέδωκεν ἥνπερ ἂν τὸν Ἀθηναῖον κτείνῃ. τὸν γὰρ φυγάδα τὸ τῆς πόλεως οὐ προσεῖπ’ ὄνομα, ἧς οὐκ ἔστι ματουσία αὐτῷ, ἀλλὰ τὸ τοῦ πράγματος, ᾧ κατέστησεν αὑτὸν ἐκεῖνος ἔνοχον· καὶ διὰ ταῦτ’ “ἄν τις ἀποκτείνῃ” φησὶ “τὸν ἀνδροφόνον.” εἶτ’ εἰπὼν ὧν εἰργόμενον, ἐπὶ τῷ τὴν τιμωρίαν νομίμως ἐπιθεῖναι τὸ τῆς πόλεως ὄνομ’ ὠνόμασεν, “τοῖς αὐτοῖς ἐνεχέσθω καθάπερ ἂν τὸν Ἀθηναῖον ἀποκτείνῃ” γράψας, ἀνομοίως, ὦ ἄνδρες Ἀθηναῖοι, τῷ τουτὶ τὸ ψήφισμ’ εἰρηκότι.", "st": "23.41"}, {"sp": "N", "t": "καίτοι πῶς οὐχὶ δεινὸν εἰ, οἷς ὁ νόμος δέδωκεν, ἐὰν ὧν εἶπον εἴργωνται, μετ’ ἀσφαλείας ζῆν φεύγουσιν, τούτους ἐκδότους τις εἶναι γράφει, καὶ ἀφαιρεῖται τὸ τῆς συγγνώμης ὠφέλιμον, ὃ τοῖς ἀτυχοῦσιν ὑπάρχειν εἰκὸς παρὰ τῶν ἔξω τῶν ἐγκλημάτων ὄντων, ὅτῳ ποτὲ τῶν πάντων ἀπόκειται ἄδηλον ὄν, μὴ προδήλου τῆς ἐπιούσης τύχης οὔσης ἑκάστῳ; καὶ νυνὶ τὸν ἀποκτείναντα Χαρίδημον, ὄντως ἂν ἄρα τοῦτο γένηται, ἂν ἀνταποκτείνωσί τινες λαβόντες ἔκδοτον, πεφευγότα καὶ τῶν νομίμων εἰργόμενον, ἔνοχοι μὲν αὐτοὶ ταῖς φονικαῖς δίκαις ἔσονται, ἔνοχος δὲ σύ·", "st": "23.42"}, {"sp": "N", "t": "καὶ γὰρ “ἄν τις αἴτιος ᾖ” γέγραπται, ἔσει δ’ αἴτιος τὴν διὰ τοῦ ψηφίσματος ἐξουσίαν δεδωκώς. οὐκοῦν εἰ μὲν ἐάσομεν ὑμᾶς τούτων συμβάντων, οὐ καθαροῖς οὖσιν ὁμοῦ διατρίψομεν· εἰ δ’ ἐπέξιμεν, οἷς ἐγνώκαμεν αὐτοὶ τἀναντία πράττειν ἀναγκασθησόμεθα. ἆρά γε μικρὸν ἢ τὸ τυχόν ἐστιν ὑπὲρ οὗ δεῖ λῦσαι τὸ ψήφισμ’ ὑμᾶς;", "st": "23.43"}, {"sp": "N", "t": "λέγε δὴ τὸν μετὰ ταῦτα νόμον.", "st": "23.44"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.44"}, {"sp": "N", "t": "ἐάν τίς τινα τῶν ἀνδροφόνων τῶν ἐξεληλυθότων, ὧν τὰ χρήματα ἐπίτιμα, πέρα ὅρου ἐλαύνῃ ἢ φέρῃ ἢ ἄγῃ, τὰ ἴσα ὀφείλειν ὅσα περ ἂν ἐν τῇ ἡμεδαπῇ δράσῃ.", "st": "23.44"}, {"sp": "N", "t": "ἄλλος οὗτος, ὦ ἄνδρες Ἀθηναῖοι, νόμος ἀνθρωπίνως καὶ καλῶς κείμενος, ὃν παραβὰς οὗτος ὁμοίως φανήσεται.", "st": "23.44"}, {"sp": "N", "t": "“ἐάν τίς τινα τῶν ἀνδροφόνων” φησὶ “τῶν ἐξεληλυθότων, ὧν τὰ χρήματα ἐπίτιμα.” τῶν ἐπ’ ἀκουσίῳ φόνῳ λέγει μεθεστηκότων. τῷ τοῦτο δῆλον; τῷ τ’ “ἐξεληλυθότων” εἰπεῖν, ἀλλὰ μὴ φευγόντων, καὶ τῷ διορίζειν “ὧν τὰ χρήματα ἐπίτιμα·” τῶν γὰρ ἐκ προνοίας δεδήμευται τὰ ὄντα.", "st": "23.45"}, {"sp": "N", "t": "περὶ μὲν δὴ τῶν ἀκουσίων ἂν λέγοι. λέγει δὲ τί; “ἐὰν πέρα ὅρου” φησὶν “ἐλαύνῃ ἢ φέρῃ ἢ ἄγῃ.” τοῦτο δ’ ἐστὶν τί, τὸ “πέρα ὅρου”; ἔστι πᾶσιν ὅρος τοῖς ἀνδροφόνοις τῆς τοῦ παθόντος εἴργεσθαι πατρίδος. ἐκ μὲν δὴ ταύτης δίδωσιν ἐλαύνειν καὶ ἄγειν, πέρα δ’ οὐκ ἐᾷ τούτων οὐδέτερον ποιεῖν. ἐὰν δέ τις παρὰ ταῦτα ποιῇ, τὴν αὐτὴν ἔδωκεν ὑπὲρ αὐτοῦ δίκην ἥνπερ ἂν εἰ μένοντ’ ἠδίκει [οἴκοι], γράψας ταὔτ’ ὀφείλειν ἅπερ ἂν οἴκοι δράσῃ.", "st": "23.46"}, {"sp": "N", "t": "εἰ δή τις ἔροιτ’ Ἀριστοκράτην τουτονί (καὶ μὴ νομίσητ’ εὔηθες τὸ ἐρώτημα) πρῶτον μὲν εἰ οἶδεν εἴ τις ἀποκτενεῖ Χαρίδημον, ἢ καὶ ἄλλως πως τελευτήσει, οὐκ ἄν, οἶμαι, φαίη. θήσομεν τοίνυν ἀποκτενεῖν. πάλιν οἶσθα, ἑκὼν ἢ ἄκων, καὶ ξένος ἢ πολίτης ὁ τοῦτο ποιήσων ἔσται;", "st": "23.47"}, {"sp": "N", "t": "οὐκ ἔνεστ’ εἰπεῖν ὡς οἶσθα. οὐκοῦν ταῦτά γε δήπου προσῆκε γράψαι “ἐάν τις ἀποκτείνῃ” γράφοντα, ἄκων ἢ ἑκών, ἀδίκως ἢ δικαίως, ξένος ἢ πολίτης, ἵν’ ὅτῳ ποτὲ τοὔργον ἐπράχθη, τούτῳ τὰ ἐκ τῶν νόμων ὑπῆρχε δίκαια, μὴ μὰ Δί’ αὐτὸ τὸ τῆς αἰτίας ὄνομ’ εἰπόντα “ἀγώγιμος ἔστω” προσγράψαι. τίνα γὰρ σὺ λέλοιπας ὅρον τῷ γράμματι τούτῳ, τοῦ νόμου σαφῶς οὑτωσὶ λέγοντος μὴ πέρα ὅρων ἐλαύνειν, ὃς πανταχόθεν δίδως ἄγειν;", "st": "23.48"}, {"sp": "N", "t": "ὁ νόμος δ’ οὐκ ἐλαύνειν τῶν ὅρων πέρα, ἀλλ’ οὐδ’ ἄγειν ἐᾷ. ἐκ δὲ τοῦ σοῦ ψηφίσματος ὁ βουλόμενος ἄξει τὸν ἄκοντ’ ἀπεκτονότα, ἔκδοτον λαβών, εἰς τὴν τοῦ παθόντος βίᾳ πατρίδα. ἆρ’ οὐ πάντα συγχεῖς τἀνθρώπινα, καὶ ἀφαιρεῖ τὴν πρόφασιν μεθ’ ἧς ἢ καλόν ἐστιν ἕκαστον τῶν ἔργων ἢ αἰσχρόν;", "st": "23.49"}, {"sp": "N", "t": "ὁρᾶτε γὰρ ὡς ἐπὶ πάντων, οὐκ ἐπὶ τῶν φονικῶν μόνον, οὕτω τοῦτ’ ἔχει. “ἄν τις τύπτῃ τινά” φησὶν “ἄρχων χειρῶν ἀδίκων,” ὡς, εἴ γ’ ἠμύνατο, οὐκ ἀδικεῖ. “ἄν τις κακῶς ἀγορεύῃ,” “τὰ ψευδῆ” προσέθηκεν, ὡς, εἴ γε τἀληθῆ, προσῆκον. “ἄν τις ἀποκτείνῃ,” “ἐκ προνοίας,” ὡς, εἴ γ’ ἄκων, οὐ ταὐτόν. “ἄν τις καταβλάψῃ τινά,” “ἑκὼν ἀδίκως.” πανταχοῦ τὴν πρόφασιν βεβαιοῦσαν τὸ πρᾶγμ’ εὑρήσομεν. ἀλλ’ οὐ σοί, ἀλλ’ ἁπλῶς, “ἄν τις ἀποκτείνῃ Χαρίδημον, ἀγέσθω,” κἂν ἄκων, κἂν δικαίως, κἂν ἀμυνόμενος, κἂν ἐφ’ οἷς διδόασιν οἱ νόμοι, κἂν ὁπωσοῦν.", "st": "23.50"}, {"sp": "N", "t": "λέγε τὸν μετὰ ταῦτα νόμον.", "st": "23.51"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.51"}, {"sp": "N", "t": "φόνου δὲ δίκας μὴ εἶναι μηδαμοῦ κατὰ τῶν τοὺς φεύγοντας ἐνδεικνύντων, ἐάν τις κατίῃ ὅποι μὴ ἔξεστιν.", "st": "23.51"}, {"sp": "N", "t": "ὁ μὲν νόμος ἐστὶν οὗτος Δράκοντος, ὦ ἄνδρες Ἀθηναῖοι, καὶ οἱ ἄλλοι δὲ ὅσους ἐκ τῶν φονικῶν νόμων παρεγραψάμην· δεῖ δ’ ἃ λέγει σκέψασθαι. “κατὰ τῶν ἐνδεικνύντων” φησὶ “τοὺς κατιόντας ἀνδροφόνους ὅποι μὴ ἔξεστι δίκας φόνου μὴ εἶναι.” ἐνταυθὶ δύο δηλοῖ δίκαια, ἃ παρ’ ἀμφότερ’ οὗτος εἴρηκεν τὸ ψήφισμα, ὅτι τ’ ἐνδεικνύναι δίδωσι τὸν ἀνδροφόνον καὶ οὐκ αὐτὸν ἀγώγιμον οἴχεσθαι λαβόντα, καὶ ὅτι, ἐὰν κατίῃ τις ὅποι μὴ ἔξεστι, καὶ αὐτὸ τοῦτο δίδωσιν, οὐχ ὅπου βούλεταί τις.", "st": "23.51"}, {"sp": "N", "t": "οὐκ ἔξεστι δὲ ποῖ; ἐξ ἧς ἂν φεύγῃ τις πόλεως. ποῦ καὶ σφόδρα τοῦτο δηλοῖ; “ἐάν τις κατίῃ” φησί. τοῦτο δ’ οὐκ ἔστ’ ἐπενεγκεῖν ἄλλῃ πόλει πλὴν ἣν ἂν φεύγῃ τις· ὅθεν γὰρ μηδ’ ἐξέπεσέν τις τὴν ἀρχήν, οὐκ ἔνι δήπου κατελθεῖν εἰς ταύτην. ὁ μὲν τοίνυν νόμος ἔνδειξιν δέδωκεν, καὶ ταύτην, “ἂν κατίῃ ὅποι μὴ ἔξεστιν·” ὁ δὲ “ἀγώγιμος ἔστω” γέγραφεν κἀντεῦθεν, ὅποι φεύγειν οὐδεὶς κωλύει νόμος.", "st": "23.52"}, {"sp": "N", "t": "λέγ’ ἄλλον νόμον.", "st": "23.53"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.53"}, {"sp": "N", "t": "ἐάν τις ἀποκτείνῃ ἐν ἄθλοις ἄκων, ἢ ἐν ὁδῷ καθελὼν ἢ ἐν πολέμῳ ἀγνοήσας, ἢ ἐπὶ δάμαρτι ἢ ἐπὶ μητρὶ ἢ ἐπ’ ἀδελφῇ ἢ ἐπὶ θυγατρί, ἢ ἐπὶ παλλακῇ ἣν ἂν ἐπ’ ἐλευθέροις παισὶν ἔχῃ, τούτων ἕνεκα μὴ φεύγειν κτείναντα.", "st": "23.53"}, {"sp": "N", "t": "πολλῶν, ὦ ἄνδρες Ἀθηναῖοι, νόμων ὄντων, παρ’ οὓς εἴρηται τὸ ψήφισμα, παρ’ οὐδένα μᾶλλον ἢ παρὰ τοῦτον τὸν ἀνεγνωσμένον νῦν εἴρηται. διδόντος γὰρ τοῦ νόμου σαφῶς οὑτωσὶ καὶ λέγοντος ἐφ’ οἷς ἐξεῖναι κτεῖναι, οὗτος ἅπαντα παρεῖδε ταῦτα, καὶ γέγραφεν, οὐδὲν ὑπειπὼν πῶς, ἄν τις ἀποκτείνῃ, τὴν τιμωρίαν.", "st": "23.53"}, {"sp": "N", "t": "καίτοι σκέψασθ’ ὡς ὁσίως καὶ καλῶς ἕκαστα διεῖλεν ὁ ταῦτ’ ἐξ ἀρχῆς διελών. ἄν τις ἐν ἄθλοις ἀποκτείνῃ τινά, τοῦτον ὥρισεν οὐκ ἀδικεῖν. διὰ τί; οὐ τὸ συμβὰν ἐσκέψατο, ἀλλὰ τὴν τοῦ δεδρακότος διάνοιαν. ἔστι δ’ αὕτη τίς; ζῶντα νικῆσαι καὶ οὐκ ἀποκτεῖναι. εἰ δ’ ἐκεῖνος ἀσθενέστερος ἦν τὸν ὑπὲρ τῆς νίκης ἐνεγκεῖν πόνον, ἑαυτῷ τοῦ πάθους αἴτιον ἡγήσατο, διὸ τιμωρίαν οὐκ ἔδωκεν ὑπὲρ αὐτοῦ.", "st": "23.54"}, {"sp": "N", "t": "πάλιν “ἂν ἐν πολέμῳ” φησὶν “ἀγνοήσας,” καὶ τοῦτον εἶναι καθαρόν. καλῶς· εἰ γὰρ ἐγώ τινα τῶν ἐναντίων οἰηθεὶς εἶναι διέφθειρα, οὐ δίκην ὑπέχειν, ἀλλὰ συγγνώμης τυχεῖν δίκαιός εἰμι. “ἢ ἐπὶ δάμαρτι” φησὶν “ἢ ἐπὶ μητρὶ ἢ ἐπ’ ἀδελφῇ ἢ θυγατρί, ἢ ἐπὶ παλλακῇ ἣν ἂν ἐπ’ ἐλευθέροις παισὶν ἔχῃ,” καὶ τὸν ἐπὶ τούτων τῳ κτείναντ’ ἀθῷον ποιεῖ, πάντων γ’ ὀρθότατ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον ἀφιείς. τί δήποτε;", "st": "23.55"}, {"sp": "N", "t": "ὅτι ὑπὲρ ὧν τοῖς πολεμίοις μαχόμεθα, ἵνα μὴ πάσχωσιν ὑβριστικὸν μηδ’ ἀσελγὲς μηδέν, ὑπὲρ τούτων καὶ τοὺς φιλίους, ἐὰν παρὰ τὸν νόμον εἰς αὐτοὺς ὑβρίζωσι καὶ διαφθείρωσιν, ἔδωκεν ἀποκτεῖναι. ἐπειδὴ γὰρ οὐ γένος ἐστὶν φιλίων καὶ πολεμίων, ἀλλὰ τὰ πραττόμεν’ ἐξεργάζεται τούτων ἑκάτερον, τοὺς ἐχθρὰ ποιοῦντας ἐν ἐχθροῦ μέρει κολάζειν ἀπέδωκεν ὁ νόμος. οὐκοῦν δεινόν, εἰ τοσούτων ὄντων ἐφ’ οἷς τοὺς ἄλλους ἔξεστιν ἀποκτιννύναι, μόνον ἀνθρώπων ἐκεῖνον μηδ’ ἐπὶ τούτοις ἐξέσται ἀποκτεῖναι.", "st": "23.56"}, {"sp": "N", "t": "φέρε, ἂν δέ τι συμβῇ τοιοῦτον οἷον ἴσως ἤδη τῳ καὶ ἄλλῳ, ἀπαλλαγῇ μὲν ἐκ Θρᾴκης, ἐλθὼν δ’ εἰς πόλιν οἰκῇ που, τῆς μὲν ἐξουσίας μηκέτι κύριος ὢν δι’ ἧς πολλὰ ποιεῖ τῶν ἀπειρημένων ὑπὸ τῶν νόμων, τοῖς δ’ ἔθεσιν καὶ ταῖς ἐπιθυμίαις ταῦτ’ ἐπιχειρῶν πράττειν, ἄλλο τι ἢ σιγῶντα δεήσει Χαρίδημον ἐᾶν αὑτὸν ὑβρίζειν; οὐ γὰρ ἀποκτεῖναί γ’ ἀσφαλὲς οὐδὲ τιμωρίαν λαβεῖν ἣν δίδωσ’ ὁ νόμος, διὰ τὸ ψήφισμα τουτί.", "st": "23.57"}, {"sp": "N", "t": "καὶ μὴν εἴ τις ἐκεῖν’ ὑπολαμβάνει, ποῦ δὲ γένοιτ’ ἂν ταῦτα; τί κωλύει κἀμὲ λέγειν, τίς δ’ ἂν ἀποκτείναι Χαρίδημον; ἀλλὰ μὴ τοῦτο σκοπῶμεν· ἀλλ’ ἐπειδήπερ ἐστὶ τὸ φεῦγον ψήφισμα οὐκ ἐπ’ ἤδη γεγενημένῳ τινὶ πράγματι, ἀλλ’ ἐπὶ τοιούτῳ ὃ μηδ’ εἰ γενήσεται μηδεὶς οἶδεν, τὸ μὲν τοῦ μέλλοντος ἔσεσθαι κοινὸν ἀμφοῖν ὑπαρχέτω, πρὸς δὲ τοῦθ’ ὑποθέντες ἀνθρωπίνως τὰς ἐλπίδας οὕτω σκοπῶμεν, ὡς τάχ’ ἄν, εἰ τύχοι, καὶ τούτων κἀκείνων συμβάντων.", "st": "23.58"}, {"sp": "N", "t": "λύσασι μὲν τοίνυν τὸ ψήφισμα, ἂν ἄρα συμβῇ τι παθεῖν ἐκείνῳ, εἰσὶν αἱ κατὰ τοὺς νόμους ὑπὲρ αὐτοῦ τιμωρίαι· ἐῶσι δέ, ἂν ἄρ’ ἐκεῖνος ζῶν ἀδικῇ τινα, ἀνῄρηται τοῖς ὑβριζομένοις ἡ μετὰ τῶν νόμων δίκη. ὥστε πανταχῇ καὶ ἐναντίον ἐστὶ τοῖς νόμοις τὸ ψήφισμα καὶ λῦσαι συμφέρει.", "st": "23.59"}, {"sp": "N", "t": "λέγε τὸν μετὰ ταῦτα νόμον.", "st": "23.60"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.60"}, {"sp": "N", "t": "καὶ ἐὰν φέροντα ἢ ἄγοντα βίᾳ ἀδίκως εὐθὺς ἀμυνόμενος κτείνῃ, νηποινεὶ τεθνάναι.", "st": "23.60"}, {"sp": "N", "t": "ἄλλα ταῦτ’ ἐφ’ οἷς ἔξεστι κτεῖναι. “ἐὰν ἄγοντα ἢ φέροντα βίᾳ ἀδίκως εὐθὺς ἀμυνόμενος κτείνῃ, νηποινεὶ τεθνάναι” κελεύει. θεάσασθε πρὸς Διὸς ὡς εὖ· τῷ μὲν ὑπειπών, ἐφ’ οἷς ἐξεῖναι κτείνειν, προσγράψαι τὸ “εὐθὺς” ἀφεῖλε τὸν τοῦ βουλεύσασθαί τι κακὸν χρόνον· τῷ δὲ “ἀμυνόμενος” γράψαι δηλοῖ τῷ πάσχοντι διδοὺς τὴν ἐξουσίαν, οὐκ ἄλλῳ τινί. ὁ μὲν δὴ νόμος εὐθὺς ἀμυνομένῳ δέδωκεν ἀποκτιννύναι, ὁ δ’ οὐδὲν εἴρηκεν, ἀλλ’ ἁπλῶς “ἐάν τις ἀποκτείνῃ,” κἂν ὡς οἱ νόμοι διδόασιν.", "st": "23.60"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία συκοφαντοῦμεν τὸ πρᾶγμα· τίνα γὰρ οἴσει ἢ ἄξει βίᾳ ἀδίκως Χαρίδημος; πάντας ἀνθρώπους. ἴστε γὰρ δήπου τοῦθ’ ὅτι πάντες οἱ στράτευμ’ ἔχοντες, ὧν ἂν οἴωνται κρείττους ἔσεσθαι, ἄγουσι καὶ φέρουσι χρήματ’ αἰτοῦντες. εἶτ’ οὐ δεινόν, ὦ γῆ καὶ θεοί, καὶ φανερῶς παράνομον, οὐ μόνον παρὰ τὸν γεγραμμένον νόμον, ἀλλὰ καὶ παρὰ τὸν κοινὸν ἁπάντων ἀνθρώπων, τὸν ἄγοντ’ ἢ φέροντα βίᾳ τἄμ’ ἐν πολεμίου μοίρᾳ μὴ ἐξεῖναί μοι ἀμύνεσθαι, εἴ γε μηδὲ τοῦτον τὸν τρόπον ἐξέσται Χαρίδημον ἀποκτεῖναι, ἀλλά, ἐὰν ἀδικῶν ἄγῃ καὶ φέρῃ βίᾳ τά τινος λῃζόμενος, ἀγώγιμος ὁ κτείνας ἔσται, τοῦ νόμου διδόντος, ἐὰν ἐπὶ τούτοις, ἀθῷον εἶναι;", "st": "23.61"}, {"sp": "N", "t": "λέγε τὸν μετὰ ταῦτα νόμον.", "st": "23.62"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.62"}, {"sp": "N", "t": "ὃς ἂν ἄρχων ἢ ἰδιώτης αἴτιος ᾖ τὸν θεσμὸν συγχυθῆναι τόνδε, ἢ μεταποιήσῃ αὐτόν, ἄτιμον εἶναι καὶ παῖδας [ἀτίμους] καὶ τὰ ἐκείνου.", "st": "23.62"}, {"sp": "N", "t": "ἠκούσατε μὲν τοῦ νόμου λέγοντος ἄντικρυς, ὦ ἄνδρες Ἀθηναῖοι, “ὃς ἂν ἄρχων ἢ ἰδιώτης αἴτιος ᾖ τὸν θεσμὸν συγχυθῆναι τόνδε, ἢ μεταποιήσῃ αὐτόν, ἄτιμος ἔστω καὶ οἱ παῖδες καὶ τὰ ἐκείνου.” ἆρ’ οὖν μικρὰν ἢ φαύλην πρόνοιαν ἔχειν ὑμῖν ὁ θεὶς τὸν νόμον δοκεῖ, ὅπως κύριος ἔσται καὶ μήτε συγχυθήσεται μήτ’ αὖ μεταποιηθήσεται; ἀλλ’ Ἀριστοκράτης οὑτοσὶ μικρὰ φροντίσας αὐτοῦ μεταποιεῖ καὶ συγχεῖ. τί γὰρ ἄλλ’ ἐστὶν τὸ μεταποιεῖν ἢ ὅταν ἔξω τῶν τεταγμένων δικαστηρίων καὶ ὅρων, [ὧν εἴργεσθαι δεῖ,] διδῷ τις τὰς τιμωρίας, καὶ τὸ λόγου τυχεῖν ἀναιρῶν ἐκδότους ποιῇ; τί δ’ ἄλλο τὸ συγχεῖν ἢ ὅταν ἑξῆς οὑτωσὶ πάντα τἀναντία τῶν ἐν τοῖς νόμοις τις γεγραμμένων γράφῃ;", "st": "23.62"}, {"sp": "N", "t": "οὐ τοίνυν τούτους μόνον τοὺς νόμους, ὦ ἄνδρες Ἀθηναῖοι, παραβέβηκεν, ἀλλὰ καὶ ἄλλους πολλοὺς οὓς οὐ παραγεγράμμεθα διὰ τὸ πλῆθος. ἀλλ’ ἐν κεφαλαίῳ λέγω· ὁπόσοι νόμοι περὶ τῶν φονικῶν δικαστηρίων εἰσίν, καλεῖσθαι λέγοντες ἢ μαρτυρεῖν ἢ διόμνυσθαι τοὺς ἀγωνιζομένους ἢ ἄλλ’ ὁτιοῦν προστάττοντες, πάντας ὑπερβέβηκε τούτους καὶ πᾶσιν ἐναντίον εἴρηκεν τὸ ψήφισμα τουτί. οὗ γὰρ οὐ κλῆσις, οὐ κρίσις, οὐ μαρτυρία συνειδότος, οὐ διωμοσία, ἀλλ’ ἀπ’ αἰτίας εὐθὺς ἡ τιμωρία γέγραπται, καὶ αὕτη ἣν ἀπαγορεύουσιν οἱ νόμοι, τί ἂν ἄλλο τις εἴποι; καίτοι ταῦτα πάντ’ ἐπὶ πέντε δικαστηρίοις γίγνεται προστεταγμένα τοῖς νόμοις.", "st": "23.63"}, {"sp": "N", "t": "νὴ Δία, ἴσως εἴποι τις ἄν, ἀλλὰ ταῦτα μὲν οὐδενός ἐστ’ ἄξι’ οὐδὲ δικαίως εὑρημένα, ἃ δ’ ἔγραψεν οὗτος, δίκαια καὶ καλά. ἀλλὰ τοὐναντίον τούτου μὲν τοῦ ψηφίσματος οὐκ οἶδ’ εἴ τι δεινότερον γέγονεν πώποτ’ ἐν ὑμῖν, τούτων δὲ τῶν πάντων ὁπόσ’ ἐστὶ δικαστήρι’ ἐν ἀνθρώποις οὐδὲν οὔτε σεμνότερον οὔτε δικαιότερον φανήσεται. βούλομαι δ’ εἰπεῖν διὰ βραχέων ἃ καὶ ζῆλόν τινα καὶ τιμὴν φέρει τῇ πόλει ῥηθέντα καὶ ἡδίους ἔσεσθ’ ἀκούσαντες. ἄρξομαι δ’ ἐντεῦθεν ὅθεν μάλιστα μαθήσεσθε, ἐπὶ τὴν δωρειὰν ἐπανελθὼν ἣ τῷ Χαριδήμῳ δέδοται.", "st": "23.64"}, {"sp": "N", "t": "ἡμεῖς, ὦ ἄνδρες Ἀθηναῖοι, Χαρίδημον ἐποιησάμεθα πολίτην, καὶ διὰ τῆς δωρειᾶς ταύτης μετεδώκαμεν αὐτῷ καὶ ἱερῶν καὶ ὁσίων καὶ νομίμων καὶ πάντων ὅσων περ αὐτοῖς μέτεστιν ἡμῖν. πολλὰ μὲν δὴ παρ’ ἡμῖν ἐστι τοιαῦθ’ οἷ’ οὐχ ἑτέρωθι, ἓν δ’ οὖν ἰδιώτατον πάντων καὶ σεμνότατον, τὸ ἐν Ἀρείῳ πάγῳ δικαστήριον, ὑπὲρ οὗ τοσαῦτ’ ἔστιν εἰπεῖν καλὰ παραδεδομένα καὶ μυθώδη καὶ ὧν αὐτοὶ μάρτυρές ἐσμεν, ὅσα περὶ οὐδενὸς ἄλλου δικαστηρίου· ὧν ὡσπερεὶ δείγματος εἵνεκ’ ἄξιόν ἐστιν ἓν ἢ δύ’ ἀκοῦσαι.", "st": "23.65"}, {"sp": "N", "t": "τοῦτο μὲν τοίνυν τὰ παλαιά, ὡς ἡμῖν ἀκούειν παραδέδοται, ἐν μόνῳ τούτῳ τῷ δικαστηρίῳ δίκας φόνου θεοὶ καὶ δοῦναι καὶ λαβεῖν ἠξίωσαν καὶ δικασταὶ γενέσθαι διενεχθεῖσιν ἀλλήλοις, ὡς λόγος· λαβεῖν μὲν Ποσειδῶν ὑπὲρ Ἁλιρροθίου τοῦ υἱοῦ παρ’ Ἄρεως, δικάσαι δ’ Εὐμενίσιν καὶ Ὀρέστῃ οἱ δώδεκα θεοί. καὶ τὰ μὲν δὴ παλαιὰ ταῦτα· τὰ δ’ ὕστερον, τοῦτο μόνον τὸ δικαστήριον οὐχὶ τύραννος, οὐκ ὀλιγαρχία, οὐ δημοκρατία τὰς φονικὰς δίκας ἀφελέσθαι τετόλμηκεν, ἀλλὰ πάντες ἀσθενέστερον ἂν τὸ δίκαιον εὑρεῖν ἡγοῦνται περὶ τούτων αὐτοὶ τοῦ παρὰ τούτοις εὑρημένου δικαίου. πρὸς δὲ τούτοις τοιούτοις οὖσιν, ἐνταυθοῖ μόνον οὐδεὶς πώποτ’ οὔτε φεύγων ἁλοὺς οὔτε διώκων ἡττηθεὶς ἐξήλεγξεν ὡς ἀδίκως ἐδικάσθη τὰ κριθέντα.", "st": "23.66"}, {"sp": "N", "t": "ταύτην τοίνυν τὴν φυλακὴν καὶ τὰς ἐν ταύτῃ νομίμους τιμωρίας παραβὰς ὁ γράφων τὸ ψήφισμα τοδὶ ζῶντι μὲν ἐξουσίαν γέγραφεν τῷ Χαριδήμῳ ποιεῖν ὅ τι ἂν βούληται, παθόντος δέ τι τοῖς οἰκείοις συκοφαντίαν δέδωκεν. σκέψασθε γὰρ οὑτωσί. ἴστε δήπου τοῦθ’ ἅπαντες, ὅτι ἐν Ἀρείῳ πάγῳ, οὗ δίδωσ’ ὁ νόμος καὶ κελεύει τοῦ φόνου δικάζεσθαι, πρῶτον μὲν διομεῖται κατ’ ἐξωλείας αὑτοῦ καὶ γένους καὶ οἰκίας ὅ τιν’ αἰτιώμενος εἰργάσθαι τι τοιοῦτον,", "st": "23.67"}, {"sp": "N", "t": "εἶτ’ οὐδὲ τὸν τυχόντα τιν’ ὅρκον [τοῦτο ποιήσει] ἀλλ’ ὃν οὐδεὶς ὄμνυσ’ ὑπὲρ οὐδενὸς ἄλλου, στὰς ἐπὶ τῶν τομίων κάπρου καὶ κριοῦ καὶ ταύρου, καὶ τούτων ἐσφαγμένων ὑφ’ ὧν δεῖ καὶ ἐν αἷς ἡμέραις καθήκει, ὥστε καὶ ἐκ τοῦ χρόνου καὶ ἐκ τῶν μεταχειριζομένων ἅπαν, ὅσον ἔσθ’ ὅσιον, πεπρᾶχθαι. καὶ μετὰ ταῦθ’ ὁ τὸν τοιοῦτον ὅρκον ὀμωμοκὼς οὔπω πεπίστευται, ἀλλ’ ἐὰν ἐξελεγχθῇ μὴ λέγων ἀληθῆ, τὴν ἐπιορκίαν ἀπενεγκάμενος τοῖς αὑτοῦ παισὶν καὶ τῷ γένει πλέον οὐδ’ ὁτιοῦν ἕξει.", "st": "23.68"}, {"sp": "N", "t": "ἂν δὲ δόξῃ τὰ δίκαι’ ἐγκαλεῖν καὶ ἕλῃ τὸν δεδρακότα τοῦ φόνου, οὐδ’ οὕτω κύριος γίγνεται τοῦ ἁλόντος, ἀλλ’ ἐκείνου μὲν οἱ νόμοι κύριοι κολάσαι καὶ οἷς προστέτακται, τῷ δ’ ἐπιδεῖν διδόντα δίκην ἔξεστιν, ἣν ἔταξ’ ὁ νόμος, τὸν ἁλόντα, πέρα δ’ οὐδὲν τούτου. καὶ τῷ μὲν διώκοντι ὑπάρχει ταῦτα, τῷ δὲ φεύγοντι τὰ μὲν τῆς διωμοσίας ταὐτά, τὸν πρότερον δ’ ἔξεστιν εἰπόντα λόγον μεταστῆναι, καὶ οὔθ’ ὁ διώκων οὔθ’ οἱ δικάζοντες οὔτ’ ἄλλος ἀνθρώπων οὐδεὶς κύριος κωλῦσαι.", "st": "23.69"}, {"sp": "N", "t": "τί δήποτ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’ οὕτως ἔχει; ὅτι οἱ ταῦτ’ ἐξ ἀρχῆς τὰ νόμιμα διαθέντες, οἵτινές ποτ’ ἦσαν, εἴθ’ ἥρωες εἴτε θεοί, οὐκ ἐπέθεντο τοῖς ἀτυχήμασιν, ἀλλ’ ἀνθρωπίνως ἐπεκούφισαν, εἰς ὅσον εἶχε καλῶς, τὰς συμφοράς. ταῦτα μέντοι πάνθ’ οὕτω καλῶς καὶ νομίμως ἔχονθ’ ὁ γράφων τὸ ψήφισμα τουτὶ παραβεβηκὼς φαίνεται· ἓν γὰρ οὐδ’ ὁτιοῦν ἔνι τούτων ἐν τῷ ψηφίσματι τῷ τούτου. καὶ πρῶτον μὲν παρ’ ἑνὸς τούτου δικαστηρίου καὶ [παρὰ] τοὺς γεγραμμένους νόμους καὶ τἄγραφα νόμιμα τὸ ψήφισμ’ εἴρηται.", "st": "23.70"}, {"sp": "N", "t": "δεύτερον δ’ ἕτερον δικαστήριον τὸ τῶν ἀκουσίων φόνων φανήσεται συγχέων, τοὐπὶ Παλλαδίῳ, καὶ τοὺς παρὰ τούτῳ νόμους παραβαίνων. καὶ γὰρ ἐνταῦθ’ ὑπόκειται πρῶτον μὲν διωμοσία, δεύτερον δὲ λόγος, τρίτον δὲ γνῶσις τοῦ δικαστηρίου, ὧν οὐδέν ἐστιν ἐν τῷ τούτου ψηφίσματι. ἂν δ’ ἁλῷ καὶ δοκῇ τοὔργον εἰργάσθαι, οὔθ’ ὁ διώκων τοῦ δεδρακότος κύριος οὔτ’ ἄλλος οὐδεὶς πλὴν ὁ νόμος.", "st": "23.71"}, {"sp": "N", "t": "τί οὖν ὁ νόμος κελεύει; τὸν ἁλόντ’ ἐπ’ ἀκουσίῳ φόνῳ ἔν τισιν εἰρημένοις χρόνοις ἀπελθεῖν τακτὴν ὁδόν, καὶ φεύγειν ἕως ἂν αἰδέσηταί τινα τῶν ἐν γένει τοῦ πεπονθότος. τηνικαῦτα δ’ ἥκειν δέδωκεν ἔστιν ὃν τρόπον, οὐχ ὃν ἂν τύχῃ, ἀλλὰ καὶ θῦσαι καὶ καθαρθῆναι καὶ ἄλλ’ ἄττα διείρηκεν ἃ χρὴ ποιῆσαι, ὀρθῶς, ὦ ἄνδρες Ἀθηναῖοι, πάντα ταῦτα λέγων ὁ νόμος.", "st": "23.72"}, {"sp": "N", "t": "καὶ γὰρ τὸ τῶν ἀκουσίων ἐλάττω τὴν τιμωρίαν ἢ τῶν ἑκουσίων τάξαι δίκαιον, καὶ τὸ παρασχόντ’ ἀσφάλειαν ἀπελθεῖν οὕτω προστάττειν φεύγειν ὀρθῶς ἐστιν ἔχον, καὶ τὸ τὸν κατιόνθ’ ὁσιοῦν καὶ καθαίρεσθαι νομίμοις τισί, καὶ τὸ τοὺς νόμους κυρίους ἁπάντων εἶναι, καὶ πάντα ταῦτ’ ἔχει καλῶς. ταῦτα τοίνυν ἅπαντα δικαίως οὕτω διορισθένθ’ ὑπὸ τῶν ἐξ ἀρχῆς νομοθετησάντων παρέβη γράφων τὸ ψήφισμ’ οὑτοσί. ταῦτα μὲν δὴ δύο τηλικαῦτα καὶ τοιαῦτα δικαστήρια καὶ νόμιμ’ ἐκ παντὸς τοῦ χρόνου παραδεδομένα οὕτως ἀναιδῶς ὑπερπεπήδηκεν.", "st": "23.73"}, {"sp": "N", "t": "τρίτον δ’ ἕτερον πρὸς τούτοις δικαστήριον, ὃ πάντων ἁγιώτατα τούτων ἔχει καὶ φρικωδέστατα, ἄν τις ὁμολογῇ μὲν κτεῖναι, ἐννόμως δὲ φῇ δεδρακέναι. τοῦτο δ’ ἐστὶ τοὐπὶ Δελφινίῳ. δοκοῦσι γάρ μοι, ὦ ἄνδρες δικασταί, ζητῆσαι τοῦτο πρῶτον ἁπάντων οἱ περὶ τούτων ἐν ἀρχῇ τὰ δίκαι’ ὁρίσαντες, πότερ’ οὐδένα χρὴ φόνον ὅσιον εἶναι νομίζειν ἢ τινά γ’ ἔσθ’ ὅσιον νομιστέον, λογιζόμενοι δ’ ὅτι μητέρ’ Ὀρέστης ἀπεκτονὼς ὁμολογῶν θεῶν δικαστῶν τυχὼν ἀποφυγγάνει, νομίσαι δίκαιόν τιν’ εἶναι φόνον· οὐ γὰρ ἂν τά γε μὴ δίκαια θεοὺς ψηφίσασθαι. ὡς δὲ τοῦτ’ ἐνόμισαν, γράφουσιν ἤδη καὶ διορίζουσι σαφῶς ἐφ’ οἷς ἐξεῖναι ἀποκτιννύναι.", "st": "23.74"}, {"sp": "N", "t": "ἀλλ’ οὐχ οὗτος οὐδὲν ἀφεῖλεν, ἀλλ’ ἁπλῶς, ἐάν τις ἀποκτείνῃ Χαρίδημον, κἂν δικαίως, κἂν ὡς οἱ νόμοι διδόασιν, ἔκδοτον ποιεῖ. καίτοι πᾶσίν εἰσι πράγμασι καὶ λόγοις δύο προσθῆκαι, ἡ τοῦ δικαίου καὶ ἀδίκου· ἃς ἅμα μὲν ταὐτὸ πρᾶγμ’ οὐδὲν ἂν δύναιτο σχεῖν οὐδὲ λόγος οὐδείς (πῶς γὰρ ἂν δίκαι’ ἅμα ταὐτὰ καὶ μὴ γένοιτο;) τὴν ἑτέραν δ’ ἕκαστον ἔχον δοκιμάζεται, κἂν μὲν τὴν ἄδικον φανῇ, πονηρὸν κρίνεται, ἂν δὲ τὴν δικαίαν, χρηστὸν καὶ καλόν. σὺ τοίνυν οὐδετέραν προσέθηκας τούτων, “ἄν τις ἀποκτείνῃ” γράφων· ἀλλ’ ἀόριστον εἰπὼν αὐτὴν τὴν αἰτίαν, καὶ μετὰ ταῦτ’ εὐθὺς προσγράψας ἀγώγιμον εἶναι, τρίτον τουτὶ δικαστήριον καὶ τὰ τούτου νόμιμα παραβεβηκὼς φαίνει.", "st": "23.75"}, {"sp": "N", "t": "τέταρτον τοίνυν ἄλλο πρὸς τούτοις τοὐπὶ Πρυτανείῳ. τοῦτο δ’ ἐστὶ τί; ἐὰν λίθος ἢ ξύλον ἢ σίδηρος ἤ τι τοιοῦτον ἐμπεσὸν πατάξῃ, καὶ τὸν μὲν βαλόντ’ ἀγνοῇ τις, αὐτὸ δ’ εἰδῇ καὶ ἔχῃ τὸ τὸν φόνον εἰργασμένον, τούτοις ἐνταῦθα λαγχάνεται. εἰ τοίνυν τῶν ἀψύχων καὶ μὴ μετεχόντων τοῦ φρονεῖν οὐδέν ἐσθ’ ὅσιον, τοιαύτην ἔχον αἰτίαν, ἐᾶν ἄκριτον, ἦ που τόν γ’ ἀδικοῦντα μὲν οὐδέν, ἐὰν τύχῃ, θήσω δ’ ἀδικοῦντα, ἀλλ’ ἄνθρωπόν γ’ ὄντα καὶ μετειληφότα [τῇ τύχῃ] τῆς αὐτῆς ἡμῖν φύσεως, ἀνόσιον καὶ δεινὸν ἄνευ λόγου καὶ ψήφου ποιεῖν ἔκδοτον ἐπ’ αἰτίᾳ τοιαύτῃ.", "st": "23.76"}, {"sp": "N", "t": "ἔτι τοίνυν πέμπτον δικαστήριον ἄλλο θεάσασθ’ οἷον ὑπερβέβηκε, τὸ ἐν Φρεαττοῖ. ἐνταῦθα γάρ, ὦ ἄνδρες Ἀθηναῖοι, κελεύει δίκας ὑπέχειν ὁ νόμος, “ἐάν τις ἐπ’ ἀκουσίῳ φόνῳ πεφευγώς, μήπω τῶν ἐκβαλλόντων αὐτὸν ᾐδεσμένων, αἰτίαν ἔχῃ ἑτέρου φόνου ἑκουσίου.” καὶ οὐχ, ὅτι δεῦρ’ οὐχ οἷόν τ’ ἐλθεῖν αὐτῷ, παρεῖδεν αὐτὸν ὁ ταῦθ’ ἕκαστα τάξας, οὐδ’, ὅτι καὶ πρότερόν τι τοιοῦτον ἐποίησε, καὶ δὴ τὴν ὁμοίαν ἐποιήσατο πιστὴν αἰτίαν κατ’ αὐτοῦ,", "st": "23.77"}, {"sp": "N", "t": "ἀλλὰ τό τ’ εὐσεβὲς εὗρεν ὅπως ἔσται, κἀκεῖνον οὐκ ἀπεστέρησε λόγου καὶ κρίσεως. τί οὖν ἐποίησεν; ἤγαγε τοὺς δικάσοντας οἷ προσελθεῖν οἷόν τ’ ἐκείνῳ, τῆς χώρας ἀποδείξας τόπον τιν’ ἐν Φρεαττοῖ καλούμενον ἐπὶ θαλάττῃ. εἶθ’ ὁ μὲν ἐν πλοίῳ προσπλεύσας λέγει τῆς γῆς οὐχ ἁπτόμενος, οἱ δ’ ἀκροῶνται καὶ δικάζουσιν ἐν τῇ γῇ· κἂν μὲν ἁλῷ, τὴν ἐπὶ τοῖς ἑκουσίοις φόνοις δίκην ἔδωκε δικαίως, ἂν δ’ ἀποφύγῃ, ταύτης μὲν ἀθῷος ἀφίεται, τὴν δ’ ἐπὶ τῷ πρότερον φόνῳ φυγὴν ὑπέχει.", "st": "23.78"}, {"sp": "N", "t": "τίνος οὖν ποθ’ εἵνεκα ταῦθ’ οὕτω διεσπούδασται; ἴσον ἡγεῖτ’ ἀσέβημ’ ὁ ταῦτα διαιρῶν τόν τ’ ἀδικοῦντ’ ἐᾶν καὶ τὸν ἀναίτιον ἐκδιδόναι πρὸ δίκης. καίτοι εἰ περὶ τῶν ἀνδροφόνων τῶν ἤδη κεκριμένων τοσαύτη σπουδή, ὅπως λόγου καὶ κρίσεως καὶ πάντων ὁπόσ’ ἐστὶ δίκαια τεύξονται περὶ τῶν ὕστερον αἰτιῶν, ἦ που περί γε τοῦ μήθ’ ἑαλωκότος μήτ’ ἐγνωσμένου πότερον δέδρακεν ἢ οὒ καὶ πότερ’ ἄκων ἢ ἑκών, πάνδεινον γράφειν ὡς ἐκδοτέον τοῖς ἐγκαλοῦσιν.", "st": "23.79"}, {"sp": "N", "t": "ἔτι τοίνυν ἔσθ’ ἕκτη τιμωρία πρὸς ἁπάσαις ταύταις, ἣν ὁμοίως παραβὰς γέγραφεν τὸ ψήφισμ’ οὑτοσί. εἰ πάντα ταῦτά τις ἠγνόηκεν, ἢ καὶ παρεληλύθασιν οἱ χρόνοι ἐν οἷς ἔδει τούτων ἕκαστα ποιεῖν, ἢ δι’ ἄλλο τι οὐχὶ βούλεται τούτους τοὺς τρόπους ἐπεξιέναι, τὸν ἀνδροφόνον δ’ ὁρᾷ περιιόντ’ ἐν τοῖς ἱεροῖς καὶ κατὰ τὴν ἀγοράν, ἀπάγειν ἔξεστιν εἰς τὸ δεσμωτήριον, οὐκ οἴκαδ’ οὐδ’ ὅποι βούλεται, ὥσπερ σὺ δέδωκας. κἀνταῦθ’ ἀπαχθεὶς οὐδ’ ὁτιοῦν, πρὶν ἂν κριθῇ, πείσεται, ἀλλ’ ἐὰν μὲν ἁλῷ, θανάτῳ ζημιωθήσεται, ἐὰν δὲ μὴ μεταλάβῃ τὸ πέμπτον μέρος τῶν ψήφων ὁ ἀπαγαγών, χιλίας προσοφλήσει.", "st": "23.80"}, {"sp": "N", "t": "ἀλλ’ οὐχ οὗτος ἔγραψε ταῦτα, ἀλλὰ τὸν μὲν ἀθῷον αἰτιᾶσθαι, τὸν δ’ ἄκριτον παραχρῆμ’ ἐκδίδοσθαι. ἂν δέ τις ἀνθρώπων ἢ καὶ ὅλη πόλις τοσούτοις νομίμοις ἀναιρουμένοις ὅσοις ἐγὼ διεξελήλυθα, καὶ τοσούτοις δικαστηρίοις καταλυομένοις ὅσοις εἴρηκα, ἃ θεοὶ κατέδειξαν καὶ μετὰ ταῦτ’ ἄνθρωποι χρῶνται πάντα τὸν χρόνον, βοηθήσῃ καὶ τὸν ὑβριζόμενον καὶ παρανομούμενον ἀφέληται, ἔκσπονδον ἔγραψεν εἶναι, καὶ οὐδὲ τούτῳ λόγον οὐδὲ κρίσιν πεποίηκεν, ἀλλὰ καὶ τοῦτον εὐθὺς ἄνευ κρίσεως κολάζει. πῶς ἂν ἢ δεινότερον γένοιτ’ ἢ παρανομώτερον τούτου ψήφισμα;", "st": "23.81"}, {"sp": "N", "t": "ἆρά τις ἡμῖν ἔτι λοιπός ἐστι νόμος; δεῖξον. οὑτοσί. λέγε τοῦτον.", "st": "23.82"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.82"}, {"sp": "N", "t": "ἐάν τις βιαίῳ θανάτῳ ἀποθάνῃ, ὑπὲρ τούτου τοῖς προσήκουσιν εἶναι τὰς ἀνδροληψίας, ἕως ἂν ἢ δίκας τοῦ φόνου ὑπόσχωσιν ἢ τοὺς ἀποκτείναντας ἐκδῶσι. τὴν δὲ ἀνδροληψίαν εἶναι μέχρι τριῶν, πλέον δὲ μή.", "st": "23.82"}, {"sp": "N", "t": "πολλῶν, ὦ ἄνδρες Ἀθηναῖοι, καλῶς ἐχόντων νόμων οὐκ οἶδ’ εἴ τινος ἧττον οὗτος ἔχει καλῶς καὶ δικαίως ὁ νόμος. σκέψασθε γὰρ ὡς νομίμως καὶ σφόδρ’ ἀνθρωπίνως κεῖται.", "st": "23.82"}, {"sp": "N", "t": "“ἐάν τις βιαίῳ θανάτῳ ἀποθάνῃ,” φησίν. πρῶτον μὲν δὴ τοῦτο προσγράψας τὸ “βιαίως,” σύμβολον πεποίηκεν ᾧ γιγνώσκομεν ὅτι, ἂν ἀδίκως, λέγει. “ὑπὲρ τούτου” φησὶ “τοῖς προσήκουσιν εἶναι τὰς ἀνδροληψίας, ἕως ἂν ἢ δίκας τοῦ φόνου ὑπόσχωσιν ἢ τοὺς ἀποκτείναντας ἐκδῶσιν.” σκοπεῖσθ’ ὡς καλῶς. πρότερον μὲν ὑποσχεῖν δίκας ἀξιοῖ, μετὰ ταῦτα δέ, ἂν τοῦτο μὴ βούλωνται, προσέταξεν ἐκδοῦναι· ἐὰν δὲ μηδέτερον τούτων ἐθέλωσι, “τὸ ἀνδρολήψιόν” φησιν “εἶναι μέχρι τριῶν, πλέον δὲ μή.” παρὰ τοίνυν ὅλον τοῦτον τὸν νόμον εἴρηται τὸ ψήφισμα.", "st": "23.83"}, {"sp": "N", "t": "πρῶτον μὲν γάρ, “ἐάν τις ἀποκτείνῃ” γράφων, οὐ προσέγραψ’ ἀδίκως οὐδὲ βιαίως οὐδ’ ὅλως οὐδέν. εἶτα πρὸ τοῦ δίκην ἀξιῶσαι λαβεῖν, εὐθὺς ἔγραψεν ἀγώγιμον εἶναι. πρὸς δὲ τούτοις ὁ μὲν νόμος, ἐὰν μήτε δίκας ὑπόσχωσι παρ’ οἷς ἂν τὸ πάθος γένηται, μήτε τοὺς δεδρακότας ἐκδῶσι, κελεύει κατὰ τούτων εἶναι μέχρι τριῶν τὸ ἀνδρολήψιον·", "st": "23.84"}, {"sp": "N", "t": "ὁ δὲ τούτους μὲν ἀθῴους παρῆκε, καὶ οὐδὲ λόγον πεποίηται περὶ αὐτῶν οὐδένα, τοὺς δὲ τὸν ἤδη πεφευγότα (θήσω γὰρ οὕτω) κατὰ τὸν κοινὸν ἁπάντων ἀνθρώπων νόμον, ὃς κεῖται τὸν φεύγοντα δέχεσθαι, ὑποδεξαμένους ἐκσπόνδους εἶναι γράφει, ἐὰν μὴ τὸν ἱκέτην ἔκδοτον διδῶσιν. οὐκοῦν καὶ τῷ μὴ προσθεῖναι πῶς, ἐὰν ἀποκτείνῃ, καὶ τῷ μηδεμίαν κρίσιν εἰπεῖν, καὶ τῷ μὴ δίκας αἰτεῖν, καὶ τῷ πανταχόθεν διδόναι λαβεῖν, καὶ τῷ τοὺς ὑποδεξαμένους, ἀλλὰ μὴ παρ’ οἷς ἂν τὸ πάθος γένηται κολάζειν, καὶ πᾶσιν οὑτωσὶ φανερῶς καὶ παρὰ τοῦτον εἴρηκε τὸν νόμον.", "st": "23.85"}, {"sp": "N", "t": "λέγε δὴ τὸν ἐφεξῆς.", "st": "23.86"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.86"}, {"sp": "N", "t": "μηδὲ νόμον ἐπ’ ἀνδρὶ ἐξεῖναι θεῖναι, ἐὰν μὴ τὸν αὐτὸν ἐπὶ πᾶσιν Ἀθηναίοις.", "st": "23.86"}, {"sp": "N", "t": "ἔστι μὲν οὐκέτι τῶν φονικῶν ὅδ’ ὁ νῦν ἀνεγνωσμένος νόμος, ὦ ἄνδρες δικασταί, οὐδ’ ὁτιοῦν δ’ ἧττον ἔχει καλῶς, εἴπερ καὶ ἄλλος τις. ὥσπερ γὰρ τῆς ἄλλης πολιτείας ἴσον μέτεστιν ἑκάστῳ, οὕτως ᾤετο δεῖν καὶ τῶν νόμων ἴσον μετέχειν πάντας ὁ θεὶς αὐτόν, καὶ διὰ ταῦτ’ ἔγραψεν “μηδὲ νόμον ἐπ’ ἀνδρὶ ἐξεῖναι θεῖναι, ἐὰν μὴ τὸν αὐτὸν ἐφ’ ἅπασιν Ἀθηναίοις.” ὁπότε τοίνυν τὰ ψηφίσματα δεῖν κατὰ τοὺς νόμους ὁμολογεῖται γράφειν, ὁ γράφων ἰδίᾳ τι Χαριδήμῳ τοιοῦτον ὃ μὴ πᾶσι καὶ ὑμῖν ἔσται, σαφῶς καὶ παρὰ τοῦτον ἂν εἰρηκὼς εἴη τὸν νόμον. οὐ γὰρ δήπου, ἃ μηδὲ νομοθετεῖν ἔξεστιν, ταῦτ’ ἐν ψηφίσματι γράψας τις ἔννομ’ ἂν εἰρηκὼς εἴη.", "st": "23.86"}, {"sp": "N", "t": "λέγε τὸν μετὰ ταῦτα νόμον. ἢ οὗτοι πάντες εἰσίν;", "st": "23.87"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "23.87"}, {"sp": "N", "t": "ψήφισμα δὲ μηδὲν μήτε βουλῆς μήτε δήμου νόμου κυριώτερον εἶναι.", "st": "23.87"}, {"sp": "N", "t": "κατάθου. πάνυ μικρὸν ὑπείληφά μοι τὸν λόγον, ὦ ἄνδρες δικασταί, καὶ ῥᾴδιον εἶναι περὶ τοῦ παρὰ τοῦτον εἰρῆσθαι τὸν νόμον τὸ ψήφισμα. ὃς γὰρ ὑπαρχόντων τοσούτων νόμων πάντας ὑπερβὰς τούτους γέγραφεν καὶ κατέκλεισ’ ἴδιον πρᾶγμα ψηφίσματι, τοῦτον τί τις ἄλλο ποιεῖν φήσει πλὴν ψήφισμα νόμου κυριώτερον ἀξιοῦν εἶναι;", "st": "23.87"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν καὶ ἓν ἢ δύο ψηφίσματα δεῖξαι τῶν γεγραμμένων τοῖς ὡς ἀληθῶς εὐεργέταις τῆς πόλεως, ἵν’ εἰδῆθ’ ὅτι ῥᾴδιόν ἐστι γράφειν τὰ δίκαια, ὅταν αὐτοῦ τις εἵνεκα τούτου γράφῃ, τοῦ τιμῆσαί τινα καὶ μεταδοῦναι τῶν ἡμῖν ὑπαρχόντων, καὶ μὴ διὰ τοῦ ταῦτα δοκεῖν ποιεῖν βούληται κακουργεῖν καὶ παρακρούεσθαι. λέγε τὰ ψηφίσματα ταυτί. ἀλλ’ ἵνα μὴ μακρὸν ὑμῖν ἀκούειν ᾖ, ἐξ ἑκάστου τῶν ψηφισμάτων αὐτὸ τοῦτ’ ἐξείλεκται περὶ οὗ τούτου κατηγορῶ. λέγε.", "st": "23.88"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑΤΑ.", "st": "23.88"}, {"sp": "N", "t": "ὁρᾶθ’ ὅτι πάντες, ὦ ἄνδρες Ἀθηναῖοι, τὸν αὐτὸν τρόπον γεγράφασιν. “ἔστω” φησὶν “ὑπὲρ αὐτοῦ ἡ αὐτὴ τιμωρία καθάπερ ἂν τὸν Ἀθηναῖον ἀποκτείνῃ,” κυρίους μὲν ἐῶντες τοὺς περὶ τούτων ὑπάρχοντας ὑμῖν νόμους, σεμνοὺς δ’ ἀποφαίνοντες, οἵ γ’ ἐν δωρειᾶς ἐποιήσαντο τάξει τὸ τούτων μεταδοῦναι. ἀλλ’ οὐκ Ἀριστοκράτης, ἀλλὰ προπηλακίζει μὲν καθ’ ὅσον δύναται τούτους (ὡς γοῦν οὐδενὸς ἀξίων ἴδιόν τι γράφειν ἐπεχείρησεν), μικρὰν δ’ ἀποφαίνει κἀκείνην τὴν δωρειὰν ᾗ τὴν πολιτείαν δεδώκατε τῷ Χαριδήμῳ. ὃς γάρ, ὡς ἀγαπώντων τοῦθ’ ὑμῶν καὶ προσοφειλόντων χάριν αὐτῷ, γέγραφεν καὶ πρὸς φυλάττειν ὑμᾶς ἐκεῖνον, ὅπως ἀδεῶς ὅ τι ἂν βούληται ποιῇ, πῶς οὐ τοῦθ’ ὃ λέγω διαπράττεται;", "st": "23.89"}, {"sp": "N", "t": "οὐκ ἀγνοῶ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, ὅτι ὡς μὲν οὐ παρὰ τοὺς νόμους φανερῶς γέγραφεν τὸ ψήφισμα Ἀριστοκράτης οὐχ ἕξει δεῖξαι, ὃ δὲ δεινότατον πάντων ἐστίν, τὸ μηδεμίαν κρίσιν ἐν παντὶ ποιῆσαι τῷ ψηφίσματι τοιαύτης αἰτίας, τοῦθ’ ὑφαιρεῖσθαι πειράσεται. ἐγὼ δὲ περὶ αὐτοῦ τούτου πολλὰ μὲν λέγειν οὐκ οἶμαι δεῖν, ἐκ δὲ τοῦ ψηφίσματος αὐτοῦ δείξω σαφῶς οὐδ’ αὐτὸν τοῦτον ἡγούμενον εἶναι κρίσιν οὐδεμίαν τῷ τὴν αἰτίαν ἔχοντι.", "st": "23.90"}, {"sp": "N", "t": "γέγραφεν γὰρ “ἐάν τις ἀποκτείνῃ Χαρίδημον, ἀγώγιμος ἔστω, ἐὰν δέ τις ἀφέληται ἢ πόλις ἢ ἰδιώτης, ἔκσπονδος ἔστω,” οὐκ “ἐὰν μὴ παράσχῃ εἰς κρίσιν τὸν ἀφαιρεθέντα,” ἀλλ’ ὅλως εὐθύς. καίτοι εἴ γ’ ἐδίδου κρίσιν καὶ μὴ ἀφῃρεῖτο, τότ’ ἂν προσέγραψεν κατὰ τῶν ἀφελομένων τὴν τιμωρίαν, ὁπότ’ εἰς τὴν κρίσιν μὴ παρέσχον ὃν ἐξείλοντο.", "st": "23.91"}, {"sp": "N", "t": "οἶμαι τοίνυν αὐτὸν κἀκεῖνον ἐρεῖν τὸν λόγον, καὶ σφόδρα ταύτῃ ζητήσειν ἐξαπατᾶν ὑμᾶς, ὡς ἄκυρόν ἐστι τὸ ψήφισμα· προβούλευμα γάρ ἐστιν, ὁ νόμος δ’ ἐπέτεια κελεύει τὰ τῆς βουλῆς εἶναι ψηφίσματα, ὥστε κἂν αὐτοῦ νῦν ἀποψηφίσησθε, ἥ γε πόλις φλαῦρον οὐδὲν πείσεται κατὰ τὸ ψήφισμα τοῦτο.", "st": "23.92"}, {"sp": "N", "t": "ἐγὼ δὲ πρὸς ταῦτ’ οἶμαι δεῖν ὑμᾶς ἐκεῖν’ ὑπολαμβάνειν, ὅτι τὸ ψήφισμα τοῦθ’ οὗτος ἔγραψεν οὐχ ἵν’ ὄντος ἀκύρου μηδὲν ἀηδὲς ὑμῖν συμβῇ (τὴν ἀρχὴν γὰρ ἐξῆν αὐτῷ μὴ γράφειν, εἴ γε τὸ βέλτιστον τῇ πόλει σκοπεῖν ἐβούλετο) ἀλλ’ ἵν’ ἐξαπατηθέντων ὑμῶν διαπράξαιντό τινες τἀναντία τοῖς ὑμῖν συμφέρουσιν. οἱ δὲ γραψάμενοι καὶ χρόνους ἐμποιήσαντες καὶ δι’ οὓς ἄκυρόν ἐστιν, ἡμεῖς ἐσμεν. ἄτοπον δὴ γένοιτ’ ἄν, εἰ ὧν ἡμῖν χάριν εἰκὸς ὑπάρχειν, ταῦτα τούτοις εἰς σωτηρίαν ὑπάρξειεν.", "st": "23.93"}, {"sp": "N", "t": "ἔτι τοίνυν οὐδ’ ἁπλοῦν τοῦθ’ οὕτως ἐστίν, ὥς τις οἴεται. εἰ μὲν γὰρ μηδεὶς ἄλλος ἦν ὅστις ἔμελλεν ὁμοίως τούτῳ τῶν συμφερόντων ὑμῖν ὀλιγωρήσας γράφειν, ἴσως ἂν ἦν τοῦτο· νῦν δ’ ὄντων οὐκ ὀλίγων οὐχὶ καλῶς ἔχει μὴ λῦσαι τὸ ψήφισμ’ ὑμῖν. τίς γὰρ οὐ γράψει θαρρῶν πάλιν, ἡνίκ’ ἂν ᾖ τοῦτ’ ἀποπεφευγός; τίς δ’ οὐκ ἐπιψηφιεῖ; τίς δὲ γράψεται; οὐ τοίνυν τοῦτο σκεπτέον, εἰ τοῦτ’ ἔστιν ἄκυρον τοῖς χρόνοις, ἀλλ’ ἐκεῖνο, ὅτι τῇ περὶ τούτου ψήφῳ, νῦν ἐὰν ἀποψηφίσησθε, τοῖς ἀδικεῖν βουλομένοις αὖθις ὑμᾶς ἄδειαν δώσετε.", "st": "23.94"}, {"sp": "N", "t": "οὐ τοίνυν οὐδ’ ἐκεῖνό μ’, ὦ ἄνδρες Ἀθηναῖοι, λέληθεν, ὅτι ἁπλῆν μὲν οὐδὲ δικαίαν οὐδ’ ἡντινοῦν ἀπολογίαν Ἀριστοκράτης ἕξει λέγειν, παραγωγὰς δέ τινας τοιαύτας ἐρεῖ, ὡς ἄρα πολλὰ τοιαῦτ’ ἤδη γέγονε ψηφίσματα πολλοῖς. ἔστι δ’ οὐδέν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτο σημεῖον τοῦ τοῦτον ἔννομ’ εἰρηκέναι· πολλαὶ γὰρ προφάσεις εἰσὶν δι’ ἃς πολλάκις ὑμεῖς ἐξηπάτησθε.", "st": "23.95"}, {"sp": "N", "t": "οἷον εἴ τι τῶν ἑαλωκότων ψηφισμάτων παρ’ ὑμῖν μὴ ἐγράφη, κύριον ἂν δήπουθεν ἦν· καὶ μὴν παρὰ τοὺς νόμους γ’ ἂν εἴρητο. καὶ εἴ τί γε γραφὲν ἢ καθυφέντων τῶν κατηγόρων ἢ μὴ δυνηθέντων μηδὲν διδάξαι ἀπέφυγεν, καὶ τοῦτ’ οὐδὲν κωλύει παράνομον εἶναι. οὐκ ἄρ’ εὐορκοῦσιν οἱ δικάσαντες αὐτό; ναί. πῶς; ἐγὼ διδάξω. γνώμῃ τῇ δικαιοτάτῃ δικάσειν ὀμωμόκασιν, ἡ δὲ τῆς γνώμης δόξα ἀφ’ ὧν ἂν ἀκούσωσι παρίσταται· ὅτε τοίνυν κατὰ ταύτην ἔθεντο τὴν ψῆφον, εὐσεβοῦσιν.", "st": "23.96"}, {"sp": "N", "t": "πᾶς γὰρ ὁ μήτε δι’ ἔχθραν μήτε δι’ εὔνοιαν μήτε δι’ ἄλλην ἄδικον πρόφασιν μηδεμίαν παρ’ ἃ γιγνώσκει θέμενος τὴν ψῆφον εὐσεβεῖ· εἰ γὰρ ἠγνόησέν τι διδασκόμενος, τοῦ μὴ συνεῖναι δίκην οὐκ ὀφείλει δοῦναι· ἀλλ’ εἴ τις εἰδὼς ἐκείνους προδέδωκεν ἢ ἐξαπατᾷ, οὗτός ἐστ’ ἔνοχος τῇ ἀρᾷ. διόπερ καταρᾶται καθ’ ἑκάστην ἐκκλησίαν ὁ κῆρυξ, οὐκ εἴ τινες ἐξηπατήθησαν, ἀλλ’ εἴ τις ἐξαπατᾷ λέγων ἢ βουλὴν ἢ δῆμον ἢ τὴν ἡλιαίαν.", "st": "23.97"}, {"sp": "N", "t": "μὴ δὴ τοῦθ’ ὑμῖν ἐᾶτε λέγειν, ὡς γέγονεν, ἀλλ’ ὡς ἔστι δίκαιον γίγνεσθαι, μηδ’ ὡς ἕτεροι δικάσαντες ἐκύρωσαν ἐκεῖνα, ἀλλ’ ὑμᾶς αὐτοὺς ἀξιοῦτε διδάσκειν ὡς δικαιότερ’ ἡμῶν περὶ τοῦδε λέγουσιν. εἰ δὲ τοῦτο μὴ δυνήσονται, οὐχὶ καλῶς ἔχειν ὑμῖν ἡγοῦμαι τὴν ἑτέρων ἀπάτην κυριωτέραν ποιήσασθαι τῆς ὑμετέρας αὐτῶν γνώμης.", "st": "23.98"}, {"sp": "N", "t": "ἔτι τοίνυν ἔμοιγε δοκεῖ καὶ σφόδρ’ ἀναιδὴς ὁ τοιοῦτος εἶναι λόγος, ὡς γέγονεν καὶ πρότερόν τισιν ἄλλοις τοιαῦτα ψηφίσματα. οὐ γὰρ εἴ τι πώποτε μὴ κατὰ τοὺς νόμους ἐπράχθη, σὺ δὲ τοῦτ’ ἐμιμήσω, διὰ τοῦτ’ ἀποφεύγειν σοι προσήκει, ἀλλὰ τοὐναντίον πολὺ μᾶλλον ἁλίσκεσθαι διὰ ταῦτα. ὥσπερ γάρ, εἴ τις ἐκείνων ἑάλω, σὺ τάδ’ οὐκ ἂν ἔγραψας, οὕτως, ἐὰν σὺ νῦν ἁλῷς, ἄλλος οὐ γράψει.", "st": "23.99"}, {"sp": "N", "t": "ὡς μὲν τοίνυν οὐ παρὰ πάντας τοὺς νόμους φανερῶς γέγραφεν τὸ ψήφισμ’ Ἀριστοκράτης, οὐκ οἶμαι λέγειν αὐτὸν ἕξειν· ἤδη δέ τιν’ εἶδον, ὦ ἄνδρες Ἀθηναῖοι, γραφὴν ἀγωνιζόμενον παρανόμων τοῖς νόμοις μὲν ἁλισκόμενον, ὡς δὲ συμφέρονθ’ ὑμῖν γέγραφεν λέγειν ἐπιχειροῦντα καὶ ταύτῃ βιαζόμενον, εὐήθη μέν, οἶμαι, μᾶλλον δ’ ἀναιδῆ λόγον.", "st": "23.100"}, {"sp": "N", "t": "εἰ γὰρ καὶ κατὰ τἄλλα πάντα συμφέρει τὰ εἰρημένα, ᾗ γ’ ὀμωμοκότας κατὰ τοὺς νόμους δικάσειν ὑμᾶς ἀξιοῖ κυροῦν ἃ μηδ’ αὐτὸς ἔχει δικαίως δεῖξαι γεγραμμένα, ἀσύμφορ’ ἂν εἴη, εἴπερ τὸ εὐορκεῖν περὶ πλείστου πᾶσίν ἐστι ποιητέον· οὐ μὴν ἀλλ’ ἔχει τιν’ ὅμως ἡ ἀναίδει’ αὕτη λόγον. τούτῳ τοίνυν οὐδ’ οὗτος ἐνέσται πρὸς ὑμᾶς ὁ λόγος· οὕτω γὰρ σφόδρ’ ἐναντίον ὂν τοῖς νόμοις τὸ ψήφισμα μᾶλλον ἀσύμφορόν ἐστιν ἢ παράνομον.", "st": "23.101"}, {"sp": "N", "t": "βούλομαι δ’ ἤδη καὶ τοῦθ’ ὑμῖν ἐπιδεικνύναι. ἵνα δ’ ὡς διὰ βραχυτάτου λόγου δῆλον ὃ βούλομαι ποιήσω, παράδειγμά τι γνώριμον πᾶσιν ὑμῖν ἐρῶ. ἴσθ’ ὅτι συμφέρει τῇ πόλει μήτε Θηβαίους μήτε Λακεδαιμονίους ἰσχύειν, ἀλλὰ τοῖς μὲν Φωκέας ἀντιπάλους, τοῖς δ’ ἄλλους τινὰς εἶναι· ἐκ γὰρ τοῦ ταῦθ’ οὕτως ἔχειν ἡμῖν ὑπάρχει μεγίστοις οὖσιν ἀσφαλῶς οἰκεῖν.", "st": "23.102"}, {"sp": "N", "t": "τοῦτο τοίνυν νομίζετε ταὐτὸ καὶ τοῖς Χερρόνησον οἰκοῦσι τῶν πολιτῶν συμφέρειν, μηδέν’ εἶναι τῶν Θρᾳκῶν ἰσχυρόν· ἡ γὰρ ἐκείνων πρὸς ἀλλήλους ταραχὴ καὶ ὑποψία φρουρὰ Χερρονήσου μεγίστη τῶν πασῶν ἐστιν καὶ βεβαιοτάτη. τὸ τοίνυν ψήφισμα τουτὶ τῷ μὲν ἡγουμένῳ τῶν Κερσοβλέπτου πραγμάτων ἀσφάλειαν διδόν, τοῖς δὲ τῶν ἑτέρων βασιλέων στρατηγοῖς φόβον καὶ δέος μή τιν’ αἰτίαν ἔχωσι παριστάν, τοὺς μὲν ἀσθενεῖς, τὸν δ’ ἕν’ ὄντ’ ἰσχυρὸν καθίστησιν.", "st": "23.103"}, {"sp": "N", "t": "ἵνα δὲ μὴ πάνυ θαυμάζητ’ εἰ τὰ παρ’ ὑμῖν ψηφίσματα τηλικαύτην ἔχει δύναμιν, γεγονὸς καὶ ὃ πάντες ἐπίστασθε πρᾶγμ’ ὑμᾶς ὑπομνήσω. ὅτε Μιλτοκύθης ἀπέστη Κότυος, συχνὸν ἤδη χρόνον ὄντος τοῦ πολέμου, καὶ ἀπηλλαγμένου μὲν Ἐργοφίλου, μέλλοντος δ’ Αὐτοκλέους ἐκπλεῖν στρατηγοῦ, ἐγράφη τι παρ’ ὑμῖν ψήφισμα τοιοῦτον, δι’ οὗ Μιλτοκύθης μὲν ἀπῆλθε φοβηθεὶς καὶ νομίσας ὑμᾶς οὐ προσέχειν αὐτῷ, Κότυς δ’ ἐγκρατὴς τοῦ τ’ ὄρους τοῦ ἱεροῦ καὶ τῶν θησαυρῶν ἐγένετο. καὶ γάρ τοι μετὰ ταῦτ’, ὦ ἄνδρες Ἀθηναῖοι, Αὐτοκλῆς μὲν ἐκρίνεθ’ ὡς ἀπολωλεκὼς Μιλτοκύθην, οἱ δὲ χρόνοι κατὰ τοῦ τὸ ψήφισμ’ εἰπόντος τῆς γραφῆς ἐξεληλύθεσαν, τὰ δὲ πράγματ’ ἀπωλώλει τῇ πόλει.", "st": "23.104"}, {"sp": "N", "t": "εὖ τοίνυν ἴσθ’ ὅτι καὶ νῦν, εἰ μὴ λύσετε τὸ ψήφισμα τοδί, καὶ τοῖς βασιλεῦσι θαυμαστὴ γενήσεται δι’ αὔτ’ ἀθυμία καὶ τοῖς στρατηγοῖς αὐτῶν· ὅλως γὰρ ἡγήσονται παρεῶσθαι μὲν αὐτοί, πρὸς Κερσοβλέπτην δ’ ἀποκλίνειν ὑμᾶς. εἰ δ’ ἐκ τοῦ ταῦτα γνῶναι παραχωρήσονται τῆς ἀρχῆς ἐπὶ καιροῦ τινος αὐτοῖς ἐπιθεμένου τοῦ Κερσοβλέπτου, πάλιν ὁρᾶτε τί συμβήσεται.", "st": "23.105"}, {"sp": "N", "t": "φέρε γὰρ πρὸς θεῶν, ἂν ἡμᾶς ἀδικῇ Κερσοβλέπτης, ὃ μᾶλλον ἐλπὶς ἢ μὴ δυνηθέντα ποιῆσαι, οὐκ ἐπ’ ἐκείνους ἴμεν καὶ δι’ ἐκείνων ἀσθενῆ ποιεῖν αὐτὸν ζητήσομεν; ἂν οὖν εἴπωσ’ ἡμῖν ὅτι “ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, οὐ μόνον ἡμῖν ἀδικουμένοις οὐκ ἐβοηθήσατε, ἀλλὰ καὶ φόβον, ἂν ὑπὲρ ἡμῶν αὐτῶν ἀμυνώμεθα, θαυμαστὸν παρεστήσατε, ψήφισμα ποιησάμενοι, τὸν ἐναντία τοῖς ὑμῖν συμφέρουσι καὶ ἡμῖν πράττοντ’ ἐάν τις ἀποκτείνῃ, ἀγώγιμον εἶναι· οὔκουν ἐστὲ δίκαιοι βοηθοὺς καλεῖν ἡμᾶς, ἐφ’ οἷς καὶ περὶ ὑμᾶς αὐτοὺς καὶ περὶ ἡμᾶς κακῶς ἐβουλεύσασθε,” εἰπέ μοι, ταῦτ’ ἐὰν λέγωσιν, οὐ δικαιότερ’ ἡμῶν ἐροῦσιν; ἔγωγ’ οἶμαι.", "st": "23.106"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνό γ’ ἔστιν εἰπεῖν, ὅτι νὴ Δί’ εἰκότως ἐφενακίσθητε καὶ παρεκρούσθητε. εἰ γὰρ μηδὲν εἴχετε τῶν ἄλλων λογίσασθαι, μηδ’ ἐφ’ ὑμῶν αὐτῶν οἷοί τ’ ἦτε ταῦτα συνεῖναι, ἦν ἰδεῖν παράδειγμα Ὀλυνθίους τουτουσί, οἳ τί πεποιηκότος αὐτοῖς Φιλίππου πῶς αὐτῷ χρῶνται; ἐκεῖνος ἐκείνοις Ποτείδαιαν οὐχὶ τηνικαῦτ’ ἀπέδωκεν, ἡνίκ’ ἀποστερεῖν οὐκέθ’ οἷός τ’ ἦν, ὥσπερ ὑμῖν Κερσοβλέπτης Χερρόνησον· ἀλλὰ πρὸς ὑμᾶς πολεμῶν χρήματα πόλλ’ ἀναλώσας, ἑλὼν καὶ δυνηθεὶς ἂν αὐτὸς ἔχειν, εἴπερ ἐβουλήθη, παρέδωκεν καὶ οὐδ’ ἐπεχείρησεν ἄλλο ποιεῖν οὐδέν.", "st": "23.107"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἐκεῖνοι, τέως μὲν ἑώρων αὐτὸν τηλικοῦτον ἡλίκος ὢν πιστὸς ὑπῆρχεν, σύμμαχοί τ’ ἦσαν καὶ δι’ ἐκεῖνον ἡμῖν ἐπολέμουν, ἐπειδὴ δ’ εἶδον μείζω τῆς πρὸς αὑτοὺς πίστεως γιγνόμενον, τοσοῦτ’ ἀπέχουσι τοῦ ψηφίσασθαι, ἐάν τις ἀποκτείνῃ τινὰ τῶν ἐκείνῳ συγκατεσκευακότων τὴν ἀρχήν, ἐκ τῶν ἑαυτῶν συμμάχων ἀγώγιμον εἶναι,", "st": "23.108"}, {"sp": "N", "t": "ὥσθ’ ὑμᾶς, οὓς ἴσασιν ἁπάντων ἀνθρώπων ἥδιστ’ ἂν καὶ τοὺς ἐκείνου φίλους καὶ αὐτὸν τὸν Φίλιππον ἀποκτείναντας, φίλους πεποίηνται, φασὶ δὲ καὶ συμμάχους ποιήσεσθαι. εἶτ’ Ὀλύνθιοι μὲν ἴσασι τὸ μέλλον προορᾶν, ὑμεῖς δ’ ὄντες Ἀθηναῖοι ταὐτὸν τοῦτ’ οὐχὶ ποιήσετε; ἀλλ’ αἰσχρὸν τοὺς ⟨τῷ⟩ περὶ πραγμάτων ἐπίστασθαι βουλεύσασθαι δοκοῦντας προέχειν ἧττον Ὀλυνθίων τὸ συμφέρον εἰδότας ὀφθῆναι.", "st": "23.109"}, {"sp": "N", "t": "ἀκούω τοίνυν αὐτὸν καὶ τοιοῦτόν τιν’ ἐρεῖν λόγον, οἷον καὶ πρότερόν ποτ’ Ἀριστόμαχος παρ’ ὑμῖν ἐδημηγόρει, ὡς οὐκ ἔστιν ὅπως ποτὲ Κερσοβλέπτης αἱρήσεται Χερρόνησον ἀποστερεῖν ἐπιχειρῶν ἐχθρὸς ὑμῖν εἶναι· οὐδὲ γὰρ εἰ λάβοι καὶ κατάσχοι, λυσιτελήσειν αὐτῷ. ἐκ μέν γ’ ἐκείνης οὐκ ἔστιν ὑπὲρ τριάκοντα τάλανθ’ ἡ πρόσοδος μὴ πολεμουμένης, εἰ πολεμήσεται δέ, οὐδὲ ἕν· ἐκ δὲ τῶν ἐμπορίων, ἃ τότ’ ἂν κλεισθείη, πλεῖν ἢ διακόσια [τάλαντά ἐσθ’ ἡ πρόσοδος]· ὥστε τί βουλόμενος μικρὰ λαμβάνειν καὶ πολεμεῖν ἂν ἕλοιτο, ἐξὸν τὰ πλείω καὶ φίλος εἶναι, θαυμάζειν φήσουσιν.", "st": "23.110"}, {"sp": "N", "t": "ἐγὼ δ’ οὐκ ἀπορῶ μὲν εἰπεῖν πόλλ’ ἅ μοι δοκεῖ μᾶλλον ἄν τις ἰδὼν ἀπιστεῖν εἰκότως ἢ τούτοις πιστεύων ἐκεῖνον ἐᾶν μέγαν γίγνεσθαι· οὐ μὴν ἀλλ’ ὃ μάλιστα πρόχειρον ἔχω, τοῦτ’ ἐρῶ. ἴστε δήπου Φίλιππον, ἄνδρες Ἀθηναῖοι, τουτονὶ τὸν Μακεδόνα, ᾧ πολὺ δήπου μᾶλλον ἐλυσιτέλει τὰς ἐξ ἁπάσης Μακεδονίας προσόδους ἀδεῶς λαμβάνειν ἢ μετὰ κινδύνων τὰς ἐξ Ἀμφιπόλεως, καὶ χρῆσθαι φίλοις αἱρετώτερον ἦν αὐτῷ τοῖς πατρικοῖς ὑμῖν ἢ Θετταλοῖς, οἳ τὸν πατέρ’ αὐτοῦ ποτ’ ἐξέβαλον.", "st": "23.111"}, {"sp": "N", "t": "ἄνευ γὰρ τούτου κἀκεῖν’ ἔστιν ἰδεῖν· ὑμεῖς μέν, ὦ ἄνδρες Ἀθηναῖοι, οὐδένα προὐδώκατε πώποτε τῶν φίλων, Θετταλοὶ δ’ οὐδένα πώποθ’ ὅντιν’ οὔ. ἀλλ’ ὅμως οὕτως ἐχόντων τούτων μικρὰ λαμβάνειν καὶ τοὺς ἀπίστους φίλους καὶ τὸ κινδυνεύειν ἀντὶ τοῦ μετ’ ἀσφαλείας ζῆν ὁρᾶτε προῃρημένον αὐτόν.", "st": "23.112"}, {"sp": "N", "t": "τί δή ποτ’ αἴτιον; οὐ γὰρ δὴ λόγον γε τὸ πρᾶγμ’ οὑτωσὶ πρόχειρον ἔχει. ὅτι, ὦ ἄνδρες Ἀθηναῖοι, δυοῖν ἀγαθοῖν ὄντοιν πᾶσιν ἀνθρώποις, τοῦ μὲν ἡγουμένου καὶ μεγίστου πάντων, τοῦ εὐτυχεῖν, τοῦ δ’ ἐλάττονος μὲν τούτου, τῶν δ’ ἄλλων μεγίστου, τοῦ καλῶς βουλεύεσθαι, οὐχ ἅμ’ ἡ κτῆσις παραγίγνεται τοῖς ἀνθρώποις, οὐδ’ ἔχει τῶν εὖ πραττόντων οὐδεὶς ὅρον οὐδὲ τελευτὴν τῆς τοῦ πλεονεκτεῖν ἐπιθυμίας· δι’ ὅπερ πολλοὶ πολλάκις μειζόνων ἐπιθυμοῦντες τὰ παρόντ’ ἀπώλεσαν.", "st": "23.113"}, {"sp": "N", "t": "καὶ τί δεῖ Φίλιππον λέγειν ἤ τιν’ ἄλλον; ἀλλ’ ὁ πατὴρ αὐτὸς ὁ Κερσοβλέπτου Κότυς, ἡνίκα μὲν στασιάζοι πρός τινας, πρέσβεις πέμπων ἅπαντα ποιεῖν ἕτοιμος ἦν, καὶ τότ’ ᾐσθάνετο ὡς ἀλυσιτελὲς τὸ τῇ πόλει πολεμεῖν· ἐπειδὴ δ’ ὑφ’ αὑτῷ τὴν Θρᾴκην ἔχοι, κατελάμβανε τὰς πόλεις, ἠδίκει, μεθύων ἐπαρῴνει μάλιστα μὲν εἰς αὑτόν, εἶτα καὶ εἰς ἡμᾶς, τὴν χώραν ἐποιεῖθ’ ἑαυτοῦ, τὸ πρᾶγμ’ ἀμήχανον ἦν. τῶν γὰρ ὑπὲρ τοῦ πλεονεκτεῖν ἐπιχειρούντων οἷς οὐ χρὴ οὐ τὰ δυσχερέσταθ’ ἕκαστος εἴωθε λογίζεσθαι, ἀλλ’ ἃ κατορθώσας διαπράξεται.", "st": "23.114"}, {"sp": "N", "t": "ἐγὼ δὴ δεῖν ὑμᾶς οἶμαι τοῦτον τὸν τρόπον βεβουλεῦσθαι, ὅπως, ἂν μὲν ἃ χρὴ περὶ ὑμῶν γιγνώσκῃ Κερσοβλέπτης, μηδὲν ὑφ’ ὑμῶν ἀδικήσεται, ἂν δ’ ἀλόγως ἀδικεῖν ἐπιχειρῇ, μὴ μείζων ἔσται τοῦ δίκην δοῦναι. ἀναγνώσομαι δ’ ὑμῖν τὴν ἐπιστολὴν ἥν, ὅτ’ ἀφειστήκει Μιλτοκύθης, Κότυς ἔπεμψεν, καὶ ἣν [ὅτε] πᾶσαν ἔχων τὴν ἀρχὴν πέμψας Τιμομάχῳ τὰ χωρί’ ὑμῶν ἐξεῖλεν.", "st": "23.115"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΑΙ.", "st": "23.115"}, {"sp": "N", "t": "τοῦτ’, ὦ ἄνδρες Ἀθηναῖοι, τὸ παράδειγμ’ ἑορακότες, ἂν ἐμοὶ πείθησθε, κἀκεῖν’ εἰδότες, ὅτι Φίλιππος, ὅτε μὲν Ἀμφίπολιν ἐπολιόρκει, ἵν’ ὑμῖν παραδῷ πολιορκεῖν ἔφη, ἐπειδὴ δ’ ἔλαβεν, καὶ Ποτείδαιαν προσαφείλετο, ἐκείνην τὴν πίστιν βουλήσεσθ’ ἔχειν, ἥνπερ φασὶ πρὸς Λακεδαιμονίους ποτ’ εἰπεῖν Φιλοκράτην τὸν Ἐφιάλτου.", "st": "23.116"}, {"sp": "N", "t": "καὶ γὰρ ἐκεῖνόν φασιν, ἐξαπατώντων τι τῶν Λακεδαιμονίων καὶ προτεινόντων πίστιν ἥντινα βούλεται λαμβάνειν, εἰπεῖν ὅτι πίστιν ἂν οἴεται γενέσθαι μόνην, εἰ δείξειαν ὅπως, ἂν ἀδικεῖν βούλωνται, μὴ δυνήσονται, ἐπεὶ ὅτι γ’ ἀεὶ βουλήσονται εὖ εἰδέναι· ἕως ἂν οὖν δύνωνται, πίστιν οὐκ εἶναι. ταύτην, ἂν ἐμοὶ χρῆσθε συμβούλῳ, φυλάξετε τὴν πίστιν πρὸς τοῦτον τὸν Θρᾷκα, καὶ μὴ βουλήσεσθ’ εἰδέναι τιν’ ἄν, εἰ πάσης ἄρξειε Θρᾴκης, πρὸς ὑμᾶς σχοίη γνώμην.", "st": "23.117"}, {"sp": "N", "t": "ὅτι τοίνυν ὅλως οὐδ’ ὑγιαινόντων ἐστὶν ἀνθρώπων τοιαῦτα γράφειν ψηφίσματα καὶ διδόναι τισὶ τοιαύτας δωρειάς, καὶ τοῦτ’ ἐκ πολλῶν ῥᾴδιον γνῶναι. ἴστε γὰρ δήπου πάντες, ὦ ἄνδρες Ἀθηναῖοι, τοῦθ’ ὁμοίως ἐμοί, ὅτι τὸν Κότυν ποτ’ ἐκεῖνον ἐποιήσασθε πολίτην, δῆλον ὡς κατ’ ἐκεῖνον τὸν χρόνον εὔνουν ἡγούμενοι. καὶ μὴν καὶ χρυσοῖς στεφάνοις ἐστεφανοῦτε, οὐκ ἄν, εἴ γ’ ἐχθρὸν ἡγεῖσθε.", "st": "23.118"}, {"sp": "N", "t": "ἀλλ’ ὅμως, ἐπειδὴ πονηρὸς καὶ θεοῖς ἐχθρὸς ἦν καὶ μεγάλ’ ὑμᾶς ἠδίκει, τοὺς ἀποκτείναντας ἐκεῖνον Πύθωνα καὶ Ἡρακλείδην, τοὺς Αἰνίους, πολίτας ἐποιήσασθ’ ὡς εὐεργέτας καὶ χρυσοῖς στεφάνοις ἐστεφανώσατε. εἰ δὴ τότε, ὅθ’ ὑμῖν οἰκείως ἔχειν ὁ Κότυς ἐδόκει, ἔγραψέ τις, ἄν τις ἀποκτείνῃ Κότυν, ἔκδοτον αὐτὸν εἶναι, πότερ’ ἐξέδοτ’ ἂν τὸν Πύθωνα καὶ τὸν ἀδελφόν, ἢ παρὰ τὸ ψήφισμα τοῦτο πολίτας ἐποιεῖσθε καὶ ὡς εὐεργέτας ἐτιμᾶτε;", "st": "23.119"}, {"sp": "N", "t": "τί δ’; Ἀλέξανδρον ἐκεῖνον τὸν Θετταλόν, ἡνίκ’ εἶχε μὲν αἰχμάλωτον δήσας Πελοπίδαν, ἐχθρὸς δ’ ὡς οὐδεὶς ἦν Θηβαίοις, ὑμῖν δ’ οἰκείως διέκειθ’ οὕτως ὥστε παρ’ ὑμῶν στρατηγὸν αἰτεῖν, ἐβοηθεῖτε δ’ αὐτῷ καὶ πάντ’ ἦν Ἀλέξανδρος, πρὸς Διὸς εἴ τις ἔγραψεν, ἄν τις ἀποκτείνῃ Ἀλέξανδρον, ἀγώγιμον εἶναι, ἆρ’ ἂν ὧν μετὰ ταῦθ’ ὕβρισεν καὶ προὐπηλάκισεν ἀσφαλὲς ἦν τῳ παρ’ αὐτοῦ δίκην πειρᾶσθαι λαβεῖν;", "st": "23.120"}, {"sp": "N", "t": "τί δὲ τἄλλα λέγοι τις ἄν; ἀλλ’ ὁ μάλιστα δοκῶν νῦν ἡμῖν ἐχθρὸς εἶναι Φίλιππος οὑτοσί, εἰ τότε, ὅτ’ Ἀργαῖον κατάγοντας λαβὼν τῶν ἡμετέρων τινὰς πολιτῶν ἀφῆκε μὲν αὐτούς, ἀπέδωκε δὲ πάνθ’ ὅσ’ ἀπώλεσαν αὐτοῖς, πέμψας δὲ γράμματ’ ἐπηγγέλλεθ’ ἕτοιμος εἶναι συμμαχίαν ποιεῖσθαι καὶ τὴν πατρικὴν φιλίαν ἀνανεοῦσθαι, εἰ τότ’ ἠξίωσε τυχεῖν τούτων καί τις ἔγραψε τῶν ἀφεθέντων ὑπ’ αὐτοῦ, ἐάν τις ἀποκτείνῃ Φίλιππον, ἀγώγιμον εἶναι, καλήν γ’ ὕβριν ἦμεν ἂν ὑβρισμένοι.", "st": "23.121"}, {"sp": "N", "t": "ἆρά γ’ ὁρᾶτε καὶ καταμανθάνετ’, ὦ ἄνδρες Ἀθηναῖοι, ἐφ’ ἑκάστου τούτων ἡλίκην ἂν ὠφληκότες ἦτε παράνοιαν, εἴ τι τοιοῦτον ἐτυγχάνετ’ ἐψηφισμένοι; ἔστι γὰρ οὐχ ὑγιαινόντων, οἶμαι, ἀνθρώπων, οὔθ’ ὅταν τιν’ ὑπειλήφωσι φίλον, οὕτω πιστεύειν ὥστε, ἂν ἀδικεῖν ἐπιχειρῇ, τὸ ἀμύνασθαι σφῶν αὐτῶν ἀφελέσθαι, οὔθ’ ὅταν ἐχθρόν τιν’ ἡγῶνται, οὕτως αὖ μισεῖν ὥστε, ἂν παυσάμενος βούληται φίλος εἶναι, τὸ ποιεῖν ἐξεῖναι ταῦτα κωλῦσαι· ἀλλ’ ἄχρι τούτου καὶ φιλεῖν, οἶμαι, χρὴ καὶ μισεῖν, μηδετέρου τὸν καιρὸν ὑπερβάλλοντας.", "st": "23.122"}, {"sp": "N", "t": "οὐ τοίνυν ἔγωγ’ οὐδ’ ἐκεῖν’ ἰδεῖν δύναμαι, ὡς οὐχὶ πάντες ἄνθρωποι τούτων ἀξιώσουσι τυχεῖν, ὅσοις πέρ ἐστι καὶ ἡτισοῦν εὐεργεσίας πρόφασις πρὸς ὑμᾶς, εἰ Χαριδήμῳ δώσετε, οἷον, εἰ βούλεσθε, Σίμων, Βιάνωρ, Ἀθηνόδωρος, ἄλλοι μυρίοι. εἰ μὲν τοίνυν πᾶσι ψηφιούμεθα ταῦτα, λήσομεν, ὡς ἔοικε, μισθοφόρων ἔργον ἀνθρώπων ποιοῦντες τὴν ἑκάστου σωτηρίαν τούτων δορυφοροῦντες· εἰ δὲ τῷ μέν, τοῖς δ’ οὔ, δικαίως ἐγκαλοῦσιν οἱ μὴ τυχόντες.", "st": "23.123"}, {"sp": "N", "t": "φέρ’, ἐὰν δὲ δὴ καὶ Μενέστρατος ἡμᾶς ὁ Ἐρετριεὺς ἀξιοῖ ταὐτὰ καὶ αὑτῷ ψηφίσασθαι, ἢ Φάυλλος ὁ Φωκεὺς ἤ τις ἄλλος δυνάστης (πολλοῖς δὲ δήπου διὰ καιρούς τινας πολλάκις φίλοι γιγνόμεθα), πότερον ψηφιούμεθα πᾶσιν ἢ οὔ; ψηφιούμεθα νὴ Δία. καὶ τί φήσομεν, ὦ ἄνδρες Ἀθηναῖοι, καλόν, εἰ τῶν Ἑλλήνων ἐπ’ ἐλευθερίᾳ προεστάναι φάσκοντες τοὺς ἰδίᾳ δυνάμεις ἐπὶ τοῖς πλήθεσι κεκτημένους δορυφοροῦντες φανούμεθα;", "st": "23.124"}, {"sp": "N", "t": "εἰ γάρ ἐστί τῳ δοτέον τι τοιοῦτον, ὡς ἔγωγ’ οὔ φημι, πρῶτον μὲν τῷ μηδὲν ἠδικηκότι πώποτε, δεύτερον δὲ μηδ’ ἂν ἀδικεῖν βούληται δυνησομένῳ, ἔπειθ’ ὡς ἀληθῶς ὅστις ἅπασιν ἀνθρώποις ἔσται φανερὸς ὑπὲρ τοῦ μή ⟨τι⟩ παθεῖν ταῦθ’ εὑρισκόμενος, καὶ οὐκ ἐπὶ τῷ ποιεῖν μετ’ ἀδείας ἑτέρους κακῶς, τούτῳ δοτέον. ὅτι μὲν τοίνυν ὁ Χαρίδημος οὔτε τῶν ἀναμαρτήτων ἐστὶ πρὸς ὑμᾶς οὔτε τῶν ἵνα μή τι πάθῃ ταῦθ’ εὑρισκομένων, ἐάσω· ἀλλ’ ὡς οὐδὲ πιστὸς εἰς τὸν ἔπειτα χρόνον, ἀκούσατέ μου, καὶ σκοπεῖτε, ἂν ὑμῖν ὀρθῶς ἐξετάζειν δοκῶ.", "st": "23.125"}, {"sp": "N", "t": "ἐγὼ νομίζω, ὦ ἄνδρες Ἀθηναῖοι, ὅσοι μὲν τῶν ἡμετέρων ἐθῶν καὶ νόμων ἐπιθυμηταὶ γενόμενοι πολῖται γενέσθαι ἐσπούδασαν, ἅμα τ’ αὐτοὺς ἂν τυγχάνειν τούτων καὶ παρ’ ἡμῖν οἰκεῖν καὶ μετέχειν ὧν ἐπεθύμησαν· ὅσους δὲ τούτων μὲν μηδενὸς μήτ’ ἐπιθυμία μήτε ζῆλος εἰσέρχεται, τὴν πλεονεξίαν δ’ ἀγαπῶσιν ἣν διὰ τοῦ δοκεῖν ὑφ’ ὑμῶν τιμᾶσθαι καρποῦνται, τούτους δ’ οἴομαι, μᾶλλον δ’ οἶδα σαφῶς, ὅταν ποτὲ μείζονος πλεονεξίας ἑτέρωθεν ἐλπίδ’ ἴδωσιν, οὐδ’ ὁτιοῦν ὑμῶν φροντίσαντας ἐκείνην θεραπεύσειν.", "st": "23.126"}, {"sp": "N", "t": "οἷον, ἵν’ εἰδῆτε καὶ ὑμεῖς πρὸς ὃ ταῦτ’ ἐγὼ βλέπων λέγω, Πύθων οὑτοσί, ὅτε μὲν Κότυν εὐθὺς ἀπεκτονὼς οὐκ ἀσφαλὲς ἡγεῖτ’ ἀπελθεῖν ὅποι τύχοι, ἦλθεν ὡς ὑμᾶς καὶ πολιτείαν ᾔτησεν καὶ πάντων ἐποιήσατο πρώτους ὑμᾶς, ἐπειδὴ δ’ οἴεται τὰ Φιλίππου πράγματα συμφέρειν αὑτῷ μᾶλλον, οὐδ’ ὁτιοῦν ὑμῶν φροντίσας τἀκείνου φρονεῖ. οὐ γάρ ἐστιν, οὐκ ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, παρὰ τούτοις τοῖς ἐπὶ τῇ τοῦ πλεονεκτεῖν προαιρέσει ζῶσιν οὐδὲν οὔτε βέβαιον οὔθ’ ὅσιον, ἀλλὰ δεῖ τούτων, ὅστις εὖ φρονεῖ, φυλαττόμενον περιεῖναι, μὴ προπιστεύσαντα κατηγορεῖν.", "st": "23.127"}, {"sp": "N", "t": "εἰ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τοὐναντίον ἢ τἀληθὲς ὑπάρχει, θείημεν τὸν Χαρίδημον αὐτὸν καὶ γεγενῆσθαι περὶ ἡμᾶς σπουδαῖον καὶ εἶναι καὶ ἔσεσθαι, καὶ μηδέποτ’ ἄλλην γνώμην ἢ ταύτην σχήσειν, οὐδὲν μᾶλλον ἔχει καλῶς ταῦτ’ αὐτῷ ψηφίσασθαι. εἰ μὲν γὰρ ἐπ’ ἄλλο τι ταύτην τὴν ἄδειαν ἐλάμβανε, τὴν ἐκ τοῦ ψηφίσματος, ἢ τὰ Κερσοβλέπτου πράγματα, ἧττον ἂν ἦν δεινόν· νῦν δέ, ὑπὲρ οὗ καταχρήσεται τῇ διὰ τοῦ ψηφίσματος πλεονεξίᾳ, οὐκ ἀξιόπιστον οὔθ’ ἡμῖν οὔτ’ ἐκείνῳ λογιζόμενος [αὐτὸν] εὑρίσκω.", "st": "23.128"}, {"sp": "N", "t": "σκέψασθε δ’ ὡς δικαίως ἕκαστ’ ἐξετάζω, καὶ σφόδρα γ’ εἰκότως δεδιώς. ἐγὼ σκοπῶ Κότυν, ὅτι κηδεστὴς ἦν Ἰφικράτει τὸν αὐτὸν τρόπον ὅνπερ Χαριδήμῳ Κερσοβλέπτης, καὶ τὰ πεπραγμέν’ ὁρῶ πολλῷ μείζονα καὶ χάριτος πλείονος ἄξι’ ὑπὲρ Κότυος Ἰφικράτει ἢ ὑπὲρ Κερσοβλέπτου Χαριδήμῳ.", "st": "23.129"}, {"sp": "N", "t": "σκεψώμεθα δ’ οὑτωσί. ἴστε δήπου τοῦτ’, ἄνδρες Ἀθηναῖοι, ὅτι χαλκῆς εἰκόνος οὔσης παρ’ ὑμῖν Ἰφικράτει καὶ σιτήσεως ἐν πρυτανείῳ καὶ δωρειῶν καὶ τιμῶν ἄλλων, δι’ ἃς εὐδαίμων ἐκεῖνος ἦν, ὅμως ἐτόλμησεν ὑπὲρ τῶν Κότυος πραγμάτων ἐναντία τοῖς ὑμετέροις στρατηγοῖς ναυμαχεῖν, καὶ περὶ πλείονος ἐποιήσατο τὴν ἐκείνου σωτηρίαν ἢ τὰς ὑπαρχούσας ἑαυτῷ παρ’ ὑμῖν τιμάς· καὶ εἰ μὴ μετριωτέραν ἔσχετε τὴν ὀργὴν ὑμεῖς τῆς ἐκείνου προπετείας, οὐδὲν ἂν αὐτὸν ἐκώλυεν ἀθλιώτατον ἀνθρώπων ἁπάντων εἶναι.", "st": "23.130"}, {"sp": "N", "t": "ἀλλ’ ὅμως ὁ Κότυς, ὑπ’ ἐκείνου σωθεὶς καὶ λαβὼν ἔργῳ τῆς ἐκείνου φιλίας πεῖραν, ἐπειδὴ βεβαίως ἡγήσατο σῶς εἶναι, οὐχ ὅπως ἀποδώσει χάριν ἐσπούδασεν αὐτῷ καὶ πρὸς ὑμᾶς δι’ ἐκείνου τι φιλάνθρωπον ἔπραξεν, ἵνα συγγνώμης ἐπὶ τοῖς πεπραγμένοις τύχῃ, ἀλλὰ πᾶν τοὐναντίον ἠξίου μὲν αὐτὸν συμπολιορκεῖν τὰ λοιπὰ τῶν ὑμετέρων χωρίων,", "st": "23.131"}, {"sp": "N", "t": "οὐκ ἐθέλοντος δ’ ἐκείνου, λαβὼν αὐτὸς τήν τε βαρβαρικὴν δύναμιν καὶ τὴν ὑπ’ ἐκείνου συνειλεγμένην, καὶ τὸν Χαρίδημον τοῦτον προσμισθωσάμενος, προσέβαλλε τοῖς ὑμετέροις χωρίοις, καὶ εἰς τοῦτο κατέστησε τὸν Ἰφικράτην ἀπορίας, ὥστ’ ἀπελθόντ’ εἰς Ἄντισσαν οἰκεῖν καὶ πάλιν εἰς Δρῦν, ἡγούμενον ὡς μὲν ὑμᾶς οὐχὶ καλῶς ἔχειν ἐλθεῖν, οὓς ὑστέρους ἐπεποίητο τοῦ Θρᾳκὸς καὶ τοῦ βαρβάρου, παρ’ ἐκείνῳ δ’ οὐκ ἀσφαλὲς εἶναι μένειν, ὃν οὕτως ὀλιγωροῦνθ’ ἑώρα τῆς ἑαυτοῦ σωτηρίας.", "st": "23.132"}, {"sp": "N", "t": "ἂν οὖν, ὦ ἄνδρες Ἀθηναῖοι, καὶ Κερσοβλέπτης ἐκ τῆς τῷ Χαριδήμῳ νῦν ἀδείας κατασκευαζομένης αὐξηθεὶς ὀλιγωρῇ μὲν ἐκείνου, νεωτερίζῃ δέ τι καὶ κινῇ πρὸς ὑμᾶς, ἐξαρκεῖ τοῦθ’ ὑμῖν, ἐὰν Χαρίδημος ἐξαπατηθῇ, τὸν Θρᾷκ’ ἰσχυρὸν ἐφ’ ὑμᾶς αὐτοὺς κατεσκευακέναι; ἐγὼ μὲν οὐκ ἀξιῶ. καὶ γὰρ ἐκεῖνο νομίζω δίκαιον, εἰ μὲν αἰσθάνεται ταῦτα καὶ προορᾷ Χαρίδημος, εἶθ’ ὅπως τοιούτων ψηφισμάτων τεύξεται διαπράττεται,", "st": "23.133"}, {"sp": "N", "t": "ὡς ἐπιβουλεύοντι μὴ ἐπιτρέπειν αὐτῷ, εἰ δὲ λέληθεν αὐτόν, ὅσῳ μᾶλλον εὔνουν τις αὐτὸν ὑπείληφεν εἶναι, τοσούτῳ μᾶλλον προϊδέσθαι καὶ ὑπὲρ αὑτοῦ καὶ ὑπὲρ ἐκείνου. ἔστι γὰρ φίλων ἀγαθῶν οὐ τὰ τοιαῦτα χαρίζεσθαι τοῖς εὔνοις, ἐξ ὧν κἀκείνοις καὶ σφίσιν αὐτοῖς ἔσται τις βλάβη, ἀλλ’ ὃ μὲν ἂν μέλλῃ συνοίσειν ἀμφοῖν, συμπράττειν, ὃ δ’ ἂν αὐτὸς ἄμεινον ἐκείνου προορᾷ, πρὸς τὸ καλῶς ἔχον τίθεσθαι καὶ μὴ τὴν ἤδη χάριν τοῦ μετὰ ταῦτα χρόνου παντὸς περὶ πλείονος ἡγεῖσθαι.", "st": "23.134"}, {"sp": "N", "t": "οὐ τοίνυν οὐδ’ ἐκεῖνο λογιζόμενος δύναμαι κατιδεῖν, ὡς, εἰ καὶ βάρβαρος καὶ ἄπιστος ὁ Κερσοβλέπτης, ὅμως προνοηθείη γ’ ἂν μὴ τὰ τηλικαῦτ’ ἀδικῆσαι Χαρίδημον. ὅταν γὰρ πάλιν ἐξετάσω ἡλίκων Κότυς Ἰφικράτην ἀποστερήσειν μέλλων οὐδὲν ἐφρόντισεν, παντελῶς τούτῳ γ’ οὐδὲν ἂν ἡγοῦμαι μελῆσαι τῶν ἀπολουμένων Χαριδήμῳ.", "st": "23.135"}, {"sp": "N", "t": "ὁ μέν γ’ ἐκεῖνον τιμάς, σίτησιν, εἰκόνας, πατρίδ’ ἣ ζηλωτὸν αὐτὸν ἐποίησεν, ὀλίγου δέω λέγειν πάνθ’ ὧν ἄνευ ζῆν οὐκ ἄξιον ἦν Ἰφικράτει, νομίζων ἀποστερήσειν οὐκ ἐπεστράφη· οὗτος δ’ ὡς ἀληθῶς τίνος ἂν καὶ λόγον σχοίη μὴ [τίνος] Χαρίδημον ἀποστερήσῃ; οὐδ’ ὁτιοῦν ἐστι γὰρ παρ’ ὑμῖν αὐτῷ, οὐ παῖδες, οὐκ εἰκών, οὐ συγγενεῖς, οὐκ ἄλλ’ οὐδέν.", "st": "23.136"}, {"sp": "N", "t": "καὶ μὴν εἰ μήτε φύσει πιστὸς ὁ Κερσοβλέπτης, ἔκ τε τῶν γεγενημένων πρότερον δικαίως ἄπιστος, μηδέν τε τοιοῦτον ὑπάρχει τοῖς πράγμασιν δι’ ὃ κἂν παρὰ γνώμην καὶ φύσιν προνοηθείη τι τοῦ Χαριδήμου, τίνος εἵνεχ’ ἁπλῶς καὶ κομιδῇ τετυφωμένως οὕτως, ἃ βούλεται διαπράξασθαι, συλλάβωμεν αὐτῷ, καὶ ταῦτ’ ἐφ’ ἡμῖν ὄντα; ἐγὼ μὲν οὐχ ὁρῶ.", "st": "23.137"}, {"sp": "N", "t": "ὅτι τοίνυν ἄνευ τοῦ τοῖς πράγμασι μὴ συμφέρειν τὸ ψήφισμα, οὐδὲ πρὸς δόξαν συμφέρει τῇ πόλει τοιοῦτον οὐδὲν ἐψηφισμένῃ φαίνεσθαι, καὶ τοῦτο δεῖ μαθεῖν ὑμᾶς. εἰ μὲν γάρ, ὦ ἄνδρες Ἀθηναῖοι, πόλιν οἰκοῦντί τῳ καὶ νόμοις πολιτευομένῳ τὸ ψήφισμ’ ἐγέγραπτο, δεινὸν ὂν ἧττον ἂν ἦν αἰσχρόν· νῦν δὲ γέγραπται Χαριδήμῳ τῷ πόλιν μὲν οὐδ’ ἡντινοῦν οἰκοῦντι, Θρᾳκὶ δ’ ἀνθρώπῳ [βασιλεῖ] στρατηγοῦντι καὶ διὰ τῆς ἐκείνου βασιλείας πολλοὺς ἀδικοῦντι.", "st": "23.138"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦθ’ ὅτι πάντες οἱ ξεναγοῦντες οὗτοι πόλεις καταλαμβάνοντες Ἑλληνίδας ἄρχειν ζητοῦσιν, καὶ πάντων, ὅσοι περ νόμοις οἰκεῖν βούλονται τὴν αὑτῶν ὄντες ἐλεύθεροι, κοινοὶ περιέρχονται κατὰ πᾶσαν χώραν, εἰ δεῖ τἀληθὲς εἰπεῖν, ἐχθροί. ἆρ’ οὖν, ὦ ἄνδρες Ἀθηναῖοι, καλὸν ἢ πρέπον ὑμῖν τοῦ μὲν εἵνεκα τῆς ἑαυτοῦ πλεονεξίας ἐπιβουλεύσοντος οἷς ἂν τύχῃ τοιαύτην φυλακὴν ἐψηφισμένους φαίνεσθαι, τοῖς δ’ ὑπὲρ τῆς ἑαυτῶν ἐλευθερίας ἀμυνουμένοις εἴργεσθαι τῆς ὑμετέρας συμμαχίας προειρηκέναι;", "st": "23.139"}, {"sp": "N", "t": "ἐγὼ μὲν οὐχ ὑπολαμβάνω τοῦτ’ οὔτε καλῶς ἔχειν οὔθ’ ὑμῶν ἀξίως. πῶς γὰρ οὐκ αἰσχρὸν Λακεδαιμονίοις μὲν ἐγκαλεῖν ὅτι τοὺς τὴν Ἀσίαν οἰκοῦντας Ἕλληνας ἔγραψαν ἐξεῖναι δρᾶσαι πᾶν ὅ τι ἂν θέλῃ βασιλεύς, αὐτοὺς δ’ ἐκδοῦναι καὶ τοὺς τὴν Εὐρώπην οἰκοῦντας Κερσοβλέπτῃ καὶ πάντας ὅσων περ ἂν οἴηται κρείττων Χαρίδημος ἔσεσθαι; οὐ γὰρ ἄλλο τι ποιεῖ τὸ ψήφισμα τουτί, ὅτε τῷ μὲν ἐκείνου στρατηγῷ οὐ διῄρηται τί πρακτέον ἢ μή, πᾶσι δέ, ἄν τις ἀμύνηται, τοσοῦτος ἐπήρτηται φόβος.", "st": "23.140"}, {"sp": "N", "t": "καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, καὶ γεγονός τι πρᾶγμα φράσαι πρὸς ὑμᾶς βούλομαι, δι’ οὗ μᾶλλον ἔθ’ ὑμῖν γενήσεται δῆλον ὡς σφόδρα δεῖ λῦσαι τὸ ψήφισμα τουτί. ὑμεῖς ἐποιήσασθ’ ἔν τισι καιροῖς καὶ χρόνοις Ἀριοβαρζάνην πολίτην καὶ δι’ ἐκεῖνον Φιλίσκον, ὥσπερ νῦν διὰ Κερσοβλέπτην Χαρίδημον. ὢν δ’ ὅμοιος ἐκεῖνος τούτῳ τῇ προαιρέσει τοῦ βίου, διὰ τῆς Ἀριοβαρζάνου δυνάμεως πόλεις κατελάμβανεν Ἑλληνίδας, εἰς ἃς εἰσιὼν πολλὰ καὶ δείν’ ἐποίει, παῖδας ἐλευθέρους ἀδικῶν καὶ γυναῖκας ὑβρίζων, καὶ πάντα ποιῶν ὅσ’ ἂν ἄνθρωπος ποιήσειεν ἄνευ νόμων καὶ τῶν ἐν πολιτείᾳ καλῶν τεθραμμένος εἰς ἐξουσίαν ἐλθών.", "st": "23.141"}, {"sp": "N", "t": "ἐν δὴ Λαμψάκῳ τινὲς ἄνθρωποι γίγνονται δύο· Θερσαγόρας ὄνομ’ αὐτῶν θατέρῳ, τῷ δ’ Ἐξήκεστος· οἳ παραπλήσια τοῖς παρ’ ἡμῖν γνόντες περὶ τῶν τυράννων ἀποκτιννύασι τὸν Φιλίσκον δικαίως, τὴν αὑτῶν πατρίδ’ οἰόμενοι δεῖν ἐλευθεροῦν. εἰ δὴ τῶν τόθ’ ὑπὲρ Φιλίσκου λεγόντων, ὅτ’ ἐμισθοδότει μὲν τοῖς ἐν Περίνθῳ ξένοις, εἶχεν δ’ ὅλον τὸν Ἑλλήσποντον, μέγιστος δ’ ἦν τῶν ὑπάρχων, ἔγραψέ τις ὥσπερ οὗτος νυνί, ἐάν τις ἀποκτείνῃ Φιλίσκον, ἀγώγιμον αὐτὸν ἐκ τῶν συμμάχων εἶναι, πρὸς Διὸς θεάσασθ’ εἰς ὅσην αἰσχύνην ἂν ἡ πόλις ἡμῶν ἐληλύθει.", "st": "23.142"}, {"sp": "N", "t": "ἧκε μὲν γὰρ ὁ Θερσαγόρας καὶ ὁ Ἐξήκεστος εἰς Λέσβον καὶ ᾤκουν ἐκεῖ· εἰ δ’ ἐφήπτετό τις τῶν Φιλίσκου φίλων ἢ παίδων, ἐξεδίδοντ’ ἂν ὑπὸ τοῦ ὑμετέρου ψηφίσματος. πῶς οὖν οὐκ αἰσχρὸν καὶ δεινὸν ἂν ἦτε πεποιηκότες, ἄνδρες Ἀθηναῖοι, εἰ τοὺς μὲν παρ’ ὑμῖν τοιοῦτό τι πράξαντας χαλκοῦς ἱστάντες καὶ ταῖς μεγίσταις δωρειαῖς τιμῶντες ἐφαίνεσθε, τοὺς δ’ ἑτέρωθί που τὴν αὐτὴν τούτοις διάνοιαν ὑπὲρ τῆς αὑτῶν πατρίδος ἔχοντας ἐκδότους εἶναι κατεψηφισμένοι; τοῦτο τοίνυν ἐπ’ ἐκείνου μέν, εὖ ποιοῦν, οὐ συνέβη φενακισθεῖσιν ὑμῖν αἰσχύνην ὀφλεῖν· ἐπὶ τούτου δέ, ἂν ἐμοὶ πίθησθε, φυλάξεσθε. μὴ γὰρ ὡρισμένου μηδενός, ἀλλ’ ἁπλῶς “ἄν τις ἀποκτείνῃ Χαρίδημον” γεγραμμένου, τάχ’ ἄν, εἰ τύχοι, καὶ τοιοῦτό τι συμβαίη.", "st": "23.143"}, {"sp": "N", "t": "βούλομαι τοίνυν ἤδη καὶ τὰ πεπραγμέν’ ἐξετάσαι τῷ Χαριδήμῳ διὰ βραχέων, καὶ δεῖξαι τὴν ὑπερβολὴν τῆς ἀναιδείας τῶν ἐπαινούντων αὐτόν. ἓν δ’ ὑμῖν ἐκεῖν’ ὑπισχνοῦμαι, καί μου μηδεὶς ἀχθεσθῇ τῇ ὑποσχέσει· οὐ μόνον ὑμῖν ἐπιδείξω τῆς φυλακῆς οὐκ ἄξιον ἣν γέγραφ’ οὗτος, ἀλλὰ καὶ δίκην δόντ’ ἂν δικαίως τὴν μεγίστην, εἴπερ οἱ κακόνοι καὶ φενακίζοντες ὑμᾶς καὶ διὰ παντὸς ἐναντία πράττοντες κολάζοιντ’ ἂν δικαίως.", "st": "23.144"}, {"sp": "N", "t": "ἴσως δέ τισιν λογιζομένοις ὑμῶν ὅτι πρῶτον μὲν πολίτης γέγον’ ἅνθρωπος, εἶτα πάλιν χρυσοῖς στεφάνοις ὡς εὐεργέτης ἐστεφάνωται, θαυμάζειν ἐπελήλυθεν εἰ τὰ τηλικαῦθ’ οὕτως ἐξηπάτησθε ῥᾳδίως. εὖ τοίνυν ἴστ’, ὦ ἄνδρες Ἀθηναῖοι, ὅτι ἐξηπάτησθε. καὶ δι’ ἅ γ’ εἰκότως τοῦτο πεπόνθατε, ἐγὼ πρὸς ὑμᾶς φράσω. ὅτι, ὦ ἄνδρες Ἀθηναῖοι, πολλὰ γιγνώσκοντες ὀρθῶς ὑμεῖς οὐ διὰ τέλους αὐτοῖς χρῆσθε.", "st": "23.145"}, {"sp": "N", "t": "οἷον τί λέγω; εἴ τις ὑμᾶς ἔροιτο τί πονηρότατον νομίζετε τῶν ἐν τῇ πόλει πάντων ἐθνῶν, οὔτε τοὺς γεωργοὺς οὔτε τοὺς ἐμπόρους οὔτε τοὺς ἐκ τῶν ἀργυρείων οὔτε τῶν τοιούτων οὐδὲν ἂν εἴποιτε, ἀλλ’ εἰ τοὺς ἐπὶ μισθῷ λέγειν καὶ γράφειν εἰωθότας εἴποι τις, εὖ οἶδ’ ὅτι συμφήσαιτ’ ἂν ἅπαντες. μέχρι μὲν δὴ τούτου καλῶς ἐγνώκατε, ἔπειτ’ οὐκέτ’ ὀρθῶς τὸ λοιπόν.", "st": "23.146"}, {"sp": "N", "t": "οὓς γὰρ αὐτοὶ πονηροτάτους νομίζετε πάντων, τούτοις περὶ τοῦ ποῖόν τιν’ ἕκαστον χρὴ νομίζειν πεπιστεύκατε· οἱ δ’ ὃν ἂν αὑτοῖς λυσιτελῇ, καὶ χρηστὸν καὶ πονηρὸν εἶναί φασιν, οὐχ ὃν ἂν ᾖ δίκαιον καὶ ἀληθές. ὅπερ πεποιήκασι τὸν Χαρίδημον τοῦτον οἱ ῥήτορες πάντα τὸν χρόνον, ὡς καὶ ὑμεῖς ὁμολογήσετε, ἐπειδὰν ἀκούσητέ μου τὰ πεπραγμέν’ αὐτῷ.", "st": "23.147"}, {"sp": "N", "t": "ὅσα μὲν δὴ στρατιώτης ὢν ἐν σφενδονήτου καὶ ψιλοῦ μέρει τὸ ἀπ’ ἀρχῆς ἐναντί’ ἐστράτευται τῇ πόλει, οὐ τίθημ’ ἐν ἀδικήματος μέρει, οὐδ’ ὅτι λῃστικόν ποτε πλοῖον ἔχων ἐλῄζετο τοὺς ὑμετέρους συμμάχους, ἀλλ’ ἐῶ ταῦτα. διὰ τί; ὅτι, ὦ ἄνδρες Ἀθηναῖοι, αἱ ἀναγκαῖαι χρεῖαι τοὺς τοῦ τί πρακτέον ἢ μὴ λογισμοὺς ἀναιροῦσιν ἅπαντας, ὥστ’ οὐ πάνυ ταῦτ’ ἀκριβολογεῖσθαι δεῖ τὸν δικαίως ἐξετάζοντα. ἀλλ’ ὅθεν ἀρξάμενος ξεναγῶν ἤδη καί τινων ἄρχων στρατιωτῶν κακῶς ὑμᾶς ἐποίει, ταῦτ’ ἀκούσατέ μου.", "st": "23.148"}, {"sp": "N", "t": "οὗτος ἓν μὲν ἁπάντων πρῶτον, μισθωθεὶς ὑπ’ Ἰφικράτους καὶ πλεῖν ἢ τρί’ ἔτη μισθοφορήσας παρ’ ἐκείνῳ, ἐπειδὴ τὸν μὲν Ἰφικράτην ἀποστράτηγον ἐποιήσατε, Τιμόθεον δ’ ἐπ’ Ἀμφίπολιν καὶ Χερρόνησον ἐξεπέμψατε στρατηγόν, πρῶτον μὲν τοὺς Ἀμφιπολιτῶν ὁμήρους, οὓς παρ’ Ἁρπάλου λαβὼν Ἰφικράτης ἔδωκε φυλάττειν αὐτῷ, ψηφισαμένων ὑμῶν ὡς ὑμᾶς κομίσαι παρέδωκεν Ἀμφιπολίταις· καὶ τοῦ μὴ λαβεῖν Ἀμφίπολιν τοῦτ’ ἐμποδὼν κατέστη. δεύτερον δέ, μισθουμένου Τιμοθέου πάλιν αὐτὸν καὶ τὸ στράτευμα, τούτῳ μὲν οὐ μισθοῖ, πρὸς δὲ Κότυν πλέων ᾤχετ’ ἔχων τὰς ὑμετέρας τριακοντόρους, ὃν ἀκριβῶς ᾔδει τῶν ὄντων ἀνθρώπων ἐχθρόταθ’ ὑμῖν διακείμενον.", "st": "23.149"}, {"sp": "N", "t": "καὶ μετὰ ταῦτα, ἐπειδὴ τὸν πρὸς Ἀμφίπολιν πόλεμον πρότερον πολεμεῖν εἵλετο Τιμόθεος τοῦ πρὸς Χερρόνησον, καὶ οὐδὲν εἶχε ποιεῖν ὑμᾶς ἐκεῖ κακόν, μισθοῖ πάλιν αὑτὸν Ὀλυνθίοις τοῖς ὑμετέροις ἐχθροῖς καὶ τοῖς ἔχουσιν Ἀμφίπολιν κατ’ ἐκεῖνον τὸν χρόνον. καὶ πλέων ἐκεῖσε, ἐκ Καρδίας ἀναχθείς, ἵνα τἀναντία τῇ πόλει πολεμῇ, ὑπὸ τῶν ἡμετέρων τριήρων ἑάλω. διὰ τὸν παρόντα δὲ καιρὸν καὶ τὸ δεῖν ξένων ἐπὶ τὸν πόλεμον τὸν ἐπ’ Ἀμφίπολιν, ἀντὶ τοῦ δίκην δοῦναι ὅτι οὐκ ἀπεδεδώκει τοὺς ὁμήρους καὶ διότι πρὸς Κότυν ἐχθρὸν ὄνθ’ ὑμῖν ηὐτομόλησεν ἔχων τὰς τριακοντόρους, πίστεις δοὺς καὶ λαβὼν ἐστράτευσε μεθ’ ὑμῶν.", "st": "23.150"}, {"sp": "N", "t": "ὧν δ’ ἐκεῖνον δίκαιον ἦν χάριν ὑμῖν ἔχειν οὐκ ἀπολωλότα, τοῦτο παθόντ’ ἂν δικαίως, ἀντὶ τούτων ὡς ὀφείλουσ’ ἡ πόλις αὐτῷ στεφάνους καὶ πολιτείαν καὶ ἃ πάντες ἐπίστασθε δέδωκεν. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, τό τε ψήφισμ’ ἀνάγνωθί μοι τὸ περὶ τῶν ὁμήρων, καὶ τὴν Ἰφικράτους ἐπιστολὴν καὶ τὴν Τιμοθέου, καὶ μετὰ ταῦτα τὴν μαρτυρίαν ταυτηνί· ὄψεσθε γὰρ οὐ λόγους οὐδ’ αἰτίαν, ἀλλ’ ἀλήθειαν οὖσαν ὧν λέγω. λέγε.", "st": "23.151"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ ΕΠΙΣΤΟΛΑΙ.", "st": "23.151"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν καὶ τὸ πρῶτον, οὗ πολεμεῖν ὑμῖν ᾤετο, ἐκεῖσ’ ἐμίσθωσεν αὑτὸν πολλαχόσ’ ἄλλοσε μισθῶσαι παρόν, καὶ μετὰ ταῦτα, ὡς οὐδὲν ἐκεῖ κακὸν εἶχε ποιεῖν ὑμᾶς, ἔπλει δεῦρο πάλιν οὗ τἀναντί’ ἔμελλε πράξειν τῇ πόλει, καὶ τοῦ μὴ λαβεῖν Ἀμφίπολιν πάντων οὗτος αἰτιώτατός ἐστιν, ἀκηκόατ’ ἐκ τῆς ἐπιστολῆς καὶ τῆς μαρτυρίας. καὶ τὰ μὲν πρῶτα τοιαῦτ’ ἐστὶν τῶν ἔργων τῶν Χαριδήμου, μετὰ ταῦτα δ’ ἄλλα θεάσασθε.", "st": "23.152"}, {"sp": "N", "t": "χρόνου γὰρ διελθόντος καὶ τοῦ πολέμου πρὸς Κότυν ὄντος ἤδη, πέμπει πρὸς ὑμᾶς ἐπιστολήν (μᾶλλον δ’ οὐχὶ πρὸς ὑμᾶς, ἀλλὰ πρὸς Κηφισόδοτον· οὕτω σφόδρ’ ὑπ’ αὐτοῦ γε οὐδ’ ἂν ἐξαπατηθῆναι τὴν πόλιν ἡγεῖτο, συνειδὼς ἃ πεποίηκεν) ἐν ᾗ Χερρόνησον ὑπέσχετο τῇ πόλει κομιεῖσθαι, πάντα τούτοις τἀναντί’ ἐγνωκὼς ποιεῖν. δεῖ δ’ ὑμᾶς τὸ πρᾶγμ’ οἷον ἦν τὸ περὶ τὴν ἐπιστολὴν ἀκοῦσαι (καὶ γάρ ἐστι βραχύ) καὶ θεωρῆσαι τὸν τρόπον τἀνθρώπου, ὡς ὑμῖν ἀπ’ ἀρχῆς κέχρηται.", "st": "23.153"}, {"sp": "N", "t": "ἐκεῖνος ὡς ἀπόμισθος γίγνεται παρὰ τοῦ Τιμοθέου τότε, ἀπ’ Ἀμφιπόλεως ἀναχωρῶν, διαβὰς εἰς τὴν Ἀσίαν, διὰ τὴν σύλληψιν τὴν Ἀρταβάζῳ συμβᾶσαν τόθ’ ὑπ’ Αὐτοφραδάτου μισθοῖ τὸ στράτευμα καὶ αὑτὸν τοῖς Ἀρταβάζου κηδεσταῖς, λαβὼν δὲ πίστεις καὶ δούς, ὀλιγωρήσας τῶν ὅρκων καὶ παραβὰς αὐτούς, ἀφυλάκτων ὄντων ὡς ἂν πρὸς φίλον τῶν ἐν τῇ χώρᾳ, καταλαμβάνει Σκῆψιν καὶ Κεβρῆνα καὶ Ἴλιον αὐτῶν.", "st": "23.154"}, {"sp": "N", "t": "ἐγκρατὴς δὲ τούτων γενόμενος τῶν χωρίων πρᾶγμ’ ἔπαθεν τοιοῦτον οἷον οὐχ ὅτι στρατηγὸς ἂν [ἠγνόησέ] τις εἶναι φάσκων, ἀλλ’ οὐδ’ ὁ τυχὼν ἄνθρωπος. οὐδ’ ὁτιοῦν γὰρ ἔχων χωρίον ἐπὶ θαλάττῃ, [οὐδ’] ὅθεν ἂν σιτοπομπίας ηὐπόρησε τοῖς στρατιώταις, οὐδ’ αὖ σῖτον ἔχων ἐν τοῖς χωρίοις, ὑπέμειν’ ἐν τοῖς τείχεσιν καὶ οὐ διαρπάσας ᾤχετο, ἐπειδή γ’ ἀδικεῖν ἔγνω. ὡς δὲ συλλέξας δύναμιν παρῆν ὁ Ἀρτάβαζος, ἀφειμένος παρὰ τοῦ Αὐτοφραδάτου, τῷ μὲν ὑπῆρχ’ ἐπισιτισμὸς ἐκ τῆς ἄνωθεν Φρυγίας καὶ Λυδίας καὶ Παφλαγονίας οἰκείας οὔσης, τῷ δ’ οὐδ’ ὁτιοῦν ἄλλο πλὴν πολιορκία περιειστήκει.", "st": "23.155"}, {"sp": "N", "t": "αἰσθόμενος δ’ οὗ ἦν κακοῦ καὶ λογισμὸν λαβὼν ὅτι ληφθήσεται, κἂν μηδενὶ τῶν ἄλλων, τῷ γε λιμῷ, εἶδεν, εἴτε δή τινος εἰπόντος εἴτ’ αὐτὸς συνείς, ὅτι σωτηρία μόνη γένοιτ’ ἂν αὐτῷ ἥπερ ἅπαντας ἀνθρώπους σῴζει. ἔστι δ’ αὕτη τίς; ἡ ὑμετέρα, ὦ ἄνδρες Ἀθηναῖοι, εἴτε χρὴ φιλανθρωπίαν λέγειν εἴθ’ ὅ τι δήποτε. γνοὺς δὲ τοῦτο πέμπει τὴν ἐπιστολὴν ὑμῖν, ἧς ἄξιόν ἐστιν ἀκοῦσαι, βουλόμενος διὰ τῆς ὑποσχέσεως τοῦ κομιεῖσθαι Χερρόνησον ὑμῖν, καὶ διὰ τοῦ τὸν Κηφισόδοτον δοκεῖν ἐχθρὸν ὄντα τοῦ Κότυος καὶ τοῦ Ἰφικράτους ταῦτα βούλεσθαι, τριήρων εὐπορήσας παρ’ ὑμῶν ἀσφαλῶς ἐκ τῆς Ἀσίας ἀποδρᾶναι.", "st": "23.156"}, {"sp": "N", "t": "τί δὴ συμβαίνει παραυτά, ὅθεν ἐξηλέγχθη τὸ πρᾶγμ’ ἐπ’ αὐτοφώρῳ; ὁ Μέμνων καὶ ὁ Μέντωρ, οἱ κηδεσταὶ τοῦ Ἀρταβάζου, ἄνθρωποι νέοι καὶ κεχρημένοι ἀπροσδοκήτῳ εὐτυχίᾳ τῇ τοῦ Ἀρταβάζου κηδείᾳ, βουλόμενοι τῆς χώρας ἄρχειν εὐθὺς ἐν εἰρήνῃ καὶ τιμᾶσθαι καὶ μὴ πολεμεῖν μηδὲ κινδυνεύειν, πείθουσι τὸν Ἀρτάβαζον τοῦ μὲν τιμωρεῖσθαι τὸν Χαρίδημον ἀφέσθαι, ἀποστεῖλαι δ’ ὑπόσπονδον, διδάσκοντες ὡς ὑμεῖς, κἂν ἐκεῖνος μὴ ’θέλῃ, διαβιβᾶτε καὶ οὐ δυνήσεται κωλύειν.", "st": "23.157"}, {"sp": "N", "t": "ὡς δὲ τυγχάνει ταύτης τῆς ἀλόγου καὶ ἀπροσδοκήτου σωτηρίας ὁ Χαρίδημος, διαβὰς εἰς τὴν Χερρόνησον ἐφ’ αὑτοῦ διὰ τὰς σπονδάς, τοσούτου ἐδέησεν ἐπελθεῖν τῷ Κότυϊ, γεγραφὼς ὅτι οὐχ ὑπομενεῖ Κότυς αὐτὸν ἐπιόντα, ἢ τὴν Χερρόνησον ὅπως κομιεῖσθ’ ὑμεῖς συμπρᾶξαι, ὥστε πάλιν μισθώσας αὑτὸν τῷ Κότυϊ τὰ ὑπόλοιπα τῶν ὑμετέρων χωρίων Κριθώτην καὶ Ἐλαιοῦντ’ ἐπολιόρκει. καὶ ὅτι ταῦτα, καὶ ἡνίκ’ ἔτ’ ἦν ἐν τῇ Ἀσίᾳ καὶ τὴν ἐπιστολὴν ἔπεμπε πρὸς ὑμᾶς, ἐγνωκὼς ποιεῖν ἐφενάκιζεν ὑμᾶς, ἀπὸ τῆς διαβάσεως ἣν ἐποιήσατο γνώσεσθε· ἐκ γὰρ Ἀβύδου τῆς τὸν ἅπαντα χρόνον ὑμῖν ἐχθρᾶς καὶ ὅθεν ἦσαν οἱ Σηστὸν καταλαβόντες, εἰς Σηστὸν διέβαινεν, ἣν εἶχε Κότυς.", "st": "23.158"}, {"sp": "N", "t": "καίτοι μὴ νομίζετε μήτ’ ἂν τοὺς Ἀβυδηνοὺς αὐτὸν ὑποδέχεσθαι μήτ’ ἂν τοὺς ἐν τῇ Σηστῷ, τῆς ἐπιστολῆς ὑμῖν ἐκείνης πεπεμμένης, εἰ μὴ συνῄδεσαν αὐτῷ φενακίζοντι τότε καὶ συνεξηπάτων αὐτοί, βουλόμενοι τοῦ μὲν διαβῆναι τὸ στράτευμ’ ὑμᾶς παρέχειν τὴν ἀσφάλειαν, διαβάντος δέ, ὅπερ συνέβη δόντος Ἀρταβάζου τὴν ἄδειαν, αὑτοῖς ὑπάρξαι τὴν χρείαν. ὅτι τοίνυν οὕτω ταῦτ’ ἔχει, λέγε τὰς ἐπιστολάς, ἥν τ’ ἔπεμψεν ἐκεῖνος καὶ τὰς παρὰ τῶν ἀρχόντων τῶν ἐκ Χερρονήσου· γνώσεσθε γὰρ ἐκ τούτων ὅτι ταῦθ’ οὕτως ἔχει. λέγε.", "st": "23.159"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.159"}, {"sp": "N", "t": "ἐνθυμεῖσθ’ ὅθεν οἷ διέβη, ἐξ Ἀβύδου εἰς Σηστόν. ἆρ’ οὖν οἴεσθ’ ἂν ὑποδέξασθαι τοὺς Ἀβυδηνοὺς ἢ τοὺς Σηστίους, εἰ μὴ συνεξηπάτων ὅτε τὴν πρὸς ὑμᾶς ἔπεμπεν ἐπιστολήν;", "st": "23.160"}, {"sp": "N", "t": "λέγ’ αὐτοῖς τὴν ἐπιστολὴν αὐτήν. καὶ θεωρεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, τὰς ὑπερβολὰς ὧν αὐτὸς περὶ αὑτοῦ πρὸς ὑμᾶς ἔγραψεν ἐπαίνων, [καὶ] τὰ μὲν ὡς πεποίηκε λέγων, τὰ δ’ ὑπισχνούμενος ποιήσειν. λέγε.", "st": "23.160"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.160"}, {"sp": "N", "t": "καλά γ’, οὐ γάρ; ὦ ἄνδρες Ἀθηναῖοι, τὰ γεγραμμένα καὶ χάριτος πολλῆς ἄξια, εἴ γ’ ἦν ἀληθῆ. νῦν δέ, ὅτε μὲν τῶν σπονδῶν οὐκ ᾤετο τεύξεσθαι, ταῦτ’ ἔγραφ’ ἐξαπατῶν· ἐπειδὴ δ’ ἔτυχεν, λέγ’ οἷ’ ἐποίησεν.", "st": "23.161"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.161"}, {"sp": "N", "t": "οὐκοῦν τοῦ κομιεῖσθαι τἀπολωλότα χωρί’ ὑποσχομένου [Χαριδήμου] διαβάντος φησὶν ὁ ἄρχων Κριθώτης περὶ τῶν ὑπαρχόντων γεγενῆσθαι μείζους τῶν πρότερον τοὺς κινδύνους. λέγ’ ἐξ ἑτέρας ἐπιστολῆς ἐπιδείξας.", "st": "23.161"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.161"}, {"sp": "N", "t": "λέγ’ ἐξ ἑτέρας.", "st": "23.161"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.161"}, {"sp": "N", "t": "ὁρᾶθ’ ὅτι πανταχόθεν τὸ πρᾶγμα μαρτυρεῖται, ὅτι διαβὰς οὐκ ἐπὶ τὸν Κότυν, ἀλλ’ ἐφ’ ἡμᾶς μετ’ ἐκείνου ἐπορεύετο. ἔτι τοίνυν ταύτην μόνην ἀνάγνωθί μοι τὴν ἐπιστολήν, τὰς δ’ ἄλλας ἔα· δῆλον γάρ που [ὑμῖν] γέγον’ ὡς πεφενάκικεν ὑμᾶς. λέγε.", "st": "23.162"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.162"}, {"sp": "N", "t": "ἐπίσχες. ἐνθυμεῖσθ’ ὅτι γράψας μὲν ὡς ἀποδώσει Χερρόνησον, τὰ λοίπ’ ἀφελέσθαι μισθώσας αὑτὸν τοῖς ὑμετέροις ἐχθροῖς ἐπεχείρει, γράψας δ’ ὡς Ἀλεξάνδρου πρεσβευσαμένου πρὸς αὐτὸν οὐ προσεδέξατο, τοῖς λῃσταῖς φαίνεται τοῖς παρ’ ἐκείνου ταὐτὰ πράττων. εὔνους γ’, οὐ γάρ; ἁπλῶς ὑμῖν, καὶ οὐδὲν ἂν ἐπιστείλας ψεῦδος οὐδ’ ἐξαπατήσας.", "st": "23.162"}, {"sp": "N", "t": "οὐ τοίνυν ἐκ τούτων πω δῆλόν ἐσθ’, οὕτω σαφῶς δῆλον ὄν, ὡς οὐδὲν πιστόν ἐσθ’ ὧν ἐκεῖνός φησιν [προσποιεῖται] τῇ πόλει προσέχειν, ἀλλ’ ἐκ τῶν μετὰ ταῦτα συμβάντων ἔσται φανερώτερον. τὸν μὲν γὰρ Κότυν, εὖ ποιῶν, ὄντα γ’ ἐχθρὸν ὑμῖν καὶ πονηρὸν ἀποκτίννυσιν ὁ Πύθων, ὁ δὲ Κερσοβλέπτης ὁ νυνὶ βασιλεύων μειρακύλλιον ἦν καὶ πάντες οἱ τοῦ Κότυος παῖδες, τῶν δὲ πραγμάτων κύριος διὰ τὴν παρουσίαν καὶ τὸ δύναμιν ἔχειν ὁ Χαρίδημος ἐγεγόνει, ἧκε δὲ Κηφισόδοτος στρατηγῶν, πρὸς ὃν αὐτὸς ἔπεμψε τὴν ἐπιστολὴν ἐκείνην, καὶ αἱ τριήρεις, αἵ, ὅτ’ ἦν ἄδηλα τὰ τῆς σωτηρίας αὐτῷ, καὶ μὴ συγχωροῦντος Ἀρταβάζου σῴζειν ἔμελλον αὐτόν.", "st": "23.163"}, {"sp": "N", "t": "τί δὴ προσῆκεν, ὦ ἄνδρες Ἀθηναῖοι, τὸν ὡς ἀληθῶς ἁπλοῦν καὶ φίλον, παρόντος μὲν στρατηγοῦ οὐχ ὧν ἐκεῖνος ἔφησεν ἂν αὑτῷ φθονεῖν οὐδενός, ἀλλ’ ὃν αὐτὸς ἑαυτοῦ φίλον προείλετο τῶν παρ’ ὑμῖν, καὶ πρὸς ὃν τὴν ἐπιστολὴν ἐπεπόμφει, τετελευτηκότος δὲ Κότυος, κύριον δ’ ὄντα τῶν πραγμάτων; οὐκ ἀποδοῦναι μὲν τὴν χώραν εὐθέως ὑμῖν, κοινῇ δὲ μεθ’ ὑμῶν καθιστάναι τὸν βασιλέα τῆς Θρᾴκης, δηλῶσαι δ’ ὡς εἶχεν εὐνοϊκῶς ὑμῖν, καιροῦ τοιούτου λαβόμενον;", "st": "23.164"}, {"sp": "N", "t": "ἔγωγ’ ἂν φαίην. ἆρ’ οὖν ἐποίησέ τι τούτων; πολλοῦ γε δεῖ. ἀλλὰ τὸν μὲν ἅπαντα χρόνον μῆνας ἑπτὰ διήγαγεν ἡμᾶς πολεμῶν, ἐκ προφανοῦς ἐχθρὸς ὢν καὶ οὐδὲ λόγον φιλάνθρωπον διδούς. καὶ κατ’ ἀρχὰς μὲν ἡμῶν δέκα ναυσὶ μόναις εἰς Πέρινθον ὁρμισαμένων, ἀκηκοότων ὅτι πλησίον ἐστὶν ἐκεῖνος, ὅπως συμμείξαιμεν αὐτῷ καὶ περὶ τούτων εἰς λόγους ἔλθοιμεν, ἀριστοποιουμένους φυλάξας τοὺς στρατιώτας ἐπεχείρησε μὲν ἡμῶν τὰ σκάφη λαβεῖν, πολλοὺς δ’ ἀπέκτεινε τῶν ναυτῶν, κατήραξε δ’ εἰς τὴν θάλατταν ἅπαντας, ἱππέας ἔχων καὶ ψιλούς τινας.", "st": "23.165"}, {"sp": "N", "t": "μετὰ ταῦτα δὲ πλευσάντων ἡμῶν—οὐκ ἐπὶ τῆς Θρᾴκης τόπον οὐδέν’ οὐδὲ χωρίον· οὐδὲ γὰρ τοῦτό γ’ ἂν εἴποι τις “νὴ Δί’, ἀμυνόμενος γὰρ ὑπὲρ τοῦ μὴ παθεῖν ἐποίει τι κακόν”· οὐκ ἔστι τοῦτο· οὐ γὰρ ἤλθομεν οὐδαμοῖ τῆς Θρᾴκης, ἀλλ’ ἐπ’ Ἀλωπεκόννησον, ἣ Χερρονήσου μέν ἐστι καὶ ἦν ὑμετέρα, ἀκρωτήριον δ’ ἀνέχον πρὸς τὴν Ἴμβρον ἀπωτάτω τῆς Θρᾴκης, λῃστῶν δ’ ἦν μεστὴ καὶ καταποντιστῶν—", "st": "23.166"}, {"sp": "N", "t": "ἐνταῦθα δ’ ἐλθόντων ἡμῶν καὶ πολιορκούντων τούτους, πορευθεὶς διὰ Χερρονήσου πάσης τῆς ὑμετέρας ἡμῖν μὲν προσέβαλλεν, ἐβοήθει δὲ τοῖς λῃσταῖς καὶ καταποντισταῖς. καὶ πρότερον προσκαθήμενος τὸν ὑμέτερον στρατηγὸν ἔπεισε καὶ ἠνάγκασε μὴ τὰ βέλτισθ’ ὑπὲρ ὑμῶν πράττειν, ἢ αὐτὸς [ὑπὸ τούτου] ἐπείσθη ὧν ὡμολογήκει καὶ ὑπέσχητό τι πρᾶξαι, καὶ γράφει δὴ τὰς συνθήκας ταύτας τὰς πρὸς Κηφισόδοτον, ἐφ’ αἷς ὑμεῖς οὕτως ἠγανακτήσατε καὶ χαλεπῶς ἠνέγκατε, ὥστ’ ἀπεχειροτονήσατε μὲν τὸν στρατηγόν, πέντε ταλάντοις δ’ ἐζημιώσατε, τρεῖς δὲ μόναι ψῆφοι διήνεγκαν τὸ μὴ θανάτου τιμῆσαι.", "st": "23.167"}, {"sp": "N", "t": "καίτοι πηλίκην τινὰ χρὴ νομίζειν, ὦ ἄνδρες Ἀθηναῖοι, ταύτην [τὴν] ἀλογίαν, ὅταν τις ἴδῃ διὰ τὰς αὐτὰς πράξεις τὸν μὲν ὡς ἀδικοῦντα κολασθέντα πικρῶς οὕτως, τὸν δ’ ὡς εὐεργέτην ἔτι καὶ νῦν τιμώμενον; ὅτι τοίνυν ταῦτ’ ἀληθῆ λέγω, τῶν μὲν τῷ στρατηγῷ συμβάντων δήπου μάρτυρες ὑμεῖς ἐστέ μοι· καὶ γὰρ ἐκρίνεθ’ ὑμεῖς καὶ ἀπεχειροτονεῖτε καὶ ὠργίζεσθε, καὶ πάντα ταῦτα σύνισθ’ ὑμεῖς· τῶν δ’ ἐν Περίνθῳ καὶ τῶν ἐν Ἀλωπεκοννήσῳ κάλει μοι τοὺς τριηράρχους μάρτυρας.", "st": "23.168"}, {"sp": "N", "t": "ΜΑΡΤΥΡΕΣ.", "st": "23.168"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν, ἐπειδὴ Κηφισόδοτος μὲν ἀπηλλάγη τοῦ στρατηγεῖν, ὑμῖν δ’ οὐκ ἐδόκουν καλῶς ἔχειν οὐδὲ δικαίως αἱ πρὸς ἐκεῖνον γραφεῖσαι συνθῆκαι, τὸν μὲν Μιλτοκύθην, τὸν διὰ παντὸς εὔνουν ὑμῖν τοῦ χρόνου, λαβὼν προδοθένθ’ ὑπὸ τοῦ Σμικυθίωνος ὁ χρηστὸς οὗτος Χαρίδημος, οὐκ ὄντος νομίμου τοῖς Θρᾳξὶν ἀλλήλους ἀποκτιννύναι, γνοὺς ὅτι σωθήσεται πρὸς Κερσοβλέπτην ἂν ἀχθῇ, παραδίδωσι Καρδιανοῖς τοῖς ὑμετέροις ἐχθροῖς. κἀκεῖνοι λαβόντες καὶ αὐτὸν καὶ τὸν υἱόν, ἀναγαγόντες εἰς τὸ πέλαγος ἐν πλοίῳ, τὸν μὲν υἱὸν ἀπέσφαξαν, ἐκεῖνον δ’ ἐπιδόντα τὸν υἱὸν ἀποσφαττόμενον κατεπόντισαν.", "st": "23.169"}, {"sp": "N", "t": "τῶν δὲ Θρᾳκῶν ἁπάντων χαλεπῶς ἐνεγκόντων ἐπὶ τούτοις, καὶ συστραφέντων τοῦ τε Βηρισάδου καὶ τοῦ Ἀμαδόκου, ἰδὼν τὸν καιρὸν τοῦτον Ἀθηνόδωρος, συμμαχίαν ποιησάμενος πρὸς τούτους οἷος ἦν πολεμεῖν. ἐν φόβῳ δὲ καταστάντος τοῦ Κερσοβλέπτου γράφει ὁ Ἀθηνόδωρος συνθήκας, καθ’ ἃς ἀναγκάζει τὸν Κερσοβλέπτην ὀμόσαι πρός θ’ ὑμᾶς καὶ τοὺς βασιλέας εἶναι μὲν τὴν ἀρχὴν κοινὴν τῆς Θρᾴκης εἰς τρεῖς διῃρημένην, πάντας δ’ ὑμῖν ἀποδοῦναι τὴν χώραν.", "st": "23.170"}, {"sp": "N", "t": "ὡς δ’ ἐν ἀρχαιρεσίαις ὑμεῖς Χαβρίαν ἐπὶ τὸν πόλεμον τοῦτον κατεστήσατε, καὶ τῷ μὲν Ἀθηνοδώρῳ συνέβη διαφεῖναι τὴν δύναμιν χρήματ’ οὐκ ἔχοντι παρ’ ὑμῶν οὐδ’ ἀφορμὴν τῷ πολέμῳ, τῷ Χαβρίᾳ δὲ μίαν ναῦν ἔχοντι μόνην ἐκπλεῖν, τί ποιεῖ πάλιν οὗτος ὁ Χαρίδημος; ἃς μὲν ὤμοσε πρὸς τὸν Ἀθηνόδωρον συνθήκας ἔξαρνος γίγνεται καὶ τὸν Κερσοβλέπτην ἀρνεῖσθαι πείθει, γράφει δ’ ἑτέρας πρὸς τὸν Χαβρίαν ἔτι τῶν πρὸς Κηφισόδοτον δεινοτέρας· οὐκ ἔχων δ’ ἐκεῖνος, οἶμαι, δύναμιν στέργειν ἠναγκάζετο τούτοις.", "st": "23.171"}, {"sp": "N", "t": "ἀκούσαντες δ’ ὑμεῖς ταῦτα, ἐν τῷ δήμῳ λόγων ῥηθέντων πολλῶν καὶ τῶν συνθηκῶν ἀναγνωσθεισῶν, οὔτε τὴν Χαβρίου δόξαν αἰσχυνθέντες οὔτε τῶν συναγορευόντων οὐδένα, ἀπεχειροτονήσατε καὶ ταύτας πάλιν τὰς συνθήκας, καὶ ψηφίζεσθε ψήφισμα Γλαύκωνος εἰπόντος ἑλέσθαι πρέσβεις δέκ’ ἄνδρας ἐξ ὑμῶν αὐτῶν, τούτους δέ, ἂν μὲν ἐμμένῃ ταῖς πρὸς Ἀθηνόδωρον συνθήκαις, ὁρκίσαι πάλιν αὐτόν, εἰ δὲ μή, παρὰ μὲν τοῖν δυοῖν βασιλέοιν ἀπολαβεῖν τοὺς ὅρκους, πρὸς δ’ ἐκεῖνον ὅπως πολεμήσετε βουλεύεσθαι.", "st": "23.172"}, {"sp": "N", "t": "ἐκπεπλευκότων δὲ τῶν πρέσβεων συμβαίνει τοῖς χρόνοις εἰς τοῦθ’ ὑπηγμένα τὰ πράγματ’ ἤδη, διατριβόντων τούτων καὶ οὐδὲν ἁπλοῦν οὐδὲ δίκαιον ὑμῖν ἐθελόντων πρᾶξαι, ὥστ’ ἐβοηθοῦμεν εἰς Εὔβοιαν, καὶ Χάρης ἧκεν ἔχων τοὺς ξένους, καὶ στρατηγὸς ὑφ’ ὑμῶν αὐτοκράτωρ εἰς Χερρόνησον ἐξέπλει. οὕτω γράφει πάλιν συνθήκας πρὸς τὸν Χάρητα, παραγενομένου Ἀθηνοδώρου καὶ τῶν βασιλέων, ταύτας αἵπερ εἰσὶν ἄρισται καὶ δικαιόταται. καὶ ἔργῳ ἑαυτὸν ἐξήλεγξεν ὅτι καιροφυλακεῖ τὴν πόλιν ἡμῶν, καὶ οὐδὲν ἁπλοῦν ἔγνωκε ποιεῖν οὐδ’ ἴσον.", "st": "23.173"}, {"sp": "N", "t": "εἶθ’ ὃν ὁρᾶτ’ ἐκ προσαγωγῆς ὑμῖν φίλον, καὶ ὅπως ἂν ὑμᾶς δύνασθαι νομίσῃ, οὕτω πρὸς ὑμᾶς εὐνοίας ἔχοντα, τοῦτον οἴεσθε δεῖν ἰσχυρόν ποτ’ ἐᾶσαι γενέσθαι, καὶ ταῦτα δι’ ὑμῶν; οὐκ ἄρ’ ὀρθῶς ἐγνώκατε. ἵνα τοίνυν εἰδῆθ’ ὅτι τἀληθῆ λέγω, λαβέ μοι τὴν ἐπιστολὴν ἣ μετὰ τὰς πρώτας συνθήκας ἦλθεν, εἶτα τὴν παρὰ Βηρισάδου· μάλιστα γὰρ οὕτω γνώσεσθε διδασκόμενοι.", "st": "23.174"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.174"}, {"sp": "N", "t": "λέγε καὶ τὴν ἐπιστολὴν τὴν τοῦ Βηρισάδου.", "st": "23.174"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.174"}, {"sp": "N", "t": "ἡ μὲν τοίνυν συμμαχία τοῖς βασιλεῦσι [τοῖν δυοῖν] τοῦτον τὸν τρόπον μετὰ τὴν παράκρουσιν τὴν διὰ τῶν πρὸς Κηφισόδοτον συνθηκῶν συνεστάθη, ἤδη Μιλτοκύθου μὲν ἀνῃρημένου, Χαριδήμου δ’ ἔργῳ φανεροῦ γεγενημένου ὅτι τῆς πόλεως ἐχθρός ἐστιν. ὃς γὰρ ὃν ᾔδει διὰ παντὸς τοῦ χρόνου πάντων τῶν Θρᾳκῶν εὐνούστατον ὄνθ’ ὑμῖν, τοῦτον ἠξίωσ’ ὑποχείριον λαβὼν τοῖς ὑμετέροις ἐχθροῖς Καρδιανοῖς ἐγχειρίσαι, πῶς οὐ μεγάλης ἔχθρας δεῖγμα πρὸς ὑμᾶς ἐξέφερεν; ἃς δὴ τὸν πόλεμον δεδιὼς τὸν πρὸς τοὺς Θρᾷκας καὶ πρὸς Ἀθηνόδωρον ἐποιήσατο συνθήκας μετὰ ταῦθ’ ὁ Κερσοβλέπτης, λέγε.", "st": "23.175"}, {"sp": "N", "t": "ΣΥΝΘΗΚΑΙ.", "st": "23.175"}, {"sp": "N", "t": "ταῦτα τοίνυν γράψας καὶ συνθέμενος, καὶ τὸν ὅρκον ὃν ἠκούσαθ’ ὑμεῖς ὀμόσας, ἐπειδὴ τὴν μὲν Ἀθηνοδώρου δύναμιν διαφειμένην εἶδεν, μιᾷ δὲ μόνον τριήρει Χαβρίαν ἥκοντα, οὔτε τὸν Ἰφιάδου παρέδωκεν υἱὸν [ὑμῖν] οὔτ’ ἄλλ’ οὐδὲν ὧν ὤμοσ’ ἐποίησεν, ἀλλὰ καὶ περὶ τῶν ἄλλων τῶν γεγραμμένων ἐν ταῖς συνθήκαις ἔξαρνος γίγνεται, καὶ γράφει ταύτας τὰς συνθήκας. λαβέ μοι καὶ λέγε ταυτασί.", "st": "23.176"}, {"sp": "N", "t": "ΣΥΝΘΗΚΑΙ.", "st": "23.176"}, {"sp": "N", "t": "ἐνθυμεῖσθ’ ὅτι καὶ τέλη καὶ δεκάτας ἠξίου λαμβάνειν, καὶ πάλιν ὡς αὑτοῦ τῆς χώρας οὔσης τοὺς λόγους ἐποιεῖτο, τοὺς δεκατηλόγους ἀξιῶν τοὺς αὑτοῦ τῶν τελῶν κυρίους εἶναι, καὶ τὸν ὅμηρον τὸν υἱὸν τὸν Ἰφιάδου, ὃν ὑπὲρ Σηστοῦ ἔχων ὤμοσε πρὸς τὸν Ἀθηνόδωρον παραδώσειν, οὐδ’ ὑπισχνεῖται παραδώσειν ἔτι. λαβὲ τὸ ψήφισμ’ ὃ πρὸς ταῦθ’ ὑμεῖς ἐψηφίσασθε. λέγε.", "st": "23.177"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "23.177"}, {"sp": "N", "t": "ἐλθόντων τοίνυν μετὰ ταῦτα τῶν πρέσβεων εἰς Θρᾴκην, ὁ μὲν Κερσοβλέπτης ὑμῖν ἐπιστέλλει ταυτί, καὶ οὐδ’ ὁτιοῦν ὡμολόγει δίκαιον, οἱ δ’ ἕτεροι ταυτί. λέγ’ αὐτοῖς.", "st": "23.178"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.178"}, {"sp": "N", "t": "λέγε δὴ τὴν παρὰ τῶν βασιλέων. καὶ σκοπεῖτ’ εἰ ἄρ’ ὑμῖν δοκοῦσι μηδὲν ἐγκαλεῖν.", "st": "23.178"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.178"}, {"sp": "N", "t": "ὁρᾶτε καὶ συνίετ’, ὦ ἄνδρες Ἀθηναῖοι, τὴν πονηρίαν καὶ τὴν ἀπιστίαν, ὡς ἄνω καὶ κάτω. τὸ πρῶτον ἠδίκει Κηφισόδοτον, πάλιν φοβηθεὶς Ἀθηνόδωρον ἐπαύσατο· αὖθις ἠδίκει Χαβρίαν, πάλιν ὡμολόγει Χάρητι. πάντ’ ἄνω καὶ κάτω [πεποίηκεν], καὶ οὐδὲν ἁπλῶς οὐδὲ δικαίως ἔπραξεν.", "st": "23.178"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν ὅσον μὲν χρόνον ἡ ὑμετέρα δύναμις παρῆν ἐν Ἑλλησπόντῳ, κολακεύων καὶ φενακίζων ὑμᾶς διαγέγονεν· ἐπεὶ δ’ εἶδε τάχιστα τὸν Ἑλλήσποντον ἔρημον δυνάμεως, εὐθὺς ἐνεχείρει καταλύειν καὶ ἀπαλλάξαι τοὺς δύο [τῆς ἀρχῆς] καὶ πᾶσαν ὑφ’ ἑαυτῷ ποιήσασθαι τὴν ἀρχήν, ἔργῳ πεῖραν ἔχων ὅτι τῶν πρὸς ὑμᾶς οὐδὲν μὴ δυνηθῇ πρότερον λῦσαι, πρὶν ἂν ἐκβάλῃ τούτους.", "st": "23.179"}, {"sp": "N", "t": "ἵνα δ’ ὡς ῥᾷστα τοῦτο περάνειε, ψήφισμα τοιοῦτο παρ’ ὑμῶν εὕρετο ἐξ οὗ κυρωθέντος ἄν, εἰ μὴ δι’ ἡμᾶς καὶ ταύτην τὴν γραφήν, ἠδίκηντο μὲν φανερῶς οἱ δύο τῶν βασιλέων, ἡσυχίαν δ’ ἂν ἦγον οἱ στρατηγοῦντες αὐτοῖς, ὁ Βιάνωρ, ὁ Σίμων, ὁ Ἀθηνόδωρος, φοβούμενοι τὴν διὰ τοῦ ψηφίσματος συκοφαντίαν, ὁ δὲ ταύτης τῆς ἐξουσίας ἀπολαύσας καὶ πᾶσαν ὑφ’ αὑτῷ λαβὼν τὴν ἀρχὴν ἰσχυρὸς ἂν ἐχθρὸς ὑπῆρχεν ὑμῖν.", "st": "23.180"}, {"sp": "N", "t": "ἔχει δ’ ὁρμητήριον παρὰ πάντα τὸν χρόνον αὑτῷ τετηρημένον τὴν Καρδιανῶν πόλιν, ἣν ἐν ἁπάσαις μὲν ταῖς συνθήκαις ἐξαίρετον αὑτῷ γέγραφεν, τὸ τελευταῖον δὲ καὶ φανερῶς αὐτὴν ἀφείλετο παρ’ ὑμῶν. καίτοι τοῖς ἀπηλλαγμένοις μὲν τοῦ περὶ ἡμῶν τι φρονεῖν ἄδικον, μετὰ πάσης δ’ ἀληθείας ἁπλῶς εὐνοεῖν ἡμῖν ᾑρημένοις τί προσῆκεν αὑτοῖς ὁρμητήριον καταλείπειν χρήσιμον τοῦ πρὸς ἡμᾶς πολέμου;", "st": "23.181"}, {"sp": "N", "t": "ἴστε γὰρ δήπου τοῦτο, οἱ μὲν ἀφιγμένοι σαφῶς, οἱ δ’ ἄλλοι τούτων ἀκούοντες, ὅτι τῆς Καρδιανῶν πόλεως ἐχούσης ὡς ἔχει, εἰ γενήσεται τὰ πρὸς τοὺς Θρᾷκας εὐτρεπῆ τῷ Κερσοβλέπτῃ, παρ’ ἡμέραν ἔξεστιν αὐτῷ βαδίζειν ἐπὶ Χερρόνησον ἀσφαλῶς. ὥσπερ γὰρ Χαλκὶς τῷ τόπῳ τῆς Εὐβοίας πρὸς τῆς Βοιωτίας κεῖται, οὕτω Χερρονήσου κεῖται πρὸς τῆς Θρᾴκης ἡ Καρδιανῶν πόλις. ἣν ὃν ἔχει τόπον ὅστις οἶδεν ὑμῶν, οὐδ’ ἐκεῖν’ ἀγνοεῖ, τίνος εἵνεκα καιροῦ περιπεποίηται καὶ διεσπούδασται μὴ λαβεῖν ὑμᾶς.", "st": "23.182"}, {"sp": "N", "t": "ὃν οὐ συμπαρασκευάσαι καθ’ ὑμῶν αὐτῶν ὀφείλετε, ἀλλὰ κωλῦσαι καθ’ ὅσον δυνατὸν καὶ σκοπεῖν ὅπως μὴ γενήσεται, ἐπεὶ ὅτι γ’ οὐδ’ ἂν ὁντινοῦν καιρὸν παρείη, δεδήλωκεν. Φιλίππου γὰρ εἰς Μαρώνειαν ἐλθόντος ἔπεμψεν πρὸς αὐτὸν Ἀπολλωνίδην, πίστεις δοὺς ἐκείνῳ καὶ Παμμένει· καὶ εἰ μὴ κρατῶν τῆς χώρας Ἀμάδοκος ἀπεῖπε Φιλίππῳ μὴ ἐπιβαίνειν, οὐδὲν ἂν ἦν ἐν μέσῳ πολεμεῖν ἡμᾶς πρὸς Καρδιανοὺς ἤδη καὶ Κερσοβλέπτην. καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, λαβὲ τὴν Χάρητος ἐπιστολήν.", "st": "23.183"}, {"sp": "N", "t": "ΕΠΙΣΤΟΛΗ.", "st": "23.183"}, {"sp": "N", "t": "ταῦτα μέντοι δεῖ σκοπουμένους ἀπιστεῖν καὶ μὴ τετυφῶσθαι, μηδ’ ὡς εὐεργέτῃ προσέχειν τὸν νοῦν. οὐ γὰρ ὧν ἀναγκαζόμενος φίλος εἶναί φησι φενακίζων ὑμᾶς, χάριν ἐστὶ δίκαιον ὀφείλειν [Κερσοβλέπτῃ], οὐδ’ ὧν μίκρ’ ἀναλίσκων ἰδίᾳ καὶ τοῖς στρατηγοῖς καὶ τοῖς ῥήτορσιν [Χαρίδημος] διαπράττεται πρὸς ὑμᾶς ἐπαίνους αὑτοῦ γράφεσθαι· ἀλλ’ ὧν, ὁσαχοῦ κύριος γέγονεν τοῦ πράττειν ὅ τι βούλεται, πανταχοῦ κακῶς ἐπιχειρῶν ἡμᾶς ποιεῖν φαίνεται, τούτων πολὺ μᾶλλον ὀργίζεσθαι προσήκει.", "st": "23.184"}, {"sp": "N", "t": "οἱ μὲν τοίνυν ἄλλοι πάντες, ὅσοι τι παρ’ ὑμῶν εὕρηνται πώποτε, ἐφ’ οἷς εὖ πεποιήκασιν ὑμᾶς τετίμηνται, οὗτος δ’ εἷς ἁπάντων τῶν ἄλλων μόνος ἐφ’ οἷς ἐγχειρῶν οὐ δεδύνηται κακῶς ποιῆσαι. καίτοι τῷ τοιούτῳ τὸ δίκης, ἣν ἔδωκε δικαίως ἄν, ἀφεῖσθαι, μεγάλη δωρειὰ παρ’ ὑμῶν ἦν. ἀλλ’ οὐ ταῦτα δοκεῖ τοῖς ῥήτορσιν, ἀλλὰ πολίτης, εὐεργέτης, στέφανοι, δωρειαί, δι’ ἃ τούτοις ἰδίᾳ δίδωσιν· οἱ δ’ ἄλλοι πεφενακισμένοι κάθησθε, τὰ πράγματα θαυμάζοντες.", "st": "23.185"}, {"sp": "N", "t": "τὸ τελευταῖον δὲ νυνὶ κἂν φύλακας κατέστησαν ὑμᾶς ἐκείνου διὰ τοῦ προβουλεύματος τούτου, εἰ μὴ τὴν γραφὴν ἐποιησάμεθ’ ἡμεῖς ταυτηνί, καὶ τὸ τοῦ μισθοφόρου καὶ θεραπεύοντος ἐκεῖνον ἔργον ἡ πόλις ἂν διεπράττετο, ἐφρούρει Χαρίδημον. καλόν γ’, οὐ γάρ; ὦ Ζεῦ καὶ θεοί, ὃς αὐτός ποτε τοὺς ὑμετέρους ἐχθροὺς μισθὸν λαμβάνων ἐδορυφόρει, τοῦτον ὑφ’ ὑμετέρου ψηφίσματος φανῆναι φυλαττόμενον.", "st": "23.186"}, {"sp": "N", "t": "ἴσως τοίνυν ἐκεῖν’ ἄν τίς μ’ ἔροιτο, τί δήποτε ταῦτ’ εἰδὼς οὕτως ἀκριβῶς ἐγὼ καὶ παρηκολουθηκὼς ἐνίοις τῶν ἀδικημάτων εἴασα, καὶ οὔθ’ ὅτ’ αὐτὸν ἐποιεῖσθε πολίτην οὐδὲν ἀντεῖπον, οὔθ’ ὅτ’ ἐπῃνεῖτε, οὔθ’ ὅλως πρότερον, πρὶν τὸ ψήφισμα τουτὶ γενέσθαι, λόγον οὐδέν’ ἐποιησάμην. ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, πρὸς ὑμᾶς ἅπασαν ἐρῶ τὴν ἀλήθειαν. καὶ γὰρ ὡς ἀνάξιος ἦν ᾔδειν, καὶ παρῆν ὅτε τούτων ἠξιοῦτο, καὶ οὐκ ἀντεῖπον· ὁμολογῶ.", "st": "23.187"}, {"sp": "N", "t": "διὰ τί; ὅτι, ὦ ἄνδρες Ἀθηναῖοι, πρῶτον μὲν ἀσθενέστερον ἡγούμην ἔσεσθαι πολλῶν ψευδομένων ἑτοίμως περὶ αὐτοῦ πρὸς ὑμᾶς ἕνα τἀληθῆ λέγοντ’ ἐμαυτόν· ἔπειθ’ ὧν μὲν ἐκεῖνος εὑρίσκετ’ ἐξαπατῶν ὑμᾶς, μὰ τὸν Δία καὶ θεοὺς πάντας οὐδενὸς εἰσῄει μοι φθονεῖν, κακὸν δ’ οὐδὲν ἑώρων ὑπερφυὲς πεισομένους ὑμᾶς, εἴ τιν’ ἠδικηκότα πόλλ’ ἀφίετε καὶ προὐκαλεῖσθέ τι τοῦ λοιποῦ ποιεῖν ὑμᾶς ἀγαθόν· ἐν γὰρ τῷ πολίτην ποιεῖσθαι καὶ στεφανοῦν ταῦτ’ ἐνῆν ἀμφότερα.", "st": "23.188"}, {"sp": "N", "t": "ἐπειδὴ δ’ ὁρῶ προσκατασκευαζόμενόν τι τοιοῦτον δι’ οὗ, ἂν μόνον εὐτρεπίσηται τοὺς ἐνθάδ’ ἐξαπατήσοντας ὑμᾶς ὑπὲρ αὑτοῦ, τῶν γ’ ἔξω φίλων καὶ βουλομένων ἄν τι ποιεῖν ὑμᾶς ἀγαθὸν κἀκεῖνον κωλύειν ἐναντία πράττειν ὑμῖν, οἷον Ἀθηνόδωρον λέγω, Σίμωνα, Βιάνορα, Ἀρχέβιον τὸν Βυζάντιον, τοὺς Θρᾷκας τοὺς δύο, τοὺς βασιλέας, τούτων μηδενὶ μήτ’ ἐναντιωθῆναι μήτε κωλύειν ἐκεῖνον ἐξέσται, τηνικαῦθ’ ἥκω καὶ κατηγορῶ.", "st": "23.189"}, {"sp": "N", "t": "καὶ νομίζω τὸ μέν, οἷς ἔμελλεν ἐκεῖνος λαβὼν μηδὲν ὑπερμέγεθες τὴν πόλιν βλάψειν, ἀντιλέγειν ἢ κακῶς ἰδίᾳ πεπονθότος ἢ συκοφαντοῦντος εἶναι, τὸ δέ, ἐφ’ οἷς μέγα πρᾶγμ’ ἀλυσιτελὲς τῇ πόλει κατεσκευάζετο, ἐναντιοῦσθαι χρηστοῦ καὶ φιλοπόλιδος ἀνδρὸς ἔργον εἶναι. διὰ ταῦτ’ ἐπ’ ἐκείνοις οὐδὲν εἰπὼν νῦν λέγω.", "st": "23.190"}, {"sp": "N", "t": "ἔστιν τοίνυν τις αὐτοῖς τοιοῦτος λόγος δι’ οὗ προσδοκῶσι παράξειν ὑμᾶς, ὡς ὁ Κερσοβλέπτης καὶ Χαρίδημος ἴσως ἐναντί’ ἔπραττον τῇ πόλει τόθ’ ὅτ’ ἦσαν ἐχθροί, νῦν δὲ φίλοι καὶ χρησίμους παρέχουσιν ἑαυτούς. οὐ δὴ δεῖ μνησικακεῖν· οὐδὲ γὰρ Λακεδαιμονίους ὅτ’ ἐσῴζομεν, οὐκ ἀνεμιμνῃσκόμεθ’ εἴ τι κακῶς ἐποίησαν ἡμᾶς ὄντες ἐχθροί, οὐδὲ Θηβαίους, οὐδ’ Εὐβοέας τὰ τελευταῖα νυνί.", "st": "23.191"}, {"sp": "N", "t": "ἐγὼ δ’ ἡγοῦμαι τοῦτον τὸν λόγον, εἰ μὲν ἔν τινι καιρῷ, βοηθείας γεγραμμένης τῷ Κερσοβλέπτῃ καὶ τῷ Χαριδήμῳ, κωλυόντων ἡμῶν ταύτην, ἔλεγον, ὀρθῶς ἂν λέγεσθαι· εἰ δὲ τοιούτου μὲν μηδενὸς ὄντος μηδὲ γεγραμμένου, βουλόμενοι δὲ μείζω τοῦ δέοντος ποιῆσαι διὰ τοῦ παρ’ ὑμῶν ἄδειαν λαβεῖν τοὺς ἐκείνου στρατηγούς, δεινὰ ποιεῖν αὐτοὺς ἡγοῦμαι. οὐ γάρ ἐστι δίκαιον, ἄνδρες Ἀθηναῖοι, τοὺς τῶν σωθῆναι ζητούντων λόγους πρὸς ὑμᾶς λέγειν ὑπὲρ τῶν ὅπως ἀδικεῖν αὑτοῖς ἐξέσται πραττόντων.", "st": "23.192"}, {"sp": "N", "t": "χωρὶς δὲ τούτων, εἰ μὲν ἐχθρὸς ὢν κακῶς ἐποίει, φίλος δὲ φήσας μετεβέβλητο, τάχ’ ἂν ταῦτά τις ἤκουεν· ἐπειδὴ δ’ οὐ τοιοῦτ’ ἐστίν, ἀλλ’ ἐξ οὗ φίλος εἶναι προσποιεῖται, ἐκ τούτου πλεῖσθ’ ὑμᾶς ἐξηπάτηκεν, εἰ μὴ καὶ δι’ ἐκεῖνα μισεῖν, διά γε ταῦτ’ ἀπιστεῖν δήπου προσήκει. καὶ μὴν περὶ τοῦ γε μὴ μνησικακεῖν ἔγωγ’ ὡδί πως λέγω· ὁ μὲν εἵνεκα τοῦ κακόν τι ποιεῖν τὰ τοιαῦτ’ ἐξετάζων μνησικακεῖ, ὁ δ’ ὑπὲρ τοῦ μὴ παθεῖν, ἀλλὰ φυλάξασθαι σκοπῶν σωφρονεῖ.", "st": "23.193"}, {"sp": "N", "t": "ἴσως τοίνυν καὶ τοιαύτην τιν’ ἐροῦσ’ ὑπόνοιαν, ὡς ὡρμηκότα νῦν τὸν ἄνθρωπον φίλον εἶναι καὶ βουλόμενόν τι ποιεῖν ἀγαθὸν τὴν πόλιν εἰς ἀθυμίαν τρέψομεν, εἰ καταψηφιούμεθα, καὶ ποιήσομεν ὑπόπτως ἔχειν πρὸς ἡμᾶς. ἐγὼ δ’, ὦ ἄνδρες Ἀθηναῖοι, θεάσασθ’ ὡς ἔχω. εἰ μετ’ ἀληθείας ἁπλῶς ἦν ἡμῖν φίλος καὶ νὴ Δία πάντ’ ἀγάθ’ ἔμελλεν ἡμᾶς ποιήσειν, οὐδ’ ἂν οὕτως ᾤμην δεῖν τοῦτον ἀκούειν τὸν λόγον· οὐδένα γὰρ ἂν νομίζω τοσαῦτ’ ἀγαθὰ ποιῆσαι, δι’ ὃν ὑμῖν προσήκειν ἐπιορκῆσαι καὶ παρ’ ἃ φαίνεται δίκαια τὴν ψῆφον θέσθαι.", "st": "23.194"}, {"sp": "N", "t": "ἐπειδὴ δὲ καὶ φενακίζων καὶ οὐδ’ ὁτιοῦν ὑγιὲς πράττων ἐξελέγχεται, δυοῖν ἀγαθοῖν θάτερον ὑμῖν, ἂν καταψηφίσησθε, συμβήσεται· ἢ γὰρ ἐξαπατῶν παύσεται νομίσας οὐκέτι λανθάνειν, ἢ εἴπερ αὐτῷ βουλομένῳ πρὸς ὑμᾶς ἔστιν οἰκείως ἔχειν ὡς ἀληθῶς, ἀγαθόν τι ποιεῖν πειράσεται, γνοὺς ὅτι τῷ φενακίζειν οὐκέθ’ ἃ βούλεται πράξει. ὥστε καὶ εἰ μηδὲ δι’ ἓν τῶν ἄλλων, διὰ τοῦτο καταψηφίσασθαι συμφέρει.", "st": "23.195"}, {"sp": "N", "t": "ἄξιον τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, κἀκεῖν’ ἐξετάσαι, πῶς ποθ’ οἱ πάλαι τὰς τιμὰς ἔνεμον καὶ τὰς δωρειὰς τοῖς ὡς ἀληθῶς εὐεργέταις, καὶ ὅσοι πολῖται τύχοιεν ὄντες καὶ ὅσοι ξένοι. κἂν μὲν ἴδητ’ ἐκείνους ἄμεινον ὑμῶν, καλὸν τὸ μιμήσασθαι, ἂν δ’ ὑμᾶς αὐτούς, ἐφ’ ὑμῖν ἔσται τὸ πράττειν. πρῶτον μὲν τοίνυν ἐκεῖνοι Θεμιστοκλέα τὸν τὴν ἐν Σαλαμῖνι ναυμαχίαν νικήσαντα καὶ Μιλτιάδην τὸν ἡγούμενον Μαραθῶνι καὶ πολλοὺς ἄλλους, οὐκ ἴσα τοῖς νῦν στρατηγοῖς ἀγάθ’ εἰργασμένους, οὐ χαλκοῦς ἵστασαν οὐδ’ ὑπερηγάπων.", "st": "23.196"}, {"sp": "N", "t": "οὐκ ἄρα τοῖς ἑαυτοὺς ἀγαθόν τι ποιοῦσιν χάριν εἶχον; σφόδρα γ’, ὦ ἄνδρες Ἀθηναῖοι, καὶ ἀπεδίδοσάν γε καὶ αὑτῶν κἀκείνων ἀξίαν· ὄντες γὰρ πολλοῦ πάντες ἄξιοι προὔκρινον ἐκείνους αὑτῶν ἡγεῖσθαι. ἔστι δὲ σώφροσιν ἀνθρώποις καὶ πρὸς ἀλήθειαν βουλομένοις σκοπεῖν πολὺ μείζων τιμὴ τῆς χαλκῆς εἰκόνος τὸ καλῶν κἀγαθῶν ἀνδρῶν κεκρίσθαι πρώτους.", "st": "23.197"}, {"sp": "N", "t": "καὶ γάρ τοι τῶν ἔργων τῶν τότ’, ἄνδρες Ἀθηναῖοι, οὐδενὸς ἀπεστέρησαν ἑαυτούς, οὐδ’ ἔστιν οὐδεὶς ὅστις ἂν εἴποι τὴν ἐν Σαλαμῖνι ναυμαχίαν Θεμιστοκλέους, ἀλλ’ Ἀθηναίων, οὐδὲ τὴν Μαραθῶνι μάχην Μιλτιάδου, ἀλλὰ τῆς πόλεως. νῦν δ’, ὦ ἄνδρες Ἀθηναῖοι, πολλοὶ τοῦτο λέγουσιν, ὡς Κέρκυραν εἷλε Τιμόθεος καὶ τὴν μόραν κατέκοψεν Ἰφικράτης καὶ τὴν περὶ Νάξον ἐνίκα ναυμαχίαν Χαβρίας· δοκεῖτε γὰρ αὐτοὶ τῶν ἔργων τούτων παραχωρεῖν τῶν τιμῶν ταῖς ὑπερβολαῖς αἷς δεδώκατ’ ἐπ’ αὐτοῖς ἑκάστῳ τούτων.", "st": "23.198"}, {"sp": "N", "t": "τὰς μὲν δὴ πολιτικὰς δωρειὰς οὕτως ἐκεῖνοί τε καλῶς καὶ λυσιτελούντως αὑτοῖς ἐδίδοσαν καὶ ἡμεῖς οὐκ ὀρθῶς· τὰς δὲ τῶν ξένων πῶς; ἐκεῖνοι Μένωνι τῷ Φαρσαλίῳ δώδεκα μὲν τάλαντ’ ἀργυρίου δόντι πρὸς τὸν ἐπ’ Ἠιόνι τῇ πρὸς Ἀμφιπόλει πόλεμον, τριακοσίοις δ’ ἱππεῦσι πενέσταις ἰδίοις βοηθήσαντι, οὐκ ἐψηφίσαντο, αὐτὸν ἄν τις ἀποκτείνῃ, ἀγώγιμον εἶναι, ἀλλὰ πολιτείαν ἔδοσαν καὶ ταύτην ἱκανὴν ὑπελάμβανον εἶναι τὴν τιμήν.", "st": "23.199"}, {"sp": "N", "t": "καὶ πάλιν Περδίκκᾳ τῷ κατὰ τὴν τοῦ βαρβάρου ποτ’ ἐπιστρατείαν βασιλεύοντι Μακεδονίας, τοὺς ἀναχωροῦντας ἐκ Πλαταιῶν τῶν βαρβάρων διαφθείραντι καὶ τέλειον τἀτύχημα ποιήσαντι τῷ βασιλεῖ, οὐκ ἐψηφίσαντ’ ἀγώγιμον, ἄν τις ἀποκτείνῃ Περδίκκαν, ᾧ βασιλεὺς ἐχθρὸς δι’ ἡμᾶς ἀπεδέδεικτο, ἀλλὰ πολιτείαν ἔδωκαν μόνον. καὶ γάρ τοι τότε μὲν οὕτω τίμιον ἦν πᾶσιν ἀνθρώποις τὸ γενέσθαι πολίταις παρ’ ὑμῖν ὥσθ’ ὑπὲρ τοῦ τυχεῖν τούτου τηλικαῦθ’ ὑμᾶς ἀγάθ’ ἤθελον ποιεῖν, νῦν δ’ οὕτως ἄτιμον ὥστε τῶν τετυχηκότων πολλοὶ πλείω κακὰ τῶν φανερῶς ἐχθρῶν εἰσιν ὑμᾶς εἰργασμένοι.", "st": "23.200"}, {"sp": "N", "t": "οὐ μόνον δ’ αὕτη τῆς πόλεως ἡ δωρειὰ προπεπηλάκισται καὶ φαύλη γέγονεν, ἀλλὰ καὶ πᾶσαι διὰ τὴν τῶν καταράτων καὶ θεοῖς ἐχθρῶν ῥητόρων, τῶν τὰ τοιαῦτα γραφόντων ἑτοίμως, πονηρίαν, οἳ τοσαύτην ὑπερβολὴν πεποίηνται τῆς αὑτῶν αἰσχροκερδείας ὥστε τὰς τιμὰς καὶ τὰς παρ’ ὑμῶν δωρειάς, ὥσπερ οἱ τὰ μικρὰ καὶ κομιδῇ φαῦλ’ ἀποκηρύττοντες, οὕτω πωλοῦσιν ἐπευωνίζοντες καὶ πολλοῖς ἀπὸ τῶν αὐτῶν λημμάτων γράφοντες πᾶν ὅ τι ἂν βούλωνται.", "st": "23.201"}, {"sp": "N", "t": "πρῶτον μέν, ἵνα τῶν τελευταίων πρώτων μνησθῶμεν, Ἀριοβαρζάνην ἐκεῖνον οὐ μόνον αὐτὸν καὶ τοὺς υἱεῖς τρεῖς ὄντας πάντων ἠξίωσαν ὅσων ἐβουλήθησαν, ἀλλὰ καὶ δύ’ Ἀβυδηνούς, μισαθηναιοτάτους καὶ πονηροτάτους ἀνθρώπους, [προσέθηκαν αὐτῷ] Φιλίσκον καὶ Ἀγαυόν. πάλιν Τιμοθέου δόξαντός τι ποιῆσαι τῶν δεόντων ὑμῖν, πρὸς τῷ πάνθ’ ἃ μέγιστ’ ἦν αὐτῷ δοῦναι προσέθηκαν αὐτῷ Φρασιηρίδην καὶ Πολυσθένην, ἀνθρώπους οὐδ’ ἐλευθέρους, ἀλλ’ ὀλέθρους καὶ τοιαῦτα πεποιηκότας οἷα λέγειν ὀκνήσειεν ἄν τις εὖ φρονῶν.", "st": "23.202"}, {"sp": "N", "t": "τὸ τελευταῖον δὲ νῦν, ἐπειδὴ Κερσοβλέπτην ἠξίουν ὧν αὐτοῖς ἐδόκει, καὶ περὶ τούτων ἦν ἡ σπουδή, προστιθέασιν δύ’ αὐτῷ, τὸν μὲν ὅσ’ ὑμεῖς ἀκηκόατ’ εἰργασμένον κακά, τὸν δ’ ὅλως οὐδεὶς οἶδεν ἀνθρώπων τίς ἐστιν, Εὐδέρκην ὄνομα. τοιγάρτοι διὰ ταῦτ’, ὦ ἄνδρες Ἀθηναῖοι, μικρά, ἃ πρὸ τοῦ μεγάλ’ ἦν, φαίνεται, καὶ τὸ πρᾶγμ’ ἤδη καὶ πορρωτέρω βαδίζει καὶ οὐκέτι ταῦτ’ ἀπόχρη, ἀλλ’ εἰ μὴ καὶ φυλάξεθ’ ἕκαστον τούτων, ἐκείνων γ’ οὐδεμία χάρις, ὡς ἔοικεν.", "st": "23.203"}, {"sp": "N", "t": "τοῦ μέντοι ταῦθ’ οὕτως αἰσχρῶς προεληλυθέναι, εἰ δεῖ μετὰ παρρησίας εἰπεῖν τἀληθῆ, οὐδένες ὑμῶν, ὦ ἄνδρες Ἀθηναῖοι, μᾶλλόν εἰσιν αἴτιοι. οὐδὲ γὰρ δίκην ἔτι λαμβάνειν ἐθέλετε παρὰ τῶν ἀδικούντων, ἀλλὰ καὶ τοῦτ’ ἐξελήλυθεν ἐκ τῆς πόλεως. καίτοι σκέψασθ’ ὡς ἐκόλαζον οἱ πρόγονοι τοὺς ἀδικοῦντας ἑαυτούς, εἰ παραπλησίως ὑμῖν.", "st": "23.204"}, {"sp": "N", "t": "ἐκεῖνοι Θεμιστοκλέα λαβόντες μεῖζον ἑαυτῶν ἀξιοῦντα φρονεῖν ἐξήλασαν ἐκ τῆς πόλεως καὶ μηδισμὸν κατέγνωσαν· καὶ Κίμωνα, ὅτι τὴν πάτριον μετεκίνησε πολιτείαν ἐφ’ ἑαυτοῦ, παρὰ τρεῖς μὲν ἀφεῖσαν ψήφους τὸ μὴ θανάτῳ ζημιῶσαι, πεντήκοντα δὲ τάλαντ’ ἐξέπραξαν. καὶ τοῦτον τὸν τρόπον προσεφέροντο τηλικαῦτ’ αὐτοὺς ἀγάθ’ εἰργασμένοις ἀνθρώποις. δικαίως· οὐ γὰρ αὐτοῖς ἀπεδίδοντο τὴν αὑτῶν ἐλευθερίαν καὶ μεγαλοψυχίαν τῶν ἔργων, ἀλλὰ χρηστοὺς μὲν ὄντας ἐτίμων, ἀδικεῖν δ’ ἐπιχειροῦσιν οὐκ ἐπέτρεπον.", "st": "23.205"}, {"sp": "N", "t": "ὑμεῖς δ’, ὦ ἄνδρες Ἀθηναῖοι, τοὺς τὰ μέγιστ’ ἀδικοῦντας καὶ φανερῶς ἐξελεγχομένους, ἂν ἓν ἢ δύ’ ἀστεῖ’ εἴπωσιν καὶ παρὰ τῶν φυλετῶν τινες ᾑρημένοι σύνδικοι δεηθῶσιν, ἀφίετε· ἂν δὲ καὶ καταψηφίσησθέ του, πέντε καὶ εἴκοσι δραχμῶν ἐτιμήσατε. καὶ γάρ τοι τότε μὲν τὰ μὲν τῆς πόλεως ἦν εὔπορα καὶ λαμπρὰ δημοσίᾳ, ἰδίᾳ δ’ οὐδεὶς ὑπερεῖχε τῶν πολλῶν.", "st": "23.206"}, {"sp": "N", "t": "τεκμήριον δέ· τὴν Θεμιστοκλέους μὲν οἰκίαν καὶ τὴν Μιλτιάδου καὶ τῶν τότε λαμπρῶν, εἴ τις ἄρ’ ὑμῶν οἶδεν ὁποία ποτ’ ἐστίν, ὁρᾷ τῶν πολλῶν οὐδὲν σεμνοτέραν οὖσαν, τὰ δὲ τῆς πόλεως οἰκοδομήματα καὶ κατασκευάσματα τηλικαῦτα καὶ τοιαῦθ’ ὥστε μηδενὶ τῶν ἐπιγιγνομένων ὑπερβολὴν λελεῖφθαι, προπύλαια ταῦτα, νεώσοικοι, στοαί, Πειραιεύς, τἄλλ’ οἷς κατεσκευασμένην ὁρᾶτε τὴν πόλιν.", "st": "23.207"}, {"sp": "N", "t": "νῦν δ’ ἰδίᾳ μὲν ἑκάστῳ τῶν τὰ κοινὰ πραττόντων τοσαύτη περιουσία [ἐστὶν] ὥστε τινὲς μὲν αὐτῶν πολλῶν δημοσίων οἰκοδομημάτων σεμνοτέρας τὰς ἰδίας κατεσκευάκασιν οἰκίας, γῆν δ’ ἔνιοι πλείω πάντων ὑμῶν τῶν ἐν τῷ δικαστηρίῳ συνεώνηνται· δημοσίᾳ δ’ ὑμεῖς ἃ μὲν οἰκοδομεῖτε καὶ κονιᾶτε, ὡς μικρὰ καὶ γλίσχρα, αἰσχύνη λέγειν. ἀλλ’ ἔχετ’ εἰπεῖν ὅ τι κοινῇ κτησάμενοι καταλείψετε, ὥσπερ ἐκεῖνοι Χερρόνησον, Ἀμφίπολιν, δόξαν ἔργων καλῶν; ἣν οἱ τοιοῦτοι πολῖται πάντ’ ἀναλίσκοντες τρόπον οὐχ οἷοί τ’ εἰσὶν ἀφανίσαι, ὦ ἄνδρες Ἀθηναῖοι.", "st": "23.208"}, {"sp": "N", "t": "εἰκότως· τότε μὲν γὰρ τῷ κυρίῳ τῶν φόρων γενομένῳ τάξαι Ἀριστείδῃ οὐδὲ μιᾷ δραχμῇ πλείω τὰ ὑπάρχοντ’ ἐγένετο, ἀλλὰ καὶ τελευτήσαντ’ αὐτὸν ἔθαψεν ἡ πόλις· ὑμῖν δ’, εἴ τι δέοισθε, χρήμαθ’ ὑπῆρχε κοινῇ πλεῖστα τῶν πάντων Ἑλλήνων, ὥσθ’ ὁπόσου χρόνου ψηφίσαισθ’ ἐξιέναι, τοσούτου μισθὸν ἔχοντες ἐξῇτε. νῦν δ’ οἱ μὲν τὰ κοινὰ διοικοῦντες ἐκ πτωχῶν εὔποροι καὶ πολλοῦ χρόνου τροφὴν ἄφθονόν εἰσιν ἡτοιμασμένοι· ὑμῖν δ’ οὐδὲ μιᾶς ἡμέρας ἐφόδι’ ἐστὶν ἐν τῷ κοινῷ, ἀλλ’ ἅμα δεῖ τι ποιεῖν, καὶ πόθεν οὐκ ἔχετε. τότε μὲν γὰρ ὁ δῆμος ἦν δεσπότης τῶν πολιτευομένων, νῦν δ’ ὑπηρέτης.", "st": "23.209"}, {"sp": "N", "t": "αἴτιοι δ’ οἱ τὰ τοιαῦτα γράφοντες, καὶ συνεθίζοντες ὑμᾶς ὑμῶν μὲν αὐτῶν καταφρονεῖν, ἕνα δ’ ἢ δύο θαυμάζειν ἀνθρώπους. εἶθ’ οὗτοι κληρονομοῦσι τῆς ὑμετέρας δόξης καὶ τῶν ἀγαθῶν, ὑμεῖς δ’ οὐδ’ ὁτιοῦν ἀπολαύετε, ἀλλὰ μάρτυρές ἐστε τῶν ἑτέρων ἀγαθῶν, οὐδενὸς ἄλλου μετέχοντες ἢ τοῦ ἐξαπατᾶσθαι. καίτοι πηλίκον τί ποτ’ ἂν στενάξειαν οἱ ἄνδρες ἐκεῖνοι, οἱ ὑπὲρ δόξης καὶ ἐλευθερίας τελευτήσαντες, καὶ πολλῶν καὶ καλῶν ἔργων ὑπομνήματα καταλιπόντες, εἰ ἄρ’ αἴσθοινθ’ ὅτι νῦν ἡ πόλις εἰς ὑπηρέτου σχῆμα καὶ τάξιν προελήλυθεν, καὶ Χαρίδημον εἰ χρὴ φρουρεῖν βουλεύεται; Χαρίδημον; οἴμοι.", "st": "23.210"}, {"sp": "N", "t": "ἀλλ’ οὐ τοῦτ’ ἔστι τὸ δεινόν, εἰ τῶν προγόνων, οἳ διενηνόχασιν ἁπάντων ἀρετῇ, χεῖρον βουλευόμεθα, ἀλλ’ ὅτι καὶ πάντων ἀνθρώπων. πῶς γὰρ οὐκ αἰσχρὸν Αἰγινήτας μὲν τουτουσί, νῆσον οἰκοῦντας οὕτω μικρὰν καὶ οὐδὲν ἔχοντας ἐφ’ ᾧ μέγα χρὴ φρονεῖν αὐτούς, Λάμπιν, ὃς μέγιστα ναυκλήρια κέκτηται τῶν Ἑλλήνων, καὶ κατεσκεύακεν τὴν πόλιν αὐτοῖς καὶ τὸ ἐμπόριον, μηδέπω καὶ τήμερον πολίτην πεποιῆσθαι, ἀλλὰ μόλις τῆς ἀτελείας αὐτὸν ἠξιωκέναι τῆς τοῦ μετοικίου·", "st": "23.211"}, {"sp": "N", "t": "καὶ Μεγαρέας τουτουσὶ τοὺς καταράτους οὕτως εὖ τὰ παρ’ αὑτοῖς σεμνύνειν ὥσθ’ Ἕρμωνα τὸν κυβερνήτην, τὸν μετὰ Λυσάνδρου λαβόντα τριήρεις διακοσίας ὅτ’ ἐν Αἰγὸς ποταμοῖς ἠτυχήσαμεν ἡμεῖς, πεμψάντων Λακεδαιμονίων καὶ κελευόντων ποιήσασθαι πολίτην ἀποκρίνασθαι ὅτι, ὅταν αὐτοὺς ἴδωσι Σπαρτιάτην αὐτὸν πεποιημένους, τότε καὶ αὐτοὶ Μεγαρέα ποιήσονται·", "st": "23.212"}, {"sp": "N", "t": "καὶ Ὠρείτας ἐκείνους, μέρος τέταρτον Εὐβοίας οἰκοῦντας, τὸν Χαρίδημον τοῦτον αὐτόν, ᾧ μήτηρ μὲν ὑπάρχει πολῖτις ἐκεῖ, πατὴρ δ’ οὐκ ἐρῶ τίς ἢ πόθεν (οὐδὲν γὰρ δεῖ πλείω τῶν ἀναγκαίων αὐτὸν ἐξετάζεσθαι), ἀλλ’ ὅμως, τὸ ἥμισυ τοῦ γένους αὐτοῦ συμβαλλομένου, τοῦ ἡμίσεος μέχρι τῆς τήμερον ἡμέρας οὐκ ἠξιώκασιν, ἀλλ’ εἰς τοὺς νόθους ἐκεῖ συντελεῖ, καθάπερ ποτ’ ἐνθάδ’ εἰς Κυνόσαργες οἱ νόθοι·", "st": "23.213"}, {"sp": "N", "t": "ὑμεῖς δ’, ὦ ἄνδρες Ἀθηναῖοι, πάσης τῆς πόλεως μεταδόντες αὐτῷ καὶ τετιμηκότες ἄλλοις, ἔτι καὶ τοῦτ’ αὐτῷ προσθήσετε; ὅτι τί; ποίας ἔλαβεν ναῦς ὑμῖν δι’ ἃς ὑπὸ τῶν ἀπολωλεκότων ἐπιβουλεύεται; ἢ ποίαν πόλιν παρέδωκεν αἰχμάλωτον λαβών; ἢ τίνας κινδύνους ὑπὲρ ὑμῶν κεκινδύνευκεν; ἢ τίνας ἐχθροὺς τοὺς αὐτοὺς ὑμῖν ᾕρηται; οὐδ’ ἂν εἷς εἰπεῖν ἔχοι.", "st": "23.214"}, {"sp": "N", "t": "περὶ δὴ τῶν νόμων ὧν παραγεγράμμεθ’, ὦ ἄνδρες δικασταί, βούλομαι μικρὰ πρὸς ὑμᾶς εἰπὼν καταβαίνειν, ἃ νομίζω μνημονεύοντας ἂν ὑμᾶς ἄμεινον φυλάττειν, ἂν παράγειν καὶ φενακίζειν οὗτοι ζητῶσιν. ὁ πρῶτος νόμος ἄντικρυς εἴρηκεν, ἄν τις ἀποκτείνῃ, τὴν βουλὴν δικάζειν· ὁ δέ, ἄν τις ἀποκτείνῃ, εὐθὺς ἔγραψεν ἀγώγιμον εἶναι. τοῦτο φυλάττετε καὶ μέμνησθε, ὅτι πάντων ἐναντιώτατόν ἐστι τῷ κρίνειν τὸ μὴ διδόντα κρίσιν ἔκδοτον ποιεῖν.", "st": "23.215"}, {"sp": "N", "t": "οὐκ ἐᾷ μετὰ ταῦθ’ ὁ δεύτερος νόμος οὐδὲ τὸν ἑαλωκότ’ ἀνδροφόνον λυμαίνεσθαι οὐδὲ χρήματα πράττεσθαι· ὁ δ’ ἐν τῷ ποιεῖν ἀγώγιμον πάντα ταῦτα δέδωκεν· ἐπὶ γὰρ τοῖς λαβοῦσιν ἔσται ποιεῖν ὅ τι ἂν βούλωνται. ἀπάγειν ὁ νόμος ὡς τοὺς θεσμοθέτας κελεύει, καὶ τοῦτ’, ἂν ἐν τῇ τοῦ πεπονθότος λάβῃ τις πατρίδι· ὁ δ’ ἀγώγιμον αὐτῷ τῷ τὴν αἰτίαν ἐπενεγκόντι δίδωσιν ὡς αὑτόν, κἂν τῆς ἀλλοτρίας που λάβῃ.", "st": "23.216"}, {"sp": "N", "t": "ἔστιν ἐφ’ οἷς ἀδικήμασιν δέδωκεν ἀποκτείνειν ὁ νόμος· ὁ δ’ οὐδὲν ὑπειπών, κἂν ἐπὶ τούτοις τις κτείνῃ, δίδωσιν ἔκδοτον τὸν ἀθῷον ἀφειμένον ἐν τοῖς νόμοις. ἄν τις πάθῃ τι τοιοῦτον, δίκας ὁ νόμος κελεύει αἰτεῖν πρῶτον· ὁ δὲ τοὐναντίον οὐδεμίαν κρίσιν οὔτ’ αὐτὸς εἰπὼν οὔτε παρ’ ὧν ἀξιοῖ λαβεῖν αἰτήσας, ἀγώγιμον εὐθὺς ἔγραψεν, κἄν τις ἀφαιρῆται, παραχρῆμ’ ἔκσπονδον.", "st": "23.217"}, {"sp": "N", "t": "τὸ ἀνδρολήψιον, παρ’ οἷς ἂν ὁ δράσας ᾖ, ἂν μὴ διδῶσι δίκας, κελεύουσιν οἱ νόμοι μέχρι τριῶν εἶναι· ὁ δέ, ἂν ἀφέληταί τις τὸν ἄγοντα μὴ βουλόμενος πρὸ δίκης ἐκδοῦναι, εὐθὺς ἔκσπονδον ποιεῖ. οὐκ ἐᾷ νόμον, ἂν μὴ τὸν αὐτὸν ἐπὶ πᾶσι τιθῇ τις, εἰσφέρειν· ὁ δ’ ἐπ’ ἀνδρὶ γράφει ψήφισμ’ ἴδιον. οὐκ ἐᾷ ψήφισμ’ ὁ νόμος κυριώτερον εἶναι νόμου· ὁ δ’ ὑπαρχόντων τοσούτων νόμων ψήφισμα ποιεῖ κύριον τοὺς νόμους ἀναιρῶν.", "st": "23.218"}, {"sp": "N", "t": "ταῦτα φυλάττετε καὶ μεμνημένοι κάθησθε. καὶ τὰς μὲν παραγωγάς, ἃς οὗτοι ποιήσονται, χαίρειν ἐᾶτε καὶ μὴ ἐπιτρέπετε λέγειν αὐτοῖς, κελεύετε δὲ δεῖξαι ποῦ γέγραφεν κρίσιν, ἢ ποῦ γέγραφεν, ἄν τις ἁλῷ φόνου, κατὰ τούτου τὰς τιμωρίας. εἰ γὰρ ἢ τὸν ἄλλοθί που κριθέντα καὶ ἑαλωκότα ὅτι δεῖ κολάζειν ἔγραψεν, ἢ αὐτὸς ἔγραψεν κρίσιν εἰ πεποίηκεν ἢ οὒ καὶ εἰ δικαίως ἢ ἀδίκως, οὐκ ἂν ἠδίκει.", "st": "23.219"}, {"sp": "N", "t": "εἰ δὲ τὸ τῆς αἰτίας ὄνομ’ αὐτὸ γράψας “ἄν τις ἀποκτείνῃ,” καὶ ὑπερβὰς τὸ “καὶ ἁλῷ φόνου,” καὶ τὸ “δόξῃ ἀπεκτονέναι,” καὶ τὸ “δίκας ὑπεχέτω τοῦ φόνου,” καὶ τὸ “τὰς τιμωρίας εἶναι κατ’ αὐτοῦ τὰς αὐτὰς ἅσπερ ἂν τὸν Ἀθηναῖον κτείνῃ,” καὶ πάνθ’ ὅσ’ ἐστὶ δίκαι’ ὑπερβὰς ἀγώγιμον εἶναι γέγραφεν, μὴ φενακίζεσθε, ἀλλ’ εὖ ἴσθ’ ὅτι πάντων παρανομώτατ’ εἴρηκεν.", "st": "23.220"}, {"sp": "HDR", "t": "Κατὰ Τιμοκράτους", "st": "24"}, {"sp": "N", "t": "τοῦ μὲν ἀγῶνος, ὦ ἄνδρες δικασταί, τοῦ παρόντος οὐδ’ ἂν αὐτὸν οἶμαι Τιμοκράτην εἰπεῖν ὡς αἴτιός ἐστιν ἄλλος τις αὐτῷ πλὴν αὐτὸς αὑτῷ. χρημάτων γὰρ οὐκ ὀλίγων ἀποστερῆσαι βουλόμενος τὴν πόλιν, παρὰ πάντας τοὺς νόμους νόμον εἰσήνεγκεν οὔτ’ ἐπιτήδειον οὔτε δίκαιον, ὦ ἄνδρες δικασταί· ὃς τὰ μὲν ἄλλ’ ὅσα λυμανεῖται καὶ χεῖρον ἔχειν τὰ κοινὰ ποιήσει, κύριος εἰ γενήσεται, τάχα δὴ καθ’ ἕκαστον ἀκούοντες ἐμοῦ μαθήσεσθε, ἓν δ’, ὃ μέγιστον ἔχω καὶ προχειρότατον πρὸς ὑμᾶς εἰπεῖν, οὐκ ἀποτρέψομαι.", "st": "24.1"}, {"sp": "N", "t": "τὴν γὰρ ὑμετέραν ψῆφον, ἣν ὀμωμοκότες περὶ πάντων φέρετε, λύει καὶ ποιεῖ τοῦ μηδενὸς ἀξίαν ὁ τουτουὶ νόμος, οὐχ ἵνα κοινῇ τι τὴν πόλιν ὠφελήσῃ (πῶς γάρ; ὅς γε, ἃ δοκεῖ συνέχειν τὴν πολιτείαν, τὰ δικαστήρια, ταῦτ’ ἄκυρα ποιεῖ τῶν προστιμημάτων τῶν ἐπὶ τοῖς ἀδικήμασιν ἐκ τῶν νόμων ὡρισμένων), ἀλλ’ ἵνα τῶν πολὺν χρόνον ὑμᾶς τινες ἐκκεκαρπωμένων καὶ πολλὰ τῶν ὑμετέρων διηρπακότων μηδ’ ἃ κλέπτοντες φανερῶς ἐλήφθησαν καταθῶσιν.", "st": "24.2"}, {"sp": "N", "t": "καὶ τοσούτῳ ῥᾷόν ἐστ’ ἰδίᾳ τινὰς θεραπεύειν ἢ τῶν ὑμετέρων δικαίων προΐστασθαι, ὥσθ’ οὗτος μὲν ἔχει παρ’ ἐκείνων ἀργύριον καὶ οὐ πρότερον τοῦτον εἰσήνεγκε ὑπὲρ αὐτῶν τὸν νόμον, ἐμοὶ δ’ ἐν χιλίαις ὑπὲρ ὑμῶν ὁ κίνδυνος· τοσοῦτ’ ἀπέχω τοῦ λαβεῖν τι παρ’ ὑμῶν.", "st": "24.3"}, {"sp": "N", "t": "εἰώθασιν μὲν οὖν οἱ πολλοὶ τῶν πράττειν τι προαιρουμένων τῶν κοινῶν λέγειν ὡς ταῦθ’ ὑμῖν σπουδαιότατ’ ἐστὶν καὶ μάλιστ’ ἄξιον προσέχειν τούτοις, ὑπὲρ ὧν ἂν αὐτοὶ τυγχάνωσι ποιούμενοι τοὺς λόγους. ἐγὼ δ’, εἴπερ τινὶ τοῦτο καὶ ἄλλῳ προσηκόντως εἴρηται, νομίζω κἀμοὶ νῦν ἁρμόττειν εἰπεῖν.", "st": "24.4"}, {"sp": "N", "t": "τῶν γὰρ ὄντων ἀγαθῶν τῇ πόλει καὶ τοῦ δημοκρατουμένην καὶ ἐλευθέραν εἶναι ὡς ἄλλο τι τῶν νόμων αἰτιώτερόν ἐστιν, οὐδ’ ἂν ἕν’ εἰπεῖν οἶμαι. περὶ τοίνυν αὐτοῦ τούτου νῦν ὑμῖν ἐστιν, πότερον δεῖ τοὺς μὲν ἄλλους νόμους, οὓς ἐπὶ τοῖς ἀδικοῦσι τὴν πόλιν ὑμεῖς ἀνεγράψατε, ἀκύρους εἶναι, τόνδε δὲ κύριον, ἢ τοὐναντίον τοῦτον μὲν λῦσαι, κατὰ χώραν δὲ μένειν τοὺς ἄλλους ἐᾶν. τὸ μὲν οὖν πρᾶγμα περὶ οὗ δεῖ νῦν ὑμᾶς γνῶναι, ὡς ἐν κεφαλαίῳ τις ἂν εἴποι, τοῦτ’ ἐστίν.", "st": "24.5"}, {"sp": "N", "t": "ἵνα δ’ ὑμῶν μηδεὶς θαυμάζῃ τί δή ποτ’ ἐγὼ μετρίως, ὥς γ’ ἐμαυτὸν πείθω, τὸν ἄλλον χρόνον βεβιωκὼς νῦν ἐν ἀγῶσι καὶ γραφαῖς δημοσίαις ἐξετάζομαι, βούλομαι μικρὰ πρὸς ὑμᾶς εἰπεῖν· ἔσται δὲ ταῦτ’ οὐκ ἄπο τοῦ πράγματος. ἐγὼ γάρ, ὦ ἄνδρες Ἀθηναῖοι, προσέκρουσ’ ἀνθρώπῳ πονηρῷ καὶ φιλαπεχθήμονι καὶ θεοῖς ἐχθρῷ, ᾧ τελευτῶσ’ ὅλη προσέκρουσεν ἡ πόλις, Ἀνδροτίωνα λέγω.", "st": "24.6"}, {"sp": "N", "t": "καὶ τοσούτῳ δεινότερ’ Εὐκτήμονος ἠδικήθην ὑπ’ αὐτοῦ, ὥσθ’ ὁ μὲν Εὐκτήμων εἰς χρήματ’ ἔσθ’ ἃ κακῶς ἔπαθεν, ἐγὼ δ’, εἰ κατώρθωσεν ἐκεῖνος ἣν ἐπ’ ἔμ’ ἦλθεν ὁδόν, οὐχ ὅτι τῶν ὄντων ἂν ἀπεστερήμην, ἀλλ’ οὐδ’ ἂν ἔζων, οὐδ’ ὃ κοινὸν ἅπασίν ἐστιν, ἀπαλλαγῆναι τοῦ βίου, ῥᾴδιον ἦν ἄν μοι. αἰτιασάμενος γάρ μ’ ἃ καὶ λέγειν ἄν τις ὀκνήσειεν εὖ φρονῶν, τὸν ἐμαυτοῦ πατέρ’ ὡς ἀπέκτονα, ἀσεβείας γραφὴν κατασκευάσας εἰς ἀγῶνα κατέστησεν. ἐν δὲ τούτῳ τὸ πέμπτον μέρος τῶν ψήφων οὐ μεταλαβὼν ὦφλε χιλίας, ἐγὼ δ’, ὥσπερ ἦν δίκαιον, μάλιστα μὲν διὰ τοὺς θεούς, ἔπειτα δὲ καὶ διὰ τοὺς δικάζοντας ὑμῶν ἐσώθην,", "st": "24.7"}, {"sp": "N", "t": "τὸν δ’ εἰς τοιαῦτα καταστήσαντά μ’ ἀδίκως ἀδιάλλακτον ἐχθρὸν ἡγούμην. ἰδὼν δ’ ἠδικηκότα κοινῇ πᾶσαν τὴν πόλιν καὶ περὶ τὴν εἴσπραξιν τῶν εἰσφορῶν καὶ περὶ τὴν ποίησιν τῶν πομπείων, καὶ χρήματα πολλὰ τῆς θεοῦ καὶ τῶν ἐπωνύμων καὶ τῆς πόλεως ἔχοντα καὶ οὐκ ἀποδιδόντα, ἦλθον ἐπ’ αὐτὸν μετ’ Εὐκτήμονος, ἡγούμενος ἁρμόττοντ’ εἰληφέναι καιρὸν τοῦ βοηθῆσαί θ’ ἅμα τῇ πόλει καὶ τιμωρίαν ὑπὲρ ὧν ἐπεπόνθειν λαβεῖν· βουλοίμην δ’ ἂν ἐμέ τε τυχεῖν ὧν βούλομαι τοῦτόν τε παθεῖν ὧν ἄξιός ἐστι.", "st": "24.8"}, {"sp": "N", "t": "τοῦ δὲ πράγματος οὐκέτ’ ὄντος ἀμφισβητησίμου, ἀλλὰ πρῶτον μὲν τῆς βουλῆς κατεγνωκυίας, εἶτα τοῦ δήμου μίαν ἡμέραν ὅλην ἐπὶ τούτοις αὐτοῖς ἀναλώσαντος, πρὸς δὲ τούτοις δικαστηρίοιν δυοῖν εἰς ἕνα καὶ χιλίους ἐψηφισμένων, ἐνούσης δ’ οὐδεμιᾶς ἔτ’ ἀποστροφῆς τοῦ μὴ τὰ χρήματ’ ἔχειν ὑμᾶς, Τιμοκράτης οὑτοσὶ τοσοῦθ’ ὑπερεῖδεν ἅπαντα τὰ πράγματα, ὥστε τίθησι τουτονὶ τὸν νόμον, δι’ οὗ τῶν ἱερῶν μὲν χρημάτων τοὺς θεούς, τῶν ὁσίων δὲ τὴν πόλιν ἀποστερεῖ, ἄκυρα δὲ τὰ γνωσθένθ’ ὑπὸ τῆς βουλῆς καὶ τοῦ δήμου καὶ τοῦ δικαστηρίου καθίστησιν, ἄδειαν δὲ τὰ κοινὰ διαρπάζειν τῷ βουλομένῳ πεποίηκεν.", "st": "24.9"}, {"sp": "N", "t": "ὑπὲρ δὴ τούτων ἁπάντων λύσιν εὑρίσκομεν ταύτην οὖσαν μόνην, εἰ γραψάμενοι τὸν νόμον καὶ εἰσαγαγόντες εἰς ὑμᾶς λῦσαι δυναίμεθα. ἐξ ἀρχῆς οὖν ἐν βραχέσιν τὰ πραχθέντα δίειμι πρὸς ὑμᾶς, ἵνα μᾶλλον μάθητε καὶ παρακολουθήσητε τοῖς περὶ τὸν νόμον αὐτὸν ἀδικήμασιν.", "st": "24.10"}, {"sp": "N", "t": "ψήφισμ’ εἶπεν ἐν ὑμῖν Ἀριστοφῶν ἑλέσθαι ζητητάς, εἰ δέ τις οἶδέν τιν’ ἢ τῶν ἱερῶν ἢ τῶν ὁσίων χρημάτων ἔχοντά τι τῆς πόλεως, μηνύειν πρὸς τούτους. μετὰ ταῦτ’ ἐμήνυσεν Εὐκτήμων ἔχειν Ἀρχέβιον καὶ Λυσιθείδην τριηραρχήσαντας χρήματα Ναυκρατιτικά, τίμημα τάλαντ’ ἐννέα καὶ τριάκοντα μνᾶς. προσῆλθε τῇ βουλῇ, προβούλευμ’ ἐγράφη. μετὰ ταῦτα γενομένης ἐκκλησίας προὐχειροτόνησεν ὁ δῆμος.", "st": "24.11"}, {"sp": "N", "t": "ἀναστὰς Εὐκτήμων ἔλεγ’ ἄλλα τε πολλὰ καὶ διεξῆλθεν πρὸς ὑμᾶς ὡς ἔλαβ’ ἡ τριήρης τὸ πλοῖον ἡ Μελάνωπον ἄγουσα καὶ Γλαυκέτην καὶ Ἀνδροτίωνα πρεσβευτὰς ὡς Μαύσωλον, ὡς ἔθεσαν τὴν ἱκετηρίαν ὧν ἦν τὰ χρήμαθ’ ἅνθρωποι, ὡς ἀπεχειροτονήσαθ’ ὑμεῖς μὴ φίλι’ εἶναι τότε, ἀνέμνησεν ὑμᾶς, τοὺς νόμους ἀνέγνω καθ’ οὓς τοῦτον τὸν τρόπον πραχθέντων τῆς πόλεως γίγνεται τὰ χρήματα.", "st": "24.12"}, {"sp": "N", "t": "ἐδόκει δίκαια λέγειν ὑμῖν ἅπασιν. ἀναπηδήσας Ἀνδροτίων καὶ Γλαυκέτης καὶ Μελάνωπος (καὶ ταυτὶ σκοπεῖτ’ ἂν ἀληθῆ λέγω) ἐβόων, ἠγανάκτουν, ἐλοιδοροῦντο, ἀπέλυον τοὺς τριηράρχους, ἔχειν ὡμολόγουν, παρ’ ἑαυτοῖς ζητεῖν ἠξίουν τὰ χρήματα. ταῦτ’ ἀκουσάντων ὑμῶν, ἐπειδή ποτ’ ἐπαύσανθ’ οὗτοι βοῶντες, ἔδωκε γνώμην Εὐκτήμων ὡς δυνατὸν δικαιοτάτην, ὑμᾶς μὲν εἰσπράττειν τοὺς τριηράρχους, ἐκείνοις δ’ εἶναι περὶ αὐτῶν εἰς τοὺς ἔχοντας ἀναφοράν· ἐὰν δ’ ἀμφισβητῆταί τι, ποιεῖν διαδικασίαν, τὸν δ’ ἡττηθέντα, τοῦτον ὀφείλειν τῇ πόλει.", "st": "24.13"}, {"sp": "N", "t": "γράφονται τὸ ψήφισμα· εἰς ὑμᾶς εἰσῆλθεν· ἵνα συντέμω, κατὰ τοὺς νόμους ἔδοξεν εἰρῆσθαι καὶ ἀπέφυγεν. ἐνταῦθα τί προσῆκεν; τὰ μὲν χρήματ’ ἔχειν τὴν πόλιν, τὸν δ’ ἀποστεροῦντα κολάζειν· νόμου δ’ οὐδ’ ὁτιοῦν οὐδενὸς δήπου προσέδει. μέχρι μὲν δὴ τούτων οὐδὲν ἠδίκησθ’ ὑπὸ Τιμοκράτους τουτουί. μετὰ ταῦτα δὲ πάντ’ ἀνεδέξατ’ ἐφ’ αὑτὸν τὰ προειρημένα, καὶ πάντ’ ἠδικημένοι φανήσεσθ’ ὑπὸ τούτου· ταῖς γὰρ ἐκείνων τέχναις καὶ πανουργίαις μισθώσας αὑτὸν καὶ παρασχὼν ὑπηρέτην ἐφ’ αὑτὸν ἤγαγεν τἀδικήματα, ὡς ἐγὼ σαφῶς ὑμῖν ἐπιδείξω.", "st": "24.14"}, {"sp": "N", "t": "ἀνάγκη δὲ πρῶτον ὑπομνῆσαι τοὺς χρόνους ὑμᾶς καὶ τὸν καιρὸν ἐν ᾧ τίθησι τὸν νόμον· καὶ γὰρ ὑβριστικῶς προσεκκεχλευακὼς ὑμᾶς φανήσεται. ἦν μὲν γὰρ σκιροφοριὼν μὴν ἐν ᾧ τὰς γραφὰς ἥττηντ’ ἐκεῖνοι τὰς κατὰ τοῦ Εὐκτήμονος· μισθωσάμενοι δὲ τοῦτον καὶ οὐδὲ παρεσκευασμένοι τὰ δίκαια ποιεῖν ὑμῖν κατὰ τὴν ἀγορὰν λογοποιοὺς καθίεσαν ὡς ἁπλᾶ μὲν ἕτοιμοι τὰ χρήματ’ ἐκτίνειν, διπλᾶ δ’ οὐ δυνήσονται.", "st": "24.15"}, {"sp": "N", "t": "ἦν δὲ ταῦτ’ ἐνέδρα μετὰ χλευασίας καὶ κατασκευασμὸς ὑπὲρ τοῦ λαθεῖν τόνδε τὸν νόμον τεθέντα. μαρτυρεῖ δ’ ὅτι ταῦθ’ οὕτως ἔχει τοὔργον αὐτό· τῶν μὲν γὰρ χρημάτων ἐκείνοις τοῖς χρόνοις δραχμὴν οὐ κατέθηκαν ὑμῖν, νόμῳ δ’ ἑνὶ πλείστους ὑπάρχοντας ἀκύρους ἐποίησαν, καὶ τούτῳ τῶν πώποτ’ ἐν ὑμῖν τεθέντων αἰσχίστῳ καὶ δεινοτάτῳ.", "st": "24.16"}, {"sp": "N", "t": "βούλομαι δὴ μικρὰ διεξελθὼν περὶ τῶν κειμένων νόμων, καθ’ οὕς εἰσιν αἱ τοιαίδε γραφαί, περὶ αὐτοῦ τοῦ νόμου λέγειν ὃν γέγραμμαι· γενήσεσθε γὰρ εὐμαθέστεροι πρὸς τὰ λοιπὰ ταῦτα προακούσαντες. ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, ἐν τοῖς οὖσι νόμοις ἡμῖν κυρίοις διωρισμέν’ ἀκριβῶς καὶ σαφῶς πάνθ’ ὅσα δεῖ ποιεῖν περὶ τῶν μελλόντων τεθήσεσθαι νόμων.", "st": "24.17"}, {"sp": "N", "t": "καὶ πρῶτον μὲν ἁπάντων χρόνος ἐστὶ γεγραμμένος, ἐν ᾧ προσήκει νομοθετεῖν· εἶτ’ οὐδὲ τόθ’ ὡς ἂν ἑκάστῳ δοκῇ δέδωκε τοῦτο πράττειν, ἀλλὰ προστάττει πρῶτον μὲν ἐκθεῖναι πρόσθεν τῶν ἐπωνύμων γράψαντα σκοπεῖν τῷ βουλομένῳ, μετὰ ταῦτ’ ἐπὶ πᾶσι τὸν αὐτὸν νόμον τιθέναι κελεύει, πρὸς τούτοις λύειν τοὺς ἐναντίους, ἄλλα περὶ ὧν οὐδὲν ἴσως ὑμᾶς κατεπείγει νῦν ἀκοῦσαι. ἂν δέ τις τούτων ἓν παραβῇ, τῷ βουλομένῳ δίδωσι γράφεσθαι.", "st": "24.18"}, {"sp": "N", "t": "εἰ μὲν οὖν μὴ πᾶσιν ἦν ἔνοχος τούτοις Τιμοκράτης, καὶ παρὰ πάντα ταῦτ’ εἰσενηνόχει τὸν νόμον, ἓν ἂν αὐτοῦ τις ἐποιεῖτο κατηγόρημα, ὅ τι δήποτε τοῦτ’ ἦν· νῦν δ’ ἀνάγκη καθ’ ἕκαστον, χωρὶς περὶ ἑκάστου διελόμενον, λέγειν. πρῶτον μὲν οὖν, ὅπερ ἠδίκησε πρῶτον, τοῦτ’ ἐρῶ, ὡς παρὰ πάντας τοὺς νόμους ἐνομοθέτει, εἶτα τῶν ἄλλων ἑξῆς ὅ τι ἂν βουλομένοις ὑμῖν ἀκούειν ᾖ. καί μοι λαβὲ τουτουσὶ τοὺς νόμους καὶ ἀνάγνωθι· φανήσεται γὰρ τούτων οὐδὲν πεποιηκώς. προσέχετ’, ἄνδρες δικασταί, τὸν νοῦν ἀναγιγνωσκομένοις τοῖς νόμοις.", "st": "24.19"}, {"sp": "N", "t": "ΕΠΙΧΕΙΡΟΤΟΝΙΑ ΝΟΜΩΝ.", "st": "24.19"}, {"sp": "N", "t": "ἐπὶ δὲ τῆς πρώτης πρυτανείας τῇ ἑνδεκάτῃ ἐν τῷ δήμῳ, ἐπειδὰν εὔξηται ὁ κῆρυξ, ἐπιχειροτονίαν ποιεῖν τῶν νόμων, πρῶτον μὲν περὶ τῶν βουλευτικῶν, δεύτερον δὲ τῶν κοινῶν, εἶτα οἳ κεῖνται τοῖς ἐννέα ἄρχουσιν, εἶτα τῶν ἄλλων ἀρχῶν. ἡ δὲ χειροτονία ἔστω ἡ προτέρα, ὅτῳ δοκοῦσιν ἀρκεῖν οἱ νόμοι οἱ βουλευτικοί, ἡ δ’ ὑστέρα, ὅτῳ μὴ δοκοῦσιν· εἶτα τῶν κοινῶν κατὰ ταὐτά. τὴν δ’ ἐπιχειροτονίαν εἶναι τῶν νόμων κατὰ τοὺς νόμους τοὺς κειμένους.", "st": "24.20"}, {"sp": "N", "t": "ἐὰν δέ τινες τῶν νόμων τῶν κειμένων ἀποχειροτονηθῶσι, τοὺς πρυτάνεις, ἐφ’ ὧν ἂν ἡ ἐπιχειροτονία γένηται, ποιεῖν περὶ τῶν ἀποχειροτονηθέντων τὴν τελευταίαν τῶν τριῶν ἐκκλησιῶν· τοὺς δὲ προέδρους, οἳ ἂν τυγχάνωσι προεδρεύοντες ἐν ταύτῃ τῇ ἐκκλησίᾳ, χρηματίζειν ἐπάναγκες πρῶτον μετὰ τὰ ἱερὰ περὶ τῶν νομοθετῶν, καθ’ ὅ τι καθεδοῦνται, καὶ περὶ τοῦ ἀργυρίου, ὁπόθεν τοῖς νομοθέταις ἔσται· τοὺς δὲ νομοθέτας εἶναι ἐκ τῶν ὀμωμοκότων τὸν ἡλιαστικὸν ὅρκον.", "st": "24.21"}, {"sp": "N", "t": "ἐὰν δ’ οἱ πρυτάνεις μὴ ποιήσωσι κατὰ τὰ γεγραμμένα τὴν ἐκκλησίαν ἢ οἱ πρόεδροι μὴ χρηματίσωσι, ὀφείλειν τῶν μὲν πρυτάνεων ἕκαστον χιλίας δραχμὰς ἱερὰς τῇ Ἀθηνᾷ, τῶν δὲ προέδρων ἕκαστος ὀφειλέτω τετταράκοντα δραχμὰς ἱερὰς τῇ Ἀθηνᾷ. καὶ ἔνδειξις αὐτῶν ἔστω πρὸς τοὺς θεσμοθέτας, καθάπερ ἐάν τις ἄρχῃ ὀφείλων τῷ δημοσίῳ· οἱ δὲ θεσμοθέται τοὺς ἐνδειχθέντας εἰσαγόντων εἰς τὸ δικαστήριον κατὰ τὸν νόμον, ἢ μὴ ἀνιόντων εἰς Ἄρειον πάγον, ὡς καταλύοντες τὴν ἐπανόρθωσιν τῶν νόμων.", "st": "24.22"}, {"sp": "N", "t": "πρὸ δὲ τῆς ἐκκλησίας ὁ βουλόμενος Ἀθηναίων ἐκτιθέτω πρόσθεν τῶν ἐπωνύμων γράψας τοὺς νόμους οὓς ἂν τιθῇ, ὅπως ἂν πρὸς τὸ πλῆθος τῶν ἐκτεθέντων νόμων ψηφίσηται ὁ δῆμος περὶ τοῦ χρόνου τοῖς νομοθέταις. ὁ δὲ τιθεὶς τὸν καινὸν νόμον ἀναγράψας εἰς λεύκωμα ἐκτιθέτω πρόσθεν τῶν ἐπωνύμων ὁσημέραι, ἕως ἂν ⟨ἡ⟩ ἐκκλησία γένηται. αἱρεῖσθαι δὲ καὶ τοὺς συναπολογησομένους τὸν δῆμον τοῖς νόμοις, οἳ ἂν ἐν τοῖς νομοθέταις λύωνται, πέντε ἄνδρας ἐξ Ἀθηναίων ἁπάντων, τῇ ἑνδεκάτῃ τοῦ ἑκατομβαιῶνος μηνός.", "st": "24.23"}, {"sp": "N", "t": "οὗτοι πάντες οἱ νόμοι κεῖνται πολὺν ἤδη χρόνον, ὦ ἄνδρες δικασταί, καὶ πεῖραν αὑτῶν πολλάκις δεδώκασ’ ὅτι συμφέροντες ὑμῖν εἰσιν, καὶ οὐδεὶς πώποτ’ ἀντεῖπεν μὴ οὐ καλῶς ἔχειν αὐτούς. εἰκότως· οὐδὲν γὰρ ὠμὸν οὐδὲ βίαιον οὐδ’ ὀλιγαρχικὸν προστάττουσιν, ἀλλὰ τοὐναντίον πάντα φιλανθρώπως καὶ δημοτικῶς φράζουσι πράττειν.", "st": "24.24"}, {"sp": "N", "t": "καὶ πρῶτον μὲν ἐφ’ ὑμῖν ἐποίησαν διαχειροτονίαν, πότερον εἰσοιστέος ἐστὶ νόμος καινὸς ἢ δοκοῦσιν ἀρκεῖν οἱ κείμενοι· μετὰ ταῦτα δέ, ἂν χειροτονῆτ’ εἰσφέρειν, οὐκ εὐθὺς τιθέναι προσέταξαν, ἀλλὰ τὴν τρίτην ἀπέδειξαν ἐκκλησίαν, καὶ οὐδ’ ἐν ταύτῃ τιθέναι δεδώκασιν, ἀλλὰ σκέψασθαι καθ’ ὅ τι τοὺς νομοθέτας καθιεῖτε. ἐν δὲ τῷ μεταξὺ χρόνῳ τούτῳ προσέταξαν τοῖς βουλομένοις εἰσφέρειν ἐκτιθέναι τοὺς νόμους πρόσθεν τῶν ἐπωνύμων, ἵν’ ὁ βουλόμενος σκέψηται, κἂν ἀσύμφορον ὑμῖν κατίδῃ τι, φράσῃ καὶ κατὰ σχολὴν ἀντείπῃ.", "st": "24.25"}, {"sp": "N", "t": "τούτων μέντοι τοσούτων ὄντων οὐδὲν πεποίηκε Τιμοκράτης οὑτοσί· οὔτε γὰρ ἐξέθηκε τὸν νόμον, οὔτ’ ἔδωκεν εἴ τις ἐβούλετ’ ἀναγνοὺς ἀντειπεῖν, οὔτ’ ἀνέμεινεν οὐδένα τῶν τεταγμένων χρόνων ἐν τοῖς νόμοις, ἀλλὰ τῆς ἐκκλησίας, ἐν ᾗ τοὺς νόμους ἐπεχειροτονήσατε, οὔσης ἑνδεκάτῃ τοῦ ἑκατομβαιῶνος μηνός, δωδεκάτῃ τὸν νόμον εἰσήνεγκεν, εὐθὺς τῇ ὑστεραίᾳ, καὶ ταῦτ’ ὄντων Κρονίων καὶ διὰ ταῦτ’ ἀφειμένης τῆς βουλῆς, διαπραξάμενος μετὰ τῶν ὑμῖν ἐπιβουλευόντων καθέζεσθαι νομοθέτας διὰ ψηφίσματος ἐπὶ τῇ τῶν Παναθηναίων προφάσει.", "st": "24.26"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν τὸ ψήφισμ’ αὔτ’ ἀναγνῶναι τὸ νικῆσαν, ἵν’ ἴδηθ’ ὅτι πάντα συνταξάμενοι καὶ οὐδὲν ἀπὸ ταὐτομάτου τούτων ἔπραττον. λαβὲ τὸ ψήφισμ’ αὐτοῖς καὶ ἀναγίγνωσκε σύ.", "st": "24.27"}, {"sp": "N", "t": "ΨΗΦΙΣΜΑ.", "st": "24.27"}, {"sp": "N", "t": "ἐπὶ τῆς Πανδιονίδος πρώτης, ἑνδεκάτῃ τῆς πρυτανείας, Ἐπικράτης εἶπεν, ὅπως ἂν τὰ ἱερὰ θύηται καὶ ἡ διοίκησις ἱκανὴ γένηται καὶ εἴ τινος ἐνδεῖ πρὸς τὰ Παναθήναια διοικηθῇ, τοὺς πρυτάνεις τοὺς τῆς Πανδιονίδος καθίσαι νομοθέτας αὔριον, τοὺς δὲ νομοθέτας εἶναι ἕνα καὶ χιλίους ἐκ τῶν ὀμωμοκότων, συννομοθετεῖν δὲ καὶ τὴν βουλήν.", "st": "24.27"}, {"sp": "N", "t": "ἐνθυμήθητε ἀναγιγνωσκομένου τοῦ ψηφίσματος ὡς τεχνικῶς ὁ γράφων αὐτὸ τὴν διοίκησιν καὶ τὸ τῆς ἑορτῆς προστησάμενος κατεπεῖγον, ἀνελὼν τὸν ἐκ τῶν νόμων χρόνον, αὐτὸς ἔγραψεν αὔριον νομοθετεῖν, οὐ μὰ Δί’ οὐχ ἵν’ ὡς κάλλιστα γένοιτό τι τῶν περὶ τὴν ἑορτήν (οὐδὲ γὰρ ἦν ὑπόλοιπον οὐδ’ ἀδιοίκητον οὐδέν), ἀλλ’ ἵνα μὴ προαισθομένου μηδενὸς ἀνθρώπων μηδ’ ἀντειπόντος τεθείη καὶ γένοιτο κύριος αὐτοῖς ὅδ’ ὁ νῦν ἀγωνιζόμενος νόμος.", "st": "24.28"}, {"sp": "N", "t": "τεκμήριον δέ· καθεζομένων γὰρ τῶν νομοθετῶν, περὶ μὲν τούτων, τῆς διοικήσεως καὶ τῶν Παναθηναίων, οὔτε χείρον’ οὔτε βελτίω νόμον οὐδέν’ εἰσήνεγκεν οὐδείς, περὶ δ’ ὧν οὔτε τὸ ψήφισμ’ ἐκέλευεν οἵ τε νόμοι κωλύουσιν, Τιμοκράτης οὑτοσὶ κατὰ πολλὴν ἡσυχίαν ἐνομοθέτει, κυριώτερον μὲν νομίσας τὸν ἐκ τοῦ ψηφίσματος ἢ τὸν ἐν τοῖς νόμοις εἰρημένον χρόνον, οὐδ’ ὁτιοῦν δὲ φοβηθεὶς εἰ ἁπάντων ὑμῶν ἀγόντων ἱερομηνίαν, καὶ νόμου κειμένου μήτ’ ἰδίᾳ μήτε κοινῇ μηδὲν ἀλλήλους ἀδικεῖν ἐν τούτῳ τῷ χρόνῳ, μηδὲ χρηματίζειν ὅ τι ἂν μὴ περὶ τῆς ἑορτῆς ᾖ, αὐτὸς οὐχ ἕνα τὸν τυχόντα, ἀλλ’ ὅλην ἀδικῶν φανήσεται τὴν πόλιν.", "st": "24.29"}, {"sp": "N", "t": "καίτοι πῶς οὐ δεινόν, εἰδότα μὲν τοὺς νόμους, ὧν ὀλίγῳ πρότερον πάντες ἠκούσατε, κυρίους ὄντας, εἰδότα δ’ οὐκ ἐῶνθ’ ἕτερον νόμον ψήφισμ’ οὐδέν, οὐδ’ ἂν ἔννομον ᾖ, νόμου κυριώτερον εἶναι, γράψαι καὶ θεῖναι νόμον ὑμῖν κατὰ ψήφισμα, ὃ καὶ αὐτὸ παρὰ τοὺς νόμους εἰρημένον ᾔδει;", "st": "24.30"}, {"sp": "N", "t": "ἢ πῶς οὐ σχέτλιον τὴν μὲν πόλιν [αὐτὴν] ἑκάστῳ ἡμῶν δεδωκέναι ἄδειαν τοῦ μή τι παθεῖν ἀηδὲς ἢ δεινὸν ἐν τούτῳ τῷ χρόνῳ ποιήσασαν ἱερομηνίαν, αὐτὴν δὲ μὴ τετυχηκέναι ταύτης τῆς ἀσφαλείας παρὰ Τιμοκράτους, ἀλλ’ ἐν αὐτῇ τῇ ἱερομηνίᾳ τὰ μέγιστ’ ἠδικῆσθαι; τί γὰρ ἄν τις μεῖζον ἠδίκησ’ ἰδιώτης ἀνὴρ ἢ καταλύων τοὺς νόμους αὐτῆς, δι’ ὧν οἰκεῖται;", "st": "24.31"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν οὐδὲν ὧν προσῆκέν τε καὶ κελεύουσιν οἱ νόμοι πεποίηκεν, εἰς τὰ προειρημένα τις σκοπῶν ἂν γνοίη. ὅτι δ’ οὐ μόνον κατὰ τοῦτ’ ἀδικεῖ, εἰ παραβὰς τὸν χρόνον τὸν ἐκ τῶν νόμων καὶ τὸ βουλεύσασθαι καὶ σκέψασθαι περὶ τούτων ὑμᾶς παντελῶς ἀνελὼν οὔσης ἱερομηνίας ἐνομοθέτει, ἀλλὰ καὶ κατ’ ἐκεῖνο, ὅτι πᾶσιν ἐναντίον εἰσενήνοχεν τοῖς οὖσι νόμοις, αὐτίκα δὴ μάλ’ ἀκριβῶς μαθήσεσθε. ἀνάγνωθι δέ μοι λαβὼν τουτονὶ πρῶτον τὸν νόμον, ὃς διαρρήδην οὐκ ἐᾷ νόμον οὐδέν’ ἐναντίον εἰσφέρειν, ἐὰν δέ τις εἰσφέρῃ, γράφεσθαι κελεύει. ἀναγίγνωσκε.", "st": "24.32"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.32"}, {"sp": "N", "t": "τῶν δὲ νόμων τῶν κειμένων μὴ ἐξεῖναι λῦσαι μηδένα, ἐὰν μὴ ἐν νομοθέταις. τότε δ’ ἐξεῖναι τῷ βουλομένῳ Ἀθηναίων λύειν, ἕτερον τιθέντι ἀνθ’ ὅτου ἂν λύῃ. διαχειροτονίαν δὲ ποιεῖν τοὺς προέδρους περὶ τούτων τῶν νόμων, πρῶτον μὲν περὶ τοῦ κειμένου, εἰ δοκεῖ ἐπιτήδειος εἶναι τῷ δήμῳ τῷ Ἀθηναίων ἢ οὔ, ἔπειτα περὶ τοῦ τιθεμένου. ὁπότερον δ’ ἂν χειροτονήσωσιν οἱ νομοθέται, τοῦτον κύριον εἶναι. ἐναντίον δὲ νόμον μὴ ἐξεῖναι τιθέναι τῶν νόμων τῶν κειμένων μηδενί. ἐὰν δέ τις λύσας τινὰ τῶν νόμων τῶν κειμένων ἕτερον ἀντιθῇ μὴ ἐπιτήδειον τῷ δήμῳ τῷ Ἀθηναίων ἢ ἐναντίον τῶν κειμένων τῳ, τὰς γραφὰς εἶναι κατ’ αὐτοῦ κατὰ τὸν νόμον ὃς κεῖται ἐάν τις μὴ ἐπιτήδειον θῇ νόμον.", "st": "24.33"}, {"sp": "N", "t": "ἠκούσατε μὲν τοῦ νόμου· πολλῶν δὲ καλῶς κειμένων νόμων τῇ πόλει οὐδενὸς ἧττον ἡγοῦμαι καὶ τοῦτον ἀξίως ἐπαίνου γεγράφθαι. σκέψασθε γὰρ ὡς δικαίως καὶ σφόδρ’ ὑπὲρ τοῦ δήμου κεῖται. οὐκ ἐᾷ τοῖς ὑπάρχουσι νόμοις ἐναντίον εἰσφέρειν, ἐὰν μὴ λύσῃ τὸν πρότερον κείμενον. τίνος εἵνεκα; πρῶτον μὲν ἵν’ ὑμῖν ἐξῇ τὰ δίκαια ψηφίζεσθαι μετ’ εὐσεβείας.", "st": "24.34"}, {"sp": "N", "t": "εἰ γὰρ εἴησαν δύ’ ἐναντίοι νόμοι, καί τινες ἀντίδικοι παρ’ ὑμῖν ἀγωνίζοιντο ἢ περὶ δημοσίων ἢ περὶ ἰδίων πραγμάτων, ἀξιοίη δ’ ἑκάτερος νικᾶν μὴ τὸν αὐτὸν δεικνύων νόμον, οὔτ’ ἀμφοτέροις ἔνι δήπου ψηφίσασθαι· πῶς γάρ; οὔτε θατέρῳ ψηφιζομένους εὐορκεῖν· παρὰ γὰρ τὸν ἐναντίον, ὄντα δ’ ὁμοίως κύριον, ἡ γνῶσις συμβαίνει.", "st": "24.35"}, {"sp": "N", "t": "τοῦτό τ’ οὖν ὑπὲρ ὑμῶν φυλαττόμενος ταῦτα προεῖπε καὶ ἔτι πρὸς τούτῳ βουλόμενος φύλακας ὑμᾶς τῶν νόμων καταστῆσαι· ᾔδει γὰρ ἐκεῖνο, ὅτι τὰς ἄλλας ἃς γέγραφ’ αὐτῶν φυλακὰς ἔστι πολλαχῇ διακρούσασθαι. τοὺς συνηγόρους, οὓς χειροτονεῖτε, δύναιτ’ ἂν πεῖσαί τις σιωπᾶν. ἐκτιθέναι κελεύει τοῦ προειδέναι πάντας· τάχ’ ἄν, εἰ τύχοι, τοὺς μὲν ἀντειπόντας ἂν εἰ [μὴ] προαίσθοιντο, λάθοι, οἱ δ’ οὐδὲν προσέχοντες ἀναγνοῖεν ἄν.", "st": "24.36"}, {"sp": "N", "t": "ἀλλὰ γράψασθαι νὴ Δί’ ἕκαστον ἔστιν, ὃ κἀγὼ νυνὶ πεποίηκα· κἀνταῦθα, ἂν ἀπαλλάξῃ τις τὸν ἐπιστάντα, ἡ πόλις παρακέκρουσται. τίς οὖν μόνη φυλακὴ καὶ δικαία καὶ βέβαιος τῶν νόμων; ὑμεῖς οἱ πολλοί· οὔτε γὰρ τὸ γνῶναι καὶ δοκιμάσαι τὸ βέλτιστον ἐξελέσθαι δύναιτ’ ἂν ὑμῶν οὐδὲ εἷς, οὔτ’ ἀπαλλάξας καὶ διαφθείρας πεῖσαι τὸν χείρω θέσθαι νόμον ἀντὶ τοῦ κρείττονος.", "st": "24.37"}, {"sp": "N", "t": "διὰ ταῦτα πάντ’ ἐφ’ ἑκάστην ἀπαντᾷ τὴν ὁδὸν τῶν ἀδικημάτων, κωλύων καὶ οὐκ ἐῶν βαδίζειν τοὺς ἐπιβουλεύοντας ὑμῖν. ταῦτα πάντα Τιμοκράτης, οὕτω καλῶς καὶ δικαίως κείμενα, ἠφάνισεν, ἐξήλειψεν, ὅσον ἦν ἐπὶ τούτῳ, καὶ νόμον εἰσήνεγκεν ἅπασιν ἐναντίον, ὡς ἔπος εἰπεῖν, τοῖς οὖσιν, οὐ παραναγνούς, οὐ λύσας, οὐ δοὺς αἵρεσιν, οὐκ ἄλλο ποιήσας οὐδὲν τῶν προσηκόντων.", "st": "24.38"}, {"sp": "N", "t": "ὡς μὲν οὖν ἔνοχος τῇ γραφῇ καθέστηκεν, ἐναντίον εἰσενηνοχὼς τοῖς οὖσι νόμοις, οἶμαι πάντας ὑμᾶς ᾐσθῆσθαι· ἵνα δ’ εἰδῆτε παρ’ οἵους νόμους οἷον οὗτος εἰσήνεγκεν, ἀναγνώσεται πρῶτον ὑμῖν τὸν τούτου νόμον, εἶτα τοὺς ἄλλους, οἷς οὗτος ἐναντίος ἐστίν. ἀναγίγνωσκε.", "st": "24.39"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.39"}, {"sp": "N", "t": "ἐπὶ τῆς Πανδιονίδος πρώτης, δωδεκάτῃ τῆς πρυτανείας, Τιμοκράτης εἶπεν, καὶ εἴ τινι τῶν ὀφειλόντων τῷ δημοσίῳ προστετίμηται κατὰ νόμον ἢ κατὰ ψήφισμα δεσμοῦ ἢ τὸ λοιπὸν προστιμηθῇ, εἶναι αὐτῷ ἢ ἄλλῳ ὑπὲρ ἐκείνου ἐγγυητὰς καταστῆσαι τοῦ ὀφλήματος, οὓς ἂν ὁ δῆμος χειροτονήσῃ, ἦ μὴν ἐκτείσειν τὸ ἀργύριον ὃ ὦφλεν. τοὺς δὲ προέδρους ἐπιχειροτονεῖν ἐπάναγκες, ὅταν τις καθιστάναι βούληται.", "st": "24.39"}, {"sp": "N", "t": "τῷ δὲ καταστήσαντι τοὺς ἐγγυητάς, ἐὰν ἀποδιδῷ τῇ πόλει τὸ ἀργύριον ἐφ’ ᾧ κατέστησε τοὺς ἐγγυητάς, ἀφεῖσθαι τοῦ δεσμοῦ. ἐὰν δὲ μὴ καταβάλῃ τὸ ἀργύριον ἢ αὐτὸς ἢ οἱ ἐγγυηταὶ ἐπὶ τῆς ἐνάτης πρυτανείας, τὸν μὲν ἐξεγγυηθέντα δεδέσθαι, τῶν δὲ ἐγγυητῶν δημοσίαν εἶναι τὴν οὐσίαν. περὶ δὲ τῶν ὠνουμένων τὰ τέλη καὶ τῶν ἐγγυωμένων καὶ ἐκλεγόντων, καὶ τῶν τὰ μισθώσιμα μισθουμένων καὶ ἐγγυωμένων, τὰς πράξεις εἶναι τῇ πόλει κατὰ τοὺς νόμους τοὺς κειμένους. ἐὰν δ’ ἐπὶ τῆς ἐνάτης ἢ δεκάτης πρυτανείας ὄφλῃ, τοῦ ὑστέρου ἐνιαυτοῦ ἐπὶ τῆς ἐνάτης πρυτανείας ἐκτίνειν.", "st": "24.40"}, {"sp": "N", "t": "ἀκηκόατε μὲν τοῦ νόμου, μνημονεύετε δ’ ἐξ αὐτοῦ μοι πρῶτον μὲν τὸ “καὶ εἴ τινι τῶν ὀφειλόντων δεσμοῦ προστετίμηται ἢ τὸ λοιπὸν προστιμηθῇ,” ἔπειθ’ ὅτι πλὴν περὶ τῶν τελωνῶν καὶ περὶ τῶν μισθουμένων, καὶ ὅσοι ταῦτ’ ἐγγυῶνται, χρῆσθαι κελεύει τῷ νόμῳ. ὅλος μὲν γάρ ἐστιν ἅπασιν ἐναντίος τοῖς οὖσι, μάλιστα δὲ ταῦτα· γνώσεσθε δὲ τοὺς νόμους ἀκούοντες αὐτούς. λέγε.", "st": "24.41"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.41"}, {"sp": "N", "t": "Διοκλῆς εἶπεν· τοὺς νόμους τοὺς πρὸ Εὐκλείδου τεθέντας ἐν δημοκρατίᾳ καὶ ὅσοι ἐπ’ Εὐκλείδου ἐτέθησαν καὶ εἰσὶν ἀναγεγραμμένοι, κυρίους εἶναι. τοὺς δὲ μετ’ Εὐκλείδην τεθέντας καὶ τὸ λοιπὸν τιθεμένους κυρίους εἶναι ἀπὸ τῆς ἡμέρας ἧς ἕκαστος ἐτέθη, πλὴν εἴ τῳ προσγέγραπται χρόνος ὅντινα δεῖ ἄρχειν. ἐπιγράψαι δὲ τοῖς μὲν νῦν κειμένοις τὸν γραμματέα τῆς βουλῆς τριάκοντα ἡμερῶν· τὸ δὲ λοιπόν, ὃς ἂν τυγχάνῃ γραμματεύων, προσγραφέτω παραχρῆμα τὸν νόμον κύριον εἶναι ἀπὸ τῆς ἡμέρας ἧς ἐτέθη.", "st": "24.42"}, {"sp": "N", "t": "καλῶς ἐχόντων τῶν νόμων, ὦ ἄνδρες δικασταί, τῶν ὑπαρχόντων, ὅδ’ ὁ νῦν ἀναγνωσθεὶς νόμος ὡσπερεὶ διώρισεν καὶ βεβαιοτέρους ἐποίησεν αὐτούς. κελεύει γὰρ ἕκαστον ἀφ’ ἧς ἡμέρας ἐτέθη κύριον εἶναι, πλὴν εἴ τῳ χρόνος προσγέγραπται, τούτῳ δὲ τὸν γεγραμμένον ἄρχειν. διὰ τί; ὅτι πολλοῖς τῶν νόμων προσεγέγραπτο “τὸν δὲ νόμον εἶναι κύριον τόνδ’ ἀπὸ τοῦ μετὰ τὸν νῦν ἄρχοντα.” ὕστερον δὲ γράφων ὁ τιθεὶς ἐπὶ τούτοις τόνδε τὸν νόμον τὸν ἀνεγνωσμένον, οὐκ ἐνόμιζε δίκαιον εἶναι τοὺς αὐτοὺς τῶν νόμων ἀναγεγραμμένους ὕστερον ἢ ἐτέθησαν κυρίους εἶναι ἀνενεγκεῖν ἐπὶ τὴν ἡμέραν, ἀφ’ ἧς ἐτέθησαν, καὶ πρότερον ποιῆσαι κυρίους ἢ ὁ θεὶς ἕκαστον ἠξίωσεν.", "st": "24.43"}, {"sp": "N", "t": "τούτῳ μέντοι τῷ νόμῳ σκέψασθ’ ὡς ἐναντίος ἐστὶν ὃν οὗτος τέθηκεν. ὁ μέν γε κελεύει τὸν γεγραμμένον χρόνον ἢ τὴν ἡμέραν ἀφ’ ἧς ἂν τεθῇ κυρίαν εἶναι· ὁ δ’ ἔγραψεν “καὶ εἴ τινι προστετίμηται,” περὶ τῶν παρεληλυθότων λέγων. καὶ οὐδὲ τοῦθ’ ὥρισεν, ἄρχοντα προσγράψας ἀφ’ οὗ, ἀλλὰ πεποίηκεν οὐ μόνον πρὸ τῆς ἡμέρας ἐν ᾗ τέθηκε κύριον τὸν νόμον, ἀλλὰ καὶ πρὸ τοῦ γενέσθαι τιν’ ἡμῶν· ἀόριστον γὰρ ἅπαντα τὸν παρεληλυθότα προσπεριείληφε χρόνον. καίτοι χρῆν σ’, ὦ Τιμόκρατες, ἢ τοῦτον μὴ γράφειν ἢ ἐκεῖνον λύειν, οὐχ, ἵν’ ὃ βούλει σὺ γένηται, πάντα τὰ πράγματα συνταράξαι. λέγ’ ἄλλον νόμον.", "st": "24.44"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.45"}, {"sp": "N", "t": "μηδὲ περὶ τῶν ἀτίμων, ὅπως χρὴ ἐπιτίμους αὐτοὺς εἶναι, μηδὲ περὶ τῶν ὀφειλόντων τοῖς θεοῖς ἢ τῷ δημοσίῳ τῷ Ἀθηναίων περὶ ἀφέσεως τοῦ ὀφλήματος ἢ τάξεως, ἐὰν μὴ ψηφισαμένων Ἀθηναίων τὴν ἄδειαν πρῶτον μὴ ἔλαττον ἑξακισχιλίων, οἷς ἂν δόξῃ κρύβδην ψηφιζομένοις. τότε δ’ ἐξεῖναι χρηματίζειν καθ’ ὅ τι ἂν τῇ βουλῇ καὶ τῷ δήμῳ δοκῇ.", "st": "24.45"}, {"sp": "N", "t": "ἄλλος οὗτος νόμος, οὐκ ἐῶν περὶ τῶν ἀτίμων οὐδὲ τῶν ὀφειλόντων λέγειν οὐδὲ χρηματίζειν περὶ ἀφέσεως τῶν ὀφλημάτων οὐδὲ τάξεως, ἂν μὴ τῆς ἀδείας δοθείσης, καὶ ταύτης μὴ ἔλαττον ἢ ἑξακισχιλίων ψηφισαμένων. οὗτος δ’ ἔγραψεν ἄντικρυς, καὶ εἴ τινι τῶν ὀφειλόντων δεσμοῦ προστετίμηται, εἶναι τὴν ἄφεσιν πορισαμένῳ τοὺς ἐγγυησομένους, οὐ προτεθέντος οὐδενὸς περὶ τούτων, οὐδὲ δοθείσης ἀδείας λέγειν.", "st": "24.46"}, {"sp": "N", "t": "καὶ ὁ μὲν νόμος, οὐδ’ ἐπειδὰν τὴν ἄδειαν εὕρηταί τις, ἔδωκεν ὡς ἂν βούληται πράττειν, ἀλλ’ ὡς ἂν τῇ βουλῇ καὶ τῷ δήμῳ δοκῇ· τῷ δ’ οὐκ ἀπέχρησε τοῦτ’ ἀδικεῖν μόνον, εἰ μὴ δοθείσης τῆς ἀδείας λέγει καὶ νόμον εἰσφέρει περὶ τούτων, ἀλλὰ καὶ προσέτ’ οὐκ εἰς τὴν βουλήν, οὐκ εἰς τὸν δῆμον εἰπὼν περὶ τούτων οὐδέν, ἐν παραβύστῳ, τῆς βουλῆς μὲν ἀφειμένης, τῶν δ’ ἄλλων διὰ τὴν ἑορτὴν ἱερομηνίαν ἀγόντων, λάθρα τὸν νόμον εἰσήνεγκεν.", "st": "24.47"}, {"sp": "N", "t": "καίτοι χρῆν σ’, ὦ Τιμόκρατες, εἰδότα τὸν νόμον τόνδ’ ὃν ἀνέγνω, εἴ τι δίκαιον ἐβούλου πράττειν, πρῶτον μὲν πρόσοδον γράψασθαι πρὸς τὴν βουλήν, εἶτα τῷ δήμῳ διαλεχθῆναι, κᾆθ’ οὕτως, εἰ πᾶσιν Ἀθηναίοις ἐδόκει, γράφειν καὶ νομοθετεῖν περὶ τούτων, καὶ τότε τοὺς χρόνους ἀναμείναντα τοὺς ἐκ τῶν νόμων, ἵνα τοῦτον τὸν τρόπον πράττων, εἰ καί τις ἐπεχείρει δεικνύειν οὐκ ἐπιτήδειον ὄντα τῇ πόλει τὸν νόμον, μὴ οὖν ἐπιβουλεύειν γ’ ἐδόκεις, ἀλλὰ γνώμῃ διαμαρτὼν ἀποτυχεῖν.", "st": "24.48"}, {"sp": "N", "t": "νῦν δὲ τῷ λάθρα καὶ ταχὺ καὶ παρὰ τοὺς νόμους ἐμβαλεῖν τὸν νόμον εἰς τοὺς νόμους καὶ μὴ θεῖναι, πᾶσαν ἀφῄρησαι σαυτοῦ τὴν συγγνώμην· τοῖς γὰρ ἄκουσιν ἁμαρτοῦσι μέτεστι συγγνώμης, οὐ τοῖς ἐπιβουλεύσασιν, ὃ σὺ νῦν εἴληψαι ποιῶν. ἀλλὰ γὰρ αὐτίκ’ ἐρῶ περὶ τούτων. νῦν δ’ ἀναγίγνωσκε τὸν ἑξῆς νόμον.", "st": "24.49"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.50"}, {"sp": "N", "t": "ἐὰν δέ τις ἱκετεύῃ ἐν τῇ βουλῇ ἢ ἐν τῷ δήμῳ περὶ ὧν δικαστήριον ἢ ἡ βουλὴ ἢ ὁ δῆμος κατέγνω, ἐὰν μὲν αὐτὸς ὁ ὀφλὼν ἱκετεύῃ πρὶν ἐκτεῖσαι, ἔνδειξιν εἶναι αὐτοῦ, καθάπερ ἐάν τις ὀφείλων τῷ δημοσίῳ ἡλιάζηται· ἐὰν δ’ ἄλλος ὑπὲρ τοῦ ὠφληκότος ἱκετεύῃ πρὶν ἐκτεῖσαι, δημοσία ἔστω αὐτοῦ ἡ οὐσία ἅπασα. ἐὰν δέ τις τῶν προέδρων δῷ τινι τὴν ἐπιχειροτονίαν, ἢ αὐτῷ τῷ ὠφληκότι ἢ ἄλλῳ ὑπὲρ ἐκείνου, πρὶν ἐκτεῖσαι, ἄτιμος ἔστω.", "st": "24.50"}, {"sp": "N", "t": "ἔστι μὲν ἔργον, ὦ ἄνδρες δικασταί, εἰ περὶ πάντων τῶν νόμων οἷς οὗτος ἐναντίον εἰσενήνοχεν ἐροῦμεν· ἄξιον δ’, εἰ περί του καὶ ἄλλου, καὶ περὶ τοῦδ’ ὃν νῦν ἀνέγνω διελθεῖν. ὁ γὰρ τὸν νόμον τοῦτον, ὦ ἄνδρες Ἀθηναῖοι, θεὶς ᾔδει τὴν φιλανθρωπίαν καὶ τὴν πραότητα τὴν ὑμετέραν, καὶ διὰ ταύτην ἑώρα περὶ πολλῶν ὑμᾶς ἑκόντας ἤδη ποτὲ μεγάλα ζημιωθέντας.", "st": "24.51"}, {"sp": "N", "t": "βουλόμενος δὴ μηδεμίαν πρόφασιν τοῦ τὰ κοινὰ κακῶς ἔχειν ὑπολιπεῖν, τοὺς μετὰ τῶν νόμων κρίσει καὶ δικαστηρίῳ μὴ δίκαια ποιεῖν ἐγνωσμένους οὐκ ᾤετο δεῖν τῆς εὐηθείας τῆς ὑμετέρας ἀπολαύειν, τὸ δεῖσθαι καὶ μετὰ συμφορᾶς ἱκετεύειν ἔχοντας ἀφορμήν, ἀλλ’ ὅλως ἀπεῖπεν μήτ’ αὐτῷ μήτ’ ἄλλῳ μηδενὶ μήθ’ ἱκετεύειν μήτε λέγειν ὑπὲρ τῶν τοιούτων, ἀλλὰ ποιεῖν τὰ δίκαια σιγῇ.", "st": "24.52"}, {"sp": "N", "t": "εἰ τοίνυν τις ἔροιθ’ ὑμᾶς ποτέροις μᾶλλον ἂν εἰκότως ποιήσαιθ’ ὁτιοῦν, τοῖς δεομένοις ἢ τοῖς ἐπιτάττουσιν, οἶδ’ ὅτι φήσαιτ’ ἂν τοῖς δεομένοις· τὸ μὲν γὰρ χρηστῶν, τὸ δ’ ἀνάνδρων ἀνθρώπων ἔργον ἐστίν. οὐκοῦν οἱ νόμοι μὲν ἅπαντες προστάττουσιν ἃ χρὴ ποιεῖν, οἱ τιθέντες δὲ τὰς ἱκετηρίας δέονται. εἰ τοίνυν ἱκετεύειν οὐκ ἔξεστιν, ἦ που νόμον γ’ ἐπίταγμ’ ἔχοντ’ εἰσφέρειν; ἐγὼ μὲν οὐκ οἶμαι. καὶ γὰρ αἰσχρὸν περὶ ὧν μηδὲ χαρίζεσθαι δεῖν ὑπειλήφατε, περὶ τούτων ἀκόντων ὑμῶν ἐᾶν ἅ τινες βούλονται πραχθῆναι.", "st": "24.53"}, {"sp": "N", "t": "λέγε τὸν μετὰ τοῦτον ἐφεξῆς.", "st": "24.53"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.54"}, {"sp": "N", "t": "ὅσων δίκη πρότερον ἐγένετο ἢ εὔθυνα ἢ διαδικασία περί του ἐν δικαστηρίῳ, ἢ ἰδίᾳ ἢ δημοσίᾳ, ἢ τὸ δημόσιον ἀπέδοτο, μὴ εἰσάγειν περὶ τούτων εἰς τὸ δικαστήριον μηδ’ ἐπιψηφίζειν τῶν ἀρχόντων μηδένα, μηδὲ κατηγορεῖν ἐώντων ἃ οὐκ ἐῶσιν οἱ νόμοι.", "st": "24.54"}, {"sp": "N", "t": "Τιμοκράτης τοίνυν, ὥσπερ μαρτυρίαν ὧν ἀδικεῖ γράφων, εὐθὺς ἀρχόμενος τοῦ νόμου τἀναντί’ ἔθηκε τούτοις. ὁ μέν γ’ οὐκ ἐᾷ περὶ ὧν ἂν ἅπαξ γνῷ δικαστήριον πάλιν χρηματίζειν· ὁ δ’ ἔγραψεν, καὶ εἴ τινι προστετίμηται κατὰ νόμον ἢ κατὰ ψήφισμα, τὸν δῆμον τούτῳ χρηματίζειν, ὅπως ἃ μὲν ἔγνω τὸ δικαστήριον λυθήσεται, καταστήσει δ’ ἐγγυητὰς ὁ ὀφλών. καὶ ὁ μὲν νόμος μηδ’ ἐπιψηφίζειν φησὶ τῶν ἀρχόντων παρὰ ταῦτα μηδένα· ὁ δ’ ἔγραψε τοῖς προέδροις ἐπάναγκες, ἐάν τις καθιστῇ, προσάγειν, καὶ προσέγραψεν “ὁπότ’ ἄν τις βούληται.”", "st": "24.55"}, {"sp": "N", "t": "λέγ’ ἄλλον νόμον.", "st": "24.56"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.56"}, {"sp": "N", "t": "τὰς δίκας καὶ τὰς διαίτας, ὅσαι ἐγένοντο ἐπὶ τοῖς νόμοις ἐν δημοκρατουμένῃ τῇ πόλει, κυρίας εἶναι.", "st": "24.56"}, {"sp": "N", "t": "οὔ φησι Τιμοκράτης, οὔκουν ὁπόσοις γ’ ἂν δεσμοῦ προστιμηθῇ.", "st": "24.56"}, {"sp": "N", "t": "λέγε.", "st": "24.56"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.56"}, {"sp": "N", "t": "ὁπόσα δ’ ἐπὶ τῶν τριάκοντα ἐπράχθη ἢ δίκη ἐδικάσθη, ἢ ἰδίᾳ ἢ δημοσίᾳ, ἄκυρα εἶναι.", "st": "24.56"}, {"sp": "N", "t": "ἐπίσχες. εἰπέ μοι, τί δεινότατον πάντες ἂν ἀκούσαντες φήσαιτε, καὶ τί μάλιστ’ ἂν ἀπεύξαισθε; οὐχὶ ταῦτα τὰ πράγμαθ’ ἅπερ ἦν ἐπὶ τῶν τριάκοντα μὴ γενέσθαι; ἔγωγ’ οἶμαι. ὁ γοῦν νόμος οὑτοσί, εὐλαβούμενος, ὡς ἐμοὶ δοκεῖ, τὸ τοιοῦτον ἀπεῖπε τὰ πραχθέντ’ ἐπ’ ἐκείνων μὴ κύρι’ εἶναι. οὑτοσὶ τοίνυν τὴν αὐτὴν κατέγνω παρανομίαν τῶν ἐπὶ τῆς δημοκρατίας πεπραγμένων ἥνπερ τῶν ἐπ’ ἐκείνων ὑμεῖς· ὁμοίως γοῦν ἄκυρα ποιεῖ.", "st": "24.57"}, {"sp": "N", "t": "καίτοι τί φήσομεν, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον κύριον τὸν νόμον ἐάσαντες γενέσθαι; πότερον τὰ δικαστήρια, ἃ δημοκρατουμένης τῆς πόλεως ἐκ τῶν ὀμωμοκότων πληροῦται, ταὔτ’ ἀδικήματα τοῖς ἐπὶ τῶν τριάκοντ’ ἀδικεῖν; καὶ πῶς οὐ δεινόν; ἀλλὰ δικαίως ἐψηφίσθαι; τίνος οὖν εἵνεκα τὸν λύσοντα ταῦτα νόμον θέσθαι φήσομεν; πλὴν εἰ τοῦτό τις εἴποι, μανέντες· ἄλλο γὰρ οὐκ ἔστιν εἰπεῖν.", "st": "24.58"}, {"sp": "N", "t": "λέγ’ ἄλλον νόμον.", "st": "24.59"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.59"}, {"sp": "N", "t": "μηδὲ νόμον ἐξεῖναι ἐπ’ ἀνδρὶ θεῖναι, ἐὰν μὴ τὸν αὐτὸν ἐπὶ πᾶσιν Ἀθηναίοις [τιθῇ] ⟨ἐὰν μὴ⟩ ψηφισαμένων μὴ ἔλαττον ἑξακισχιλίων οἷς ἂν δόξῃ κρύβδην ψηφιζομένοις.", "st": "24.59"}, {"sp": "N", "t": "οὐκ ἐᾷ νόμον ἀλλ’ ἢ τὸν αὐτὸν τιθέναι κατὰ τῶν πολιτῶν πάντων, καλῶς καὶ δημοτικῶς λέγων. ὥσπερ γὰρ τῆς ἄλλης πολιτείας ἴσον μέτεστιν ἑκάστῳ, οὕτω καὶ τούτων ἴσον μετέχειν ἕκαστον ἀξιοῖ. δι’ οὓς μὲν τοίνυν οὗτος εἰσέφερεν, ὑμεῖς οὐδὲν ἐμοῦ χεῖρον γιγνώσκετε· ἄνευ δὲ τούτων αὐτὸς ὡμολόγησεν μὴ ἐπὶ πᾶσι τὸν αὐτὸν τεθηκέναι, πλὴν περὶ τῶν τελωνῶν καὶ τῶν μισθουμένων καὶ τῶν τούτων ἐγγυητῶν χρῆσθαι προσγράψας τῷ νόμῳ. οὐκοῦν ὁπότ’ εἰσίν τινες οὓς ἀφορίζεις, οὐκ ἂν ἔτ’ εἴης ἐπὶ πᾶσιν τὸν αὐτὸν τεθηκώς.", "st": "24.59"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνό γ’ ἂν εἴποις, ὡς ὅσοις δεσμοῦ προστιμᾶται, τούτων μάλιστ’ ἢ τὰ μέγιστ’ ἀδικοῦσιν οἱ τελῶναι, ὥστε μόνοις αὐτοῖς μὴ μεταδοῦναι τοῦ νόμου. πολὺ γὰρ δήπου μᾶλλον οἱ προδιδόντες τι τῶν κοινῶν, οἱ τοὺς γονέας κακοῦντες, οἱ μὴ καθαρὰς τὰς χεῖρας ἔχοντες, εἰσιόντες δ’ εἰς τὴν ἀγοράν, ἀδικοῦσιν. οἷς ἅπασιν οἱ μὲν ὑπάρχοντες νόμοι δεσμὸν προλέγουσιν, ὁ δὲ σὸς λελύσθαι δίδωσιν. ἀλλ’ ἐνταῦθα πάλιν καταμηνύεις ὑπὲρ ὧν ἐτίθεις· διὰ γὰρ τὸ μὴ τελωνήσαντας ὀφείλειν αὐτούς, ἀλλὰ κλέψαντας, μᾶλλον δ’ ἁρπάσαντας τὰ χρήματα, διὰ τοῦτ’ οὐκ ἐφρόντισας, οἶμαι, τῶν τελωνῶν.", "st": "24.60"}, {"sp": "N", "t": "πολλοὺς δ’ ἄν τις ἔχοι νόμους ἔτι καὶ καλῶς ἔχοντας δεικνύναι, οἷς πᾶσιν ἐναντίος ἐστὶν ὃν οὗτος τέθηκεν. ἀλλ’ ἴσως ἐγὼ μέν, εἰ περὶ πάντων ἐρῶ, ἐξωσθήσομαι περὶ τοῦ μηδ’ ἐπιτήδειον ὅλως ὑμῖν εἶναι τὸν νόμον εἰπεῖν, ὑμῖν δ’ ὁμοίως ἔνοχος φανεῖται τῇ γραφῇ, καὶ εἰ ἑνὶ τῶν ὄντων νόμων ἐναντίος ἐστίν. πῶς οὖν μοι δοκεῖ; τοὺς μὲν ἄλλους ἐᾶν, περὶ δ’ οὗ πρότερόν ποτ’ αὐτὸς οὗτος ἔθηκεν νόμου διελθόντ’ ἐπ’ ἐκεῖν’ ἰέναι τὸ μέρος τῆς κατηγορίας ἤδη, ὡς καὶ μεγάλ’ ἂν βλάπτοι γενόμενος κύριος τὴν πόλιν.", "st": "24.61"}, {"sp": "N", "t": "τὸ μὲν οὖν τοῖς τῶν ἄλλων ἐναντίον εἰσενηνοχέναι νόμον δεινὸν μέν, ἀλλ’ ἄλλου δεῖται κατηγόρου· τὸ δ’ ὑφ’ αὑτοῦ πρότερον κειμένῳ νόμῳ τἀναντία θεῖναι, τοῦτ’ ἤδη ποιεῖ κατήγορον αὐτὸν αὑτοῦ γεγενῆσθαι. ἵν’ οὖν τοῦτ’ εἰδῆτε γιγνόμενον, ἀναγνώσεται τὸν νόμον ὑμῖν αὐτὸν ὃν οὗτος ἔθηκεν· ἐγὼ δὲ σιωπήσομαι. λέγε.", "st": "24.62"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.63"}, {"sp": "N", "t": "Τιμοκράτης εἶπεν· ὁπόσοι Ἀθηναίων κατ’ εἰσαγγελίαν ἐκ τῆς βουλῆς ἢ νῦν εἰσιν ἐν τῷ δεσμωτηρίῳ ἢ τὸ λοιπὸν κατατεθῶσι, καὶ μὴ παραδοθῇ ἡ κατάγνωσις αὐτῶν τοῖς θεσμοθέταις ὑπὸ τοῦ γραμματέως τοῦ κατὰ πρυτανείαν κατὰ τὸν εἰσαγγελτικὸν νόμον, δεδόχθαι τοῖς νομοθέταις εἰσάγειν τοὺς ἕνδεκα εἰς τὸ δικαστήριον τριάκονθ’ ἡμερῶν ἀφ’ ἧς ἂν παραλάβωσιν, ἐὰν μή τι δημοσίᾳ κωλύῃ, ἐὰν δὲ μή, ὅταν πρῶτον οἷόν τ’ ᾖ. κατηγορεῖν δ’ Ἀθηναίων τὸν βουλόμενον οἷς ἔξεστιν. ἐὰν δ’ ἁλῷ, τιμάτω ἡ ἡλιαία περὶ αὐτοῦ ὅ τι ἂν δοκῇ ἄξιος εἶναι παθεῖν ἢ ἀποτεῖσαι. ἐὰν δ’ ἀργυρίου τιμηθῇ, δεδέσθω τέως ἂν ἐκτείσῃ ὅ τι ἂν αὐτοῦ καταγνωσθῇ.", "st": "24.63"}, {"sp": "N", "t": "ἀκούετ’, ὦ ἄνδρες δικασταί; λέγ’ αὐτοῖς αὐτὸ τοῦτο πάλιν.", "st": "24.64"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.64"}, {"sp": "N", "t": "ἐὰν δ’ ἀργυρίου τιμηθῇ, δεδέσθω τέως ἂν ἐκτείσῃ.", "st": "24.64"}, {"sp": "N", "t": "πέπαυσο. ἔστιν οὖν ὅπως ἂν ἐναντιώτερά τις δύο θείη τοῦ δεδέσθαι, τέως ἂν ἐκτείσωσι, τοὺς ἁλόντας, καὶ τοῦ καθιστάναι τοὺς αὐτοὺς τούτους ἐγγυητάς, ἀλλὰ μὴ δεῖν; ταῦτα τοίνυν κατηγορεῖ Τιμοκράτης Τιμοκράτους, οὐ Διόδωρος, οὐδ’ ἄλλος ὑμῶν οὐδεὶς τοσούτων ὄντων τὸ πλῆθος.", "st": "24.64"}, {"sp": "N", "t": "καίτοι τίνος ἂν ὑμῖν ἀποσχέσθαι δοκεῖ λήμματος ἢ τί ποιεῖν ἂν ὀκνῆσαι κέρδους εἵνεκα, ὅστις ἐναντί’ αὐτὸς αὑτῷ νομοθετεῖν ἠξίωσεν, οὐδὲ τοῖς ἄλλοις τῶν νόμων ἐώντων; ἐμοὶ μὲν γὰρ εἵνεκ’ ἀναιδείας ὁ τοιοῦτος δοκεῖ πᾶν ἂν ἑτοίμως ἔργον ποιῆσαι. ὥσπερ τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τῶν περὶ τἄλλα κακούργων τοὺς ὁμολογοῦντας ἄνευ κρίσεως κολάζειν οἱ νόμοι κελεύουσιν, οὕτω δίκαιον καὶ τούτου, ἐπειδὴ τοὺς νόμους κακουργῶν εἴληπται, μὴ δόντας λόγον μηδ’ ἐθελήσαντας ἀκοῦσαι καταψηφίσασθαι· ὡμολόγηκε γὰρ θατέρῳ [τῷ προτέρῳ] νόμῳ τόνδε τιθεὶς ἀδικεῖν.", "st": "24.65"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν καὶ παρὰ τούτους τοὺς νόμους καὶ παρὰ τοὺς προειρημένους, καὶ μικροῦ δέω παρὰ πάντας εἰπεῖν τοὺς ὄντας ἐν τῇ πόλει, τέθηκε τὸν νόμον, οἶμαι δῆλον ἅπασιν ὑμῖν εἶναι. θαυμάζω δ’ αὐτοῦ τί ποτε καὶ τολμήσει λέγειν περὶ τούτων. οὔτε γὰρ ὡς οὐκ ἐναντίος ἔσθ’ ὁ νόμος τοῖς ἄλλοις δεικνύειν ἕξει, οὔθ’ ὡς δι’ ἀπειρίαν ἰδιώτην αὐτὸν ὄντα τοῦτ’ ἔλαθεν δύναιτ’ ἂν πεῖσαι· πάλαι γὰρ μισθοῦ καὶ γράφων καὶ νόμους εἰσφέρων ὦπται.", "st": "24.66"}, {"sp": "N", "t": "καὶ μὴν οὐδ’ ἐκεῖνό γ’ ἔνεστιν αὐτῷ, ἀδίκημα μὲν εἶναι τὸ πρᾶγμ’ ὁμολογῆσαι, συγγνώμης δὲ τυχεῖν ἀξιοῦν· οὐ γὰρ ἄκων οὐδ’ ὑπὲρ ἠτυχηκότων οὐδ’ ὑπὲρ συγγενῶν καὶ ἀναγκαίων αὐτῷ τεθηκὼς φαίνεται τὸν νόμον, ἀλλ’ ἑκὼν ὑπὲρ μεγάλ’ ἠδικηκότων ὑμᾶς, οὐδὲν προσηκόντων αὐτῷ, πλὴν εἰ συγγενεῖς ὑπολαμβάνειν φησὶν τοὺς μισθουμένους αὐτόν.", "st": "24.67"}, {"sp": "N", "t": "ὡς τοίνυν οὐδ’ ἐπιτήδειον νόμον ὑμῖν οὐδὲ συμφέροντ’ εἰσενήνοχεν, τοῦτ’ ἤδη πειράσομαι νυνὶ δεικνύειν. οἶμαι δὴ πάντας ἂν ὑμᾶς ὁμολογῆσαι, δεῖν τὸν ὀρθῶς ἔχοντα νόμον καὶ συνοίσειν μέλλοντα τῷ πλήθει πρῶτον μὲν ἁπλῶς καὶ πᾶσι γνωρίμως γεγράφθαι, καὶ μὴ τῷ μὲν εἶναι ταυτὶ περὶ αὐτοῦ νομίζειν, τῷ δὲ ταυτί. ἔπειτ’ εἶναι δυνατὰς τὰς πράξεις ἃς δεῖ γίγνεσθαι διὰ τοῦ νόμου· εἰ γὰρ αὖ καλῶς μὲν ἔχοι, μὴ δυνατὸν δέ τι φράζοι, εὐχῆς, οὐ νόμου διαπράττοιτ’ ἂν ἔργον.", "st": "24.68"}, {"sp": "N", "t": "πρὸς δὲ τούτοις μηδενὶ τῶν ἀδικούντων φαίνεσθαι μηδεμίαν διδόντα ῥᾳστώνην. εἰ γὰρ δημοτικόν τις ὑπείληφεν τὸ πράους εἶναι τοὺς νόμους, τίσιν τούτοις προσεξεταζέτω, κἄνπερ ὀρθῶς βούληται σκοπεῖν, εὑρήσει τοῖς κρίνεσθαι μέλλουσιν, οὐ τοῖς ἐξεληλεγμένοις· ἐν μὲν γὰρ τοῖς ἄδηλον εἴ τις ἔστ’ ἀδίκως διαβεβλημένος, τοῖς δ’ οὐδὲ λόγος λείπεται τὸ μὴ οὐ πονηροῖς εἶναι.", "st": "24.69"}, {"sp": "N", "t": "τούτων τοίνυν ὧν διεξελήλυθ’ ἐγὼ νῦν οὐδ’ ὁτιοῦν οὗτος ἔχων ὁ νόμος φανήσεται, τἀναντία δ’ ἑξῆς πάντα. πολλαχόθεν μὲν οὖν ἄν τις ἔχοι τοῦτο διδάσκειν, μάλιστα δὲ τὸν νόμον αὐτὸν ὃν τέθηκε διεξιών. ἔστι γὰρ οὐ τὸ μὲν αὐτοῦ καλῶς κείμενον, τὸ δ’ ἡμαρτημένον, ἀλλ’ ὅλος ἐξ ἀρχῆς, ἀπὸ τῆς πρώτης συλλαβῆς μέχρι τῆς τελευταίας, ἐφ’ ὑμῖν κεῖται.", "st": "24.70"}, {"sp": "N", "t": "λαβὲ δ’ αὐτοῖς τὴν γραφὴν αὐτήν, καὶ μέχρι τοῦ πρώτου μέρους ἀνάγνωθι τὸν νόμον· ῥᾷστα γὰρ οὕτως ἐγώ τε διδάξω καὶ ὑμεῖς μαθήσεσθ’ ἃ λέγω.", "st": "24.71"}, {"sp": "N", "t": "ΝΟΜΟΣ.", "st": "24.71"}, {"sp": "N", "t": "ἐπὶ τῆς Πανδιονίδος πρώτης δωδεκάτῃ τῆς πρυτανείας τῶν προέδρων ἐπεψήφισεν Ἀριστοκλῆς Μυρρινούσιος, Τιμοκράτης εἶπεν· καὶ εἴ τινι τῶν ὀφειλόντων τῷ δημοσίῳ προστετίμηται κατὰ νόμον ἢ κατὰ ψήφισμα δεσμοῦ ἢ τὸ λοιπὸν προστιμηθῇ, εἶναι αὐτῷ ἢ ἄλλῳ ὑπὲρ ἐκείνου ἐγγυητὰς καταστῆσαι.", "st": "24.71"}, {"sp": "N", "t": "ἐπίσχες· αὐτίκα γὰρ καθ’ ἕκαστον ἀναγνώσει. τουτὶ πάντων, ὦ ἄνδρες δικασταί, τῶν γεγραμμένων ἐν τῷ νόμῳ σχεδόν ἐστι δεινότατον. οἶμαι γὰρ οὐδὲ ἕν’ ἀνθρώπων ἄλλον τολμῆσαι, νόμον εἰσφέροντ’ ἐπὶ τῷ χρῆσθαι τοὺς πολίτας αὐτῷ, τὰς κατὰ τοὺς πρότερον κυρίους νόμους κρίσεις γεγενημένας ἐπιχειρῆσαι λύειν. τοῦτο τοίνυν οὑτοσὶ Τιμοκράτης ἀναιδῶς καὶ οὐδ’ ἀποκρυψάμενος πεποίηκεν, γράψας διαρρήδην “καὶ εἴ τινι τῶν ὀφειλόντων τῷ δημοσίῳ προστετίμηται κατὰ νόμον ἢ κατὰ ψήφισμα δεσμοῦ ἢ τὸ λοιπὸν προστιμηθῇ.”", "st": "24.72"}, {"sp": "N", "t": "περὶ μὲν δὴ τῶν μελλόντων εἴ τι δίκαιον ἔπεισεν ὑμᾶς, οὐκ ἂν ἠδίκει· περὶ δ’ ὧν δικαστήριον ἔγνωκεν καὶ τέλος ἔσχηκεν, πῶς οὐ δεινὰ ποιεῖ νόμον εἰσφέρων δι’ οὗ ταῦτα λυθήσεται; ὥσπερ ἂν εἴ τις ἐάσας κύριον τὸν τούτου γενέσθαι νόμον γράψει’ ἕτερον τοιόνδε “καὶ εἴ τινες, ὠφληκότες χρήματα καὶ δεσμοῦ προστετιμημένον αὐτοῖς, ἐγγυητὰς κατέστησαν κατὰ τὸν νόμον, μὴ εἶναι τὴν διεγγύησιν αὐτοῖς, μηδὲ τὸ λοιπὸν ἐξεγγυᾶν μηδένα.”", "st": "24.73"}, {"sp": "N", "t": "ἀλλ’ οὔτε ταῦτα ποιήσειεν ἂν οὐδεὶς ὑγιαίνων, οἶμαι, σύ τ’ ἐκεῖνα λύων ἠδίκεις. χρῆν γὰρ αὐτόν, εἰ τὸ πρᾶγμ’ ἐνόμιζεν δίκαιον, ἐπὶ τοῖς ὕστερον γενησομένοις θεῖναι τὸν νόμον, καὶ μὴ συνενεγκόντ’ εἰς ταὐτὸ τὰ μέλλοντα τοῖς παρεληλυθόσιν καὶ τὰ μὴ δῆλα τοῖς φανεροῖς ἀδικήμασιν, εἶτ’ ἐπὶ πᾶσι γράψαι τὴν αὐτὴν γνώμην. πῶς γὰρ οὐ δεινὸν τῶν αὐτῶν ἠξιωκέναι δικαίων τοὺς ἐξεληλεγμένους ἀδικοῦντας τὴν πόλιν πρότερον καὶ τοὺς μηδ’ εἰ κρίσεως ἄξιον ἐργάσονταί τι δήλους;", "st": "24.74"}, {"sp": "N", "t": "καὶ μὴν κἀκεῖθεν ἴδοι τις ἂν ὡς δεινὸν πεποίηκεν τὸ θεῖναι περὶ τῶν παρεληλυθότων τὸν νόμον, εἰ λογίσαιτο παρ’ αὑτῷ τί ποτ’ ἐστὶν ᾧ νόμος ὀλιγαρχίας διαφέρει, καὶ τί δή ποθ’ οἱ μὲν ὑπὸ νόμων ἐθέλοντες ἄρχεσθαι σώφρονες καὶ χρηστοὶ νομίζονται, οἱ δ’ ὑπὸ τῶν ὀλιγαρχιῶν ἄνανδροι καὶ δοῦλοι.", "st": "24.75"}, {"sp": "N", "t": "εὕροι γὰρ ἂν ὡς ἀληθῶς τοῦτο προχειρότατον, ὅτι τῶν μὲν ἐν ταῖς ὀλιγαρχίαις ἕκαστος καὶ τὰ πεπραγμένα λῦσαι καὶ περὶ τῶν μελλόντων ἃν αὐτῷ δοκῇ προστάξαι κύριός ἐστιν, οἱ δὲ νόμοι περὶ τῶν μελλόντων ἃ χρὴ γίγνεσθαι φράζουσιν, μετὰ τοῦ πεῖσαι τεθέντες ὡς συνοίσουσι τοῖς χρωμένοις. Τιμοκράτης τοίνυν ἐν δημοκρατουμένῃ τῇ πόλει νομοθετῶν τὴν ἐκ τῆς ὀλιγαρχίας ἀδικίαν εἰς τὸν αὑτοῦ νόμον μετήνεγκεν, καὶ περὶ τῶν παρεληλυθότων αὑτὸν κυριώτερον τῶν καταγνόντων δικαστῶν ἠξίωσε ποιῆσαι.", "st": "24.76"}, {"sp": "N", "t": "καὶ οὐ τοῦτο μόνον πεποίηκεν ὑβριστικόν, ἀλλὰ καὶ γέγραπται, “ἢ τὸ λοιπὸν ἐάν τινι προστιμηθῇ δεσμοῦ, εἶναι καταστήσαντι τοὺς ἐγγυητάς, ἦ μὴν ἐκτείσειν, ἀφεῖσθαι.” καίτοι χρῆν αὐτόν, εἰ τὸ δεδέσθαι δεινὸν ἡγεῖτο, μηδενὶ προστιμᾶν ὃς ἂν ὑμῖν ἐγγυητὰς καθιστῇ δεσμοῦ νομοθετῆσαι, μὴ προλαβόντα κατεγνωκότας ὑμᾶς τὸν δεσμὸν μηδ’ ἐχθρῶς διαθέντα πρὸς ὑμᾶς τὸν ἑαλωκότα, τηνικαῦτα ποιεῖν τὴν ἐξεγγύησιν. νυνὶ δ’, ὥσπερ ἐνδεικνύμενος ὅτι, κἂν ὑμῖν δοκῇ δεδέσθαι τινά, αὐτὸς ἀφήσει, τοῦτον τὸν τρόπον τὸν νόμον εἰσήνεγκεν.", "st": "24.77"}, {"sp": "N", "t": "ἆρ’ οὖν τῷ δοκεῖ συμφέρειν τῇ πόλει τοιοῦτος νόμος ὃς δικαστηρίου γνώσεως αὐτὸς κυριώτερος ἔσται, καὶ τὰς ὑπὸ τῶν ὀμωμοκότων γνώσεις τοῖς ἀνωμότοις προστάξει λύειν; ἐγὼ μὲν οὐκ οἶμαι. φαίνεται τοίνυν ὁ τούτου νόμος ταῦτ’ ἔχων ἀμφότερα. ὥστ’ εἴπερ ὑμῶν ἑκάστῳ μέλει τι τῆς πολιτείας καὶ δεῖν οἴεται κυρίαν εἶναι τὴν αὑτοῦ γνώμην περὶ ὧν ἂν ὀμωμοκὼς ψηφίσηται, λυτέος καὶ οὐκ ἐατέος οὗτος ὁ τοιοῦτος νόμος κύριος νυνὶ γενέσθαι.", "st": "24.78"}, {"sp": "N", "t": "οὐ τοίνυν ἀπέχρησεν αὐτῷ τὰ δικαστήρι’ ἄκυρα ποιῆσαι τῶν προστιμημάτων, ἀλλ’ οὐδ’ ἃ δίκαι’ ὡρίσατ’ αὐτὸς ἐν τῷ νόμῳ καὶ προσέταξε τοῖς ὠφληκόσιν, οὐδὲ ταῦθ’ ἁπλῶς οὐδ’ ἀδόλως φανήσεται γεγραφώς, ἀλλ’ ὡς ἂν μάλιστά τις ὑμᾶς ἐξαπατῆσαι καὶ παρακρούσασθαι βουλόμενος. σκέψασθε γὰρ ὡς γέγραφεν. “Τιμοκράτης εἶπεν” φησὶ “καὶ εἴ τινι τῶν ὀφειλόντων τῷ δημοσίῳ προστετίμηται κατὰ νόμον ἢ κατὰ ψήφισμα δεσμοῦ ἢ τὸ λοιπὸν προστιμηθῇ, εἶναι αὐτῷ ἢ ἄλλῳ ὑπὲρ ἐκείνου ἐγγυητὰς καταστῆσαι, οὓς ἂν ὁ δῆμος χειροτονήσῃ, ἦ μὴν ἐκτείσειν.”", "st": "24.79"}, {"sp": "N", "t": "ἐνθυμεῖσθ’ ἀπὸ τοῦ δικαστηρίου καὶ τῆς καταγνώσεως οἷ διεπήδησεν· ἐπὶ τὸν δῆμον, ἐκκλέπτων τὸν ἠδικηκότα καὶ τὴν παράδοσιν αὐτοῦ τὴν τοῖς ἕνδεκα. τίς γὰρ ἀρχὴ παραδώσει τὸν ὀφλόντα; τίς τῶν ἕνδεκα παραλήψεται; κελεύοντος μὲν τούτου ἐν τῷ δήμῳ καθιστάναι τοὺς ἐγγυητάς, ἀδυνάτου δ’ ὄντος αὐθημερὸν ἐκκλησίαν ἅμα καὶ δικαστήριον γενέσθαι, οὐδαμοῦ δ’ ἐπιτάττοντος φυλάττειν τέως ἂν καταστήσῃ τοὺς ἐγγυητάς.", "st": "24.80"}, {"sp": "N", "t": "καίτοι τί ποτ’ ἦν δι’ ὃ προσγράψαι σαφῶς ὤκνησεν “τὴν δ’ ἀρχὴν τὸν ὀφλόντα φυλάττειν τέως ἂν καταστήσῃ τοὺς ἐγγυητάς”; πότερ’ οὐχὶ δίκαιον; εὖ οἶδ’ ὅτι πάντες ἂν φήσαιτε. ἀλλ’ ἐναντίον ἦν τινὶ τοῦτο νόμῳ; οὔκ, ἀλλὰ μόνον κατὰ τοὺς νόμους. τί ποτ’ οὖν ἦν; οὐδὲν ἂν ἄλλο τις εὕροι πλὴν ὅτι οὐχ ὅπως δώσουσι δίκην ὧν ἂν ὑμεῖς καταγνῶτ’ ἐσκόπει, ἀλλ’ ὅπως μή.", "st": "24.81"}, {"sp": "N", "t": "εἶτα πῶς γέγραπται μετὰ ταῦτα; “καθιστάναι τοὺς ἐγγυητὰς ἦ μὴν ἐκτείσειν τὸ ἀργύριον ὃ ὦφλεν.” ἐνταυθὶ πάλιν τῶν ἱερῶν μὲν χρημάτων τὴν δεκαπλασίαν ὑφῄρηται, τῶν δ’ ὁσίων, ὁπόσων ἐν τῷ νόμῳ διπλασιάζεται, τὸ ἥμισυ. πῶς δὴ τοῦτο ποιεῖ; γράψας ἀντὶ μὲν τοῦ τιμήματος τὸ ἀργύριον, ἀντὶ δὲ τοῦ “τὸ γιγνόμενον,” “ὃ ὦφλεν.”", "st": "24.82"}, {"sp": "N", "t": "διαφέρει δὲ τί; εἰ μὲν ἔγραψε καθιστάναι τοὺς ἐγγυητὰς ἦ μὴν ἐκτείσειν τὸ τίμημα τὸ γιγνόμενον, προσπεριειλήφει τοὺς νόμους ἂν καθ’ οὓς τὰ μὲν διπλᾶ, τὰ δὲ καὶ δεκαπλᾶ γίγνεται τῶν ὀφλημάτων· ὥστ’ ἐκ τούτων ἦν ἀνάγκη τοῖς ὀφλοῦσιν τὸ γεγραμμένον τ’ ἐκτίνειν καὶ τὰς ἐκ τῶν νόμων προσούσας ζημίας καταβάλλειν. νῦν δ’ ἐν τῷ γράψαι “τὴν κατάστασιν εἶναι τῶν ἐγγυητῶν ἦ μὴν ἐκτείσειν τὸ ἀργύριον ὃ ὦφλεν,” ἐκ τῆς λήξεως καὶ τῶν γραμμάτων ἐφ’ οἷς ἕκαστος εἰσήχθη ποιεῖ τὴν ἔκτισιν, ἐν οἷς πᾶσιν ἁπλοῦν ὅ τις ὦφλεν ἀργύριον γέγραπται.", "st": "24.83"}, {"sp": "N", "t": "μετὰ ταῦτα τοίνυν τηλικοῦτο πρᾶγμ’ ἀνελὼν ἐν τῇ τῶν ῥημάτων μεταθέσει, προσέγραψεν “τοὺς δὲ προέδρους ἐπιχειροτονεῖν ἐπάναγκες, ὅταν τις καθιστάναι βούληται,” παρὰ πάντα τὸν νόμον οἰόμενος δεῖν σῴζειν τὸν ἠδικηκότα καὶ τὸν ἐν ὑμῖν ἑαλωκότα. δοὺς γὰρ ὅταν βούληται τὴν κατάστασιν αὐτῷ τῶν ἐγγυητῶν, ἐπ’ ἐκείνῳ πεποίηκεν μηδέποτ’ ἐκτεῖσαι μηδὲ δεθῆναι.", "st": "24.84"}, {"sp": "N", "t": "τίς γὰρ οὐ ποριεῖται φαύλους ἀνθρώπους, οὓς ὅταν ὑμεῖς ἀποχειροτονήσητ’ ἀπηλλάξεται; ἐὰν γάρ τις ὡς οὐ καθιστάντα τοὺς ἐγγυητὰς ἀξιοῖ δεδέσθαι, φήσει καὶ καθιστάναι καὶ καταστήσειν, καὶ δείξει τὸν τούτου νόμον, ὃς καθιστάναι μὲν ὅταν βούληται κελεύει, φυλάττειν δὲ τέως οὐ λέγει, οὐδ’, ἂν ἀποχειροτονήσηθ’ ὑμεῖς τοὺς ἐγγυητάς, προστάττει δεδέσθαι, ἀλλ’ ὡς ἀληθῶς ὥσπερ ἀλεξιφάρμακόν ἐστι τοῖς ἀδικεῖν βουλομένοις.", "st": "24.85"}, {"sp": "N", "t": "“τῷ δὲ καταστήσαντι” φησὶ “τοὺς ἐγγυητάς, ἐὰν ἀποδιδῷ τῇ πόλει τὸ ἀργύριον.” πάλιν ἐνταῦθ’ ἐπέμειν’ ἐπὶ τοῦ κακουργήματος ὃ μικρῷ πρότερον εἶπον, καὶ οὐκ ἐπελάθετο, οὐδ’ ἔγραψε τὸ τίμημα τὸ γιγνόμενον, ἀλλὰ τὸ ἀργύριον ὃ ὦφλεν, ἐὰν ἀποδιδῷ, ἀφεῖσθαι τοῦ δεσμοῦ.", "st": "24.86"}, {"sp": "N", "t": "“ἐὰν δὲ μὴ καταβάλῃ τὸ ἀργύριον ἢ αὐτὸς ἢ οἱ ἐγγυηταὶ ἐπὶ τῆς ἐνάτης πρυτανείας, τὸν μὲν ἐξεγγυηθέντα δεδέσθαι, τῶν δ’ ἐγγυητῶν δημοσίαν εἶναι τὴν οὐσίαν.” ἐν δὴ τῷ τελευταίῳ τούτῳ παντελῶς αὐτὸς αὑτοῦ κατήγορος, ὡς ἀδικεῖ, γεγονὼς φανήσεται. οὐ γὰρ ὅλως τὸ δεδέσθαι τινὰ τῶν πολιτῶν αἰσχρὸν ἢ δεινὸν νομίσας ἀπεῖπε μὴ δεῖν, ἀλλὰ τὸν καιρὸν ἐν ᾧ τὸν ἠδικηκότ’ ἐνῆν παρόντα λαβεῖν ἐκκλέψας, τοὔνομα μὲν τῆς τιμωρίας ἔλιπεν τοῖς ἀδικουμένοις ὑμῖν, τὸ δ’ ἔργον ἀφείλετο. καὶ παρ’ ἀκόντων ἔδωκ’ ἄφεσιν τοῖς τὰ ὑμέτερ’ ἀξιοῦσιν ἔχειν βίᾳ, καὶ μόνον οὐ προσέγραψε δίκην ἐξεῖναι λαχεῖν αὐτῷ κατὰ τῶν δικαστῶν τῶν προστιμησάντων τοῦ δεσμοῦ.", "st": "24.87"}, {"sp": "N", "t": "ὃ δέ, πολλῶν ὄντων καὶ δεινῶν ὧν ἐν τῷ νόμῳ τέθηκε, μάλιστ’ ἄξιόν ἐστ’ ἀγανακτῆσαι, βούλομαι πρὸς ὑμᾶς εἰπεῖν. δι’ ὅλου γὰρ τοῦ νόμου τῷ καταστήσαντι τοὺς ἐγγυητὰς ἅπαντα λέγει, τῷ δὲ μὴ καθιστάντι μήτε βελτίους μήτε χείρους, μηδ’ ὅλως προσέχοντι τὸν νοῦν ὑμῖν, οὐδεμίαν οὔτε δίκην οὔτε τιμωρίαν προσγέγραφεν, ἀλλ’ ἄδειαν πεποίηκε τοσαύτην ὅσην οἷόν τε γενέσθαι πλείστην. καὶ γὰρ τὸν χρόνον ὃν διώρισε, τὴν ἐνάτην πρυτανείαν, τῷ καταστήσαντι λέγει τοὺς ἐγγυητάς.", "st": "24.88"}, {"sp": "N", "t": "γνοίη δ’ ἄν τις ἐκεῖθεν· προσέγραψε δημοσίαν εἶναι τὴν οὐσίαν τὴν τῶν ἐγγυητῶν, ἂν μή τις ἐκτείσῃ· τοῦ δὲ μὴ καταστήσαντος οὐκ ἔνι δήπουθεν ὑπάρχειν ἐγγυητάς. καὶ τοῖς μὲν προέδροις, οἳ κεκληρωμένοι καθίζουσιν ἐξ ὑμῶν, ἐπάναγκες ἐποίησεν, ὅταν καθιστῇ τις, δέχεσθαι· τοῖς δ’ ἀδικοῦσι τὴν πόλιν οὐδεμίαν προσέγραψεν ἀνάγκην, ἀλλ’ ὥσπερ εὐεργέταις αἵρεσιν αὐτοῖς ἔδωκεν εἰ χρὴ δοῦναι δίκην ἢ μή.", "st": "24.89"}, {"sp": "N", "t": "καίτοι πῶς ἂν ἀσυμφορώτερος ὑμῖν τούτου γένοιτο νόμος ἢ κάκιον ἔχων; ὃς πρῶτον μὲν περὶ τῶν ἐκ τοῦ παρεληλυθότος χρόνου κριθέντων ἐναντία τοῖς ὑφ’ ὑμῶν ἐγνωσμένοις προστάττει, δεύτερον δὲ περὶ τῶν μελλόντων κριθήσεσθαι προστιμᾶν κελεύων τοὺς δικαστὰς τοὺς ὀμωμοκότας, ἄκυρα τὰ προστιμήματα ποιεῖ, πρὸς δὲ τούτοις ἐπιτίμους τοὺς ὀφείλοντας οὐ τὰ προσήκοντ’ ἐκτίνοντας καθίστησιν, ὅλως δ’ ἐπιδείκνυσι μάτην ὀμνύντας, τιμῶντας, δικάζοντας, ὀργιζομένους, ἅπαντα ποιοῦντας ὑμᾶς. ἐγὼ μὲν γάρ, εἰ Κριτίας ὁ γενόμενος τῶν τριάκοντ’ εἰσέφερεν τὸν νόμον, οὐκ ἂν ἄλλον τρόπον οἶμαι γράψαντ’ εἰσενεγκεῖν ἢ τοῦτον.", "st": "24.90"}, {"sp": "N", "t": "ὅτι τοίνυν ὅλην συγχεῖ τὴν πολιτείαν καὶ καταλύει πάντα τὰ πράγμαθ’ ὁ νόμος, καὶ πολλὰς φιλοτιμίας περιαιρεῖται τῆς πόλεως, καὶ τοῦτο ῥᾳδίως ὑμᾶς νομίζω μαθήσεσθαι. ἴστε γὰρ δήπου τοῦθ’ ὅτι σῴζεται πολλάκις ἡμῶν ἡ πόλις διὰ τὰς στρατείας καὶ τὰς ναυτικὰς καὶ τὰς πεζάς, καὶ πολλὰ καὶ καλὰ πολλάκις ἤδη διεπράξασθε καὶ σώσαντές τινας καὶ τιμωρησάμενοι καὶ διαλλάξαντες.", "st": "24.91"}, {"sp": "N", "t": "πῶς οὖν ἀνάγκη τὰ τοιαῦτα διοικεῖν ἐστιν; διὰ ψηφισμάτων καὶ νόμων τοῖς μὲν εἰσφέρειν ἐπιτάττοντας, τοὺς δὲ τριηραρχεῖν κελεύοντας, τοὺς δὲ πλεῖν, τοὺς δ’ ἕκαστα ποιεῖν ὧν δεῖ. οὐκοῦν ταῦθ’ ὅπως γίγνηται δικαστήρια πληροῦτε καὶ καταγιγνώσκετε δεσμὸν τῶν ἀκοσμούντων. σκέψασθε δὴ τὸν τοῦ καλοῦ κἀγαθοῦ τούτου νόμον, ὡς λυμαίνεται ταῦτα καὶ διαφθείρει.", "st": "24.92"}, {"sp": "N", "t": "γέγραπται γὰρ δήπου [ἐν τῷ νόμῳ αὐτοῦ], “καὶ εἴ τινι τῶν ὀφειλόντων προστετίμηται δεσμοῦ ἢ καὶ τὸ λοιπὸν προστιμηθῇ, εἶναι καταστήσαντι ἐγγυητάς, ἦ μὴν ἐπὶ τῆς ἐνάτης πρυτανείας ἐκτείσειν τὸ ἀργύριον, ἀφεῖσθαι τοῦ δεσμοῦ.” τίς οὖν πόρος ἔσται; τίν’ ἀποσταλήσεται τρόπον ἡ στρατιά; πῶς τὰ χρήματ’ εἰσπράξομεν, ἂν ἕκαστος ὀφλισκάνων ἐγγυητὰς καθιστῇ κατὰ τὸν τούτου νόμον, ἀλλὰ μὴ τὸ προσῆκον ποιῇ;", "st": "24.93"}, {"sp": "N", "t": "ἐροῦμεν νὴ Δία τοῖς Ἕλλησιν “Τιμοκράτους νόμος ἐστὶ παρ’ ἡμῖν· ἀναμείνατ’ οὖν τὴν ἐνάτην πρυτανείαν· εἶτα τότ’ ἔξιμεν·” τοῦτο γὰρ λοιπόν. ἂν δ’ ὑπὲρ ὑμῶν αὐτῶν ἀμύνεσθαι δέῃ, ἆρά γ’ οἴεσθε τοὺς ἐχθροὺς τὰς τῶν παρ’ ἡμῖν πονηρῶν διαδύσεις καὶ κακουργίας ἀναμενεῖν; ἢ τὴν πόλιν, αὑτὴν ἐμποδίζοντας νόμους εἰ θήσεται καὶ τἀναντία τῶν συμφερόντων λέγοντας, δυνήσεσθαί τι ποιῆσαι τῶν δεόντων;", "st": "24.94"}, {"sp": "N", "t": "ἀλλ’ ἀγαπητόν, ὦ ἄνδρες Ἀθηναῖοι, εἰ πάντων καλῶς ἐχόντων ἡμῖν καὶ μηδενὸς ὄντος τοιούτου νόμου, κρατοῖμεν τῶν ἐχθρῶν καὶ ταῖς ὀξύτησι δυναίμεθα καὶ τοῖς τοῦ πολέμου καιροῖς ἀκολουθεῖν καὶ μηδενὸς ὑστερίζειν. ἀλλὰ μὴν εἰ φαίνει τοιοῦτον τεθηκὼς νόμον ὃς τὰ τοιαῦτα λυμαίνεται δι’ ὧν ἡ πόλις καὶ σεμνὴ καὶ λαμπρὰ παρὰ πᾶσι καθέστηκεν, πῶς οὐχὶ δικαίως ὁτιοῦν ἂν πάθοις;", "st": "24.95"}, {"sp": "N", "t": "ἔτι τοίνυν, ὦ ἄνδρες Ἀθηναῖοι, τὴν διοίκησιν ἀναιρεῖ, τήν θ’ ἱερὰν καὶ τὴν ὁσίαν. ὡς δέ, ἐγὼ φράσω. ἔστιν ὑμῖν κύριος νόμος, καλῶς εἴπερ τις καὶ ἄλλος κείμενος, τοὺς ἔχοντας τά θ’ ἱερὰ καὶ τὰ ὅσια χρήματα καταβάλλειν εἰς τὸ βουλευτήριον, εἰ δὲ μή, τὴν βουλὴν αὐτοὺς εἰσπράττειν χρωμένην τοῖς νόμοις τοῖς τελωνικοῖς.", "st": "24.96"}, {"sp": "N", "t": "διὰ τοίνυν τοῦ νόμου τούτου διοικεῖται τὰ κοινά· τὰ γὰρ εἰς τὰς ἐκκλησίας καὶ τὰς θυσίας καὶ τὴν βουλὴν καὶ τοὺς ἱππέας καὶ τἄλλα χρήματ’ ἀναλισκόμενα, οὗτός ἐσθ’ ὁ νόμος ὁ ποιῶν προσευπορεῖσθαι. οὐ γὰρ ὄντων ἱκανῶν τῶν ἐκ τῶν τελῶν χρημάτων τῇ διοικήσει, τὰ προσκαταβλήματ’ ὀνομαζόμενα διὰ τὸν τοῦ νόμου τούτου φόβον καταβάλλεται.", "st": "24.97"}, {"sp": "N", "t": "πῶς οὖν οὐχ ἅπαντ’ ἀνάγκη καταλυθῆναι τὰ τῆς πόλεως, ὅταν αἱ μὲν τῶν τελῶν καταβολαὶ μὴ ὦσ’ ἱκαναὶ τῇ διοικήσει, ἀλλ’ ἐνδέῃ πολλῶν, καὶ μηδὲ ταῦτ’ ἀλλ’ ἢ περὶ λήγοντα τὸν ἐνιαυτὸν ᾖ λαβεῖν, τὰ δὲ προσκαταβλήματα τοὺς μὴ τιθέντας μὴ ᾖ κυρία δεῖν ἡ βουλὴ μηδὲ τὰ δικαστήρια, ἀλλὰ καθιστῶσιν ἐγγυητὰς ἄχρι τῆς ἐνάτης πρυτανείας;", "st": "24.98"}, {"sp": "N", "t": "τὰς δ’ ὀκτὼ τί ποιήσομεν; εἰπέ, Τιμόκρατες· οὐ σύνιμεν καὶ βουλευσόμεθ’ ἄν τι δέῃ; εἶτ’ ἔτι δημοκρατησόμεθα; οὐ δικάσει τὰ δικαστήρια τά τ’ ἴδια καὶ τὰ δημόσια; καὶ τίς ὑπάρξει τοῖς ἀδικουμένοις ἀσφάλεια; οὐκ εἴσεισιν ἡ βουλὴ καὶ διοικήσει τὰ ἐκ τῶν νόμων; καὶ τί λοιπὸν ἔσθ’ ἡμῖν ἀλλ’ ἢ καταλελύσθαι; ἀλλὰ νὴ Δί’ ἀμισθεὶ ταῦτα ποιήσομεν. καὶ πῶς οὐ δεινόν, εἰ διὰ τὸν νόμον, ὃν σὺ τέθηκας μισθὸν λαβών, ἄμισθος ὁ δῆμος καὶ ἡ βουλὴ καὶ τὰ δικαστήρι’ ἔσται;", "st": "24.99"}, {"sp": "N", "t": "χρῆν γὰρ τοῦτό γέ σ’, ὦ Τιμόκρατες, προσγράψαι τῷ νόμῳ, οὗπερ ἐποίεις κατὰ τῶν τελωνῶν καὶ τῶν ἐγγυητῶν [τὰς πράξεις κατὰ τοὺς ὑπάρχοντας νόμους], “καὶ εἰ κατά τινων ἐν ἄλλῳ τινὶ νόμῳ ἢ ψηφίσματι τὰς αὐτὰς εἴρηται πράξεις ὧν ὀφείλουσιν εἶναι ἃς περὶ τῶν τελωνῶν, καὶ κατὰ τούτων εἶναι τὰς πράξεις κατὰ τοὺς ὑπάρχοντας νόμους.”", "st": "24.100"}, {"sp": "N", "t": "νῦν δὲ κύκλῳ φεύγων τοὺς νόμους τοὺς τελωνικούς, ὅτι τὸ ψήφισμα τὸ Εὐκτήμονος εἴρηκε πράττειν τοὺς ὠφληκότας κατὰ τούτους τοὺς νόμους, διὰ ταῦτ’ οὐ προσέγραψε τοῦτο. ἐκ δὲ τούτου τοῦ τρόπου τὴν μὲν ὑπάρχουσαν τιμωρίαν λύσας κατὰ τῶν τὰ τῆς πόλεως ἐχόντων, ἑτέραν δ’ οὐ γράψας πάντα τὰ πράγματ’ ἀναιρεῖ, δῆμον, ἱππέας, βουλήν, ἱερά, ὅσια· ἀνθ’ ὧν, ἄνπερ ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, σωφρονῆτε, κολασθεὶς καὶ δοὺς ἀξίαν δίκην τοῖς ἄλλοις παράδειγμα γενήσεται μὴ τιθέναι τοιούτους νόμους.", "st": "24.101"}, {"sp": "N", "t": "οὐ τοίνυν μόνον τὰ δικαστήρι’ ἄκυρα ποιεῖ τῶν προστιμημάτων, τοῖς ἀδικοῦσι τὰ κοινὰ δίδωσιν ἄδειαν, τὰς ὑπὲρ τῆς πόλεως στρατείας λυμαίνεται, τὴν διοίκησιν καταλύει, ἀλλὰ καὶ τοῖς κακούργοις καὶ τοῖς πατραλοίαις καὶ τοῖς ἀστρατεύτοις βοηθοῦντα τέθηκε τὸν νόμον· τὰς γὰρ ὑπαρχούσας ἐκ τῶν νῦν κυρίων νόμων τιμωρίας καταλύει.", "st": "24.102"}, {"sp": "N", "t": "λεγόντων γὰρ τῶν νόμων οὓς ἔθηκε Σόλων, οὐδὲν ὅμοιος ὢν τούτῳ νομοθέτης, ἄν τις ἁλῷ κλοπῆς καὶ μὴ τιμηθῇ θανάτου, προστιμᾶν αὐτῷ δεσμόν, κἄν τις ἁλοὺς [τῆς] κακώσεως τῶν γονέων εἰς τὴν ἀγορὰν ἐμβάλλῃ, δεδέσθαι, κἂν ἀστρατείας τις ὄφλῃ καί τι τῶν αὐτῶν τοῖς ἐπιτίμοις ποιῇ, καὶ τοῦτον δεδέσθαι, Τιμοκράτης ἅπασι τούτοις ἄδειαν ποιεῖ, τῇ καταστάσει τῶν ἐγγυητῶν τὸν δεσμὸν ἀφαιρῶν.", "st": "24.103"}, {"sp": "N", "t": "ὥστ’ ἔμοιγε δοκεῖ (καὶ γὰρ εἰ φορτικώτερον εἶναι τὸ ῥηθησόμενον δόξει, λέξω καὶ οὐκ ἀποτρέψομαι) κατὰ τοῦτ’ αὔτ’ ἄξιον αὐτὸν εἶναι θανάτῳ ζημιῶσαι, ἵν’ ἐν Ἅιδου τοῖς ἀσεβέσιν θῇ τοῦτον τὸν νόμον, ἡμᾶς δὲ τοὺς ζῶντας τοῖσδε τοῖς ὁσίοις καὶ δικαίοις ἐᾷ τὸ λοιπὸν χρῆσθαι. ἀνάγνωθι δὲ καὶ τούτους τοὺς νόμους.", "st": "24.104"}, {"sp": "N", "t": "ΝΟΜΟΙ ΚΛΟΠΗΣ, ΚΑΚΩΣΕΩΣ ΓΟΝΕΩΝ, ΑΣΤΡΑΤΕΙΑΣ.", "st": "24.104"}, {"sp": "N", "t": "ὅ τι ἄν τις ἀπολέσῃ, ἐὰν μὲν αὐτὸ λάβῃ, τὴν διπλασίαν καταδικάζειν, ἐὰν δὲ μή, τὴν διπλασίαν πρὸς τοῖς ἐπαιτίοις. δεδέσθαι δ’ ἐν τῇ ποδοκάκκῃ τὸν πόδα πένθ’ ἡμέρας καὶ νύκτας ἴσας, ἐὰν προστιμήσῃ ἡ ἡλιαία. προστιμᾶσθαι δὲ τὸν βουλόμενον, ὅταν περὶ τοῦ τιμήματος ᾖ. —ἐὰν δέ τις ἀπαχθῇ, τῶν γονέων κακώσεως ἑαλωκὼς ἢ ἀστρατείας ἢ προειρημένον αὐτῷ τῶν νόμων εἴργεσθαι, εἰσιὼν ὅποι μὴ χρή, δησάντων αὐτὸν οἱ ἕνδεκα καὶ εἰσαγόντων εἰς τὴν ἡλιαίαν, κατηγορείτω δὲ ὁ βουλόμενος οἷς ἔξεστιν. ἐὰν δ’ ἁλῷ, τιμάτω ἡ ἡλιαία ὅ τι χρὴ παθεῖν αὐτὸν ἢ ἀποτεῖσαι. ἐὰν δ’ ἀργυρίου τιμηθῇ, δεδέσθω τέως ἂν ἐκτείσῃ.", "st": "24.105"}, {"sp": "N", "t": "ὅμοιός γ’, οὐ γάρ; ὦ ἄνδρες Ἀθηναῖοι, Σόλων νομοθέτης καὶ Τιμοκράτης. ὁ μέν γε καὶ τοὺς ὄντας βελτίους ποιεῖ καὶ τοὺς μέλλοντας ἔσεσθαι· ὁ δὲ καὶ τοῖς γεγενημένοις πονηροῖς, ὅπως μὴ δώσουσι δίκην, ὁδὸν δείκνυσιν, καὶ τοῖς οὖσιν ὅπως ἄδεια γενήσεται κακουργεῖν εὑρίσκει, καὶ τοῖς μέλλουσιν ἔσεσθαι, τοὺς ἐξ ἁπάντων τῶν χρόνων πονηρούς, ὅπως ἔσονται σῷοι καὶ μηδὲν πείσονται, παρασκευάζων.", "st": "24.106"}, {"sp": "N", "t": "καίτοι τίν’ ἂν ἀξίαν δοίης δίκην, ἢ τί σὺ παθὼν ἂν τὰ προσήκοντ’ εἴης πεπονθώς, ὅς, τὰ μὲν ἄλλ’ ἐῶ, ἀλλὰ τοὺς τῷ γήρᾳ βοηθοὺς ⟨νόμους⟩ λυμαίνει, οἳ καὶ ζῶντας ἀναγκάζουσι [τοὺς παῖδας] τοὺς γονέας τρέφειν, καὶ ἐπειδὰν ἀποθάνωσιν, ὅπως τῶν νομιζομένων τύχωσι παρασκευάζουσιν; ἢ πῶς οὐ κάκιστος ἁπάντων ἀνθρώπων δικαίως ἂν νομίζοιο, ὅστις, ὦ κατάρατε, περὶ πλείονος φαίνει τοὺς κλέπτας καὶ τοὺς κακούργους καὶ τοὺς ἀστρατεύτους τῆς πατρίδος ποιούμενος, καὶ διὰ τούτους καθ’ ἡμῶν νόμον τίθης;", "st": "24.107"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν, ἃ ὑπεσχόμην ἐν ἀρχῇ τοῦ λόγου, ἀπολογίσασθαι πεποιηκότ’ ἐμαυτόν. ἔφην γὰρ αὐτὸν ἐξελέγξειν κατὰ πάντ’ ἔνοχον ὄντα τῇ γραφῇ, πρῶτον μὲν παρὰ τοὺς νόμους νομοθετοῦντα, δεύτερον δ’ ὑπεναντία τοῖς οὖσι νόμοις γεγραφότα, τρίτον δὲ τοιαῦτα δι’ ὧν βλάπτει τὴν πόλιν. οὐκοῦν ἠκούσατε τῶν νόμων, ἃ κελεύουσι ποιεῖν τὸν τιθέντα νόμον καινόν· καὶ πάλιν ὑμᾶς ἐδίδαξ’ ὅτι τούτων οὐδ’ ὁτιοῦν ἐποίησεν οὗτος.", "st": "24.108"}, {"sp": "N", "t": "καὶ μὴν κἀκείνων ἠκούετε τῶν νόμων οἷς ἐναντίος ὢν ἐφαίνεθ’ ὁ τούτου· καὶ τούτους ὅτι πρὶν λῦσαι τόνδε τέθηκεν ἐπίστασθε. ἀλλὰ μὴν ὅτι γ’ οὐκ ἐπιτήδειος, ἀκηκόατε· ἄρτι γὰρ λέγων ἐπαυσάμην. οὐκοῦν κατὰ πάντ’ ἀδικεῖ φανερῶς, καὶ οὐδὲν ἔσθ’ ὅ τι φροντίσας οὐδ’ εὐλαβηθεὶς φαίνεται, ἀλλ’ ἔμοιγε δοκεῖ, κἂν εἰ πρὸς τούτοις ἄλλο τι μὴ ποιεῖν ἐγέγραπτ’ ἐν τοῖς οὖσι νόμοις, κἂν τοῦτο ποιῆσαι.", "st": "24.109"}, {"sp": "N", "t": "πανταχόθεν μὲν τοίνυν δῆλός ἐσθ’ ὅτι ταῦτ’ ἔγραψ’ ἐπιβουλεύσας [μετὰ τοῦ βουλεύσασθαι ταῦτ’ ἀδικεῖν] καὶ οὐ γνώμῃ διαμαρτών, μάλιστα δ’ ἐκ τοῦ πάντα τὸν νόμον μέχρι τῆς ὑστάτης συλλαβῆς τοιοῦτον εἶναι· οὐδὲ γὰρ οὐδ’ ἄκων οὐδὲν ἔθηκεν ὀρθῶς ἔχον, οὐδ’ ὡς ὑμῖν ἔμελλε λυσιτελήσειν. πῶς οὖν οὐκ εἰκὸς μισεῖν καὶ τιμωρεῖσθαι τοῦτον, ὅστις τοῦ μὲν δήμου ἠδικημένου ἠμέλησεν, ὑπὲρ δὲ τῶν ἠδικηκότων καὶ ὕστερον ἀδικησόντων τοὺς νόμους ἔθηκεν;", "st": "24.110"}, {"sp": "N", "t": "θαυμάζω δ’, ὦ ἄνδρες δικασταί, τῆς ἀναιδείας αὐτοῦ, τὸ ἡνίκα μὲν ἦρχεν αὐτὸς μετ’ Ἀνδροτίωνος, τὸν ἔλεον τοῦτον ἐπὶ τῷ πλήθει τῷ ὑμετέρῳ μὴ ποιήσασθαι, τῷ ἀπειρηκότι τὰ ἑαυτοῦ χρήματ’ εἰσφέροντι, ἐπειδὴ δ’ Ἀνδροτίων’ ἔδει ἃ πάλαι ὑφῄρητο τῆς πόλεως χρήματα καταθεῖναι, τὰ μὲν ἱερά, τὰ δ’ ὅσια, τότε θεῖναι τὸν νόμον ἐπ’ ἀποστερήσει τῶν μὲν ὁσίων τῆς διπλασίας, τῶν ἱερῶν δὲ τῆς δεκαπλασίας. καὶ οὕτω πρὸς τὸ πλῆθος τὸ ὑμέτερον προσενήνεκται ὁ αὐτίκα δὴ μάλ’ ὑπὲρ τοῦ δήμου φήσων τὸν νόμον τοῦτον θεῖναι.", "st": "24.111"}, {"sp": "N", "t": "δικαίως δ’ ἂν ἐμοὶ δοκεῖ παθεῖν ὁτιοῦν, ὅστις οἴεται δεῖν, εἰ μέν τις ἀγορανόμος ἢ ἀστυνόμος ἢ δικαστὴς κατὰ δήμους γενόμενος κλοπῆς ἐν ταῖς εὐθύναις ἑάλωκεν, ἄνθρωπος πένης καὶ ἰδιώτης καὶ πολλῶν ἄπειρος καὶ κληρωτὴν ἀρχὴν ἄρξας, τούτῳ μὲν τὴν δεκαπλασίαν εἶναι, καὶ νόμον οὐδένα τοῖς τοιούτοις ἐπικουροῦντα τίθησιν· εἰ δέ τινες πρέσβεις αἱρεθέντες ὑπὸ τοῦ δήμου, πλούσιοι ὄντες, ὑφείλοντο χρήματα πολλά, τὰ μὲν ἱερά, τὰ δ’ ὅσια, καὶ εἶχον χρόνον πολύν, τούτοις ὅπως μηδὲν πείσονται μήθ’ ὧν οἱ νόμοι μήθ’ ὧν τὰ ψηφίσματα προστάττει, μάλ’ ἀκριβῶς εὗρεν.", "st": "24.112"}, {"sp": "N", "t": "καίτοι γ’ ὁ Σόλων, ὦ ἄνδρες δικασταί, ᾧ οὐδ’ ἂν αὐτὸς Τιμοκράτης φήσειεν ὅμοιος νομοθέτης εἶναι, οὐχ ὅπως ἀσφαλῶς κακουργήσουσι φαίνεται παρασκευάζων τοῖς τοιούτοις, ἀλλ’ ὅπως ἢ μὴ ἀδικήσουσιν ἢ δώσουσι δίκην ἀξίαν, καὶ νόμον εἰσήνεγκεν, εἰ μέν τις μεθ’ ἡμέραν ὑπὲρ πεντήκοντα δραχμὰς κλέπτοι, ἀπαγωγὴν πρὸς τοὺς ἕνδεκ’ εἶναι, εἰ δέ τις νύκτωρ ὁτιοῦν κλέπτοι, τοῦτον ἐξεῖναι καὶ ἀποκτεῖναι καὶ τρῶσαι διώκοντα καὶ ἀπαγαγεῖν τοῖς ἕνδεκα, εἰ βούλοιτο. τῷ δ’ ἁλόντι ὧν αἱ ἀπαγωγαί εἰσιν, οὐκ ἐγγυητὰς καταστήσαντι ἔκτισιν εἶναι τῶν κλεμμάτων, ἀλλὰ θάνατον τὴν ζημίαν.", "st": "24.113"}, {"sp": "N", "t": "καὶ εἴ τίς γ’ ἐκ Λυκείου ἢ ἐξ Ἀκαδημείας ἢ ἐκ Κυνοσάργους ἱμάτιον ἢ ληκύθιον ἢ ἄλλο τι φαυλότατον, ἢ εἰ τῶν σκευῶν τι τῶν ἐκ τῶν γυμνασίων ὑφέλοιτο ἢ ἐκ τῶν λιμένων, ὑπὲρ δέκα δραχμάς, καὶ τούτοις θάνατον ἐνομοθέτησεν εἶναι τὴν ζημίαν. εἰ δέ τις ἰδίαν δίκην κλοπῆς ἁλοίη, ὑπάρχειν μὲν αὐτῷ διπλάσιον ἀποτεῖσαι τὸ τιμηθέν, προστιμῆσαι δ’ ἐξεῖναι τῷ δικαστηρίῳ πρὸς τῷ ἀργυρίῳ δεσμὸν τῷ κλέπτῃ, πένθ’ ἡμέρας καὶ νύκτας ἴσας, ὅπως ὁρῷεν ἅπαντες αὐτὸν δεδεμένον. καὶ τούτων ὀλίγῳ πρότερον ἠκούσατε τῶν νόμων.", "st": "24.114"}, {"sp": "N", "t": "ᾤετο γὰρ δεῖν τόν γε τὰ αἴσχρ’ ἔργ’ ἐργαζόμενον μὴ ἃ ὑφείλετο μόνον ἀποδόντ’ ἀπηλλάχθαι (πολλοὶ γὰρ [ἂν] αὐτῷ ἐδόκουν οὕτω γ’ οἱ κλέπται ἔσεσθαι, εἰ μέλλοιεν λαθόντες μὲν ἕξειν, μὴ λαθόντες δ’ αὐτὰ μόνον καταθήσειν), ἀλλὰ ταῦτα μὲν διπλάσια καταθεῖναι, δεθέντα δὲ πρὸς τούτῳ τῷ τιμήματι ἐν αἰσχύνῃ ζῆν ἤδη τὸν ἄλλον βίον. ἀλλ’ οὐ Τιμοκράτης, ἀλλ’ ὅπως ἁπλᾶ μέν, ἃ δεῖ διπλάσια, καταθήσουσιν παρεσκεύασε, μηδ’ ὁτιοῦν δ’ ἐπιτίμιον ἔσται πρὸς τούτοις.", "st": "24.115"}, {"sp": "N", "t": "καὶ οὐκ ἀπέχρησεν ὑπὲρ τῶν μελλόντων αὐτῷ ταῦτ’ ἀδικεῖν, ἀλλὰ καὶ εἴ τις ἄρ’ ἠδικηκὼς καὶ κεκολασμένος ἦν, καὶ τοῦτον ἀφῆκεν. καίτοι ἔγωγ’ ᾤμην δεῖν τὸν νομοθετοῦντα περὶ τῶν μελλόντων ἔσεσθαι, οἷα δεῖ γίγνεσθαι καὶ ὡς ἕκαστ’ ἔχειν, καὶ τὰς τιμωρίας ὁποίας τινὰς ἐφ’ ἑκάστοις δεῖ τοῖς ἀδικήμασιν εἶναι, περὶ τούτων νομοθετεῖν· τοῦτο γάρ ἐστι τὸ ἐφ’ ἅπασι τοῖς πολίταις κοινοὺς τοὺς νόμους τιθέναι. τὸ δὲ περὶ τῶν γεγονότων πραγμάτων νόμους γράφειν, οὐ νομοθετεῖν ἐστιν, ἀλλὰ τοὺς ἀδικοῦντας σῴζειν.", "st": "24.116"}, {"sp": "N", "t": "σκοπεῖτε δ’ ὡς ἀληθῆ λέγω, ἐκ τωνδί. εἰ μὲν γὰρ Εὐκτήμων ἑάλω τὴν τῶν παρανόμων γραφήν, οὐκ ἂν ἔθηκε τοῦτον τὸν νόμον [ὁ] Τιμοκράτης, οὐδ’ ἂν ἐδεῖθ’ ἡ πόλις τούτου τοῦ νόμου, ἀλλ’ ἐξήρκει ἂν αὐτοῖς ἀπεστερηκόσι τὴν πόλιν τὰ χρήματα τῶν ἄλλων μὴ φροντίζειν. νῦν δ’, ἐπειδὴ ἀπέφυγεν, τὸ μὲν ὑμέτερον δόγμα καὶ τὴν τοῦ δικαστηρίου ψῆφον καὶ τοὺς ἄλλους νόμους ἀκύρους οἴεται δεῖν εἶναι, αὑτὸν δὲ καὶ τὸν αὑτοῦ νόμον κύριον.", "st": "24.117"}, {"sp": "N", "t": "καίτοι, ὦ Τιμόκρατες, οἱ μὲν ὄντες ἡμῖν κύριοι νόμοι τουτουσὶ ποιοῦσι κυρίους ἁπάντων, καὶ διδόασιν αὐτοῖς ἀκούσασιν, ὁποῖον ἄν τι νομίζωσι τἀδίκημα, τοιαύτῃ περὶ τοῦ ἠδικηκότος χρῆσθαι τῇ ὀργῇ, μέγα μεγάλῃ, μικρὸν μικρᾷ. ὅταν γὰρ ᾖ “ὅ τι χρὴ παθεῖν ἢ ἀποτεῖσαι,” τὸ τιμᾶν ἐπὶ τούτοις γίγνεται.", "st": "24.118"}, {"sp": "N", "t": "σὺ τοίνυν τὸ παθεῖν ἀφαιρεῖς τὸν δεσμὸν ἀφιείς· καὶ ταῦτα τίσιν; τοῖς κλέπταις, τοῖς ἱεροσύλοις, τοῖς πατραλοίαις, τοῖς ἀνδροφόνοις, τοῖς ἀστρατεύτοις, τοῖς λιποῦσι τὰς τάξεις· τούτους γὰρ πάντας σῴζεις τῷ νόμῳ. καίτοι ὅστις ἐν δημοκρατίᾳ νομοθετῶν μήθ’ ὑπὲρ τῶν ἱερῶν μήθ’ ὑπὲρ τοῦ δήμου νομοθετεῖ, ἀλλ’ ὑπὲρ ὧν εἶπον ἀρτίως, πῶς οὐ δίκαιός ἐστι τῆς ἐσχάτης τιμωρίας τυχεῖν;", "st": "24.119"}, {"sp": "N", "t": "οὐ γὰρ δὴ ἐρεῖ γ’ ὡς τοὺς τοιούτους οὐ καὶ προσήκει καὶ οἱ νόμοι κελεύουσιν ταῖς μεγίσταις τιμωρίαις ἐνόχους εἶναι, οὐδ’ ὡς οὗτοι, ὑπὲρ ὧν εὕρηκε τὸν νόμον, οὐ καὶ κλέπται καὶ ἱερόσυλοί εἰσιν, τὰ μὲν ἱερά, τὰς δεκάτας τῆς θεοῦ καὶ τὰς πεντηκοστὰς τῶν ἄλλων θεῶν, σεσυληκότες καὶ ἀντὶ τοῦ ἀποδοῦναι αὐτοὶ ἔχοντες, τὰ δ’ ὅσια, ἃ ἐγίγνετο ὑμέτερα, κεκλοφότες. διαφέρει δὲ τοσοῦτον αὐτῶν ἡ ἱεροσυλία τῶν ἄλλων, ὅτι τὴν ἀρχὴν οὐδ’ ἀνήνεγκαν εἰς τὴν ἀκρόπολιν, δέον αὐτούς.", "st": "24.120"}, {"sp": "N", "t": "οἶμαι δέ, νὴ τὸν Δία τὸν Ὀλύμπιον, ὦ ἄνδρες δικασταί, οὐκ ἀπὸ ταὐτομάτου τὴν ὕβριν καὶ τὴν ὑπερηφανίαν ἐπελθεῖν Ἀνδροτίωνι, ἀλλ’ ὑπὸ τῆς θεοῦ ἐπιπεμφθεῖσαν, ἵν’, ὥσπερ οἱ τὰ ἀκρωτήρια τῆς Νίκης περικόψαντες ἀπώλοντ’ αὐτοὶ ὑφ’ αὑτῶν, οὕτω καὶ οὗτοι αὐτοὶ αὑτοῖς δικαζόμενοι ἀπόλοιντο, καὶ τὰ χρήματα καταθεῖεν δεκαπλάσια κατὰ τοὺς νόμους ἢ δεθεῖεν.", "st": "24.121"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν, ὃ μεταξὺ λέγων περὶ τούτων ἐνεθυμήθην, εἰπεῖν περὶ οὗ τέθηκε νόμου, παράδοξόν τι, θαυμαστὸν ἡλίκον. οὗτος γάρ, ὦ ἄνδρες δικασταί, τοῖς μὲν τὰ τέλη ὠνουμένοις ἔγραψε τὰς τιμωρίας εἶναι, εἰ μὴ καταβάλοιεν τὰ χρήματα, κατὰ τοὺς νόμους τοὺς προτέρους, ἐν οἷς καὶ ὁ δεσμὸς καὶ ἡ διπλασία γέγραπται, ἀνθρώποις οἳ διὰ τὸ ζημιοῦσθαι ἐπὶ τῇ ὠνῇ ἄκοντες ἔμελλον τὴν πόλιν ἀδικήσειν· τοῖς δ’ ὑφαιρουμένοις τὰ τῆς πόλεως καὶ ἱεροσυλοῦσι τὰ τῆς θεοῦ τὸν δεσμὸν ἀφεῖλεν. καίτοι εἰ μὲν ἐλάττω τούτους ἀδικεῖν ἐκείνων νομίσαι φήσεις, ἀνάγκη μαίνεσθαί σ’ ὁμολογεῖν, εἰ δὲ μείζω νομίζων, ὥσπερ ἔστιν, [ἐκεῖνα τἀδικήματα] τοὺς μὲν ἀφίης, τοὺς δὲ μή, οὐκ ἤδη δῆλος εἶ πεπρακὼς τὸ πρᾶγμα τούτοις;", "st": "24.122"}, {"sp": "N", "t": "ἄξιον τοίνυν καὶ τοῦτ’ εἰπεῖν, ὅσον ὑμεῖς διαφέρετ’, ὦ ἄνδρες δικασταί, μεγαλοφροσύνῃ τῶν ῥητόρων. ὑμεῖς μέν γε τἀπὶ τῷ πλήθει νενομοθετημένα δεινά, ἐάν τις ἢ διχόθεν μισθοφορῇ ἢ ὀφείλων τῷ δημοσίῳ ἐκκλησιάζῃ ἢ δικάζῃ, ἢ ἄλλο τι ποιῇ ὧν οἱ νόμοι ἀπαγορεύουσιν, οὐ λύετε, καὶ ταῦτ’ εἰδότες ὅτι διὰ πενίαν ⟨ἂν⟩ ποιήσειεν ὁ τούτων τι ποιῶν, οὐδὲ νόμους τοιούτους τίθεσθ’ ὅπως ἐξουσία ἔσται ἐξαμαρτεῖν, ἀλλὰ τοὐναντίον ὅπως μή· οὗτοι δ’, ὅπως οἱ τὰ αἴσχιστα καὶ τὰ δεινότατα ποιοῦντες δίκην μὴ δώσουσιν.", "st": "24.123"}, {"sp": "N", "t": "εἶτα προπηλακίζουσιν ὑμᾶς ἰδίᾳ τοῖς λόγοις, ὡς αὐτοὶ καλοὶ κἀγαθοί, πονηρῶν καὶ ἀχαρίστων οἰκετῶν τρόπους ἔχοντες. καὶ γὰρ ἐκείνων, ὦ ἄνδρες δικασταί, ὅσοι ἂν ἐλεύθεροι γένωνται, οὐ τῆς ἐλευθερίας χάριν ἔχουσι τοῖς δεσπόταις, ἀλλὰ μισοῦσι μάλιστ’ ἀνθρώπων, ὅτι συνίσασιν αὐτοῖς δουλεύσασιν. οὕτω δὴ καὶ οὗτοι οἱ ῥήτορες οὐκ ἀγαπῶσιν ἐκ πενήτων πλούσιοι ἀπὸ τῆς πόλεως γιγνόμενοι, ἀλλὰ καὶ προπηλακίζουσι τὸ πλῆθος, ὅτι σύνοιδεν αὐτῶν ἑκάστῳ τὰ ἐν τῇ πενίᾳ καὶ νεότητι ἐπιτηδεύματα.", "st": "24.124"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ αἰσχρὸν ἴσως ἦν Ἀνδροτίωνα δεθῆναι ἢ Γλαυκέτην ἢ Μελάνωπον. οὐ μὰ τὸν Δί’, ὦ ἄνδρες δικασταί, ἀλλὰ πολὺ αἴσχιον τὴν πόλιν ἀδικουμένην καὶ ὑβριζομένην μὴ λαβεῖν δίκην καὶ ὑπὲρ τῆς θεοῦ καὶ ὑπὲρ αὑτῆς. ἐπεὶ Ἀνδροτίωνί γε πότερ’ οὐ πατρῷον τὸ δεδέσθαι; ἀλλ’ αὐτοὶ ἴστε πολλὰς πεντετηρίδας ἐν τῷ δεσμωτηρίῳ διατρίψαντα τὸν πατέρ’ αὐτοῦ, καὶ ἀποδράντα, ἀλλ’ οὐκ ἀφεθέντα.", "st": "24.125"}, {"sp": "N", "t": "ἀλλὰ διὰ τὰ ἐπιτηδεύματα τὰ ἐν τῇ ἡλικίᾳ; ἀλλὰ καὶ διὰ ταῦτα δεδέσθαι αὐτῷ οὐχ ἧττον προσήκει ἢ δι’ ἅπερ ὑφείλετο. ἢ ὅτι εἰσῄει εἰς τὴν ἀγορὰν οὐκ ἐξὸν αὐτῷ, καὶ ἐκ ταύτης τοὺς σωφρόνως βεβιωκότας αὐτὸς ἦγεν εἰς τὸ δεσμωτήριον; ἀλλὰ Μελάνωπος δεινὸν νὴ Δί’ ἐστὶν εἰ δεθήσεσθαι νῦν ἔμελλεν.", "st": "24.126"}, {"sp": "N", "t": "ἀλλὰ περὶ μὲν τοῦ πατρὸς αὐτοῦ οὐδὲν ἂν φλαῦρον εἴποιμι, οὐδ’ εἰ πάνυ πόλλ’ ἔχω περὶ κλοπῆς λέγειν, ἀλλ’ ἔστω ἐμοὶ ἐκεῖνός γε τοιοῦτος οἷον ἂν Τιμοκράτης αὐτὸν ἐγκωμιάσειεν. ἀλλ’ εἰ χρηστοῦ πατρὸς ὢν πονηρὸς καὶ κλέπτης ἦν, καὶ προδοσίας γ’ ἁλοὺς τρία τάλαντ’ ἀπέτεισε, καὶ συνέδρου γενομένου κλοπὴν αὐτοῦ τὸ δικαστήριον κατέγνω καὶ δεκαπλάσιον ἀπέτεισεν, καὶ παρεπρεσβεύσατ’ εἰς Αἴγυπτον, καὶ τοὺς ἀδελφοὺς τοὺς ἑαυτοῦ ἠδίκει, οὐ τοσούτῳ μᾶλλον αὐτὸν ἔδει δεδέσθαι, εἰ χρηστοῦ πατρὸς ὢν τοιοῦτος ἦν; οἶμαι γὰρ ἔγωγε, εἴπερ τῷ ὄντι χρηστὸς ἦν Λάχης καὶ φιλόπολις, ὑπ’ αὐτοῦ ἂν ἐκείνου δεθῆναι αὐτὸν τοιοῦτόν γ’ ὄντα καὶ οὕτως αἰσχροῖς ὀνείδεσιν περιβάλλοντ’ ἐκεῖνον. καὶ τοῦτον μὲν δὴ ἐῶμεν, Γλαυκέτην δὲ σκεψώμεθα.", "st": "24.127"}, {"sp": "N", "t": "οὐχ οὗτός ἐστιν ὁ πρῶτον μὲν εἰς Δεκέλειαν αὐτομολήσας, κἀκεῖθεν ὁρμώμενος καταθέων καὶ φέρων καὶ ἄγων ὑμᾶς; ἀλλὰ πάντες ἴστε ταῦτα. καὶ ἀπὸ μὲν τῶν ὑμετέρων παίδων καὶ γυναικῶν καὶ τῶν ἄλλων χρημάτων ὅσα λάβοι, δεκάτας ἐκεῖ τῷ ἁρμοστῇ κατατιθεὶς τούτων ἀκριβῶς,", "st": "24.128"}, {"sp": "N", "t": "τὴν δέ γ’ ἐνθάδε θεόν, πρεσβευτὴς ἀξιωθεὶς εἶναι ὑφ’ ὑμῶν, ἀποστερῶν τὰς ἀπὸ τῶν ὑμετέρων πολεμίων δεκάτας; ἔπειτα ταμιεύσας ἐν ἀκροπόλει τἀριστεῖα τῆς πόλεως ἃ ἔλαβεν ἀπὸ τῶν βαρβάρων ὑφῃρημένος ἐξ ἀκροπόλεως, τόν τε δίφρον τὸν ἀργυρόποδα καὶ τὸν ἀκινάκην τὸν Μαρδονίου, ὃς ἦγε τριακοσίους δαρεικούς; ἀλλὰ ταῦτά γ’ οὕτω περιφανῆ ἐστιν ὥστε πάντας ἀνθρώπους εἰδέναι.", "st": "24.129"}, {"sp": "N", "t": "ἀλλὰ τἄλλ’ οὐ βίαιος; ὡς οὐδείς γ’ ἀνθρώπων. εἶτα φείσασθαί τινος αὐτῶν ἄξιόν ἐστιν, ὥστε διὰ τούτους ἢ τῶν δεκατῶν τῶν τῆς θεοῦ ἀμελῆσαι ἢ τῆς διπλασίας τῶν ὁσίων χρημάτων, ἢ τὸν τούτους πειρώμενον σῴζειν μὴ τιμωρήσασθαι; καὶ τί κωλύσει ἅπαντας εἶναι πονηρούς, ὦ ἄνδρες δικασταί, εἰ διὰ ταῦτα πλέον ἕξουσιν; ἐγὼ μὲν γὰρ οἶμαι οὐδέν.", "st": "24.130"}, {"sp": "N", "t": "μὴ τοίνυν αὐτοὶ διδάσκετε, ἀλλὰ τιμωρεῖσθε. καὶ μὴ ἐᾶτ’ ἀγανακτεῖν εἰ δεθήσονται ἔχοντες τὰ ὑμέτερα ἀλλ’ ἄγετ’ αὐτοὺς ὑπὸ τοὺς νόμους. οὐδὲ γὰρ οἱ τῆς ξενίας ἁλισκόμενοι ἀγανακτοῦσιν ἐν τῷ οἰκήματι τούτῳ ὄντες, ἕως ἂν τῶν ψευδομαρτυριῶν ἀγωνίσωνται, ἀλλὰ μένουσιν καὶ οὐκ οἴονται δεῖν ἐγγυητὰς καταστήσαντες περιιέναι.", "st": "24.131"}, {"sp": "N", "t": "ἔδοξε γὰρ τῇ πόλει ἀπιστεῖν αὐτοῖς, καὶ οὐκ ᾤετο δεῖν διακρουσθῆναι τῆς τιμωρίας δι’ ἐγγυητῶν καταστάσεως, ἀλλ’ ἐνταῦθα μένειν αὐτοὺς οὗ καὶ ἄλλοι πολλοὶ τῶν πολιτῶν. καίτοι καὶ ἐπὶ χρήμασιν ἤδη τινὲς ἐδέθησαν καὶ ἐπὶ κρίσεσιν, ἀλλ’ ὅμως ὑπέμενον. ἀηδὲς μὲν οὖν ἴσως ἐστὶν ὀνομαστὶ περί τινων μεμνῆσθαι, ἀναγκαῖον δὲ παρεξετάσαι αὐτοὺς παρὰ τούτους.", "st": "24.132"}, {"sp": "N", "t": "τοὺς μὲν οὖν πρὸ Εὐκλείδου ἄρχοντος ἐάσω καὶ τοὺς σφόδρα παλαιούς. καίτοι κατὰ τοὺς χρόνους οὓς ἕκαστοι αὐτῶν ἦσαν, πολλοῦ ἄξιοι δοκοῦντες γεγενῆσθαι τὸν ἔμπροσθεν χρόνον ὅμως ἰσχυρᾶς παρὰ τοῦ δήμου ὀργῆς ἐτύγχανον ἐπὶ τοῖς ὕστερον γιγνομένοις ἀδικήμασιν· οὐ γὰρ χρόνον τινὰ δικαίους ᾤετο δεῖν αὐτοὺς ἡ πόλις εἶναι, εἶτα κλέπτας, ἀλλὰ περί γε τὰ κοίν’ ἀεὶ δικαίους· ἐδόκει γὰρ τὸν ἔμπροσθεν χρόνον οὐ φύσει, ἀλλ’ ἐπιβουλεύων, τοῦ πιστευθῆναι, δίκαιος γεγονέναι ὁ τοιοῦτος ἄνθρωπος.", "st": "24.133"}, {"sp": "N", "t": "ἀλλὰ μετ’ Εὐκλείδην ἄρχοντ’, ὦ ἄνδρες δικασταί, πρῶτον μὲν Θρασύβουλον τὸν Κολλυτέα πάντες μέμνησθε δὶς δεθέντα καὶ κριθέντ’ ἀμφοτέρας τὰς κρίσεις ἐν τῷ δήμῳ· καίτοι τῶν ἐκ Πειραιῶς κἀπὸ Φυλῆς οὗτος ἦν. ἔπειτα Φιλέψιον τὸν Λαμπτρέα. ἔπειτ’ Ἀγύρριον τὸν Κολλυτέα, ἄνδρα χρηστὸν καὶ δημοτικὸν καὶ περὶ τὸ πλῆθος τὸ ὑμέτερον πολλὰ σπουδάσαντα·", "st": "24.134"}, {"sp": "N", "t": "ἀλλ’ ὅμως τοὺς νόμους ᾤετο δεῖν καὶ αὐτὸς ἐκεῖνος ὁμοίως, ὥσπερ ἐπὶ τοῖς ἀδυνάτοις, οὕτω καὶ ἐφ’ αὑτῷ ἰσχύειν, καὶ ἐγένετ’ ἐν τῷ οἰκήματι τούτῳ πόλλ’ ἔτη, ἕως τὰ χρήματα ἀπέτεισεν ἃ ἔδοξε τῆς πόλεως ὄντ’ ἔχειν· καὶ ἐπ’ ἐκείνῳ Καλλίστρατος δυνάμενος καὶ ἀδελφιδοῦς ὢν αὐτοῦ οὐκ ἐτίθει νόμους. καὶ Μυρωνίδης ὁ Ἀρχίνου υἱός, τοῦ καταλαβόντος Φυλὴν καὶ μετά γε τοὺς θεοὺς αἰτιωτάτου ὄντος τῆς καθόδου τῷ δήμῳ, καὶ ἄλλα πολλὰ καὶ καλὰ πεπολιτευμένου καὶ ἐστρατηγηκότος πολλάκις.", "st": "24.135"}, {"sp": "N", "t": "ἀλλ’ ὅμως ἅπαντες οὗτοι ὑπέμενον τοὺς νόμους. καὶ οἱ ταμίαι ἐφ’ ὧν ὁ Ὀπισθόδομος ἐνεπρήσθη, καὶ οἱ τῶν τῆς θεοῦ καὶ οἱ τῶν ἄλλων θεῶν, ἐν τῷ οἰκήματι τούτῳ ἦσαν, ἕως ἡ κρίσις αὐτοῖς ἐγένετο. καὶ οἱ περὶ τὸν σῖτον ἀδικεῖν δόξαντες, καὶ ἄλλοι πολλοί, ὦ ἄνδρες δικασταί, πάντες βελτίους Ἀνδροτίωνος ὄντες.", "st": "24.136"}, {"sp": "N", "t": "εἶτα τούτοις μὲν ἔδει κυρίους τοὺς πάλαι κειμένους νόμους εἶναι, καὶ δεδωκέναι δίκην αὐτοὺς κατὰ τοὺς ὑπάρχοντας νόμους· δι’ Ἀνδροτίωνα δὲ καὶ Γλαυκέτην καὶ Μελάνωπον καινὸν δεῖ γενέσθαι νόμον, διὰ τοὺς ἑαλωκότας καὶ ψήφῳ κεκριμένους κατὰ τοὺς πάλαι κειμένους νόμους καὶ δόξαντας ἔχειν ἱερὰ χρήματα καὶ ὅσια; εἶτ’ οὐ καταγέλαστος δόξει ἡ πόλις εἶναι, εἰ τοῖς ἱεροσύλοις, ὅπως σωθήσονται, νόμον φανεῖται τιθεμένη; ἔγωγ’ οἶμαι.", "st": "24.137"}, {"sp": "N", "t": "μὴ τοίνυν ἐάσηθ’ ὑμᾶς αὐτοὺς ὑβρίζεσθαι μηδὲ τὴν πόλιν, ἀλλὰ μνησθέντες ὅτι Εὔδημον τὸν Κυδαθηναιᾶ νόμον δόξαντα θεῖναι οὐκ ἐπιτήδειον, οὐ πάλαι ἀλλ’ ἐπ’ Εὐάνδρου ἄρχοντος ἀπεκτείνατε, καὶ Φίλιππον τὸν Φιλίππου τοῦ ναυκλήρου υἱὸν μικροῦ μὲν ἀπεκτείνατε, χρημάτων δὲ πολλῶν αὐτοῦ ἐκείνου ἀντιτιμωμένου παρ’ ὀλίγας ψήφους ἐτιμήσατε, ταύτην τὴν ὀργὴν καὶ νῦν ἐπὶ τουτονὶ λάβετε, ἐκεῖνο πρὸς τούτοις ἅπασιν ἐνθυμηθέντες, τί ποτ’ ἂν ἐπάθετε ὑπὸ τούτου αὐτοῦ, εἰ οὗτος εἷς ὢν ἐπρέσβευεν ὑπὲρ ὑμῶν. οἶμαι γὰρ τοιοῦτον οὐδὲν εἶναι ὅτου ἂν ἀπέσχετο. ὁρᾶτε δὲ τὴν διάνοιαν αὐτοῦ· ὁ γὰρ νόμος ὃν ἐτόλμησε θεῖναι τὸν τρόπον αὐτοῦ δείκνυσιν.", "st": "24.138"}, {"sp": "N", "t": "βούλομαι δ’ ὑμῖν, ὦ ἄνδρες δικασταί, ἐν Λοκροῖς ὡς νομοθετοῦσι διηγήσασθαι· οὐδὲν γὰρ χείρους ἔσεσθε παράδειγμά τι ἀκηκοότες, ἄλλως τε καὶ ᾧ πόλις εὐνομουμένη χρῆται. ἐκεῖ γὰρ οὕτως οἴονται δεῖν τοῖς πάλαι κειμένοις χρῆσθαι νόμοις καὶ τὰ πάτρια περιστέλλειν καὶ μὴ πρὸς τὰς βουλήσεις μηδὲ πρὸς τὰς διαδύσεις τῶν ἀδικημάτων νομοθετεῖσθαι, ὥστ’ ἄν τις βούληται νόμον καινὸν τιθέναι, ἐν βρόχῳ τὸν τράχηλον ἔχων νομοθετεῖ, καὶ ἐὰν μὲν δόξῃ καλὸς καὶ χρήσιμος εἶναι ὁ νόμος, ζῇ ὁ τιθεὶς καὶ ἀπέρχεται, εἰ δὲ μή, τέθνηκεν ἐπισπασθέντος τοῦ βρόχου.", "st": "24.139"}, {"sp": "N", "t": "καὶ γάρ τοι καινοὺς μὲν οὐ τολμῶσι τίθεσθαι, τοῖς δὲ πάλαι κειμένοις ἀκριβῶς χρῶνται. καὶ ἐν πολλοῖς δὲ πάνυ ἔτεσιν, ὦ ἄνδρες δικασταί, εἷς λέγεται παρ’ αὐτοῖς νόμος καινὸς τεθῆναι. ὄντος γὰρ αὐτόθι νόμου, ἐάν τις ὀφθαλμὸν ἐκκόψῃ, ἀντεκκόψαι παρασχεῖν τὸν ἑαυτοῦ, καὶ οὐ χρημάτων τιμήσεως οὐδεμιᾶς, ἀπειλῆσαί τις λέγεται ἐχθρὸς ἐχθρῷ ἕν’ ἔχοντι ὀφθαλμὸν ὅτι αὐτοῦ ἐκκόψει τοῦτον τὸν ἕνα.", "st": "24.140"}, {"sp": "N", "t": "γενομένης δὲ ταύτης τῆς ἀπειλῆς χαλεπῶς ἐνεγκὼν ὁ ἑτερόφθαλμος, καὶ ἡγούμενος ἀβίωτον αὑτῷ [εἶναι] τὸν βίον τοῦτο παθόντι, λέγεται τολμῆσαι νόμον εἰσενεγκεῖν, ἐάν τις ἕνα ἔχοντος ὀφθαλμὸν ἐκκόψῃ, ἄμφω ἀντεκκόψαι παρασχεῖν, ἵνα τῇ ἴσῃ συμφορᾷ ἀμφότεροι χρῶνται. καὶ τοῦτον μόνον λέγονται Λοκροὶ θέσθαι τὸν νόμον ἐν πλεῖν ἢ διακοσίοις ἔτεσιν.", "st": "24.141"}, {"sp": "N", "t": "οἱ δὲ παρ’ ἡμῖν ῥήτορες, ὦ ἄνδρες δικασταί, πρῶτον μὲν ὅσοι μῆνες μικροῦ δέουσι νομοθετεῖν τὰ αὑτοῖς συμφέροντα, ἔπειτ’ αὐτοὶ μὲν τοὺς ἰδιώτας εἰς τὸ δεσμωτήριον ἄγουσιν ὅταν ἄρχωσιν, ἐφ’ ἑαυτοῖς δ’ οὐκ οἴονται δεῖν ταὐτὸ δίκαιον τοῦτ’ εἶναι· ἔπειτα τοὺς μὲν τοῦ Σόλωνος νόμους τοὺς πάλαι δεδοκιμασμένους, οὓς οἱ πρόγονοι ἔθεντο, λύουσιν αὐτοί, τοῖς δ’ ἑαυτῶν, οὓς ἐπ’ ἀδικίᾳ τῆς πόλεως τιθέασιν, χρῆσθαι ὑμᾶς οἴονται δεῖν.", "st": "24.142"}, {"sp": "N", "t": "εἰ οὖν μὴ τιμωρήσεσθε τούτους, οὐκ ἂν φθάνοι τὸ πλῆθος τούτοις τοῖς θηρίοις δουλεῦον. εὖ δ’ ἴστ’, ὦ ἄνδρες δικασταί, ὅτι ἐὰν μὲν σφόδρ’ ὀργίζησθε, ἧττον ἀσελγανοῦσιν, ἂν δὲ μή, πολλοὺς τοὺς ἀσελγεῖς εὑρήσετε καὶ τοὺς ὑβρίζοντας ὑμᾶς ἐπὶ τῇ τοῦ φιλοτιμεῖσθαι προφάσει.", "st": "24.143"}, {"sp": "N", "t": "ἵνα δὲ καὶ περὶ ἐκείνου εἴπω τοῦ νόμου, ὦ ἄνδρες δικασταί, ᾧ ἀκούω μέλλειν παραδείγματι χρῆσθαι τοῦτον καὶ φήσειν ἀκόλουθον αὐτῷ τεθηκέναι, ἐν ᾧ ἔνι “οὐδὲ δήσω Ἀθηναίων οὐδένα, ὃς ἂν ἐγγυητὰς τρεῖς καθιστῇ τὸ αὐτὸ τέλος τελοῦντας, πλὴν ἐάν τις ἐπὶ προδοσίᾳ τῆς πόλεως ἢ ἐπὶ καταλύσει τοῦ δήμου συνιὼν ἁλῷ, ἢ τέλος πριάμενος ἢ ἐγγυησάμενος ἢ ἐκλέγων μὴ καταβάλῃ,” ἀκούσατέ μου καὶ περὶ τούτου.", "st": "24.144"}, {"sp": "N", "t": "οὐ γὰρ ἐρῶ ὅτι αὐτὸς Ἀνδροτίων ἦγεν εἰς τὸ δεσμωτήριον καὶ ἔδει τούτου κειμένου τοῦ νόμου, ἀλλ’ ἐφ’ οἷς κεῖται ὁ νόμος οὗτος, διδάξω ὑμᾶς. οὗτος γάρ, ὦ ἄνδρες δικασταί, οὐκ ἐπὶ τοῖς κεκριμένοις καὶ ἠγωνισμένοις κεῖται, ἀλλ’ ἐπὶ τοῖς ἀκρίτοις, ἵνα μὴ διὰ τὸ δεδέσθαι χεῖρον ἀναγκάζοιντ’ ἀγωνίζεσθαι ἢ καὶ παντάπασιν ἀπαράσκευοι εἶεν. οὑτοσὶ δέ, ἃ ἐπὶ τοῖς ἀκρίτοις κεῖται, ὡς περὶ ἁπάντων εἰρημένα μέλλει πρὸς ὑμᾶς λέγειν.", "st": "24.145"}, {"sp": "N", "t": "ὡς δὲ σαφῶς γνώσεσθ’ ὅτι ἀληθῆ λέγω, ἐγὼ ὑμῖν ἐρῶ. οὔτε γὰρ ἄν, ὦ ἄνδρες δικασταί, τιμᾶν ἐξῆν ὑμῖν ὅ τι χρὴ παθεῖν ἢ ἀποτεῖσαι (ἐν γὰρ τῷ παθεῖν καὶ ὁ δεσμὸς ἔνι· οὐκ ἂν οὖν ἐξῆν δεσμοῦ τιμῆσαι), οὔθ’ ὅσων ἔνδειξίς ἐστιν ἢ ἀπαγωγὴ προσεγέγραπτ’ ἂν ἐν τοῖς νόμοις “τὸν δ’ ἐνδειχθέντα ἢ ἀπαχθέντα δησάντων οἱ ἕνδεκα ἐν τῷ ξύλῳ,” εἴπερ μὴ ἐξῆν ἄλλους ἢ τοὺς ἐπὶ προδοσίᾳ τῆς πόλεως ἢ ἐπὶ καταλύσει τοῦ δήμου συνιόντας ἢ τοὺς τὰ τέλη ὠνουμένους καὶ μὴ καταβάλλοντας δῆσαι.", "st": "24.146"}, {"sp": "N", "t": "νῦν δὲ ταῦθ’ ὑμῖν τεκμήρι’ ἔστω ὅτι ἔξεστι δῆσαι· παντελῶς γὰρ ἤδη ἄκυρ’ ἂν ἦν τὰ τιμήματα. ἔπειτα δ’, ὦ ἄνδρες δικασταί, τοῦτο τὸ γράμμα αὐτὸ μὲν καθ’ αὑτὸ οὐκ ἔστι νόμος, τὸ “οὐδὲ δήσω Ἀθηναίων οὐδένα,” ἐν δὲ τῷ ὅρκῳ τῷ βουλευτικῷ γέγραπται, ἵνα μὴ συνιστάμενοι οἱ ῥήτορες οἱ ἐν τῇ βουλῇ δεσμὸν κατά τινος τῶν πολιτῶν λέγοιεν.", "st": "24.147"}, {"sp": "N", "t": "ἄκυρον οὖν τοῦ δῆσαι τὴν βουλὴν ποιῶν ὁ Σόλων τοῦτο πρὸς τὸν ὅρκον τὸν βουλευτικὸν προσέγραψεν, ἀλλ’ οὐ πρὸς τὸν ὑμέτερον· ἁπάντων γὰρ κυριώτατον ᾤετο δεῖν εἶναι τὸ δικαστήριον, καὶ ὅ τι γνοίη, τοῦτο πάσχειν τὸν ἁλόντα. ἀναγνώσεται δ’ ὑμῖν αὐτοῦ τούτου ἕνεκα τὸν τῶν ἡλιαστῶν ὅρκον. λέγε σύ.", "st": "24.148"}, {"sp": "N", "t": "ΟΡΚΟΣ ΗΛΙΑΣΤΩΝ.", "st": "24.149"}, {"sp": "N", "t": "ψηφιοῦμαι κατὰ τοὺς νόμους καὶ τὰ ψηφίσματα τοῦ δήμου τοῦ Ἀθηναίων καὶ τῆς βουλῆς τῶν πεντακοσίων. καὶ τύραννον οὐ ψηφιοῦμαι εἶναι οὐδ’ ὀλιγαρχίαν· οὐδ’ ἐάν τις καταλύῃ τὸν δῆμον τὸν Ἀθηναίων ἢ λέγῃ ἢ ἐπιψηφίζῃ παρὰ ταῦτα, οὐ πείσομαι· οὐδὲ τῶν χρεῶν τῶν ἰδίων ἀποκοπὰς οὐδὲ γῆς ἀναδασμὸν τῆς Ἀθηναίων οὐδ’ οἰκιῶν· οὐδὲ τοὺς φεύγοντας κατάξω, οὐδὲ ὧν θάνατος κατέγνωσται, οὐδὲ τοὺς μένοντας ἐξελῶ παρὰ τοὺς νόμους τοὺς κειμένους καὶ τὰ ψηφίσματα τοῦ δήμου τοῦ Ἀθηναίων καὶ τῆς βουλῆς οὔτ’ αὐτὸς ἐγὼ οὔτ’ ἄλλον οὐδένα ἐάσω.", "st": "24.149"}, {"sp": "N", "t": "οὐδ’ ἀρχὴν καταστήσω ὥστ’ ἄρχειν ὑπεύθυνον ὄντα ἑτέρας ἀρχῆς, καὶ τῶν ἐννέα ἀρχόντων καὶ τοῦ ἱερομνήμονος καὶ ὅσοι μετὰ τῶν ἐννέα ἀρχόντων κυαμεύονται ταύτῃ τῇ ἡμέρᾳ, καὶ κήρυκος καὶ πρεσβείας καὶ συνέδρων· οὐδὲ δὶς τὴν αὐτὴν ἀρχὴν τὸν αὐτὸν ἄνδρα, οὐδὲ δύο ἀρχὰς ἄρξαι τὸν αὐτὸν ἐν τῷ αὐτῷ ἐνιαυτῷ. οὐδὲ δῶρα δέξομαι τῆς ἡλιάσεως ἕνεκα οὔτ’ αὐτὸς ἐγὼ οὔτ’ ἄλλος ἐμοὶ οὔτ’ ἄλλη εἰδότος ἐμοῦ, οὔτε τέχνῃ οὔτε μηχανῇ οὐδεμιᾷ.", "st": "24.150"}, {"sp": "N", "t": "καὶ γέγονα οὐκ ἔλαττον ἢ τριάκοντα ἔτη. καὶ ἀκροάσομαι τοῦ τε κατηγόρου καὶ τοῦ ἀπολογουμένου ὁμοίως ἀμφοῖν, καὶ διαψηφιοῦμαι περὶ αὐτοῦ οὗ ἂν ἡ δίωξις ᾖ. ἐπομνύναι Δία, Ποσειδῶ, Δήμητρα, καὶ ἐπαρᾶσθαι ἐξώλειαν ἑαυτῷ καὶ οἰκίᾳ τῇ ἑαυτοῦ, εἴ τι τούτων παραβαίνοι, εὐορκοῦντι δὲ πολλὰ κἀγαθὰ εἶναι.", "st": "24.151"}, {"sp": "N", "t": "ἐνταῦθ’ οὐκ ἔνι, ὦ ἄνδρες δικασταί, “οὐδὲ δήσω Ἀθηναίων οὐδένα.” τὰ γὰρ κρίνοντα τὰς κρίσεις ἁπάσας τὰ δικαστήρι’ ἐστίν, οἷς ἐξουσία ἐστὶ καὶ δεσμὸν καὶ ἄλλ’ ὅ τι ἂν βούλωνται καταγιγνώσκειν.", "st": "24.151"}, {"sp": "N", "t": "ὡς μὲν οὖν ἔξεστιν ὑμῖν δεσμὸν καταγιγνώσκειν ταῦτ’ ἐπιδείκνυμι· ὡς δὲ τὰ δεδικασμέν’ ἄκυρα ποιεῖν καὶ δεινὸν καὶ ἀνόσιόν ἐστι καὶ δήμου κατάλυσις, πάντας ἂν οἶμαι ὁμολογῆσαι. ἡ γὰρ πόλις ἡμῶν, ὦ ἄνδρες δικασταί, νόμοις καὶ ψηφίσμασιν διοικεῖται. εἰ δή τις τὰ ψήφῳ κεκριμένα νόμῳ καινῷ λύσει, τί πέρας ἔσται; ἢ πῶς τοῦτον δίκαιόν ἐστι νόμον προσαγορεύειν, ἀλλ’ οὐκ ἀνομίαν; ἢ πῶς οὐ τῆς μεγίστης ὀργῆς ὁ τοιοῦτος νομοθέτης ἄξιός ἐστιν;", "st": "24.152"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ τῶν ἐσχάτων νομίζω, οὐχ ὅτι τοῦτον μόνον τὸν νόμον ἔθηκεν, ἀλλ’ ὅτι καὶ τοῖς ἄλλοις ὁδὸν δείκνυσι καὶ περὶ δικαστηρίων καταλύσεως καὶ περὶ τῶν φευγόντων καθόδου καὶ περὶ τῶν ἄλλων τῶν δεινοτάτων. τί γὰρ κωλύει, ὦ ἄνδρες δικασταί, εἰ οὗτος χαίρων ἀπαλλάξει ὁ τοιοῦτον νόμον τιθείς, ἕτερον φανῆναι ἄλλο τι τῶν τῆς πόλεως ἰσχυροτάτων καταλύοντα νόμῳ καινῷ;", "st": "24.153"}, {"sp": "N", "t": "ἐγὼ μὲν γὰρ οἶμαι οὐδέν. ἀκούω δ’ ἔγωγε καὶ τὸ πρότερον οὕτω καταλυθῆναι τὴν δημοκρατίαν, παρανόμων πρῶτον γραφῶν καταλυθεισῶν καὶ τῶν δικαστηρίων ἀκύρων γενομένων. ἴσως μὲν οὖν ἄν τις ὑπολάβοι ὅτι οὐχ ὁμοίων ὄντων τῶν πραγμάτων νῦν καὶ τότε λέγω περὶ καταλύσεως τοῦ δήμου. ἀλλ’ οὐδὲ σπέρμα δεῖ καταβάλλειν ἐν τῇ πόλει οὐδένα, ὦ ἄνδρες δικασταί, τοιούτων πραγμάτων, οὐδ’ εἰ μήπω ἂν ἐκφύοι, ἀλλὰ τὸν ἐγχειροῦντα λέγειν ἢ ποιεῖν τι τοιοῦτον δίκην διδόναι.", "st": "24.154"}, {"sp": "N", "t": "ὅτι τοίνυν καὶ τέχνῃ κακῶς ἐνεχείρησε ποιεῖν ὑμᾶς, ἄξιόν ἐστιν ἀκοῦσαι. ὁρῶν γὰρ ἑκάστοτε πάντας, καὶ τοὺς πολιτευομένους καὶ τοὺς ἰδιώτας, τοὺς νόμους τῶν τῆς πόλεως ἀγαθῶν αἰτίους ὑπολαμβάνοντας, ἐσκόπει πῶς λήσει τούτους καταλύσας, κἂν ἄρα ληφθῇ τοῦτο ποιῶν, μὴ δόξει δεινὸν μηδ’ ἀναιδὲς μηδὲν εἰργάσθαι.", "st": "24.155"}, {"sp": "N", "t": "εὗρεν οὖν τοῦθ’ ὃ πεποίηκεν, νόμῳ τοὺς νόμους καταλῦσαι, ἵνα τἀδικήματ’ αὐτοῦ τὸ τῆς σωτηρίας ὄνομ’ ἔχῃ. οἵ τε γὰρ σῴζοντες τὴν πόλιν εἰσὶ νόμοι, ὅν θ’ οὗτος ἔθηκεν οὐδὲν ἐκείνοις τῶν αὐτῶν ἔχοντα, νόμος. τὴν μὲν οὖν τοῦ ὀνόματος φιλανθρωπίαν, ὅτι ταύτην ἂν μάλιστα προσεῖσθε, κατεῖδεν· τὴν δὲ χρείαν, ὅτι τἀναντί’ ἔχουσα φανήσεται, παρεῖδεν.", "st": "24.156"}, {"sp": "N", "t": "φέρε γὰρ πρὸς Διός, ἔστιν ὅστις ἂν ἢ πρόεδρός ποτ’ ἐπεψήφισεν ἢ πρύτανις τούτων τι τῶν ἐν τῷ νόμῳ γεγραμμένων; ἐγὼ μὲν οὐδέν’ ἂν οἶμαι. πῶς οὖν τοῦθ’ ὑπέδυ; νόμον ἔθετ’ ὄνομα τοῖς αὑτοῦ κακουργήμασιν. οὐ γὰρ ἁπλῶς, οὐδ’ ὅπως ἔτυχον, ποιοῦσι κακῶς ὑμᾶς, ἀλλ’ ἐσκεμμένως καὶ τοῦτ’ αὐτὸ πράττοντες, οὐχ οὗτοι μόνον, ἀλλὰ πολλοὶ τῶν πολιτευομένων, οἳ τούτῳ παριόντες αὐτίκα δὴ μάλα συναπολογήσονται, οὐ μὰ Δί’ οὐ Τιμοκράτει χαρίσασθαι βουλόμενοι, πόθεν; ἀλλ’ αὑτῷ συμφέρειν ἕκαστος ἡγούμενος τὸν νόμον. ὥσπερ τοίνυν οὗτοι σφίσιν αὐτοῖς βοηθοῦσιν ἐφ’ ὑμᾶς, οὕτω δεῖ καὶ ὑμᾶς ὑμῖν αὐτοῖς βοηθεῖν.", "st": "24.157"}, {"sp": "N", "t": "καίτοι ἀνερωτῶντός τινος αὐτὸν ὅτου ἕνεκα τοιαῦτ’ ἠθέλησε γράφειν, καὶ διεξιόντος ὡς χαλεπὸν τὸν ἀγῶν’ ὑπολαμβάνοι τόνδε, τετυφῶσθαι τὸν ταῦτα λέγοντ’ ἔφη· συμπαρέσεσθαι γὰρ Ἀνδροτίων’ ἑαυτῷ, καὶ τοιούτους λόγους σχολὴν ἄγοντ’ ἐσκέφθαι περὶ πάντων ὥστ’ εὖ εἰδέναι ὅτι οὐδὲν αὐτῷ γενήσοιτο φλαῦρον ἀπὸ τῆς γραφῆς τῆσδε.", "st": "24.158"}, {"sp": "N", "t": "καὶ δῆτα καὶ τεθαύμακα τὴν ἀναισχυντίαν τὴν τούτου τε κἀκείνου, τοῦ μέν, εἰ καλεῖ, τοῦ δέ, εἰ πάρεισι καὶ συναπολογήσεται. μαρτυρία γὰρ δήπου φανερὰ γενήσεται πᾶσιν ὑμῖν ὅτι τὸν νόμον τούτου ἕνεκ’ ἐτίθει, ἀλλ’ οὐκ ἐπὶ πᾶσι τὸν αὐτόν. ὅμως δὲ καὶ περὶ τῶν ἐκείνῳ πεπολιτευμένων ὑμᾶς μικρὰ βέλτιόν ἐστιν ἀκοῦσαι, καὶ τούτων ταῦθ’ ὧν κεκοινώνηκεν οὗτος, καὶ δι’ ἃ τοῦτον οὐδὲν ἧττον ἐκείνου δικαίως ἂν μισοῖτε. λέξω δ’ οὐδὲν ὧν ἀκηκόαθ’ ὑμεῖς, εἰ μή τινες ἄρ’ ἐπὶ τοῖς Εὐκτήμονι γιγνομένοις ἀγῶσι παρῆσαν.", "st": "24.159"}, {"sp": "N", "t": "καὶ πρῶτον μέν, ἐφ’ ᾧ μέγιστον φρονεῖ, τὴν τῶν χρημάτων εἴσπραξιν ἐξετάσωμεν αὐτοῦ, ἣν μετὰ τούτου τοῦ χρηστοῦ πάντας εἰσέπραξεν ὑμᾶς. αἰτιασάμενος γὰρ Εὐκτήμονα τὰς ὑμετέρας ἔχειν εἰσφοράς, καὶ τοῦτ’ ἐξελέγξειν ἢ παρ’ ἑαυτοῦ καταθήσειν ὑποσχόμενος, καταλύσας ψηφίσματι κληρωτὴν ἀρχὴν ἐπὶ τῇ προφάσει ταύτῃ, ἐπὶ τὴν εἴσπραξιν παρέδυ, καὶ τοῦτον προὐβάλετο, εἰπὼν τὴν τοῦ σώματος ἀρρωστίαν, ἵν’, ἔφη, συνδιοικῇ μοι.", "st": "24.160"}, {"sp": "N", "t": "δημηγορίαν δ’ ἐπὶ τούτοις ποιούμενος, ὡς ἔστι τριῶν αἵρεσις, ἢ τὰ πομπεῖα κατακόπτειν ἢ πάλιν εἰσφέρειν ἢ τοὺς ὀφείλοντας εἰσπράττειν, αἱρουμένων εἰκότως ὑμῶν τοὺς ὀφείλοντας εἰσπράττειν, ταῖς ὑποσχέσεσιν κατέχων καὶ διὰ τὸν καιρὸν ὃς ἦν τότ’ ἔχων ἐξουσίαν, τοῖς μὲν κειμένοις νόμοις περὶ τούτων οὐκ ᾤετο δεῖν χρῆσθαι, οὐδ’, εἰ μὴ τούτους ἐνόμιζ’ ἱκανούς, ἑτέρους τιθέναι, ψηφίσματα δ’ εἶπεν ἐν ὑμῖν δεινὰ καὶ παράνομα, δι’ ὧν ἠργολάβει, προσαγωγεῖ τούτῳ χρώμενος τῶν λημμάτων.", "st": "24.161"}, {"sp": "N", "t": "καὶ πολλὰ τῶν ὑμετέρων κέκλοφεν μετὰ τούτου, γράψας τοὺς ἕνδεκα καὶ τοὺς ἀποδέκτας καὶ τοὺς ὑπηρέτας ἀκολουθεῖν μεθ’ αὑτοῦ. εἶτ’ ἔχων τούτους ἦγ’ ἐπὶ τὰς ὑμετέρας οἰκίας, καὶ σύ, ὦ Τιμόκρατες, συνηκολούθεις μόνος τῶν συναρχόντων δέκ’ ὄντων. καὶ μηδεὶς ὑπολαμβανέτω με λέγειν ὡς οὐ χρῆν εἰσπράττειν τοὺς ὀφείλοντας. χρῆν γάρ. ἀλλὰ πῶς; ὡς ὁ νόμος ἀγορεύει· τῶν ἄλλων ἕνεκα· τοῦτο γάρ ἐστι δημοτικόν. οὐ γὰρ τοσοῦτον, ὦ ἄνδρες Ἀθηναῖοι, πέντε ταλάντων ὑμῖν, ὧν οὗτοι τότ’ εἰσέπραξαν, τεθέντων ὠφέλησθε, ὅσον βέβλαφθε τοιούτων ἐθῶν εἰς τὴν πολιτείαν εἰσαγομένων.", "st": "24.162"}, {"sp": "N", "t": "εἰ γὰρ θέλετ’ ἐξετάσαι τίνος εἵνεκα μᾶλλον ἄν τις ἕλοιτ’ ἐν δημοκρατίᾳ ζῆν ἢ ἐν ὀλιγαρχίᾳ, τοῦτ’ ἂν εὕροιτε προχειρότατον, ὅτι πάντα πραότερ’ ἐν δημοκρατίᾳ. ὅτι μὲν τοίνυν τῆς ὅπου βούλεσθ’ ὀλιγαρχίας πολλῷ ἀσελγέστερα καὶ δεινότερ’ ἐποίουν οὗτοι, παραλείψω. ἀλλὰ παρ’ ἡμῖν πότε πώποτε δεινότατ’ ἐν τῇ πόλει γέγονεν;", "st": "24.163"}, {"sp": "N", "t": "εὖ οἶδ’ ὅτι ἐπὶ τῶν τριάκοντα ἅπαντες ἂν εἴποιτε. τότε τοίνυν, ὡς ἔστιν ἀκούειν, οὐδεὶς ἔστιν ὅστις ἀπεστερεῖτο τοῦ σωθῆναι, ὅστις ἑαυτὸν οἴκοι κρύψειεν, ἀλλ’ αὐτὸ τοῦτο κατηγοροῦσι τῶν τριάκοντα, ὅτι τοὺς ἐκ τῆς ἀγορᾶς ἀδίκως ἀπῆγον. οὗτοι τοίνυν τοσαύτην ὑπερβολὴν ἐποιήσαντ’ ἐκείνων τῆς αὑτῶν πονηρίας ὥστ’ ἐν δημοκρατίᾳ πολιτευόμενοι τὴν ἰδίαν οἰκίαν ἑκάστῳ δεσμωτήριον καθίστασαν, τοὺς ἕνδεκ’ ἄγοντες ἐπὶ τὰς οἰκίας.", "st": "24.164"}, {"sp": "N", "t": "καίτοι, ὦ ἄνδρες Ἀθηναῖοι, τί οἴεσθ’ ὁπότ’ ἄνθρωπος πένης ἢ καὶ πλούσιος, πολλὰ δ’ ἀνηλωκὼς καί τιν’ ἴσως τρόπον εἰκότως οὐκ εὐπορῶν ἀργυρίου, μὴ μόνον εἰς τὴν ἀγορὰν φοβοῖτ’ ἐμβαλεῖν, ἀλλὰ μηδ’ οἴκοι μένειν ἀσφαλὲς ἡγοῖτο, ὁ δὲ τούτων αἴτιος Ἀνδροτίων εἴη, ὃν οὐδ’ ὑπὲρ αὑτοῦ δίκην ἐᾷ λαβεῖν τὰ πεπραγμένα καὶ βεβιωμένα, μή τί γ’ ὑπὲρ τῆς πόλεως [εἰσπράττειν εἰσφοράς];", "st": "24.165"}, {"sp": "N", "t": "καίτοι εἴ τις ἔροιτ’ αὐτὸν ἢ σέ, ὦ Τιμόκρατες, τὸν ἐπαινέτην τούτων καὶ συνεργόν, τὰς εἰσφορὰς πότερον τὰ κτήματ’ ἢ τὰ σώματ’ ὀφείλει, τὰ κτήματα φήσαιτ’ ἄν, εἴπερ ἀληθῆ λέγειν βούλοισθε· ἀπὸ γὰρ τούτων εἰσφέρομεν. τίνος οὖν ἕνεκ’, ὦ κάκιστοι πάντων ἀνθρώπων, ἀφέντες τὸ τὰ χωρία δημεύειν καὶ τὰς οἰκίας καὶ ταῦτ’ ἀπογράφειν, ἐδεῖτε καὶ ὑβρίζετε πολίτας ἀνθρώπους καὶ τοὺς ταλαιπώρους μετοίκους, οἷς ὑβριστικώτερον ὑμεῖς ἢ τοῖς οἰκέταις τοῖς ὑμετέροις αὐτῶν ἐχρῆσθε;", "st": "24.166"}, {"sp": "N", "t": "καὶ μὴν εἰ θέλετε σκέψασθαι παρ’ ὑμῖν αὐτοῖς, ὦ ἄνδρες δικασταί, τί δοῦλον ἢ ἐλεύθερον εἶναι διαφέρει, τοῦτο μέγιστον ἂν εὕροιτε, ὅτι τοῖς μὲν δούλοις τὸ σῶμα τῶν ἀδικημάτων ἁπάντων ὑπεύθυνόν ἐστιν, τοῖς δ’ ἐλευθέροις ὕστατον τοῦτο προσήκει κολάζειν. οἱ δὲ τοὐναντίον εἰς τὰ σώματα, ὥσπερ ἀνδραπόδοις, ἐποιήσαντο τὰς τιμωρίας.", "st": "24.167"}, {"sp": "N", "t": "οὕτω δ’ ἀνίσως καὶ πλεονεκτικῶς ἔσχε πρὸς ὑμᾶς Ἀνδροτίων ὥστε τὸν μὲν αὑτοῦ πατέρ’ ᾤετο δεῖν, δημοσίᾳ δεθέντ’ ἐπὶ χρήμασιν ἐν τῷ δεσμωτηρίῳ, μήτ’ ἀποδόντα ταῦτα μήτε κριθέντ’ ἀποδρᾶναι, τῶν δ’ ἄλλων πολιτῶν τὸν μὴ δυνάμενον τὰ ἑαυτοῦ θεῖναι οἴκοθεν εἰς τὸ δεσμωτήριον ἀχθένθ’ ὑφ’ ἑαυτοῦ δεδέσθαι.", "st": "24.168"}, {"sp": "N", "t": "καὶ Τιμοκράτης τῶν μὲν πολλῶν ἡμῶν τότε, ὅτε τὴν διπλασίαν εἰσέπραττεν, οὐδ’ ἂν παρ’ ἑνὸς λαβεῖν ἠθέλησεν ἐγγυητάς, μὴ ⟨ὅτι⟩ μέχρι τῆς ἐνάτης πρυτανείας, ἀλλ’ οὐδὲ μιᾶς ἡμέρας, ἀλλ’ ἢ διπλᾶ τὰ χρήματ’ ἔδει καταβάλλειν ἢ παραχρῆμα δεδέσθαι· παρεδίδου δ’ οὗτος τοῖς ἕνδεκα τὸν οὐκ ὠφληκότ’ ἐν τῷ δικαστηρίῳ. νῦν δ’ ὅπως ὧν ἂν ὑμεῖς καταγνῶτ’ ἄδετοι περιίασιν, ὑπεύθυνον αὑτὸν ποιήσας νόμον εἰσενεγκεῖν ἐτόλμησεν.", "st": "24.169"}, {"sp": "N", "t": "ἀλλ’ ὅμως κἀκεῖνα καὶ τάδε φήσουσ’ ὑπὲρ ὑμῶν πράττειν. εἶτα ταῦθ’ ὑμεῖς ἀναδέξεσθ’ ὑπὲρ ὑμῶν πεπρᾶχθαι, καὶ τὰ τῆς τούτων θρασύτητος καὶ πονηρίας ἔργα πράως οἴσετε; ἀλλὰ μισεῖν ὀφείλετε τοὺς τοιούτους, ὦ ἄνδρες Ἀθηναῖοι, μᾶλλον ἢ σῴζειν. τὸν γὰρ ὑπὲρ τῆς πόλεως πράττοντά τι καὶ πράων ὑμῶν τευξόμενον τὸ τῆς πόλεως ἦθος ἔχοντα δεῖ φαίνεσθαι.", "st": "24.170"}, {"sp": "N", "t": "τοῦτο δ’ ἐστὶ τί; τοὺς ἀσθενεῖς ἐλεεῖν, τοῖς ἰσχυροῖς καὶ δυναμένοις μὴ ἐπιτρέπειν ὑβρίζειν, οὐ τοὺς μὲν πολλοὺς ὠμῶς μεταχειρίζεσθαι, κολακεύειν δὲ τὸν ἀεί τι δύνασθαι δοκοῦντα. ὃ σὺ ποιεῖς, ὦ Τιμόκρατες· δι’ ἃ πολλῷ μᾶλλον ἂν εἰκότως μὴ θελήσαντες ἀκοῦσαι σοῦ θάνατον καταψηφίσαινθ’ οὗτοι ἢ δι’ Ἀνδροτίων’ ἀφείησαν.", "st": "24.171"}, {"sp": "N", "t": "ὅτι τοίνυν οὐδὲ τὴν εἴσπραξιν αὐτὴν ὑπὲρ ὑμῶν πεποίηνται, καὶ τοῦτ’ αὐτίκα δὴ μάλ’ ὑμῖν δῆλον ποιήσω. εἰ γάρ τις ἔροιτ’ αὐτοὺς πότερ’ αὐτοῖς δοκοῦσ’ ἀδικεῖν μᾶλλον τὴν πόλιν οἱ γεωργοῦντες καὶ φειδόμενοι, διὰ παιδοτροφίας δὲ καὶ οἰκεῖ’ ἀναλώματα καὶ λῃτουργίας ἑτέρας ἐλλελοιπότες εἰσφοράν, ἢ οἱ τὰ τῶν ἐθελησάντων εἰσενεγκεῖν χρήματα καὶ τὰ παρὰ τῶν συμμάχων κλέπτοντες καὶ ἀπολλύντες, οὐκ ἂν εἰς τοῦτο δήπου τόλμης, καίπερ ὄντες ἀναιδεῖς, ἔλθοιεν, ὥστε φῆσαι τοὺς τὰ ἑαυτῶν μὴ εἰσφέροντας μᾶλλον ἀδικεῖν ἢ τοὺς τὰ κοίν’ ὑφαιρουμένους.", "st": "24.172"}, {"sp": "N", "t": "τίνος οὖν ἕνεκ’, ὦ Τιμόκρατες καὶ Ἀνδροτίων, ἐτῶν ὄντων πλειόνων ἢ τριάκοντ’ ἀφ’ οὗ ὅ γ’ ἕτερος ὑμῶν πολιτεύεται, καὶ ἐν τούτῳ τῷ χρόνῳ πολλῶν μὲν στρατηγῶν ἠδικηκότων τὴν πόλιν, πολλῶν δὲ ῥητόρων, οἳ παρὰ τουτοισὶ κέκρινται, ὧν οἱ μὲν τεθνᾶσιν ἐφ’ οἷς ἠδίκουν, οἱ δ’ ὑποχωρήσαντες ᾤχοντο καταγνόντες αὑτῶν, οὐδενὸς πώποτε τούτων ἐξητάσθη κατήγορος ὑμῶν οὐδέτερος, οὐδ’ ἀγανακτῶν ὤφθη ὑπὲρ ὧν ἡ πόλις πάσχει, ἀλλ’ ἐνταῦθ’ ἐφάνηθ’ ἡμῶν κηδόμενοι οὗ πολλοὺς ἔδει κακῶς ποιῆσαι;", "st": "24.173"}, {"sp": "N", "t": "βούλεσθ’, ὦ ἄνδρες Ἀθηναῖοι, τὸ τούτων αἴτιον ἐγὼ ὑμῖν εἴπω; ὅτι τούτων μὲν μετέχουσιν ὧν ἀδικοῦσιν ὑμᾶς τινες, ἀπὸ δὲ τῶν εἰσπραττομένων ὑφαιροῦνται· δι’ ἀπληστίαν δὲ τρόπων διχόθεν καρποῦνται τὴν πόλιν. οὔτε γὰρ ῥᾷον πολλοῖς καὶ τὰ μίκρ’ ἀδικοῦσιν ἀπεχθάνεσθαι ἢ ὀλίγοις καὶ μεγάλα, οὔτε δημοτικώτερον δήπου τὰ τῶν πολλῶν ἀδικήμαθ’ ὁρᾶν ἢ τὰ τῶν ὀλίγων.", "st": "24.174"}, {"sp": "N", "t": "ἀλλὰ τοῦτ’ αἴτιον οὑγὼ λέγω. δεῖ τοίνυν ὑμᾶς ταῦτα λογιζομένους, καὶ μεμνημένους ὧν ἂν ἕκαστος ἁμάρτῃ, κολάζειν, ὅταν λάβητέ τινα, καὶ μὴ τὸν χρόνον εἰ πολύς ἐστ’ ἀπ’ ἐκείνου σκοπεῖν, ἀλλ’ εἰ ταῦτ’ ἐποίουν. ὡς εἰ νῦν πράως οἴσετ’ ἐφ’ οἷς τότ’ ἠγανακτεῖτε, δόξετ’ ὀργιζόμενοι κατεγνωκέναι τὰ χρήματα τούτων, οὐκ ἀδικούμενοι. τῶν μὲν γὰρ ὀργιζομένων ἐστὶν ὀξέως τι κακὸν τὸν λελυπηκότ’ ἐργάσασθαι, τῶν δ’ ἀδικουμένων, ὅταν ποθ’ ὑφ’ αὑτοῖς λάβωσι τὸν ἠδικηκότα, τότε τιμωρήσασθαι. οὔκουν δεῖ δοκεῖν, νῦν μαλακισθέντας, τότε τῶν ὀμωμοσμένων ὅρκων ἀμελήσαντας ὑμῖν αὐτοῖς χαρίσασθαι παρὰ τὸ δίκαιον, ἀλλὰ μισεῖν καὶ μηδ’ ἀνέχεσθαι φωνὴν μήτε τούτου μήτ’ ἐκείνου, τοιαῦτα πεπολιτευμένων.", "st": "24.175"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦτα μὲν τοιοῦτοι γεγόνασιν ἐν οἷς πεπολίτευνται, ἄλλα δ’ ἔσθ’ ἃ καλῶς διῳκήκασιν. ἀλλὰ καὶ τἄλλ’ οὕτω προσεληλύθασι πρὸς ὑμᾶς ὥσθ’ ἥκιστ’ ἐν οἷς ἀκηκόατ’ ἄξιόν ἐστι μισεῖν αὐτούς. τί γὰρ βούλεσθ’ εἴπω; τὰ πομπεῖ’ ὡς ἐπεσκευάκασι, καὶ τὴν τῶν στεφάνων καθαίρεσιν, ἢ τὴν τῶν φιαλῶν ποίησιν τὴν καλήν;", "st": "24.176"}, {"sp": "N", "t": "ἀλλ’ ἐπὶ τούτοις γε, εἰ μηδὲν ἄλλ’ ἠδίκουν τὴν πόλιν, τρίς, οὐχ ἅπαξ τεθνάναι δικαίως ἄν μοι δοκοῦσιν· καὶ γὰρ ἱεροσυλίᾳ καὶ ἀσεβείᾳ καὶ κλοπῇ καὶ πᾶσι τοῖς δεινοτάτοις εἴσ’ ἔνοχοι. τὰ μὲν οὖν πόλλ’ ὧν λέγων ἐφενάκιζεν ὑμᾶς Ἀνδροτίων, παραλείψω· φήσας δ’ ἀπορρεῖν τὰ φύλλα τῶν στεφάνων καὶ σαπροὺς εἶναι διὰ τὸν χρόνον, ὥσπερ ἴων ἢ ῥόδων ὄντας, ἀλλ’ οὐ χρυσίου, συγχωνεύειν ἔπεισεν. αἱρεθεὶς δ’ ἐπὶ ταῦτα προσείλετο τοῦτον τὸν πάντων τῶν κακῶν κοινωνόν.", "st": "24.177"}, {"sp": "N", "t": "κᾆτ’ ἐπὶ μὲν ταῖς εἰσφοραῖς τὸν δημόσιον παρεῖναι προσέγραψεν ὡς δὴ δίκαιος ὤν, ὧν ἕκαστος ἀντιγραφεὺς ἔμελλεν ἔσεσθαι τῶν εἰσενεγκόντων· ἐπὶ τοῖς στεφάνοις δ’ οὓς κατέκοπτεν οὐχὶ προσήγαγεν ταὐτὸ δίκαιον τοῦτο, ἀλλ’ αὑτὸς ῥήτωρ, χρυσοχόος, ταμίας, ἀντιγραφεὺς γέγονεν.", "st": "24.178"}, {"sp": "N", "t": "καὶ μὴν εἰ μὲν ἅπαντ’ ἠξίους, ὅσα πράττεις τῇ πόλει, σαυτῷ πιστεύειν, οὐκ ἂν ὁμοίως κλέπτης ὢν ἐφωρῶ· νῦν δ’ ἐπὶ ταῖς εἰσφοραῖς ὃ δίκαιόν ἐσθ’ ὁρίσας, μὴ σοὶ πιστεύειν, ἀλλὰ τοῖς αὑτῆς δούλοις τὴν πόλιν, ὁπότ’ ἄλλο τι πράττων καὶ χρήματα κινῶν ἱερά, ὧν ἔνι’ οὐδ’ ἐπὶ τῆς ἡμετέρας γενεᾶς ἀνετέθη, μὴ προσγραψάμενος τὴν αὐτὴν φυλακὴν ἥνπερ ἐπὶ τῶν εἰσφορῶν φαίνει, οὐκ ἤδη δῆλον δι’ ὃ τοῦτ’ ἐποίησας; ἐγὼ μὲν οἶμαι.", "st": "24.179"}, {"sp": "N", "t": "καὶ μήν, ὦ ἄνδρες Ἀθηναῖοι, καὶ κατὰ παντὸς τοῦ χρόνου σκέψασθ’ ὡς καλὰ καὶ ζηλώτ’ ἐπιγράμματα τῆς πόλεως ἀνελὼν ὡς ἀσεβῆ καὶ δείν’ ἀντεπέγραψεν. οἶμαι γὰρ ὑμᾶς ἅπαντας ὁρᾶν ὑπὸ τῶν στεφάνων ταῖς χοινικίσιν κάτωθεν γεγραμμένα “οἱ σύμμαχοι τὸν δῆμον ἀνδραγαθίας εἵνεκα [ἐστεφάνωσαν] καὶ δικαιοσύνης,” ἢ “οἱ σύμμαχοι ἀριστεῖον τῇ Ἀθηναίᾳ [ἀνέθεσαν],” ἢ κατὰ πόλεις “οἱ δεῖνες τὸν δῆμον [ἐστεφάνωσαν] σωθέντες ὑπὸ τοῦ δήμου,” οἷον “Εὐβοεῖς ἐλευθερωθέντες ἐστεφάνωσαν τὸν δῆμον [ἐπεγέγραπτό που],” πάλιν “Κόνων ἀπὸ τῆς ναυμαχίας τῆς πρὸς Λακεδαιμονίους,” “Χαβρίας ἀπὸ τῆς ἐν Νάξῳ ναυμαχίας·” τοιαῦτα γὰρ ἦν τὰ τῶν στεφάνων ἐπιγράμματα.", "st": "24.180"}, {"sp": "N", "t": "ταῦτα μὲν τοίνυν, ἃ [πρότερον] ζῆλον πολὺν εἶχε καὶ φιλοτιμίαν ὑμῖν, ἠφάνισται καθαιρεθέντων τῶν στεφάνων· ἐπὶ ταῖς φιάλαις δ’ ἃς ἀντ’ ἐκείνων ἐποιήσαθ’ ὑμῖν ὁ πόρνος οὗτος, “Ἀνδροτίωνος ἐπιμελουμένου” ἐπιγέγραπται, καὶ οὗ τὸ σῶμ’ ἡταιρηκότος οὐκ ἐῶσιν οἱ νόμοι εἰς τὰ ἱέρ’ εἰσιέναι, τούτου τοὔνομ’ ἐν τοῖς ἱεροῖς ἐπὶ τῶν φιαλῶν γεγραμμένον ἐστίν. ὅμοιόν γε, οὐ γάρ; τοῦτο τοῖς προτέροις ἐπιγράμμασιν, ἢ φιλοτιμίαν ἴσην ἔχον ὑμῖν.", "st": "24.181"}, {"sp": "N", "t": "τρία τοίνυν ἐκ τούτου τὰ δεινότατ’ ἄν τις ἴδοι πεπραγμέν’ αὐτοῖς. τὴν μὲν γὰρ θεὸν τοὺς στεφάνους σεσυλήκασιν· τῆς πόλεως δὲ τὸν ζῆλον ἠφανίκασιν τὸν ἐκ τῶν ἔργων, ὧν ὑπόμνημ’ ἦσαν ὄντες οἱ στέφανοι· τοὺς δ’ ἀναθέντας δόξαν οὐ μικρὰν ἀφῄρηνται, τὸ δοκεῖν ὧν ἂν εὖ πάθωσ’ ἐθέλειν μεμνῆσθαι. καὶ τοιαῦτα καὶ τοσαῦτα τὸ πλῆθος κάκ’ εἰργασμένοι εἰς τοῦτ’ ἀναισθησίας καὶ τόλμης προεληλύθασιν, ὥσθ’ ὁ μὲν οἴεται δι’ ἐκεῖνον ὑφ’ ὑμῶν σωθήσεσθαι, ὁ δὲ παρακάθηται καὶ οὐ καταδύεται τοῖς πεπραγμένοις.", "st": "24.182"}, {"sp": "N", "t": "οὕτω δ’ οὐ μόνον εἰς χρήματ’ ἀναιδής, ἀλλὰ καὶ σκαιός ἐστιν, ὥστ’ οὐκ οἶδεν ἐκεῖνο, ὅτι στέφανοι μέν εἰσ’ ἀρετῆς σημεῖον, φιάλαι δὲ καὶ τὰ τοιαῦτα πλούτου, καὶ στέφανος μὲν ἅπας, κἂν μικρὸς ᾖ, τὴν ἴσην φιλοτιμίαν ἔχει τῷ μεγάλῳ, ἐκπώματα δ’ ἢ θυμιατήρια ἢ τὰ τοιαῦτα κτήματα, ἐὰν μὲν ὑπερβάλλῃ τῷ πλήθει, πλούτου τινὰ δόξαν προσετρίψατο τοῖς κεκτημένοις, ἐὰν δ’ ἐπὶ μικροῖς σεμνύνηταί τις, τοσοῦτ’ ἀπέχει τοῦ τιμῆς τινος διὰ ταῦτα τυχεῖν ὥστ’ ἀπειρόκαλος πρὸς ἔδοξεν εἶναι. οὗτος τοίνυν ἀνελὼν τὰ τῆς δόξης κτήματα τὰ τοῦ πλούτου πεποίηται μικρὰ καὶ ἀνάξι’ ὑμῶν.", "st": "24.183"}, {"sp": "N", "t": "καὶ οὐδ’ ἐκεῖν’ εἶδεν, ὅτι πρὸς μὲν χρημάτων κτῆσιν οὐδεπώποθ’ ὁ δῆμος ἐσπούδασεν, πρὸς δὲ δόξης ὡς οὐδὲ πρὸς ἓν τῶν ἄλλων. τεκμήριον δέ· χρήματα μὲν γὰρ πλεῖστα τῶν Ἑλλήνων ποτὲ σχὼν ἅπανθ’ ὑπὲρ φιλοτιμίας ἀνήλωσεν, ὑπὲρ δὲ δόξης εἰσφέρων ἐκ τῶν ἰδίων οὐδένα πώποτε κίνδυνον ἐξέστη. ἀφ’ ὧν κτήματ’ ἀθάνατ’ αὐτῷ περίεστιν, τὰ μὲν τῶν ἔργων ἡ μνήμη, τὰ δὲ τῶν ἀναθημάτων τῶν ἐπ’ ἐκείνοις σταθέντων τὸ κάλλος, προπύλαια ταῦτα, ὁ παρθενών, στοαί, νεώσοικοι, οὐκ ἀμφορίσκοι δύο οὐδὲ χρυσίδες τέτταρες ἢ τρεῖς, ἄγουσ’ ἑκάστη μνᾶν, ἅς, ὅταν σοι δοκῇ, πάλιν γράψεις καταχωνεύειν.", "st": "24.184"}, {"sp": "N", "t": "οὐ γὰρ ἑαυτοὺς δεκατεύοντες, οὐδ’ ἃν καταράσαινθ’ οἱ ἐχθροὶ ποιοῦντες, διπλᾶς πράττοντες τὰς εἰσφοράς, ταῦτ’ ἀνέθεσαν, οὐδ’ οἵοισπερ σὺ χρώμενοι συμβούλοις ἐπολιτεύοντο, ἀλλὰ τοὺς ἐχθροὺς κρατοῦντες, καὶ ἃ πᾶς τις ἂν εὖ φρονῶν εὔξαιτο, τὴν πόλιν εἰς ὁμόνοιαν ἄγοντες, ἀθάνατον κλέος αὑτῶν λελοίπασι, τοὺς ἐπιτηδεύοντας οἷά σοι βεβίωται τῆς ἀγορᾶς εἴργοντες.", "st": "24.185"}, {"sp": "N", "t": "ὑμεῖς δ’ εἰς τοσοῦτον, ὦ ἄνδρες Ἀθηναῖοι, προῆχθ’ εὐηθείας καὶ ῥᾳθυμίας ὥστ’ οὐδὲ τοιαῦτ’ ἔχοντες παραδείγματα ταῦτα μιμεῖσθε, ἀλλ’ Ἀνδροτίων ὑμῖν πομπείων ἐπισκευαστής, Ἀνδροτίων, ὦ γῆ καὶ θεοί. καὶ τοῦτ’ ἀσέβημ’ ἔλαττον τίνος ἡγεῖσθε; ἐγὼ μὲν γὰρ ἡγοῦμαι δεῖν τὸν εἰς ἱέρ’ εἰσιόντα καὶ χερνίβων καὶ κανῶν ἁψόμενον, καὶ τῆς πρὸς τοὺς θεοὺς ἐπιμελείας προστάτην ἐσόμενον οὐχὶ τακτὸν ἡμερῶν ἀριθμὸν ἁγνεύειν, ἀλλὰ τὸν βίον ἡγνευκέναι τοιούτων ἐπιτηδευμάτων οἷα τούτῳ βεβίωται.", "st": "24.186"}, {"sp": "N", "t": "καὶ περὶ μὲν τούτου κατὰ σχολήν· ἃ δὲ Τιμοκράτης νῦν ἐρεῖ, πολλὰ λέγειν ἔτι πρὸς τούτοις ἔχων παύσομαι. οἶδα δ’ ὅτι, ὡς μὲν οὐκ ἀσύμφορος ὑμῖν ἐσθ’ ὁ νόμος καὶ παρὰ πάντας τοὺς νόμους εἰσενηνεγμένος καὶ κατὰ πάντ’ ἀδίκως ἔχων, οὐχ ἕξει λέγειν· ἀκούω δ’ αὐτὸν λέγειν ὡς ἐκτέτεισται τὰ χρήματ’ Ἀνδροτίωνι καὶ Γλαυκέτῃ καὶ Μελανώπῳ, καὶ ὅτι δεινότατ’ ἂν πάθοι πάντων ἀνθρώπων, εἰ πεποιηκότων ἐκείνων τὰ δίκαια, ὑπὲρ ὧν [αὐτὸς] αἰτίαν ἔχει θεῖναι τὸν νόμον, μηδὲν ἧττον αὐτὸς ἁλίσκοιτο.", "st": "24.187"}, {"sp": "N", "t": "ἐγὼ δὲ τὸν λόγον ἡγοῦμαι τοῦτον οὐδὲ καθ’ ἓν λέγειν ἐνεῖναι τούτῳ. εἰ μὲν γὰρ ὑπὲρ τούτων, οὓς τὰ προσήκοντα φῂς πεποιηκέναι, θεῖναι τὸν νόμον ὁμολογεῖς, κατ’ ἐκεῖνο προσήκει σ’ ἁλίσκεσθαι φανερῶς, ὅτι μὴ τιθέναι νόμον, ἂν μὴ τὸν αὐτὸν ἐπὶ πᾶσι τοῖς πολίταις, ἄντικρυς οἱ κύριοι νόμοι λέγουσι, καθ’ οὓς οὗτοι δικάσειν ὀμωμόκασιν.", "st": "24.188"}, {"sp": "N", "t": "εἰ δὲ τοῦ πᾶσι συμφέροντος εἵνεκα ταῦτα νομοθετῆσαι φήσεις, μὴ λέγε τὴν ἔκτισιν τὴν τούτων· οὐδὲν γὰρ κοινωνεῖ τῷ νόμῳ τῷδε· ἀλλ’ ὡς ἐπιτήδειός ἐστιν καὶ καλῶς ἔχων ὁ νόμος, τοῦτο δίδασκε. τοῦτο γάρ ἐσθ’ ὑπὲρ οὗ σὺ μὲν εἰσενεγκεῖν φῄς, ἐγὼ δὲ γέγραμμαι τἀναντία φάσκων, κρῖναι δὲ προσήκει τουτουσί. καίτοι καὶ τοῦτ’ οὐκ ἀπορήσαιμ’ ἂν δεῖξαι, πάντα μᾶλλον ἢ κατὰ τοὺς νόμους πεποιημένους τὴν ἔκτισιν ἐκείνους τὴν τῶν χρημάτων· ἀλλὰ μὴ περὶ τούτων ὑμῶν οἰσόντων τὴν ψῆφον, τί δεῖ ταῦτα λέγοντ’ ἐνοχλεῖν με νυνί;", "st": "24.189"}, {"sp": "N", "t": "οἶμαι τοίνυν αὐτὸν οὐδ’ ἐκείνων ἀφέξεσθαι τῶν λόγων, ὡς δείν’ ἂν πάθοι, εἰ γράψας ὅπως Ἀθηναίων μηδεὶς δεθήσεται αὐτὸς πείσεταί τι κακόν, καὶ ὅτι τοὺς νόμους ὡς πραοτάτους καὶ μετριωτάτους εἶναι ὑπὲρ τῶν ἀδυνάτων μάλιστ’ ἐστίν. πρὸς δὴ τοὺς τοιούτους λόγους βέλτιον ἀκηκοέναι μικρὰ πάντας ὑμᾶς, ἵν’ ἧττον ἐξαπατᾶσθε.", "st": "24.190"}, {"sp": "N", "t": "ὅταν μὲν γὰρ λέγῃ, ὅπως μηδεὶς Ἀθηναίων δεθήσεται, μὴ λανθανέτω ψευδόμενος ὑμᾶς. οὐ γὰρ τοῦτο τέθηκεν, ἀλλ’ ὅπως ὑμεῖς ἄκυροι τῶν προστιμημάτων ἔσεσθε· καὶ τὴν μεθ’ ὅρκου καὶ λόγου καὶ κρίσεως ψῆφον ἐνηνεγμένην ἀνάδικον καθίστησιν. μὴ δὴ ταῦθ’ ὑμῖν τῶν ἐκ τοῦ νόμου ῥημάτων ἐκλέξας λεγέτω, ἃ φιλανθρωπότατ’ ἐστὶν ἀκοῦσαι· ἀλλ’ ὅλον δεικνύτω τὸν νόμον ἑξῆς, καὶ τὰ συμβαίνοντ’ ἐξ αὐτοῦ σκοπεῖν ἐάτω. εὑρήσετε γὰρ ταῦτ’ ὄνθ’ ἃ ἐγὼ λέγω, καὶ οὐχ ἅ φησιν οὗτος.", "st": "24.191"}, {"sp": "N", "t": "ἀλλὰ μὴν πρός γε τὸ τοῖς πολλοῖς συμφέρειν τοὺς νόμους πράους καὶ μετρίους εἶναι τάδε χρὴ σκοπεῖν. ἔστιν, ὦ ἄνδρες Ἀθηναῖοι, δύ’ εἴδη περὶ ὧν εἰσιν οἱ νόμοι κατὰ πάσας τὰς πόλεις· ὧν τὸ μέν ἐστιν, δι’ ὧν χρώμεθ’ ἀλλήλοις καὶ συναλλάττομεν καὶ περὶ τῶν ἰδίων ἃ χρὴ ποιεῖν διωρίσμεθα καὶ ζῶμεν ὅλως τὰ πρὸς ἡμᾶς αὐτούς, τὸ δέ, ὃν τρόπον δεῖ τῷ κοινῷ τῆς πόλεως ἕν’ ἕκαστον ἡμῶν χρῆσθαι, ἂν πολιτεύεσθαι βούληται καὶ φῇ κήδεσθαι τῆς πόλεως.", "st": "24.192"}, {"sp": "N", "t": "ἐκείνους μὲν τοίνυν τοὺς νόμους τοὺς περὶ τῶν ἰδίων ἠπίως κεῖσθαι καὶ φιλανθρώπως ὑπὲρ τῶν πολλῶν ἐστιν· τούσδε δὲ τοὺς περὶ τῶν πρὸς τὸ δημόσιον τοὐναντίον ἰσχυρῶς καὶ χαλεπῶς ἔχειν ὑπὲρ ὑμῶν ἐστιν· οὕτω γὰρ ἂν ἥκισθ’ οἱ πολιτευόμενοι τοὺς πολλοὺς ὑμᾶς ἀδικοῖεν. ὅταν δὴ τούτῳ τῷ λόγῳ χρῆται, ἐπὶ ταῦτ’ ἀπαντᾶτε, ὅτι τοὺς νόμους οὐκ ἐκείνους τοὺς ὑπὲρ ὑμῶν πράους ποιεῖ, ἀλλὰ τούσδ’ οἳ τοῖς πολιτευομένοις φόβον παρέχουσιν.", "st": "24.193"}, {"sp": "N", "t": "πολλὰ δ’ ἄν τις ἔχοι λέγειν, εἰ καθ’ ἕκαστον ὧν ἐρεῖ δεικνύναι βούλοιτο φενακισμοῦ καὶ παρακρούσεως εἵνεκα ῥηθησόμενα. ἀλλὰ τὰ μὲν πολλὰ παρήσω, κεφάλαιον δ’ ὑμῖν ὃ μνημονεύσετ’ ἐρῶ. σκοπεῖτ’ ἐν ἅπασι τοῖς λόγοις, ὁπόσους ἂν λέγῃ, εἴ τι δυνήσεται τοιοῦτον εἰπεῖν δι’ οὗ διδάξει ὡς ἔστι δίκαιον τὸν τιθέντα νόμον ταὐτὰ προστάξαι περὶ τῶν παρεληλυθότων καὶ τέλος ἐσχηκότων καὶ περὶ τῶν μελλόντων γενήσεσθαι· πάντων γὰρ ὄντων αἰσχρῶν καὶ δεινῶν τῶν γεγραμμένων ἐν τῷ νόμῳ, τοῦτο δεινότατον καὶ μάλιστα παράνομον γέγραπται.", "st": "24.194"}, {"sp": "N", "t": "εἰ δὲ μήθ’ οὗτος μήτ’ ἄλλος μηδεὶς τοῦτο δυνήσεται δεῖξαι, εἰδέναι χρὴ σαφῶς φενακιζομένους, καὶ λογίζεσθαι πρὸς ὑμᾶς αὐτοὺς ἐκ τίνος ποτ’ ἐπῆλθε τούτῳ τοιαῦτα νομοθετεῖν. οὐ προῖκ’, ὦ Τιμόκρατες, πόθεν; οὐδ’ ὀλίγου δεῖ, τοῦτον ἔθηκας τὸν νόμον· οὐδεμίαν γὰρ ἂν εἰπεῖν ἔχοις ἄλλην πρόφασιν δι’ ἣν τοιοῦτον ἐπήρθης εἰσενεγκεῖν νόμον, ἢ τὴν σαυτοῦ θεοῖς ἐχθρὰν αἰσχροκέρδειαν· οὔτε γὰρ συγγενὴς οὔτ’ οἰκεῖος οὔτ’ ἀναγκαῖος ἦν σοι τούτων οὐδείς.", "st": "24.195"}, {"sp": "N", "t": "οὐδ’ ἐκεῖν’ ἂν ἔχοις εἰπεῖν, ὡς ἐλεήσας δεινὰ πάσχοντας ἀνθρώπους εἵλου διὰ ταῦτα βοηθεῖν αὐτοῖς· οὔτε γὰρ τὰ τούτων πολλοστῷ χρόνῳ μόλις ἄκοντας, ἐν τρισὶν ἐξελεγχθέντας δικαστηρίοις, κατατιθέναι, τοῦθ’ ἡγήσω [τὸ] δεινὰ πάσχειν εἶναι· ποιεῖν γάρ ἐστι τοῦτό γε δεινά, καὶ παροξύνειεν μᾶλλον ἄν τινα μισεῖν ἢ προτρέψει’ ἐλεεῖν· οὔτ’ ἄλλως πρᾶος καὶ φιλάνθρωπος σύ τις τῶν ἄλλων διαφόρως ὢν ἐλεεῖς αὐτούς·", "st": "24.196"}, {"sp": "N", "t": "οὐ γάρ ἐστι τῆς αὐτῆς ψυχῆς Ἀνδροτίωνα μὲν καὶ Μελάνωπον καὶ Γλαυκέτην ἐλεεῖν, ἃ κλέψαντες εἶχον εἰ καταθήσουσι, τουτωνὶ δὲ τοσούτων ὄντων καὶ τῶν ἄλλων πολιτῶν, ὧν ἐπὶ τὰς οἰκίας ἐβάδιζες σὺ τοὺς ἕνδεκα καὶ τοὺς ἀποδέκτας ἔχων καὶ τοὺς ὑπηρέτας, μηδένα πώποτ’ ἐλεῆσαι, ἀλλὰ θύρας ἀφαιρεῖν καὶ στρώμαθ’ ὑποσπᾶν καὶ διάκονον, εἴ τις ἐχρῆτο, ταύτην ἐνεχυράζειν· ἃ σὺ πάντ’ ἐποίεις ἐνιαυτὸν ὅλον μετ’ Ἀνδροτίωνος.", "st": "24.197"}, {"sp": "N", "t": "πολλῷ γὰρ δήπου σχετλιώτερ’ ἐπάσχεθ’ ὑμεῖς, καὶ πολὺ μᾶλλον ἂν εἰκότως ἠλέεις τούτους, οἳ δι’ ὑμᾶς, ὦ κατάρατε, τοὺς λέγοντας οὐδ’ ὁτιοῦν εἰσφέροντες παύονται. καὶ οὐκ ἀπόχρη τοῦτο, ἀλλὰ καὶ διπλᾶ πράττονται, καὶ ταῦθ’ ὑπὸ σοῦ καὶ Ἀνδροτίωνος, οἳ μίαν εἰσφορὰν οὐδεπώποτ’ εἰσενηνόχατε.", "st": "24.198"}, {"sp": "N", "t": "τηλικοῦτο τοίνυν ἐφρόνησεν οὗτος, ὡς ἄρ’ οὐδὲ δίκην τούτων οὐδεμίαν δώσων, ὥστε μόνος δέκα τῶν συναρχόντων ὄντων κοινῇ τὸν λόγον ἐγγράψαι μετ’ Ἀνδροτίωνος ἐτόλμησεν. προῖκα γάρ, οὐδὲν ὠφελούμενος, ὑμῖν Τιμοκράτης ἀπεχθάνεται καὶ νόμους εἰσφέρει πᾶσιν ἐναντίους, τὸ τελευταῖον δὲ καὶ αὑτοῦ νόμῳ προτέρῳ, ὃ μὰ τὴν Ἀθηνᾶν οὐδ’ ὑμᾶς οἴομαι λανθάνειν.", "st": "24.199"}, {"sp": "N", "t": "ὃ τοίνυν ἔμοιγε δοκεῖ μάλιστ’ ἄξιον ὀργῆς εἶναι, φράσω καὶ οὐκ ἀποτρέψομαι, ὅτι ταῦτ’, ὦ ἄνδρες Ἀθηναῖοι, πράττων ἐπ’ ἀργυρίῳ, καὶ προῃρημένος ὡς ἀληθῶς μισθαρνεῖν, οὐκ εἰς ἃ καὶ συγγνώμην ἀκούσας ἄν τις ἔσχε, ταῦτ’ ἀναλίσκει. ταῦτα δ’ ἐστὶν τί; ὁ πατήρ, ὦ ἄνδρες δικασταί, ὁ τούτου τῷ δημοσίῳ ὀφείλει· καὶ οὐκ ὀνειδίζων ἐκείνῳ λέγω, ἀλλ’ ἀναγκαζόμενος· καὶ οὗτος ὁ χρηστὸς περιορᾷ.", "st": "24.200"}, {"sp": "N", "t": "καίτοι ὅστις μέλλων κληρονομήσειν τῆς ἀτιμίας, ἂν ἐκεῖνός τι πάθῃ, μὴ οἴεται δεῖν ἐκτεῖσαι, ἀλλὰ κερδαίνειν, ὃν ἐκεῖνος ζῇ χρόνον, ἀξιοῖ τοῦτο τὸ κέρδος, τίνος ἂν ὑμῖν ἀποσχέσθαι δοκεῖ; καὶ τὸν μὲν πατέρ’ οὔτ’ ἐλεεῖς οὔτε δεινά σοι δοκεῖ πάσχειν, εἰ σοῦ λαμβάνοντος καὶ χρηματιζομένου ἀπὸ τῶν εἰσφορῶν ὧν εἰσέπραττες, ἀπὸ τῶν ψηφισμάτων ὧν γράφεις, ἀφ’ ὧν εἰσφέρεις νόμων, διὰ μικρὸν ἀργύριον μὴ μετέχει τῆς πόλεως, ἑτέρους δ’ ἐλεῆσαί τινας φῄς;", "st": "24.201"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία τὴν ἀδελφὴν καλῶς διῴκηκεν. ἀλλ’ εἰ καὶ μηδὲν ἄλλ’ ἠδίκει, κατὰ τοῦτ’ ἄξιός ἐστ’ ἀπολωλέναι· πέπρακε γὰρ αὐτήν, οὐκ ἐκδέδωκεν. τῶν γὰρ ὑμετέρων ἐχθρῶν ἑνί, Κερκυραίῳ τινὶ τῶν νῦν ἐχόντων τὴν πόλιν, καταλύοντι παρ’ αὐτῷ, ὅτε δεῦρο πρεσβεύοι, καὶ βουληθέντι λαβεῖν αὐτήν (ἐξ οὗ δὲ τρόπου, παραλείψω) λαβὼν ἀργύριον δέδωκεν· καὶ νῦν ἐστιν ἐν Κερκύρᾳ.", "st": "24.202"}, {"sp": "N", "t": "ὃς οὖν τὴν μὲν ἀδελφὴν ἐπ’ ἐξαγωγῇ, φησὶ μὲν ἐκδοῦναι, πέπρακε δὲ τῷ ἔργῳ. τὸν δ’ αὑτοῦ πατέρ’ οὕτω γηροτροφεῖ, κολακεύει δὲ καὶ μισθοῦ γράφει καὶ πολιτεύεται, τοῦτον ὑμεῖς λαβόντες οὐκ ἀποκτενεῖτε; δόξετ’ ἄρ’, ὦ ἄνδρες Ἀθηναῖοι, κρίσεις βούλεσθαι καὶ πράγματ’ ἔχειν, ἀλλ’ οὐκ ἀπηλλάχθαι τῶν πονηρῶν.", "st": "24.203"}, {"sp": "N", "t": "καὶ μὴν ὅτι μὲν προσήκει πάντας κολάζειν τοὺς ἀδικοῦντας, εὖ οἶδ’ ὅτι πάντες ἄν, εἴ τις ἔροιτο, φήσαιτε· ὅσῳ δὲ μάλιστα τοῦτον, ὃς νόμον εἰσενήνοχ’ ἐπὶ βλάβῃ τοῦ πλήθους, ἐγὼ πειράσομαι διδάξαι. τῶν μὲν γὰρ κλεπτῶν καὶ λωποδυτῶν καὶ τὰ τοιαῦτα κακουργούντων ἕκαστος πρῶτον μὲν ὡς ἀληθῶς τὸν ἐντυχόντ’ ἀδικεῖ, καὶ οὐκ ἂν οἷός τ’ εἴη πάντας ἐκδύειν οὐδὲ τὰ πάντων ὑφελέσθαι, εἶτα καταισχύνει τὴν αὑτοῦ δόξαν καὶ τὸν βίον μόνον.", "st": "24.204"}, {"sp": "N", "t": "εἰ δέ τις εἰσφέρει νόμον ἐξ οὗ τοῖς ὑμᾶς βουλομένοις ἀδικεῖν ἡ πᾶσ’ ἐξουσία καὶ ἄδεια γενήσεται, οὗτος ὅλην ἀδικεῖ τὴν πόλιν καὶ καταισχύνει πάντας· νόμος γὰρ αἰσχρὸς ὅταν κύριος ᾖ, τῆς πόλεως ὄνειδός ἐστι τῆς θεμένης, καὶ βλάπτει πάντας ὅσοι περ ἂν αὐτῷ χρῶνται. τὸν οὖν καὶ βλάπτειν ὑμᾶς καὶ δόξης ἀναπιμπλάναι φαύλης ἐπιχειροῦντα, τοῦτον οὐ τιμωρήσεσθε λαβόντες;", "st": "24.205"}, {"sp": "N", "t": "καὶ τί φήσετε; γνοίη δ’ ἄν τις οὕτω μάλισθ’ ἡλίκα πράγματα συσκευάσας γέγραφ’ αὐτόν, καὶ ταῦθ’ ὡς ὑπεναντία τῇ καθεστώσῃ πολιτείᾳ, εἰ λογίσαιθ’ ὅτι πάντες, ὅταν που καταλύοντες τὸν δῆμον πράγμασιν ἐγχειρῶσι νεωτέροις, τοῦτο ποιοῦσι πρῶτον ἁπάντων· ἔλυσαν τοὺς πρότερον νόμῳ δι’ ἁμαρτίαν τινὰ ταύτην ὑπέχοντας τὴν δίκην.", "st": "24.206"}, {"sp": "N", "t": "πῶς οὖν οὐκ ἄξιος οὗτος, εἰ δυνατόν, τρίς, οὐχ ἅπαξ ἀπολωλέναι, ὃς εἷς ὢν καὶ οὐ δήπου μέλλων καταλύσειν ὑμᾶς, ἀλλὰ τοὐναντίον αὐτὸς ἐν ὑμῖν, ἂν τὰ δίκαια καὶ τὰ προσήκοντα ποιῆτε, ἀπολεῖσθαι, ὅμως ἐμιμήσατο τοῦτο τἀδίκημα, καὶ διὰ τοῦ νόμου λύειν ἠξίωσεν οὓς δέδεκεν τὰ δικαστήρια, γράψας ἀναιδῶς, εἴ τινι προστετίμηται δεσμοῦ κἂν τὸ λοιπόν τινι προστιμήσητε, τοῦτον ἀφεῖσθαι.", "st": "24.207"}, {"sp": "N", "t": "καὶ μὴν εἰ αὐτίκα δὴ μάλα κραυγὴν ἀκούσαιτε πρὸς τῷ δικαστηρίῳ, εἶτ’ εἴποι τις ὡς ἀνέῳκται τὸ δεσμωτήριον, οἱ δὲ δεσμῶται φεύγουσιν, οὐδεὶς οὔτε γέρων οὔτ’ ὀλίγωρος οὕτως ὅστις οὐχὶ βοηθήσειεν ἂν καθ’ ὅσον δύναται. εἰ δὲ δή τις εἴποι παρελθὼν ὡς ὁ τούτους ἀφείς ἐστιν οὑτοσί, οὐδὲ λόγου τυχὼν ἂν εὐθὺς ἀπαχθεὶς θανάτῳ ζημιωθείη.", "st": "24.208"}, {"sp": "N", "t": "νῦν τοίνυν ἔχετ’, ὦ ἄνδρες Ἀθηναῖοι, τοῦτον, ὃς οὐχὶ λάθρα πεποίηκε τοῦτο, ἀλλὰ φενακίσας καὶ παρακρουσάμενος νόμον τέθηκεν φανερῶς ὃς οὐκ ἀνοίγνυσι τὸ δεσμωτήριον, ἀλλὰ καθαιρεῖ, προσπεριείληφε δὲ καὶ τὰ δικαστήρια. τίς γὰρ ἢ τούτων ἢ ἐκείνου χρεία, ὅταν οἷς τετίμηται δεσμοῦ λύωνται, κἂν τὸ λοιπὸν τιμήσητέ τῳ, μηδὲν ὑμῖν ᾖ πλέον;", "st": "24.209"}, {"sp": "N", "t": "δεῖ τοίνυν ὑμᾶς κἀκεῖνο σκοπεῖν, ὅτι πολλοὶ τῶν Ἑλλήνων πολλάκις εἰσὶν ἐψηφισμένοι τοῖς νόμοις χρῆσθαι τοῖς ὑμετέροις, ἐφ’ ᾧ φιλοτιμεῖσθ’ ὑμεῖς, εἰκότως· ὃ γὰρ εἰπεῖν τινά φασιν ἐν ὑμῖν, ἀληθὲς εἶναί μοι δοκεῖ, ὅτι τοὺς νόμους ἅπαντες ὑπειλήφασιν, ὅσοι σωφρονοῦσι, τρόπους τῆς πόλεως. χρὴ τοίνυν σπουδάζειν ὅπως ὡς βέλτιστοι δόξουσιν εἶναι, καὶ τοὺς λυμαινομένους καὶ διαστρέφοντας αὐτοὺς κολάζειν, ὡς εἰ καταρρᾳθυμήσετε, τῆς φιλοτιμίας τε ταύτης ἀποστερήσεσθε καὶ κατὰ τῆς πόλεως δόξαν οὐ χρηστὴν ποιήσετε.", "st": "24.210"}, {"sp": "N", "t": "καὶ μὴν εἰ Σόλωνα καὶ Δράκοντα δικαίως ἐπαινεῖτε, οὐκ ἂν ἔχοντες εἰπεῖν οὐδετέρου κοινὸν εὐεργέτημ’ οὐδὲν πλὴν ὅτι συμφέροντας ἔθηκαν καὶ καλῶς ἔχοντας νόμους, δίκαιον δήπου καὶ τοῖς ὑπεναντίως τιθεῖσιν ἐκείνοις ὀργίλως ἔχοντας καὶ κολάζοντας φαίνεσθαι. οἶδα δὲ Τιμοκράτην, ὅτι τὸν νόμον εἰσενήνοχε τοῦτον οὐχ ἥκισθ’ ὑπὲρ αὑτοῦ· πολλὰ γὰρ ἡγεῖτο πολιτεύεσθαι παρ’ ὑμῖν ἄξια δεσμοῦ.", "st": "24.211"}, {"sp": "N", "t": "βούλομαι τοίνυν ὑμῖν κἀκεῖνο διηγήσασθαι, ὅ φασί ποτ’ εἰπεῖν Σόλωνα κατηγοροῦντα νόμον τινὸς οὐκ ἐπιτήδειον θέντος. λέγεται γὰρ τοῖς δικασταῖς αὐτὸν εἰπεῖν, ἐπειδὴ τἄλλα κατηγόρησεν, ὅτι νόμος ἐστὶν ἁπάσαις, ὡς ἔπος εἰπεῖν, ταῖς πόλεσιν, ἐάν τις τὸ νόμισμα διαφθείρῃ, θάνατον τὴν ζημίαν εἶναι. ἐπερωτήσας δ’ εἰ δίκαιος αὐτοῖς καὶ καλῶς ἔχων ὁ νόμος φαίνεται,", "st": "24.212"}, {"sp": "N", "t": "ἐπειδὴ φῆσαι τοὺς δικαστάς, εἰπεῖν ὅτι αὐτὸς ἡγεῖται ἀργύριον μὲν νόμισμ’ εἶναι τῶν ἰδίων συναλλαγμάτων εἵνεκα τοῖς ἰδιώταις εὑρημένον, τοὺς δὲ νόμους [ἡγοῖτο] νόμισμα τῆς πόλεως εἶναι. δεῖν δὴ τοὺς δικαστὰς πολλῷ μᾶλλον, εἴ τις ὃ τῆς πόλεώς ἐστι νόμισμα, τοῦτο διαφθείρει καὶ παράσημον εἰσφέρει, μισεῖν καὶ κολάζειν, ἢ εἴ τις ἐκεῖν’ ὃ τῶν ἰδιωτῶν ἐστιν.", "st": "24.213"}, {"sp": "N", "t": "προσθεῖναι δὲ τεκμήριον τοῦ καὶ μεῖζον εἶναι τἀδίκημα, τὸ τοὺς νόμους διαφθείρειν ἢ τὸ ἀργύριον, ὅτι ἀργυρίῳ μὲν πολλαὶ τῶν πόλεων καὶ φανερῶς πρὸς χαλκὸν καὶ μόλυβδον κεκραμένῳ χρώμεναι σῴζονται καὶ οὐδ’ ὁτιοῦν παρὰ τοῦτο πάσχουσιν, νόμοις δὲ πονηροῖς χρώμενοι καὶ διαφθείρεσθαι τοὺς ὄντας ἐῶντες οὐδένες πώποτ’ ἐσώθησαν. ταύτῃ μέντοι τῇ κατηγορίᾳ Τιμοκράτης ἔνοχος καθέστηκε νυνί, καὶ δικαίως ἂν ὑφ’ ὑμῶν τοῦ προσήκοντος τύχοι τιμήματος.", "st": "24.214"}, {"sp": "N", "t": "χρὴ μὲν οὖν πᾶσιν ὀργίλως ἔχειν, ὅσοι τιθέασι νόμους αἰσχροὺς καὶ πονηρούς, μάλιστα δὲ τούτοις οἳ τοὺς τοιούτους τῶν νόμων διαφθείρουσι δι’ ὧν ἔστιν ἢ μικρὰν ἢ μεγάλην εἶναι τὴν πόλιν. εἰσὶ δ’ οὗτοι τίνες; οἵ τε τοὺς ἀδικοῦντας τιμωρούμενοι καὶ ὅσοι τοῖς ἐπιεικέσι τιμάς τινας διδόασιν.", "st": "24.215"}, {"sp": "N", "t": "εἰ γὰρ ἅπαντες προθυμηθεῖεν ποιεῖν ἀγαθόν τι τὸ κοινόν, τὰς τιμὰς καὶ τὰς δωρειὰς τὰς ὑπὲρ τούτων ζηλώσαντες, καὶ πάντες ἀποσταῖεν τοῦ κακουργεῖν [ἢ κακόν τι πράττειν], τὰς βλάβας καὶ τὰς ζημίας τὰς ἐπὶ τούτοις κειμένας φοβηθέντες, ἔσθ’ ὅ τι κωλύει τὴν πόλιν μεγίστην εἶναι; οὐ τριήρεις ὅσας οὐδεμία πόλις Ἑλληνὶς κέκτηται; οὐχ ὁπλίτας; οὐχ ἱππέας; οὐ προσόδους; οὐ τόπους; οὐ λιμένας; ταῦτα δὲ πάντα τί σῴζει καὶ συνέχει; οἱ νόμοι· κατὰ γὰρ τούτους οὔσης τῆς πολιτείας ἐστὶ ταῦτα χρήσιμα τῷ κοινῷ.", "st": "24.216"}, {"sp": "N", "t": "εἰ δὲ τοὐναντίον γένοιτο τοῖς χρηστοῖς μὲν μηδ’ ὁτιοῦν πλέον, τοῖς δ’ ἀδικοῦσιν ἄδει’ ὅσην Τιμοκράτης γέγραφεν, πόση ταραχὴ γένοιτ’ ἂν εἰκότως; εὖ γὰρ ἴσθ’ ὅτι τούτων ὧν διεξῆλθον κτημάτων, οὐδ’ εἰ δὶς γένοιθ’ ὅσα νῦν ἐστιν, οὐδ’ ὁτιοῦν ἂν ὄφελος εἴη. οὗτος τοίνυν ἐν τούτῳ τῷ νόμῳ φαίνεται κακῶς ἐπιχειρῶν ὑμᾶς ποιεῖν δι’ οὗ τοῖς ἀδικεῖν ἐπιχειροῦσίν εἰσιν αἱ τιμωρίαι.", "st": "24.217"}, {"sp": "N", "t": "πάντων οὖν εἵνεκα τῶν εἰρημένων ἄξιον ὀργισθῆναι καὶ κολάσαι καὶ παράδειγμα ποιῆσαι τοῖς ἄλλοις· ὡς τὸ πράως ἔχειν τοῖς τοιούτοις, καὶ καταψηφίζεσθαι μέν, ὀλίγου δὲ τιμᾶν, ἐθίζειν καὶ προδιδάσκειν ἔστ’ ἀδικεῖν ὑμᾶς ὡς πλείστους.", "st": "24.218"}, {"sp": "HDR", "t": "Κατὰ Ἀριστογείτονος Αʹ", "st": "25"}, {"sp": "N", "t": "πάλαι καθήμενος, ὦ ἄνδρες δικασταί, καὶ κατηγοροῦντος ἀκούων, ὥσπερ ὑμεῖς, Λυκούργου, τὰ μὲν ἄλλα καλῶς αὐτὸν ἡγούμην λέγειν, ἓν δὲ τεθαύμακα ὁρῶν ὑπερδιατεινόμενον, εἰ ἀγνοεῖ τοῦθ’ ὅτι οὔτε παρὰ τοὺς ὑφ’ ἑαυτοῦ λόγους εἰρημένους οὔτε παρὰ τοὺς ὑπ’ ἐμοῦ μέλλοντας ῥηθήσεσθαι τὰ τουτουὶ τοῦ ἀγῶνός ἐστιν δίκαι’ ἰσχυρά, ἀλλ’ ὡς ἂν ἕκαστος ὑμῶν ἔχῃ πρὸς τὸ δυσχεραίνειν ἢ προσίεσθαι πονηρίαν.", "st": "25.1"}, {"sp": "N", "t": "καὶ ἔγωγ’ ὑπολαμβάνω τὴν μὲν κατηγορίαν καὶ τὸ τῶν λόγων πλῆθος ἔθους ἕνεκα καὶ τῆς ὑμετέρας ἀκροάσεως δεῖν ποιήσασθαι, κεκρίσθαι δὲ τοῦτο τὸ πρᾶγμα πάλαι ὑπὸ τῆς ἑκάστου φύσεως οἴκοθεν, καὶ νυνὶ εἰ μέν εἰσιν ὑμῶν οἱ πλείους οἷοι τοὺς πονηροὺς φιλεῖν καὶ σῴζειν, μάτην ἐρραψῳδηκότας ἡμᾶς ἔσεσθαι, εἰ δ’ οἷοι μισεῖν, δίκην, ἐὰν θεὸς θέλῃ, τοῦτον δώσειν.", "st": "25.2"}, {"sp": "N", "t": "πολλῶν δὲ λόγων εἰρημένων καὶ πάντων καλῶς, οὐκ ὀκνήσω πρὸς ὑμᾶς εἰπεῖν ἅ γ’ ἐμοὶ φαίνεται. ἐμοὶ γὰρ οὐδ’ ὁτιοῦν ἐοικέναι δοκεῖ τοῖς ἄλλοις ὁ παρὼν ἀγών. σκοπεῖτε δ’ οὑτωσί. πρὸς ἅπαντ’ ἔρχονται τὰ δικαστήρια οἱ μὲν δικασταὶ παρὰ τοῦ κατηγόρου καὶ τοῦ φεύγοντος τὸ πρᾶγμα μαθησόμενοι περὶ οὗ δεήσει τὴν ψῆφον ἐνεγκεῖν αὐτούς, οἱ δ’ ἀντίδικοι μεθ’ ἑαυτοῦ δείξων ἑκάτερος ὄντα τὰ τῶν νόμων δίκαια.", "st": "25.3"}, {"sp": "N", "t": "τὰ δὲ τούτου τοῦ ἀγῶνος πῶς ἔχει; οἱ μὲν δικάσοντες ὑμεῖς ἥκετε μᾶλλον ἡμῶν τῶν κατηγόρων εἰδότες καὶ ὀφείλοντα τῷ δημοσίῳ τοῦτον καὶ ἐγγεγραμμένον ἐν ἀκροπόλει καὶ οὐκ ἐξὸν αὐτῷ λέγειν· ὥσθ’ ἕκαστον ὑμῶν κατηγόρου τάξιν ἔχειν καὶ τὸ πρᾶγμ’ εἰδέναι, μὴ μαθεῖν δεῖσθαι.", "st": "25.4"}, {"sp": "N", "t": "ὁ δὲ κρινόμενος τῶν μὲν εἰς σωτηρίαν φερόντων ἀλλ’ οὐδ’ ὁτιοῦν πάρεστιν ἔχων, οὐ τοὺς ὑπὲρ αὐτοῦ τοῦ πράγματος λόγους δικαίους, οὐ τὸν ἑαυτοῦ βίον ἀνθρώπινον, οὐκ ἄλλ’ οὐδ’ ὁτιοῦν ἀγαθόν· δι’ ἃ δ’ ἂν καὶ μηδ’ ὁτιοῦν ἀδικῶν τις ἔδεισε, διὰ ταῦθ’ οὗτος οἴεται σωθήσεσθαι· ἐν γὰρ τῇ τῆς πονηρίας ὑπερβολῇ τὴν ἐλπίδα τῆς σωτηρίας ἔχει.", "st": "25.5"}, {"sp": "N", "t": "οὕτω δ’ ἐχόντων τούτων, δοκεῖ μοί τις οὐκ ἂν ἁμαρτεῖν εἰπὼν ὅτι νυνὶ κρίνεται μὲν Ἀριστογείτων, δοκιμάζεσθε δὲ καὶ κινδυνεύεθ’ ὑμεῖς περὶ δόξης. εἰ μὲν γὰρ ὀφθήσεσθ’ ἐπὶ τοῖς οὕτω φανεροῖς καὶ μεγάλοις ἀδικήμασιν ὀργιζόμενοι καὶ τιμωρούμενοι, δόξετε τοῦθ’, ὅπερ ἐστέ, δικασταὶ καὶ φύλακες τῶν νόμων εἰσεληλυθέναι·", "st": "25.6"}, {"sp": "N", "t": "εἰ δ’ ἕτερόν τι περιέσται τούτων, ὃ μηδεὶς μὲν ἂν αὐτὸς πεποιηκέναι φήσειεν, ἐν δὲ ταῖς ψήφοις εὑρεθήσεται, δέδοικα μὴ δόξητέ τισιν τὸν ἀεὶ βουλόμενον εἶναι πονηρὸν τῶν ἐν τῇ πόλει παιδοτριβεῖν. ἀσθενὴς μὲν γάρ ἐστιν ἅπας ὁ πονηρὸς καθ’ ἑαυτόν· ᾧ δ’ ἂν ὑμεῖς πρόσθησθε, οὗτος ἰσχυρὸς γίγνεται. ἔστι δὲ τοῦτο τῷ μὲν λαβόντι παρ’ ὑμῶν ἐργασία καὶ δυναστεία, ὑμῖν δὲ τοῖς δοῦσιν ὄνειδος.", "st": "25.7"}, {"sp": "N", "t": "βουλοίμην δ’ ἄν, ὦ ἄνδρες Ἀθηναῖοι, πρὸ τοῦ περὶ τῶν ἰδίων ἐμὲ τῶν τουτουὶ λέγειν, σπουδάσαντας ὑμᾶς ἐξετάσαι διὰ βραχέων εἰς ὅσην αἰσχύνην καὶ ἀδοξίαν προῆχε τὴν πόλιν δημοσίᾳ πάντα τὰ τοιαῦτα θηρία, ὧν μέσος καὶ τελευταῖος καὶ πρῶτός ἐστιν οὗτος.", "st": "25.8"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλ’ ἐάσω· ἀλλ’ εἰς τὰς ἐκκλησίας ἀναβαίνουσιν, ἐν αἷς ὑμεῖς γνώμης ἀπόδειξιν, οὐ πονηρίας τοῖς λέγουσι προτίθετε, τόλμαν καὶ κραυγὴν καὶ ψευδεῖς αἰτίας καὶ συκοφαντίαν καὶ ἀναισχυντίαν καὶ πάντα τὰ τοιαῦτα συνεσκευασμένοι, ὧν οὐκ ἂν εὕροι τις ἐναντιώτερα τῷ βουλεύεσθαι, νομίζω δ’ οὐδ’ ἂν αἰσχίω. καὶ τούτοις τοῖς αἰσχροῖς ἁπάντων τῶν τῆς πόλεως καλῶν περίεισι, τῶν νόμων, τῶν προέδρων, τοῦ προγράμματος, τῆς εὐκοσμίας.", "st": "25.9"}, {"sp": "N", "t": "εἰ μὲν οὖν ὑμεῖς ταῦτα βούλεσθε καὶ μετὰ τῆς ὑμετέρας γνώμης οὗτοι ταῦτα ποιοῦσιν, ὁδῷ βαδίζει καὶ ἐᾶν δεῖ· εἰ δ’ ἐπανορθώσασθαι ταῦτ’ ἔτι καὶ νῦν οἴεσθε χρῆναι, καὶ τὰ προειμένα πόρρω καὶ πολὺν ἤδη χρόνον αἰσχρῶς καὶ κακῶς ὑπὸ τούτων διακείμενα βελτίω ποιῆσαι, πάντα τὰ τοιαῦτ’ ἔθη παριδόντας ὑμᾶς τήμερον ὀρθῶς δεῖ δικάσαι,", "st": "25.10"}, {"sp": "N", "t": "τὴν τὰ δίκαι’ ἀγαπῶσαν Εὐνομίαν περὶ πλείστου ποιησαμένους, ἣ πάσας καὶ πόλεις καὶ χώρας σῴζει· καὶ τὴν ἀπαραίτητον καὶ σεμνὴν Δίκην, ἣν ὁ τὰς ἁγιωτάτας ἡμῖν τελετὰς καταδείξας Ὀρφεὺς παρὰ τὸν τοῦ Διὸς θρόνον φησὶ καθημένην πάντα τὰ τῶν ἀνθρώπων ἐφορᾶν, εἰς αὑτὸν ἕκαστον νομίσαντα βλέπειν οὕτω ψηφίζεσθαι, φυλαττόμενον καὶ προορώμενον μὴ καταισχῦναι ταύτην, ἧς ἐπώνυμός ἐστιν ὑμῶν ἕκαστος ὁ ἀεὶ δικάζειν λαχών, πάντα τὰ ἐν τῇ πόλει καλὰ καὶ δίκαια καὶ συμφέροντα [φυλάττων καὶ] ταύτην τὴν ἡμέραν παρακαταθήκην ἔνορκον εἰληφὼς παρὰ τῶν νόμων καὶ τῆς πολιτείας καὶ τῆς πατρίδος.", "st": "25.11"}, {"sp": "N", "t": "ὡς εἰ μὴ τοῦτον ἕξετε τὸν τρόπον, ἀλλ’ ἀπὸ τῆς συνήθους εὐηθείας εἰσεληλυθότες καθεδεῖσθε, φοβοῦμαι μὴ τὸ πρᾶγμ’ εἰς τοὐναντίον περιστῇ καὶ δοκοῦντες ἡμεῖς Ἀριστογείτονος κατηγορεῖν ὑμῶν κατηγοροῦντες φανῶμεν· ὅσῳ γὰρ ἂν μᾶλλον ἡμῶν δειξάντων τὴν τούτου πονηρίαν μηδὲν ὑμεῖς φροντίσητε, τοσούτῳ μείζων ἡ καθ’ ὑμῶν αἰσχύνη γενήσεται. καὶ περὶ μὲν τούτων ἱκανά.", "st": "25.12"}, {"sp": "N", "t": "πάνυ δ’, ὦ ἄνδρες Ἀθηναῖοι, μετὰ πάσης οἰκειότητος ἐρῶ τἀληθῆ πρὸς ὑμᾶς. ἐγὼ γὰρ ἐν ταῖς ἐκκλησίαις ὁρῶν ὑμᾶς κατατάττοντάς με καὶ προχειριζομένους ἐπὶ τὴν τούτου κατηγορίαν, ἠχθόμην καὶ μὰ τὸν Δία καὶ πάντας θεοὺς οὐκ ἐβουλόμην. οὐ γὰρ ἠγνόουν ὅτι ὁ ποιήσας τι τοιοῦτον παρ’ ὑμῖν καὶ παθὼν ἀπέρχεται. εἰ δὲ μὴ τηλικοῦτον ὥστ’ εὐθὺς αἰσθέσθαι, ἀλλ’ ἐὰν πολλὰ τοιαῦτα ποιῇ καὶ μὴ παύηται, ταχὺ γνώσεται. ὅμως δ’ ἀναγκαῖον ἡγούμην εἶναι πείθεσθαι τοῖς ὑμετέροις βουλήμασιν.", "st": "25.13"}, {"sp": "N", "t": "τὰ μὲν οὖν περὶ τῆς ἐνδείξεως καὶ τῶν νόμων δίκαια αὐτόν, ὅπερ πεποίηκεν, Λυκοῦργον ἐρεῖν ἡγούμην, καὶ τοὺς μάρτυρας τῆς πονηρίας τῆς τούτου τοῦτον ἑώρων προσκαλούμενον· ἃ δὲ καὶ λογίζεσθαι τοὺς ὑπὲρ πόλεως καὶ νόμων βουλευομένους προσήκει καὶ σκοπεῖσθαι δεῖ, ταῦτα προῃρούμην εἰπεῖν, καὶ νῦν ἐπὶ ταῦτα πορεύσομαι. δότε δ’, ὦ ἄνδρες Ἀθηναῖοι, δότε καὶ συγχωρήσατε μοι πρὸς Διός, ὡς πέφυκα καὶ προῄρημαι, περὶ τούτων διαλεχθῆναι πρὸς ὑμᾶς· καὶ γὰρ οὐδ’ ἂν ἄλλως δυναίμην.", "st": "25.14"}, {"sp": "N", "t": "ἅπας ὁ τῶν ἀνθρώπων βίος, ὦ ἄνδρες Ἀθηναῖοι, κἂν μεγάλην πόλιν οἰκῶσι κἂν μικράν, φύσει καὶ νόμοις διοικεῖται. τούτων δ’ ἡ μὲν φύσις ἐστὶν ἄτακτον καὶ κατ’ ἄνδρ’ ἴδιον τοῦ ἔχοντος, οἱ δὲ νόμοι κοινὸν καὶ τεταγμένον καὶ ταὐτὸ πᾶσιν. ἡ μὲν οὖν φύσις, ἂν ᾖ πονηρά, πολλάκις φαῦλα βούλεται· διόπερ τοὺς τοιούτους ἐξαμαρτάνοντας εὑρήσετε.", "st": "25.15"}, {"sp": "N", "t": "οἱ δὲ νόμοι τὸ δίκαιον καὶ τὸ καλὸν καὶ τὸ συμφέρον βούλονται, καὶ τοῦτο ζητοῦσιν, καὶ ἐπειδὰν εὑρεθῇ, κοινὸν τοῦτο πρόσταγμ’ ἀπεδείχθη, πᾶσιν ἴσον καὶ ὅμοιον, καὶ τοῦτ’ ἔστι νόμος. ᾧ πάντας πείθεσθαι προσήκει διὰ πολλά, καὶ μάλισθ’ ὅτι πᾶς ἐστι νόμος εὕρημα μὲν καὶ δῶρον θεῶν, δόγμα δ’ ἀνθρώπων φρονίμων, ἐπανόρθωμα δὲ τῶν ἑκουσίων καὶ ἀκουσίων ἁμαρτημάτων, πόλεως δὲ συνθήκη κοινή, καθ’ ἣν πᾶσι προσήκει ζῆν τοῖς ἐν τῇ πόλει.", "st": "25.16"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅτι νῦν Ἀριστογείτων τοῖς μὲν τῆς ἐνδείξεως δικαίοις ἅπασιν ἑάλωκεν, ἕτερος δ’ οὐδὲ εἷς ἔστιν ἀνεκτὸς αὐτῷ λόγος, περὶ τούτων ῥᾴδιον διδάξαι. δυοῖν γὰρ ὄντοιν, ὦ ἄνδρες Ἀθηναῖοι, ὧν ἕνεκα πάντες τίθενται οἱ νόμοι, τοῦ τε μηδένα μηδὲν ὃ μὴ δίκαιόν ἐστι ποιεῖν, καὶ τοῦ τοὺς παραβαίνοντας ταῦτα κολαζομένους βελτίους τοὺς ἄλλους ποιεῖν, ἀμφοτέροις τούτοις οὗτος ἔνοχος ὢν φανήσεται. ἐπὶ μὲν γὰρ οἷς ἐξ ἀρχῆς παρέβη τοὺς νόμους, τὰ ὀφλήματ’ αὐτῷ γέγονεν· ἐπὶ δ’ οἷς οὐκ ἐμμένει τούτοις, νῦν ἐπὶ τὴν παρ’ ὑμῶν ἄγεται τιμωρίαν, ὥστε μηδεμίαν καταλείπεσθαι πρόφασιν δι’ ἣν ἄν τις αὐτὸν ἀφείη.", "st": "25.17"}, {"sp": "N", "t": "οὐδὲ γὰρ αὖ τοῦτ’ ἔστιν εἰπεῖν, ὡς ἄρ’ ἐκ τούτων οὐδὲν ἡ πόλις βλάπτεται. ἐγὼ γάρ, ὅτι μὲν πάντ’ ἀπόλλυται τὰ τῆς πόλεως ὀφλήματα, εἰ τὰ τούτου σοφίσματα προσδέξεσθε, καὶ ὅτι, εἰ ἄρα δεῖ τινας ἐκ τῶν ὀφειλόντων ἀφιέναι, τοὺς ἐπιεικεστάτους καὶ βελτίστους καὶ τοὺς ἐπὶ τοῖς ἥκιστα δεινοῖς ὠφληκότας, τούτους ἀφιέναι δεῖ, οὐχὶ τὸν πονηρότατον καὶ πλεῖσθ’ ἡμαρτηκότα καὶ", "st": "25.18"}, {"sp": "N", "t": "δικαιότατ’ ὠφληκότα καὶ ἐπὶ δεινοτάτοις (τί γὰρ ἂν γένοιτο συκοφαντίας καὶ παρανομίας δεινότερον, ἐφ’ οἷς ἀμφοτέροις οὗτος ὤφληκεν;) καὶ ὅτι οὐδ’ εἰ πᾶσι τοῖς ἄλλοις [ἀφίετε], οὐχὶ τῷ βιαζομένῳ δήπου συγχωρῆσαι προσήκει (ὕβρις γὰρ δὴ τοῦτό γε), καὶ πάντα τὰ τοιαῦτ’ ἐάσω· ἀλλ’ ὅτι καὶ πᾶς ὁ τῆς πόλεως καὶ τῶν νόμων κόσμος, ὦ ἄνδρες Ἀθηναῖοι, συνταράττεται καὶ διαφθείρεται ⟨τὸ⟩ κατὰ τοῦτον, καὶ τοῦτ’ οἶμαι σαφῶς ὑμῖν ἐπιδείξειν.", "st": "25.19"}, {"sp": "N", "t": "λέξω δ’ οὔτε καινὸν οὔτε περιττὸν οὐδὲν οὔτ’ ἴδιον, ἀλλ’ ὃ πάντες ὑμεῖς ἴσθ’ ὁμοίως ἐμοί. εἰ γάρ τις ὑμῶν ἐξετάσαι βούλεται τί ποτ’ ἐστὶ τὸ αἴτιον καὶ τὸ ποιοῦν τὴν βουλὴν συλλέγεσθαι, τὸν δῆμον εἰς τὴν ἐκκλησίαν ἀναβαίνειν, τὰ δικαστήρια πληροῦσθαι, τὰς ἕνας ἀρχὰς ταῖς νέαις ἑκούσας ὑπεξιέναι, καὶ πάντα δι’ ὧν ἡ πόλις οἰκεῖται καὶ σῴζεται γίγνεσθαι, τοὺς νόμους εὑρήσει [τούτων αἰτίους] καὶ τὸ τούτοις ἅπαντας πείθεσθαι, ἐπεὶ λυθέντων γε τούτων, καὶ ἑκάστῳ δοθείσης ἐξουσίας ὅ τι βούλεται ποιεῖν, οὐ μόνον ἡ πολιτεία οἴχεται, ἀλλ’ οὐδ’ ὁ βίος ἡμῶν τοῦ τῶν θηρίων οὐδὲν ἂν διενέγκαι.", "st": "25.20"}, {"sp": "N", "t": "τί γὰρ ἂν τοῦτον αὐτὸν οἴεσθε ποιεῖν λυθέντων τῶν νόμων, ὃς ὄντων κυρίων τοιοῦτός ἐστιν; ἐπειδὴ τοίνυν οἱ νόμοι μετὰ τοὺς θεοὺς ὁμολογοῦνται σῴζειν τὴν πόλιν, δεῖ πάντας ὑμᾶς τὸν αὐτὸν τρόπον ὥσπερ ἂν εἰ καθῆσθ’ ἐράνου πληρωταί, τὸν μὲν πειθόμενον τούτοις ὡς φέροντα τὴν τῆς σωτηρίας φορὰν πλήρη τῇ πατρίδι τιμᾶν καὶ ἐπαινεῖν, τὸν δ’ ἀπειθοῦντα κολάζειν.", "st": "25.21"}, {"sp": "N", "t": "ἔρανος γάρ ἐστιν πολιτικὸς καὶ κοινὸς πάνθ’ ὅσα, ταξάντων τῶν νόμων, ἕκαστος ἡμῶν ποιεῖ. ὃν ὁ λείπων, ὦ ἄνδρες Ἀθηναῖοι, πολλὰ καὶ καλὰ καὶ σεμνὰ καὶ μεγάλ’ ὑμῶν ἀφαιρεῖται καὶ διαφθείρει τὸ καθ’ αὑτόν.", "st": "25.22"}, {"sp": "N", "t": "ὧν ἓν ἢ δύ’ ἐρῶ παραδείγματος ἕνεκα, τὰ γνωριμώτατα. τὸ τὴν βουλὴν τοὺς πεντακοσίους ἀπὸ τῆς [ἀσθενοῦς] τοιαυτησὶ κιγκλίδος τῶν ἀπορρήτων κυρίαν εἶναι, καὶ μὴ τοὺς ἰδιώτας ἐπεισιέναι· τὸ τὴν ἐξ Ἀρείου πάγου βουλήν, ὅταν ἐν τῇ βασιλείῳ στοᾷ καθεζομένη περισχοινίσηται, κατὰ πολλὴν ἡσυχίαν ἐφ’ ἑαυτῆς εἶναι, καὶ ἅπαντας ἐκποδὼν ἀποχωρεῖν· τὸ τὰς ἀρχὰς ἁπάσας, ὅσας οἱ λαχόντες ἄρχουσιν ὑμῶν, ἅμα τῷ τὸν ὑπηρέτην εἰπεῖν “μετάστητ’ ἔξω” τῶν νόμων κρατεῖν ἐφ’ οἷς εἰσεπέμφθησαν, καὶ μηδὲ τοὺς ἀσελγεστάτους βιάζεσθαι· ἄλλα μυρία.", "st": "25.23"}, {"sp": "N", "t": "πάντα γὰρ τὰ σεμνὰ καὶ καλὰ καὶ δι’ ὧν ἡ πόλις κοσμεῖται καὶ σῴζεται, ἡ σωφροσύνη, ἡ πρὸς τοὺς γονέας καὶ τοὺς πρεσβυτέρους ὑμῶν παρὰ τῶν νέων αἰσχύνη, ἡ εὐταξία, τῇ τῶν νόμων προσθήκῃ τῶν αἰσχρῶν περίεστιν, τῆς ἀναισχυντίας, τῆς θρασύτητος, τῆς ἀναιδείας. ἰταμὸν γὰρ ἡ πονηρία καὶ τολμηρὸν καὶ πλεονεκτικόν, καὶ τοὐναντίον ἡ καλοκαγαθία ἡσύχιον καὶ ὀκνηρὸν καὶ βραδὺ καὶ δεινὸν ἐλαττωθῆναι. τοὺς νόμους οὖν δεῖ τηρεῖν καὶ τούτους ἰσχυροὺς ποιεῖν τοὺς ἀεὶ δικάζοντας ὑμῶν· μετὰ γὰρ τούτων οἱ χρηστοὶ τῶν πονηρῶν περίεισιν.", "st": "25.24"}, {"sp": "N", "t": "εἰ δὲ μή, λέλυται πάντα, ἀνέῳκται, συγκέχυται, τῶν πονηροτάτων καὶ ἀναιδεστάτων ἡ πόλις γίγνεται. φέρε γὰρ πρὸς θεῶν, εἰ ἕκαστος τῶν ἐν τῇ πόλει τὴν Ἀριστογείτονος τόλμαν καὶ ἀναισχυντίαν λαβών, καὶ διαλογισάμενος ταῦθ’ ἅπερ οὗτος, ὅτι ἔξεστι καὶ λέγειν καὶ ποιεῖν μέχρι παντὸς ὅ τι ἂν βούληταί τις ἐν δημοκρατίᾳ, ἄνπερ τοῦ ποῖός τις εἶναι δόξει [ὁ] ταῦτα ποιῶν ὀλιγωρήσῃ, καὶ οὐδεὶς ἐπ’ οὐδενὶ τῶν ἀδικημάτων εὐθὺς αὐτὸν ἀποκτενεῖ·", "st": "25.25"}, {"sp": "N", "t": "εἰ ταῦτα διανοηθεὶς ὁ μὴ λαχὼν τῷ λαχόντι καὶ ὁ μὴ χειροτονηθεὶς τῷ χειροτονηθέντι ἐξ ἴσου ζητοίη εἶναι καὶ τῶν αὐτῶν μετέχειν, καὶ ὅλως μὴ νέος, μὴ πρεσβύτερος τὰ προσήκοντα πράττοι, ἀλλὰ πᾶν τὸ τεταγμένον ἐξελάσας ἕκαστος ἐκ τοῦ βίου, τὴν ἑαυτοῦ βούλησιν νόμον, ἀρχήν, πάνθ’ ὑπολαμβάνοι· εἰ ταῦτα ποιοῖμεν, ἔστι τὴν πόλιν οἰκεῖσθαι; τί δέ; τοὺς νόμους κυρίους εἶναι; πόσην δ’ ἂν οἴεσθε βίαν καὶ ὕβριν καὶ παρανομίαν ἐν ἁπάσῃ τῇ πόλει καθ’ ἑκάστην τὴν ἡμέραν γίγνεσθαι καὶ βλασφημίαν ἀντὶ τῆς νῦν εὐφημίας καὶ τάξεως;", "st": "25.26"}, {"sp": "N", "t": "καὶ τί δεῖ λέγειν ὅτι τοῖς νόμοις ἅπαντα κοσμεῖται καὶ τῷ τούτοις πείθεσθαι; ἀλλ’ ὑμεῖς αὐτοὶ πάντων ἄρτι κληρουμένων Ἀθηναίων, καὶ πάντων εὖ οἶδ’ ὅτι βουλομένων εἰς τοῦτο λαχεῖν τὸ δικαστήριον, μόνοι δικάζεθ’ ἡμῖν. διὰ τί; ὅτι ἐλάχετε, εἶτ’ ἀπεκληρώθητε· ταῦτα δ’ οἱ νόμοι λέγουσιν. εἶθ’ ὑμεῖς αὐτοὶ κατὰ τοὺς νόμους εἰσεληλυθότες τὸν παρὰ τοὺς νόμους λέγειν ἢ πράττειν τι βιαζόμενον λαβόντες ἀφήσετε; καὶ οὐδεὶς ὑμῶν χολὴν οὐδ’ ὀργὴν ἔχων φανήσεται ἐφ’ οἷς ὁ βδελυρὸς καὶ ἀναιδὴς ἄνθρωπος βιάζεται τοὺς νόμους;", "st": "25.27"}, {"sp": "N", "t": "ὅς, ὦ μιαρώτατε πάντων τῶν ὄντων ἀνθρώπων, κεκλειμένης σου τῆς παρρησίας οὐ κιγκλίσιν οὐδὲ θύραις, ἃ καὶ παρανοίξειεν ἄν τις, ἀλλὰ τοσούτοις καὶ τηλικούτοις ὀφλήμασιν, καὶ τούτων παρὰ τῇ θεῷ κειμένων, εἰς τὸ ἐντὸς τούτων βιάζει καὶ προσέρχει πρὸς ταῦτ’ ἀφ’ ὧν ἀπελαύνουσίν σ’ οἱ νόμοι· ἀπεσχοινισμένος πᾶσι τοῖς ἐν τῇ πόλει δικαίοις, γνώσει δικαστηρίων τριῶν, ἐγγραφῇ θεσμοθετῶν, ἑτέρᾳ πρακτόρων, τῇ τῆς βουλεύσεως, ἣν αὐτὸς διώκεις, γραφῇ, μόνον οὐχ ἁλύσει σιδηρᾷ, ὑποδύει παρὰ ταῦτα καὶ διασπᾷς, καὶ προφάσεις πλάττων καὶ ψευδεῖς αἰτίας συντιθεὶς τὰ κοινὰ δίκαι’ ἀνατρέψειν οἴει.", "st": "25.28"}, {"sp": "N", "t": "καὶ μὴν μέγα καὶ σαφὲς ὑμῖν ἐρῶ παράδειγμα, ὅτι ταῦτ’ οὐδὲ καθ’ ἓν προσήκει παριδεῖν. εἰ γάρ τις αὐτίκα δὴ μάλ’ εἴποι ὡς ἐκ τῶν νεωτάτων ἢ τῶν πλουσιωτάτων ἢ τῶν λελῃτουργηκότων ἢ τῶν τοιούτων τι μερῶν ἀφορίσας, τοὺς λέγοντας εἶναι δεῖ, ἀποκτείναιτ’ ἂν αὐτὸν εὖ οἶδ’ ὅτι, ὡς καταλύοντα τὸν δῆμον, καὶ δικαίως ἂν τοῦτο ποιήσαιτε.", "st": "25.29"}, {"sp": "N", "t": "καὶ μὴν ὅ τι βούλεσθε τούτων ἧττόν ἐστι δεινὸν ἢ εἴ τις ἐξ ὧν οὗτός ἐστι μερῶν εἴποι τοῖς βιαζομένοις ἐξεῖναι λέγειν, ἢ τοῖς ἐκ τοῦ δεσμωτηρίου, ἢ τοῖς ὧν ἀπέκτεινεν ὁ δῆμος τοὺς πατέρας, ἢ τοῖς ἀποδεδοκιμασμένοις ἄρχειν λαχοῦσιν, ἢ τοῖς ὀφείλουσι τῷ δημοσίῳ, ἢ τοῖς καθάπαξ ἀτίμοις, ἢ τοῖς πονηροτάτοις καὶ δοκοῦσι καὶ οὖσι· πάντα γὰρ ταῦθ’ ὑπάρχει τούτῳ, καὶ πρόσεστι τοῖς οἷος οὗτός ἐστι τὴν φύσιν. ἐγὼ γάρ, ὦ ἄνδρες Ἀθηναῖοι, νομίζω μὲν αὐτὸν καὶ ἐφ’ οἷς νυνὶ ποιεῖ δικαίως ἂν ἀποθανεῖν, πολὺ μέντοι μᾶλλον, ἢ οὐδέν γ’ ἧττον, ἐφ’ οἷς δῆλός ἐστι ποιήσων, εἰ τὴν παρ’ ὑμῶν ἐξουσίαν λήψεται καὶ καιρόν· ὃ μὴ γένοιτο.", "st": "25.30"}, {"sp": "N", "t": "ὃ καὶ θαυμαστόν ἐστιν, εἴ τις ὑμῶν ἀγνοεῖ ὅτι ἐπὶ μὲν καλὸν ἢ χρηστὸν ἢ τῆς πόλεως ἄξιον πρᾶγμ’ οὐδὲν οὗτός ἐστι χρήσιμος (μὴ γάρ, ὦ Ζεῦ καὶ θεοί, τοσαύτη σπάνις ἀνδρῶν γένοιτο τῇ πόλει ὥστε παρ’ Ἀριστογείτονος τῶν καλῶν τι ποιήσασθαι)· ἐφ’ ἃ δ’ ἂν καὶ χρήσαιτό τις τοιούτῳ θηρίῳ, ἀπεύχεσθαι τοῖς θεοῖς μὴ γενέσθαι δεῖ. εἰ δ’ ἄρα συμβαίη, μεῖζόν ἐστιν εὐτύχημα τῇ πόλει ἀπορῆσαι τοὺς βουλομένους ἐξαμαρτεῖν δι’ οὗ τοῦτο ποιήσουσιν, ἢ τοῦτον ἀφειμένον αὐτοῖς ἕτοιμον ὑπάρξαι.", "st": "25.31"}, {"sp": "N", "t": "τί γὰρ οὗτος ὀκνήσειεν ἄν, ὦ ἄνδρες Ἀθηναῖοι, τῶν ἀνηκέστων ἢ δεινῶν, ἄνθρωπος μιαρὸς καὶ πατρικῆς ἔχθρας πρὸς τὸν δῆμον ἀνάμεστος; τίς δ’ ἂν ἄλλος μᾶλλον, ὃ μὴ γένοιτο, ἀνατρέψειεν τὴν πόλιν, εἰ λάβοιτ’ ἐξουσίας; οὐχ ὁρᾶθ’ ὅτι τῆς φύσεως αὐτοῦ καὶ πολιτείας οὐ λογισμὸς οὐδ’ αἰδὼς οὐδεμία, ἀλλ’ ἀπόνοι’ ἡγεῖται, μᾶλλον δ’ ὅλον ἔστ’ ἀπόνοι’ ἡ τούτου πολιτεία; ἣ μέγιστον μέν ἐστιν αὐτῷ τῷ ἔχοντι κακόν, δεινὸν δὲ καὶ χαλεπὸν πᾶσι, πόλει δ’ οὐκ ἀνεκτόν. ὁ γὰρ ἀπονενοημένος ἅπας ἑαυτὸν μὲν προεῖται καὶ τὴν ἐκ λογισμοῦ σωτηρίαν, ἐκ δὲ τοῦ παραδόξου καὶ παραλόγου, ἐὰν ἄρα σωθῇ, σῴζεται.", "st": "25.32"}, {"sp": "N", "t": "τίς ἂν οὖν εὖ φρονῶν αὑτὸν ἂν ἢ τὰ τῇ πατρίδι συμφέροντα ταύτῃ συνάψειεν; τίς οὐκ ἂν εἰς ὅσον δυνατὸν φεύγοι, καὶ τὸν ἔχοντα ταύτην ἐκποδὼν ποιήσαιτο, ἵνα μηδ’ ἄκων αὐτῇ ποτε περιπέσῃ; οὐκ ἀπονοίας, ὦ ἄνδρες Ἀθηναῖοι, τοὺς ὑπὲρ πατρίδος βουλευομένους δεῖ ζητεῖν ὅτῳ κοινωνήσουσιν, ἀλλὰ νοῦ καὶ φρενῶν ἀγαθῶν καὶ προνοίας πολλῆς. ταῦτα μὲν γὰρ εἰς εὐδαιμονίαν ἄγει πάντας ἀνθρώπους, ἐκείνη δ’ οἷ τοῦτον ἀπελθεῖν δεῖ.", "st": "25.33"}, {"sp": "N", "t": "θεωρεῖτε δὲ μὴ πρὸς τὸν ἐμὸν λόγον, ἀλλ’ εἰς ἅπαντα τὰ τῶν ἀνθρώπων ἔθη βλέποντες. εἰσὶ ταῖς πόλεσι πάσαις βωμοὶ καὶ νεῲ πάντων τῶν θεῶν, ἐν δὲ τούτοις καὶ Προνοίας Ἀθηνᾶς ὡς ἀγαθῆς καὶ μεγάλης θεοῦ, καὶ παρὰ τῷ Ἀπόλλωνι ἐν Δελφοῖς κάλλιστος καὶ μέγιστος νεὼς εὐθὺς εἰσιόντι εἰς τὸ ἱερόν, ὃς ὢν θεὸς καὶ μάντις οἶδε τὸ βέλτιστον· ἀλλ’ οὐκ ἀπονοίας οὐδ’ ἀναιδείας.", "st": "25.34"}, {"sp": "N", "t": "καὶ δίκης γε καὶ εὐνομίας καὶ αἰδοῦς εἰσι πᾶσιν ἀνθρώποις βωμοί, οἱ μὲν κάλλιστοι καὶ ἁγιώτατοι ἐν αὐτῇ τῇ ψυχῇ ἑκάστου καὶ τῇ φύσει, οἱ δὲ καὶ κοινῇ τοῖς πᾶσι τιμᾶν ἱδρυμένοι· ἀλλ’ οὐκ ἀναισχυντίας οὐδὲ συκοφαντίας οὐδ’ ἐπιορκίας οὐδ’ ἀχαριστίας, ἃ πάντα τούτῳ πρόσεστιν.", "st": "25.35"}, {"sp": "N", "t": "οἶδα τοίνυν ὅτι τὴν μὲν ὀρθὴν καὶ δικαίαν ὁδὸν τῆς ἀπολογίας οὗτος φεύξεται, ἔξωθεν δὲ κύκλῳ περίεισιν λοιδορούμενος καὶ διαβάλλων καὶ ὑπισχνούμενος κρινεῖν, εἰσάξειν, παραδώσειν. ἔστιν δὲ πάντ’ αὐτῷ ταῦτα, ἐάνπερ ὑμεῖς ὀρθῶς σκοπῆτε, ἀδόκιμα. τί γὰρ οὐκ ἐξελήλεγκται τούτων ἐπὶ πάντων πολλάκις;", "st": "25.36"}, {"sp": "N", "t": "καὶ τὰ μὲν ἄλλ’ ἐάσω· ἀλλ’, Ἀριστογεῖτον, ἑπτὰ γραφὰς κέκρικάς με, τοῖς ὑπὲρ Φιλίππου τότε πράττουσιν σεαυτὸν μισθώσας, καὶ εὐθύνας διδόντος δὶς κατηγόρησας· καὶ Ἀδράστειαν μὲν ἄνθρωπος ὢν προσκυνῶ, καὶ ἔχω τοῖς θεοῖς καὶ πᾶσιν ὑμῖν, ὦ ἄνδρες Ἀθηναῖοι, τοῖς σώσασί με πολλὴν χάριν· οὐδεπώποτε δ’ οὐδὲν ἀληθὲς λέγων ἐφάνης, ἀλλ’ ἀεὶ συκοφαντῶν ἠλέγχου. ἐὰν οὖν ἀκύρους τοὺς νόμους οὗτοι ποιήσαντες ἀφῶσί σε τήμερον, νῦν μ’ ἐξελέγξεις; περὶ τοῦ;", "st": "25.37"}, {"sp": "N", "t": "σκοπεῖτε γὰρ οὑτωσί. δύ’ ἔτη βιάζεται λέγειν οὗτος οὐκ ἐξὸν αὐτῷ, ἀλλὰ λέγει γ’ ὅμως. ἔπειτ’ ἐν τούτοις τὸν μὲν ταλαίπωρον Φωκίδην καὶ τὸν χαλκοτύπον τὸν ἐκ Πειραιῶς καὶ τὸν σκυλόδεψον, καὶ ὅσων ἄλλων κατηγόρηκε παρ’ ὑμῖν, εἶδ’ ἀδικοῦντας τὴν πόλιν, ἐμὲ δ’ οὐχ ἑώρα τὸν ῥήτορ’ ᾧ ἐπολέμει, οὐδὲ τὸν Λυκοῦργον, οὐδὲ τοὺς ἄλλους, περὶ ὧν αὐτίκα δὴ τὰ πόλλ’ ἐρεῖ; καὶ μὴν κατ’ ἀμφότερ’ ἄξιός ἐστ’ ἀπολωλέναι, τοῦτο μέν, εἴ τι καθ’ ἡμῶν ἔχων ἀδίκημα δεικνύναι ἡμᾶς μὲν ἀφίει, ἐπὶ δὲ τοὺς ἰδιώτας ἐπορεύετο, τοῦτο δέ, εἰ μηδὲν ἔχων ἕνεκα τοῦ παρακρούσασθαι καὶ φενακίσαι ὑμᾶς ταῦτ’ ἐρεῖ.", "st": "25.38"}, {"sp": "N", "t": "εἰ τοίνυν ἄρα καὶ τοιοῦτός τίς ἐστιν ἄνθρωπος ἐν τῇ πόλει, οἷος ἐκ παντὸς τρόπου τὸν κρινοῦντά τινα [καὶ συκοφαντήσοντα] ζητεῖν, εἰ δὲ δικαίως ἢ ἀδίκως μηδὲν φροντίζειν, οὐδέν’ ἂν ἧττον εὕροι χρήσιμον ὄντ’ ἢ τοῦτον ἑαυτῷ. διὰ τί; ὅτι τὸν κατηγορήσοντα τῶν ἄλλων καὶ πάντας κρινοῦντα αὐτὸν ἀνεξέλεγκτον ὑπάρχειν δεῖ, ἵνα μὴ διὰ τὴν τούτου πονηρίαν ἀποφεύγωσιν ἐκεῖνοι. τούτου δ’ οὔτε πλειόνων οὔτε μειζόνων ἁμαρτημάτων οὐδεὶς μᾶλλόν ἐστι μεστὸς ἐν τῇ πόλει.", "st": "25.39"}, {"sp": "N", "t": "τί οὖν οὗτός ἐστι; κύων νὴ Δία, φασί τινες, τοῦ δήμου. ποδαπός; οἷος οὓς μὲν αἰτιᾶται λύκους εἶναι μὴ δάκνειν, ἃ δέ φησι φυλάττειν πρόβατ’ αὐτὸς κατεσθίειν. τίνα γὰρ τῶν ῥητόρων οὗτος εἴργασταί τι κακὸν τοσοῦτον ἡλίκον τοὺς ἰδιώτας, περὶ ὧν ψηφίσματα γράψας ἑάλω; τίνα δ’, ἐξ οὗ νῦν πάλιν λέγει, κέκρικεν ῥήτορα; οὐδ’ ἕνα· ἀλλ’ ἰδιώτας πολλούς. ἀλλὰ μὴν τοὺς γευομένους κύνας τῶν προβάτων κατακόπτειν φασὶ δεῖν, ὥστ’ οὐκ ἂν φθάνοι κατακοπτόμενος.", "st": "25.40"}, {"sp": "N", "t": "οὐδέν, ὦ ἄνδρες Ἀθηναῖοι, χρήσιμός ἐστιν ὧν φησίν, ἀλλ’ οὗτος πρᾶγμ’ ἑόρακεν μιαρὸν καὶ ἀναιδές. λοιδορούμενος γὰρ ἐν ταῖς ἐκκλησίαις καὶ προπετῶς ἅπασι προσκρούων, ὧν ἂν ἐκ τούτων ἁθρόους πάντας ὑμᾶς ἐκεῖ παρακρούσηται, τούτων καταβὰς καθ’ ἕν’ ὑμῶν παρ’ ἑκάστου δίκην λαμβάνει, συκοφαντῶν, αἰτῶν, εἰσπράττων ἀργύριον, οὐχὶ μὰ Δία τοὺς λέγοντας (οὗτοι μὲν γὰρ ἐπίστανται τούτῳ διαβαπτίζεσθαι), ἀλλὰ τοὺς ἰδιώτας καὶ τοὺς ἀπείρους· ἴσασι δ’ οἱ πεπληγμένοι.", "st": "25.41"}, {"sp": "N", "t": "ἀλλὰ νὴ Δία ταῦτα μὲν οὕτως ἔχειν ὁμολογήσετε, χρήσιμον δ’ ἄνθρωπον τῇ πόλει κρίνειν, ὥστε πάντα ταῦτα παριδόντας δεῖν αὐτὸν σῴζειν. ἀλλ’ ὧν ἔργῳ πεῖραν εἰλήφατ’, ὦ ἄνδρες Ἀθηναῖοι, μηδέποτ’ ἐκ λόγου ταῦτα σκοπεῖσθε. οὗτος ὑμῖν οὐχὶ προσῆλθε πέντ’ ἐτῶν, ὧν ἐτιμήθη μὴ λέγειν αὐτῷ. τίς οὖν ἐν τούτῳ τῷ χρόνῳ τοῦτον ἐπόθησεν; τί τῶν τῆς πόλεως ἐλλειφθὲν διὰ τὴν ἀπουσίαν εἶδε τὴν τούτου; τί δέ, ἀφ’ οὗ νῦν λέγει, βέλτιον γεγονός; ἐμοὶ μὲν γὰρ δοκεῖ τοὐναντίον, ὃν μὲν οὐ προσῄει χρόνον ὑμῖν, ἀναπαύσασθαι τῶν κακῶν ἡ πόλις ὧν ἅπασιν οὗτος παρεῖχεν, ἀφ’ οὗ δὲ πάλιν δημηγορεῖ, πολιορκεῖσθαι, λόγους στασιώδεις καὶ ταραχώδεις ἐν ἁπάσαις ἀεὶ ταῖς ἐκκλησίαις λέγοντος τούτου.", "st": "25.42"}, {"sp": "N", "t": "βούλομαι τοίνυν καὶ παρακινδυνευτικοῦ τινος ἅψασθαι λόγου καὶ διαλεχθῆναι τοῖς διὰ ταῦτα φιλοῦσιν αὐτόν· οὓς ὁποίους μέν τινας χρὴ νομίζειν, αὐτοὶ σκοπεῖσθε, ἐγὼ δ’ οὐδὲν ἂν εἴποιμι, πλὴν ὅτι γ’ οὐ σωφρονοῦσι προσνέμοντες αὑτοὺς τούτῳ. τῶν μὲν οὖν ἐν τῷ δικαστηρίῳ νῦν ὄντων ὑμῶν οὐδέν’ εἶναι τοιοῦτον τίθεμαι· καὶ γὰρ δίκαιον, ὦ ἄνδρες Ἀθηναῖοι, καὶ καλὸν καὶ συμφέρον οὕτω καὶ λέγειν ἐμὲ καὶ φρονεῖν περὶ ὑμῶν.", "st": "25.43"}, {"sp": "N", "t": "ἐκ δὲ τῶν ἄλλων πολιτῶν, ἵν’ ὡς εἰς ἐλαχίστους τὴν βλασφημίαν ἀγάγω, τὸν μαθητήν, εἰ δὲ βούλεσθε, τὸν διδάσκαλον αὐτοῦ, Φιλοκράτην τὸν Ἐλευσίνιον, μόνον εἶναι τοιοῦτον τίθεμαι, οὐχ ὡς οὐχὶ πλειόνων ὄντων (ὤφελε γὰρ μηδεὶς ἄλλος Ἀριστογείτονι χαίρειν), ἀλλ’ ὃ καθ’ ὑμῶν ὡς ὄνειδος ὀκνῶ λέγειν, οὐδὲ τῶν ἄλλων πολιτῶν δίκαιός εἰμι δημοσίᾳ κατηγορεῖν· εἶτα καὶ ταὐτὸ ποιήσει καὶ πρὸς ἕνα ῥηθεὶς ὁ λόγος.", "st": "25.44"}, {"sp": "N", "t": "τὸ μὲν οὖν ἐξετάζειν ἀκριβῶς οἷον ἀνάγκη τὴν φύσιν εἶναι τὸν Ἀριστογείτονι χαίροντα, ἐάσω, ἵνα μὴ πολλὰ καὶ βλάσφημ’ ἀναγκάζωμαι λέγειν καὶ διεξιέναι· ἀλλ’ ἐκεῖνο λέγω. εἰ πονηρός ἐστιν Ἀριστογείτων ἁπλῶς καὶ πικρὸς καὶ συκοφάντης καὶ τοιοῦτος οἷος ὑπισχνεῖται, δίδωμι, συγχωρῶ, Φιλόκρατες, σοὶ τῷ τοιούτῳ τὸν ὅμοιον σῴζειν· τῶν γὰρ ἄλλων ἁπάντων καὶ φρονούντων ἃ δεῖ καὶ φυλαττόντων τοὺς νόμους, οὐδὲν ἂν παρὰ τοῦτ’ οἶμαι γενέσθαι.", "st": "25.45"}, {"sp": "N", "t": "εἰ δὲ κάπηλός ἐστι πονηρίας καὶ παλιγκάπηλος καὶ μεταβολεύς, καὶ μόνον οὐ ζυγὰ καὶ στάθμ’ ἔχων πάνθ’ ὅσα πώποτ’ ἔπραξεν ἐπώλει, τί τοῦτον, ὦ μάται’, ἀκονᾷς; οὔτε γὰρ μαγείρῳ μαχαίρας οὐδέν ἐστ’ ὄφελος δήπουθεν ἥτις μὴ τέμνει, οὔτε τῷ βουλομένῳ δι’ αὑτοῦ πᾶσι πράγματα καὶ κακὰ γίγνεσθαι ὁ ταῦτ’ ἀποδωσόμενος συκοφάντης οὐδέν ἐστι χρήσιμος.", "st": "25.46"}, {"sp": "N", "t": "ἀλλὰ μὴν ὅτι τοιοῦτος οὗτός ἐστιν εἰδότι σοι φράσω. τὴν καθ’ Ἡγήμονος εἰσαγγελίαν μέμνησαι ὡς ἀπέδοτο· τὰς κατὰ Δημάδου γραφὰς οἶσθ’ ὡς ἐξέλιπεν. τὸν ἐλαιοπώλην Ἀγάθωνα (ταυτὶ γὰρ τὰ πρώην) βοῶν καὶ κεκραγὼς καὶ ἰοὺ ἰού, πάντ’ ἄνω τε καὶ κάτω ποιῶν ἐν ταῖς ἐκκλησίαις ὡς δέον στρεβλοῦν, λαβὼν ὁτιδήποτε, παρὼν ὅτ’ ἀφίετο, ἄφωνος ἐγένετο. τὴν κατὰ Δημοκλέους εἰσαγγελίαν ἀνασείσας ποῖ ἔτρεψεν; ἄλλα μυρία, ὧν ἐμοὶ μὲν ἔργον ἁπάντων μνησθῆναι, σὺ δ’ εὖ οἶδ’ ὅτι καὶ τὰ ἀντίγραφ’ αὐτῶν ἔχεις, ἐργολαβῶν αὐτῷ.", "st": "25.47"}, {"sp": "N", "t": "τίς οὖν ὁ τὸν τοιοῦτον σώσων ἢ πονηρὸς ἢ χρηστός; ἢ διὰ τί; τῶν μὲν γὰρ ὁμοίων προδότης, τῶν δὲ χρηστῶν ἐχθρὸς ἐκ φύσεως καὶ γένους· πλὴν εἰ συκοφάντου τις καὶ πονηροῦ σπέρμα καὶ ῥίζαν, ὡσπερανεὶ γεωργός, οἴεται δεῖν ὑπάρχειν τῇ πόλει. τοῦτο δ’ οὐ καλόν, ὦ ἄνδρες Ἀθηναῖοι, νομίζω δὲ μὰ τοὺς θεοὺς οὐδ’ ὅσιον· οὐδὲ γὰρ τοὺς προγόνους ὑπολαμβάνω τὰ δικαστήρια ταῦθ’ ὑμῖν οἰκοδομῆσαι, ἵνα τοὺς τοιούτους ἐν αὐτοῖς μοσχεύητε, ἀλλὰ τοὐναντίον ἵν’ ἀνείργητε καὶ κολάζητε καὶ μηδεὶς ζηλοῖ μηδ’ ἐπιθυμῇ κακίας.", "st": "25.48"}, {"sp": "N", "t": "δυσκατάπαυστον δέ τι κινδυνεύει πρᾶγμ’ εἶναι πονηρία. ὅπου γὰρ Ἀριστογείτων ἐπὶ τοῖς ὡμολογημένοις ἀδικήμασι κρίνεται καὶ οὐκ ἀπόλωλε πάλαι, τί χρὴ ποιεῖν ἢ λέγειν; ὃς εἰς τοῦθ’ ἥκει πονηρίας ὥστ’ ἐνδεδειγμένος ἤδη βοῶν, συκοφαντῶν, ἀπειλῶν οὐκ ἐπαύετο, οἷς μὲν ὑμεῖς τὰ μέγιστ’ ἐνεχειρίζετε στρατηγοῖς, ὅτι αὐτῷ ἀργύριον αἰτοῦντι οὐκ ἔδοσαν, οὐδὲ τῶν κοπρώνων ἂν ἐπιστάτας ἑλέσθαι φάσκων,", "st": "25.49"}, {"sp": "N", "t": "οὐκ ἐκείνους ὑβρίζων, οὔ (ἐκείνοις μὲν γὰρ ἐξῆν μικρὸν ἀργύριον δοῦσι τούτῳ μὴ ἀκούειν ταῦτα), ἀλλὰ τὴν ὑμετέραν χειροτονίαν προπηλακίζων καὶ τῆς αὑτοῦ πονηρίας ἐπίδειξιν ποιούμενος, τὰς δὲ κληρωτὰς ἀρχὰς σπαράττων, αἰτῶν, εἰσπράττων ἀργύριον, τί κακὸν οὐ παρέχων; τὰ τελευταῖα δὲ ταυτὶ πάντας εἰς ταραχὴν καὶ στάσιν ἐμβάλλειν ζητήσας, γράμματ’ ἐκτιθεὶς ψευδῆ, ὅλως δ’ ἐπὶ τῷ πάντων κακῷ πεφυκώς, καὶ πρόδηλος ὢν ὅτι τοιοῦτός ἐστι τῷ βίῳ.", "st": "25.50"}, {"sp": "N", "t": "σκοπεῖτε γάρ. εἰσὶν ὁμοῦ δισμύριοι πάντες Ἀθηναῖοι. τούτων ἕκαστος ἕν γέ τι πράττων κατὰ τὴν ἀγορὰν περιέρχεται, ἤτοι νὴ τὸν Ἡρακλέα τῶν κοινῶν ἢ τῶν ἰδίων. ἀλλ’ οὐχ οὗτος οὐδέν, οὐδ’ ἂν ἔχοι δεῖξαι πρὸς ὅτῳ τὸν βίον ἐστὶ τῶν μετρίων ἢ καλῶν. οὐχὶ τῶν πολιτικῶν ἀγαθῶν ἐπ’ οὐδενὶ τῇ ψυχῇ διατρίβει· οὐ τέχνης, οὐ γεωργίας, οὐκ ἄλλης ἐργασίας οὐδεμιᾶς ἐπιμελεῖται· οὐ φιλανθρωπίας, οὐχ ὁμιλίας οὐδεμιᾶς οὐδενὶ κοινωνεῖ·", "st": "25.51"}, {"sp": "N", "t": "ἀλλὰ πορεύεται διὰ τῆς ἀγορᾶς, ὥσπερ ἔχις ἢ σκορπίος ἠρκὼς τὸ κέντρον, ᾁττων δεῦρο κἀκεῖσε, σκοπῶν τίνι συμφορὰν ἢ βλασφημίαν ἢ κακόν τι προστριψάμενος καὶ καταστήσας εἰς φόβον ἀργύριον εἰσπράξεται. οὐδὲ προσφοιτᾷ πρός τι τούτων τῶν ἐν τῇ πόλει κουρείων ἢ μυροπωλίων ἢ τῶν ἄλλων ἐργαστηρίων οὐδὲ πρὸς ἕν· ἀλλ’ ἄσπειστος, ἀνίδρυτος, ἄμεικτος, οὐ χάριν, οὐ φιλίαν, οὐκ ἄλλ’ οὐδὲν ὧν ἄνθρωπος μέτριος γιγνώσκων· μεθ’ ὧν δ’ οἱ ζωγράφοι τοὺς ἀσεβεῖς ἐν Ἅιδου γράφουσιν, μετὰ τούτων, μετ’ ἀρᾶς καὶ βλασφημίας καὶ φθόνου καὶ στάσεως καὶ νείκους, περιέρχεται.", "st": "25.52"}, {"sp": "N", "t": "εἶθ’ ὃν οὐδὲ τῶν ἐν Ἅιδου θεῶν εἰκός ἐστιν τυχεῖν ἵλεων, ἀλλ’ εἰς τοὺς ἀσεβεῖς ὠσθῆναι διὰ τὴν πονηρίαν τοῦ βίου, τοῦτον ὑμεῖς ἀδικοῦντα λαβόντες οὐ μόνον οὐ τιμωρήσεσθε, ἀλλὰ καὶ μειζόνων ἀξιώσαντες δωρειῶν ἀφήσετ’ ἢ τοὺς εὐεργέτας; τίνι γὰρ πώποθ’ ὑμεῖς ἔδοτε, ἐὰν ὄφλῃ τι τῷ δημοσίῳ, τοῦτο μὴ καταθέντι τῶν ἴσων μετέχειν; οὐδενί. μὴ τοίνυν μηδὲ τούτῳ δῶτε νῦν, ἀλλὰ τιμωρήσασθε καὶ παράδειγμα ποιήσατε τοῖς ἄλλοις.", "st": "25.53"}, {"sp": "N", "t": "ἄξιον δ’ ἐστίν, ὦ ἄνδρες Ἀθηναῖοι, καὶ τὰ λοίπ’ ἀκοῦσαι· δεινῶν γὰρ ὄντων, οὐ μὲν οὖν ἐχόντων ὑπερβολήν, ὧν ἠκούσατ’ ἄρτι λέγοντος Λυκούργου, τὰ λοίπ’ ἐνάμιλλα τούτοις καὶ τῆς αὐτῆς φύσεως εὑρεθήσεται. πρὸς μὲν γὰρ τῷ τὸν πατέρ’ ἐν τῷ δεσμωτηρίῳ προδοὺς ἀπελθεῖν ἐξ Ἐρετρίας, ὥσπερ ἠκούσατε Φαίδρου, ἀποθανόνθ’ ὁ ἀσεβὴς οὗτος καὶ μιαρὸς οὐκ ἔθαψεν, οὐδὲ τοῖς θάψασι τὴν ταφὴν ἀπέδωκεν, ἀλλὰ καὶ δίκην πρὸς ἔλαχεν.", "st": "25.54"}, {"sp": "N", "t": "πρὸς δὲ τῷ τῆς μητρὸς μὴ ἀπεσχῆσθαι τὼ χεῖρε, ὥσπερ ἀρτίως ἠκούσατε τῶν μαρτύρων, καὶ τὴν ἀδελφὴν τὴν ἑαυτοῦ, οὐχ ὁμοπατρίαν μὲν οὖσαν, θυγατέρα δ’ ἐκείνης ὁπωσδήποτε γενομένην (ἐῶ γὰρ τοῦτο), ἀλλ’ ἀδελφήν γε, ἐπ’ ἐξαγωγῇ ἀπέδοτο, ὥς φησι τὸ ἔγκλημα τῆς δίκης, ἣν ὑπὲρ τούτων ἔλαχεν αὐτῷ ὁ χρηστὸς ἀδελφὸς οὑτοσί, ὁ νῦν συναπολογησόμενος.", "st": "25.55"}, {"sp": "N", "t": "πρὸς δὲ τούτοις τοιούτοις οὖσιν ἕτερον δεινόν, ὦ γῆ καὶ θεοί, πρᾶγμ’ ἀκούσεσθε. ὅτε γὰρ τὸ δεσμωτήριον διορύξας ἀπέδρα, τότε πρὸς γυναῖκά τιν’ ἔρχεται Ζωβίαν ὄνομα, ᾗ ἐτύγχανεν, ὡς ἔοικε, κεχρημένος ποτέ· καὶ κρύπτει καὶ διασῴζει τὰς πρώτας ἡμέρας αὐτὸν ἐκείνη, ἃς ἐζήτουν καὶ ἐκήρυττον οἱ ἕνδεκα, καὶ μετὰ ταῦτα δοῦσα δραχμὰς ὀκτὼ ἐφόδιον καὶ χιτωνίσκον καὶ ἱμάτιον ἐξέπεμψεν εἰς Μέγαρα.", "st": "25.56"}, {"sp": "N", "t": "ταύτην τὴν ἄνθρωπον, τὴν τοιαῦτ’ εὐεργετήσασαν αὐτόν, ὡς πολὺς παρ’ ὑμῖν ἔπνει καὶ λαμπρός, μεμφομένην τι καὶ τούτων ὑπομιμνῄσκουσαν καὶ ἀξιοῦσαν εὖ παθεῖν τὸ μὲν πρῶτον ῥαπίσας καὶ ἀπειλήσας ἀπέπεμψεν ἀπὸ τῆς οἰκίας, ὡς δ’ οὐκ ἐπαύεθ’ ἡ ἄνθρωπος, ἀλλὰ γυναίου πρᾶγμ’ ἐποίει καὶ πρὸς τοὺς γνωρίμους προσιοῦσ’ ἐνεκάλει, λαβὼν αὐτὸς αὐτοχειρίᾳ πρὸς τὸ πωλητηρίον τοῦ μετοικίου ἀπήγαγεν· καὶ εἰ μὴ κείμενον αὐτῇ τὸ μετοίκιον ἔτυχεν, ἐπέπρατ’ ἂν διὰ τοῦτον, ᾧ τῆς σωτηρίας αὐτὴ αἰτία ἐγεγόνει.", "st": "25.57"}, {"sp": "N", "t": "καὶ ταῦθ’ ὡς ἀληθῆ λέγω, κάλει μοι τὸν τὴν ταφὴν τοῦ πατρὸς οὐκ ἀπειληφότα, καὶ τὸν τῆς δίκης διαιτητήν, ἣν ὑπὲρ τῆς πράσεως τῆς ἀδελφῆς ἔλαχεν αὐτῷ οὑτοσί, καὶ τὸ ἔγκλημα φέρε. κάλει δέ μοι πρῶτον πάντων τὸν τῆς Ζωβίας προστάτην, τῆς ὑποδεξαμένης αὐτόν, καὶ τοὺς πωλητάς, πρὸς οὓς ἀπήγαγεν αὐτήν. ὑμεῖς δ’ ἠγανακτεῖτ’ ἀρτίως εἰ τῶν τὸν ἔρανον φερόντων εἰς τὴν σωτηρίαν αὐτῷ κατηγόρει. μιαρόν, μιαρόν, ὦ ἄνδρες Ἀθηναῖοι, τὸ θηρίον καὶ ἄμεικτον. λέγε τὰς μαρτυρίας.", "st": "25.58"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑΙ", "st": "25.58"}, {"sp": "N", "t": "τίς οὖν ἱκανὴ κατὰ τοῦ τοσαῦτα καὶ τοιαῦτα πεποιηκότος γένοιτ’ ἂν δίκη; τίς ἀξία τιμωρία; θάνατος μὲν γὰρ ἔμοιγε μικρὰ φαίνεται.", "st": "25.59"}, {"sp": "N", "t": "ἓν τοίνυν εἰπὼν ἔτι τῶν ἰδίων αὐτοῦ πονηρευμάτων τὰ λοίπ’ ἐάσω. πρὶν γὰρ ἐξελθεῖν ἐκ τοῦ δεσμωτηρίου, ἐμπεσόντος ἀνθρώπου τινὸς Ταναγραίου πρὸς κατεγγύην, γραμματεῖον ἔχοντος, προσελθὼν καὶ λαλῶν ὁτιδήποθ’ ὑφαιρεῖται τὸ γραμματεῖον. αἰτιωμένου δὲ καὶ δεινὰ ποιοῦντος τἀνθρώπου, καὶ λέγοντος ὅτι οὐδεὶς ἄλλος ὑφῄρηται, εἰς τοῦτ’ ἀφικνεῖται βδελυρίας ὥστε τύπτειν ἐπεχείρησε τὸν ἄνθρωπον.", "st": "25.60"}, {"sp": "N", "t": "νεαλὴς δὲ καὶ πρόσφατος ὢν ἐκεῖνος περιῆν αὐτοῦ τεταριχευμένου καὶ πολὺν χρόνον ἐμπεπτωκότος. ὡς δ’ εἰς τοῦθ’ ἧκεν, ἀπεσθίει τὴν ῥῖνα τἀνθρώπου. καὶ τότε μὲν περὶ τὴν γεγονυῖαν συμφορὰν ἅνθρωπος γενόμενος ἀπέστη τοῦ τὸ γραμματεῖον ἐρευνᾶν [καὶ ζητεῖν]· ὕστερον δ’ εὑρίσκουσι τὸ γραμματεῖον ἐν κιβωτίῳ τινί, οὗ τὴν κλεῖν οὗτος εἶχεν. καὶ μετὰ ταῦτα ψηφίζονται περὶ αὐτοῦ ταῦθ’ οἱ ἐν τῷ οἰκήματι, μὴ πυρός, μὴ λύχνου, μὴ ποτοῦ, μὴ βρωτοῦ μηδενὸς μηδένα τούτῳ κοινωνεῖν[, μηδὲ λαμβάνειν, μηδ’ αὐτὸν τούτῳ διδόναι].", "st": "25.61"}, {"sp": "N", "t": "καὶ ὅτι ταῦτ’ ἀληθῆ λέγω, κάλει μοι τὸν ἄνθρωπον οὗ τὴν ῥῖν’ ὁ μιαρὸς οὗτος ἐσθίων κατέφαγεν.", "st": "25.62"}, {"sp": "N", "t": "ΜΑΡΤΥΡΙΑ", "st": "25.62"}, {"sp": "N", "t": "καλῶν γ’ ἔργων ὁ ῥήτωρ δημιουργὸς ὑμῖν γέγονεν. ἄξιόν γ’ ἐκ τοῦ τοιαῦτα πεποιηκότος στόματος λόγον ἢ συμβουλήν τιν’ ἀκοῦσαι. ἀνάγνωθι δὴ καὶ τουτὶ τὸ καλὸν περὶ αὐτοῦ δόγμα.", "st": "25.62"}, {"sp": "N", "t": "ΔΟΓΜΑ", "st": "25.62"}, {"sp": "N", "t": "εἶτ’ οὐκ αἰσχύνεσθ’, ὦ ἄνδρες Ἀθηναῖοι, εἰ οἱ μὲν ἐπὶ πονηρίᾳ καὶ τοῖς ἐσχάτοις ἐμπεπτωκότες εἰς τὸ οἴκημα τοσούτῳ τοῦτον ἡγήσανθ’ ἑαυτῶν εἶναι πονηρότερον ὥστ’ ἄμεικτον ἑαυτοῖς καταστῆσαι, ὑμεῖς δ’ ἐξεληλακότων τῶν νόμων αὐτὸν ἐκ τῆς πολιτείας εἰς ὑμᾶς αὐτοὺς καταμείξετε; τί τῶν πεπραγμένων ἢ βεβιωμένων ἐπαινέσαντες; ἢ τί τῶν πάντων οὐχὶ δυσχεράναντες; οὐκ ἀσεβής; οὐκ ὠμός; οὐκ ἀκάθαρτος; οὐ συκοφάντης;", "st": "25.63"}, {"sp": "N", "t": "ἀλλ’ ὅμως τοιαῦτα ποιῶν καὶ τοιοῦτος ὢν ἐν ἁπάσαις ἀεὶ βοᾷ ταῖς ἐκκλησίαις “ἐγὼ μόνος εὔνους ὑμῖν· πάντες οὗτοι συνεστᾶσιν· προδέδοσθε· ἡ παρ’ ἐμοὶ μόνον εὔνοια λοιπή.” βούλομαι δὴ τὴν σφοδρὰν καὶ μεγάλην εὔνοιαν αὐτοῦ ταύτην ἐξετάσαι, πόθεν ἐστὶ καὶ ἐκ τίνος αὐτῷ γεγονυῖα, ἵν’ εἰ μέν ἐστι τοιαύτη, χρῆσθ’ αὐτῇ καὶ πιστεύητε, εἰ δὲ μή, φυλάττησθε.", "st": "25.64"}, {"sp": "N", "t": "πότερον γάρ, ὅτι τοῦ πατρὸς αὐτοῦ θάνατον κατέγνωτε καὶ τὴν μητέρ’ [αὐτοῦ] ὀφλοῦσαν ἀποστασίου ἀπέδοσθε, διὰ ταῦτ’ αὐτὸν ὑμῖν εὔνουν ὑπολαμβάνετ’ εἶναι; ἀλλ’ ἄτοπον νὴ τὸν Δία καὶ θεοὺς τοῦτό γε. εἰ μὲν γὰρ εὔνους ἐστὶν ἐκείνοις καὶ τὸν τῆς φύσεως διασῴζει νόμον, ὃς καὶ ἀνθρώποις καὶ θηρίοις εἷς καὶ ὁ αὐτὸς ἅπασιν ὥρισται, στέργειν τοὺς γονέας,", "st": "25.65"}, {"sp": "N", "t": "κακόνους ἐστὶ τοῖς ἐκείνους ἀπολωλεκόσιν δῆλον ὅτι καὶ νόμοις καὶ πολιτείᾳ τῇ τούτων· εἰ δὲ μηδένα τούτων ὑπόλογον ποιεῖται, ἡδέως ἂν εἰδείην τίς ἐστιν ὁ τὴν πρὸς τοὺς γονέας εὔνοιαν ὁρῶν προδεδωκότα τοῦτον, ἣν πρὸς τὸν δῆμον νῦν ἔχειν ὑπισχνεῖται, πιστεύων· ἐγὼ μὲν γὰρ ἄπιστον καὶ θεοῖς ἐχθρόν, οὐ μόνον ἀνθρώποις, ὑπολαμβάνω τὸν τῶν γονέων ἀμελοῦντα.", "st": "25.66"}, {"sp": "N", "t": "ἀλλὰ νὴ Δί’ ὅτι τὰς ἐνδείξεις αὐτοῦ κατεψηφίσασθε, καὶ δὶς εἰς τὸ δεσμωτήριον κατέθεσθε καὶ αὐτὸν καὶ τὸν ἀδελφόν, διὰ ταῦθ’ ὑμῖν εὔνους ἐστίν. ἀλλὰ καὶ τοῦτ’ ἄτοπον. ἀλλ’ ὅτι τὴν ἀρχὴν ἣν ἔλαχεν ⟨ἄρχειν⟩ ἀπεδοκιμάσατε;", "st": "25.67"}, {"sp": "N", "t": "ἀλλ’ ὅτι παρανόμων αὐτοῦ κατέγνωτε; ἀλλ’ ὅτι πέντε ταλάντων πρὸς ἐτιμήσατε; ἀλλ’ ὅτι δακτυλοδεικτεῖτ’ ἐπὶ τῷ πονηρότατον τῶν ὄντων ἁπάντων δεικνύναι; ἀλλ’ ὅτι τῶν ὑπαρχόντων νόμων καὶ πολιτείας μενόντων οὐκ ἔνι τῶν αἰσχρῶν αὐτῷ τούτων ἀπαλλαγῆναι; ἀλλὰ διὰ τί ὑμῖν οὗτος εὔνους ἐστίν; ὅτι, φησίν, ἀναιδής ἐστιν. ὁ δ’ ἀναιδὴς ἐκ τίνος ὠνομάσθη τῶν ἄλλων ἀλλ’ ἢ ὅταν τὰ μήτ’ ὄντα μήτ’ ἂν γενόμενα, ταῦτα τολμᾷ λέγειν δι’ ἀναισχυντίαν, ὅπερ οὗτος ποιεῖ;", "st": "25.68"}, {"sp": "N", "t": "ἡγοῦμαι τοίνυν καὶ περὶ τῆς ἐνδείξεως, ἅ μοι παραλείπειν ἔδοξε Λυκοῦργος, βέλτιον εἶναι πρὸς ὑμᾶς εἰπεῖν. ἐγὼ γὰρ οἶμαι δεῖν ὑμᾶς, ὥσπερ ἂν εἰ χρέος ἐσκοπεῖτ’ ἴδιον, οὕτως ἐξετάσαι τοῦτον καὶ τὰ τουτουὶ τοῦ ἀγῶνος δίκαια. εἰ τοίνυν τις ὀφείλειν τιν’ ᾐτιᾶτο χρήματα, ὁ δ’ ἠρνεῖτο, εἰ μὲν ἐφαίνονθ’ αἵ τε συνθῆκαι καθ’ ἃς ἐδανείσατο κείμεναι καὶ οἱ τεθέντες ὅροι ἑστηκότες, τὸν ἀρνούμενον ἡγεῖσθ’ ἂν ἀναιδῆ δηλονότι, εἰ δ’ ἀνῃρημένα ταῦτα, τὸν ἐγκαλοῦντα· οὕτω ταῦτα πέφυκεν.", "st": "25.69"}, {"sp": "N", "t": "εἰσὶ τοίνυν ὧν Ἀριστογείτων ὀφείλει τῇ πόλει συνθῆκαι μὲν οἱ νόμοι, καθ’ οὓς ἐγγράφονται πάντες οἱ ὀφλισκάνοντες, ὅρος δ’ ἡ σανὶς ἡ παρὰ τῇ θεῷ κειμένη. εἰ μὲν οὖν ἀνῄρηται ταῦτα καὶ ἐξαλήλιπται τὸ ὄφλημα, ἡμεῖς ληροῦμεν, μᾶλλον δὲ ψευδόμεθα· εἰ δ’ ἔτ’ ἔστι καὶ ἔσται τέωσπερ ἂν ἐκτείσῃ κείμενα, οὗτος οὐδὲν ἀληθὲς λέγει, ἀλλ’ ἀδικεῖ καὶ δεινὰ ποιεῖ τὰ κοινὰ δίκαι’ ἀφανίζειν ἐπιχειρῶν.", "st": "25.70"}, {"sp": "N", "t": "οὐ γάρ, εἰ μὴ πᾶν ὅσον ὦφλεν ὀφείλει, νῦν ἡ κρίσις οὐδ’ ὁ λόγος, ἀλλ’ εἰ ὀφείλει. ἢ δεινά γ’ ἂν πάθοιεν οἱ δραχμὴν ἐγγεγραμμένοι μόνην, εἰ, διότι μικρὰ καὶ οὐδὲν ἠδικήκασιν, ἰσχύσει τὸ ὀφείλειν κατ’ αὐτῶν· ἐὰν δέ τις μεγάλ’ ἠδικηκὼς ᾖ, μίαν θεὶς ἢ δύο καταβολὰς ἐπίτιμος ἔσται. ἔτι τοίνυν τρί’ ἐστὶν τὰ ὀφλήμαθ’ ἃ ἐγγέγραπται καὶ ἐφ’ οἷς ἐνδέδεικται. τὰ μὲν δὴ δύ’ ἐν ἀπογραφῇ πεποίηται, τὸ δ’ ἓν οὐδ’ ἀπογέγραπται, ἀλλὰ βουλεύσεως τὸν Ἀλωπεκῆθεν Ἀρίστωνα διώκει.", "st": "25.71"}, {"sp": "N", "t": "ναί, φησίν· ἀδίκως γάρ μ’ ἐγγέγραφεν. δεῖ δή σε, ὡς ἔοικεν, δίκην λαβεῖν. οὐκοῦν ὑποσχεῖν πρῶτον καὶ μεῖναι ἐν οἷς πέπονθας ἀνάγκη. ἢ τίνος λήψει δίκην; εἰ γὰρ ἔξεστί σοι πάνθ’ ἅπερ τοῖς ἄλλοις, τί ἠδίκησαι;", "st": "25.72"}, {"sp": "N", "t": "φέρε δὴ πρὸς θεῶν κἀκεῖνο σκέψασθε. ἂν ἕλῃ τὸν Ἀρίστωνα τῆς βουλεύσεως, τί ἔσται; ἐξαλειφθήσεται νὴ Δία, ὁ δ’ ἀντεγγραφήσεται· ταῦτα γὰρ οἱ νόμοι λέγουσιν. καλῶς. πότερον οὖν ἀπὸ ταύτης τῆς ἡμέρας ὁδὶ μὲν ὀφειλήσει τῷ δημοσίῳ, ὁ ἐξαλειφθείς, ἐκεῖνος δ’ ἐπίτιμος ἔσται, ὁ ἐγγραφείς; ἐκ γὰρ ὧν νῦν ὅδ’ ἀξιοῖ, ταῦτα συμβαίνει· εἰ γὰρ ὅτ’ ἐγγέγραπται μὴ ὀφείλει, ἐπειδὰν ἐξαλειφθῇ, ὀφειλήσει δηλονότι. ἀλλ’ οὐκ ἔστι ταῦτα, οὐκ ἔστιν, ἀλλ’ ὅταν ἐξαλειφθῇ, τότ’ οὐκ ὀφειλήσει· οὐκοῦν νῦν ὀφείλει.", "st": "25.73"}, {"sp": "N", "t": "τί δ’; ἂν αὐτὸν ἀποφύγῃ, παρὰ τοῦ κομιεῖται ταῦθ’ ἡ πόλις ἃ νῦν οὐκ ἐξὸν οὗτος ποιεῖ; πόθεν δέ, οἷς οὗτος θανάτου τιμᾶται καὶ δεσμοῦ περιιὼν ἐν τῷ δικαστηρίῳ, οἱ μὲν τὰς ψυχάς, οἱ δὲ τὸ μὴ δεινὰ πεπονθέναι κομιοῦνται; ᾧ γὰρ οὐδὲ τῶν ἴσων οὐδὲ τῶν ἐγκυκλίων δικαίων μετουσίαν διδόασιν οἱ νόμοι, οὗτος τῶν ἀνηκέστων ἑτέροις αἴτιος γίγνεται, οὐκ ὀρθῶς οὐδὲ πολιτικῶς οὐδ’ ὡς συμφέρει γιγνομένων τούτων.", "st": "25.74"}, {"sp": "N", "t": "ἀλλ’ ἔγωγε ταῦθ’ ὁρῶν θαυμάζω, τὸ τἄνω κάτω γεγενῆσθαι τί ποτ’ οἴεσθ’ εἶναι. ἐὰν ἡ γῆ μὲν ἄνω, τὰ δ’ ἄστρα κάτω γένηται; οὐκ ἔστι τοῦτο γενέσθαι, μηδὲ γένοιτο. ἀλλ’ ὅταν, οἷς ἐκ τῶν νόμων μὴ ἔξεστιν, ἐκ τῶν ὑμετέρων βουλήσεων ἐξῇ, ὅταν ἡ μὲν πονηρία τιμᾶται, τὰ χρηστὰ δ’ ἀπορρίπτηται, ὅταν τὸ δίκαιον καὶ τὸ συμφέρον ἡττᾶται τοῦ φθόνου, τότ’ ἄνω κάτω πάντα χρὴ νομίζειν τετράφθαι.", "st": "25.75"}, {"sp": "N", "t": "ἤδη τοίνυν τινὰς εἶδον τῶν ἀγωνιζομένων οἳ τοῖς πράγμασιν αὐτοῖς ἁλισκόμενοι, καὶ οὐκ ἔχοντες ὡς οὐκ ἀδικοῦσι δεῖξαι, οἱ μὲν εἰς τὴν τοῦ βίου μετριότητα καὶ σωφροσύνην κατέφυγον, οἱ δ’ εἰς τὰ τῶν προγόνων ἔργα καὶ λῃτουργίας, οἱ δ’ εἰς ἕτερα τοιαῦτα δι’ ὧν εἰς ἔλεον καὶ φιλανθρωπίαν τοὺς δικάζοντας ἤγαγον. τούτῳ δ’ οὐδέν’ ὁρῶ τῶν τόπων τούτων βάσιμον ὄντα, ἀλλὰ πάντ’ ἀπόκρημνα, φάραγγας,", "st": "25.76"}, {"sp": "N", "t": "βάραθρα. τί γὰρ ὡς ἀληθῶς ἐρεῖ; ὧν ὁ πατήρ τι πεποίηκε νὴ Δία. ἀλλὰ κατεγνώκαθ’ ὑμεῖς ἐν τουτοισὶ τοῖς δικαστηρίοις αὐτοῦ θάνατον, ὡς πονηροῦ δηλονότι καὶ ἀξίου τεθνάναι. ἀλλὰ νὴ Δία, εἰ ταῦτ’ ἐστὶν αὐτῷ δυσχερῆ τὰ περὶ τὸν πατέρα, εἰς τὸν ἑαυτοῦ βίον καταφεύξεται ὡς σώφρονα καὶ μέτριον. ποῖον; ὃν ποῦ βεβίωκεν; ὃν μὲν γὰρ ἅπαντες ὑμεῖς ἑοράκατε, οὐκ ἔστι τοιοῦτος.", "st": "25.77"}, {"sp": "N", "t": "ἀλλ’ ὦ τᾶν, εἰς τὰς λῃτουργίας ἀποχωρήσεται. τὰς πότ’ ἢ ποῦ γεγονυίας; τὰς τοῦ πατρός; ἀλλ’ οὐκ εἰσίν. ἀλλὰ τὰς ἑαυτοῦ; φάσεις, ἀπαγωγάς, ἐνδείξεις, οὐχὶ λῃτουργίας εὑρήσετε. ἀλλὰ νὴ Δία καὶ χωρὶς τούτων συγγενεῖς πολλοὶ καὶ καλοὶ κἀγαθοὶ παραστάντες αὐτὸν ἐξαιτήσονται. ἀλλ’ οὔτ’ εἰσὶν οὔτ’ ἐγένοντο πώποτε· πῶς γὰρ τῷ γε μηδ’ ἐλευθέρῳ;", "st": "25.78"}, {"sp": "N", "t": "πλὴν ἔστι νὴ Δία, ἔστιν ἀδελφός τις οὗτος αὐτῷ, ὁ παρὼν καὶ τὴν καλὴν δίκην [αὐτῷ] λαχών. περὶ οὗ τὰ μὲν ἄλλα τί δεῖ λέγειν; ἀδελφὸς δ’ ἐστὶ τούτου ὁμομήτριος καὶ ὁμοπάτριος καὶ πρὸς τοῖς ἄλλοις κακοῖς δίδυμος. οὑτοσί—τὰ μὲν ἄλλα σιωπῶ, ἀλλ’ ἐφ’ οἷς ὑμεῖς τὴν μιαρὰν Θεωρίδα, τὴν Λημνίαν, τὴν φαρμακίδα, καὶ αὐτὴν καὶ τὸ γένος ἅπαν ἀπεκτείνατε,", "st": "25.79"}, {"sp": "N", "t": "ταῦτα λαβὼν τὰ φάρμακα καὶ τὰς ἐπῳδὰς παρὰ τῆς θεραπαίνης αὐτῆς, ἣ κατ’ ἐκείνης τότ’ ἐμήνυσεν, ἐξ ἧσπερ ὁ βάσκανος οὗτος πεπαιδοποίηται, μαγγανεύει καὶ φενακίζει καὶ τοὺς ἐπιλήπτους φησὶν ἰᾶσθαι, αὐτὸς ὢν ἐπίληπτος πάσῃ πονηρίᾳ. οὗτος οὖν αὐτὸν ἐξαιρήσεται, ὁ φαρμακός, ὁ λοιμός, ὃν οἰωνίσαιτ’ ἄν τις μᾶλλον ἰδὼν ἢ προσειπεῖν βούλοιτο, ὃς αὐτὸς αὑτῷ θανάτου τετίμηκεν ὅτε τοιαύτην δίκην ἔλαχεν.", "st": "25.80"}, {"sp": "N", "t": "τί οὖν λοιπόν, ὦ ἄνδρες Ἀθηναῖοι; ἃ κοινὰ νὴ Δία πᾶσιν ὑπάρχει τοῖς ἀγωνιζομένοις παρὰ τῆς τῶν ἄλλων ὑμῶν φύσεως, καὶ οὐδεὶς αὐτὸς ἑαυτῷ ταῦτα φέρει τῶν κρινομένων, ἀλλ’ ὑμῶν ἕκαστος ἔχων οἴκοθεν ἔρχεται, ἔλεον, συγγνώμην, φιλανθρωπίαν. ἀλλὰ τούτων γ’ οὔθ’ ὅσιον οὔτε θέμις τῷ μιαρῷ τούτῳ μεταδοῦναι. διὰ τί; ὅτι ὃν ἂν αὐτὸς ἕκαστος νόμον τῇ φύσει κατὰ πάντων ἔχῃ, τούτου τυγχάνειν παρ’ ἑκάστου δίκαιός ἐστι καὶ αὐτός.", "st": "25.81"}, {"sp": "N", "t": "τίν’ οὖν νόμον ὑμῖν ἢ τίνα βούλησιν ἔχειν Ἀριστογείτων κατὰ πάντων δοκεῖ; πότερ’ εὐτυχοῦντας ὁρᾶν καὶ ἐν εὐδαιμονίᾳ καὶ χρηστῇ δόξῃ διάγοντας; καὶ τί ποιῶν ζήσεται; τὰ γὰρ τῶν ἄλλων κακὰ τοῦτον τρέφει. οὐκοῦν ἐν κρίσεσι καὶ ἀγῶσι καὶ πονηραῖς αἰτίαις ἅπαντας εἶναι βούλεται· ταῦτα γεωργεῖ, ταῦτ’ ἐργάζεται. ὁ δὲ ποῖός τις, ὦ ἄνδρες Ἀθηναῖοι, καλοῖτ’ ἂν δικαίως ὁ τρισκατάρατος, ὁ κοινὸς ἐχθρός, ὁ πᾶσι δυσμενής, ὅτῳ μήτε γῆ φέροι καρπὸν μήτ’ ἀποθανόντα δέξαιτο; οὐχ ὁ τοιοῦτος; ἔγωγε νομίζω.", "st": "25.82"}, {"sp": "N", "t": "τίνος δὲ συγγνώμης ἢ ποίων ἐλέων οἱ σεσυκοφαντημένοι τετυχήκασιν παρὰ τούτου, οἷς οὗτος θανάτου πᾶσιν ἐτιμᾶτ’ ἐν τουτοισὶ τοῖς δικαστηρίοις, καὶ ταῦτα πρὶν τὴν πρώτην ψῆφον διενεχθῆναι; καὶ ἐφ’ οἷς ὁ βάσκανος οὗτος οὕτως ὠμῶς καὶ πικρῶς εἶχεν, τούτους ὑμῶν οἱ λαχόντες, ἄνδρες Ἀθηναῖοι, τὰ δίκαια ποιοῦντες ἔσῳζον, καὶ τοὺς ὑπὸ τούτου συκοφαντουμένους ἀπεψηφίζοντο, καὶ τὸ πέμπτον μέρος τῶν ψήφων οὐ μετεδίδοσαν τούτῳ.", "st": "25.83"}, {"sp": "N", "t": "ἀλλ’ ἥ γε τούτου πικρία καὶ μιαιφονία καὶ ὠμότης παρῆν καὶ ἐξητάζετο. οὐχὶ παιδία, οὐχὶ μητέρας τῶν κρινομένων ἐνίων γραῦς παρεστώσας ὁρῶν οὗτος ἠλέει. εἶτα σοὶ συγγνώμη; πόθεν ἢ παρὰ τοῦ; ἢ τοῖς σοῖς παιδίοις ἔλεος; πολλοῦ γε καὶ δεῖ. σὺ τὸν εἰς ταῦτ’ ἔλεον προδέδωκας, Ἀριστογεῖτον, μᾶλλον δ’ ἀνῄρηκας ὅλως. μὴ δὴ πρὸς οὓς αὐτὸς ἔχωσας λιμένας καὶ προβόλων ἐνέπλησας, πρὸς τούτους προσορμίζου· οὐ γὰρ δίκαιον.", "st": "25.84"}, {"sp": "N", "t": "εἰ τοίνυν ἀκούσαιτε καὶ τὰς βλασφημίας ἃς κατὰ τὴν ἀγορὰν περιιὼν καθ’ ὑμῶν ἔλεγεν, ἔτι μᾶλλον ἂν αὐτὸν μισήσαιτε, καὶ δικαίως. φησὶ γὰρ πολλοὺς ὀφείλειν τῷ δημοσίῳ, τούτους δ’ ἅπαντας ὁμοίους ὑπάρχειν ἑαυτῷ. ἐγὼ δὲ πολλοὺς μὲν εἶναι τοὺς ἠτυχηκότας, εἰ καὶ δύ’ εἰσὶ μόνοι, συγχωρῶ· παντὶ γὰρ πλείους εἰσὶ τοῦ δέοντος, καὶ οὐδένα τῶν ἄλλων ὀφείλειν ἔδει. οὐ μέντοι μὰ τοὺς θεοὺς τούτῳ γ’ ὑπάρχειν ὁμοίους οἴομαι τούτους, οὐδὲ πολλοῦ δεῖ, ἀλλὰ καὶ τοὐναντίον.", "st": "25.85"}, {"sp": "N", "t": "οὑτωσὶ δὲ λογίζεσθε. καὶ μή μ’ ὑπολάβητ’, ὦ ἄνδρες Ἀθηναῖοι, ὡς πρὸς ὀφείλοντας ὑμᾶς τῷ δημοσίῳ διαλέγεσθαι· οὔτε γὰρ ἔστιν μήτε γένοιτο τοῦτο, οὔτ’ ἐγὼ νομίζω. ἀλλ’ εἴ τῴ τις ἄρ’ ἢ φίλος ἢ γνώριμός ἐστιν ἐν τούτοις, ὡς ὑπὲρ τούτου τοῦτον προσήκει μισεῖν, τοῦτο βούλομαι δεῖξαι. πρῶτον μὲν ὅτι ἀνθρώπους ἐπιεικεῖς, οἷς ἐγγύαι καὶ φιλανθρωπίαι γίγνονται καὶ ὀφλήματ’ ἴδια, οἷς οὐ πρόσεστι κοίν’ ἀδικήματα, ἠτυχηκέναι δὲ συμβέβηκεν, εἰς τὴν ὁμοίαν τάξιν ἑαυτῷ καὶ βλασφημίαν ἄγει, οὐκ ὀρθῶς οὐδὲ προσηκόντως.", "st": "25.86"}, {"sp": "N", "t": "οὐ γὰρ ὅμοιόν ἐστιν, Ἀριστογεῖτον, οὐδὲ πολλοῦ δεῖ, γράψαντά σε τῶν πολιτῶν τρεῖς ἀκρίτους ἀποκτεῖναι γραφὴν ἁλῶναι παρανόμων καὶ δέον σε τεθνάναι [ἐπὶ ταύτῃ] τιμήματος τυχεῖν, καὶ φίλον ἐγγυησάμενον μὴ δύνασθαι ζημίαν ἀπροσδόκητον ἐνεγκεῖν· οὐχ ὅμοιον, οὔ. ἔπειθ’ ὅτι τὴν κοινὴν φιλανθρωπίαν ἣν ὑμεῖς ἔχετ’ ἐκ φύσεως πρὸς ἀλλήλους οὗτος ἀναιρεῖ καὶ διαφθείρει. ὑμεῖς γάρ, ὦ ἄνδρες Ἀθηναῖοι, τῇ τῆς φύσεως πρὸς ἀλλήλους, ὅπερ εἶπον, χρώμενοι φιλανθρωπίᾳ, ὥσπερ αἱ συγγένειαι τὰς ἰδίας οἰκοῦσιν οἰκίας, οὕτω τὴν πόλιν οἰκεῖτε δημοσίᾳ.", "st": "25.87"}, {"sp": "N", "t": "πῶς οὖν ἐκεῖναι; ὅπου πατήρ ἐστι καὶ υἱεῖς ἄνδρες, τυχὸν δὲ καὶ τούτων παῖδες, ἐνταῦθ’ ἀνάγκη πολλὰς καὶ μηδὲν ὁμοίας εἶναι βουλήσεις· οὐ γὰρ τῶν αὐτῶν οὔτε λόγων οὔτ’ ἔργων ἐστὶν ἡ νεότης τῷ γήρᾳ. ἀλλ’ ὅμως οἵ τε νέοι πάνθ’ ὅσ’ ἂν πράττωσιν, ἄνπερ ὦσιν μέτριοι, οὕτω ποιοῦσιν ὥστε μάλιστα μὲν πειρᾶσθαι λανθάνειν, εἰ δὲ μή, φανεροί γ’ εἶναι τοῦτο βουλόμενοι ποιεῖν· οἵ τε πρεσβύτεροι πάλιν, ἂν ἄρ’ ἴδωσιν ἢ δαπάνην ἢ πότον ἢ παιδιὰν πλείω τῆς μετρίας, οὕτω ταῦθ’ ὁρῶσιν ὥστε μὴ δοκεῖν ἑορακέναι. ἐκ δὲ τούτων γίγνεταί τε πάνθ’ ἃ φέρουσιν αἱ φύσεις καὶ καλῶς γίγνεται.", "st": "25.88"}, {"sp": "N", "t": "τὸν αὐτὸν τοίνυν τρόπον ὑμεῖς, ὦ ἄνδρες Ἀθηναῖοι, τὴν πόλιν οἰκεῖτε συγγενικῶς καὶ φιλανθρώπως, οἱ μὲν οὕτως ὁρῶντες τὰ τῶν ἠτυχηκότων ἔργα ὥστε, τὸ τῆς παροιμίας, ὁρῶντας μὴ ὁρᾶν καὶ ἀκούοντας μὴ ἀκούειν, οἱ δ’ οὕτω ποιοῦντες ἃ πράττουσιν ὥστ’ εἶναι φανεροὶ καὶ φυλαττόμενοι καὶ αἰσχυνόμενοι. ἐκ δὲ τούτων ἡ κοινὴ καὶ πάντων τῶν ἀγαθῶν αἰτία τῇ πόλει μένει καὶ συνέστηκεν ὁμόνοια.", "st": "25.89"}, {"sp": "N", "t": "ταῦτα τοίνυν Ἀριστογείτων τὰ καλῶς οὕτω πεπηγότα τῇ φύσει καὶ τοῖς ἤθεσι τοῖς ὑμετέροις κινεῖν καὶ ἀναιρεῖ καὶ μεταρρίπτει, καὶ ἃ τῶν ἄλλων τῶν ἠτυχηκότων ἕκαστος ἀψοφητεὶ ποιεῖ, ταῦθ’ οὗτος μόνον οὐ κώδωνας ἐξαψάμενος διαπράττεται. οὐ πρυτάνεις, οὐ κῆρυξ, οὐκ ἐπιστάτης, οὐχ ἡ προεδρεύουσα φυλὴ τούτου κρατεῖν δύναται.", "st": "25.90"}, {"sp": "N", "t": "ἐπειδὰν οὖν τις ὑμῶν ἐφ’ οἷς οὗτος ἀσελγαίνει λυπηθεὶς εἴπῃ “τοῦτον δὲ ταῦτα ποιεῖν, καὶ ταῦτ’ ὀφείλοντα τῷ δημοσίῳ,” “τί δ’; οὐ καὶ ὁ δεῖνα” φησὶν “ὀφείλει”; τὸν ἐχθρὸν ἕκαστος ὑπειπὼν τὸν αὑτοῦ· ὥστε τὴν πονηρίαν τὴν τούτου αἰτίαν εἶναι τῶν βλασφημιῶν αἳ περὶ τῶν οὐχ ὁμοίων τούτῳ διὰ τοῦτον γίγνονται.", "st": "25.91"}, {"sp": "N", "t": "λοιπὸν τοίνυν ἐστίν, ὦ ἄνδρες Ἀθηναῖοι, τοῖς ἀπαλλαγῆναι βουλομένοις τούτου, ἀδίκημα σαφὲς καὶ ἐναργὲς ἔχοντας ἐκ τῶν νόμων, μάλιστα μὲν αὐτῷ θανάτου τιμῆσαι, εἰ δὲ μή, τοσοῦτον ἀναθεῖναι τίμημα χρημάτων ὅσον μὴ δυνήσεται φέρειν· ἄλλη γὰρ οὐκ ἔστιν ἀπαλλαγὴ τούτου, σαφῶς ἐπίστασθε.", "st": "25.92"}, {"sp": "N", "t": "καὶ γάρ, ὦ ἄνδρες Ἀθηναῖοι, τῶν μὲν ἄλλων ἀνθρώπων ἄν τις ἴδοι τοὺς μὲν βελτίστους καὶ μετριωτάτους αὐτῇ τῇ φύσει πάντα ποιοῦντας ἑκόντας ἃ δεῖ, τοὺς δὲ χείρους μὲν τούτων, ἔξω δὲ τοῦ πονηροὺς ἄγαν κληθῆναι, τῷ φόβῳ τῷ πρὸς ὑμᾶς καὶ τῷ τοῖς αἰσχροῖς καὶ λόγοις καὶ ὀνείδεσιν ἀλγεῖν εὐλαβουμένους ἐξαμαρτάνειν· τοὺς δὲ πονηροτάτους καὶ ἐξαγίστους ὀνομαζομένους τάς γε συμφορὰς σωφρονίζειν λέγουσιν.", "st": "25.93"}, {"sp": "N", "t": "οὑτοσὶ τοίνυν Ἀριστογείτων τοσοῦτον ὑπερῆρκεν ἅπαντας ἀνθρώπους πονηρίᾳ ὥστ’ οὐδὲ παθὼν ἐνουθετήθη, ἀλλ’ ἐπὶ τοῖς αὐτοῖς ἀδικήμασι καὶ πλεονεκτήμασιν πάλιν εἴληπται. καὶ τοσούτῳ πλείονος ὀργῆς ἄξιός ἐστιν νῦν ἢ πρότερον, ὅσῳ τότε μὲν γράφειν μόνον ᾤετο δεῖν παρὰ τοὺς νόμους, νυνὶ δὲ πάντα ποιεῖν, αἰτιᾶσθαι, λέγειν, διαβάλλειν, βλασφημεῖν, θανάτου τιμᾶσθαι, εἰσαγγέλλειν, κακολογεῖν τοὺς ἐπιτίμους αὐτὸς ὀφείλων τῷ δημοσίῳ· τούτου γὰρ οὐδέν ἐστι δεινότερον.", "st": "25.94"}, {"sp": "N", "t": "τὸ μὲν οὖν νουθετεῖν τοῦτον μανία· ὃς γὰρ οἷς ὁ δῆμος ἅπας τοὺς ἐνοχλοῦντας ἑαυτὸν νουθετεῖ θορύβοις μηδεπώποθ’ ὑπεῖξε μηδὲ διετράπη, ταχύ γ’ ἂν φροντίσειέ τι τοῦ παρ’ ἑνὸς λόγου. ἀνίατον, ἀνίατον, ἄνδρες Ἀθηναῖοι, τὸ πρᾶγμ’ ἔστι τὸ τούτου. δεῖ δὴ πάντας, ὥσπερ οἱ ἰατροί, ὅταν καρκίνον ἢ φαγέδαιναν ἢ τῶν ἀνιάτων τι κακῶν ἴδωσιν, ἀπέκαυσαν ἢ ὅλως ἀπέκοψαν, οὕτω τοῦτο τὸ θηρίον ὑμᾶς ἐξορίσαι, ῥῖψαι ἐκ τῆς πόλεως, ἀνελεῖν, μὴ περιμείναντάς τι παθεῖν, ὃ μήτ’ ἰδίᾳ μήτε δημοσίᾳ γένοιτο, ἀλλὰ προευλαβηθέντας.", "st": "25.95"}, {"sp": "N", "t": "ὡδὶ γὰρ ὁρᾶτε. οὐδένα πώποτ’ ἴσως ὑμῶν ἔχις ἔδακεν οὐδὲ φαλάγγιον, μηδὲ δάκοι· ἀλλ’ ὅμως ἅπαντα τὰ τοιαῦτα, ἐπὰν ἴδητε, ἀποκτείνετε. τὸν αὐτὸν τοίνυν τρόπον, ὦ ἄνδρες Ἀθηναῖοι, καὶ ὅταν συκοφάντην καὶ πικρὸν καὶ ἔχιν τὴν φύσιν ἄνθρωπον ἴδητε, μὴ πόθ’ ἕκαστον ὑμῶν δήξεται περιμένετε, ἀλλ’ ὁ προστυχὼν ἀεὶ τιμωρησάσθω.", "st": "25.96"}, {"sp": "N", "t": "Λυκοῦργος μὲν οὖν τὴν Ἀθηνᾶν ἐμαρτύρετο καὶ τὴν μητέρα τῶν θεῶν, καὶ καλῶς ἐποίει. ἐγὼ δὲ τοὺς προγόνους τοὺς ὑμετέρους καὶ τὰς ἀρετὰς τὰς ἐκείνων ἀνακαλῶ, ὧν οὐδ’ ὁ χρόνος τὴν μνήμην ἠφάνικεν, εἰκότως· ἐπολιτεύοντο γὰρ οὐχὶ τοῖς πονηροτάτοις καὶ συκοφάνταις συνεργεῖν διδόντες ἑαυτούς, οὐδὲ τὸν ἐντὸς τείχους φθόνον ἀσκοῦντες ἐπ’ ἀλλήλους, ἀλλὰ καὶ τῶν ῥητόρων καὶ τῶν ἰδιωτῶν τοὺς μὲν σώφρονας καὶ χρηστοὺς τιμῶντες, τοὺς δὲ πονηροὺς καὶ θρασεῖς μισοῦντες καὶ κολάζοντες. ἐξ ὧν πάντες ἀθληταὶ τῶν καλῶν ἔργων ἐγένοντο.", "st": "25.97"}, {"sp": "N", "t": "ἓν δ’ εἰπὼν ἔτι παύσασθαι βούλομαι. ἔξιτ’ αὐτίκα δὴ μάλ’ ἐκ τοῦ δικαστηρίου, θεωρήσουσι δ’ ὑμᾶς οἱ περιεστηκότες καὶ ξένοι καὶ πολῖται, καὶ κατ’ ἄνδρ’ εἰς ἕκαστον τὸν παριόντα βλέψονται καὶ φυσιογνωμονήσουσι τοὺς ἀπεψηφισμένους. τί οὖν ἐρεῖτ’, ὦ ἄνδρες Ἀθηναῖοι, εἰ προέμενοι τοὺς νόμους ἔξιτε; ποίοις προσώποις ἢ τίσιν ὀφθαλμοῖς πρὸς ἕκαστον τούτων ἀντιβλέψεσθε;", "st": "25.98"}, {"sp": "N", "t": "πῶς δ’ εἰς τὸ μητρῷον βαδιεῖσθε, ἄν τι βούλησθε; οὐ γὰρ δήπου καθ’ ἕν’ ὑμῶν ἕκαστος ὡς ἐπὶ κυρίους τοὺς νόμους πορεύσεται, εἰ νῦν μὴ βεβαιώσαντες αὐτοὺς ἔξιθ’ ἅπαντες κοινῇ. πῶς δὲ ταῖς νουμηνίαις εἰς ἀκρόπολιν ἀναβαίνοντες τἀγαθὰ τῇ πόλει διδόναι καὶ ἕκαστος ἑαυτῷ τοῖς θεοῖς εὔξεσθε, ὅταν ὄντος τούτου ἐκεῖ καὶ τοῦ πατρὸς αὐτοῦ τοῦ χρηστοῦ τἀναντία τοῖς ὅρκοις καὶ τοῖς ἐκεῖ γράμμασιν ἐγνωκότες ἦτε;", "st": "25.99"}, {"sp": "N", "t": "τί ἐρεῖτ’, ἄνδρες Ἀθηναῖοι, τί ἐρεῖτε, ἄν τις ὑμᾶς ἐρωτᾷ γνωρίσας τοὺς ἀπεψηφισμένους; τί φήσετε; ἀρέσκειν τοῦτον ὑμῖν; καὶ τίς ὁ τοῦτο τολμήσων εἰπεῖν; τίς ὁ τῆς τούτου πονηρίας μετ’ ἀρᾶς καὶ κακῆς δόξης κληρονομεῖν βουλησόμενος; ἀλλ’ οὐκ αὐτὸς ἕκαστος ⟨οὐκ⟩ ἀποψηφίσασθαι; οὐκοῦν καταράσεσθε τοῖς ἀποψηφισαμένοις, τοῦτο τὸ πιστὸν ἕκαστος διδοὺς ὡς οὐκ αὐτὸς οὗτός ἐστι.", "st": "25.100"}, {"sp": "N", "t": "καὶ τί δεῖ ταῦτα ποιεῖν, ἐξὸν εὐφημεῖν καὶ ἅπαντας ἅπασι πάντα τἀγάθ’ εὔχεσθαι, καὶ ὑμᾶς ὑμῖν αὐτοῖς καὶ τοὺς ἄλλους Ἀθηναίους ἅπαντας ὑμῖν, προσθήσω δὲ καὶ τοὺς ξένους καὶ παῖδας καὶ γυναῖκας; ἐφῖκται γάρ, ἐφῖκται πάντων ἡ τούτου κακοπραγμοσύνη, καὶ πᾶσι βουλομένοις ἐστὶν ἀπαλλαγῆναι τῆς τούτου πονηρίας καὶ δίκην δεδωκότ’ ἰδεῖν.", "st": "25.101"}, {"sp": "HDR", "t": "Κατὰ Ἀριστογείτονος Βʹ", "st": "26"}, {"sp": "N", "t": "ὅτι μὲν τοίνυν καὶ ὀφείλει τῷ δημοσίῳ Ἀριστογείτων οὑτοσὶ καὶ οὐκ ἔστιν ἐπίτιμος, καὶ οἱ νόμοι διαρρήδην ἀπαγορεύουσιν μὴ ἐξεῖναι λέγειν τοῖς τοιούτοις, φανερῶς ἐπιδέδεικται, ὦ ἄνδρες Ἀθηναῖοι. δεῖ δ’ ὑμᾶς ἅπαντας μὲν ἀπείργειν καὶ κωλύειν τοὺς παρανομοῦντας, πολὺ δὲ μάλιστα τοὺς ἐν ταῖς ἀρχαῖς ὄντας καὶ τοὺς πολιτευομένους·", "st": "26.1"}, {"sp": "N", "t": "διὰ γὰρ τούτους τὰ κοινὰ καὶ βλάπτεσθαι πέφυκεν, ἐὰν ὦσι φαῦλοι, καὶ τὰ μέγιστα πάλιν ὠφελεῖσθαι, ἐὰν ὦσιν ἐπιεικεῖς καὶ θέλωσιν ἐμμένειν τοῖς νόμοις. ὡς ἐὰν ἅπαξ δῶτε τοῖς ὑπὲρ τῶν κοινῶν ἐγχειροῦσί τι πράττειν τὸ παρανομεῖν καὶ καταφρονεῖν τῶν ὡρισμένων δικαίων, ἀναγκαῖόν ἐστιν ἅπαντας ἀπολαύειν τοὺς μετέχοντας τῆς πόλεως.", "st": "26.2"}, {"sp": "N", "t": "ὥσπερ γὰρ τῶν ἐν ταῖς ναυσὶν ἁμαρτημάτων ἃ συμβαίνει περὶ τοὺς πλοῦς, ὅταν μὲν τῶν ναυτῶν τις ἁμάρτῃ, βραχεῖαν τὴν βλάβην ἤνεγκεν, ὅταν δ’ ὁ κυβερνήτης ἀποσφαλῇ, κοινὴν τὴν ἀτυχίαν ἅπασι τοῖς ἐμπλέουσι παρεσκεύασεν, ὡσαύτως τὰ μὲν τῶν ἰδιωτῶν ἁμαρτήματα οὐκ εἰς τὸ πλῆθος, εἰς δ’ αὐτοὺς ἤνεγκε τὰς βλάβας, τὰ δὲ τῶν ἀρχόντων καὶ πολιτευομένων εἰς ἅπαντας ἀφικνεῖται.", "st": "26.3"}, {"sp": "N", "t": "διὸ καὶ τὰς τιμωρίας ὁ Σόλων τοῖς μὲν ἰδιώταις ἐποίησε βραδείας, ταῖς δ’ ἀρχαῖς καὶ τοῖς δημαγωγοῖς ταχείας, ὑπολαμβάνων τοῖς μὲν ἐνδέχεσθαι καὶ παρὰ τὸν χρόνον τὸ δίκαιον λαβεῖν, τοῖς δ’ οὐκ ἐνεῖναι περιμεῖναι· τὸ γὰρ τιμωρησόμενον οὐχ ὑπέσται τῆς πολιτείας καταλυθείσης. καὶ τούτοις τοῖς δικαίοις οὐδεὶς οὕτως οὔτ’ ἀναιδὴς οὔθ’ ὑπὲρ ὑμᾶς φρονῶν ἐστὶν ὅστις ἀντιλέγειν ἐπιχειρήσει, πλὴν Ἀριστογείτονος τουτουὶ καὶ τῆς τούτου πονηρίας. ἀλλὰ πάσας καὶ τὰς ἀρχὰς καὶ τοὺς πολιτευομένους εὑρήσομεν, ἐπειδὰν ἅπαξ τι καταγνῶθ’ ὑμεῖς, τούτοις ἐμμένοντας.", "st": "26.4"}, {"sp": "N", "t": "τοῦτο μὲν γὰρ ὅταν ἀποχειροτονηθῶσι τινες τῶν ἐν ταῖς ἀρχαῖς, παραχρῆμα πέπαυνται ἄρχοντες καὶ τοὺς στεφάνους περιῄρηνται· τοῦτο δ’ ὅσοις τῶν θεσμοθετῶν εἰς Ἄρειον πάγον οὐχ οἷόν τ’ ἐστὶν ἀνελθεῖν, παρέντες τὸ βιάζεσθαι στέργουσιν ταῖς ὑμετέραις γνώσεσι. καὶ τοῦτ’ εἰκότως· ὥσπερ γάρ, ὅταν ἄρχωσι, τοὺς ἰδιώτας οἴονται δεῖν αὑτοῖς πειθαρχεῖν, ὡσαύτως, ὅταν αὐτοὶ ἰδιῶται γένωνται πάλιν, τοῖς τῆς πόλεως ἄρχουσι νόμοις δικαίως ἂν ἀκολουθοῖεν.", "st": "26.5"}, {"sp": "N", "t": "ἔτι τοίνυν οἱ πολιτευόμενοι πάντες, ἐκ τῶν παλαιῶν εἰ βούλεσθ’ ἀρξάμενοι χρόνων θεωρεῖν, ὡσαύτως φαίνονται εἴκοντες τοῖς ὑμετέροις δικαίοις. Ἀριστείδην μέν γέ φασιν ὑπὸ τῶν προγόνων μετασταθέντ’ ἐν Αἰγίνῃ διατρίβειν, ἕως ὁ δῆμος αὐτὸν κατεδέξατο, Μιλτιάδην δὲ καὶ Περικλέα ὀφλόντας, τὸν μὲν τριάκοντα, τὸν δὲ πεντήκοντα τάλαντα, ἐκτείσαντας οὕτω δημηγορεῖν.", "st": "26.6"}, {"sp": "N", "t": "ὃ καὶ δεινότατον ἂν εἴη συμβαῖνον, τοὺς μὲν πολλὰ καὶ μεγάλα ποιήσαντας ὑμᾶς ἀγαθὰ μὴ τυχεῖν ταύτης τῆς δωρειᾶς, ὥστε παρὰ τοὺς νόμους τι τοὺς κειμένους ὑμῖν πρᾶξαι, τὸν δὲ μηδὲν μὲν ἀγαθὸν εἰργασμένον, ὑπερπληθῆ δ’ ἐξημαρτηκότα, τοῦτον οὕτω προχείρως φαίνεσθαι καὶ παρὰ τὸ συμφέρον καὶ τὸ δίκαιον ἐξουσίαν παρ’ ὑμῶν τοῦ παρανομεῖν εἰληφότα. καὶ τί δεῖ λέγειν περὶ τῶν παλαιῶν; ἀλλὰ τοὺς ἐφ’ ὑμῶν αὐτῶν ἀναλογίσασθε, εἴ τις οὕτως ἀναιδὴς γέγονεν πώποτε· οὐδένα γὰρ ἂν εὕροιτε, εἰ βουλήσεσθ’ ἀκριβῶς ἐξετάζειν.", "st": "26.7"}, {"sp": "N", "t": "χωρὶς τοίνυν τούτων, ὅταν τις ψηφίσματος ἢ νόμου γραφὴν ἀπενέγκῃ πρὸς τοὺς θεσμοθέτας, ὁ μὲν νόμος ἢ τὸ ψήφισμ’ ἄκυρόν ἐστιν, ὁ δὲ θεὶς ἢ γράψας οὐδὲν ἀναισχυντεῖ βιαζόμενος, ἀλλ’ ὅ τι ἂν ὑμεῖς ψηφίσησθε, τούτῳ ἐμμένει, κἂν ᾖ πρῶτος τῷ δύνασθαι λέγειν ἢ πράττειν ἐν ὑμῖν. καίτοι πῶς οὐκ ἄτοπον, ἃ μὲν ἅπαντες ὑμεῖς συλλεγέντες ἐψηφίσασθε, διὰ τοὺς νόμους ἄκυρ’ εἶναι, τὴν δ’ Ἀριστογείτονος βούλησιν εἰς τὸ παρανομεῖν κυριωτέραν οἴεσθαι δεῖν τῶν νόμων αὐτῶν καταστῆσαι;", "st": "26.8"}, {"sp": "N", "t": "πάλιν τοίνυν ὅταν τις ἐπεξιὼν μὴ μεταλάβῃ τὸ πέμπτον μέρος τῶν ψήφων, ἐφ’ οἷς οἱ νόμοι κελεύουσι τὸ λοιπὸν μὴ γράφεσθαι μηδ’ ἀπάγειν μηδ’ ἐφηγεῖσθαι, τὸν αὐτὸν τρόπον παρὰ ταῦτ’ οὐδεὶς οἴεται δεῖν πράττειν τῶν ἐνόχων ὄντων τούτοις τοῖς ἐπιτιμίοις. Ἀριστογείτονι δέ, ὡς ἔοικε, μόνῳ τῶν ἁπάντων οὐδὲν οὔτε δικαστήριον οὔτε νόμος κυριώτερόν ἐστι τῆς αὑτοῦ βουλήσεως.", "st": "26.9"}, {"sp": "N", "t": "καὶ ταῦτα πάνθ’ οὕτω διαφυλάττουσιν οὐδεπώποτ’ οὔθ’ ὑμῖν οὔτε τοῖς προγόνοις μετεμέλησεν. ἔστι γὰρ δημοκρατίας φυλακὴ τῶν μὲν ἐχθρῶν ἢ βουλευομένους ἢ μαχομένους περιεῖναι, τῶν δὲ νόμων ἢ προαιρουμένους ἢ συναναγκαζομένους ἡττᾶσθαι. καὶ ταῦθ’ ὅτι τοῦτον τὸν τρόπον προσήκει πράττεσθαι, καὶ παρ’ αὐτοῦ τούτου συνωμολόγηται.", "st": "26.10"}, {"sp": "N", "t": "ὅτε γὰρ Ὑπερείδης ἔγραψε, τῶν περὶ Χαιρώνειαν ἀτυχημάτων τοῖς Ἕλλησι γενομένων, καὶ τῆς πόλεως ὑπὲρ αὐτῶν τῶν ἐδαφῶν εἰς κίνδυνον μέγιστον κατακεκλειμένης, εἶναι τοὺς ἀτίμους ἐπιτίμους, ἵν’ ὁμονοοῦντες ἅπαντες ὑπὲρ τῆς ἐλευθερίας προθύμως ἀγωνίζωνται, ἐάν τις κίνδυνος τηλικοῦτος καταλαμβάνῃ τὴν πόλιν, τούτου τοῦ ψηφίσματος γραφὴν παρανόμων ἀπενέγκας ἠγωνίζετ’ ἐν τῷ δικαστηρίῳ.", "st": "26.11"}, {"sp": "N", "t": "καίτοι πῶς οὐ δεινὸν εἰς μὲν τὴν [ὑπὲρ] τῆς πατρίδος σωτηρίαν μηδενὶ τῶν πολιτῶν Ἀριστογείτονα τουτονὶ συγχωρῆσαι τυχεῖν τῆς ἐπιτιμίας, εἰς δὲ τὴν αὑτοῦ παρανομίαν παρὰ πάντων ὑμῶν ἀξιοῦν λαμβάνειν τὴν αὐτὴν δωρειάν; καίτοι πολύ γε νομιμώτερον καὶ δικαιότερον τὸ ψήφισμ’ ἐκεῖν’ ἦν οὗ σὺ νῦν ἀξιοῖς ψηφίσασθαί σοι τουτουσί.", "st": "26.12"}, {"sp": "N", "t": "τὸ μὲν γὰρ ἴσον καὶ κοινὸν ἅπασι τοῖς πολίταις ἦν, τὸ δ’ ἄνισον καὶ σοὶ μόνῳ τῶν ἐν τῇ πόλει τὴν πλεονεξίαν κατασκευάζον· καὶ τὸ μὲν ὑπὲρ τοῦ μὴ γενέσθαι τὴν εἰρήνην ἐφ’ ᾧ θ’ ἕνα κύριον τῆς ὅλης πολιτείας καταστῆναι, τὸ δ’ ὑπὲρ τοῦ τὰ τουτωνὶ δόγματα καὶ νόμιμα ἐκ παλαιοῦ παραδοθένθ’ ὑπὸ τῶν προγόνων σοὶ μόνῳ δεδόσθαι ἐξουσίαν ἀδεῶς παραβαίνοντι καὶ πράττοντι ὅ τι ἂν βουληθῇς.", "st": "26.13"}, {"sp": "N", "t": "ἡδέως δ’ ἂν ἔγωγ’ αὐτὸν ἐρωτήσαιμι πότερ’ ἔννομον καὶ δικαίαν ἐποιήσατο τοῦ ψηφίσματος τὴν γραφὴν ἢ τοὐναντίον ἄδικον καὶ παράνομον. εἰ μὲν γὰρ ἀσύμφερον καὶ τῷ δήμῳ βλαβεράν, δι’ αὐτὸ τοῦτο δικαίως ἂν ἀποθάνοι· εἰ δὲ συμφέρουσαν καὶ τοῖς πολλοῖς ὠφέλιμον, διὰ τί νῦν τἀναντί’ οἷς αὐτὸς ἔγραψας ψηφίζεσθαι τούτους ἀξιοῖς; ἀλλ’ οὔτ’ ἐκεῖνα δίκαια οὔτε ταῦτ’ ἔννομ’ οὐδὲ συμφέροντ’ ἐστὶν ὑμῖν.", "st": "26.14"}, {"sp": "N", "t": "ὁρῶ δ’ ὑμᾶς ἔγωγ’, ὦ ἄνδρες Ἀθηναῖοι, ταύτην ἔχοντας τὴν γνώμην καὶ περὶ ὑμῶν αὐτῶν· πολλὰς γὰρ ἐνδείξεις ἤδη κατεψηφίσασθ’ ἰδιωτῶν ἀνθρώπων. καίτοι πῶς οὐ δεινὸν ἐφ’ ὑμῶν μὲν αὐτῶν ἐξετάζεσθαι ἀκριβῶς τοὺς νόμους, ἐπὶ δὲ τῶν περιεργαζομένων τι καὶ κοινῇ πάντας ἐνοχλούντων καὶ προσποιουμένων ὑπὲρ τοὺς ἄλλους εἶναι ῥᾳθύμως οὕτως ἔχειν;", "st": "26.15"}, {"sp": "N", "t": "οὐ γὰρ δή τινες ὑμῶν οὕτως ἔχουσιν, ὡς προσῆκον μὲν ταῦθ’ οὕτως ἔχειν ὡς ἐγὼ λέγω, διὰ δὲ τὴν ἐπιείκειαν τὴν Ἀριστογείτονος καὶ τὸ χρήσιμον αὐτὸν ὑμῖν εἶναι παροπτέον τι καὶ παρανομοῦντ’ αὐτόν. ὅτι μὲν γὰρ πονηρὸς καὶ τὸν τρόπον δεινῶς ἄδικος, ἱκανῶς ὑμῖν, ὡς ἔγωγ’ οἶμαι, ἐκ τῶν προειρημένων Λυκοῦργος ἐπιδέδειχεν· ὅτι δ’ οὐδὲ χρήσιμος, ἐξ αὐτῶν τῶν πολιτευμάτων ἄν τις αὐτοῦ θεωρήσειεν.", "st": "26.16"}, {"sp": "N", "t": "τίνα γὰρ παραγαγὼν εἰς τὸ δικαστήριον, ὧν ᾐτιᾶτο, τούτων καὶ ᾕρηκεν [καὶ εἷλεν]; ἢ ποῖον πόρον ὑμῖν πεπόρικεν; ἢ τί ψήφισμα γέγραφεν ᾧ πεισθέντες ὑμεῖς οὐ πάλιν μετανοῆσαι προείλεσθε; καὶ γὰρ ταῦτα· οὕτω σκαιός ἐστι καὶ βάρβαρος τὸν τρόπον ὥστε, ὅταν ὑμᾶς ἴδῃ πρός τινας ὀργισθέντας τι καὶ μᾶλλον τοῦ δέοντος παροξυνθέντας, τηνικαῦτα παρὰ τὴν ὀργὴν ὑμῶν τὰ βουλήματα λαβὼν τοῖς καιροῖς ἐναντιοῦται.", "st": "26.17"}, {"sp": "N", "t": "δεῖ δὲ τὸν πολιτευόμενον ὑπὲρ ὑμῶν οὐχὶ τοῖς ἐξαίφνης μετ’ ὀργῆς πάθεσιν ὑμῖν συμπίπτουσιν ἐπακολουθεῖν, ἀλλὰ τοῖς λογισμοῖς καὶ τοῖς πράγμασι καὶ τοῖς ὑπάρχουσι καιροῖς· τὰ μὲν γὰρ ταχὺ μεταπίπτειν εἴθισται, τὰ δὲ διαμένειν καὶ πλείω χρόνον ὑπάρχειν· ὧν οὗτος οὐδὲν ἐνθυμούμενος ἐλέγχει τἀπόρρητα τῆς πολιτείας, ὥστε ταὔτ’ ἀναγκάζεσθαι καὶ κύρια καὶ πάλιν ἄκυρα ποιεῖν.", "st": "26.18"}, {"sp": "N", "t": "ἀλλ’ ἴσως ὅτι πρὸς ἅπαντας ἀεὶ προαιρεῖται λοιδορεῖσθαι καὶ διαβοᾶσθαι καὶ μέμφεσθαι τὰ λεγόμενα, διὰ ταῦτα περιποιῆσαι νῦν αὐτὸν ἁρμόττει. ἀλλὰ ταῦτά γε νὴ τὴν Ἀθηνᾶν ὄνειδός ἐστιν, ἄνδρες δικασταί, τῇ πόλει γιγνόμεν’ ἐπὶ τοῦ βήματος, καὶ διὰ τὰς τούτων ἀπονοίας ἐπονείδιστον ἤδη τὸ πολιτεύεσθαι παρὰ τοῖς ἐπιεικέσιν ὑμῶν ἐστιν. εἰ δ’ οὖν τινι τοῦθ’ ὑμῶν ἐν ἡδονῇ συμβέβηκεν, οὐκ ἀπορήσετε τῶν τοιαῦτα ποιησόντων, ἐπεὶ καὶ νῦν μεστὸν τὸ βῆμ’ ἐστίν. οὐ γὰρ ἐπιτιμᾶν τοῖς συμβεβουλευμένοις χαλεπόν, ἀλλὰ συμβουλεῦσαι καὶ πεῖσαί τι τῶν δεόντων ὑμᾶς ψηφίσασθαι.", "st": "26.19"}, {"sp": "N", "t": "πρὸς δὲ τούτοις, εἰ μὲν μὴ καὶ πρότερον τοῖς αὐτοῖς τούτοις χρώμενος λόγοις ἐξηπάτησεν ὑμᾶς, ὅτ’ ἠγωνίσατο τὴν προτέραν ἔνδειξιν, ἦν μὲν οὐδ’ οὕτω δίκαιον παρὰ τοὺς ὑπάρχοντας νόμους τι συγχωρεῖν (οὐ δεῖ γὰρ παρανομεῖν δόντας τισὶ τοὺς ἄλλους κατὰ τοὺς νόμους ἀξιοῦν πράττειν), οὐ μὴν ἀλλ’ ἴσως γ’ εὐλογώτερον ἦν τὸ πιστεῦσαι καὶ καταχαρίσασθαι καὶ προέσθαι τι τῶν τοιούτων.", "st": "26.20"}, {"sp": "N", "t": "ἐπειδὴ δὲ τότ’ ἀφέντες ἐπὶ ταῖς ὁμολογουμέναις ἐλπίσιν, μικρὸν ὕστερον τὸν αὐτὸν τοῦτον, ὡς πράττοντα καὶ λέγοντα μὴ τὰ ἄριστα τῷ δήμῳ, πάλιν ἐκολάσατε, τίς ὑπολείπεται σκῆψις ὑμῖν ἁρμόττουσα, ἂν νῦν παρακρουσθῆτε; ὧν μὲν γὰρ ἔργῳ πεῖραν εἰλήφατε, τί δεῖ τοῖς λόγοις πιστεύειν; ὧν δὲ μηδέπω τὴν δοκιμασίαν ἔχετ’ ἀκριβῆ παρ’ ὑμῖν αὐτοῖς, ἐκ τῶν λεγομένων ἴσως ἀναγκαῖόν ἐστι κρίνειν.", "st": "26.21"}, {"sp": "N", "t": "θαυμάζω δ’ ἔγωγε τῶν οὕτως ἐχόντων ὥστε τὰ μὲν ἴδια τοῖς ἐκ τῶν παρεληλυθότων χρόνων οὖσιν ἐπιεικέσι, τούτοις παρακατατίθεσθαι, τὰ δ’ ἐν τῇ πολιτείᾳ κοινὰ τοῖς ὁμολογουμένως ἐξεληλεγμένοις οὖσι φαύλοις ἐπιτρέπειν. καὶ κύνα μὲν ἐπὶ ποίμνην ἀγεννῆ καὶ φαῦλον οὐδ’ ἂν εἷς ἐπιστήσειε φυλάττειν· ἐπὶ δὲ τοὺς τὰ κοινὰ πράττοντας τοὺς τυχόντας ἀνθρώπους φασὶν ἔνιοι φύλακας δεῖν ἐπιπέμπειν, οἳ προσποιούμενοι μηνύειν τοὺς ἁμαρτάνοντας αὐτοὶ τῆς μεγίστης εἰσὶ φυλακῆς δεόμενοι.", "st": "26.22"}, {"sp": "N", "t": "ὧν, ἐὰν ἔχητε νοῦν, ἐνθυμούμενοι τοὺς μὲν φάσκοντας τούτους τῷ λόγῳ φιλεῖν ὑμᾶς χαίρειν ἐάσετε, αὐτοὶ δὲ τοῦτ’ ἐκ παντὸς τρόπου παραφυλάξετε, ὅπως μηδενὶ δῶτ’ ἐξουσίαν ἀκύρους τοὺς νόμους ποιεῖν, ἄλλως τε καὶ τῶν [πολλῶν] ὑπὲρ τοῦ πλήθους καὶ λέγειν καὶ γράφειν δύνασθαι προσποιουμένων. ὡς πάνδεινόν ἐστιν τοὺς μὲν προγόνους ὑπὲρ τοῦ μὴ καταλυθῆναι τοὺς νόμους ἀποθνῄσκειν τολμᾶν, ὑμᾶς δὲ μηδὲ τοὺς ἐξαμαρτάνοντας εἰς αὐτοὺς τιμωρεῖσθαι, καὶ τὸν μὲν γράψαντα τοὺς νόμους Σόλωνα [ἐψηφίσθαι] χαλκοῦν ἐν ἀγορᾷ στῆσαι, αὐτῶν δὲ τῶν νόμων ὀλιγωροῦντας φαίνεσθαι, δι’ οὓς κἀκεῖνον ὑπερβαλλόντως συμβέβηκε τιμᾶσθαι.", "st": "26.23"}, {"sp": "N", "t": "πῶς δ’ οὐκ ἂν εἴη τὸ συμβαῖνον ἄλογον, εἰ νομοθετοῦντες μὲν ὀργίζεσθε τοῖς πονηροῖς, ἐπ’ αὐτοφώρῳ δέ τινας εἰληφότες ἀθῴους ἐάσετε; καὶ τὸν μὲν νομοθέτην ἕν’ ὄντα πᾶσιν ὑπὲρ ὑμῶν ἀπεχθάνεσθαι τοῖς φαύλοις, ὑμᾶς δὲ μηδ’ ὑπὲρ ὑμῶν αὐτῶν κοινῇ συλλεγέντας ἐπιδείξασθαι μισοῦντας τοὺς πονηρούς, ἀλλ’ ὑφ’ ἑνὸς ἀνδρὸς πονηρίας ἡττηθῆναι; καὶ θάνατον μὲν ὡρικέναι τὴν ζημίαν, ἐάν τις οὐκ ὄντα νόμον παράσχηται, τοὺς δὲ τοὺς ὄντας εἰς τὴν τῶν οὐκ ὄντων νόμων τάξιν ἄγοντας, τούτους ἀτιμωρήτους περιορᾶν;", "st": "26.24"}, {"sp": "N", "t": "οὕτω δ’ ἂν ἀκριβέστατα συνθεωρήσαιτε τὸ τοῖς κειμένοις νόμοις πείθεσθαι ἡλίκον ἀγαθόν ἐστιν, καὶ τὸ καταφρονεῖν καὶ τὸ μὴ πειθαρχεῖν αὐτοῖς ἡλίκον κακόν, εἰ τά τ’ ἐκ τῶν νόμων ἀγαθὰ χωρὶς καὶ τὰ διὰ τῆς παρανομίας συμβαίνοντα πρὸ ὀφθαλμῶν ὑμῖν αὐτοῖς ποιησάμενοι θεωρήσαιτε. εὑρήσετε γὰρ τὴν μὲν τὰ τῆς μανίας καὶ ἀκρασίας καὶ πλεονεξίας, τοὺς δὲ τὰ τῆς φρονήσεως καὶ σωφροσύνης καὶ δικαιοσύνης ἔργα διαπραττομένους.", "st": "26.25"}, {"sp": "N", "t": "δῆλον δέ· τῶν γὰρ πόλεων ταύτας ἄριστ’ οἰκουμένας ἴδοιμεν ἂν ἐν αἷς ἄριστοι νομοθέται γεγόνασιν· τὰ μὲν γὰρ ἐν τοῖς σώμασιν ἀρρωστήματα τοῖς τῶν ἰατρῶν εὑρήμασι καταπαύεται, τὰς δ’ ἐν ταῖς ψυχαῖς ἀγριότητας αἱ τῶν νομοθετῶν ἐξορίζουσι διάνοιαι. ὅλως δ’ οὐδὲν οὔτε σεμνὸν οὔτε σπουδαῖον εὑρήσομεν ὃ μὴ νόμου κεκοινώνηκεν,", "st": "26.26"}, {"sp": "N", "t": "ἐπεὶ καὶ τὸν ὅλον κόσμον καὶ τὰ θεῖα καὶ τὰς καλουμένας ὥρας νόμος καὶ τάξις, εἰ χρὴ τοῖς ὁρωμένοις πιστεύειν, διοικεῖν φαίνεται. παρακαλέσαντες οὖν ὑμᾶς αὐτούς, ἄνδρες Ἀθηναῖοι, βοηθήσατε μὲν τοῖς νόμοις, καταψηφίσασθε δὲ τῶν εἰς τὸ θεῖον ἀσεβεῖν προῃρημένων. καὶ ταῦτ’ ἐὰν πράξητε, τὰ δέοντα ποιήσετε καὶ τὰ κράτιστα ψηφιεῖσθε.", "st": "26.27"}], []);})();
